CREATE OR REPLACE FUNCTION "public"."current_empresa_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select public.current_empresa_id__by_tenant(public.current_tenant_id());
$$;


ALTER FUNCTION "public"."current_empresa_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_tenant_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
begin
  if auth.uid() is null then
    return null;
  end if;

  select utc.tenant_id
    into v_tenant_id
  from public.user_tenant_context utc
  where utc.user_id = auth.uid()
    and public.has_active_tenant_access(utc.tenant_id)
  limit 1;

  if v_tenant_id is not null then
    return v_tenant_id;
  end if;

  select ut.tenant_id
    into v_tenant_id
  from a.usuario u
  join a.usuario_tenant ut on ut.usuario_id = u.id
  join public.tenants t on t.id = ut.tenant_id
  where u.auth_user_id = auth.uid()
    and u.ativo is true
    and u.deleted_at is null
    and ut.ativo is true
    and ut.deleted_at is null
    and t.ativo is true
  order by ut.created_at asc, ut.tenant_id
  limit 1;

  return v_tenant_id;
end;
$$;


ALTER FUNCTION "public"."current_tenant_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_month_first"("p_date" "date") RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
  select date_trunc('month', p_date)::date;
$$;


ALTER FUNCTION "f"."_month_first"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_month_last"("p_date" "date") RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
  select (date_trunc('month', p_date) + interval '1 month - 1 day')::date;
$$;


ALTER FUNCTION "f"."_month_last"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_nfe_xpath_num"("p_xml" "xml", "p_path" "text") RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
declare
  v_text text;
begin
  -- pega o primeiro nó do xpath com namespace NF-e
  select (xpath(
    p_path,
    p_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  ))[1]::text
  into v_text;

  if v_text is null or btrim(v_text) = '' then
    return null;
  end if;

  -- normaliza decimal com vírgula (se vier)
  v_text := replace(btrim(v_text), ',', '.');

  return v_text::numeric;
exception when others then
  return null;
end;
$$;


ALTER FUNCTION "f"."_nfe_xpath_num"("p_xml" "xml", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_nfe_xpath_text"("p_xml" "xml", "p_path" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
  select nullif((xpath(
    p_path,
    p_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  ))[1]::text, '');
$$;


ALTER FUNCTION "f"."_nfe_xpath_text"("p_xml" "xml", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_safe_day_in_month"("p_month_first" "date", "p_day" integer) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
  select make_date(extract(year from p_month_first)::int, extract(month from p_month_first)::int,
    least(greatest(p_day, 1), extract(day from f._month_last(p_month_first))::int)
  );
$$;


ALTER FUNCTION "f"."_safe_day_in_month"("p_month_first" "date", "p_day" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_xpath_first_num_anyns"("p_xml" "xml", "p_xpath" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
  select coalesce(nullif(replace((xpath(p_xpath, p_xml))[1]::text, ',', '.'), '')::numeric, 0);
$$;


ALTER FUNCTION "f"."_xpath_first_num_anyns"("p_xml" "xml", "p_xpath" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_xpath_first_text_anyns"("p_xml" "xml", "p_xpath" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
  select nullif(btrim((xpath(p_xpath, p_xml))[1]::text), '');
$$;


ALTER FUNCTION "f"."_xpath_first_text_anyns"("p_xml" "xml", "p_xpath" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_xpath_num_anyns"("p_xml" "xml", "p_xpath" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
declare
  v_text text;
begin
  -- pega o primeiro resultado do xpath
  select (xpath(p_xpath, p_xml))[1]::text
    into v_text;

  v_text := nullif(btrim(v_text), '');

  if v_text is null then
    return 0;
  end if;

  -- normaliza decimal (caso venha com vírgula)
  v_text := replace(v_text, ',', '.');

  begin
    return v_text::numeric;
  exception when others then
    return 0;
  end;
end;
$$;


ALTER FUNCTION "f"."_xpath_num_anyns"("p_xml" "xml", "p_xpath" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."_xpath_sum_num_anyns"("p_xml" "xml", "p_xpath" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
  select coalesce(sum(nullif(replace(x::text, ',', '.'), '')::numeric), 0)
  from unnest(xpath(p_xpath, p_xml)) as t(x);
$$;


ALTER FUNCTION "f"."_xpath_sum_num_anyns"("p_xml" "xml", "p_xpath" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."agendar_pagamento_ap"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_prevista" "date", "p_forma_pagamento" "text", "p_valor_previsto" numeric, "p_observacoes" "text" DEFAULT NULL::"text", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_cb f.conta_bancaria%rowtype;

  v_user uuid;
begin
  if p_data_prevista is null then
    raise exception 'Data prevista obrigatoria';
  end if;

  if p_forma_pagamento is null or length(trim(p_forma_pagamento)) = 0 then
    raise exception 'Forma de pagamento obrigatoria';
  end if;

  if p_forma_pagamento not in ('PIX','BOLETO','TRANSFERENCIA','DINHEIRO','CARTAO','OUTROS') then
    raise exception 'Forma de pagamento invalida: %', p_forma_pagamento;
  end if;

  if p_valor_previsto is null or p_valor_previsto <= 0 then
    raise exception 'Valor previsto deve ser > 0';
  end if;

  -- auth: app ou SQL Editor (postgres/service_role)
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  -- carrega título
  select * into v_titulo
  from f.titulo
  where id = p_titulo_id
    and deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if v_titulo.tipo <> 'AP' then
    raise exception 'Agendamento so permite titulo AP. Tipo atual=%', v_titulo.tipo;
  end if;

  if v_titulo.status not in ('PENDENTE','APROVADO','AGENDADO') then
    raise exception 'Titulo precisa estar PENDENTE/APROVADO/AGENDADO. Status atual=%', v_titulo.status;
  end if;

  if v_titulo.valor_aberto <= 0 then
    raise exception 'Titulo sem saldo em aberto';
  end if;

  -- permissão no app
  if auth.uid() is not null then
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  -- fallback SQL Editor
  if v_user is null then
    select ut.usuario_id into v_user
    from a.usuario_tenant ut
    where ut.tenant_id = v_titulo.tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN')
    order by ut.created_at nulls last
    limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  -- conta bancária
  select * into v_cb
  from f.conta_bancaria
  where id = p_conta_bancaria_id
    and deleted_at is null;

  if not found then
    raise exception 'Conta bancaria nao encontrada (id=%)', p_conta_bancaria_id;
  end if;

  if v_cb.tenant_id <> v_titulo.tenant_id or v_cb.empresa_id <> v_titulo.empresa_id then
    raise exception 'Conta bancaria nao pertence ao mesmo tenant/empresa do titulo';
  end if;

  if round(p_valor_previsto,2) > round(v_titulo.valor_aberto,2) then
    raise exception 'Valor previsto (%) maior que saldo em aberto (%)', round(p_valor_previsto,2), round(v_titulo.valor_aberto,2);
  end if;

  -- upsert 1:1 por título
  insert into f.titulo_agendamento (
    tenant_id,
    titulo_id,
    conta_bancaria_id,
    data_prevista,
    forma_pagamento,
    valor_previsto,
    observacoes,
    change_reason,
    agendado_em,
    agendado_por,
    created_at, updated_at, created_by, updated_by
  )
  values (
    v_titulo.tenant_id,
    v_titulo.id,
    v_cb.id,
    p_data_prevista,
    p_forma_pagamento,
    round(p_valor_previsto,2),
    p_observacoes,
    p_change_reason,
    now(),
    v_user,
    now(), now(), v_user, v_user
  )
  on conflict (tenant_id, titulo_id) do update set
    conta_bancaria_id = excluded.conta_bancaria_id,
    data_prevista = excluded.data_prevista,
    forma_pagamento = excluded.forma_pagamento,
    valor_previsto = excluded.valor_previsto,
    observacoes = excluded.observacoes,
    change_reason = excluded.change_reason,
    agendado_em = now(),
    agendado_por = v_user,
    updated_at = now(),
    updated_by = v_user;

  -- status do título
  update f.titulo
     set status = 'AGENDADO',
         updated_at = now(),
         updated_by = v_user
   where id = v_titulo.id;

  -- evento
  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    'PAGAMENTO_AGENDADO',
    'f.titulo',
    v_titulo.id,
    jsonb_build_object(
      'conta_bancaria_id', v_cb.id,
      'data_prevista', p_data_prevista,
      'forma_pagamento', p_forma_pagamento,
      'valor_previsto', round(p_valor_previsto,2),
      'change_reason', p_change_reason
    ),
    now(), v_user
  );
end;
$$;


ALTER FUNCTION "f"."agendar_pagamento_ap"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_prevista" "date", "p_forma_pagamento" "text", "p_valor_previsto" numeric, "p_observacoes" "text", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."ajustar_valor_parcela_ap"("p_titulo_parcela_id" "uuid", "p_novo_valor" numeric, "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tp f.titulo_parcela%rowtype;
  v_t f.titulo%rowtype;
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_usuario_id uuid;
  v_delta numeric(15,2);
begin
  if p_titulo_parcela_id is null then
    raise exception 'p_titulo_parcela_id obrigat3rio';
  end if;
  if p_novo_valor is null or p_novo_valor <= 0 then
    raise exception 'p_novo_valor deve ser > 0';
  end if;

  -- Auth: app ou SQL Editor
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select * into v_tp
  from f.titulo_parcela tp
  where tp.id = p_titulo_parcela_id
    and tp.deleted_at is null;

  if not found then
    raise exception 'Parcela n3o encontrada';
  end if;

  select * into v_t
  from f.titulo t
  where t.id = v_tp.titulo_id
    and t.deleted_at is null;

  if not found then
    raise exception 'Titulo n3o encontrado';
  end if;

  if v_t.tipo <> 'AP' then
    raise exception 'Somente AP pode ajustar valor';
  end if;

  if v_t.status <> 'PENDENTE' then
    raise exception 'S3 ajusta valor em t1tulo PENDENTE (status=%)', v_t.status;
  end if;

  -- N3o permite ajustar se j1 h1 pagamentos aplicados
  if exists (
    select 1
    from f.pagamento_item pi
    where pi.titulo_parcela_id = v_tp.id
      and pi.deleted_at is null
  ) then
    raise exception 'N3o  poss1vel ajustar: parcela j1 possui pagamentos aplicados';
  end if;

  v_tenant_id := v_t.tenant_id;
  v_empresa_id := v_t.empresa_id;

  if auth.uid() is not null then
    if not f.has_finance_access(v_tenant_id, v_empresa_id) then
      raise exception 'Sem permiss3o financeira';
    end if;
  end if;

  v_usuario_id := a.fn_current_usuario_id();
  v_delta := p_novo_valor - v_tp.valor;

  -- Ajusta parcela
  update f.titulo_parcela
     set valor = p_novo_valor,
         valor_aberto = p_novo_valor,
         updated_at = now(),
         updated_by = v_usuario_id
   where id = v_tp.id;

  -- Ajusta t1tulo
  update f.titulo
     set valor_total = valor_total + v_delta,
         valor_aberto = valor_aberto + v_delta,
         updated_at = now(),
         updated_by = v_usuario_id
   where id = v_t.id;
end;
$$;


ALTER FUNCTION "f"."ajustar_valor_parcela_ap"("p_titulo_parcela_id" "uuid", "p_novo_valor" numeric, "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."aplicar_regra_rateio_titulo"("p_tenant_id" "uuid", "p_titulo_id" "uuid", "p_forcar" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_motivo_id uuid;
  v_os_id integer;
  v_requires_os boolean := false;
  v_regra_id uuid;
  v_total_rateios integer := 0;
  v_explicitos integer := 0;
  v_substituiveis integer := 0;
  v_quantidade_itens integer := 0;
  v_total_percentual numeric := 0;
  v_item record;
  v_indice integer := 0;
  v_acumulado numeric(15,2) := 0;
  v_valor_item numeric(15,2);
begin
  select t.*
    into v_titulo
  from f.titulo t
  where t.id = p_titulo_id
    and t.tenant_id = p_tenant_id
  for update;

  if not found
     or v_titulo.deleted_at is not null
     or v_titulo.status = 'CANCELADO'
     or v_titulo.tipo <> 'AP'
  then
    return jsonb_build_object('status', 'TITULO_INELEGIVEL');
  end if;

  select ta.motivo_compra_id, ta.os_id
    into v_motivo_id, v_os_id
  from f.titulo_aprovacao ta
  where ta.tenant_id = p_tenant_id
    and ta.titulo_id = p_titulo_id
    and ta.deleted_at is null
  order by ta.aprovado_em desc, ta.id desc
  limit 1;

  if v_motivo_id is null then
    v_motivo_id := v_titulo.motivo_compra_id;
  end if;

  if v_motivo_id is null then
    return jsonb_build_object('status', 'MOTIVO_AUSENTE');
  end if;

  select mc.requires_os
    into v_requires_os
  from f.motivo_compra mc
  where mc.id = v_motivo_id
    and mc.tenant_id = p_tenant_id
    and mc.ativo
    and mc.deleted_at is null;

  if not found then
    return jsonb_build_object('status', 'MOTIVO_INVALIDO');
  end if;

  if v_requires_os and v_os_id is null then
    return jsonb_build_object(
      'status', 'OS_OBRIGATORIA_AUSENTE',
      'motivo_compra_id', v_motivo_id
    );
  end if;

  if v_os_id is not null
     and not exists (
       select 1
       from public.ordens_servico os
       where os.id = v_os_id
         and os.tenant_id = p_tenant_id
         and os.empresa_id = v_titulo.empresa_id
     )
  then
    return jsonb_build_object('status', 'OS_INVALIDA');
  end if;

  select rr.id
    into v_regra_id
  from f.regra_rateio rr
  where rr.tenant_id = p_tenant_id
    and rr.empresa_id = v_titulo.empresa_id
    and rr.motivo_compra_id = v_motivo_id
    and rr.ativo
    and rr.deleted_at is null
  limit 1;

  if v_regra_id is null then
    return jsonb_build_object(
      'status', 'SEM_REGRA',
      'motivo_compra_id', v_motivo_id
    );
  end if;

  select count(*)::integer, coalesce(sum(rri.percentual), 0)
    into v_quantidade_itens, v_total_percentual
  from f.regra_rateio_item rri
  where rri.tenant_id = p_tenant_id
    and rri.regra_rateio_id = v_regra_id
    and rri.deleted_at is null;

  if v_quantidade_itens = 0
     or abs(v_total_percentual - 100.0000) > 0.0001
     or exists (
       select 1
       from f.regra_rateio_item rri
       join f.regra_rateio rr
         on rr.id = rri.regra_rateio_id
        and rr.tenant_id = rri.tenant_id
       join f.motivo_compra mc
         on mc.id = rr.motivo_compra_id
        and mc.tenant_id = rr.tenant_id
       left join f.plano_contas pc
         on pc.id = rri.plano_contas_id
        and pc.tenant_id = rri.tenant_id
        and pc.tipo = 'ANALITICA'
        and pc.ativo
        and pc.deleted_at is null
       left join f.centro_custo cc
         on cc.id = rri.centro_custo_id
        and cc.tenant_id = rri.tenant_id
        and cc.empresa_id = rr.empresa_id
        and cc.ativo
        and cc.deleted_at is null
       where rri.tenant_id = p_tenant_id
         and rri.regra_rateio_id = v_regra_id
         and rri.deleted_at is null
         and (
           rri.plano_contas_id is distinct from mc.plano_contas_id
           or pc.id is null
           or cc.id is null
         )
     )
  then
    return jsonb_build_object('status', 'REGRA_INCONSISTENTE');
  end if;

  select
    count(*)::integer,
    count(*) filter (
      where tr.origem_rateio = 'EXPLICITO'
    )::integer,
    count(*) filter (
      where tr.origem_rateio in (
        'AUTOMATICO_REGRA',
        'SISTEMA_FALLBACK'
      )
    )::integer
    into v_total_rateios, v_explicitos, v_substituiveis
  from f.titulo_rateio tr
  where tr.tenant_id = p_tenant_id
    and tr.titulo_id = p_titulo_id
    and tr.deleted_at is null;

  if v_explicitos > 0
     or v_total_rateios <> v_explicitos + v_substituiveis
  then
    return jsonb_build_object(
      'status', 'PRESERVADO_EXPLICITO',
      'rateios', v_total_rateios
    );
  end if;

  if v_total_rateios > 0 and not coalesce(p_forcar, false) then
    return jsonb_build_object(
      'status', 'JA_RATEADO_AUTOMATICAMENTE',
      'rateios', v_total_rateios
    );
  end if;

  if v_substituiveis > 0 then
    update f.titulo_rateio tr
    set
      deleted_at = now(),
      updated_at = now(),
      updated_by = a.fn_current_usuario_id()
    where tr.tenant_id = p_tenant_id
      and tr.titulo_id = p_titulo_id
      and tr.deleted_at is null
      and tr.origem_rateio in (
        'AUTOMATICO_REGRA',
        'SISTEMA_FALLBACK'
      );
  end if;

  for v_item in
    select
      rri.id,
      rri.plano_contas_id,
      rri.centro_custo_id,
      rri.percentual,
      row_number() over (
        order by rri.centro_custo_id, rri.id
      ) as numero
    from f.regra_rateio_item rri
    where rri.tenant_id = p_tenant_id
      and rri.regra_rateio_id = v_regra_id
      and rri.deleted_at is null
    order by rri.centro_custo_id, rri.id
  loop
    v_indice := v_indice + 1;
    if v_indice = v_quantidade_itens then
      v_valor_item := round(
        coalesce(v_titulo.valor_total, 0) - v_acumulado,
        2
      );
    else
      v_valor_item := round(
        coalesce(v_titulo.valor_total, 0)
          * v_item.percentual / 100.0,
        2
      );
      v_acumulado := v_acumulado + v_valor_item;
    end if;

    insert into f.titulo_rateio (
      tenant_id,
      titulo_id,
      plano_contas_id,
      centro_custo_id,
      os_id,
      percentual,
      valor,
      origem_rateio,
      regra_rateio_id,
      regra_item_id
    )
    values (
      p_tenant_id,
      p_titulo_id,
      v_item.plano_contas_id,
      v_item.centro_custo_id,
      v_os_id,
      v_item.percentual,
      v_valor_item,
      'AUTOMATICO_REGRA',
      v_regra_id,
      v_item.id
    );
  end loop;

  return jsonb_build_object(
    'status', 'APLICADO',
    'regra_rateio_id', v_regra_id,
    'motivo_compra_id', v_motivo_id,
    'destinos', v_quantidade_itens
  );
end;
$$;


ALTER FUNCTION "f"."aplicar_regra_rateio_titulo"("p_tenant_id" "uuid", "p_titulo_id" "uuid", "p_forcar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."aplicar_regras_rateio_pendentes"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_limite" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_limite integer := greatest(1, least(coalesce(p_limite, 500), 2000));
  v_total_pendentes integer := 0;
  v_analisados integer := 0;
  v_rateios_criados integer := 0;
  v_centros_preenchidos integer := 0;
  v_ignorados integer := 0;
  v_restantes integer := 0;
  v_titulo record;
  v_rateio record;
  v_item record;
  v_count_rateios integer;
  v_count_itens integer;
  v_resultado jsonb;
  v_erros jsonb := '[]'::jsonb;
begin
  if auth.uid() is not null
     and not f.pode_escrever_regras_rateio(
       p_tenant_id,
       p_empresa_id
     )
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para aplicar regras nesta empresa.';
  end if;

  with candidatos as (
    select t.id
    from f.titulo t
    left join lateral (
      select ta.motivo_compra_id, ta.os_id
      from f.titulo_aprovacao ta
      where ta.tenant_id = t.tenant_id
        and ta.titulo_id = t.id
        and ta.deleted_at is null
      order by ta.aprovado_em desc, ta.id desc
      limit 1
    ) aprovacao on true
    join f.motivo_compra mc
      on mc.id = coalesce(
        aprovacao.motivo_compra_id,
        t.motivo_compra_id
      )
     and mc.tenant_id = t.tenant_id
     and mc.ativo
     and mc.deleted_at is null
    join f.regra_rateio rr
      on rr.tenant_id = t.tenant_id
     and rr.empresa_id = t.empresa_id
     and rr.motivo_compra_id = mc.id
     and rr.ativo
     and rr.deleted_at is null
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.tipo = 'AP'
      and t.status <> 'CANCELADO'
      and t.deleted_at is null
      and (not mc.requires_os or aprovacao.os_id is not null)
      and (
        aprovacao.os_id is null
        or exists (
          select 1
          from public.ordens_servico os
          where os.id = aprovacao.os_id
            and os.tenant_id = t.tenant_id
            and os.empresa_id = t.empresa_id
        )
      )
      and (
        not exists (
          select 1
          from f.titulo_rateio tr
          where tr.tenant_id = t.tenant_id
            and tr.titulo_id = t.id
            and tr.deleted_at is null
        )
        or (
          (
            select count(*)
            from f.titulo_rateio tr
            where tr.tenant_id = t.tenant_id
              and tr.titulo_id = t.id
              and tr.deleted_at is null
          ) = 1
          and exists (
            select 1
            from f.titulo_rateio tr
            join f.regra_rateio_item rri
              on rri.tenant_id = rr.tenant_id
             and rri.regra_rateio_id = rr.id
             and rri.plano_contas_id = tr.plano_contas_id
             and rri.deleted_at is null
            where tr.tenant_id = t.tenant_id
              and tr.titulo_id = t.id
              and tr.deleted_at is null
              and tr.centro_custo_id is null
              and abs(coalesce(tr.percentual, 0) - 100) <= 0.0001
              and (
                select count(*)
                from f.regra_rateio_item rri_count
                where rri_count.tenant_id = rr.tenant_id
                  and rri_count.regra_rateio_id = rr.id
                  and rri_count.deleted_at is null
              ) = 1
          )
        )
      )
  )
  select count(*)::integer
    into v_total_pendentes
  from candidatos;

  for v_titulo in
    select
      t.id,
      rr.id as regra_rateio_id,
      mc.id as motivo_compra_id,
      aprovacao.os_id
    from f.titulo t
    left join lateral (
      select ta.motivo_compra_id, ta.os_id
      from f.titulo_aprovacao ta
      where ta.tenant_id = t.tenant_id
        and ta.titulo_id = t.id
        and ta.deleted_at is null
      order by ta.aprovado_em desc, ta.id desc
      limit 1
    ) aprovacao on true
    join f.motivo_compra mc
      on mc.id = coalesce(
        aprovacao.motivo_compra_id,
        t.motivo_compra_id
      )
     and mc.tenant_id = t.tenant_id
     and mc.ativo
     and mc.deleted_at is null
    join f.regra_rateio rr
      on rr.tenant_id = t.tenant_id
     and rr.empresa_id = t.empresa_id
     and rr.motivo_compra_id = mc.id
     and rr.ativo
     and rr.deleted_at is null
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.tipo = 'AP'
      and t.status <> 'CANCELADO'
      and t.deleted_at is null
      and (not mc.requires_os or aprovacao.os_id is not null)
      and (
        aprovacao.os_id is null
        or exists (
          select 1
          from public.ordens_servico os
          where os.id = aprovacao.os_id
            and os.tenant_id = t.tenant_id
            and os.empresa_id = t.empresa_id
        )
      )
      and (
        not exists (
          select 1
          from f.titulo_rateio tr
          where tr.tenant_id = t.tenant_id
            and tr.titulo_id = t.id
            and tr.deleted_at is null
        )
        or (
          (
            select count(*)
            from f.titulo_rateio tr
            where tr.tenant_id = t.tenant_id
              and tr.titulo_id = t.id
              and tr.deleted_at is null
          ) = 1
          and exists (
            select 1
            from f.titulo_rateio tr
            join f.regra_rateio_item rri
              on rri.tenant_id = rr.tenant_id
             and rri.regra_rateio_id = rr.id
             and rri.plano_contas_id = tr.plano_contas_id
             and rri.deleted_at is null
            where tr.tenant_id = t.tenant_id
              and tr.titulo_id = t.id
              and tr.deleted_at is null
              and tr.centro_custo_id is null
              and abs(coalesce(tr.percentual, 0) - 100) <= 0.0001
              and (
                select count(*)
                from f.regra_rateio_item rri_count
                where rri_count.tenant_id = rr.tenant_id
                  and rri_count.regra_rateio_id = rr.id
                  and rri_count.deleted_at is null
              ) = 1
          )
        )
      )
    order by t.created_at, t.id
    limit v_limite
  loop
    v_analisados := v_analisados + 1;
    begin
      select count(*)::integer
        into v_count_rateios
      from f.titulo_rateio tr
      where tr.tenant_id = p_tenant_id
        and tr.titulo_id = v_titulo.id
        and tr.deleted_at is null;

      if v_count_rateios = 0 then
        v_resultado := f.aplicar_regra_rateio_titulo(
          p_tenant_id,
          v_titulo.id,
          false
        );
        if v_resultado ->> 'status' = 'APLICADO' then
          v_rateios_criados := v_rateios_criados + 1;
        else
          v_ignorados := v_ignorados + 1;
        end if;
      elsif v_count_rateios = 1 then
        select
          tr.id,
          tr.plano_contas_id,
          tr.centro_custo_id,
          tr.percentual
          into v_rateio
        from f.titulo_rateio tr
        where tr.tenant_id = p_tenant_id
          and tr.titulo_id = v_titulo.id
          and tr.deleted_at is null
        for update;

        select count(*)::integer
          into v_count_itens
        from f.regra_rateio_item rri
        where rri.tenant_id = p_tenant_id
          and rri.regra_rateio_id = v_titulo.regra_rateio_id
          and rri.deleted_at is null;

        if v_count_itens = 1 then
          select
            rri.plano_contas_id,
            rri.centro_custo_id
            into v_item
          from f.regra_rateio_item rri
          where rri.tenant_id = p_tenant_id
            and rri.regra_rateio_id = v_titulo.regra_rateio_id
            and rri.deleted_at is null
          limit 1;
        end if;

        if v_count_itens = 1
           and v_rateio.centro_custo_id is null
           and abs(coalesce(v_rateio.percentual, 0) - 100) <= 0.0001
           and v_rateio.plano_contas_id = v_item.plano_contas_id
        then
          update f.titulo_rateio tr
          set
            centro_custo_id = v_item.centro_custo_id,
            updated_at = now(),
            updated_by = a.fn_current_usuario_id()
          where tr.id = v_rateio.id
            and tr.tenant_id = p_tenant_id
            and tr.titulo_id = v_titulo.id
            and tr.deleted_at is null
            and tr.centro_custo_id is null;

          if found then
            v_centros_preenchidos :=
              v_centros_preenchidos + 1;
          else
            v_ignorados := v_ignorados + 1;
          end if;
        else
          v_ignorados := v_ignorados + 1;
        end if;
      else
        v_ignorados := v_ignorados + 1;
      end if;
    exception
      when others then
        v_ignorados := v_ignorados + 1;
        if jsonb_array_length(v_erros) < 20 then
          v_erros := v_erros || jsonb_build_array(
            jsonb_build_object(
              'titulo_id', v_titulo.id,
              'erro', sqlerrm
            )
          );
        end if;
    end;
  end loop;

  v_restantes := greatest(
    0,
    v_total_pendentes
      - v_rateios_criados
      - v_centros_preenchidos
  );

  return jsonb_build_object(
    'titulos_analisados', v_analisados,
    'rateios_criados', v_rateios_criados,
    'centros_preenchidos', v_centros_preenchidos,
    'ignorados', v_ignorados,
    'limite', v_limite,
    'truncado', v_restantes > 0,
    'pendentes_restantes', v_restantes,
    'erros', v_erros
  );
end;
$$;


ALTER FUNCTION "f"."aplicar_regras_rateio_pendentes"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_limite" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "f"."aplicar_regras_rateio_pendentes"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_limite" integer) IS 'Aplica regras sem sobrescrever rateio existente; no historico, preenche apenas centro nulo em linha unica de 100% e plano identico.';



CREATE OR REPLACE FUNCTION "f"."aprovar_titulo_ap"("p_titulo_id" "uuid", "p_motivo_compra_id" "uuid", "p_os_id" integer DEFAULT NULL::integer, "p_motivo_outros_text" "text" DEFAULT NULL::"text", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_motivo f.motivo_compra%rowtype;

  v_aprovador uuid;
begin
  -- permite SQL Editor (postgres/service_role); no app continua autenticado
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  -- carrega titulo
  select * into v_titulo
  from f.titulo
  where id = p_titulo_id
    and deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if v_titulo.tipo <> 'AP' then
    raise exception 'Aprovacao so permite titulo AP. Tipo atual=%', v_titulo.tipo;
  end if;

  if v_titulo.status <> 'PENDENTE' then
    raise exception 'Titulo precisa estar PENDENTE para aprovar. Status atual=%', v_titulo.status;
  end if;

  -- permissão (somente ADMIN/FINANCEIRO no app)
  if auth.uid() is not null then
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  -- aprovador normal (app)
  v_aprovador := a.fn_current_usuario_id();

  -- ✅ fallback para SQL Editor: pega um OWNER/ADMIN do tenant
  if v_aprovador is null then
    select ut.usuario_id
      into v_aprovador
    from a.usuario_tenant ut
    where ut.tenant_id = v_titulo.tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN')
    order by ut.created_at nulls last
    limit 1;

    if v_aprovador is null then
      raise exception
        'Nao foi possivel determinar aprovador (a.fn_current_usuario_id() retornou null e nao existe OWNER/ADMIN no tenant). Execute pelo app.';
    end if;
  end if;

  -- =====================================================
  -- MOTIVO: busca por ID e realinha tenant se necessário
  -- =====================================================
  select * into v_motivo
  from f.motivo_compra
  where id = p_motivo_compra_id
    and deleted_at is null
    and ativo = true;

  if not found then
    raise exception 'Motivo de compra invalido/inativo (id=%)', p_motivo_compra_id;
  end if;

  if v_motivo.tenant_id <> v_titulo.tenant_id then
    if exists (
      select 1 from f.motivo_compra mc
      where mc.tenant_id = v_titulo.tenant_id
        and mc.codigo = v_motivo.codigo
        and mc.id <> v_motivo.id
        and mc.deleted_at is null
    ) then
      raise exception 'Conflito: ja existe motivo com codigo % no tenant do titulo', v_motivo.codigo;
    end if;

    if exists (
      select 1 from f.motivo_compra mc
      where mc.tenant_id = v_titulo.tenant_id
        and mc.nome = v_motivo.nome
        and mc.id <> v_motivo.id
        and mc.deleted_at is null
    ) then
      raise exception 'Conflito: ja existe motivo com nome % no tenant do titulo', v_motivo.nome;
    end if;

    update f.motivo_compra
       set tenant_id = v_titulo.tenant_id,
           updated_at = now(),
           updated_by = v_aprovador
     where id = v_motivo.id;

    select * into v_motivo
    from f.motivo_compra
    where id = p_motivo_compra_id
      and deleted_at is null
      and ativo = true;
  end if;

  -- validações do motivo
  if v_motivo.requires_os and p_os_id is null then
    raise exception 'Motivo "%" exige OS', v_motivo.nome;
  end if;

  if v_motivo.requires_text then
    if p_motivo_outros_text is null or length(trim(p_motivo_outros_text)) = 0 then
      raise exception 'Motivo "%" exige detalhamento em texto', v_motivo.nome;
    end if;
  end if;

  -- valida OS se informada
  if p_os_id is not null then
    if not exists (
      select 1
      from public.ordens_servico os
      where os.id = p_os_id
        and os.tenant_id = v_titulo.tenant_id
    ) then
      raise exception 'OS invalida (id=%) para este tenant', p_os_id;
    end if;
  end if;

  -- grava aprovação (upsert 1:1)
  insert into f.titulo_aprovacao (
    tenant_id,
    titulo_id,
    motivo_compra_id,
    motivo_outros_text,
    os_id,
    aprovado_em,
    aprovado_por,
    change_reason,
    created_at,
    updated_at,
    created_by,
    updated_by
  )
  values (
    v_titulo.tenant_id,
    v_titulo.id,
    v_motivo.id,
    p_motivo_outros_text,
    p_os_id,
    now(),
    v_aprovador,
    p_change_reason,
    now(),
    now(),
    v_aprovador,
    v_aprovador
  )
  on conflict (tenant_id, titulo_id) do update set
    motivo_compra_id = excluded.motivo_compra_id,
    motivo_outros_text = excluded.motivo_outros_text,
    os_id = excluded.os_id,
    aprovado_em = excluded.aprovado_em,
    aprovado_por = excluded.aprovado_por,
    change_reason = excluded.change_reason,
    updated_at = now(),
    updated_by = v_aprovador;

  -- status -> APROVADO
  update f.titulo
     set status = 'APROVADO',
         updated_at = now(),
         updated_by = v_aprovador
   where id = v_titulo.id;

  -- eventos
  insert into f.aprovacao_evento (
    tenant_id, empresa_id,
    acao, ref_table, ref_id,
    motivo, payload,
    created_at, created_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    'APROVOU', 'f.titulo', v_titulo.id,
    v_motivo.nome,
    jsonb_build_object(
      'motivo_compra_id', v_motivo.id,
      'motivo_codigo', v_motivo.codigo,
      'motivo_nome', v_motivo.nome,
      'os_id', p_os_id,
      'motivo_outros_text', p_motivo_outros_text,
      'change_reason', p_change_reason
    ),
    now(), v_aprovador
  );

  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    'TITULO_APROVADO',
    'f.titulo',
    v_titulo.id,
    jsonb_build_object(
      'status_anterior', 'PENDENTE',
      'status_novo', 'APROVADO',
      'motivo_compra_id', v_motivo.id,
      'os_id', p_os_id
    ),
    now(), v_aprovador
  );
end;
$$;


ALTER FUNCTION "f"."aprovar_titulo_ap"("p_titulo_id" "uuid", "p_motivo_compra_id" "uuid", "p_os_id" integer, "p_motivo_outros_text" "text", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."arquivar_regra_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_regra_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_id uuid;
begin
  if auth.uid() is not null
     and not f.pode_escrever_regras_rateio(
       p_tenant_id,
       p_empresa_id
     )
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para arquivar regras desta empresa.';
  end if;

  update f.regra_rateio rr
  set
    ativo = false,
    deleted_at = now(),
    updated_at = now(),
    updated_by = a.fn_current_usuario_id()
  where rr.id = p_regra_id
    and rr.tenant_id = p_tenant_id
    and rr.empresa_id = p_empresa_id
    and rr.deleted_at is null
  returning rr.id into v_id;

  if v_id is null then
    raise exception using
      errcode = 'P0002',
      message = 'Regra de rateio nao encontrada nesta empresa.';
  end if;

  return jsonb_build_object('id', v_id, 'arquivada', true);
end;
$$;


ALTER FUNCTION "f"."arquivar_regra_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_regra_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."atualizar_proximos_ap_recorrencia"("p_recorrencia_id" "uuid", "p_referencia_competencia" "date" DEFAULT NULL::"date", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_rec f.ap_recorrencia%rowtype;
  v_ref_comp date;
  v_ref_valor numeric(15,2);
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_usuario_id uuid;

  v_count integer := 0;
begin
  if p_recorrencia_id is null then
    raise exception 'p_recorrencia_id obrigat3rio';
  end if;

  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select * into v_rec
  from f.ap_recorrencia r
  where r.id = p_recorrencia_id
    and r.deleted_at is null;

  if not found then
    raise exception 'Recorr8ncia n3o encontrada';
  end if;

  v_tenant_id := v_rec.tenant_id;
  v_empresa_id := v_rec.empresa_id;

  if auth.uid() is not null then
    if not f.has_finance_access(v_tenant_id, v_empresa_id) then
      raise exception 'Sem permiss3o financeira';
    end if;
  end if;

  v_usuario_id := a.fn_current_usuario_id();

  if p_referencia_competencia is not null then
    v_ref_comp := f._month_first(p_referencia_competencia);
  else
    select t.competencia_date
      into v_ref_comp
    from f.titulo t
    where t.deleted_at is null
      and t.tenant_id = v_tenant_id
      and t.recorrencia_id = v_rec.id
    order by t.competencia_date desc nulls last
    limit 1;
  end if;

  if v_ref_comp is null then
    raise exception 'N3o h1 t1tulo de refer8ncia para esta recorr8ncia';
  end if;

  select t.valor_total
    into v_ref_valor
  from f.titulo t
  where t.deleted_at is null
    and t.tenant_id = v_tenant_id
    and t.recorrencia_id = v_rec.id
    and t.competencia_date = v_ref_comp
  order by t.created_at desc
  limit 1;

  if v_ref_valor is null or v_ref_valor <= 0 then
    raise exception 'Valor de refer8ncia inv1lido';
  end if;

  -- Atualiza apenas futuros ainda provisionados (PENDENTE) e sem pagamentos aplicados
  with futuros as (
    select t.id as titulo_id
    from f.titulo t
    where t.deleted_at is null
      and t.tenant_id = v_tenant_id
      and t.recorrencia_id = v_rec.id
      and t.competencia_date > v_ref_comp
      and t.status = 'PENDENTE'
  ), sem_pagamentos as (
    select f.titulo_id
    from futuros f
    where not exists (
      select 1
      from f.titulo_parcela tp
      join f.pagamento_item pi on pi.titulo_parcela_id = tp.id and pi.deleted_at is null
      where tp.titulo_id = f.titulo_id
        and tp.deleted_at is null
    )
  )
  update f.titulo t
     set valor_total = v_ref_valor,
         valor_aberto = v_ref_valor,
         updated_at = now(),
         updated_by = v_usuario_id
   where t.id in (select titulo_id from sem_pagamentos)
  returning 1 into v_count;

  -- Ajusta parcelas (valor + valor_aberto)
  update f.titulo_parcela tp
     set valor = v_ref_valor,
         valor_aberto = v_ref_valor,
         updated_at = now(),
         updated_by = v_usuario_id
   where tp.deleted_at is null
     and tp.titulo_id in (
       select t.id
       from f.titulo t
       where t.deleted_at is null
         and t.tenant_id = v_tenant_id
         and t.recorrencia_id = v_rec.id
         and t.competencia_date > v_ref_comp
         and t.status = 'PENDENTE'
     );

  return coalesce(v_count, 0);
end;
$$;


