CREATE OR REPLACE FUNCTION "f"."atualizar_titulo_parcela_vencimento_date"("p_parcela_id" "uuid", "p_vencimento_date" "date", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a'
    SET "row_security" TO 'off'
    AS $$
declare
  v_parcela f.titulo_parcela%rowtype;
  v_titulo f.titulo%rowtype;
  v_user uuid;
begin
  if p_parcela_id is null then
    raise exception 'p_parcela_id obrigatorio';
  end if;

  if p_vencimento_date is null then
    raise exception 'p_vencimento_date obrigatorio';
  end if;

  if auth.uid() is null then
    if current_user not in ('postgres', 'service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select *
    into v_parcela
  from f.titulo_parcela
  where id = p_parcela_id
    and deleted_at is null;

  if not found then
    raise exception 'Parcela nao encontrada (id=%)', p_parcela_id;
  end if;

  select *
    into v_titulo
  from f.titulo
  where id = v_parcela.titulo_id
    and deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado para parcela (id=%)', p_parcela_id;
  end if;

  if v_titulo.tipo not in ('AP', 'AR') then
    raise exception 'Somente parcelas AP/AR podem ser alteradas nesta operacao';
  end if;

  if auth.uid() is not null then
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  if coalesce(v_parcela.valor_aberto, 0) <= 0 then
    raise exception 'Parcela liquidada; vencimento nao pode ser alterado';
  end if;

  v_user := a.fn_current_usuario_id();

  update f.titulo_parcela
     set vencimento_date = p_vencimento_date,
         updated_at = now(),
         updated_by = v_user
   where id = p_parcela_id;
end;
$$;


ALTER FUNCTION "f"."atualizar_titulo_parcela_vencimento_date"("p_parcela_id" "uuid", "p_vencimento_date" "date", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."cancelar_agendamento_ap"("p_titulo_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_user uuid;

  v_tem_agendamento boolean;
begin
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select * into v_titulo
  from f.titulo
  where id = p_titulo_id
    and deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if v_titulo.tipo <> 'AP' then
    raise exception 'Cancelamento so permite titulo AP. Tipo atual=%', v_titulo.tipo;
  end if;

  -- permissão no app
  if auth.uid() is not null then
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  -- fallback SQL Editor
  if v_user is null then
    select ut.usuario_id into v_user
    from a.usuario_tenant ut
    where ut.tenant_id = v_titulo.tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN')
    order by ut.created_at nulls last
    limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  select exists(
    select 1
    from f.titulo_agendamento ta
    where ta.tenant_id = v_titulo.tenant_id
      and ta.titulo_id = v_titulo.id
      and ta.deleted_at is null
  ) into v_tem_agendamento;

  if not v_tem_agendamento then
    raise exception 'Nao existe agendamento ativo para este titulo';
  end if;

  -- soft delete do agendamento
  update f.titulo_agendamento
     set deleted_at = now(),
         updated_at = now(),
         updated_by = v_user
   where tenant_id = v_titulo.tenant_id
     and titulo_id = v_titulo.id
     and deleted_at is null;

  -- volta status: se tem saldo aberto, APROVADO; se não, PAGO
  update f.titulo
     set status = case when v_titulo.valor_aberto > 0 then 'APROVADO' else 'PAGO' end,
         updated_at = now(),
         updated_by = v_user
   where id = v_titulo.id;

  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    'PAGAMENTO_AGENDADO_CANCELADO',
    'f.titulo',
    v_titulo.id,
    jsonb_build_object(
      'motivo', p_motivo
    ),
    now(), v_user
  );
end;
$$;


ALTER FUNCTION "f"."cancelar_agendamento_ap"("p_titulo_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."cancelar_titulo_ap"("p_titulo_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_user uuid;
  v_tem_pagamento boolean;
begin
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select *
    into v_titulo
    from f.titulo
   where id = p_titulo_id
     and deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if v_titulo.tipo <> 'AP' then
    raise exception 'Cancelamento so permite titulo AP. Tipo atual=%', v_titulo.tipo;
  end if;

  if upper(coalesce(v_titulo.status, '')) = 'CANCELADO' then
    raise exception 'Titulo ja esta cancelado';
  end if;

  if auth.uid() is not null then
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  if v_user is null then
    select ut.usuario_id
      into v_user
      from a.usuario_tenant ut
     where ut.tenant_id = v_titulo.tenant_id
       and ut.ativo = true
       and ut.deleted_at is null
       and ut.papel in ('OWNER','ADMIN')
     order by ut.created_at nulls last
     limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  select exists (
    select 1
      from f.titulo_parcela tp
      join f.pagamento_item pi
        on pi.titulo_parcela_id = tp.id
       and pi.deleted_at is null
      join f.pagamento p
        on p.id = pi.pagamento_id
       and p.deleted_at is null
     where tp.tenant_id = v_titulo.tenant_id
       and tp.titulo_id = v_titulo.id
       and tp.deleted_at is null
  )
    into v_tem_pagamento;

  if v_tem_pagamento then
    raise exception 'Titulo possui pagamento aplicado. Estorne o pagamento antes de cancelar o lancamento.';
  end if;

  update f.titulo_agendamento
     set deleted_at = now(),
         updated_at = now(),
         updated_by = v_user
   where tenant_id = v_titulo.tenant_id
     and titulo_id = v_titulo.id
     and deleted_at is null;

  update f.titulo_parcela
     set valor_aberto = 0,
         updated_at = now(),
         updated_by = v_user
   where tenant_id = v_titulo.tenant_id
     and titulo_id = v_titulo.id
     and deleted_at is null
     and coalesce(valor_aberto, 0) <> 0;

  update f.titulo
     set valor_aberto = 0,
         status = 'CANCELADO',
         updated_at = now(),
         updated_by = v_user
   where id = v_titulo.id;

  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    'TITULO_AP_CANCELADO',
    'f.titulo',
    v_titulo.id,
    jsonb_build_object(
      'motivo', p_motivo,
      'status_anterior', v_titulo.status,
      'status_novo', 'CANCELADO'
    ),
    now(), v_user
  );

  insert into f.aprovacao_evento (
    tenant_id, empresa_id,
    acao, ref_table, ref_id,
    motivo, payload,
    created_at, created_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    'REPROVOU',
    'f.titulo',
    v_titulo.id,
    'CANCELAMENTO_TITULO',
    jsonb_build_object(
      'motivo', p_motivo,
      'status_anterior', v_titulo.status,
      'status_novo', 'CANCELADO'
    ),
    now(), v_user
  );
end;
$$;


ALTER FUNCTION "f"."cancelar_titulo_ap"("p_titulo_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."conciliar_pagamento_extrato"("p_extrato_linha_id" "uuid", "p_pagamento_id" "uuid", "p_referencia" "text" DEFAULT NULL::"text", "p_observacoes" "text" DEFAULT NULL::"text", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_linha f.extrato_bancario_linha%rowtype;
  v_pag f.pagamento%rowtype;

  v_user uuid;
  v_conc_id uuid;

  v_valor_mov numeric(15,2);
  v_valor_pag numeric(15,2);
  v_dif numeric(15,2);
begin
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select * into v_linha
  from f.extrato_bancario_linha
  where id = p_extrato_linha_id
    and deleted_at is null;

  if not found then
    raise exception 'Extrato linha nao encontrada (id=%)', p_extrato_linha_id;
  end if;

  select * into v_pag
  from f.pagamento
  where id = p_pagamento_id
    and deleted_at is null;

  if not found then
    raise exception 'Pagamento nao encontrado/estornado (id=%)', p_pagamento_id;
  end if;

  if auth.uid() is not null then
    if not f.has_finance_access(v_pag.tenant_id, v_pag.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  if v_user is null then
    select ut.usuario_id into v_user
    from a.usuario_tenant ut
    where ut.tenant_id = v_pag.tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN')
    order by ut.created_at nulls last
    limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  if v_linha.tenant_id <> v_pag.tenant_id then
    raise exception 'Tenant diferente entre extrato e pagamento';
  end if;

  if v_linha.conta_bancaria_id <> v_pag.conta_bancaria_id then
    raise exception 'Conta bancaria diferente entre extrato e pagamento';
  end if;

  -- MVP AP: extrato deve ser débito (negativo)
  if v_linha.valor >= 0 then
    raise exception 'Linha de extrato deve ser debito (valor negativo) para conciliar AP. Valor=%', v_linha.valor;
  end if;

  if v_linha.status <> 'PENDENTE' then
    raise exception 'Linha de extrato nao esta PENDENTE. Status atual=%', v_linha.status;
  end if;

  if v_pag.conciliado_at is not null then
    raise exception 'Pagamento ja conciliado (pagamento_id=%)', v_pag.id;
  end if;

  v_valor_mov := round(abs(v_linha.valor), 2);
  v_valor_pag := round(v_pag.valor, 2);
  v_dif := round(v_valor_mov - v_valor_pag, 2);

  insert into f.conciliacao_bancaria (
    tenant_id, empresa_id,
    conta_bancaria_id,
    extrato_linha_id,
    pagamento_id,
    referencia,
    status,
    valor_conciliado,
    diferenca,
    conciliado_em,
    conciliado_por,
    observacoes,
    change_reason,
    created_at, updated_at, created_by, updated_by
  )
  values (
    v_pag.tenant_id, v_pag.empresa_id,
    v_pag.conta_bancaria_id,
    v_linha.id,
    v_pag.id,
    p_referencia,
    'CONCILIADO',
    v_valor_pag,
    v_dif,
    now(),
    v_user,
    p_observacoes,
    p_change_reason,
    now(), now(), v_user, v_user
  )
  returning id into v_conc_id;

  update f.extrato_bancario_linha
     set status = 'CONCILIADO',
         updated_at = now(),
         updated_by = v_user
   where id = v_linha.id;

  update f.pagamento
     set conciliado_at = now(),
         conciliado_por = v_user,
         updated_at = now(),
         updated_by = v_user
   where id = v_pag.id;

  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_pag.tenant_id, v_pag.empresa_id,
    'PAGAMENTO_CONCILIADO',
    'f.conciliacao_bancaria',
    v_conc_id,
    jsonb_build_object(
      'extrato_linha_id', v_linha.id,
      'pagamento_id', v_pag.id,
      'valor_extrato', v_linha.valor,
      'valor_pagamento', v_pag.valor,
      'diferenca', v_dif,
      'referencia', p_referencia,
      'change_reason', p_change_reason
    ),
    now(), v_user
  );

  return v_conc_id;
end;
$$;


ALTER FUNCTION "f"."conciliar_pagamento_extrato"("p_extrato_linha_id" "uuid", "p_pagamento_id" "uuid", "p_referencia" "text", "p_observacoes" "text", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."conciliar_por_sugestao_ap"("p_extrato_linha_id" "uuid", "p_score_min" integer DEFAULT 2, "p_referencia" "text" DEFAULT 'AUTO MATCH'::"text", "p_observacoes" "text" DEFAULT 'CONCILIADO VIA SUGESTAO'::"text", "p_change_reason" "text" DEFAULT 'AUTO-SUGESTAO'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_status text;
  v_conc_id uuid;

  v_pagamento_id uuid;
  v_score integer;
begin
  -- 1) Se já está conciliado, devolve a conciliação ativa
  select el.status into v_status
  from f.extrato_bancario_linha el
  where el.id = p_extrato_linha_id
    and el.deleted_at is null;

  if v_status is null then
    raise exception 'Extrato linha nao encontrada (id=%)', p_extrato_linha_id;
  end if;

  if v_status = 'CONCILIADO' then
    select cb.id into v_conc_id
    from f.conciliacao_bancaria cb
    where cb.extrato_linha_id = p_extrato_linha_id
      and cb.deleted_at is null
    order by cb.created_at desc
    limit 1;

    if v_conc_id is null then
      raise exception 'Linha CONCILIADO mas sem conciliacao ativa (extrato_linha_id=%)', p_extrato_linha_id;
    end if;

    return v_conc_id;
  end if;

  if v_status = 'IGNORADO' then
    raise exception 'Linha do extrato esta IGNORADA. Desfaça/edite para conciliar (extrato_linha_id=%)', p_extrato_linha_id;
  end if;

  -- 2) PENDENTE: pega melhor sugestão
  select s.pagamento_id, s.score_data
    into v_pagamento_id, v_score
  from f.r_sugestoes_conciliacao_ap s
  where s.extrato_linha_id = p_extrato_linha_id
  order by s.score_data desc, s.data_pagamento desc
  limit 1;

  if v_pagamento_id is null then
    raise exception 'Nenhuma sugestao encontrada para extrato_linha_id=%', p_extrato_linha_id;
  end if;

  if v_score < coalesce(p_score_min, 0) then
    raise exception 'Melhor sugestao com score=% abaixo do minimo=%', v_score, p_score_min;
  end if;

  -- 3) Concilia de fato
  return f.conciliar_pagamento_extrato(
    p_extrato_linha_id,
    v_pagamento_id,
    p_referencia,
    p_observacoes,
    p_change_reason
  );
end;
$$;


ALTER FUNCTION "f"."conciliar_por_sugestao_ap"("p_extrato_linha_id" "uuid", "p_score_min" integer, "p_referencia" "text", "p_observacoes" "text", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."conta_bancaria_ajustar_saldo"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_conta_bancaria_id" "uuid", "p_saldo_atual" numeric, "p_data_referencia" "date", "p_motivo" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_conta f.conta_bancaria%rowtype;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
begin
  if auth.uid() is null then
    raise exception 'Usuario nao autenticado';
  end if;

  if p_tenant_id is null
     or p_tenant_id is distinct from public.current_tenant_id() then
    raise exception 'Tenant invalido para a sessao atual';
  end if;

  if p_empresa_id is null
     or not f.has_finance_access(p_tenant_id, p_empresa_id) then
    raise exception 'Sem acesso financeiro a empresa solicitada';
  end if;

  if p_saldo_atual is null then
    raise exception 'Informe o saldo atual';
  end if;

  if p_data_referencia is null or p_data_referencia > current_date then
    raise exception 'Data da posicao invalida';
  end if;

  if v_motivo is null or length(v_motivo) < 3 then
    raise exception 'Informe um motivo para o ajuste';
  end if;

  select cb.*
    into v_conta
  from f.conta_bancaria cb
  where cb.id = p_conta_bancaria_id
    and cb.tenant_id = p_tenant_id
    and cb.empresa_id = p_empresa_id
    and cb.deleted_at is null
  for update;

  if not found then
    raise exception 'Conta bancaria nao encontrada para a empresa informada';
  end if;

  update f.conta_bancaria cb
  set saldo_referencia = round(p_saldo_atual, 2),
      saldo_referencia_data = p_data_referencia,
      saldo_referencia_em = clock_timestamp(),
      saldo_referencia_motivo = v_motivo,
      updated_at = now()
  where cb.id = v_conta.id
    and cb.tenant_id = p_tenant_id
    and cb.empresa_id = p_empresa_id;

  insert into f.evento_financeiro (
    tenant_id,
    empresa_id,
    evento,
    ref_table,
    ref_id,
    payload
  ) values (
    p_tenant_id,
    p_empresa_id,
    'AJUSTE_SALDO_CONTA',
    'f.conta_bancaria',
    v_conta.id,
    jsonb_build_object(
      'conta_bancaria_id', v_conta.id,
      'conta_codigo', v_conta.codigo,
      'saldo_anterior', v_conta.saldo_referencia,
      'data_anterior', v_conta.saldo_referencia_data,
      'saldo_confirmado', round(p_saldo_atual, 2),
      'data_referencia', p_data_referencia,
      'motivo', v_motivo
    )
  );
end;
$$;


ALTER FUNCTION "f"."conta_bancaria_ajustar_saldo"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_conta_bancaria_id" "uuid", "p_saldo_atual" numeric, "p_data_referencia" "date", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."conta_bancaria_ajustar_saldo"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_conta_bancaria_id" "uuid", "p_saldo_atual" numeric, "p_data_referencia" "date", "p_motivo" "text") IS 'Confirma uma posicao bancaria por conta, empresa e tenant, preservando auditoria.';



CREATE OR REPLACE FUNCTION "f"."contas_bancarias_saldos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date", "p_data_referencia" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("empresa_id" "uuid", "conta_bancaria_id" "uuid", "conta_codigo" "text", "conta_nome" "text", "conta_tipo" "text", "configurada" boolean, "saldo_referencia" numeric, "saldo_referencia_data" "date", "saldo_referencia_motivo" "text", "saldo_inicial_periodo" numeric, "entradas_periodo" numeric, "saidas_periodo" numeric, "transferencias_periodo" numeric, "saldo_atual" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuario nao autenticado';
  end if;

  if p_tenant_id is null
     or p_tenant_id is distinct from public.current_tenant_id() then
    raise exception 'Tenant invalido para a sessao atual';
  end if;

  if coalesce(cardinality(p_empresa_ids), 0) = 0 then
    raise exception 'Informe ao menos uma empresa';
  end if;

  if p_data_inicio is null
     or p_data_fim is null
     or p_data_referencia is null
     or p_data_inicio > p_data_fim then
    raise exception 'Periodo invalido';
  end if;

  if exists (
    select 1
    from unnest(p_empresa_ids) as requested(empresa_id)
    where not exists (
      select 1
      from c.empresa e
      where e.id = requested.empresa_id
        and e.tenant_id = p_tenant_id
        and e.deleted_at is null
    )
       or not f.has_finance_access(p_tenant_id, requested.empresa_id)
  ) then
    raise exception 'Sem acesso financeiro a uma das empresas solicitadas';
  end if;

  return query
  with contas as (
    select cb.*
    from f.conta_bancaria cb
    where cb.tenant_id = p_tenant_id
      and cb.empresa_id = any(p_empresa_ids)
      and cb.deleted_at is null
  ),
  pagamentos_classificados as (
    select
      p.id,
      p.empresa_id,
      p.conta_bancaria_id,
      p.data_pagamento as data_movimento,
      p.created_at,
      p.valor,
      case
        when bool_or(t.tipo = 'AR') and not bool_or(t.tipo = 'AP') then 'ENTRADA'
        when bool_or(t.tipo = 'AP') and not bool_or(t.tipo = 'AR') then 'SAIDA'
        else null
      end as natureza
    from f.pagamento p
    join f.pagamento_item pi
      on pi.pagamento_id = p.id
     and pi.tenant_id = p.tenant_id
     and pi.empresa_id = p.empresa_id
     and pi.deleted_at is null
    join f.titulo_parcela tp
      on tp.id = pi.titulo_parcela_id
     and tp.tenant_id = p.tenant_id
     and tp.deleted_at is null
    join f.titulo t
      on t.id = tp.titulo_id
     and t.tenant_id = p.tenant_id
     and t.empresa_id = p.empresa_id
     and t.deleted_at is null
    where p.tenant_id = p_tenant_id
      and p.empresa_id = any(p_empresa_ids)
      and p.deleted_at is null
    group by
      p.id,
      p.empresa_id,
      p.conta_bancaria_id,
      p.data_pagamento,
      p.created_at,
      p.valor
  ),
  movimentos as (
    select
      pc.empresa_id,
      pc.conta_bancaria_id,
      pc.data_movimento,
      pc.created_at,
      pc.natureza,
      case when pc.natureza = 'ENTRADA' then pc.valor else -pc.valor end as valor_assinado
    from pagamentos_classificados pc
    where pc.natureza is not null

    union all

    select
      cb.empresa_id,
      el.conta_bancaria_id,
      el.data_movimento,
      el.created_at,
      'TRANSFERENCIA'::text as natureza,
      el.valor as valor_assinado
    from f.extrato_bancario_linha el
    join contas cb
      on cb.id = el.conta_bancaria_id
     and cb.tenant_id = el.tenant_id
    where el.tenant_id = p_tenant_id
      and el.deleted_at is null
      and el.status <> 'IGNORADO'
      and upper(coalesce(el.documento, '')) = 'TRANSFERENCIA'
  )
  select
    cb.empresa_id,
    cb.id as conta_bancaria_id,
    cb.codigo as conta_codigo,
    cb.nome as conta_nome,
    cb.tipo as conta_tipo,
    cb.saldo_referencia is not null
      and cb.saldo_referencia_data is not null
      and cb.saldo_referencia_em is not null as configurada,
    cb.saldo_referencia,
    cb.saldo_referencia_data,
    cb.saldo_referencia_motivo,
    case
      when cb.saldo_referencia is null
        or cb.saldo_referencia_data is null
        or cb.saldo_referencia_em is null then null
      when (p_data_inicio - 1) >= cb.saldo_referencia_data then
        cb.saldo_referencia + coalesce(sum(m.valor_assinado) filter (
          where m.data_movimento <= (p_data_inicio - 1)
            and (
              m.data_movimento > cb.saldo_referencia_data
              or m.created_at > cb.saldo_referencia_em
            )
        ), 0)
      else
        cb.saldo_referencia - coalesce(sum(m.valor_assinado) filter (
          where m.data_movimento > (p_data_inicio - 1)
            and m.data_movimento <= cb.saldo_referencia_data
            and m.created_at <= cb.saldo_referencia_em
        ), 0)
    end::numeric as saldo_inicial_periodo,
    coalesce(sum(m.valor_assinado) filter (
      where m.natureza = 'ENTRADA'
        and m.data_movimento between p_data_inicio and p_data_fim
    ), 0)::numeric as entradas_periodo,
    coalesce(-sum(m.valor_assinado) filter (
      where m.natureza = 'SAIDA'
        and m.data_movimento between p_data_inicio and p_data_fim
    ), 0)::numeric as saidas_periodo,
    coalesce(sum(m.valor_assinado) filter (
      where m.natureza = 'TRANSFERENCIA'
        and m.data_movimento between p_data_inicio and p_data_fim
    ), 0)::numeric as transferencias_periodo,
    case
      when cb.saldo_referencia is null
        or cb.saldo_referencia_data is null
        or cb.saldo_referencia_em is null then null
      when p_data_referencia >= cb.saldo_referencia_data then
        cb.saldo_referencia + coalesce(sum(m.valor_assinado) filter (
          where m.data_movimento <= p_data_referencia
            and (
              m.data_movimento > cb.saldo_referencia_data
              or m.created_at > cb.saldo_referencia_em
            )
        ), 0)
      else
        cb.saldo_referencia - coalesce(sum(m.valor_assinado) filter (
          where m.data_movimento > p_data_referencia
            and m.data_movimento <= cb.saldo_referencia_data
            and m.created_at <= cb.saldo_referencia_em
        ), 0)
    end::numeric as saldo_atual
  from contas cb
  left join movimentos m
    on m.empresa_id = cb.empresa_id
   and m.conta_bancaria_id = cb.id
  group by
    cb.empresa_id,
    cb.id,
    cb.codigo,
    cb.nome,
    cb.tipo,
    cb.saldo_referencia,
    cb.saldo_referencia_data,
    cb.saldo_referencia_em,
    cb.saldo_referencia_motivo
  order by cb.empresa_id, cb.nome, cb.codigo;
end;
$$;


ALTER FUNCTION "f"."contas_bancarias_saldos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date", "p_data_referencia" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."contas_bancarias_saldos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date", "p_data_referencia" "date") IS 'Calcula saldo inicial do periodo e saldo atual por conta com pagamentos, recebimentos e transferencias.';



CREATE OR REPLACE FUNCTION "f"."contas_bancarias_saldos_ativos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date", "p_data_referencia" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("empresa_id" "uuid", "conta_bancaria_id" "uuid", "conta_codigo" "text", "conta_nome" "text", "conta_tipo" "text", "configurada" boolean, "saldo_referencia" numeric, "saldo_referencia_data" "date", "saldo_referencia_motivo" "text", "saldo_inicial_periodo" numeric, "entradas_periodo" numeric, "saidas_periodo" numeric, "transferencias_periodo" numeric, "saldo_atual" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
  select
    saldos.empresa_id,
    saldos.conta_bancaria_id,
    saldos.conta_codigo,
    saldos.conta_nome,
    saldos.conta_tipo,
    saldos.configurada,
    saldos.saldo_referencia,
    saldos.saldo_referencia_data,
    saldos.saldo_referencia_motivo,
    saldos.saldo_inicial_periodo,
    saldos.entradas_periodo,
    saldos.saidas_periodo,
    saldos.transferencias_periodo,
    saldos.saldo_atual
  from f.contas_bancarias_saldos(
    p_tenant_id,
    p_empresa_ids,
    p_data_inicio,
    p_data_fim,
    p_data_referencia
  ) as saldos
  join f.conta_bancaria cb
    on cb.id = saldos.conta_bancaria_id
   and cb.tenant_id = p_tenant_id
   and cb.empresa_id = saldos.empresa_id
  where cb.empresa_id = any(p_empresa_ids)
    and cb.ativo = true
    and cb.deleted_at is null
  order by saldos.empresa_id, saldos.conta_nome, saldos.conta_codigo;
$$;


ALTER FUNCTION "f"."contas_bancarias_saldos_ativos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date", "p_data_referencia" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."contas_bancarias_saldos_ativos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date", "p_data_referencia" "date") IS 'Saldos das contas bancarias ativas acessiveis no dashboard, com escopo de tenant e empresas.';



CREATE OR REPLACE FUNCTION "f"."contas_pagar_receber_listar"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") RETURNS TABLE("empresa_id" "uuid", "tipo" "text", "nf_numero" "text", "titulo_id" "uuid", "parcela_id" "uuid", "parcela_numero" "text", "total_parcelas" bigint, "emissao_date" "date", "vencimento_date" "date", "pessoa_nome" "text", "descricao" "text", "motivo_codigo" "text", "motivo_nome" "text", "aprovado_por_nome" "text", "valor" numeric, "valor_aberto" numeric, "titulo_status" "text", "formas_aplicadas" "text"[], "formas_agendadas" "text"[], "pagamento_import_json" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuario nao autenticado';
  end if;

  if p_tenant_id is null
     or p_tenant_id is distinct from public.current_tenant_id() then
    raise exception 'Tenant invalido para a sessao atual';
  end if;

  if coalesce(cardinality(p_empresa_ids), 0) = 0 then
    raise exception 'Informe ao menos uma empresa';
  end if;

  if p_data_inicio is null or p_data_fim is null or p_data_inicio > p_data_fim then
    raise exception 'Periodo invalido';
  end if;

  if exists (
    select 1
    from unnest(p_empresa_ids) as requested(empresa_id)
    where not exists (
      select 1
      from c.empresa e
      where e.id = requested.empresa_id
        and e.tenant_id = p_tenant_id
        and e.deleted_at is null
    )
       or not f.has_finance_access(p_tenant_id, requested.empresa_id)
  ) then
    raise exception 'Sem acesso financeiro a uma das empresas solicitadas';
  end if;

  return query
  with parcelas as (
    select
      t.empresa_id,
      t.tipo,
      df.numero as nf_numero,
      t.id as titulo_id,
      tp.id as parcela_id,
      tp.numero as parcela_numero,
      count(*) over (partition by t.id) as total_parcelas,
      t.emissao_date,
      tp.vencimento_date,
      case
        when t.tipo = 'AP' then coalesce(forn.nome::text, 'Fornecedor')
        else coalesce(cli.nome::text, cli.razao_social::text, 'Cliente')
      end as pessoa_nome,
      t.descricao,
      mc.codigo as motivo_codigo,
      mc.nome as motivo_nome,
      aprovador.nome as aprovado_por_nome,
      tp.valor,
      tp.valor_aberto,
      t.status as titulo_status,
      df.pagamento_import_json
    from f.titulo_parcela tp
    join f.titulo t
      on t.id = tp.titulo_id
     and t.tenant_id = p_tenant_id
     and t.empresa_id = any(p_empresa_ids)
     and t.deleted_at is null
    left join f.documento_fiscal df
      on df.id = t.documento_fiscal_id
     and df.tenant_id = t.tenant_id
     and df.empresa_id = t.empresa_id
     and df.deleted_at is null
    left join public.fornecedores forn
      on forn.id = t.fornecedor_id
     and forn.tenant_id = t.tenant_id
     and forn.empresa_id = t.empresa_id
    left join public.clientes cli
      on cli.id = t.cliente_id
     and cli.tenant_id = t.tenant_id
     and cli.empresa_id = t.empresa_id
    left join lateral (
      select ta.motivo_compra_id, ta.aprovado_por
      from f.titulo_aprovacao ta
      where ta.tenant_id = t.tenant_id
        and ta.titulo_id = t.id
        and ta.deleted_at is null
      order by ta.aprovado_em desc, ta.created_at desc
      limit 1
    ) aprovacao on true
    left join f.motivo_compra mc
      on mc.id = coalesce(aprovacao.motivo_compra_id, t.motivo_compra_id)
     and mc.tenant_id = t.tenant_id
     and mc.deleted_at is null
    left join a.usuario aprovador
      on aprovador.id = aprovacao.aprovado_por
     and aprovador.deleted_at is null
    where tp.tenant_id = p_tenant_id
      and tp.deleted_at is null
      and tp.vencimento_date between p_data_inicio and p_data_fim
      and t.tipo in ('AP', 'AR')
  )
  select
    base.empresa_id,
    base.tipo,
    base.nf_numero,
    base.titulo_id,
    base.parcela_id,
    base.parcela_numero,
    base.total_parcelas,
    base.emissao_date,
    base.vencimento_date,
    base.pessoa_nome,
    base.descricao,
    base.motivo_codigo,
    base.motivo_nome,
    base.aprovado_por_nome,
    base.valor,
    base.valor_aberto,
    base.titulo_status,
    coalesce(aplicadas.formas, '{}'::text[]) as formas_aplicadas,
    coalesce(agendadas.formas, '{}'::text[]) as formas_agendadas,
    base.pagamento_import_json
  from parcelas base
  left join lateral (
    select array_agg(distinct p.forma_pagamento order by p.forma_pagamento) as formas
    from f.pagamento_item pi
    join f.pagamento p
      on p.id = pi.pagamento_id
     and p.tenant_id = p_tenant_id
     and p.empresa_id = base.empresa_id
     and p.deleted_at is null
    where pi.tenant_id = p_tenant_id
      and pi.empresa_id = base.empresa_id
      and pi.titulo_parcela_id = base.parcela_id
      and pi.deleted_at is null
  ) aplicadas on true
  left join lateral (
    select array_agg(distinct ta.forma_pagamento order by ta.forma_pagamento) as formas
    from f.titulo_agendamento ta
    where ta.tenant_id = p_tenant_id
      and ta.titulo_id = base.titulo_id
      and ta.deleted_at is null
  ) agendadas on true
  order by base.vencimento_date, base.tipo, base.pessoa_nome;
end;
$$;


ALTER FUNCTION "f"."contas_pagar_receber_listar"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."contas_pagar_receber_listar"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") IS 'Lista AP/AR de uma ou mais empresas com validacao financeira por tenant e empresa.';



CREATE OR REPLACE FUNCTION "f"."contas_pagar_receber_listar_v2"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") RETURNS TABLE("empresa_id" "uuid", "tipo" "text", "nf_numero" "text", "titulo_id" "uuid", "parcela_id" "uuid", "parcela_numero" "text", "total_parcelas" bigint, "emissao_date" "date", "vencimento_date" "date", "pessoa_nome" "text", "descricao" "text", "motivo_codigo" "text", "motivo_nome" "text", "aprovado_por_nome" "text", "valor" numeric, "valor_aberto" numeric, "titulo_status" "text", "formas_aplicadas" "text"[], "formas_agendadas" "text"[], "contas_aplicadas" "text"[], "contas_agendadas" "text"[], "pagamento_import_json" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuario nao autenticado';
  end if;

  if p_tenant_id is null
     or p_tenant_id is distinct from public.current_tenant_id() then
    raise exception 'Tenant invalido para a sessao atual';
  end if;

  if coalesce(cardinality(p_empresa_ids), 0) = 0 then
    raise exception 'Informe ao menos uma empresa';
  end if;

  if p_data_inicio is null or p_data_fim is null or p_data_inicio > p_data_fim then
    raise exception 'Periodo invalido';
  end if;

  if exists (
    select 1
    from unnest(p_empresa_ids) as requested(empresa_id)
    where not exists (
      select 1
      from c.empresa e
      where e.id = requested.empresa_id
        and e.tenant_id = p_tenant_id
        and e.deleted_at is null
    )
       or not f.has_finance_access(p_tenant_id, requested.empresa_id)
  ) then
    raise exception 'Sem acesso financeiro a uma das empresas solicitadas';
  end if;

  return query
  with parcelas as (
    select
      t.empresa_id,
      t.tipo,
      df.numero as nf_numero,
      t.id as titulo_id,
      tp.id as parcela_id,
      tp.numero as parcela_numero,
      count(*) over (partition by t.id) as total_parcelas,
      t.emissao_date,
      tp.vencimento_date,
      case
        when t.tipo = 'AP' then coalesce(forn.nome::text, 'Fornecedor')
        else coalesce(cli.nome::text, cli.razao_social::text, 'Cliente')
      end as pessoa_nome,
      t.descricao,
      mc.codigo as motivo_codigo,
      mc.nome as motivo_nome,
      aprovador.nome as aprovado_por_nome,
      tp.valor,
      tp.valor_aberto,
      t.status as titulo_status,
      df.pagamento_import_json
    from f.titulo_parcela tp
    join f.titulo t
      on t.id = tp.titulo_id
     and t.tenant_id = p_tenant_id
     and t.empresa_id = any(p_empresa_ids)
     and t.deleted_at is null
    left join f.documento_fiscal df
      on df.id = t.documento_fiscal_id
     and df.tenant_id = t.tenant_id
     and df.empresa_id = t.empresa_id
     and df.deleted_at is null
    left join public.fornecedores forn
      on forn.id = t.fornecedor_id
     and forn.tenant_id = t.tenant_id
     and forn.empresa_id = t.empresa_id
    left join public.clientes cli
      on cli.id = t.cliente_id
     and cli.tenant_id = t.tenant_id
     and cli.empresa_id = t.empresa_id
    left join lateral (
      select ta.motivo_compra_id, ta.aprovado_por
      from f.titulo_aprovacao ta
      where ta.tenant_id = t.tenant_id
        and ta.titulo_id = t.id
        and ta.deleted_at is null
      order by ta.aprovado_em desc, ta.created_at desc
      limit 1
    ) aprovacao on true
    left join f.motivo_compra mc
      on mc.id = coalesce(aprovacao.motivo_compra_id, t.motivo_compra_id)
     and mc.tenant_id = t.tenant_id
     and mc.deleted_at is null
    left join a.usuario aprovador
      on aprovador.id = aprovacao.aprovado_por
     and aprovador.deleted_at is null
    where tp.tenant_id = p_tenant_id
      and tp.deleted_at is null
      and tp.vencimento_date between p_data_inicio and p_data_fim
      and t.tipo in ('AP', 'AR')
  )
  select
    base.empresa_id,
    base.tipo,
    base.nf_numero,
    base.titulo_id,
    base.parcela_id,
    base.parcela_numero,
    base.total_parcelas,
    base.emissao_date,
    base.vencimento_date,
    base.pessoa_nome,
    base.descricao,
    base.motivo_codigo,
    base.motivo_nome,
    base.aprovado_por_nome,
    base.valor,
    base.valor_aberto,
    base.titulo_status,
    coalesce(aplicadas.formas, '{}'::text[]) as formas_aplicadas,
    coalesce(agendadas.formas, '{}'::text[]) as formas_agendadas,
    coalesce(aplicadas.contas, '{}'::text[]) as contas_aplicadas,
    coalesce(agendadas.contas, '{}'::text[]) as contas_agendadas,
    base.pagamento_import_json
  from parcelas base
  left join lateral (
    select
      array_agg(distinct p.forma_pagamento order by p.forma_pagamento) as formas,
      array_agg(
        distinct concat_ws(' - ', nullif(cb.codigo, ''), nullif(cb.nome, ''))
        order by concat_ws(' - ', nullif(cb.codigo, ''), nullif(cb.nome, ''))
      ) as contas
    from f.pagamento_item pi
    join f.pagamento p
      on p.id = pi.pagamento_id
     and p.tenant_id = p_tenant_id
     and p.empresa_id = base.empresa_id
     and p.deleted_at is null
    join f.conta_bancaria cb
      on cb.id = p.conta_bancaria_id
     and cb.tenant_id = p.tenant_id
     and cb.empresa_id = p.empresa_id
     and cb.deleted_at is null
    where pi.tenant_id = p_tenant_id
      and pi.empresa_id = base.empresa_id
      and pi.titulo_parcela_id = base.parcela_id
      and pi.deleted_at is null
  ) aplicadas on true
  left join lateral (
    select
      array_agg(distinct ta.forma_pagamento order by ta.forma_pagamento) as formas,
      array_agg(
        distinct concat_ws(' - ', nullif(cb.codigo, ''), nullif(cb.nome, ''))
        order by concat_ws(' - ', nullif(cb.codigo, ''), nullif(cb.nome, ''))
      ) as contas
    from f.titulo_agendamento ta
    join f.conta_bancaria cb
      on cb.id = ta.conta_bancaria_id
     and cb.tenant_id = p_tenant_id
     and cb.empresa_id = base.empresa_id
     and cb.deleted_at is null
    where ta.tenant_id = p_tenant_id
      and ta.titulo_id = base.titulo_id
      and ta.deleted_at is null
  ) agendadas on true
  order by base.vencimento_date, base.tipo, base.pessoa_nome;
end;
$$;


ALTER FUNCTION "f"."contas_pagar_receber_listar_v2"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."contas_pagar_receber_listar_v2"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") IS 'Lista AP/AR multiempresa incluindo as contas bancarias aplicadas e agendadas.';



CREATE OR REPLACE FUNCTION "f"."contas_pagar_receber_listar_v3"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") RETURNS TABLE("empresa_id" "uuid", "tipo" "text", "nf_numero" "text", "titulo_id" "uuid", "parcela_id" "uuid", "parcela_numero" "text", "total_parcelas" bigint, "emissao_date" "date", "vencimento_date" "date", "pessoa_nome" "text", "descricao" "text", "motivo_codigo" "text", "motivo_nome" "text", "aprovado_por_nome" "text", "valor" numeric, "valor_aberto" numeric, "titulo_status" "text", "formas_aplicadas" "text"[], "formas_agendadas" "text"[], "contas_aplicadas" "text"[], "contas_agendadas" "text"[], "pagamento_import_json" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
  select
    lista.empresa_id,
    lista.tipo,
    lista.nf_numero,
    lista.titulo_id,
    lista.parcela_id,
    lista.parcela_numero,
    coalesce(
      nullif(titulo.total_parcelas_serie, 0)::bigint,
      (
        select count(*)
        from f.titulo_parcela parcela_total
        where parcela_total.tenant_id = p_tenant_id
          and parcela_total.titulo_id = lista.titulo_id
          and parcela_total.deleted_at is null
      )
    ) as total_parcelas,
    lista.emissao_date,
    lista.vencimento_date,
    lista.pessoa_nome,
    lista.descricao,
    lista.motivo_codigo,
    lista.motivo_nome,
    lista.aprovado_por_nome,
    lista.valor,
    lista.valor_aberto,
    lista.titulo_status,
    lista.formas_aplicadas,
    lista.formas_agendadas,
    lista.contas_aplicadas,
    lista.contas_agendadas,
    lista.pagamento_import_json
  from f.contas_pagar_receber_listar_v2(
    p_tenant_id,
    p_empresa_ids,
    p_data_inicio,
    p_data_fim
  ) as lista
  join f.titulo titulo
    on titulo.id = lista.titulo_id
   and titulo.tenant_id = p_tenant_id
   and titulo.empresa_id = lista.empresa_id
   and titulo.deleted_at is null
  where lista.empresa_id = any(p_empresa_ids)
  order by lista.vencimento_date, lista.tipo, lista.pessoa_nome;
$$;


ALTER FUNCTION "f"."contas_pagar_receber_listar_v3"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."contas_pagar_receber_listar_v3"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim" "date") IS 'Lista AP/AR multiempresa com total de parcelas da série completa, mesmo fora do período filtrado.';



CREATE OR REPLACE FUNCTION "f"."contas_pagar_receber_resumo_hoje"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("entradas" numeric, "saidas" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuario nao autenticado';
  end if;

  if p_tenant_id is null
     or p_tenant_id is distinct from public.current_tenant_id() then
    raise exception 'Tenant invalido para a sessao atual';
  end if;

  if coalesce(cardinality(p_empresa_ids), 0) = 0 then
    raise exception 'Informe ao menos uma empresa';
  end if;

  if exists (
    select 1
    from unnest(p_empresa_ids) as requested(empresa_id)
    where not exists (
      select 1
      from c.empresa e
      where e.id = requested.empresa_id
        and e.tenant_id = p_tenant_id
        and e.deleted_at is null
    )
       or not f.has_finance_access(p_tenant_id, requested.empresa_id)
  ) then
    raise exception 'Sem acesso financeiro a uma das empresas solicitadas';
  end if;

  return query
  with pagamentos_classificados as (
    select
      p.id,
      p.valor,
      case
        when bool_or(t.tipo = 'AR') and not bool_or(t.tipo = 'AP') then 'AR'
        when bool_or(t.tipo = 'AP') and not bool_or(t.tipo = 'AR') then 'AP'
        else null
      end as tipo
    from f.pagamento p
    join f.pagamento_item pi
      on pi.pagamento_id = p.id
     and pi.tenant_id = p.tenant_id
     and pi.empresa_id = p.empresa_id
     and pi.deleted_at is null
    join f.titulo_parcela tp
      on tp.id = pi.titulo_parcela_id
     and tp.tenant_id = p.tenant_id
     and tp.deleted_at is null
    join f.titulo t
      on t.id = tp.titulo_id
     and t.tenant_id = p.tenant_id
     and t.empresa_id = p.empresa_id
     and t.deleted_at is null
    where p.tenant_id = p_tenant_id
      and p.empresa_id = any(p_empresa_ids)
      and p.data_pagamento = coalesce(p_data, current_date)
      and p.deleted_at is null
    group by p.id, p.valor
  )
  select
    coalesce(sum(pc.valor) filter (where pc.tipo = 'AR'), 0)::numeric as entradas,
    coalesce(sum(pc.valor) filter (where pc.tipo = 'AP'), 0)::numeric as saidas
  from pagamentos_classificados pc;
end;
$$;


ALTER FUNCTION "f"."contas_pagar_receber_resumo_hoje"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."contas_pagar_receber_resumo_hoje"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data" "date") IS 'Soma entradas AR e saidas AP pela data efetiva da baixa, sem duplicar pagamentos parcelados.';



CREATE OR REPLACE FUNCTION "f"."corrigir_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_ids" "uuid"[], "p_plano_contas_id" "uuid", "p_centro_custo_id" "uuid", "p_justificativa" "text", "p_criar_regra" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo_id uuid;
  v_titulo f.titulo%rowtype;
  v_rateio f.titulo_rateio%rowtype;
  v_actor uuid := a.fn_current_usuario_id();
  v_quantidade integer;
  v_total_percentual numeric;
  v_tem_corrigivel boolean;
  v_pode_criar_regra boolean;
  v_motivo_id uuid;
  v_motivo_codigo text;
  v_plano_motivo_id uuid;
  v_motivo_regra_id uuid;
  v_os_id integer;
  v_regra_resultado jsonb;
  v_regra_id uuid;
  v_snapshot_antes jsonb;
  v_snapshot_depois jsonb;
  v_detectadas_titulo jsonb;
  v_detectadas_antes jsonb := '{}'::jsonb;
  v_snapshots_antes jsonb := '{}'::jsonb;
  v_tipos_antes text[];
  v_tipos_depois text[];
  v_tipo_resolvido text;
  v_fingerprint text;
  v_dados jsonb;
  v_corrigidos integer := 0;
  v_resultados jsonb := '[]'::jsonb;
begin
  if p_tenant_id is null
     or p_empresa_id is null
     or p_plano_contas_id is null
     or p_centro_custo_id is null
  then
    raise exception using
      errcode = '22023',
      message = 'tenant_id, empresa_id, plano e centro sao obrigatorios.';
  end if;

  if p_titulo_ids is null or cardinality(p_titulo_ids) = 0 then
    raise exception using
      errcode = '22023',
      message = 'Informe ao menos um titulo para corrigir.';
  end if;

  if cardinality(p_titulo_ids) > 200 then
    raise exception using
      errcode = '54000',
      message = 'O limite e de 200 titulos por correcao.';
  end if;

  if cardinality(p_titulo_ids) <> (
    select count(distinct ids.id)::integer
    from unnest(p_titulo_ids) as ids(id)
  ) then
    raise exception using
      errcode = '23505',
      message = 'A lista contem titulo repetido ou identificador nulo.';
  end if;

  if length(btrim(coalesce(p_justificativa, ''))) < 10 then
    raise exception using
      errcode = '22023',
      message = 'Informe uma justificativa com pelo menos 10 caracteres.';
  end if;

  if auth.uid() is null
     and coalesce(auth.role(), '') <> 'service_role'
  then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado.';
  end if;

  if auth.uid() is not null
     and not f.pode_escrever_regras_rateio(
       p_tenant_id,
       p_empresa_id
     )
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para corrigir inconsistencias desta empresa.';
  end if;

  if not exists (
    select 1
    from f.plano_contas pc
    where pc.id = p_plano_contas_id
      and pc.tenant_id = p_tenant_id
      and pc.tipo = 'ANALITICA'
      and pc.codigo <> 'DESP_GERAL'
      and pc.ativo
      and pc.deleted_at is null
  ) then
    raise exception using
      errcode = '23503',
      message = 'Escolha um plano analitico ativo e especifico; DESP_GERAL nao e uma correcao.';
  end if;

  if not exists (
    select 1
    from f.centro_custo cc
    where cc.id = p_centro_custo_id
      and cc.tenant_id = p_tenant_id
      and cc.empresa_id = p_empresa_id
      and cc.ativo
      and cc.deleted_at is null
  ) then
    raise exception using
      errcode = '23503',
      message = 'Centro de custo invalido, inativo ou de outra empresa.';
  end if;

  select count(*)::integer
    into v_quantidade
  from f.titulo t
  where t.id = any(p_titulo_ids)
    and t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id
    and t.tipo = 'AP'
    and t.status <> 'CANCELADO'
    and t.deleted_at is null
    and not f.titulo_eh_legado_implantacao(
      t.tenant_id,
      t.empresa_id,
      t.id
    );

  if v_quantidade <> cardinality(p_titulo_ids) then
    raise exception using
      errcode = 'P0002',
      message = 'Um ou mais titulos nao pertencem ao escopo, estao cancelados ou sao legado de implantacao.';
  end if;

  -- Ordem deterministica evita deadlock em correcoes concorrentes.
  perform t.id
  from f.titulo t
  where t.id = any(p_titulo_ids)
    and t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id
  order by t.id
  for update;

  -- Primeira passagem: valida o lote inteiro e captura o antes.
  foreach v_titulo_id in array p_titulo_ids
  loop
    select t.*
      into strict v_titulo
    from f.titulo t
    where t.id = v_titulo_id
      and t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id;

    select
      coalesce(jsonb_object_agg(
        d.tipo,
        jsonb_build_object(
          'fingerprint', d.fingerprint,
          'dados', d.dados
        )
      ), '{}'::jsonb),
      coalesce(bool_or(d.corrigivel), false),
      coalesce(bool_or(d.pode_criar_regra), false)
      into
        v_detectadas_titulo,
        v_tem_corrigivel,
        v_pode_criar_regra
    from f.detectar_inconsistencias_financeiras(
      p_tenant_id,
      p_empresa_id,
      null,
      null
    ) d
    where d.titulo_id = v_titulo_id;

    if v_detectadas_titulo = '{}'::jsonb then
      raise exception using
        errcode = 'P0002',
        message = format(
          'O titulo %s nao possui inconsistencia ativa.',
          v_titulo_id
        );
    end if;

    if not v_tem_corrigivel
       and not (coalesce(p_criar_regra, false) and v_pode_criar_regra)
    then
      raise exception using
        errcode = '23514',
        message = format(
          'O titulo %s exige revisao individual e nao aceita correcao de plano/centro em lote.',
          v_titulo_id
        );
    end if;

    select
      count(*)::integer,
      coalesce(sum(coalesce(tr.percentual, 0)), 0)
      into v_quantidade, v_total_percentual
    from f.titulo_rateio tr
    where tr.tenant_id = p_tenant_id
      and tr.titulo_id = v_titulo_id
      and tr.deleted_at is null;

    if v_quantidade > 1
       or (
         v_quantidade = 1
         and abs(v_total_percentual - 100.0000) > 0.0001
       )
    then
      raise exception using
        errcode = '23514',
        message = format(
          'Titulo %s possui rateio multiplo ou diferente de 100%% e exige revisao individual.',
          v_titulo_id
        );
    end if;

    select
      coalesce(aprovacao.motivo_compra_id, v_titulo.motivo_compra_id),
      mc.codigo,
      mc.plano_contas_id,
      aprovacao.os_id
      into
        v_motivo_id,
        v_motivo_codigo,
        v_plano_motivo_id,
        v_os_id
    from (select 1) base
    left join lateral (
      select ta.motivo_compra_id, ta.os_id
      from f.titulo_aprovacao ta
      where ta.tenant_id = p_tenant_id
        and ta.titulo_id = v_titulo_id
        and ta.deleted_at is null
      order by ta.aprovado_em desc, ta.id desc
      limit 1
    ) aprovacao on true
    left join f.motivo_compra mc
      on mc.id = coalesce(
        aprovacao.motivo_compra_id,
        v_titulo.motivo_compra_id
      )
     and mc.tenant_id = p_tenant_id
     and mc.ativo
     and mc.deleted_at is null;

    if v_plano_motivo_id is not null
       and v_plano_motivo_id is distinct from p_plano_contas_id
       and not (
         v_motivo_codigo = 'DESP_GERAL'
         and not coalesce(p_criar_regra, false)
       )
    then
      raise exception using
        errcode = '23514',
        message = format(
          'O plano escolhido diverge do plano do motivo no titulo %s.',
          v_titulo_id
        );
    end if;

    if coalesce(p_criar_regra, false) then
      if v_motivo_id is null or v_plano_motivo_id is null then
        raise exception using
          errcode = '23514',
          message = format(
            'Titulo %s nao possui motivo com plano valido para criar regra.',
            v_titulo_id
          );
      end if;

      if v_motivo_regra_id is null then
        v_motivo_regra_id := v_motivo_id;
      elsif v_motivo_regra_id is distinct from v_motivo_id then
        raise exception using
          errcode = '23514',
          message = 'Para criar regra, todos os titulos devem possuir o mesmo motivo de compra.';
      end if;
    end if;

    v_snapshot_antes := f.snapshot_inconsistencia_financeira_titulo(
      p_tenant_id,
      p_empresa_id,
      v_titulo_id
    );
    v_detectadas_antes := v_detectadas_antes || jsonb_build_object(
      v_titulo_id::text,
      v_detectadas_titulo
    );
    v_snapshots_antes := v_snapshots_antes || jsonb_build_object(
      v_titulo_id::text,
      v_snapshot_antes
    );
  end loop;

  if coalesce(p_criar_regra, false) then
    if exists (
      select 1
      from f.regra_rateio rr
      where rr.tenant_id = p_tenant_id
        and rr.empresa_id = p_empresa_id
        and rr.motivo_compra_id = v_motivo_regra_id
        and rr.ativo
        and rr.deleted_at is null
    ) then
      raise exception using
        errcode = '23505',
        message = 'Ja existe regra ativa para o motivo selecionado.';
    end if;

    v_regra_resultado := f.salvar_regra_rateio(
      p_tenant_id,
      p_empresa_id,
      null,
      v_motivo_regra_id,
      true,
      jsonb_build_array(jsonb_build_object(
        'plano_contas_id', p_plano_contas_id,
        'centro_custo_id', p_centro_custo_id,
        'percentual', 100.0000
      ))
    );
    v_regra_id := (v_regra_resultado ->> 'id')::uuid;

    insert into f.evento_financeiro (
      tenant_id,
      empresa_id,
      evento,
      ref_table,
      ref_id,
      payload,
      created_by
    )
    values (
      p_tenant_id,
      p_empresa_id,
      'INCONSISTENCIA_FINANCEIRA_REGRA_CRIADA',
      'f.regra_rateio',
      v_regra_id,
      jsonb_build_object(
        'motivoCompraId', v_motivo_regra_id,
        'planoContasId', p_plano_contas_id,
        'centroCustoId', p_centro_custo_id,
        'percentual', 100.0000,
        'titulosOrigem', to_jsonb(p_titulo_ids),
        'justificativa', btrim(p_justificativa)
      ),
      v_actor
    );
  end if;

  -- Segunda passagem: altera somente a classificacao permitida.
  foreach v_titulo_id in array p_titulo_ids
  loop
    select t.*
      into strict v_titulo
    from f.titulo t
    where t.id = v_titulo_id
      and t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id;

    select ta.os_id
      into v_os_id
    from f.titulo_aprovacao ta
    where ta.tenant_id = p_tenant_id
      and ta.titulo_id = v_titulo_id
      and ta.deleted_at is null
    order by ta.aprovado_em desc, ta.id desc
    limit 1;

    select count(*)::integer
      into v_quantidade
    from f.titulo_rateio tr
    where tr.tenant_id = p_tenant_id
      and tr.titulo_id = v_titulo_id
      and tr.deleted_at is null;

    if v_quantidade = 0 then
      if v_os_id is not null
         and not exists (
           select 1
           from public.ordens_servico os
           where os.id = v_os_id
             and os.tenant_id = p_tenant_id
             and os.empresa_id = p_empresa_id
         )
      then
        raise exception using
          errcode = '23503',
          message = format(
            'A OS do titulo %s e invalida ou pertence a outra empresa.',
            v_titulo_id
          );
      end if;

      insert into f.titulo_rateio (
        tenant_id,
        titulo_id,
        plano_contas_id,
        centro_custo_id,
        os_id,
        percentual,
        valor,
        origem_rateio,
        regra_rateio_id,
        regra_item_id
      )
      values (
        p_tenant_id,
        v_titulo_id,
        p_plano_contas_id,
        p_centro_custo_id,
        v_os_id,
        100.0000,
        v_titulo.valor_total,
        'EXPLICITO',
        null,
        null
      );
    else
      select tr.*
        into strict v_rateio
      from f.titulo_rateio tr
      where tr.tenant_id = p_tenant_id
        and tr.titulo_id = v_titulo_id
        and tr.deleted_at is null
      for update;

      update f.titulo_rateio tr
      set
        plano_contas_id = p_plano_contas_id,
        centro_custo_id = p_centro_custo_id,
        origem_rateio = 'EXPLICITO',
        regra_rateio_id = null,
        regra_item_id = null,
        updated_at = now(),
        updated_by = v_actor
      where tr.id = v_rateio.id
        and tr.tenant_id = p_tenant_id
        and tr.titulo_id = v_titulo_id
        and tr.deleted_at is null;

      if not found then
        raise exception using
          errcode = '40001',
          message = format(
            'O rateio do titulo %s mudou durante a correcao.',
            v_titulo_id
          );
      end if;
    end if;

    v_snapshot_antes := v_snapshots_antes -> v_titulo_id::text;
    v_snapshot_depois := f.snapshot_inconsistencia_financeira_titulo(
      p_tenant_id,
      p_empresa_id,
      v_titulo_id
    );

    if v_snapshot_antes -> 'imutaveis'
       is distinct from v_snapshot_depois -> 'imutaveis'
    then
      raise exception using
        errcode = 'P0001',
        message = format(
          'A correcao do titulo %s tentou alterar valor, vencimento, saldo ou pagamento e foi cancelada.',
          v_titulo_id
        );
    end if;

    select coalesce(array_agg(chave.tipo order by chave.tipo), array[]::text[])
      into v_tipos_antes
    from jsonb_object_keys(
      v_detectadas_antes -> v_titulo_id::text
    ) as chave(tipo);

    select coalesce(array_agg(d.tipo order by d.tipo), array[]::text[])
      into v_tipos_depois
    from f.detectar_inconsistencias_financeiras(
      p_tenant_id,
      p_empresa_id,
      null,
      null
    ) d
    where d.titulo_id = v_titulo_id;

    foreach v_tipo_resolvido in array v_tipos_antes
    loop
      if not (v_tipo_resolvido = any(v_tipos_depois)) then
        v_fingerprint := v_detectadas_antes
          -> v_titulo_id::text
          -> v_tipo_resolvido
          ->> 'fingerprint';
        v_dados := v_detectadas_antes
          -> v_titulo_id::text
          -> v_tipo_resolvido
          -> 'dados';

        insert into f.inconsistencia_financeira_tratamento (
          tenant_id,
          empresa_id,
          titulo_id,
          tipo,
          status,
          fingerprint,
          justificativa,
          dados_snapshot,
          tratado_em,
          tratado_por
        )
        values (
          p_tenant_id,
          p_empresa_id,
          v_titulo_id,
          v_tipo_resolvido,
          'TRATADA',
          v_fingerprint,
          btrim(p_justificativa),
          coalesce(v_dados, '{}'::jsonb),
          now(),
          v_actor
        )
        on conflict (
          tenant_id,
          empresa_id,
          titulo_id,
          tipo
        ) where deleted_at is null
        do update set
          status = excluded.status,
          fingerprint = excluded.fingerprint,
          justificativa = excluded.justificativa,
          dados_snapshot = excluded.dados_snapshot,
          tratado_em = excluded.tratado_em,
          tratado_por = excluded.tratado_por,
          updated_at = now(),
          updated_by = v_actor;
      end if;
    end loop;

    insert into f.evento_financeiro (
      tenant_id,
      empresa_id,
      evento,
      ref_table,
      ref_id,
      payload,
      created_by
    )
    values (
      p_tenant_id,
      p_empresa_id,
      'INCONSISTENCIA_FINANCEIRA_CORRIGIDA',
      'f.titulo',
      v_titulo_id,
      jsonb_build_object(
        'planoContasId', p_plano_contas_id,
        'centroCustoId', p_centro_custo_id,
        'justificativa', btrim(p_justificativa),
        'inconsistenciasAntes', to_jsonb(v_tipos_antes),
        'inconsistenciasDepois', to_jsonb(v_tipos_depois),
        'regraCriadaId', v_regra_id,
        'antes', v_snapshot_antes,
        'depois', v_snapshot_depois,
        'alterouValor', false,
        'alterouVencimento', false,
        'alterouPagamento', false,
        'preservouOs', true
      ),
      v_actor
    );

    v_corrigidos := v_corrigidos + 1;
    v_resultados := v_resultados || jsonb_build_array(
      jsonb_build_object(
        'tituloId', v_titulo_id,
        'status', 'CORRIGIDO',
        'inconsistenciasAntes', to_jsonb(v_tipos_antes),
        'inconsistenciasDepois', to_jsonb(v_tipos_depois)
      )
    );
  end loop;

  return jsonb_build_object(
    'corrigidos', v_corrigidos,
    'regraCriadaId', v_regra_id,
    'titulos', v_resultados
  );
end;
$$;


ALTER FUNCTION "f"."corrigir_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_ids" "uuid"[], "p_plano_contas_id" "uuid", "p_centro_custo_id" "uuid", "p_justificativa" "text", "p_criar_regra" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "f"."corrigir_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_ids" "uuid"[], "p_plano_contas_id" "uuid", "p_centro_custo_id" "uuid", "p_justificativa" "text", "p_criar_regra" boolean) IS 'Corrige apenas plano/centro em zero ou uma linha de 100%, preservando valor, percentual, OS, parcelas e pagamentos. O lote e atomico.';



CREATE OR REPLACE FUNCTION "f"."criar_titulo_ap_manual"("p_descricao" "text", "p_vencimento_date" "date", "p_valor" numeric, "p_fornecedor_id" integer DEFAULT NULL::integer, "p_motivo_compra_id" "uuid" DEFAULT NULL::"uuid", "p_criar_recorrencia" boolean DEFAULT false, "p_dia_vencimento" integer DEFAULT NULL::integer, "p_auto_copiar_valor" boolean DEFAULT true, "p_change_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("titulo_id" "uuid", "recorrencia_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_usuario_id uuid;

  v_titulo_id uuid;
  v_recorrencia_id uuid;
  v_competencia date;
  v_day integer;
begin
  if p_descricao is null or length(trim(p_descricao)) = 0 then
    raise exception 'p_descricao obrigat3rio';
  end if;
  if p_vencimento_date is null then
    raise exception 'p_vencimento_date obrigat3rio';
  end if;
  if p_valor is null or p_valor <= 0 then
    raise exception 'p_valor deve ser > 0';
  end if;

  -- Auth: app ou SQL Editor
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();
  if v_tenant_id is null then
    raise exception 'Tenant n3o resolvido (current_tenant_id())';
  end if;
  if v_empresa_id is null then
    raise exception 'Empresa n3o resolvida (current_empresa_id())';
  end if;

  if auth.uid() is not null then
    if not f.has_finance_access(v_tenant_id, v_empresa_id) then
      raise exception 'Sem permiss3o financeira';
    end if;
  end if;

  v_usuario_id := a.fn_current_usuario_id();

  v_competencia := f._month_first(p_vencimento_date);

  insert into f.titulo (
    tenant_id,
    empresa_id,
    tipo,
    status,
    fornecedor_id,
    descricao,
    emissao_date,
    competencia_date,
    valor_total,
    valor_aberto,
    motivo_compra_id,
    created_at,
    updated_at,
    created_by,
    updated_by,
    deleted_at
  ) values (
    v_tenant_id,
    v_empresa_id,
    'AP',
    'PENDENTE',
    p_fornecedor_id,
    trim(p_descricao),
    current_date,
    v_competencia,
    p_valor,
    p_valor,
    p_motivo_compra_id,
    now(),
    now(),
    v_usuario_id,
    v_usuario_id,
    null
  ) returning id into v_titulo_id;

  insert into f.titulo_parcela (
    tenant_id,
    titulo_id,
    numero,
    vencimento_date,
    valor,
    valor_aberto,
    created_at,
    updated_at,
    created_by,
    updated_by,
    deleted_at
  ) values (
    v_tenant_id,
    v_titulo_id,
    '1',
    p_vencimento_date,
    p_valor,
    p_valor,
    now(),
    now(),
    v_usuario_id,
    v_usuario_id,
    null
  );

  if p_criar_recorrencia then
    v_day := coalesce(p_dia_vencimento, extract(day from p_vencimento_date)::int);

    insert into f.ap_recorrencia (
      tenant_id,
      empresa_id,
      fornecedor_id,
      descricao,
      motivo_compra_id,
      dia_vencimento,
      auto_copiar_valor,
      valor_base,
      ativo,
      created_at,
      updated_at,
      created_by,
      updated_by,
      deleted_at
    ) values (
      v_tenant_id,
      v_empresa_id,
      p_fornecedor_id,
      trim(p_descricao),
      p_motivo_compra_id,
      v_day,
      coalesce(p_auto_copiar_valor, true),
      p_valor,
      true,
      now(),
      now(),
      v_usuario_id,
      v_usuario_id,
      null
    ) returning id into v_recorrencia_id;

    update f.titulo
      set recorrencia_id = v_recorrencia_id,
          updated_at = now(),
          updated_by = v_usuario_id
    where id = v_titulo_id;
  end if;

  return query select v_titulo_id, v_recorrencia_id;
end;
$$;


ALTER FUNCTION "f"."criar_titulo_ap_manual"("p_descricao" "text", "p_vencimento_date" "date", "p_valor" numeric, "p_fornecedor_id" integer, "p_motivo_compra_id" "uuid", "p_criar_recorrencia" boolean, "p_dia_vencimento" integer, "p_auto_copiar_valor" boolean, "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."criar_titulo_ap_manual_parcelado_v1"("p_descricao" "text", "p_primeiro_vencimento" "date", "p_valor_parcela" numeric, "p_quantidade_parcelas" integer, "p_fornecedor_id" integer DEFAULT NULL::integer, "p_motivo_compra_id" "uuid" DEFAULT NULL::"uuid", "p_emissao_date" "date" DEFAULT NULL::"date", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("titulo_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_usuario_id uuid;
  v_titulo_id uuid;
  v_emissao date;
  v_valor_total numeric(15, 2);
  v_dia_vencimento integer;
  v_indice integer;
  v_vencimento date;
begin
  if p_descricao is null or length(trim(p_descricao)) = 0 then
    raise exception 'Descrição obrigatória';
  end if;

  if p_primeiro_vencimento is null then
    raise exception 'Primeiro vencimento obrigatório';
  end if;

  if p_valor_parcela is null or p_valor_parcela <= 0 then
    raise exception 'Valor da parcela deve ser maior que zero';
  end if;

  if p_quantidade_parcelas is null
     or p_quantidade_parcelas < 2
     or p_quantidade_parcelas > 120 then
    raise exception 'Quantidade de parcelas deve estar entre 2 e 120';
  end if;

  if auth.uid() is null
     and current_user not in ('postgres', 'service_role') then
    raise exception 'Usuário não autenticado';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null or v_empresa_id is null then
    raise exception 'Tenant e empresa devem estar selecionados';
  end if;

  if auth.uid() is not null
     and not f.has_finance_access(v_tenant_id, v_empresa_id) then
    raise exception 'Sem permissão financeira';
  end if;

  if p_fornecedor_id is not null
     and not exists (
       select 1
       from public.fornecedores fornecedor
       where fornecedor.id = p_fornecedor_id
         and fornecedor.tenant_id = v_tenant_id
         and fornecedor.empresa_id = v_empresa_id
         and fornecedor.ativo = true
     ) then
    raise exception 'Fornecedor inválido para a empresa selecionada';
  end if;

  if p_motivo_compra_id is not null
     and not exists (
       select 1
       from f.motivo_compra motivo
       where motivo.id = p_motivo_compra_id
         and motivo.tenant_id = v_tenant_id
         and motivo.ativo = true
         and motivo.deleted_at is null
     ) then
    raise exception 'Motivo inválido para o tenant selecionado';
  end if;

  v_usuario_id := a.fn_current_usuario_id();
  v_emissao := coalesce(p_emissao_date, p_primeiro_vencimento);
  v_valor_total := round(p_valor_parcela * p_quantidade_parcelas, 2);
  v_dia_vencimento := extract(day from p_primeiro_vencimento)::integer;

  if exists (
    select 1
    from f.titulo titulo
    where titulo.tenant_id = v_tenant_id
      and titulo.empresa_id = v_empresa_id
      and titulo.tipo = 'AP'
      and titulo.origem = 'MANUAL'
      and titulo.descricao = trim(p_descricao)
      and titulo.emissao_date = v_emissao
      and titulo.valor_total = v_valor_total
      and titulo.deleted_at is null
  ) then
    raise exception 'Já existe um AP parcelado com esta descrição, emissão e valor total';
  end if;

  insert into f.titulo (
    tenant_id,
    empresa_id,
    tipo,
    status,
    origem,
    fornecedor_id,
    descricao,
    emissao_date,
    competencia_date,
    valor_total,
    valor_aberto,
    motivo_compra_id,
    total_parcelas_serie,
    created_at,
    updated_at,
    created_by,
    updated_by,
    deleted_at
  ) values (
    v_tenant_id,
    v_empresa_id,
    'AP',
    'PENDENTE',
    'MANUAL',
    p_fornecedor_id,
    trim(p_descricao),
    v_emissao,
    f._month_first(v_emissao),
    v_valor_total,
    v_valor_total,
    p_motivo_compra_id,
    p_quantidade_parcelas,
    now(),
    now(),
    v_usuario_id,
    v_usuario_id,
    null
  ) returning id into v_titulo_id;

  for v_indice in 1..p_quantidade_parcelas loop
    v_vencimento := f._safe_day_in_month(
      f._month_first((p_primeiro_vencimento + ((v_indice - 1) || ' months')::interval)::date),
      v_dia_vencimento
    );

    insert into f.titulo_parcela (
      tenant_id,
      titulo_id,
      numero,
      vencimento_date,
      valor,
      valor_aberto,
      created_at,
      updated_at,
      created_by,
      updated_by,
      deleted_at
    ) values (
      v_tenant_id,
      v_titulo_id,
      lpad(v_indice::text, 3, '0'),
      v_vencimento,
      round(p_valor_parcela, 2),
      round(p_valor_parcela, 2),
      now(),
      now(),
      v_usuario_id,
      v_usuario_id,
      null
    );
  end loop;

  return query select v_titulo_id;
end;
$$;


ALTER FUNCTION "f"."criar_titulo_ap_manual_parcelado_v1"("p_descricao" "text", "p_primeiro_vencimento" "date", "p_valor_parcela" numeric, "p_quantidade_parcelas" integer, "p_fornecedor_id" integer, "p_motivo_compra_id" "uuid", "p_emissao_date" "date", "p_change_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."criar_titulo_ap_manual_parcelado_v1"("p_descricao" "text", "p_primeiro_vencimento" "date", "p_valor_parcela" numeric, "p_quantidade_parcelas" integer, "p_fornecedor_id" integer, "p_motivo_compra_id" "uuid", "p_emissao_date" "date", "p_change_reason" "text") IS 'Cria AP manual com parcelas mensais, respeitando tenant, empresa ativa e acesso financeiro.';



CREATE OR REPLACE FUNCTION "f"."criar_titulo_ap_manual_v2"("p_descricao" "text", "p_vencimento_date" "date", "p_valor" numeric, "p_fornecedor_id" integer DEFAULT NULL::integer, "p_motivo_compra_id" "uuid" DEFAULT NULL::"uuid", "p_emissao_date" "date" DEFAULT NULL::"date", "p_criar_recorrencia" boolean DEFAULT false, "p_dia_vencimento" integer DEFAULT NULL::integer, "p_auto_copiar_valor" boolean DEFAULT true, "p_change_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("titulo_id" "uuid", "recorrencia_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_usuario_id uuid;

  v_titulo_id uuid;
  v_recorrencia_id uuid;

  v_emissao date;
  v_competencia date;
  v_day integer;
begin
  if p_descricao is null or length(trim(p_descricao)) = 0 then
    raise exception 'p_descricao obrigatorio';
  end if;

  if p_vencimento_date is null then
    raise exception 'p_vencimento_date obrigatorio';
  end if;

  if p_valor is null or p_valor <= 0 then
    raise exception 'p_valor deve ser > 0';
  end if;

  -- Auth: app ou SQL Editor
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null then
    raise exception 'Tenant nao resolvido (current_tenant_id())';
  end if;

  if v_empresa_id is null then
    raise exception 'Empresa nao resolvida (current_empresa_id())';
  end if;

  if auth.uid() is not null then
    if not f.has_finance_access(v_tenant_id, v_empresa_id) then
      raise exception 'Sem permissao financeira';
    end if;
  end if;

  v_usuario_id := a.fn_current_usuario_id();

  -- data da NF (emissão). Se não vier, usa vencimento como “melhor chute” (melhor que current_date).
  v_emissao := coalesce(
    p_emissao_date,
    p_vencimento_date,
    (now() at time zone 'America/Sao_Paulo')::date
  );

  -- competência baseada na emissão (se informada), mantendo padrão day=1
  v_competencia := f._month_first(v_emissao);

  insert into f.titulo (
    tenant_id,
    empresa_id,
    tipo,
    status,
    origem,
    fornecedor_id,
    descricao,
    emissao_date,
    competencia_date,
    valor_total,
    valor_aberto,
    motivo_compra_id,
    created_at,
    updated_at,
    created_by,
    updated_by,
    deleted_at
  ) values (
    v_tenant_id,
    v_empresa_id,
    'AP',
    'PENDENTE',
    'MANUAL',
    p_fornecedor_id,
    trim(p_descricao),
    v_emissao,
    v_competencia,
    p_valor,
    p_valor,
    p_motivo_compra_id,
    now(),
    now(),
    v_usuario_id,
    v_usuario_id,
    null
  ) returning id into v_titulo_id;

  insert into f.titulo_parcela (
    tenant_id,
    titulo_id,
    numero,
    vencimento_date,
    valor,
    valor_aberto,
    created_at,
    updated_at,
    created_by,
    updated_by,
    deleted_at
  ) values (
    v_tenant_id,
    v_titulo_id,
    '1',
    p_vencimento_date,
    p_valor,
    p_valor,
    now(),
    now(),
    v_usuario_id,
    v_usuario_id,
    null
  );

  if p_criar_recorrencia then
    v_day := coalesce(p_dia_vencimento, extract(day from p_vencimento_date)::int);

    insert into f.ap_recorrencia (
      tenant_id,
      empresa_id,
      fornecedor_id,
      descricao,
      motivo_compra_id,
      dia_vencimento,
      auto_copiar_valor,
      valor_base,
      ativo,
      created_at,
      updated_at,
      created_by,
      updated_by,
      deleted_at
    ) values (
      v_tenant_id,
      v_empresa_id,
      p_fornecedor_id,
      trim(p_descricao),
      p_motivo_compra_id,
      v_day,
      coalesce(p_auto_copiar_valor, true),
      p_valor,
      true,
      now(),
      now(),
      v_usuario_id,
      v_usuario_id,
      null
    ) returning id into v_recorrencia_id;

    update f.titulo
      set recorrencia_id = v_recorrencia_id,
          updated_at = now(),
          updated_by = v_usuario_id
    where id = v_titulo_id;
  end if;

  return query select v_titulo_id, v_recorrencia_id;
end;
$$;


ALTER FUNCTION "f"."criar_titulo_ap_manual_v2"("p_descricao" "text", "p_vencimento_date" "date", "p_valor" numeric, "p_fornecedor_id" integer, "p_motivo_compra_id" "uuid", "p_emissao_date" "date", "p_criar_recorrencia" boolean, "p_dia_vencimento" integer, "p_auto_copiar_valor" boolean, "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."criar_titulo_ar_manual_v1"("p_cliente_id" integer, "p_descricao" "text", "p_emissao_date" "date", "p_vencimento_date" "date", "p_valor" numeric, "p_os_id" integer DEFAULT NULL::integer, "p_change_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("titulo_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_usuario_id uuid;
  v_titulo_id uuid;
begin
  if p_cliente_id is null then
    raise exception 'Cliente obrigatório';
  end if;

  if p_descricao is null or length(trim(p_descricao)) = 0 then
    raise exception 'Descrição obrigatória';
  end if;

  if p_emissao_date is null then
    raise exception 'Data de emissão obrigatória';
  end if;

  if p_vencimento_date is null then
    raise exception 'Vencimento obrigatório';
  end if;

  if p_valor is null or p_valor <= 0 then
    raise exception 'Valor deve ser maior que zero';
  end if;

  if auth.uid() is null
     and current_user not in ('postgres', 'service_role') then
    raise exception 'Usuário não autenticado';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null or v_empresa_id is null then
    raise exception 'Tenant e empresa devem estar selecionados';
  end if;

  if auth.uid() is not null
     and not f.has_finance_access(v_tenant_id, v_empresa_id) then
    raise exception 'Sem permissão financeira';
  end if;

  if not exists (
    select 1
    from public.clientes cliente
    where cliente.id = p_cliente_id
      and cliente.tenant_id = v_tenant_id
      and cliente.empresa_id = v_empresa_id
      and cliente.ativo = true
  ) then
    raise exception 'Cliente inválido para a empresa selecionada';
  end if;

  if p_os_id is not null
     and not exists (
       select 1
       from public.ordens_servico os
       where os.id = p_os_id
         and os.tenant_id = v_tenant_id
         and os.empresa_id = v_empresa_id
     ) then
    raise exception 'OS inválida para a empresa selecionada';
  end if;

  v_usuario_id := a.fn_current_usuario_id();

  insert into f.titulo (
    tenant_id,
    empresa_id,
    tipo,
    status,
    origem,
    cliente_id,
    os_id,
    descricao,
    emissao_date,
    competencia_date,
    valor_total,
    valor_aberto,
    created_at,
    updated_at,
    created_by,
    updated_by,
    deleted_at
  ) values (
    v_tenant_id,
    v_empresa_id,
    'AR',
    'PENDENTE',
    'MANUAL',
    p_cliente_id,
    p_os_id,
    trim(p_descricao),
    p_emissao_date,
    f._month_first(p_emissao_date),
    p_valor,
    p_valor,
    now(),
    now(),
    v_usuario_id,
    v_usuario_id,
    null
  ) returning id into v_titulo_id;

  insert into f.titulo_parcela (
    tenant_id,
    titulo_id,
    numero,
    vencimento_date,
    valor,
    valor_aberto,
    created_at,
    updated_at,
    created_by,
    updated_by,
    deleted_at
  ) values (
    v_tenant_id,
    v_titulo_id,
    '1',
    p_vencimento_date,
    p_valor,
    p_valor,
    now(),
    now(),
    v_usuario_id,
    v_usuario_id,
    null
  );

  return query select v_titulo_id;
end;
$$;


