COMMENT ON FUNCTION "f"."criar_titulo_ar_manual_v1"("p_cliente_id" integer, "p_descricao" "text", "p_emissao_date" "date", "p_vencimento_date" "date", "p_valor" numeric, "p_os_id" integer, "p_change_reason" "text") IS 'Cria AR manual (sem documento fiscal), respeitando tenant, empresa ativa e acesso financeiro.';



CREATE OR REPLACE FUNCTION "f"."desconciliar_pagamento_extrato"("p_conciliacao_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_conc f.conciliacao_bancaria%rowtype;
  v_user uuid;
begin
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select * into v_conc
  from f.conciliacao_bancaria
  where id = p_conciliacao_id
    and deleted_at is null;

  if not found then
    raise exception 'Conciliacao nao encontrada/ja desfeita (id=%)', p_conciliacao_id;
  end if;

  if auth.uid() is not null then
    if not f.has_finance_access(v_conc.tenant_id, v_conc.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  if v_user is null then
    select ut.usuario_id into v_user
    from a.usuario_tenant ut
    where ut.tenant_id = v_conc.tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN')
    order by ut.created_at nulls last
    limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  -- desfaz conciliação (mantém histórico)
  update f.conciliacao_bancaria
     set status = 'DESCONCILIADO',
         deleted_at = now(),
         updated_at = now(),
         updated_by = v_user
   where id = v_conc.id;

  -- volta linha para pendente (se existir)
  update f.extrato_bancario_linha
     set status = 'PENDENTE',
         updated_at = now(),
         updated_by = v_user
   where id = v_conc.extrato_linha_id
     and deleted_at is null;

  -- limpa conciliação no pagamento (se existir)
  update f.pagamento
     set conciliado_at = null,
         conciliado_por = null,
         updated_at = now(),
         updated_by = v_user
   where id = v_conc.pagamento_id
     and deleted_at is null;

  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_conc.tenant_id, v_conc.empresa_id,
    'PAGAMENTO_DESCONCILIADO',
    'f.conciliacao_bancaria',
    v_conc.id,
    jsonb_build_object(
      'motivo', p_motivo,
      'extrato_linha_id', v_conc.extrato_linha_id,
      'pagamento_id', v_conc.pagamento_id
    ),
    now(), v_user
  );
end;
$$;


ALTER FUNCTION "f"."desconciliar_pagamento_extrato"("p_conciliacao_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."desdobrar_parcela_ar_para_recebimento"("p_parcela_id" "uuid", "p_valor_receber" numeric, "p_novo_vencimento_date" "date" DEFAULT NULL::"date", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a'
    SET "row_security" TO 'off'
    AS $$
declare
  v_parcela f.titulo_parcela%rowtype;
  v_titulo f.titulo%rowtype;
  v_user uuid;
  v_receber numeric(15,2);
  v_remanescente numeric(15,2);
  v_new_numero text;
  v_new_parcela_id uuid;
begin
  if p_parcela_id is null then
    raise exception 'p_parcela_id obrigatorio';
  end if;

  if p_valor_receber is null or p_valor_receber <= 0 then
    raise exception 'p_valor_receber deve ser > 0';
  end if;

  if auth.uid() is null then
    if current_user not in ('postgres', 'service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select p.*
    into v_parcela
  from f.titulo_parcela p
  where p.id = p_parcela_id
    and p.deleted_at is null
  for update;

  if not found then
    raise exception 'Parcela nao encontrada (id=%)', p_parcela_id;
  end if;

  select *
    into v_titulo
  from f.titulo
  where id = v_parcela.titulo_id
    and deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado para parcela (id=%)', p_parcela_id;
  end if;

  if v_titulo.tipo <> 'AR' then
    raise exception 'Desdobramento permitido somente para AR';
  end if;

  if auth.uid() is not null then
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  if coalesce(v_parcela.valor_aberto, 0) <= 0 then
    raise exception 'Parcela sem saldo em aberto';
  end if;

  if round(coalesce(v_parcela.valor_aberto, 0), 2) <> round(coalesce(v_parcela.valor, 0), 2) then
    raise exception 'Desdobramento permitido apenas para parcela sem recebimentos anteriores';
  end if;

  v_receber := round(p_valor_receber, 2);
  if v_receber >= round(v_parcela.valor_aberto, 2) then
    raise exception 'Valor a receber deve ser menor que saldo aberto da parcela';
  end if;

  v_remanescente := round(v_parcela.valor_aberto - v_receber, 2);
  if v_remanescente <= 0 then
    raise exception 'Saldo remanescente invalido';
  end if;

  select lpad(
           (
             coalesce(
               max(
                 case
                   when regexp_replace(coalesce(numero, ''), '\D', '', 'g') <> ''
                     then regexp_replace(numero, '\D', '', 'g')::int
                   else null
                 end
               ),
               0
             ) + 1
           )::text,
           3,
           '0'
         )
    into v_new_numero
  from f.titulo_parcela
  where tenant_id = v_parcela.tenant_id
    and titulo_id = v_parcela.titulo_id
    and deleted_at is null;

  v_user := a.fn_current_usuario_id();

  update f.titulo_parcela
     set valor = v_receber,
         valor_aberto = v_receber,
         updated_at = now(),
         updated_by = v_user
   where id = v_parcela.id;

  insert into f.titulo_parcela (
    tenant_id,
    titulo_id,
    numero,
    vencimento_date,
    valor,
    valor_aberto,
    created_at,
    updated_at,
    created_by,
    updated_by
  )
  values (
    v_parcela.tenant_id,
    v_parcela.titulo_id,
    v_new_numero,
    coalesce(p_novo_vencimento_date, v_parcela.vencimento_date),
    v_remanescente,
    v_remanescente,
    now(),
    now(),
    v_user,
    v_user
  )
  returning id into v_new_parcela_id;

  return v_new_parcela_id;
end;
$$;


ALTER FUNCTION "f"."desdobrar_parcela_ar_para_recebimento"("p_parcela_id" "uuid", "p_valor_receber" numeric, "p_novo_vencimento_date" "date", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."desmarcar_legado_implantacao_ap"("p_titulo_id" "uuid", "p_motivo" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_marcacao f.titulo_legado_implantacao%rowtype;
  v_actor uuid;
begin
  if length(btrim(coalesce(p_motivo, ''))) < 10 then
    raise exception using
      errcode = '22023',
      message = 'Informe um motivo de desmarcacao com pelo menos 10 caracteres';
  end if;

  if auth.uid() is null and coalesce(auth.role(), '') <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado';
  end if;

  select *
  into v_titulo
  from f.titulo t
  where t.id = p_titulo_id
    and t.deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if auth.uid() is not null then
    if public.current_tenant_id() is distinct from v_titulo.tenant_id
       or public.current_empresa_id() is distinct from v_titulo.empresa_id
       or not f.has_finance_access(
         v_titulo.tenant_id,
         v_titulo.empresa_id
       ) then
      raise exception using
        errcode = '42501',
        message = 'Sem permissao para o escopo do titulo';
    end if;
  end if;

  select *
  into v_marcacao
  from f.titulo_legado_implantacao li
  where li.tenant_id = v_titulo.tenant_id
    and li.empresa_id = v_titulo.empresa_id
    and li.titulo_id = v_titulo.id
    and li.desmarcado_em is null
  for update;

  if not found then
    raise exception 'Titulo nao possui marcacao ativa de legado';
  end if;

  v_actor := a.fn_current_usuario_id();

  update f.titulo_legado_implantacao
  set
    desmarcado_em = now(),
    desmarcado_por = v_actor,
    motivo_desmarcacao = btrim(p_motivo),
    updated_at = now()
  where id = v_marcacao.id;

  insert into f.evento_financeiro (
    tenant_id,
    empresa_id,
    evento,
    ref_table,
    ref_id,
    payload,
    created_by
  )
  values (
    v_titulo.tenant_id,
    v_titulo.empresa_id,
    'TITULO_AP_LEGADO_IMPLANTACAO_DESMARCADO',
    'f.titulo',
    v_titulo.id,
    jsonb_build_object(
      'marcacaoId', v_marcacao.id,
      'motivo', btrim(p_motivo),
      'gerouPagamento', false,
      'alterouResultado', false
    ),
    v_actor
  );
end;
$$;


ALTER FUNCTION "f"."desmarcar_legado_implantacao_ap"("p_titulo_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."detectar_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date" DEFAULT NULL::"date", "p_data_fim" "date" DEFAULT NULL::"date") RETURNS TABLE("titulo_id" "uuid", "tipo" "text", "prioridade" "text", "data_referencia" "date", "fornecedor_id" integer, "fornecedor_nome" "text", "documento" "text", "descricao" "text", "valor_total" numeric, "motivo_compra_id" "uuid", "motivo_codigo" "text", "motivo_nome" "text", "plano_atual_id" "uuid", "plano_atual_codigo" "text", "plano_atual_nome" "text", "centro_atual_id" "uuid", "centro_atual_codigo" "text", "centro_atual_nome" "text", "total_rateios" integer, "total_percentual" numeric, "total_rateado" numeric, "tem_rateio_explicito" boolean, "detalhe" "text", "sugestao" "text", "corrigivel" boolean, "pode_criar_regra" boolean, "fingerprint" "text", "dados" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $_$
  with base_inicial as (
    select
      t.id as titulo_id,
      t.fornecedor_id,
      coalesce(forn.nome, 'SEM FORNECEDOR')::text as fornecedor_nome,
      coalesce(df.numero, df.chave_acesso, t.documento_fiscal_id::text)
        as documento,
      t.documento_fiscal_id,
      t.descricao,
      t.valor_total,
      t.updated_at as titulo_updated_at,
      coalesce(
        t.competencia_date,
        t.emissao_date,
        parcelas.primeiro_vencimento,
        t.created_at::date
      ) as data_referencia,
      coalesce(aprovacao.motivo_compra_id, t.motivo_compra_id)
        as motivo_compra_id,
      mc.codigo as motivo_codigo,
      mc.nome as motivo_nome,
      mc.plano_contas_id as plano_motivo_id,
      regra.id as regra_rateio_id,
      coalesce(rateio.total_rateios, 0)::integer as total_rateios,
      coalesce(rateio.total_percentual, 0)::numeric as total_percentual,
      coalesce(rateio.total_rateado, 0)::numeric as total_rateado,
      coalesce(rateio.tem_explicito, false) as tem_rateio_explicito,
      coalesce(rateio.tem_plano_nulo, false) as tem_plano_nulo,
      coalesce(rateio.tem_centro_nulo, false) as tem_centro_nulo,
      coalesce(rateio.tem_desp_geral, false) as tem_desp_geral,
      coalesce(rateio.tem_plano_invalido, false) as tem_plano_invalido,
      coalesce(rateio.tem_centro_invalido, false) as tem_centro_invalido,
      coalesce(
        rateio.tem_plano_divergente_motivo,
        false
      ) as tem_plano_divergente_motivo,
      rateio.plano_atual_id,
      rateio.plano_atual_codigo,
      rateio.plano_atual_nome,
      rateio.centro_atual_id,
      rateio.centro_atual_codigo,
      rateio.centro_atual_nome,
      coalesce(rateio.rateios, '[]'::jsonb) as rateios,
      rateio.rateio_updated_at,
      count(*) filter (
        where t.documento_fiscal_id is not null
      ) over (
        partition by t.documento_fiscal_id
      ) as quantidade_mesmo_documento
    from f.titulo t
    left join public.fornecedores forn
      on forn.id = t.fornecedor_id
     and forn.tenant_id = t.tenant_id
     and forn.empresa_id = t.empresa_id
    left join f.documento_fiscal df
      on df.id = t.documento_fiscal_id
     and df.tenant_id = t.tenant_id
     and df.empresa_id = t.empresa_id
     and df.deleted_at is null
    left join lateral (
      select
        ta.motivo_compra_id,
        ta.os_id
      from f.titulo_aprovacao ta
      where ta.tenant_id = t.tenant_id
        and ta.titulo_id = t.id
        and ta.deleted_at is null
      order by ta.aprovado_em desc, ta.id desc
      limit 1
    ) aprovacao on true
    left join f.motivo_compra mc
      on mc.id = coalesce(
        aprovacao.motivo_compra_id,
        t.motivo_compra_id
      )
     and mc.tenant_id = t.tenant_id
     and mc.ativo
     and mc.deleted_at is null
    left join f.regra_rateio regra
      on regra.tenant_id = t.tenant_id
     and regra.empresa_id = t.empresa_id
     and regra.motivo_compra_id = mc.id
     and regra.ativo
     and regra.deleted_at is null
    left join lateral (
      select min(tp.vencimento_date) as primeiro_vencimento
      from f.titulo_parcela tp
      where tp.tenant_id = t.tenant_id
        and tp.titulo_id = t.id
        and tp.deleted_at is null
    ) parcelas on true
    left join lateral (
      select
        count(*)::integer as total_rateios,
        coalesce(sum(coalesce(tr.percentual, 0)), 0)
          as total_percentual,
        coalesce(sum(coalesce(
          tr.valor,
          round(
            t.valor_total * coalesce(tr.percentual, 0) / 100.0,
            2
          ),
          0
        )), 0) as total_rateado,
        bool_or(tr.origem_rateio = 'EXPLICITO') as tem_explicito,
        bool_or(tr.plano_contas_id is null) as tem_plano_nulo,
        bool_or(tr.centro_custo_id is null) as tem_centro_nulo,
        bool_or(pc.codigo = 'DESP_GERAL') as tem_desp_geral,
        bool_or(
          tr.plano_contas_id is not null
          and pc.id is null
        ) as tem_plano_invalido,
        bool_or(
          tr.centro_custo_id is not null
          and cc.id is null
        ) as tem_centro_invalido,
        bool_or(
          mc.plano_contas_id is not null
          and mc.codigo <> 'DESP_GERAL'
          and tr.plano_contas_id is distinct from mc.plano_contas_id
        ) as tem_plano_divergente_motivo,
        (array_agg(tr.plano_contas_id order by tr.id))[1]
          as plano_atual_id,
        min(pc.codigo) as plano_atual_codigo,
        min(pc.nome) as plano_atual_nome,
        (array_agg(tr.centro_custo_id order by tr.id))[1]
          as centro_atual_id,
        min(cc.codigo) as centro_atual_codigo,
        min(cc.nome) as centro_atual_nome,
        jsonb_agg(
          jsonb_build_object(
            'id', tr.id,
            'planoContasId', tr.plano_contas_id,
            'planoCodigo', pc.codigo,
            'planoNome', pc.nome,
            'centroCustoId', tr.centro_custo_id,
            'centroCodigo', cc.codigo,
            'centroNome', cc.nome,
            'osId', tr.os_id,
            'percentual', tr.percentual,
            'valor', tr.valor,
            'origemRateio', tr.origem_rateio
          )
          order by tr.id
        ) as rateios,
        max(tr.updated_at) as rateio_updated_at
      from f.titulo_rateio tr
      left join f.plano_contas pc
        on pc.id = tr.plano_contas_id
       and pc.tenant_id = tr.tenant_id
       and pc.tipo = 'ANALITICA'
       and pc.ativo
       and pc.deleted_at is null
      left join f.centro_custo cc
        on cc.id = tr.centro_custo_id
       and cc.tenant_id = tr.tenant_id
       and cc.empresa_id = t.empresa_id
       and cc.ativo
       and cc.deleted_at is null
      where tr.tenant_id = t.tenant_id
        and tr.titulo_id = t.id
        and tr.deleted_at is null
    ) rateio on true
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.tipo = 'AP'
      and t.status <> 'CANCELADO'
      and t.deleted_at is null
      and not f.titulo_eh_legado_implantacao(
        t.tenant_id,
        t.empresa_id,
        t.id
      )
  ),
  base as (
    select *
    from base_inicial b
    where (p_data_inicio is null or b.data_referencia >= p_data_inicio)
      and (p_data_fim is null or b.data_referencia <= p_data_fim)
  ),
  problemas as (
    select
      b.*,
      p.tipo,
      p.prioridade,
      p.detalhe,
      p.sugestao,
      p.corrigivel,
      p.pode_criar_regra
    from base b
    cross join lateral (
      values
        (
          'SEM_MOTIVO_COMPRA'::text,
          'ALTA'::text,
          'O titulo nao possui motivo de compra ativo.'::text,
          'Classifique o motivo antes de criar ou aplicar uma regra.'::text,
          false,
          false,
          b.motivo_compra_id is null or b.motivo_codigo is null
        ),
        (
          'SEM_REGRA_RATEIO',
          'BAIXA',
          'O motivo possui plano, mas nao existe regra ativa para esta empresa.',
          'Revise o destino e crie uma regra somente se ele for recorrente.',
          (
            b.total_rateios = 0
            or (
              b.total_rateios = 1
              and abs(b.total_percentual - 100.0000) <= 0.0001
            )
          ) and b.motivo_codigo <> 'DESP_GERAL',
          (
            b.total_rateios = 0
            or (
              b.total_rateios = 1
              and abs(b.total_percentual - 100.0000) <= 0.0001
            )
          ) and b.motivo_codigo <> 'DESP_GERAL',
          b.motivo_compra_id is not null
            and b.plano_motivo_id is not null
            and b.regra_rateio_id is null
        ),
        (
          'SEM_RATEIO',
          'ALTA',
          'O titulo nao possui rateio financeiro ativo.',
          'Informe plano e centro de custo ou aplique uma regra conferida.',
          true,
          b.motivo_compra_id is not null
            and b.motivo_codigo <> 'DESP_GERAL'
            and b.regra_rateio_id is null,
          b.total_rateios = 0
        ),
        (
          'SEM_PLANO_CONTAS',
          'ALTA',
          'Existe rateio sem plano de contas.',
          'Defina um plano analitico coerente com o motivo da compra.',
          b.total_rateios = 1
            and abs(b.total_percentual - 100.0000) <= 0.0001,
          b.motivo_compra_id is not null
            and b.motivo_codigo <> 'DESP_GERAL'
            and b.regra_rateio_id is null
            and b.total_rateios = 1,
          b.total_rateios > 0 and b.tem_plano_nulo
        ),
        (
          'SEM_CENTRO_CUSTO',
          'ALTA',
          'Existe rateio sem centro de custo.',
          'Defina o centro responsavel; evite usar Despesas Gerais.',
          b.total_rateios = 1
            and abs(b.total_percentual - 100.0000) <= 0.0001,
          b.motivo_compra_id is not null
            and b.motivo_codigo <> 'DESP_GERAL'
            and b.regra_rateio_id is null
            and b.total_rateios = 1,
          b.total_rateios > 0 and b.tem_centro_nulo
        ),
        (
          'DESP_GERAL',
          'MEDIA',
          'O titulo esta classificado em DESP_GERAL.',
          'Substitua por um plano e centro especificos quando houver evidencia.',
          b.total_rateios = 1
            and abs(b.total_percentual - 100.0000) <= 0.0001,
          false,
          b.tem_desp_geral
        ),
        (
          'RATEIO_PERCENTUAL_INCORRETO',
          'ALTA',
          format(
            'Os percentuais somam %s%%, mas deveriam somar 100%%.',
            round(b.total_percentual, 4)
          ),
          'Revise o rateio no titulo; a central nao divide linhas automaticamente.',
          false,
          false,
          b.total_rateios > 0
            and abs(b.total_percentual - 100.0000) > 0.0001
        ),
        (
          'RATEIO_VALOR_INCORRETO',
          'ALTA',
          format(
            'O rateio soma R$ %s e o titulo vale R$ %s.',
            round(b.total_rateado, 2),
            round(b.valor_total, 2)
          ),
          'Revise os valores do rateio no titulo; nenhum valor sera ajustado em lote.',
          false,
          false,
          b.total_rateios > 0
            and abs(b.total_rateado - b.valor_total) > 0.01
        ),
        (
          'PLANO_INVALIDO',
          'ALTA',
          'Existe plano ausente, inativo, sintetico ou de outro tenant.',
          'Escolha um plano analitico ativo.',
          b.total_rateios = 1
            and abs(b.total_percentual - 100.0000) <= 0.0001,
          false,
          b.tem_plano_invalido
        ),
        (
          'CENTRO_INVALIDO',
          'ALTA',
          'Existe centro inativo ou de outra empresa.',
          'Escolha um centro ativo desta empresa.',
          b.total_rateios = 1
            and abs(b.total_percentual - 100.0000) <= 0.0001,
          false,
          b.tem_centro_invalido
        ),
        (
          'PLANO_DIVERGENTE_MOTIVO',
          'MEDIA',
          'O plano do rateio diverge do plano configurado no motivo.',
          'Confirme o motivo ou ajuste o plano; a regra sempre herda o plano do motivo.',
          b.total_rateios = 1
            and abs(b.total_percentual - 100.0000) <= 0.0001,
          false,
          b.tem_plano_divergente_motivo
        ),
        (
          'POSSIVEL_DUPLICIDADE',
          'ALTA',
          'Mais de um titulo ativo referencia o mesmo documento fiscal.',
          'Confira os titulos antes de qualquer baixa ou exclusao.',
          false,
          false,
          coalesce(b.quantidade_mesmo_documento, 0) > 1
        )
    ) as p(
      tipo,
      prioridade,
      detalhe,
      sugestao,
      corrigivel,
      pode_criar_regra,
      aplica
    )
    where p.aplica
  ),
  normalizado as (
    select
      p.*,
      jsonb_build_object(
        'tipo', p.tipo,
        'tituloId', p.titulo_id,
        'motivoCompraId', p.motivo_compra_id,
        'planoMotivoId', p.plano_motivo_id,
        'regraRateioId', p.regra_rateio_id,
        'tituloUpdatedAt', p.titulo_updated_at,
        'rateioUpdatedAt', p.rateio_updated_at,
        'rateios', p.rateios,
        'documentoFiscalId', p.documento_fiscal_id,
        'quantidadeMesmoDocumento',
          coalesce(p.quantidade_mesmo_documento, 0)
      ) as dados_inconsistencia
    from problemas p
  )
  select
    n.titulo_id,
    n.tipo,
    n.prioridade,
    n.data_referencia,
    n.fornecedor_id,
    n.fornecedor_nome,
    n.documento,
    n.descricao,
    n.valor_total,
    n.motivo_compra_id,
    n.motivo_codigo,
    n.motivo_nome,
    n.plano_atual_id,
    n.plano_atual_codigo,
    n.plano_atual_nome,
    n.centro_atual_id,
    n.centro_atual_codigo,
    n.centro_atual_nome,
    n.total_rateios,
    n.total_percentual,
    n.total_rateado,
    n.tem_rateio_explicito,
    n.detalhe,
    n.sugestao,
    n.corrigivel,
    n.pode_criar_regra,
    md5(n.dados_inconsistencia::text) as fingerprint,
    n.dados_inconsistencia as dados
  from normalizado n;
$_$;


ALTER FUNCTION "f"."detectar_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."estornar_pagamento_ap"("p_pagamento_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_pag f.pagamento%rowtype;
  v_user uuid;

  r record;

  v_titulo_id uuid;
  v_titulo f.titulo%rowtype;
  v_soma_aberto numeric(15,2);
begin
  -- auth: app ou SQL Editor (postgres/service_role)
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  -- carrega pagamento
  select * into v_pag
  from f.pagamento
  where id = p_pagamento_id
    and (deleted_at is null);

  if not found then
    raise exception 'Pagamento nao encontrado/ja estornado (id=%)', p_pagamento_id;
  end if;

  -- permissão no app
  if auth.uid() is not null then
    if not f.has_finance_access(v_pag.tenant_id, v_pag.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  -- fallback usuário (SQL Editor)
  if v_user is null then
    select ut.usuario_id
      into v_user
    from a.usuario_tenant ut
    where ut.tenant_id = v_pag.tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN')
    order by ut.created_at nulls last
    limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  -- devolve valor para cada parcela vinculada
  for r in
    select pi.id as pagamento_item_id,
           pi.valor as valor_aplicado,
           tp.id as parcela_id,
           tp.titulo_id as titulo_id
    from f.pagamento_item pi
    join f.titulo_parcela tp on tp.id = pi.titulo_parcela_id
    where pi.pagamento_id = v_pag.id
      and pi.tenant_id = v_pag.tenant_id
      and (pi.deleted_at is null)
      and (tp.deleted_at is null)
  loop
    -- guarda um titulo_id para recalcular ao final (assumimos 1 título por pagamento, que é o padrão aqui)
    v_titulo_id := r.titulo_id;

    update f.titulo_parcela
       set valor_aberto = round(valor_aberto + r.valor_aplicado, 2),
           updated_at = now(),
           updated_by = v_user
     where id = r.parcela_id;

    -- soft delete no item
    update f.pagamento_item
       set deleted_at = now()
     where id = r.pagamento_item_id;
  end loop;

  if v_titulo_id is null then
    raise exception 'Pagamento sem itens vinculados (pagamento_id=%)', v_pag.id;
  end if;

  -- soft delete no pagamento
  update f.pagamento
     set deleted_at = now(),
         updated_at = now(),
         updated_by = v_user
   where id = v_pag.id;

  -- recalcula título
  select * into v_titulo
  from f.titulo
  where id = v_titulo_id
    and deleted_at is null;

  if not found then
    raise exception 'Titulo do pagamento nao encontrado (titulo_id=%)', v_titulo_id;
  end if;

  select coalesce(sum(valor_aberto),0)::numeric(15,2)
    into v_soma_aberto
  from f.titulo_parcela
  where tenant_id = v_titulo.tenant_id
    and titulo_id = v_titulo.id
    and deleted_at is null;

  update f.titulo
     set valor_aberto = v_soma_aberto,
         status = case
                   when v_soma_aberto = 0 then 'PAGO'
                   else 'APROVADO'
                 end,
         updated_at = now(),
         updated_by = v_user
   where id = v_titulo.id;

  -- eventos
  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_pag.tenant_id, v_pag.empresa_id,
    'PAGAMENTO_ESTORNADO',
    'f.pagamento',
    v_pag.id,
    jsonb_build_object(
      'motivo', p_motivo,
      'titulo_id', v_titulo.id,
      'saldo_titulo_pos', v_soma_aberto
    ),
    now(), v_user
  );

  insert into f.aprovacao_evento (
    tenant_id, empresa_id,
    acao, ref_table, ref_id,
    motivo, payload,
    created_at, created_by
  )
  values (
    v_pag.tenant_id, v_pag.empresa_id,
    'REPROVOU',              -- usamos esse "tipo" como evento administrativo/financeiro
    'f.pagamento',
    v_pag.id,
    'ESTORNO',
    jsonb_build_object(
      'motivo', p_motivo,
      'titulo_id', v_titulo.id,
      'pagamento_id', v_pag.id
    ),
    now(), v_user
  );

end;
$$;


ALTER FUNCTION "f"."estornar_pagamento_ap"("p_pagamento_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."faturamento_analitico_documentos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim_exclusiva" "date") RETURNS TABLE("id" "uuid", "emissao_date" "date", "competencia_date" "date", "empresa_id" "uuid", "cliente_id" integer, "cliente_nome" "text", "valor_total" numeric, "modelo" "text", "nfe_status" "text", "nfse_status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_empresa_ids uuid[];
begin
  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado';
  end if;

  if p_tenant_id is null
     or p_empresa_ids is null
     or cardinality(p_empresa_ids) = 0
     or p_data_inicio is null
     or p_data_fim_exclusiva is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_id, empresas e periodo sao obrigatorios';
  end if;

  if public.current_tenant_id() is distinct from p_tenant_id then
    raise exception using
      errcode = '42501',
      message = 'Tenant informado nao corresponde ao contexto ativo';
  end if;

  if p_data_fim_exclusiva <= p_data_inicio
     or p_data_fim_exclusiva > (p_data_inicio + interval '20 years')::date then
    raise exception using
      errcode = '22023',
      message = 'Periodo invalido para o analitico de faturamento';
  end if;

  select array_agg(distinct requested.empresa_id order by requested.empresa_id)
    into v_empresa_ids
  from unnest(p_empresa_ids) as requested(empresa_id)
  where requested.empresa_id is not null;

  if v_empresa_ids is null or cardinality(v_empresa_ids) = 0 then
    raise exception using
      errcode = '22023',
      message = 'Informe ao menos uma empresa valida';
  end if;

  if exists (
    select 1
    from unnest(v_empresa_ids) as requested(empresa_id)
    left join c.empresa empresa
      on empresa.id = requested.empresa_id
     and empresa.tenant_id = p_tenant_id
     and empresa.deleted_at is null
    where empresa.id is null
       or not f.has_finance_access(p_tenant_id, requested.empresa_id)
  ) then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para uma ou mais empresas solicitadas';
  end if;

  return query
  select
    documento.id,
    documento.emissao_date,
    documento.competencia_date,
    documento.empresa_id,
    documento.cliente_id,
    cliente.nome::text as cliente_nome,
    documento.valor_total::numeric,
    documento.modelo,
    documento.nfe_status,
    documento.nfse_status,
    documento.created_at
  from f.documento_fiscal documento
  left join public.clientes cliente
    on cliente.id = documento.cliente_id
   and cliente.tenant_id = documento.tenant_id
  where documento.tenant_id = p_tenant_id
    and documento.empresa_id = any(v_empresa_ids)
    and documento.operacao = 'SAIDA'
    and documento.deleted_at is null
    and documento.emissao_date >= p_data_inicio
    and documento.emissao_date < p_data_fim_exclusiva
    and not exists (
      select 1
      from public.empresas empresa_destino
      where empresa_destino.tenant_id = documento.tenant_id
        and empresa_destino.id <> documento.empresa_id
        and regexp_replace(coalesce(empresa_destino.cnpj, ''), '[^0-9]', '', 'g') <> ''
        and regexp_replace(coalesce(empresa_destino.cnpj, ''), '[^0-9]', '', 'g') =
            regexp_replace(coalesce(cliente.documento_norm, cliente.documento, ''), '[^0-9]', '', 'g')
    )
  order by documento.emissao_date, documento.created_at, documento.id;
end;
$$;


ALTER FUNCTION "f"."faturamento_analitico_documentos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim_exclusiva" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."faturamento_analitico_documentos"("p_tenant_id" "uuid", "p_empresa_ids" "uuid"[], "p_data_inicio" "date", "p_data_fim_exclusiva" "date") IS 'Retorna faturamento externo das empresas autorizadas, excluindo documentos destinados a outra empresa do mesmo tenant.';



CREATE OR REPLACE FUNCTION "f"."fn_aplicar_credito_fiscal_manual_titulo"("p_titulo_id" "uuid", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("status" "text", "message" "text", "lancamentos_gerados" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_generated integer := 0;
  v_base numeric(15,2);
  v_imp text;
  v_rule record;
  v_comp_base date;
  v_parcelas integer;
  v_i integer;
  v_valor_total numeric(15,2);
  v_valor_parcela numeric(15,2);
  v_valor_last numeric(15,2);
  v_comp date;
begin
  select * into v_titulo
  from f.titulo
  where id = p_titulo_id;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if v_titulo.deleted_at is not null then
    update f.credito_fiscal_manual_lancamento
       set status = 'CANCELADO',
           deleted_at = now(),
           updated_at = now(),
           updated_by = a.fn_current_usuario_id()
     where tenant_id = v_titulo.tenant_id
       and titulo_id = v_titulo.id
       and deleted_at is null;

    status := 'ok';
    message := 'Titulo removido: lancamentos fiscais manuais cancelados.';
    lancamentos_gerados := 0;
    return next;
    return;
  end if;

  if auth.uid() is not null then
    if public.current_tenant_id() is distinct from v_titulo.tenant_id then
      raise exception 'Tenant mismatch';
    end if;
    if public.current_empresa_id() is distinct from v_titulo.empresa_id then
      raise exception 'Empresa mismatch';
    end if;
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  -- Apenas AP manual sem documento fiscal (cenario energia/leasing/boletos)
  if v_titulo.tipo <> 'AP' or upper(coalesce(v_titulo.origem,'')) <> 'MANUAL' or v_titulo.documento_fiscal_id is not null then
    update f.credito_fiscal_manual_lancamento
       set status = 'CANCELADO',
           deleted_at = now(),
           updated_at = now(),
           updated_by = a.fn_current_usuario_id()
     where tenant_id = v_titulo.tenant_id
       and titulo_id = v_titulo.id
       and deleted_at is null;

    status := 'ok';
    message := 'Titulo fora do escopo de credito fiscal manual.';
    lancamentos_gerados := 0;
    return next;
    return;
  end if;

  v_base := round(coalesce(v_titulo.valor_total,0),2);
  if v_base <= 0 then
    status := 'ok';
    message := 'Titulo sem base para credito.';
    lancamentos_gerados := 0;
    return next;
    return;
  end if;

  update f.credito_fiscal_manual_lancamento
     set status = 'CANCELADO',
         deleted_at = now(),
         updated_at = now(),
         updated_by = a.fn_current_usuario_id()
   where tenant_id = v_titulo.tenant_id
     and titulo_id = v_titulo.id
     and deleted_at is null;

  foreach v_imp in array array['ICMS','PIS','COFINS']
  loop
    select * into v_rule
    from f.fn_pick_credito_fiscal_manual_regra(
      v_titulo.tenant_id,
      v_titulo.empresa_id,
      v_imp,
      v_titulo.origem,
      v_titulo.descricao,
      v_titulo.motivo_compra_id,
      v_titulo.fornecedor_id
    )
    limit 1;

    if v_rule.modo is null then
      continue;
    end if;

    v_comp_base := coalesce(v_titulo.competencia_date, date_trunc('month', coalesce(v_titulo.emissao_date, current_date))::date);
    v_comp_base := (v_comp_base + make_interval(months => coalesce(v_rule.competencia_offset_meses,0)))::date;

    if v_rule.modo = 'NAO_CREDITA' then
      continue;
    end if;

    if v_rule.modo = 'PENDENTE_REVISAO' then
      insert into f.credito_fiscal_manual_lancamento(
        tenant_id, empresa_id, titulo_id, regra_id, imposto, natureza,
        competencia_date, base_calculo, aliquota, valor_credito, modo, status,
        created_by, updated_by
      ) values (
        v_titulo.tenant_id, v_titulo.empresa_id, v_titulo.id, v_rule.regra_id, v_imp, 'CREDITO',
        v_comp_base, v_base, coalesce(v_rule.aliquota,0), round(v_base * coalesce(v_rule.aliquota,0) / 100, 2), v_rule.modo, 'PENDENTE_REVISAO',
        a.fn_current_usuario_id(), a.fn_current_usuario_id()
      )
      on conflict do nothing;
      continue;
    end if;

    v_valor_total := round(v_base * coalesce(v_rule.aliquota,0) / 100, 2);
    if v_valor_total <= 0 then
      continue;
    end if;

    v_parcelas := case when v_rule.modo = 'CREDITA_PARCELADO' then greatest(1, coalesce(v_rule.parcelas_apropriacao,1)) else 1 end;

    if v_parcelas = 1 then
      insert into f.credito_fiscal_manual_lancamento(
        tenant_id, empresa_id, titulo_id, regra_id, imposto, natureza,
        competencia_date, base_calculo, aliquota, valor_credito, modo, status,
        created_by, updated_by
      ) values (
        v_titulo.tenant_id, v_titulo.empresa_id, v_titulo.id, v_rule.regra_id, v_imp, 'CREDITO',
        v_comp_base, v_base, coalesce(v_rule.aliquota,0), v_valor_total, v_rule.modo, 'PROVISIONADO',
        a.fn_current_usuario_id(), a.fn_current_usuario_id()
      )
      on conflict do nothing;
      v_generated := v_generated + 1;
    else
      v_valor_parcela := round(v_valor_total / v_parcelas, 2);
      v_valor_last := v_valor_total - (v_valor_parcela * (v_parcelas - 1));

      for v_i in 0..(v_parcelas - 1)
      loop
        v_comp := (v_comp_base + make_interval(months => v_i))::date;

        insert into f.credito_fiscal_manual_lancamento(
          tenant_id, empresa_id, titulo_id, regra_id, imposto, natureza,
          competencia_date, base_calculo, aliquota, valor_credito, modo, status,
          created_by, updated_by
        ) values (
          v_titulo.tenant_id, v_titulo.empresa_id, v_titulo.id, v_rule.regra_id, v_imp, 'CREDITO',
          v_comp,
          case when v_i = v_parcelas - 1 then v_base - (round(v_base / v_parcelas, 2) * (v_parcelas - 1)) else round(v_base / v_parcelas, 2) end,
          coalesce(v_rule.aliquota,0),
          case when v_i = v_parcelas - 1 then v_valor_last else v_valor_parcela end,
          v_rule.modo,
          'PROVISIONADO',
          a.fn_current_usuario_id(), a.fn_current_usuario_id()
        )
        on conflict do nothing;

        v_generated := v_generated + 1;
      end loop;
    end if;
  end loop;

  status := 'ok';
  message := coalesce(p_change_reason, 'Credito fiscal manual reaplicado ao titulo.');
  lancamentos_gerados := v_generated;
  return next;
end;
$$;


ALTER FUNCTION "f"."fn_aplicar_credito_fiscal_manual_titulo"("p_titulo_id" "uuid", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_arrendamento_gerar_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_contrato_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'f', 'a'
    AS $$
declare
  v_c f.arrendamento_contrato%rowtype;
  v_motivo_id uuid;
  v_plano_id uuid;
  v_titulo_id uuid;
  v_aprovado_por uuid;
  r record;
begin
  select *
    into v_c
    from f.arrendamento_contrato c
   where c.tenant_id = p_tenant_id
     and c.empresa_id = p_empresa_id
     and c.id = p_contrato_id
     and c.deleted_at is null;

  if not found then
    raise exception 'Contrato de arrendamento não encontrado (%).', p_contrato_id;
  end if;

  -- tenta pegar usuário logado (app)
  v_aprovado_por := a.fn_current_usuario_id();

  -- fallback (SQL editor): pega QUALQUER usuário do tenant via a.usuario_tenant
  if v_aprovado_por is null then
    select ut.usuario_id
      into v_aprovado_por
      from a.usuario_tenant ut
     where ut.tenant_id = p_tenant_id
       and ut.ativo = true
       and ut.deleted_at is null
     order by ut.created_at nulls last
     limit 1;

    if v_aprovado_por is null then
      raise exception
        'Nao foi possivel determinar aprovado_por (sem usuário autenticado e sem usuario_tenant ativo). Execute pelo app.';
    end if;
  end if;

  -- garante parcelas
  perform f.fn_arrendamento_gerar_parcelas(p_tenant_id, p_empresa_id, p_contrato_id);

  -- motivo padrão: OPEX_ARRENDAMENTO (se contrato não tiver)
  select coalesce(v_c.motivo_compra_id, mc.id)
    into v_motivo_id
    from f.motivo_compra mc
   where mc.tenant_id = p_tenant_id
     and mc.codigo = 'OPEX_ARRENDAMENTO'
     and mc.deleted_at is null
   limit 1;

  if v_motivo_id is null then
    raise exception 'Motivo OPEX_ARRENDAMENTO não encontrado no tenant %.', p_tenant_id;
  end if;

  select plano_contas_id
    into v_plano_id
    from f.motivo_compra
   where id = v_motivo_id
     and deleted_at is null;

  for r in
    select ap.*
      from f.arrendamento_parcela ap
     where ap.tenant_id = p_tenant_id
       and ap.empresa_id = p_empresa_id
       and ap.contrato_id = p_contrato_id
       and ap.deleted_at is null
       and ap.titulo_id is null
     order by ap.competencia_date
  loop
    insert into f.titulo (
      tenant_id, empresa_id, tipo, status, origem,
      fornecedor_id,
      descricao,
      emissao_date,
      competencia_date,
      valor_total,
      valor_aberto,
      motivo_compra_id,
      arrendamento_contrato_id
    )
    values (
      p_tenant_id, p_empresa_id,
      'AP', 'PENDENTE', 'ARRENDAMENTO',
      v_c.fornecedor_id,
      ('ARRENDAMENTO/LEASING - ' || v_c.descricao || ' - ' || to_char(r.competencia_date, 'YYYY-MM')),
      r.competencia_date,
      r.competencia_date,
      r.valor,
      r.valor,
      v_motivo_id,
      p_contrato_id
    )
    returning id into v_titulo_id;

    insert into f.titulo_parcela (
      tenant_id, titulo_id, numero, vencimento_date, valor, valor_aberto
    )
    values (
      p_tenant_id, v_titulo_id, '1/1', r.vencimento_date, r.valor, r.valor
    );

    insert into f.titulo_aprovacao (
      tenant_id, titulo_id, motivo_compra_id, motivo_outros_text, os_id,
      aprovado_em, aprovado_por
    )
    values (
      p_tenant_id, v_titulo_id, v_motivo_id, null, v_c.os_id,
      now(), v_aprovado_por
    );

    -- ✅ FIX anti-duplicação:
    -- Só cria rateio se ainda não existir nenhum rateio ativo para o título.
    if v_plano_id is not null then
      if not exists (
        select 1
          from f.titulo_rateio tr
         where tr.tenant_id = p_tenant_id
           and tr.titulo_id = v_titulo_id
           and tr.deleted_at is null
      ) then
        insert into f.titulo_rateio (
          tenant_id, titulo_id, plano_contas_id, centro_custo_id, os_id, percentual, valor
        )
        values (
          p_tenant_id, v_titulo_id, v_plano_id, v_c.centro_custo_id, v_c.os_id, 100::numeric(7,4), r.valor
        );
      end if;
    end if;

    update f.arrendamento_parcela
       set titulo_id = v_titulo_id,
           updated_at = now()
     where id = r.id;
  end loop;

end;
$$;


ALTER FUNCTION "f"."fn_arrendamento_gerar_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_contrato_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_arrendamento_gerar_parcelas"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_contrato_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'f'
    AS $$
declare
  v_c f.arrendamento_contrato%rowtype;
  i integer;
  v_comp date;
  v_venc date;
  v_last_day date;
begin
  select *
    into v_c
    from f.arrendamento_contrato c
   where c.tenant_id = p_tenant_id
     and c.empresa_id = p_empresa_id
     and c.id = p_contrato_id
     and c.deleted_at is null;

  if not found then
    raise exception 'Contrato de arrendamento não encontrado (%).', p_contrato_id;
  end if;

  if extract(day from v_c.competencia_inicio) <> 1 then
    raise exception 'competencia_inicio deve ser dia 01 (recebido: %).', v_c.competencia_inicio;
  end if;

  for i in 1..v_c.prazo_meses loop
    v_comp := (v_c.competencia_inicio + ((i-1) || ' months')::interval)::date;

    -- vencimento: dia fixo limitado ao último dia do mês
    v_last_day := (date_trunc('month', v_comp)::date + interval '1 month - 1 day')::date;
    v_venc := make_date(extract(year from v_comp)::int, extract(month from v_comp)::int, 1);
    v_venc := (v_venc + (least(v_c.dia_vencimento, extract(day from v_last_day)::int) - 1))::date;

    insert into f.arrendamento_parcela (
      tenant_id, empresa_id, contrato_id,
      competencia_date, numero, vencimento_date, valor
    )
    values (
      p_tenant_id, p_empresa_id, p_contrato_id,
      v_comp, i, v_venc, v_c.valor_parcela
    )
    on conflict (tenant_id, contrato_id, competencia_date)
    where deleted_at is null
    do update set
      numero = excluded.numero,
      vencimento_date = excluded.vencimento_date,
      valor = excluded.valor,
      updated_at = now(),
      deleted_at = null;
  end loop;

  update f.arrendamento_contrato
     set updated_at = now()
   where tenant_id = p_tenant_id
     and empresa_id = p_empresa_id
     and id = p_contrato_id;

end;
$$;


ALTER FUNCTION "f"."fn_arrendamento_gerar_parcelas"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_contrato_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_backfill_irpj_csll_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("competencia_date" "date", "status" "text", "detalhe" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'f', 'r'
    AS $$
declare
  d record;
begin
  for d in
    select distinct a.competencia_date
    from r.r_apuracao_irpj_csll_mensal_comp2 a
    where a.tenant_id = p_tenant_id
      and a.empresa_id = p_empresa_id
      and a.competencia_date between p_from and p_to
    order by a.competencia_date
  loop
    begin
      perform f.fn_irpj_csll_ao_fechar_competencia(p_tenant_id, p_empresa_id, d.competencia_date);
      competencia_date := d.competencia_date;
      status := 'OK';
      detalhe := null;
      return next;
    exception when others then
      competencia_date := d.competencia_date;
      status := 'ERRO';
      detalhe := sqlerrm;
      return next;
    end;
  end loop;
end;
$$;


ALTER FUNCTION "f"."fn_backfill_irpj_csll_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_calc_vencimento"("p_tenant_id" "uuid", "p_regra_id" "uuid", "p_competencia_date" "date") RETURNS "date"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
declare
  r record;
  v_last_next date;
  v_due date;
begin
  -- último dia do mês seguinte (fallback)
  v_last_next := (date_trunc('month', p_competencia_date)::date + interval '2 months - 1 day')::date;

  if p_regra_id is null then
    return v_last_next;
  end if;

  select vr.tipo, vr.dia
    into r
  from f.vencimento_regra vr
  where vr.tenant_id = p_tenant_id
    and vr.id = p_regra_id
    and vr.ativo = true
    and vr.deleted_at is null
  limit 1;

  if not found then
    return v_last_next;
  end if;

  if r.tipo = 'M1_ULTIMO_DIA' then
    return v_last_next;
  end if;

  if r.tipo = 'M1_DIA_FIXO' then
    -- dia fixo no mês seguinte, com "clamp" para o último dia do mês
    v_due := make_date(
      extract(year from v_last_next)::int,
      extract(month from v_last_next)::int,
      least(r.dia::int, extract(day from v_last_next)::int)
    );
    return v_due;
  end if;

  return v_last_next;
end;
$$;


ALTER FUNCTION "f"."fn_calc_vencimento"("p_tenant_id" "uuid", "p_regra_id" "uuid", "p_competencia_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_calcular_exposicao_os_unscoped"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_id" integer) RETURNS TABLE("valor" numeric, "origem" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_orcamento numeric;
  v_hh numeric := 0;
  v_materiais numeric := 0;
  v_margem numeric := 53;
begin
  if not exists (
    select 1 from public.ordens_servico os
    where os.id = p_os_id
      and os.tenant_id = p_tenant_id
      and os.empresa_id = p_empresa_id
  ) then
    return query select 0::numeric, 'CALCULADO'::text;
    return;
  end if;

  select coalesce(nullif(o.valor_fechado, 0), nullif(o.total_liquido, 0))
    into v_orcamento
  from m.orcamento o
  where o.tenant_id = p_tenant_id
    and o.empresa_id = p_empresa_id
    and o.os_id = p_os_id
    and o.deleted_at is null
  order by o.updated_at desc nulls last, o.created_at desc
  limit 1;

  if coalesce(v_orcamento, 0) > 0 then
    return query select round(v_orcamento, 2), 'ORCAMENTO'::text;
    return;
  end if;

  select coalesce(c.margem_lucro_padrao_percent, 53)
    into v_margem
  from a.config_orcamento c
  where c.tenant_id = p_tenant_id
    and c.empresa_id = p_empresa_id
    and c.deleted_at is null
  order by c.updated_at desc nulls last, c.created_at desc
  limit 1;

  select coalesce(v.total_hh, 0)
    into v_hh
  from public.vw_hh_total_os v
  where v.tenant_id = p_tenant_id
    and v.empresa_id = p_empresa_id
    and v.os_id = p_os_id;

  select coalesce(sum(
           oi.quantidade * public.fn_preco_venda_item_valores(
             i.custo_ultima_compra,
             i.preco_unitario,
             i.aliquota_ipi,
             coalesce(v_margem, 53)
           )
         ), 0)
    into v_materiais
  from public.os_itens oi
  join public.itens i
    on i.id = oi.item_id
   and i.tenant_id = oi.tenant_id
   and i.empresa_id = oi.empresa_id
  where oi.tenant_id = p_tenant_id
    and oi.empresa_id = p_empresa_id
    and oi.os_id = p_os_id;

  return query select round(coalesce(v_hh, 0) + coalesce(v_materiais, 0), 2), 'CALCULADO'::text;
end;
$$;


ALTER FUNCTION "f"."fn_calcular_exposicao_os_unscoped"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_documento_fiscal__sync_xml_pendencia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
declare
  v_xml_ok boolean;
begin
  -- ignora soft delete
  if new.deleted_at is not null then
    return new;
  end if;

  -- só NF-e: chave 44 e natureza PRODUTO (ajuste se quiser cobrir outros casos)
  if new.natureza <> 'PRODUTO' then
    return new;
  end if;

  if length(new.chave_acesso) <> 44 then
    return new;
  end if;

  select (
    exists (
      select 1
      from f.documento_fiscal_xml dfx
      where dfx.tenant_id = new.tenant_id
        and dfx.documento_fiscal_id = new.id
        and dfx.deleted_at is null
        and nullif(btrim(dfx.xml_raw), '') is not null
    )
    or
    exists (
      select 1
      from public.nf_entrada ne
      where ne.tenant_id = new.tenant_id
        and ne.id = new.source_nf_entrada_id
        and nullif(btrim(ne.xml_raw), '') is not null
    )
  ) into v_xml_ok;

  if not v_xml_ok then
    insert into f.documento_fiscal_pendencia (
      tenant_id, empresa_id, documento_fiscal_id, tipo, detalhe
    ) values (
      new.tenant_id, new.empresa_id, new.id, 'XML_FALTANDO',
      'Documento fiscal NF-e (chave 44) sem XML em nf_entrada.xml_raw e sem backup em f.documento_fiscal_xml.'
    )
    on conflict on constraint uq_doc_pend
    do update set
      detalhe = excluded.detalhe,
      updated_at = now(),
      resolved_at = null;
  else
    update f.documento_fiscal_pendencia
    set resolved_at = now(),
        updated_at = now()
    where tenant_id = new.tenant_id
      and documento_fiscal_id = new.id
      and tipo = 'XML_FALTANDO'
      and resolved_at is null;
  end if;

  return new;
end $$;


ALTER FUNCTION "f"."fn_documento_fiscal__sync_xml_pendencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_ensure_documento_fiscal_from_nf_entrada"("p_nf_entrada_id" bigint) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'extensions'
    AS $$
declare
  v_nf public.nf_entrada%rowtype;
  v_df_id uuid;
  v_emissao_date date;
  v_competencia date;
  v_xml_hash text;
begin
  select *
    into v_nf
  from public.nf_entrada
  where id = p_nf_entrada_id;

  if not found then
    raise exception 'nf_entrada não encontrada: %', p_nf_entrada_id;
  end if;

  -- 1) Se já existe DF por source_nf_entrada_id, retorna
  select df.id
    into v_df_id
  from f.documento_fiscal df
  where df.tenant_id = v_nf.tenant_id
    and df.empresa_id = v_nf.empresa_id
    and df.source_nf_entrada_id = v_nf.id
    and df.deleted_at is null
  order by df.created_at desc
  limit 1;

  -- 2) Se não achou, tenta por chave_acesso (e cola o source_nf_entrada_id)
  if v_df_id is null then
    select df.id
      into v_df_id
    from f.documento_fiscal df
    where df.tenant_id = v_nf.tenant_id
      and df.empresa_id = v_nf.empresa_id
      and df.chave_acesso = v_nf.chave
      and df.deleted_at is null
    order by df.created_at desc
    limit 1;

    if v_df_id is not null then
      update f.documento_fiscal
         set source_nf_entrada_id = v_nf.id,
             updated_at = now(),
             updated_by = a.fn_current_usuario_id()
       where id = v_df_id
         and source_nf_entrada_id is null;
    end if;
  end if;

  -- 3) Se ainda não achou, cria DF mínimo
  if v_df_id is null then
    v_emissao_date := (v_nf.data_emissao at time zone 'America/Sao_Paulo')::date;
    if v_emissao_date is null then
      v_emissao_date := (now() at time zone 'America/Sao_Paulo')::date;
    end if;

    v_competencia := date_trunc('month', v_emissao_date)::date;

    insert into f.documento_fiscal (
      id,
      tenant_id,
      empresa_id,
      modelo,
      serie,
      numero,
      chave_acesso,
      emissao_date,
      competencia_date,
      valor_total,
      operacao,
      natureza,
      source_nf_entrada_id,
      created_at,
      updated_at,
      created_by,
      updated_by
    ) values (
      gen_random_uuid(),
      v_nf.tenant_id,
      v_nf.empresa_id,
      null,
      v_nf.serie,
      v_nf.numero,
      v_nf.chave,
      v_emissao_date,
      v_competencia,
      coalesce(v_nf.valor_total, 0),
      'ENTRADA',
      'PRODUTO',
      v_nf.id,
      now(),
      now(),
      a.fn_current_usuario_id(),
      a.fn_current_usuario_id()
    )
    returning id into v_df_id;
  end if;

  -- 4) ✅ GARANTIR documento_fiscal_xml se xml_raw existir e não estiver vazio
  if v_nf.xml_raw is not null and nullif(btrim(v_nf.xml_raw), '') is not null then
    begin
      -- tenta extensions.digest (se existir no seu ambiente)
      v_xml_hash := encode(extensions.digest(convert_to(v_nf.xml_raw, 'utf8'), 'sha256'), 'hex');
    exception when others then
      v_xml_hash := null;
    end;

    insert into f.documento_fiscal_xml (
      tenant_id, documento_fiscal_id, chave_acesso, xml_raw, xml_hash
    ) values (
      v_nf.tenant_id, v_df_id, v_nf.chave, v_nf.xml_raw, v_xml_hash
    )
    on conflict (tenant_id, documento_fiscal_id)
    do update set
      chave_acesso = excluded.chave_acesso,
      xml_raw = excluded.xml_raw,
      xml_hash = excluded.xml_hash;
  end if;

  return v_df_id;
end;
$$;


ALTER FUNCTION "f"."fn_ensure_documento_fiscal_from_nf_entrada"("p_nf_entrada_id" bigint) OWNER TO "postgres";


