    g.empresa_id,
    g.competencia_date,
    g.documento_fiscal_id,
    g.nf_entrada_id,
    g.chave_acesso,
    g.operacao,
    g.tipo,
    g.imposto,
    g.natureza_esperada,
    g.esperado,
    g.encontrado,
    g.diff,
    g.detalhe
  from r.r_guardiao_impostos_docs g
  where g.tenant_id = p_tenant_id
    and g.empresa_id = p_empresa_id
