    if coalesce(v_rateio_count, 0) = 0 then
      insert into f.titulo_rateio (tenant_id, titulo_id, plano_contas_id, os_id, percentual, valor)
      values (v_df.tenant_id, v_titulo_id, v_plano_contas_id, v_df.os_id_import, 100.0000, v_valor);
    elsif v_rateio_count = 1 then
      update f.titulo_rateio
      set
        percentual = 100.0000,
        valor = v_valor,
        plano_contas_id = v_plano_contas_id,
        os_id = v_df.os_id_import
      where titulo_id = v_titulo_id
        and tenant_id = v_df.tenant_id
        and deleted_at is null;
    else
      update f.titulo_rateio
      set valor = case
        when percentual is not null
          then round(v_valor * percentual / 100.0, 2)
        when valor is not null
             and coalesce(p_old_valor_total, 0) > 0
          then round(v_valor * valor / p_old_valor_total, 2)
        else valor
      end
      where titulo_id = v_titulo_id
        and tenant_id = v_df.tenant_id
        and deleted_at is null;
    end if;
  end if;

  return v_titulo_id;
end;
$$;


ALTER FUNCTION "f"."fn_upsert_ar_from_nfe_venda"("p_documento_fiscal_id" "uuid", "p_old_valor_total" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_validar_pos_importacao"("p_documento_fiscal_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
declare
  v_xml int;
  v_itens int;
  v_impostos int;
  v_cp int;
begin
  select count(*) into v_xml
  from f.documento_fiscal_xml
  where documento_fiscal_id = p_documento_fiscal_id;

  select count(*) into v_itens
  from f.documento_fiscal_item
  where documento_fiscal_id = p_documento_fiscal_id;

  select count(*) into v_impostos
  from f.documento_fiscal_imposto
  where documento_fiscal_id = p_documento_fiscal_id;

  select count(*) into v_cp
  from public.contas_pagar_titulos
  where documento_fiscal_id = p_documento_fiscal_id;

  if v_xml = 0 then
    raise exception 'IMPORT INCOMPLETA: sem XML (documento_fiscal_xml) para documento_fiscal_id=%', p_documento_fiscal_id;
  end if;

  -- se você considera obrigatório sempre ter item fiscal quando tem XML:
  if v_itens = 0 then
    raise exception 'IMPORT INCOMPLETA: sem itens fiscais (documento_fiscal_item) para documento_fiscal_id=%', p_documento_fiscal_id;
  end if;

  -- se impostos forem obrigatórios no seu fluxo:
  -- if v_impostos = 0 then
  --   raise exception 'IMPORT INCOMPLETA: sem impostos (documento_fiscal_imposto) para documento_fiscal_id=%', p_documento_fiscal_id;
  -- end if;

  if v_cp = 0 then
    raise exception 'IMPORT INCOMPLETA: sem contas a pagar (contas_pagar_titulos) para documento_fiscal_id=%', p_documento_fiscal_id;
  end if;
end;
$$;


ALTER FUNCTION "f"."fn_validar_pos_importacao"("p_documento_fiscal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_ao_documento_fiscal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if new.operacao = 'SAIDA'
     and new.os_id_import is not null
     and new.deleted_at is null
     and coalesce(new.nfe_status, new.nfse_status, 'EMITIDA') = 'EMITIDA' then
    update f.gestao_cobranca_os g
       set status = case when g.status in ('RECEBIDO','CANCELADO') then g.status else 'FATURADO' end,
           documento_fiscal_id = new.id,
           faturado_em = coalesce(new.emissao_date, current_date),
           valor_confirmado = case when new.valor_total > 0 then new.valor_total else g.valor_confirmado end,
           valor_origem = case when new.valor_total > 0 then 'DOCUMENTO' else g.valor_origem end,
           updated_at = now()
     where g.tenant_id = new.tenant_id
       and g.empresa_id = new.empresa_id
       and g.os_id = new.os_id_import
       and g.deleted_at is null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_ao_documento_fiscal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_ao_titulo_ar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if new.tipo = 'AR' and new.deleted_at is null then
    update f.gestao_cobranca_os g
       set status = case
             when new.status = 'PAGO' or new.valor_aberto <= 0 then 'RECEBIDO'
             when g.status not in ('RECEBIDO','CANCELADO') then 'FATURADO'
             else g.status
           end,
           titulo_ar_id = new.id,
           updated_at = now()
     where g.tenant_id = new.tenant_id
       and g.empresa_id = new.empresa_id
       and g.deleted_at is null
       and (
         g.os_id = new.os_id
         or g.documento_fiscal_id = new.documento_fiscal_id
       );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_ao_titulo_ar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_atualizar"("p_credito_id" "uuid", "p_proximo_contato" "date" DEFAULT NULL::"date", "p_observacao" "text" DEFAULT NULL::"text", "p_responsavel_cliente_nome" "text" DEFAULT NULL::"text", "p_valor_confirmado" numeric DEFAULT NULL::numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare v_gc f.gestao_cobranca_os%rowtype;
begin
  select * into v_gc from f.gestao_cobranca_os g
  where g.id=p_credito_id and g.tenant_id=public.current_tenant_id()
    and g.empresa_id=public.current_empresa_id() and g.deleted_at is null;
  if not found or not f.has_cobranca_access(v_gc.tenant_id,v_gc.empresa_id) then
    raise exception 'venda_credito_nao_encontrada_ou_sem_acesso';
  end if;
  if p_valor_confirmado is not null and p_valor_confirmado < 0 then raise exception 'valor_invalido'; end if;

  update f.gestao_cobranca_os set
    proximo_contato_date=p_proximo_contato,
    observacao=nullif(btrim(p_observacao),''),
    responsavel_cliente_nome=nullif(btrim(p_responsavel_cliente_nome),''),
    valor_confirmado=p_valor_confirmado,
    valor_origem=case when p_valor_confirmado is not null then 'CONFIRMADO' else valor_origem end,
    updated_at=now(), updated_by=a.fn_current_usuario_id()
  where id=v_gc.id;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_atualizar"("p_credito_id" "uuid", "p_proximo_contato" "date", "p_observacao" "text", "p_responsavel_cliente_nome" "text", "p_valor_confirmado" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_cancelar"("p_credito_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare v_gc f.gestao_cobranca_os%rowtype;
begin
  select * into v_gc from f.gestao_cobranca_os g
  where g.id=p_credito_id and g.tenant_id=public.current_tenant_id()
    and g.empresa_id=public.current_empresa_id() and g.deleted_at is null;
  if not found or not f.has_cobranca_access(v_gc.tenant_id,v_gc.empresa_id) then
    raise exception 'venda_credito_nao_encontrada_ou_sem_acesso';
  end if;
  update f.gestao_cobranca_os set status='CANCELADO',updated_at=now(),updated_by=a.fn_current_usuario_id()
  where id=v_gc.id;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_cancelar"("p_credito_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_criar_avulso"("p_cliente_id" integer, "p_unidade_id" bigint, "p_descricao" "text", "p_valor" numeric, "p_data_competencia" "date", "p_origem" "text" DEFAULT 'AVULSO_LEGADO'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare v_tenant uuid:=public.current_tenant_id(); v_empresa uuid:=public.current_empresa_id(); v_id uuid;
begin
  if not f.has_cobranca_access(v_tenant,v_empresa) then raise exception 'venda_credito_sem_acesso'; end if;
  if p_origem not in ('AVULSO_LEGADO','IMPORTACAO_CSV','OUTRO') then raise exception 'origem_avulsa_invalida'; end if;
  if p_valor is null or p_valor < 0 then raise exception 'valor_invalido'; end if;
  if nullif(btrim(p_descricao),'') is null then raise exception 'descricao_obrigatoria'; end if;
  if not exists (select 1 from public.clientes c where c.id=p_cliente_id and c.tenant_id=v_tenant and c.empresa_id=v_empresa) then
    raise exception 'cliente_invalido';
  end if;
  if p_unidade_id is not null and not exists (
    select 1 from public.cliente_unidades u where u.id=p_unidade_id and u.cliente_id=p_cliente_id
      and u.tenant_id=v_tenant and u.empresa_id=v_empresa
  ) then raise exception 'unidade_invalida'; end if;

  insert into f.gestao_cobranca_os(
    tenant_id,empresa_id,os_id,cliente_id,unidade_id,status,origem,descricao,
    valor_estimado,valor_confirmado,valor_origem,valor_calculado_em,data_competencia
  ) values (
    v_tenant,v_empresa,null,p_cliente_id,p_unidade_id,'ABERTO',p_origem,btrim(p_descricao),
    round(p_valor,2),round(p_valor,2),'MANUAL',now(),coalesce(p_data_competencia,current_date)
  ) returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_criar_avulso"("p_cliente_id" integer, "p_unidade_id" bigint, "p_descricao" "text", "p_valor" numeric, "p_data_competencia" "date", "p_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_encerrar"("p_credito_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare v_gc f.gestao_cobranca_os%rowtype; v_status text:=upper(coalesce(p_status,''));
begin
  if v_status not in ('PERDIDO','CANCELADO') then raise exception 'status_encerramento_invalido'; end if;
  select * into v_gc from f.gestao_cobranca_os g
  where g.id=p_credito_id and g.tenant_id=public.current_tenant_id()
    and g.empresa_id=public.current_empresa_id() and g.deleted_at is null;
  if not found or not f.has_cobranca_access(v_gc.tenant_id,v_gc.empresa_id) then
    raise exception 'venda_credito_nao_encontrada_ou_sem_acesso';
  end if;
  update f.gestao_cobranca_os set status=v_status,updated_at=now(),updated_by=a.fn_current_usuario_id()
  where id=v_gc.id;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_encerrar"("p_credito_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_excluir"("p_credito_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare v_gc f.gestao_cobranca_os%rowtype; v_papel text;
begin
  select * into v_gc from f.gestao_cobranca_os g
  where g.id=p_credito_id and g.tenant_id=public.current_tenant_id()
    and g.empresa_id=public.current_empresa_id() and g.deleted_at is null;
  if not found or not f.has_cobranca_access(v_gc.tenant_id,v_gc.empresa_id) then
    raise exception 'venda_credito_nao_encontrada_ou_sem_acesso';
  end if;
  v_papel := upper(coalesce(a.fn_current_empresa_papel(v_gc.tenant_id,v_gc.empresa_id),''));
  if v_papel not in ('OWNER','ADMIN','DIRETOR') then raise exception 'venda_credito_exclusao_sem_permissao'; end if;
  update f.gestao_cobranca_os set deleted_at=now(),updated_at=now(),updated_by=a.fn_current_usuario_id()
  where id=v_gc.id;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_excluir"("p_credito_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_preco_item_por_id"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_id" integer) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null
     or p_empresa_id is distinct from public.current_empresa_id__by_tenant(p_tenant_id)
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not f.has_cobranca_access(p_tenant_id, p_empresa_id) then
    raise exception 'venda_credito_preco_access_denied';
  end if;

  return public.fn_preco_venda_item_unscoped(p_tenant_id, p_empresa_id, p_item_id);
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_preco_item_por_id"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_recalcular"("p_credito_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_gc f.gestao_cobranca_os%rowtype;
  v_valor numeric;
  v_origem text;
begin
  select * into v_gc from f.gestao_cobranca_os g
  where g.id = p_credito_id
    and g.tenant_id = public.current_tenant_id()
    and g.empresa_id = public.current_empresa_id()
    and g.deleted_at is null;

  if not found or not f.has_cobranca_access(v_gc.tenant_id, v_gc.empresa_id) then
    raise exception 'venda_credito_nao_encontrada_ou_sem_acesso';
  end if;
  if v_gc.os_id is null then raise exception 'venda_credito_avulsa_nao_recalcula'; end if;

  select x.valor, x.origem into v_valor, v_origem
  from f.fn_calcular_exposicao_os_unscoped(v_gc.tenant_id, v_gc.empresa_id, v_gc.os_id) x;

  update f.gestao_cobranca_os
     set valor_estimado = coalesce(v_valor, 0),
         valor_origem = v_origem,
         valor_calculado_em = now(),
         updated_at = now(),
         updated_by = a.fn_current_usuario_id()
   where id = v_gc.id;
  return coalesce(v_valor, 0);
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_recalcular"("p_credito_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_registrar_oc"("p_credito_id" "uuid", "p_numero" "text", "p_data" "date" DEFAULT CURRENT_DATE, "p_valor_confirmado" numeric DEFAULT NULL::numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare v_gc f.gestao_cobranca_os%rowtype;
begin
  select * into v_gc from f.gestao_cobranca_os g
  where g.id=p_credito_id and g.tenant_id=public.current_tenant_id()
    and g.empresa_id=public.current_empresa_id() and g.deleted_at is null;
  if not found or not f.has_cobranca_access(v_gc.tenant_id,v_gc.empresa_id) then
    raise exception 'venda_credito_nao_encontrada_ou_sem_acesso';
  end if;
  if nullif(btrim(p_numero),'') is null then raise exception 'numero_oc_obrigatorio'; end if;
  if p_valor_confirmado is not null and p_valor_confirmado < 0 then raise exception 'valor_invalido'; end if;

  update f.gestao_cobranca_os set
    status=case when status='ABERTO' then 'OC_RECEBIDA' else status end,
    pedido_compra_cliente=btrim(p_numero), pedido_recebido_em=coalesce(p_data,current_date),
    valor_confirmado=coalesce(p_valor_confirmado,valor_confirmado),
    valor_origem=case when p_valor_confirmado is not null then 'CONFIRMADO' else valor_origem end,
    updated_at=now(), updated_by=a.fn_current_usuario_id()
  where id=v_gc.id;

  if v_gc.os_id is not null then
    update public.ordens_servico set pedido_compra=btrim(p_numero), atualizado_em=now()
    where id=v_gc.os_id and tenant_id=v_gc.tenant_id and empresa_id=v_gc.empresa_id;
  end if;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_registrar_oc"("p_credito_id" "uuid", "p_numero" "text", "p_data" "date", "p_valor_confirmado" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."fn_venda_credito_vincular_documento"("p_credito_id" "uuid", "p_documento_fiscal_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_gc f.gestao_cobranca_os%rowtype;
  v_df f.documento_fiscal%rowtype;
  v_titulo_id uuid;
  v_recebido boolean := false;
begin
  select * into v_gc from f.gestao_cobranca_os g
  where g.id=p_credito_id and g.tenant_id=public.current_tenant_id()
    and g.empresa_id=public.current_empresa_id() and g.deleted_at is null;
  if not found or not f.has_cobranca_access(v_gc.tenant_id,v_gc.empresa_id) then
    raise exception 'venda_credito_nao_encontrada_ou_sem_acesso';
  end if;

  select * into v_df from f.documento_fiscal d
  where d.id=p_documento_fiscal_id and d.tenant_id=v_gc.tenant_id
    and d.empresa_id=v_gc.empresa_id and d.operacao='SAIDA' and d.deleted_at is null;
  if not found then raise exception 'documento_fiscal_invalido'; end if;
  if v_gc.cliente_id is not null and v_df.cliente_id is distinct from v_gc.cliente_id then
    raise exception 'documento_fiscal_cliente_divergente';
  end if;

  select t.id, (t.status='PAGO' or t.valor_aberto<=0)
    into v_titulo_id, v_recebido
  from f.titulo t
  where t.tenant_id=v_gc.tenant_id and t.empresa_id=v_gc.empresa_id
    and t.documento_fiscal_id=v_df.id and t.tipo='AR' and t.deleted_at is null
  order by t.created_at desc limit 1;

  update f.gestao_cobranca_os set
    status=case when coalesce(v_recebido,false) then 'RECEBIDO' else 'FATURADO' end,
    documento_fiscal_id=v_df.id, titulo_ar_id=v_titulo_id,
    faturado_em=coalesce(v_df.emissao_date,current_date),
    valor_confirmado=case when v_df.valor_total>0 then v_df.valor_total else valor_confirmado end,
    valor_origem=case when v_df.valor_total>0 then 'DOCUMENTO' else valor_origem end,
    updated_at=now(), updated_by=a.fn_current_usuario_id()
  where id=v_gc.id;
end;
$$;


ALTER FUNCTION "f"."fn_venda_credito_vincular_documento"("p_credito_id" "uuid", "p_documento_fiscal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."garantir_rateio_fallback_titulo"("p_tenant_id" "uuid", "p_titulo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_motivo_id uuid;
  v_os_id integer;
  v_requires_os boolean := false;
  v_plano_id uuid;
  v_fallback_id uuid;
  v_quantidade integer;
begin
  select t.*
    into v_titulo
  from f.titulo t
  where t.id = p_titulo_id
    and t.tenant_id = p_tenant_id
  for update;

  if not found
     or v_titulo.deleted_at is not null
     or v_titulo.status = 'CANCELADO'
     or v_titulo.tipo <> 'AP'
  then
    return jsonb_build_object('status', 'TITULO_INELEGIVEL');
  end if;

  if exists (
    select 1
    from f.titulo_rateio tr
    where tr.tenant_id = p_tenant_id
      and tr.titulo_id = p_titulo_id
      and tr.deleted_at is null
      and tr.origem_rateio <> 'SISTEMA_FALLBACK'
  ) then
    return jsonb_build_object('status', 'RATEIO_PRESERVADO');
  end if;

  select ta.motivo_compra_id, ta.os_id
    into v_motivo_id, v_os_id
  from f.titulo_aprovacao ta
  where ta.tenant_id = p_tenant_id
    and ta.titulo_id = p_titulo_id
    and ta.deleted_at is null
  order by ta.aprovado_em desc, ta.id desc
  limit 1;

  if v_motivo_id is null then
    v_motivo_id := v_titulo.motivo_compra_id;
  end if;

  if v_motivo_id is not null then
    select mc.plano_contas_id, mc.requires_os
      into v_plano_id, v_requires_os
    from f.motivo_compra mc
    where mc.id = v_motivo_id
      and mc.tenant_id = p_tenant_id
      and mc.ativo
      and mc.deleted_at is null;

    if v_plano_id is not null
       and not exists (
         select 1
         from f.plano_contas pc
         where pc.id = v_plano_id
           and pc.tenant_id = p_tenant_id
           and pc.tipo = 'ANALITICA'
           and pc.ativo
           and pc.deleted_at is null
       )
    then
      v_plano_id := null;
    end if;
  end if;

  if v_requires_os and v_os_id is null then
    return jsonb_build_object(
      'status', 'OS_OBRIGATORIA_AUSENTE'
    );
  end if;

  if v_os_id is not null
     and not exists (
       select 1
       from public.ordens_servico os
       where os.id = v_os_id
         and os.tenant_id = p_tenant_id
         and os.empresa_id = v_titulo.empresa_id
     )
  then
    return jsonb_build_object('status', 'OS_INVALIDA');
  end if;

  if v_plano_id is null then
    select pc.id
      into v_plano_id
    from f.plano_contas pc
    where pc.tenant_id = p_tenant_id
      and pc.codigo = 'DESP_GERAL'
      and pc.tipo = 'ANALITICA'
      and pc.ativo
      and pc.deleted_at is null
    limit 1;
  end if;

  if v_plano_id is null then
    return jsonb_build_object('status', 'PLANO_FALLBACK_AUSENTE');
  end if;

  select count(*)::integer
    into v_quantidade
  from f.titulo_rateio tr
  where tr.tenant_id = p_tenant_id
    and tr.titulo_id = p_titulo_id
    and tr.deleted_at is null
    and tr.origem_rateio = 'SISTEMA_FALLBACK';

  if v_quantidade > 1 then
    return jsonb_build_object('status', 'FALLBACK_INCONSISTENTE');
  elsif v_quantidade = 1 then
    select tr.id
      into v_fallback_id
    from f.titulo_rateio tr
    where tr.tenant_id = p_tenant_id
      and tr.titulo_id = p_titulo_id
      and tr.deleted_at is null
      and tr.origem_rateio = 'SISTEMA_FALLBACK'
    limit 1;

    update f.titulo_rateio tr
    set
      plano_contas_id = v_plano_id,
      centro_custo_id = null,
      os_id = v_os_id,
      percentual = 100.0000,
      valor = coalesce(v_titulo.valor_total, 0),
      updated_at = now(),
      updated_by = a.fn_current_usuario_id()
    where tr.id = v_fallback_id
      and tr.tenant_id = p_tenant_id
      and tr.titulo_id = p_titulo_id;
  else
    insert into f.titulo_rateio (
      tenant_id,
      titulo_id,
      plano_contas_id,
      centro_custo_id,
      os_id,
      percentual,
      valor,
      origem_rateio
    )
    values (
      p_tenant_id,
      p_titulo_id,
      v_plano_id,
      null,
      v_os_id,
      100.0000,
      coalesce(v_titulo.valor_total, 0),
      'SISTEMA_FALLBACK'
    );
  end if;

  return jsonb_build_object(
    'status', 'FALLBACK_APLICADO',
    'plano_contas_id', v_plano_id
  );
end;
$$;


ALTER FUNCTION "f"."garantir_rateio_fallback_titulo"("p_tenant_id" "uuid", "p_titulo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."gerar_ap_pendente_por_nf_entrada"("p_nf_entrada_id" bigint, "p_force" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c', 'extensions'
    SET "row_security" TO 'off'
    AS $$
declare
  v_nf public.nf_entrada%rowtype;
  v_doc_id uuid;
  v_titulo_id uuid;
  v_competencia date;
  v_xml_hash text;
begin
  -- ✅ permite SQL Editor (postgres/service_role), mas mantém segurança no app
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select * into v_nf
  from public.nf_entrada
  where id = p_nf_entrada_id;

  if not found then
    raise exception 'NF entrada nao encontrada (id=%)', p_nf_entrada_id;
  end if;

  -- permissão: no app continua exigindo ADMIN/FINANCEIRO
  if auth.uid() is not null then
    if not f.has_finance_access(v_nf.tenant_id, v_nf.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  v_competencia := date_trunc(
    'month',
    coalesce((v_nf.data_emissao at time zone 'America/Sao_Paulo')::date, current_date)
  )::date;

  select df.id into v_doc_id
  from f.documento_fiscal df
  where df.tenant_id = v_nf.tenant_id
    and df.source_nf_entrada_id = v_nf.id
    and df.deleted_at is null
  limit 1;

  if v_doc_id is not null and not p_force then
    return v_doc_id;
  end if;

  insert into f.documento_fiscal (
    tenant_id, empresa_id, source_nf_entrada_id,
    fornecedor_id, chave_acesso,
    modelo, serie, numero,
    emissao_date, competencia_date,
    valor_total, valor_produtos, valor_frete, valor_seguro, valor_desconto, valor_outros,
    finalidade_import, os_id_import,
    pagamento_import_json
  )
  values (
    v_nf.tenant_id, v_nf.empresa_id, v_nf.id,
    v_nf.fornecedor_id::int, v_nf.chave,
    null, v_nf.serie, v_nf.numero,
    (v_nf.data_emissao at time zone 'America/Sao_Paulo')::date,
    v_competencia,
    coalesce(v_nf.valor_total, 0),
    coalesce(v_nf.valor_produtos, 0),
    coalesce(v_nf.valor_frete, 0),
    coalesce(v_nf.valor_seguro, 0),
    coalesce(v_nf.valor_desconto, 0),
    coalesce(v_nf.valor_outros, 0),
    v_nf.finalidade_contexto,
    v_nf.os_id,
    null
  )
  on conflict (tenant_id, source_nf_entrada_id)
  do update set
    empresa_id = excluded.empresa_id,
    fornecedor_id = excluded.fornecedor_id,
    chave_acesso = excluded.chave_acesso,
    serie = excluded.serie,
    numero = excluded.numero,
    emissao_date = excluded.emissao_date,
    competencia_date = excluded.competencia_date,
    valor_total = excluded.valor_total,
    valor_produtos = excluded.valor_produtos,
    valor_frete = excluded.valor_frete,
    valor_seguro = excluded.valor_seguro,
    valor_desconto = excluded.valor_desconto,
    valor_outros = excluded.valor_outros,
    finalidade_import = excluded.finalidade_import,
    os_id_import = excluded.os_id_import,
    updated_at = now(),
    updated_by = a.fn_current_usuario_id()
  returning id into v_doc_id;

  if v_nf.xml_raw is not null and length(v_nf.xml_raw) > 0 then
    v_xml_hash := encode(extensions.digest(convert_to(v_nf.xml_raw, 'utf8'), 'sha256'), 'hex');

    insert into f.documento_fiscal_xml (tenant_id, documento_fiscal_id, chave_acesso, xml_raw, xml_hash)
    values (v_nf.tenant_id, v_doc_id, v_nf.chave, v_nf.xml_raw, v_xml_hash)
    on conflict (tenant_id, documento_fiscal_id) do update set
      xml_raw = excluded.xml_raw,
      xml_hash = excluded.xml_hash;
  end if;

  select t.id into v_titulo_id
  from f.titulo t
  where t.tenant_id = v_nf.tenant_id
    and t.empresa_id = v_nf.empresa_id
    and t.documento_fiscal_id = v_doc_id
    and t.deleted_at is null
  limit 1;

  if v_titulo_id is null then
    insert into f.titulo (
      tenant_id, empresa_id,
      tipo, status, origem,
      fornecedor_id, documento_fiscal_id,
      descricao,
      emissao_date, competencia_date,
      valor_total, valor_aberto
    )
    values (
      v_nf.tenant_id, v_nf.empresa_id,
      'AP', 'PENDENTE', 'XML',
      v_nf.fornecedor_id::int, v_doc_id,
      ('NF-e ' || coalesce(v_nf.numero,'') || '/' || coalesce(v_nf.serie,'') || ' - ' || coalesce(v_nf.emitente_nome,'EMITENTE')),
      (v_nf.data_emissao at time zone 'America/Sao_Paulo')::date,
      v_competencia,
      coalesce(v_nf.valor_total, 0),
      coalesce(v_nf.valor_total, 0)
    )
    returning id into v_titulo_id;

    insert into f.titulo_parcela (
      tenant_id, titulo_id, numero, vencimento_date, valor, valor_aberto
    )
    values (
      v_nf.tenant_id,
      v_titulo_id,
      '001',
      (v_nf.data_emissao at time zone 'America/Sao_Paulo')::date,
      coalesce(v_nf.valor_total, 0),
      coalesce(v_nf.valor_total, 0)
    );
  end if;

  return v_doc_id;
end;
$$;


ALTER FUNCTION "f"."gerar_ap_pendente_por_nf_entrada"("p_nf_entrada_id" bigint, "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."gerar_ap_pendente_por_nf_entrada_v2"("p_nf_entrada_id" bigint, "p_force" boolean DEFAULT false, "p_parcelas_json" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c', 'extensions'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_nf public.nf_entrada%rowtype;
  v_doc_id uuid;
  v_titulo_id uuid;

  v_emissao_date date;
  v_competencia_date date;
  v_total numeric(15,2);

  v_xml_hash text;

  v_parcelas jsonb;
  v_soma numeric(15,2) := 0;

  v_i int := 0;
  v_el jsonb;
  v_num text;
  v_venc date;
  v_val numeric(15,2);

  v_has_titulo_deleted_at boolean := false;
  v_has_parcela_deleted_at boolean := false;

  v_sql text;
  v_has_parcelas boolean := false;
  v_valor_aberto numeric(15,2) := 0;
begin
  select *
    into v_nf
  from public.nf_entrada n
  where n.id = p_nf_entrada_id
  limit 1;

  if v_nf.id is null then
    raise exception 'NF entrada nao encontrada (id=%)', p_nf_entrada_id;
  end if;

  -- Permissao:
  -- permite FINANCEIRO/ADMIN, OU quem tem capability xml_import.execute (para importacao gerar AP).
  if auth.uid() is not null then
    if not f.has_finance_access(v_nf.tenant_id, v_nf.empresa_id)
       and not public.can('xml_import','execute', v_nf.tenant_id)
    then
      raise exception 'Sem permissao para gerar contas a pagar (precisa FINANCEIRO/ADMIN ou xml_import.execute)';
    end if;
  end if;

  if v_nf.motivo_compra_id is null then
    raise exception 'NF sem motivo_compra_id. Importacao deve informar Classificacao/Motivo.';
  end if;

  if v_nf.solicitante_usuario_id is null then
    raise exception 'NF sem solicitante_usuario_id. Importacao deve informar solicitante.';
  end if;

  v_emissao_date := (v_nf.data_emissao at time zone 'America/Sao_Paulo')::date;
  if v_emissao_date is null then
    v_emissao_date := (now() at time zone 'America/Sao_Paulo')::date;
  end if;

  v_competencia_date := date_trunc('month', v_emissao_date)::date;
  v_total := round(coalesce(v_nf.valor_total, 0), 2);

  -- Compat: algumas bases antigas nao tem deleted_at em f.titulo / f.titulo_parcela.
  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'f'
      and table_name = 'titulo'
      and column_name = 'deleted_at'
  ) into v_has_titulo_deleted_at;

  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'f'
      and table_name = 'titulo_parcela'
      and column_name = 'deleted_at'
  ) into v_has_parcela_deleted_at;

  -- Documento fiscal (upsert por tenant + source_nf_entrada_id)
  insert into f.documento_fiscal (
    tenant_id,
    empresa_id,
    source_nf_entrada_id,
    fornecedor_id,
    chave_acesso,
    modelo,
    serie,
    numero,
    emissao_date,
    competencia_date,
    valor_total,
    valor_produtos,
    valor_frete,
    valor_seguro,
    valor_desconto,
    valor_outros,
    finalidade_import,
    os_id_import,
    pagamento_import_json
  )
  values (
    v_nf.tenant_id,
    v_nf.empresa_id,
    v_nf.id,
    v_nf.fornecedor_id::int,
    v_nf.chave,
    v_nf.modelo,
    v_nf.serie,
    v_nf.numero,
    v_emissao_date,
    v_competencia_date,
    v_total,
    round(coalesce(v_nf.valor_produtos, 0), 2),
    round(coalesce(v_nf.valor_frete, 0), 2),
    round(coalesce(v_nf.valor_seguro, 0), 2),
    round(coalesce(v_nf.valor_desconto, 0), 2),
    round(coalesce(v_nf.valor_outros, 0), 2),
    v_nf.finalidade_contexto,
    v_nf.os_id,
    p_parcelas_json
  )
  on conflict (tenant_id, source_nf_entrada_id)
  do update set
    empresa_id = excluded.empresa_id,
    fornecedor_id = excluded.fornecedor_id,
    chave_acesso = excluded.chave_acesso,
    modelo = excluded.modelo,
    serie = excluded.serie,
    numero = excluded.numero,
    emissao_date = excluded.emissao_date,
    competencia_date = excluded.competencia_date,
    valor_total = excluded.valor_total,
    valor_produtos = excluded.valor_produtos,
    valor_frete = excluded.valor_frete,
    valor_seguro = excluded.valor_seguro,
    valor_desconto = excluded.valor_desconto,
    valor_outros = excluded.valor_outros,
    finalidade_import = excluded.finalidade_import,
    os_id_import = excluded.os_id_import,
    pagamento_import_json = excluded.pagamento_import_json,
    updated_at = now(),
    updated_by = a.fn_current_usuario_id()
  returning id into v_doc_id;

  -- XML do documento (upsert)
  if v_nf.xml_raw is not null and length(v_nf.xml_raw) > 0 then
    v_xml_hash := encode(extensions.digest(convert_to(v_nf.xml_raw, 'utf8'), 'sha256'), 'hex');

    insert into f.documento_fiscal_xml (
      tenant_id,
      documento_fiscal_id,
      chave_acesso,
      xml_raw,
      xml_hash
    )
    values (
      v_nf.tenant_id,
      v_doc_id,
      v_nf.chave,
      v_nf.xml_raw,
      v_xml_hash
    )
    on conflict (tenant_id, documento_fiscal_id)
    do update set
      xml_raw = excluded.xml_raw,
      xml_hash = excluded.xml_hash;
  end if;

  -- Titulo AP (se existir e nao force, mantem; se force, recria parcelas)
  v_sql := '
    select t.id
    from f.titulo t
    where t.tenant_id = $1
      and t.empresa_id = $2
      and t.documento_fiscal_id = $3
      and t.tipo = ''AP''
      and t.origem = ''XML''';
  if v_has_titulo_deleted_at then
    v_sql := v_sql || ' and t.deleted_at is null';
  end if;
  v_sql := v_sql || ' limit 1';
  execute v_sql into v_titulo_id using v_nf.tenant_id, v_nf.empresa_id, v_doc_id;

  if v_titulo_id is null then
    insert into f.titulo (
      tenant_id,
      empresa_id,
      tipo,
      status,
      origem,
      fornecedor_id,
      documento_fiscal_id,
      descricao,
      emissao_date,
      competencia_date,
      valor_total,
      valor_aberto,
      motivo_compra_id
    )
    values (
      v_nf.tenant_id,
      v_nf.empresa_id,
      'AP',
      'PENDENTE',
      'XML',
      v_nf.fornecedor_id::int,
      v_doc_id,
      ('NF-e ' || coalesce(v_nf.numero,'') || '/' || coalesce(v_nf.serie,'') || ' - ' || coalesce(v_nf.emitente_nome,'EMITENTE')),
      v_emissao_date,
      v_competencia_date,
      v_total,
      v_total,
      v_nf.motivo_compra_id
    )
    returning id into v_titulo_id;
  else
    -- Atualiza metadados do titulo (best-effort) e garante motivo
    update f.titulo
    set
      fornecedor_id = v_nf.fornecedor_id::int,
      emissao_date = v_emissao_date,
      competencia_date = v_competencia_date,
      valor_total = v_total,
      motivo_compra_id = v_nf.motivo_compra_id,
      updated_at = now(),
      updated_by = a.fn_current_usuario_id()
    where id = v_titulo_id
      and tenant_id = v_nf.tenant_id;

    if not p_force then
      -- Se ja existem parcelas, nao duplica.
      v_sql := '
        select exists(
          select 1
          from f.titulo_parcela tp
          where tp.tenant_id = $1
            and tp.titulo_id = $2';
      if v_has_parcela_deleted_at then
        v_sql := v_sql || ' and tp.deleted_at is null';
      end if;
      v_sql := v_sql || ' limit 1
        )';
      execute v_sql into v_has_parcelas using v_nf.tenant_id, v_titulo_id;
      if coalesce(v_has_parcelas,false) then
        return v_titulo_id;
      end if;
    else
      -- Soft delete parcelas antigas (quando existir coluna). Caso contrario, remove.
      if v_has_parcela_deleted_at then
        update f.titulo_parcela
        set deleted_at = now(),
            updated_at = now(),
            updated_by = a.fn_current_usuario_id()
        where tenant_id = v_nf.tenant_id
          and titulo_id = v_titulo_id
          and deleted_at is null;
      else
        delete from f.titulo_parcela
        where tenant_id = v_nf.tenant_id
          and titulo_id = v_titulo_id;
      end if;
    end if;
  end if;

  -- Parcelas: se vier array cria N parcelas; senao cria 001 a vista
  v_parcelas := coalesce(p_parcelas_json, '[]'::jsonb);

  if jsonb_typeof(v_parcelas) = 'array' and jsonb_array_length(v_parcelas) > 0 then
    v_i := 0;
    v_soma := 0;

    for v_el in select * from jsonb_array_elements(v_parcelas)
    loop
      v_num := coalesce(nullif(trim(v_el->>'numero'),''), lpad((v_i+1)::text, 3, '0'));
      v_num := regexp_replace(v_num, '\D', '', 'g');
      if v_num is null or v_num = '' then
        v_num := lpad((v_i+1)::text, 3, '0');
      else
        v_num := lpad(v_num, 3, '0');
      end if;

      v_venc := nullif(trim(v_el->>'vencimento'), '')::date;
      v_val := round(coalesce(nullif(trim(v_el->>'valor'), '')::numeric, 0), 2);

      if v_venc is null then
        raise exception 'Parcela sem vencimento_date (numero=%)', v_num;
      end if;
      if v_val <= 0 then
        raise exception 'Parcela com valor invalido (numero=% valor=%)', v_num, v_val;
      end if;

      insert into f.titulo_parcela (
        tenant_id,
        titulo_id,
        numero,
        vencimento_date,
        valor,
        valor_aberto
      )
      values (
        v_nf.tenant_id,
        v_titulo_id,
        v_num,
        v_venc,
        v_val,
        v_val
      );

      v_soma := round(v_soma + v_val, 2);
      v_i := v_i + 1;
    end loop;

    if abs(v_soma - v_total) > 0.05 then
      raise exception 'Soma das parcelas (%) difere do total da NF (%)', v_soma, v_total;
    end if;
  else
    insert into f.titulo_parcela (
      tenant_id,
      titulo_id,
      numero,
      vencimento_date,
      valor,
      valor_aberto
    )
    values (
      v_nf.tenant_id,
      v_titulo_id,
      '001',
      v_emissao_date,
      v_total,
      v_total
    );
  end if;

  -- Ajusta valor em aberto do titulo
  v_sql := '
    select coalesce(sum(tp.valor_aberto), 0)
    from f.titulo_parcela tp
    where tp.tenant_id = $1
      and tp.titulo_id = $2';
  if v_has_parcela_deleted_at then
    v_sql := v_sql || ' and tp.deleted_at is null';
  end if;
  execute v_sql into v_valor_aberto using v_nf.tenant_id, v_titulo_id;

  update f.titulo
  set valor_aberto = coalesce(v_valor_aberto, 0),
      updated_at = now(),
      updated_by = a.fn_current_usuario_id()
  where id = v_titulo_id
    and tenant_id = v_nf.tenant_id;

  -- log (opcional, mas ajuda suporte)
  insert into f.importacao_doc_log (
    tenant_id,
    empresa_id,
    documento_fiscal_id,
    origem,
    status,
    mensagem,
    payload
  )
  values (
    v_nf.tenant_id,
    v_nf.empresa_id,
    v_doc_id,
    'XML',
    'SUCESSO',
    'AP gerado a partir de NF importada',
    jsonb_build_object('nf_entrada_id', v_nf.id, 'titulo_id', v_titulo_id)
  );

  return v_titulo_id;
end;
$_$;


ALTER FUNCTION "f"."gerar_ap_pendente_por_nf_entrada_v2"("p_nf_entrada_id" bigint, "p_force" boolean, "p_parcelas_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."gerar_ap_por_nf_entrada"("p_nf_entrada_id" bigint, "p_motivo_compra_id" "uuid" DEFAULT NULL::"uuid", "p_parcelas_json" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public'
    AS $$
declare
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();

  v_nf public.nf_entrada%rowtype;

  v_motivo uuid;
  v_doc_id uuid;
  v_titulo_id uuid;

  v_total numeric(15,2);
  v_emissao_date date;

  r jsonb;
  v_num text;
  v_venc date;
  v_val numeric(15,2);
  v_sum numeric(15,2) := 0;
begin
  select *
    into v_nf
    from public.nf_entrada
   where id = p_nf_entrada_id
     and tenant_id = v_tenant_id
     and empresa_id = v_empresa_id
     and deleted_at is null;

  if not found then
    raise exception 'NF entrada % não encontrada para este tenant/empresa.', p_nf_entrada_id;
  end if;

  v_motivo := coalesce(p_motivo_compra_id, v_nf.motivo_compra_id);
  if v_motivo is null then
    raise exception 'motivo_compra_id é obrigatório para gerar Contas a Pagar (XML).';
  end if;

  v_total := coalesce(v_nf.valor_total, 0)::numeric(15,2);
  v_emissao_date := (v_nf.data_emissao at time zone 'America/Sao_Paulo')::date;

  -- Documento fiscal (não duplica)
  select id
    into v_doc_id
    from f.documento_fiscal
   where tenant_id = v_tenant_id
     and empresa_id = v_empresa_id
     and source_nf_entrada_id = v_nf.id
     and deleted_at is null
   limit 1;

  if v_doc_id is null then
    insert into f.documento_fiscal (
      tenant_id, empresa_id,
      chave_acesso, modelo, serie, numero,
      emissao_date, valor_total, xml_raw,
      source_nf_entrada_id,
      finalidade_import, os_id_import, pagamento_import_json,
      created_at, updated_at, created_by, updated_by, deleted_at
    ) values (
      v_tenant_id, v_empresa_id,
      v_nf.chave, v_nf.modelo, v_nf.serie, v_nf.numero,
      v_emissao_date, v_total, v_nf.xml_raw,
      v_nf.id,
      v_nf.finalidade, v_nf.os_id, v_nf.pagamento_import_json,
      now(), now(), auth.uid(), auth.uid(), null
    )
    returning id into v_doc_id;
  end if;

  -- Título AP (não duplica)
  select id
    into v_titulo_id
    from f.titulo
   where tenant_id = v_tenant_id
     and empresa_id = v_empresa_id
     and documento_fiscal_id = v_doc_id
     and tipo = 'AP'
     and deleted_at is null
   limit 1;

  if v_titulo_id is null then
    insert into f.titulo (
      tenant_id, empresa_id,
      tipo, status, origem,
      fornecedor_id, cliente_id, documento_fiscal_id,
      descricao, emissao_date, competencia_date,
      valor_total, valor_aberto,
      created_at, updated_at, created_by, updated_by, deleted_at,
      motivo_compra_id, classificacao_id
    ) values (
      v_tenant_id, v_empresa_id,
      'AP', 'PENDENTE', 'XML',
      v_nf.fornecedor_id, null, v_doc_id,
      format('NF-e %s/%s - %s',
        coalesce(v_nf.numero::text,''),
        coalesce(v_nf.serie::text,''),
        coalesce(v_nf.fornecedor_nome,'FORNECEDOR')
      ),
      v_emissao_date,
      date_trunc('month', v_emissao_date)::date,
      v_total, v_total,
      now(), now(), auth.uid(), auth.uid(), null,
      v_motivo, null
    )
    returning id into v_titulo_id;
  else
    -- garante motivo se o título já existe
    update f.titulo
       set motivo_compra_id = v_motivo,
           updated_at = now(),
           updated_by = auth.uid()
     where id = v_titulo_id
       and motivo_compra_id is distinct from v_motivo;
  end if;

  -- Se já existem parcelas, não duplica
  if exists (
    select 1
      from f.titulo_parcela
     where tenant_id = v_tenant_id
       and titulo_id = v_titulo_id
       and deleted_at is null
  ) then
    return v_titulo_id;
  end if;

  -- Parcelas
  if p_parcelas_json is null
     or jsonb_typeof(p_parcelas_json) <> 'array'
     or jsonb_array_length(p_parcelas_json) = 0 then

    insert into f.titulo_parcela (
      tenant_id, titulo_id,
      numero, vencimento_date,
      valor, valor_aberto,
      created_at, updated_at, created_by, updated_by, deleted_at
    ) values (
      v_tenant_id, v_titulo_id,
      '001', v_emissao_date,
      v_total, v_total,
      now(), now(), auth.uid(), auth.uid(), null
    );

  else
    v_sum := 0;

    for r in select jsonb_array_elements(p_parcelas_json)
    loop
      v_num := lpad(coalesce(nullif(trim(r->>'numero'), ''), '1'), 3, '0');
      v_venc := (r->>'vencimento')::date;
      v_val := (r->>'valor')::numeric(15,2);

      if v_val is null or v_val <= 0 then
        continue;
      end if;

      v_sum := v_sum + v_val;

      insert into f.titulo_parcela (
        tenant_id, titulo_id,
        numero, vencimento_date,
        valor, valor_aberto,
        created_at, updated_at, created_by, updated_by, deleted_at
      ) values (
        v_tenant_id, v_titulo_id,
        v_num, v_venc,
        v_val, v_val,
        now(), now(), auth.uid(), auth.uid(), null
      );
    end loop;

    if abs(v_sum - v_total) > 0.05 then
      raise exception 'Soma das parcelas (%) diferente do total da NF (%).', v_sum, v_total;
    end if;
  end if;

  -- ajusta valor em aberto do título
  update f.titulo
     set valor_aberto = (
           select coalesce(sum(tp.valor_aberto), 0)
             from f.titulo_parcela tp
            where tp.tenant_id = v_tenant_id
              and tp.titulo_id = v_titulo_id
              and tp.deleted_at is null
         ),
         updated_at = now(),
         updated_by = auth.uid()
   where id = v_titulo_id;

  return v_titulo_id;
end;
$$;


ALTER FUNCTION "f"."gerar_ap_por_nf_entrada"("p_nf_entrada_id" bigint, "p_motivo_compra_id" "uuid", "p_parcelas_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."gerar_titulo_ar_do_documento"("p_documento_fiscal_id" "uuid", "p_vencimento_date" "date", "p_plano_contas_id" "uuid", "p_centro_custo_id" "uuid" DEFAULT NULL::"uuid", "p_os_id" integer DEFAULT NULL::integer, "p_descricao" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a'
    AS $$
declare
  v_df record;
  v_titulo_id uuid;
  v_desc text;
begin
  if p_documento_fiscal_id is null then
    raise exception 'documento_fiscal_id é obrigatório.';
  end if;

  if p_vencimento_date is null then
    raise exception 'vencimento_date é obrigatório para gerar Contas a Receber.';
  end if;

  if p_plano_contas_id is null then
    raise exception 'plano_contas_id (classificação) é obrigatório para gerar Contas a Receber.';
  end if;

  select *
    into v_df
  from f.documento_fiscal
  where id = p_documento_fiscal_id
    and deleted_at is null;

  if not found then
    raise exception 'Documento fiscal não encontrado: %', p_documento_fiscal_id;
  end if;

  -- Permissão
  if not f.has_finance_access(v_df.tenant_id, v_df.empresa_id) then
    raise exception 'Sem permissão financeira para gerar Contas a Receber.';
  end if;

  -- Só faz sentido para faturamento (SAÍDA)
  if coalesce(v_df.operacao,'') <> 'SAIDA' then
    raise exception 'Somente documentos com operacao=SAIDA geram Contas a Receber. Documento está em: %', v_df.operacao;
  end if;

  -- AR precisa de cliente
  if v_df.cliente_id is null then
    raise exception 'cliente_id é obrigatório no documento fiscal para gerar Contas a Receber.';
  end if;

  -- Evitar duplicar (soft delete respeitado)
  select t.id
    into v_titulo_id
  from f.titulo t
  where t.tenant_id = v_df.tenant_id
    and t.empresa_id = v_df.empresa_id
    and t.tipo = 'AR'
    and t.documento_fiscal_id = v_df.id
    and t.deleted_at is null
  limit 1;

  if v_titulo_id is not null then
    return v_titulo_id;
  end if;

  v_desc := coalesce(
    nullif(btrim(p_descricao), ''),
    concat(coalesce(v_df.modelo,'DOC'), ' ', coalesce(v_df.numero,''), '/', coalesce(v_df.serie,''))
  );

  -- Título (AR)
  insert into f.titulo (
    tenant_id,
    empresa_id,
    tipo,
    status,
    origem,
    cliente_id,
    documento_fiscal_id,
    descricao,
    emissao_date,
    competencia_date,
    valor_total,
    valor_aberto
  ) values (
    v_df.tenant_id,
    v_df.empresa_id,
    'AR',
    'PENDENTE',
    'FATURAMENTO',
    v_df.cliente_id,
    v_df.id,
    v_desc,
    v_df.emissao_date,
    v_df.competencia_date,
    coalesce(v_df.valor_total, 0),
    coalesce(v_df.valor_total, 0)
  )
  returning id into v_titulo_id;

  -- Parcela única (numero é TEXT na sua tabela)
  insert into f.titulo_parcela (
    tenant_id,
    titulo_id,
    numero,
    vencimento_date,
    valor,
    valor_aberto
  ) values (
    v_df.tenant_id,
    v_titulo_id,
    '1',
    p_vencimento_date,
    coalesce(v_df.valor_total, 0),
    coalesce(v_df.valor_total, 0)
  );

  -- Rateio (100% no plano de contas)
  insert into f.titulo_rateio (
    tenant_id,
    titulo_id,
    plano_contas_id,
    centro_custo_id,
    os_id,
    percentual,
    valor
  ) values (
    v_df.tenant_id,
    v_titulo_id,
    p_plano_contas_id,
    p_centro_custo_id,
    p_os_id,
    100.0000,
    coalesce(v_df.valor_total, 0)
  );

  return v_titulo_id;
end;
$$;


ALTER FUNCTION "f"."gerar_titulo_ar_do_documento"("p_documento_fiscal_id" "uuid", "p_vencimento_date" "date", "p_plano_contas_id" "uuid", "p_centro_custo_id" "uuid", "p_os_id" integer, "p_descricao" "text") OWNER TO "postgres";


