CREATE OR REPLACE FUNCTION "f"."has_finance_access"("p_tenant" "uuid" DEFAULT "public"."current_tenant_id"(), "p_empresa" "uuid" DEFAULT "public"."current_empresa_id"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select public.has_active_empresa_access(p_tenant, p_empresa)
     and (
       a.fn_current_empresa_papel(p_tenant, p_empresa) = 'DIRETOR'
       or f.has_finance_access_unscoped_20260810(p_tenant, p_empresa)
     );
$$;


ALTER FUNCTION "f"."has_finance_access"("p_tenant" "uuid", "p_empresa" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."has_finance_access_unscoped_20260810"("p_tenant" "uuid" DEFAULT "public"."current_tenant_id"(), "p_empresa" "uuid" DEFAULT "public"."current_empresa_id"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
  select
    exists (
      select 1
      from a.usuario u
      join a.usuario_tenant ut on ut.usuario_id = u.id
      where u.auth_user_id = auth.uid()
        and ut.tenant_id = p_tenant
        and ut.ativo = true
        and ut.deleted_at is null
        and ut.papel in ('OWNER','ADMIN','DIRETOR')
        and u.deleted_at is null
    )
    or
    exists (
      select 1
      from a.usuario u
      join a.usuario_empresa ue on ue.usuario_id = u.id
      join c.empresa e on e.id = ue.empresa_id
      where u.auth_user_id = auth.uid()
        and ue.empresa_id = p_empresa
        and ue.ativo = true
        and ue.deleted_at is null
        and ue.papel in ('ADMIN','FINANCEIRO','FATURAMENTO')
        and e.deleted_at is null
        and e.tenant_id = p_tenant
        and u.deleted_at is null
    );
$$;


ALTER FUNCTION "f"."has_finance_access_unscoped_20260810"("p_tenant" "uuid", "p_empresa" "uuid") OWNER TO "postgres";


