CREATE OR REPLACE FUNCTION "f"."has_titulo_agendamento_row_access"("p_tenant_id" "uuid", "p_titulo_id" "uuid", "p_conta_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
