CREATE OR REPLACE FUNCTION "f"."has_titulo_aprovacao_row_access"("p_tenant_id" "uuid", "p_titulo_id" "uuid", "p_os_id" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select exists (
    select 1
    from f.titulo t
    where t.id = p_titulo_id
      and t.tenant_id = p_tenant_id
      and t.empresa_id = public.current_empresa_id__by_tenant(p_tenant_id)
      and t.deleted_at is null
      and f.has_finance_access(t.tenant_id, t.empresa_id)
      and (
        p_os_id is null
        or exists (
          select 1 from public.ordens_servico os
          where os.id = p_os_id
            and os.tenant_id = t.tenant_id
            and os.empresa_id = t.empresa_id
        )
      )
  );
$$;


ALTER FUNCTION "f"."has_titulo_aprovacao_row_access"("p_tenant_id" "uuid", "p_titulo_id" "uuid", "p_os_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."has_titulo_row_access"("p_tenant_id" "uuid", "p_titulo_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select exists (
    select 1
    from f.titulo t
    where t.id = p_titulo_id
      and t.tenant_id = p_tenant_id
      and t.empresa_id = public.current_empresa_id__by_tenant(p_tenant_id)
      and t.deleted_at is null
      and f.has_finance_access(t.tenant_id, t.empresa_id)
  );
$$;


ALTER FUNCTION "f"."has_titulo_row_access"("p_tenant_id" "uuid", "p_titulo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."historico_revisoes_valor_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid") RETURNS TABLE("id" "uuid", "revisado_em" timestamp with time zone, "valor_anterior" numeric, "valor_novo" numeric, "diferenca" numeric, "valor_pago" numeric, "saldo_anterior" numeric, "saldo_novo" numeric, "motivo" "text", "origem" "text", "revisado_por" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is not null then
    if p_tenant_id is distinct from public.current_tenant_id()
       or not f.has_finance_access(p_tenant_id, p_empresa_id) then
      raise exception 'Sem acesso financeiro ao tenant/empresa solicitado';
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role'
        and current_user not in ('postgres', 'service_role') then
    raise exception 'Usuario nao autenticado';
  end if;

  if not exists (
    select 1
    from f.titulo t
    join f.titulo_parcela tp
      on tp.titulo_id = t.id
     and tp.tenant_id = t.tenant_id
     and tp.deleted_at is null
    where t.id = p_titulo_id
      and t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.tipo = 'AP'
      and t.deleted_at is null
      and tp.id = p_titulo_parcela_id
  ) then
    raise exception 'Titulo/parcela AP nao encontrado no escopo informado';
  end if;

  return query
  select
    ef.id,
    ef.created_at,
    nullif(ef.payload ->> 'valor_anterior', '')::numeric,
    nullif(ef.payload ->> 'valor_novo', '')::numeric,
    nullif(ef.payload ->> 'diferenca', '')::numeric,
    nullif(ef.payload ->> 'valor_pago', '')::numeric,
    nullif(ef.payload ->> 'saldo_anterior', '')::numeric,
    nullif(ef.payload ->> 'saldo_novo', '')::numeric,
    ef.payload ->> 'motivo',
    ef.payload ->> 'origem',
    coalesce(u.nome, 'Sistema')::text
  from f.evento_financeiro ef
  left join a.usuario u
    on u.id = ef.created_by
   and u.deleted_at is null
  where ef.tenant_id = p_tenant_id
    and ef.empresa_id = p_empresa_id
    and ef.evento = 'VALOR_FINAL_AP_REVISADO'
    and ef.ref_table = 'f.titulo'
    and ef.ref_id = p_titulo_id
    and ef.payload ->> 'titulo_parcela_id' = p_titulo_parcela_id::text
  order by ef.created_at desc;
end;
$$;


ALTER FUNCTION "f"."historico_revisoes_valor_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."historico_revisoes_valor_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid") IS 'Lista a trilha de revisoes do valor final de uma parcela AP no escopo informado.';



CREATE OR REPLACE FUNCTION "f"."ignorar_extrato_linha"("p_extrato_linha_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_extrato_id uuid;
  v_conta_id uuid;
begin
  select l.tenant_id, l.extrato_bancario_id, l.conta_bancaria_id
    into v_tenant_id, v_extrato_id, v_conta_id
  from f.extrato_bancario_linha l
  where l.id = p_extrato_linha_id
    and l.deleted_at is null;
  if not found then
    raise exception 'extrato_linha_not_found';
  end if;

  if not f.has_extrato_linha_row_access(v_tenant_id, v_extrato_id, v_conta_id) then
    raise exception 'not_allowed';
  end if;

  perform f.ignorar_extrato_linha_unscoped_20260810(p_extrato_linha_id, p_motivo);
end;
$$;


ALTER FUNCTION "f"."ignorar_extrato_linha"("p_extrato_linha_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."ignorar_extrato_linha_unscoped_20260810"("p_extrato_linha_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_linha f.extrato_bancario_linha%rowtype;
  v_user uuid;
begin
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select * into v_linha
  from f.extrato_bancario_linha
  where id = p_extrato_linha_id
    and deleted_at is null;

  if not found then
    raise exception 'Extrato linha nao encontrada (id=%)', p_extrato_linha_id;
  end if;

  -- permissão
  if auth.uid() is not null then
    if not f.has_finance_access() then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  if v_user is null then
    select ut.usuario_id into v_user
    from a.usuario_tenant ut
    where ut.tenant_id = v_linha.tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN')
    order by ut.created_at nulls last
    limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  if v_linha.status <> 'PENDENTE' then
    raise exception 'Somente linha PENDENTE pode ser ignorada. Status atual=%', v_linha.status;
  end if;

  update f.extrato_bancario_linha
     set status = 'IGNORADO',
         observacoes = coalesce(observacoes,'') ||
           case when p_motivo is null or length(trim(p_motivo))=0 then '' else (' | IGNORADO: ' || p_motivo) end,
         updated_at = now(),
         updated_by = v_user
   where id = v_linha.id;

  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_linha.tenant_id,
    (select eb.empresa_id from f.extrato_bancario eb where eb.id = v_linha.extrato_bancario_id),
    'EXTRATO_LINHA_IGNORADA',
    'f.extrato_bancario_linha',
    v_linha.id,
    jsonb_build_object(
      'motivo', p_motivo,
      'valor', v_linha.valor,
      'data_movimento', v_linha.data_movimento
    ),
    now(), v_user
  );
end;
$$;


ALTER FUNCTION "f"."ignorar_extrato_linha_unscoped_20260810"("p_extrato_linha_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."ignorar_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_itens" "jsonb", "p_justificativa" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_item jsonb;
  v_titulo_id uuid;
  v_tipo text;
  v_detectada record;
  v_existente f.inconsistencia_financeira_tratamento%rowtype;
  v_actor uuid := a.fn_current_usuario_id();
  v_ignoradas integer := 0;
  v_ja_ignoradas integer := 0;
  v_resultados jsonb := '[]'::jsonb;
begin
  if p_tenant_id is null or p_empresa_id is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_id e empresa_id sao obrigatorios.';
  end if;

  if length(btrim(coalesce(p_justificativa, ''))) < 10 then
    raise exception using
      errcode = '22023',
      message = 'Informe uma justificativa com pelo menos 10 caracteres.';
  end if;

  if p_itens is null
     or jsonb_typeof(p_itens) <> 'array'
     or jsonb_array_length(p_itens) = 0
  then
    raise exception using
      errcode = '22023',
      message = 'Informe ao menos uma inconsistencia para ignorar.';
  end if;

  if jsonb_array_length(p_itens) > 500 then
    raise exception using
      errcode = '54000',
      message = 'O limite e de 500 inconsistencias por operacao.';
  end if;

  if auth.uid() is null
     and coalesce(auth.role(), '') <> 'service_role'
  then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado.';
  end if;

  if auth.uid() is not null
     and not f.pode_escrever_regras_rateio(
       p_tenant_id,
       p_empresa_id
     )
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para ignorar inconsistencias desta empresa.';
  end if;

  if (
    select count(*)
    from jsonb_array_elements(p_itens)
  ) <> (
    select count(*)
    from (
      select distinct
        item ->> 'titulo_id',
        upper(item ->> 'tipo')
      from jsonb_array_elements(p_itens) item
    ) unicos
  ) then
    raise exception using
      errcode = '23505',
      message = 'A mesma inconsistencia foi informada mais de uma vez.';
  end if;

  for v_item in
    select value from jsonb_array_elements(p_itens)
  loop
    begin
      v_titulo_id := nullif(v_item ->> 'titulo_id', '')::uuid;
      v_tipo := upper(nullif(btrim(v_item ->> 'tipo'), ''));
    exception
      when invalid_text_representation then
        raise exception using
          errcode = '22023',
          message = 'Item para ignorar possui titulo_id invalido.';
    end;

    if v_titulo_id is null or v_tipo is null then
      raise exception using
        errcode = '22023',
        message = 'Cada item deve informar titulo_id e tipo.';
    end if;

    perform 1
    from f.titulo t
    where t.id = v_titulo_id
      and t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.tipo = 'AP'
      and t.status <> 'CANCELADO'
      and t.deleted_at is null
    for share;

    if not found then
      raise exception using
        errcode = 'P0002',
        message = format(
          'Titulo %s nao foi encontrado nesta empresa.',
          v_titulo_id
        );
    end if;

    select d.*
      into v_detectada
    from f.detectar_inconsistencias_financeiras(
      p_tenant_id,
      p_empresa_id,
      null,
      null
    ) d
    where d.titulo_id = v_titulo_id
      and d.tipo = v_tipo
    limit 1;

    if not found then
      raise exception using
        errcode = 'P0002',
        message = format(
          'A inconsistencia %s nao esta ativa no titulo %s.',
          v_tipo,
          v_titulo_id
        );
    end if;

    select trat.*
      into v_existente
    from f.inconsistencia_financeira_tratamento trat
    where trat.tenant_id = p_tenant_id
      and trat.empresa_id = p_empresa_id
      and trat.titulo_id = v_titulo_id
      and trat.tipo = v_tipo
      and trat.deleted_at is null
    for update;

    if found
       and v_existente.status = 'IGNORADA'
       and v_existente.fingerprint = v_detectada.fingerprint
    then
      v_ja_ignoradas := v_ja_ignoradas + 1;
      v_resultados := v_resultados || jsonb_build_array(
        jsonb_build_object(
          'tituloId', v_titulo_id,
          'tipo', v_tipo,
          'status', 'JA_IGNORADA'
        )
      );
      continue;
    end if;

    insert into f.inconsistencia_financeira_tratamento (
      tenant_id,
      empresa_id,
      titulo_id,
      tipo,
      status,
      fingerprint,
      justificativa,
      dados_snapshot,
      tratado_em,
      tratado_por
    )
    values (
      p_tenant_id,
      p_empresa_id,
      v_titulo_id,
      v_tipo,
      'IGNORADA',
      v_detectada.fingerprint,
      btrim(p_justificativa),
      v_detectada.dados,
      now(),
      v_actor
    )
    on conflict (
      tenant_id,
      empresa_id,
      titulo_id,
      tipo
    ) where deleted_at is null
    do update set
      status = excluded.status,
      fingerprint = excluded.fingerprint,
      justificativa = excluded.justificativa,
      dados_snapshot = excluded.dados_snapshot,
      tratado_em = excluded.tratado_em,
      tratado_por = excluded.tratado_por,
      updated_at = now(),
      updated_by = v_actor;

    insert into f.evento_financeiro (
      tenant_id,
      empresa_id,
      evento,
      ref_table,
      ref_id,
      payload,
      created_by
    )
    values (
      p_tenant_id,
      p_empresa_id,
      'INCONSISTENCIA_FINANCEIRA_IGNORADA',
      'f.titulo',
      v_titulo_id,
      jsonb_build_object(
        'tipo', v_tipo,
        'fingerprint', v_detectada.fingerprint,
        'justificativa', btrim(p_justificativa),
        'dados', v_detectada.dados,
        'alterouTitulo', false,
        'alterouParcela', false,
        'alterouPagamento', false
      ),
      v_actor
    );

    v_ignoradas := v_ignoradas + 1;
    v_resultados := v_resultados || jsonb_build_array(
      jsonb_build_object(
        'tituloId', v_titulo_id,
        'tipo', v_tipo,
        'status', 'IGNORADA'
      )
    );
  end loop;

  return jsonb_build_object(
    'ignoradas', v_ignoradas,
    'jaIgnoradas', v_ja_ignoradas,
    'itens', v_resultados
  );
end;
$$;


ALTER FUNCTION "f"."ignorar_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_itens" "jsonb", "p_justificativa" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."ignorar_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_itens" "jsonb", "p_justificativa" "text") IS 'Ignora inconsistencias detectadas com justificativa; a decisao perde efeito automaticamente se o fingerprint mudar.';



CREATE OR REPLACE FUNCTION "f"."listar_historico_inconsistencia_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid" DEFAULT NULL::"uuid", "p_limite" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_limite integer := greatest(1, least(coalesce(p_limite, 100), 500));
  v_resultado jsonb;
begin
  if p_tenant_id is null or p_empresa_id is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_id e empresa_id sao obrigatorios.';
  end if;

  if auth.uid() is null
     and coalesce(auth.role(), '') <> 'service_role'
  then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado.';
  end if;

  if auth.uid() is not null
     and not f.pode_ler_regras_rateio(p_tenant_id, p_empresa_id)
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para consultar a auditoria desta empresa.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', ev.id,
      'evento', ev.evento,
      'tituloId', case
        when ev.ref_table = 'f.titulo' then ev.ref_id
        else null
      end,
      'referenciaTabela', ev.ref_table,
      'referenciaId', ev.ref_id,
      'payload', ev.payload,
      'criadoEm', ev.created_at,
      'criadoPor', ev.created_by
    )
    order by ev.created_at desc, ev.id desc
  ), '[]'::jsonb)
    into v_resultado
  from (
    select evento.*
    from f.evento_financeiro evento
    where evento.tenant_id = p_tenant_id
      and evento.empresa_id = p_empresa_id
      and evento.evento like 'INCONSISTENCIA_FINANCEIRA_%'
      and (
        p_titulo_id is null
        or (
          evento.ref_table = 'f.titulo'
          and evento.ref_id = p_titulo_id
        )
        or evento.payload -> 'titulosOrigem' @> to_jsonb(
          array[p_titulo_id]::uuid[]
        )
      )
    order by evento.created_at desc, evento.id desc
    limit v_limite
  ) ev;

  return v_resultado;
end;
$$;


ALTER FUNCTION "f"."listar_historico_inconsistencia_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."listar_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date" DEFAULT NULL::"date", "p_data_fim" "date" DEFAULT NULL::"date", "p_tipo" "text" DEFAULT NULL::"text", "p_prioridade" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'ABERTA'::"text", "p_busca" "text" DEFAULT NULL::"text", "p_limite" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_limite integer := greatest(1, least(coalesce(p_limite, 200), 500));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_status text := upper(coalesce(nullif(btrim(p_status), ''), 'ABERTA'));
  v_tipo text := upper(nullif(btrim(p_tipo), ''));
  v_prioridade text := upper(nullif(btrim(p_prioridade), ''));
  v_busca text := lower(nullif(btrim(p_busca), ''));
  v_resultado jsonb;
begin
  if p_tenant_id is null or p_empresa_id is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_id e empresa_id sao obrigatorios.';
  end if;

  if p_data_inicio is not null
     and p_data_fim is not null
     and p_data_inicio > p_data_fim
  then
    raise exception using
      errcode = '22023',
      message = 'A data inicial nao pode ser posterior a data final.';
  end if;

  if v_status not in ('ABERTA', 'IGNORADA', 'TODAS') then
    raise exception using
      errcode = '22023',
      message = 'Status invalido. Use ABERTA, IGNORADA ou TODAS.';
  end if;

  if v_prioridade is not null
     and v_prioridade not in ('ALTA', 'MEDIA', 'BAIXA', 'TODAS')
  then
    raise exception using
      errcode = '22023',
      message = 'Prioridade invalida. Use ALTA, MEDIA ou BAIXA.';
  end if;

  if auth.uid() is null
     and coalesce(auth.role(), '') <> 'service_role'
  then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado.';
  end if;

  if auth.uid() is not null
     and not f.pode_ler_regras_rateio(p_tenant_id, p_empresa_id)
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para consultar inconsistencias desta empresa.';
  end if;

  with detectadas as (
    select *
    from f.detectar_inconsistencias_financeiras(
      p_tenant_id,
      p_empresa_id,
      p_data_inicio,
      p_data_fim
    )
  ),
  estados as (
    select
      d.*,
      case
        when trat.status = 'IGNORADA'
         and trat.fingerprint = d.fingerprint
        then 'IGNORADA'
        else 'ABERTA'
      end as status_inconsistencia,
      case
        when trat.status = 'IGNORADA'
         and trat.fingerprint = d.fingerprint
        then trat.justificativa
        else null
      end as justificativa_ignorada,
      case
        when d.tipo = 'SEM_REGRA_RATEIO'
        then 'OPORTUNIDADE_AUTOMACAO'
        else 'INCONSISTENCIA'
      end as categoria
    from detectadas d
    left join f.inconsistencia_financeira_tratamento trat
      on trat.tenant_id = p_tenant_id
     and trat.empresa_id = p_empresa_id
     and trat.titulo_id = d.titulo_id
     and trat.tipo = d.tipo
     and trat.deleted_at is null
  ),
  filtradas as (
    select *
    from estados e
    where (v_status = 'TODAS' or e.status_inconsistencia = v_status)
      and (v_tipo is null or v_tipo = 'TODAS' or e.tipo = v_tipo)
      and (
        v_prioridade is null
        or v_prioridade = 'TODAS'
        or e.prioridade = v_prioridade
      )
      and (
        v_busca is null
        or lower(concat_ws(
          ' ',
          e.fornecedor_nome,
          e.documento,
          e.descricao,
          e.motivo_codigo,
          e.motivo_nome,
          e.plano_atual_codigo,
          e.plano_atual_nome,
          e.centro_atual_codigo,
          e.centro_atual_nome,
          e.tipo
        )) like '%' || v_busca || '%'
      )
  ),
  pagina as (
    select *
    from filtradas f
    order by
      case f.prioridade
        when 'ALTA' then 1
        when 'MEDIA' then 2
        else 3
      end,
      f.valor_total desc,
      f.data_referencia desc,
      f.titulo_id,
      f.tipo
    limit v_limite
    offset v_offset
  ),
  escopo as (
    select count(*)::integer as titulos_escopo
    from (
      select
        t.id,
        coalesce(
          t.competencia_date,
          t.emissao_date,
          parcelas.primeiro_vencimento,
          t.created_at::date
        ) as data_referencia
      from f.titulo t
      left join lateral (
        select min(tp.vencimento_date) as primeiro_vencimento
        from f.titulo_parcela tp
        where tp.tenant_id = t.tenant_id
          and tp.titulo_id = t.id
          and tp.deleted_at is null
      ) parcelas on true
      where t.tenant_id = p_tenant_id
        and t.empresa_id = p_empresa_id
        and t.tipo = 'AP'
        and t.status <> 'CANCELADO'
        and t.deleted_at is null
        and not f.titulo_eh_legado_implantacao(
          t.tenant_id,
          t.empresa_id,
          t.id
        )
    ) x
    where (p_data_inicio is null or x.data_referencia >= p_data_inicio)
      and (p_data_fim is null or x.data_referencia <= p_data_fim)
  ),
  afetados as (
    select distinct e.titulo_id, e.valor_total
    from estados e
    where e.status_inconsistencia = 'ABERTA'
      and e.categoria = 'INCONSISTENCIA'
  ),
  resumo_tipo as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'tipo', x.tipo,
        'categoria', x.categoria,
        'quantidade', x.quantidade,
        'titulos', x.titulos,
        'abertas', x.abertas,
        'ignoradas', x.ignoradas,
        'valor', x.valor
      )
      order by x.categoria desc, x.quantidade desc, x.tipo
    ), '[]'::jsonb) as itens
    from (
      select
        e.tipo,
        e.categoria,
        count(*)::integer as quantidade,
        count(distinct e.titulo_id)::integer as titulos,
        count(*) filter (
          where e.status_inconsistencia = 'ABERTA'
        )::integer as abertas,
        count(*) filter (
          where e.status_inconsistencia = 'IGNORADA'
        )::integer as ignoradas,
        round(coalesce(sum(e.valor_total) filter (
          where e.status_inconsistencia = 'ABERTA'
            and e.categoria = 'INCONSISTENCIA'
        ), 0), 2) as valor
      from estados e
      group by e.tipo, e.categoria
    ) x
  ),
  resumo_prioridade as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'prioridade', x.prioridade,
        'quantidade', x.quantidade,
        'titulos', x.titulos
      )
      order by case x.prioridade
        when 'ALTA' then 1
        when 'MEDIA' then 2
        else 3
      end
    ), '[]'::jsonb) as itens
    from (
      select
        e.prioridade,
        count(*)::integer as quantidade,
        count(distinct e.titulo_id)::integer as titulos
      from estados e
      where e.status_inconsistencia = 'ABERTA'
        and e.categoria = 'INCONSISTENCIA'
      group by e.prioridade
    ) x
  ),
  catalogo_planos as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'id', pc.id,
        'codigo', pc.codigo,
        'nome', pc.nome,
        'natureza', pc.natureza
      )
      order by pc.codigo, pc.nome
    ), '[]'::jsonb) as itens
    from f.plano_contas pc
    where pc.tenant_id = p_tenant_id
      and pc.tipo = 'ANALITICA'
      and pc.codigo <> 'DESP_GERAL'
      and pc.ativo
      and pc.deleted_at is null
  ),
  catalogo_centros as (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'id', cc.id,
        'codigo', cc.codigo,
        'nome', cc.nome,
        'parentId', cc.parent_id
      )
      order by cc.codigo, cc.nome
    ), '[]'::jsonb) as itens
    from f.centro_custo cc
    where cc.tenant_id = p_tenant_id
      and cc.empresa_id = p_empresa_id
      and cc.ativo
      and cc.deleted_at is null
  )
  select jsonb_build_object(
    'resumo', jsonb_build_object(
      'titulosEscopo', esc.titulos_escopo,
      'titulosComInconsistencia', (select count(*) from afetados),
      'titulosSemInconsistencia', greatest(
        0,
        esc.titulos_escopo - (select count(*) from afetados)
      ),
      'qualidadePercentual', case
        when esc.titulos_escopo = 0 then 100.0
        else round(
          100.0 * greatest(
            0,
            esc.titulos_escopo - (select count(*) from afetados)
          ) / esc.titulos_escopo,
          1
        )
      end,
      'totalInconsistencias', (
        select count(*)
        from estados e
        where e.status_inconsistencia = 'ABERTA'
          and e.categoria = 'INCONSISTENCIA'
      ),
      'totalAbertas', (
        select count(*)
        from estados e
        where e.status_inconsistencia = 'ABERTA'
      ),
      'totalIgnoradas', (
        select count(*)
        from estados e
        where e.status_inconsistencia = 'IGNORADA'
      ),
      'oportunidadesAutomacao', (
        select count(distinct e.titulo_id)
        from estados e
        where e.status_inconsistencia = 'ABERTA'
          and e.categoria = 'OPORTUNIDADE_AUTOMACAO'
      ),
      'valorTitulosAfetados', round(coalesce((
        select sum(a.valor_total) from afetados a
      ), 0), 2),
      'porTipo', (select rt.itens from resumo_tipo rt),
      'porPrioridade', (
        select rp.itens from resumo_prioridade rp
      )
    ),
    'paginacao', jsonb_build_object(
      'total', (select count(*) from filtradas),
      'limite', v_limite,
      'offset', v_offset
    ),
    'catalogos', jsonb_build_object(
      'planos', (select cp.itens from catalogo_planos cp),
      'centros', (select cc.itens from catalogo_centros cc)
    ),
    'itens', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'tituloId', pg.titulo_id,
          'tipo', pg.tipo,
          'categoria', pg.categoria,
          'prioridade', pg.prioridade,
          'status', pg.status_inconsistencia,
          'dataReferencia', pg.data_referencia,
          'fornecedorId', pg.fornecedor_id,
          'fornecedorNome', pg.fornecedor_nome,
          'documento', pg.documento,
          'descricao', pg.descricao,
          'valorTotal', pg.valor_total,
          'motivoCompraId', pg.motivo_compra_id,
          'motivoCodigo', pg.motivo_codigo,
          'motivoNome', pg.motivo_nome,
          'planoAtualId', pg.plano_atual_id,
          'planoAtualCodigo', pg.plano_atual_codigo,
          'planoAtualNome', pg.plano_atual_nome,
          'centroAtualId', pg.centro_atual_id,
          'centroAtualCodigo', pg.centro_atual_codigo,
          'centroAtualNome', pg.centro_atual_nome,
          'totalRateios', pg.total_rateios,
          'totalPercentual', pg.total_percentual,
          'totalRateado', pg.total_rateado,
          'temRateioExplicito', pg.tem_rateio_explicito,
          'detalhe', pg.detalhe,
          'sugestao', pg.sugestao,
          'corrigivel', pg.corrigivel,
          'podeCriarRegra', pg.pode_criar_regra,
          'fingerprint', pg.fingerprint,
          'justificativaIgnorada', pg.justificativa_ignorada,
          'dados', pg.dados
        )
        order by
          case pg.prioridade
            when 'ALTA' then 1
            when 'MEDIA' then 2
            else 3
          end,
          pg.valor_total desc,
          pg.data_referencia desc,
          pg.titulo_id,
          pg.tipo
      )
      from pagina pg
    ), '[]'::jsonb)
  )
  into v_resultado
  from escopo esc;

  return coalesce(v_resultado, jsonb_build_object(
    'resumo', '{}'::jsonb,
    'paginacao', jsonb_build_object(
      'total', 0,
      'limite', v_limite,
      'offset', v_offset
    ),
    'catalogos', jsonb_build_object(
      'planos', '[]'::jsonb,
      'centros', '[]'::jsonb
    ),
    'itens', '[]'::jsonb
  ));
end;
$$;


ALTER FUNCTION "f"."listar_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date", "p_tipo" "text", "p_prioridade" "text", "p_status" "text", "p_busca" "text", "p_limite" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "f"."listar_inconsistencias_financeiras"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date", "p_tipo" "text", "p_prioridade" "text", "p_status" "text", "p_busca" "text", "p_limite" integer, "p_offset" integer) IS 'Lista APs com inconsistencias por tenant/empresa. Legado e oportunidades de automacao nao reduzem a nota de qualidade.';



CREATE OR REPLACE FUNCTION "f"."listar_regras_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_resultado jsonb;
begin
  if auth.uid() is not null
     and not f.pode_ler_regras_rateio(p_tenant_id, p_empresa_id)
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para consultar regras de rateio desta empresa.';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', base.id,
        'motivo_compra_id', base.motivo_compra_id,
        'motivo_codigo', base.motivo_codigo,
        'motivo_nome', base.motivo_nome,
        'ativo', base.ativo,
        'updated_at', base.updated_at,
        'itens', base.itens
      )
      order by base.motivo_codigo, base.motivo_nome, base.id
    ),
    '[]'::jsonb
  )
    into v_resultado
  from (
    select
      rr.id,
      rr.motivo_compra_id,
      mc.codigo as motivo_codigo,
      mc.nome as motivo_nome,
      rr.ativo,
      rr.updated_at,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', rri.id,
            'plano_contas_id', rri.plano_contas_id,
            'plano_codigo', pc.codigo,
            'plano_nome', pc.nome,
            'centro_custo_id', rri.centro_custo_id,
            'centro_codigo', cc.codigo,
            'centro_nome', cc.nome,
            'percentual', rri.percentual
          )
          order by cc.codigo, pc.codigo, rri.id
        )
        from f.regra_rateio_item rri
        join f.plano_contas pc
          on pc.id = rri.plano_contas_id
         and pc.tenant_id = rri.tenant_id
        join f.centro_custo cc
          on cc.id = rri.centro_custo_id
         and cc.tenant_id = rri.tenant_id
         and cc.empresa_id = rr.empresa_id
        where rri.tenant_id = rr.tenant_id
          and rri.regra_rateio_id = rr.id
          and rri.deleted_at is null
      ), '[]'::jsonb) as itens
    from f.regra_rateio rr
    join f.motivo_compra mc
      on mc.id = rr.motivo_compra_id
     and mc.tenant_id = rr.tenant_id
    where rr.tenant_id = p_tenant_id
      and rr.empresa_id = p_empresa_id
      and rr.deleted_at is null
  ) base;

  return v_resultado;
end;
$$;


ALTER FUNCTION "f"."listar_regras_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."listar_transferencias_bancarias"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date" DEFAULT NULL::"date", "p_data_fim" "date" DEFAULT NULL::"date", "p_conta_bancaria_id" "uuid" DEFAULT NULL::"uuid", "p_limite" integer DEFAULT 500) RETURNS TABLE("id" "uuid", "data_movimento" "date", "valor" numeric, "descricao" "text", "status" "text", "conta_origem_id" "uuid", "origem_codigo" "text", "origem_nome" "text", "origem_banco" "text", "conta_destino_id" "uuid", "destino_codigo" "text", "destino_nome" "text", "destino_banco" "text", "linha_saida_status" "text", "linha_entrada_status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Usuario nao autenticado';
  end if;

  if p_tenant_id is null
     or p_tenant_id is distinct from public.current_tenant_id() then
    raise exception 'Tenant invalido para a sessao atual';
  end if;

  if p_empresa_id is null
     or p_empresa_id is distinct from public.current_empresa_id()
     or not f.has_finance_access(p_tenant_id, p_empresa_id) then
    raise exception 'Sem acesso financeiro a empresa selecionada';
  end if;

  if p_data_inicio is not null
     and p_data_fim is not null
     and p_data_inicio > p_data_fim then
    raise exception 'Periodo invalido';
  end if;

  return query
  select
    tb.id,
    tb.data_movimento,
    tb.valor,
    tb.descricao,
    tb.status,
    tb.conta_origem_id,
    origem.codigo,
    origem.nome,
    origem.banco,
    tb.conta_destino_id,
    destino.codigo,
    destino.nome,
    destino.banco,
    saida.status,
    entrada.status,
    tb.created_at
  from f.transferencia_bancaria tb
  join f.conta_bancaria origem
    on origem.id = tb.conta_origem_id
   and origem.tenant_id = tb.tenant_id
   and origem.empresa_id = tb.empresa_id
  join f.conta_bancaria destino
    on destino.id = tb.conta_destino_id
   and destino.tenant_id = tb.tenant_id
   and destino.empresa_id = tb.empresa_id
  left join f.extrato_bancario_linha saida
    on saida.id = tb.linha_saida_id
   and saida.tenant_id = tb.tenant_id
  left join f.extrato_bancario_linha entrada
    on entrada.id = tb.linha_entrada_id
   and entrada.tenant_id = tb.tenant_id
  where tb.tenant_id = p_tenant_id
    and tb.empresa_id = p_empresa_id
    and tb.deleted_at is null
    and (p_data_inicio is null or tb.data_movimento >= p_data_inicio)
    and (p_data_fim is null or tb.data_movimento <= p_data_fim)
    and (
      p_conta_bancaria_id is null
      or tb.conta_origem_id = p_conta_bancaria_id
      or tb.conta_destino_id = p_conta_bancaria_id
    )
  order by tb.data_movimento desc, tb.created_at desc
  limit least(greatest(coalesce(p_limite, 500), 1), 1000);
end;
$$;


ALTER FUNCTION "f"."listar_transferencias_bancarias"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date", "p_conta_bancaria_id" "uuid", "p_limite" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "f"."listar_transferencias_bancarias"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date", "p_conta_bancaria_id" "uuid", "p_limite" integer) IS 'Lista transferencias bancarias da empresa selecionada com contas e status de conciliacao.';



CREATE OR REPLACE FUNCTION "f"."marcar_legado_implantacao_ap"("p_titulo_id" "uuid", "p_corte_date" "date", "p_motivo" "text", "p_origem_marcacao" "text" DEFAULT 'MANUAL'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_existente_id uuid;
  v_actor uuid;
  v_parcelas integer;
  v_valor_parcelas numeric(15,2);
  v_menor_vencimento date;
  v_maior_vencimento date;
  v_marker_id uuid;
begin
  if p_titulo_id is null or p_corte_date is null then
    raise exception using
      errcode = '22023',
      message = 'titulo_id e corte_date sao obrigatorios';
  end if;

  if length(btrim(coalesce(p_motivo, ''))) < 10 then
    raise exception using
      errcode = '22023',
      message = 'Informe um motivo de marcacao com pelo menos 10 caracteres';
  end if;

  if p_origem_marcacao not in ('AUTOMATICA_CARGA_INICIAL', 'MANUAL', 'MIGRACAO') then
    raise exception using
      errcode = '22023',
      message = 'Origem de marcacao invalida';
  end if;

  if auth.uid() is null and coalesce(auth.role(), '') <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado';
  end if;

  select *
  into v_titulo
  from f.titulo t
  where t.id = p_titulo_id
    and t.deleted_at is null
  for update;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if v_titulo.tipo <> 'AP'
     or v_titulo.status not in ('PENDENTE', 'APROVADO', 'AGENDADO') then
    raise exception 'Somente AP ativo e em aberto pode ser marcado como legado';
  end if;

  if auth.uid() is not null then
    if public.current_tenant_id() is distinct from v_titulo.tenant_id
       or public.current_empresa_id() is distinct from v_titulo.empresa_id
       or not f.has_finance_access(
         v_titulo.tenant_id,
         v_titulo.empresa_id
       ) then
      raise exception using
        errcode = '42501',
        message = 'Sem permissao para o escopo do titulo';
    end if;
  end if;

  select li.id
  into v_existente_id
  from f.titulo_legado_implantacao li
  where li.tenant_id = v_titulo.tenant_id
    and li.empresa_id = v_titulo.empresa_id
    and li.titulo_id = v_titulo.id
    and li.desmarcado_em is null
  limit 1;

  if v_existente_id is not null then
    return v_existente_id;
  end if;

  select
    count(*),
    coalesce(sum(tp.valor_aberto), 0),
    min(tp.vencimento_date),
    max(tp.vencimento_date)
  into
    v_parcelas,
    v_valor_parcelas,
    v_menor_vencimento,
    v_maior_vencimento
  from f.titulo_parcela tp
  where tp.tenant_id = v_titulo.tenant_id
    and tp.titulo_id = v_titulo.id
    and tp.deleted_at is null
    and tp.valor_aberto > 0;

  if v_parcelas = 0 or v_titulo.valor_aberto <= 0 then
    raise exception 'Titulo nao possui saldo aberto para marcar';
  end if;

  if v_maior_vencimento >= p_corte_date then
    raise exception
      'Titulo possui parcela aberta no corte ou depois dele (maior vencimento=%)',
      v_maior_vencimento;
  end if;

  if exists (
    select 1
    from f.titulo_parcela tp
    join f.pagamento_item pi
      on pi.tenant_id = v_titulo.tenant_id
     and pi.empresa_id = v_titulo.empresa_id
     and pi.titulo_parcela_id = tp.id
     and pi.deleted_at is null
    join f.pagamento p
      on p.tenant_id = v_titulo.tenant_id
     and p.empresa_id = v_titulo.empresa_id
     and p.id = pi.pagamento_id
     and p.deleted_at is null
    where tp.tenant_id = v_titulo.tenant_id
      and tp.titulo_id = v_titulo.id
  ) then
    raise exception
      'Titulo possui pagamento aplicado e exige conciliacao individual';
  end if;

  v_actor := a.fn_current_usuario_id();

  insert into f.titulo_legado_implantacao (
    tenant_id,
    empresa_id,
    titulo_id,
    corte_date,
    motivo,
    origem_marcacao,
    status_titulo_snapshot,
    origem_titulo_snapshot,
    valor_total_snapshot,
    valor_aberto_snapshot,
    parcelas_abertas_snapshot,
    valor_parcelas_abertas_snapshot,
    menor_vencimento_snapshot,
    maior_vencimento_snapshot,
    marcado_por,
    metadata
  )
  values (
    v_titulo.tenant_id,
    v_titulo.empresa_id,
    v_titulo.id,
    p_corte_date,
    btrim(p_motivo),
    p_origem_marcacao,
    v_titulo.status,
    v_titulo.origem,
    v_titulo.valor_total,
    v_titulo.valor_aberto,
    v_parcelas,
    v_valor_parcelas,
    v_menor_vencimento,
    v_maior_vencimento,
    v_actor,
    jsonb_build_object(
      'impactaResultado', false,
      'impactaCaixa', false,
      'impactaIndicadoresOperacionais', true
    )
  )
  returning id into v_marker_id;

  insert into f.evento_financeiro (
    tenant_id,
    empresa_id,
    evento,
    ref_table,
    ref_id,
    payload,
    created_by
  )
  values (
    v_titulo.tenant_id,
    v_titulo.empresa_id,
    'TITULO_AP_LEGADO_IMPLANTACAO_MARCADO',
    'f.titulo',
    v_titulo.id,
    jsonb_build_object(
      'marcacaoId', v_marker_id,
      'corte', p_corte_date,
      'motivo', btrim(p_motivo),
      'origemMarcacao', p_origem_marcacao,
      'statusTitulo', v_titulo.status,
      'valorTotal', v_titulo.valor_total,
      'valorAberto', v_titulo.valor_aberto,
      'parcelasAbertas', v_parcelas,
      'valorParcelasAbertas', v_valor_parcelas,
      'menorVencimento', v_menor_vencimento,
      'maiorVencimento', v_maior_vencimento,
      'gerouPagamento', false,
      'alterouResultado', false
    ),
    v_actor
  );

  return v_marker_id;
end;
$$;


ALTER FUNCTION "f"."marcar_legado_implantacao_ap"("p_titulo_id" "uuid", "p_corte_date" "date", "p_motivo" "text", "p_origem_marcacao" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."nfe_gravar_impostos_da_nf_entrada"("p_nf_entrada_id" bigint, "p_documento_fiscal_id" "uuid", "p_tenant_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a'
    AS $$
declare
  v_xml_text text;
  v_xml xml;

  v_operacao text;
  v_doc_natureza text;
  v_natureza_padrao text;

  v_now timestamptz := now();

  -- totais
  v_vprod   numeric := 0;

  v_vbc_icms numeric := 0;
  v_vicms    numeric := 0;

  v_vipi     numeric := 0;
  v_vpis     numeric := 0;
  v_vcofins  numeric := 0;

  -- bases (quando precisar)
  v_base_ipi    numeric := 0;
  v_base_pis    numeric := 0;
  v_base_cofins numeric := 0;

  -- aliquotas
  v_aliq_icms numeric := 0;
  v_aliq_ipi numeric := 0;
  v_aliq_pis numeric := 0;
  v_aliq_cofins numeric := 0;

  v_cnt int;
  v_single numeric;
begin
  if p_nf_entrada_id is null then raise exception 'nf_entrada_id é obrigatório.'; end if;
  if p_documento_fiscal_id is null then raise exception 'documento_fiscal_id é obrigatório.'; end if;
  if p_tenant_id is null then raise exception 'tenant_id é obrigatório.'; end if;

  select df.operacao, df.natureza
    into v_operacao, v_doc_natureza
  from f.documento_fiscal df
  where df.id = p_documento_fiscal_id
    and df.tenant_id = p_tenant_id
    and df.deleted_at is null;

  if not found then
    raise exception 'Documento fiscal não encontrado (id=% tenant_id=%).', p_documento_fiscal_id, p_tenant_id;
  end if;

  if v_operacao = 'ENTRADA' then
    v_natureza_padrao := 'CREDITO';
  else
    v_natureza_padrao := 'DEBITO';
  end if;

  -- lê o XML da NF de entrada
  select ne.xml_raw
    into v_xml_text
  from public.nf_entrada ne
  where ne.id = p_nf_entrada_id;

  if v_xml_text is null or btrim(v_xml_text) = '' then
    raise exception 'XML vazio em public.nf_entrada.id=% (coluna xml_raw).', p_nf_entrada_id;
  end if;

  v_xml := v_xml_text::xml;

  --------------------------------------------------------------------
  -- TOTAIS: tenta em ICMSTot; se vier zerado, soma por item.
  -- (sempre usando local-name() para ignorar namespace)
  --------------------------------------------------------------------

  v_vprod := f._xpath_first_num_anyns(v_xml, '//*[local-name()="ICMSTot"]/*[local-name()="vProd"]/text()');

  v_vbc_icms := f._xpath_first_num_anyns(v_xml, '//*[local-name()="ICMSTot"]/*[local-name()="vBC"]/text()');
  v_vicms    := f._xpath_first_num_anyns(v_xml, '//*[local-name()="ICMSTot"]/*[local-name()="vICMS"]/text()');

  v_vipi     := f._xpath_first_num_anyns(v_xml, '//*[local-name()="ICMSTot"]/*[local-name()="vIPI"]/text()');
  v_vpis     := f._xpath_first_num_anyns(v_xml, '//*[local-name()="ICMSTot"]/*[local-name()="vPIS"]/text()');
  v_vcofins  := f._xpath_first_num_anyns(v_xml, '//*[local-name()="ICMSTot"]/*[local-name()="vCOFINS"]/text()');

  -- Fallback: soma por item (quando totais vierem 0)
  if v_vbc_icms = 0 then
    v_vbc_icms := f._xpath_sum_num_anyns(v_xml, '//*[local-name()="det"]//*[local-name()="ICMS"]//*[local-name()="vBC"]/text()');
  end if;
  if v_vicms = 0 then
    v_vicms := f._xpath_sum_num_anyns(v_xml, '//*[local-name()="det"]//*[local-name()="ICMS"]//*[local-name()="vICMS"]/text()');
  end if;

  if v_vipi = 0 then
    v_vipi := f._xpath_sum_num_anyns(v_xml, '//*[local-name()="det"]//*[local-name()="IPI"]//*[local-name()="vIPI"]/text()');
  end if;

  if v_vpis = 0 then
    v_vpis := f._xpath_sum_num_anyns(v_xml, '//*[local-name()="det"]//*[local-name()="PIS"]//*[local-name()="vPIS"]/text()');
  end if;

  if v_vcofins = 0 then
    v_vcofins := f._xpath_sum_num_anyns(v_xml, '//*[local-name()="det"]//*[local-name()="COFINS"]//*[local-name()="vCOFINS"]/text()');
  end if;

  --------------------------------------------------------------------
  -- BASES (quando existirem por item); senão, usa vProd.
  --------------------------------------------------------------------
  v_base_ipi := f._xpath_sum_num_anyns(v_xml, '//*[local-name()="det"]//*[local-name()="IPI"]//*[local-name()="vBC"]/text()');
  if v_base_ipi = 0 then v_base_ipi := v_vprod; end if;

  v_base_pis := f._xpath_sum_num_anyns(v_xml, '//*[local-name()="det"]//*[local-name()="PIS"]//*[local-name()="vBC"]/text()');
  if v_base_pis = 0 then v_base_pis := v_vprod; end if;

  v_base_cofins := f._xpath_sum_num_anyns(v_xml, '//*[local-name()="det"]//*[local-name()="COFINS"]//*[local-name()="vBC"]/text()');
  if v_base_cofins = 0 then v_base_cofins := v_vprod; end if;

  --------------------------------------------------------------------
  -- ALÍQUOTAS: se existir 1 única alíquota, usa ela; senão calcula.
  --------------------------------------------------------------------

  -- ICMS pICMS
  select count(distinct (x::text)::numeric), max((x::text)::numeric)
    into v_cnt, v_single
  from unnest(xpath('//*[local-name()="det"]//*[local-name()="ICMS"]//*[local-name()="pICMS"]/text()', v_xml)) as t(x);

  if coalesce(v_cnt,0) = 1 and v_single is not null then
    v_aliq_icms := round(v_single, 4);
  else
    v_aliq_icms := case when v_vbc_icms > 0 then round((v_vicms / v_vbc_icms) * 100, 4) else 0 end;
  end if;

  -- IPI pIPI
  select count(distinct (x::text)::numeric), max((x::text)::numeric)
    into v_cnt, v_single
  from unnest(xpath('//*[local-name()="det"]//*[local-name()="IPI"]//*[local-name()="pIPI"]/text()', v_xml)) as t(x);

  if coalesce(v_cnt,0) = 1 and v_single is not null then
    v_aliq_ipi := round(v_single, 4);
  else
    v_aliq_ipi := case when v_base_ipi > 0 then round((v_vipi / v_base_ipi) * 100, 4) else 0 end;
  end if;

  -- PIS pPIS
  select count(distinct (x::text)::numeric), max((x::text)::numeric)
    into v_cnt, v_single
  from unnest(xpath('//*[local-name()="det"]//*[local-name()="PIS"]//*[local-name()="pPIS"]/text()', v_xml)) as t(x);

  if coalesce(v_cnt,0) = 1 and v_single is not null then
    v_aliq_pis := round(v_single, 4);
  else
    v_aliq_pis := case when v_base_pis > 0 then round((v_vpis / v_base_pis) * 100, 4) else 0 end;
  end if;

  -- COFINS pCOFINS
  select count(distinct (x::text)::numeric), max((x::text)::numeric)
    into v_cnt, v_single
  from unnest(xpath('//*[local-name()="det"]//*[local-name()="COFINS"]//*[local-name()="pCOFINS"]/text()', v_xml)) as t(x);

  if coalesce(v_cnt,0) = 1 and v_single is not null then
    v_aliq_cofins := round(v_single, 4);
  else
    v_aliq_cofins := case when v_base_cofins > 0 then round((v_vcofins / v_base_cofins) * 100, 4) else 0 end;
  end if;

  --------------------------------------------------------------------
  -- UPSERT (tenant_id, documento_fiscal_id, imposto, natureza)
  --------------------------------------------------------------------

  -- ICMS
  if v_vicms > 0 or v_vbc_icms > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id,
      imposto, natureza,
      base_original, deducoes, base_calculo,
      aliquota, valor_calculado, valor_ajustado,
      created_at, updated_at, deleted_at
    ) values (
      p_tenant_id, p_documento_fiscal_id,
      'ICMS', v_natureza_padrao,
      v_vbc_icms, 0, v_vbc_icms,
      v_aliq_icms, v_vicms, null,
      v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original   = excluded.base_original,
      deducoes        = excluded.deducoes,
      base_calculo    = excluded.base_calculo,
      aliquota        = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      valor_ajustado  = excluded.valor_ajustado,
      updated_at      = excluded.updated_at,
      deleted_at      = null;
  end if;

  -- IPI
  if v_vipi > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id,
      imposto, natureza,
      base_original, deducoes, base_calculo,
      aliquota, valor_calculado, valor_ajustado,
      created_at, updated_at, deleted_at
    ) values (
      p_tenant_id, p_documento_fiscal_id,
      'IPI', v_natureza_padrao,
      v_base_ipi, 0, v_base_ipi,
      v_aliq_ipi, v_vipi, null,
      v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original   = excluded.base_original,
      deducoes        = excluded.deducoes,
      base_calculo    = excluded.base_calculo,
      aliquota        = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      valor_ajustado  = excluded.valor_ajustado,
      updated_at      = excluded.updated_at,
      deleted_at      = null;
  end if;

  -- PIS
  if v_vpis > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id,
      imposto, natureza,
      base_original, deducoes, base_calculo,
      aliquota, valor_calculado, valor_ajustado,
      created_at, updated_at, deleted_at
    ) values (
      p_tenant_id, p_documento_fiscal_id,
      'PIS', v_natureza_padrao,
      v_base_pis, 0, v_base_pis,
      v_aliq_pis, v_vpis, null,
      v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original   = excluded.base_original,
      deducoes        = excluded.deducoes,
      base_calculo    = excluded.base_calculo,
      aliquota        = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      valor_ajustado  = excluded.valor_ajustado,
      updated_at      = excluded.updated_at,
      deleted_at      = null;
  end if;

  -- COFINS
  if v_vcofins > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id,
      imposto, natureza,
      base_original, deducoes, base_calculo,
      aliquota, valor_calculado, valor_ajustado,
      created_at, updated_at, deleted_at
    ) values (
      p_tenant_id, p_documento_fiscal_id,
      'COFINS', v_natureza_padrao,
      v_base_cofins, 0, v_base_cofins,
      v_aliq_cofins, v_vcofins, null,
      v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original   = excluded.base_original,
      deducoes        = excluded.deducoes,
      base_calculo    = excluded.base_calculo,
      aliquota        = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      valor_ajustado  = excluded.valor_ajustado,
      updated_at      = excluded.updated_at,
      deleted_at      = null;
  end if;

end;
$$;


ALTER FUNCTION "f"."nfe_gravar_impostos_da_nf_entrada"("p_nf_entrada_id" bigint, "p_documento_fiscal_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."nfe_gravar_impostos_da_nf_entrada_sem_xml"("p_nf_entrada_id" bigint, "p_documento_fiscal_id" "uuid", "p_tenant_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public'
    AS $$
declare
  v_operacao text;
  v_doc_natureza text;
  v_natureza_imposto text;

  v_base_prod numeric(15,2);
  v_vicms numeric(15,2);
  v_vipi numeric(15,2);
  v_vpis numeric(15,2);
  v_vcofins numeric(15,2);

  v_aliq_icms numeric(7,4);
  v_aliq_ipi numeric(7,4);
  v_aliq_pis numeric(7,4);
  v_aliq_cofins numeric(7,4);

  v_now timestamptz := now();
begin
  select df.operacao, df.natureza
    into v_operacao, v_doc_natureza
  from f.documento_fiscal df
  where df.id = p_documento_fiscal_id
    and df.tenant_id = p_tenant_id
    and df.deleted_at is null;

  if not found then
    raise exception 'Documento fiscal % não encontrado (tenant %).', p_documento_fiscal_id, p_tenant_id;
  end if;

  if coalesce(v_doc_natureza,'') <> 'PRODUTO' then
    return;
  end if;

  v_natureza_imposto := case when v_operacao = 'ENTRADA' then 'CREDITO' else 'DEBITO' end;

  select
    coalesce(sum(i.v_prod),0)::numeric(15,2) as base_prod,
    coalesce(sum(i.v_icms),0)::numeric(15,2) as v_icms,
    coalesce(sum(i.v_ipi),0)::numeric(15,2) as v_ipi,
    coalesce(sum(i.v_pis),0)::numeric(15,2) as v_pis,
    coalesce(sum(i.v_cofins),0)::numeric(15,2) as v_cofins,
    case when coalesce(sum(i.v_prod),0) > 0 then round((sum(i.v_icms)/sum(i.v_prod))*100,4) else null end as aliq_icms,
    case when coalesce(sum(i.v_prod),0) > 0 then round((sum(i.v_ipi)/sum(i.v_prod))*100,4) else null end as aliq_ipi,
    case when coalesce(sum(i.v_prod),0) > 0 then round((sum(i.v_pis)/sum(i.v_prod))*100,4) else null end as aliq_pis,
    case when coalesce(sum(i.v_prod),0) > 0 then round((sum(i.v_cofins)/sum(i.v_prod))*100,4) else null end as aliq_cofins
  into
    v_base_prod, v_vicms, v_vipi, v_vpis, v_vcofins,
    v_aliq_icms, v_aliq_ipi, v_aliq_pis, v_aliq_cofins
  from public.nf_entrada_itens i
  where i.nf_entrada_id = p_nf_entrada_id
    and i.tenant_id = p_tenant_id;

  -- ICMS
  if coalesce(v_vicms,0) <> 0 then
    insert into f.documento_fiscal_imposto (
      id, tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo,
      aliquota, valor_calculado, valor_ajustado,
      created_at, updated_at
    ) values (
      gen_random_uuid(), p_tenant_id, p_documento_fiscal_id, 'ICMS', v_natureza_imposto,
      v_base_prod, 0, v_base_prod,
      coalesce(v_aliq_icms,0), v_vicms, 0,
      v_now, v_now
    )
    on conflict on constraint uq_documento_fiscal_imposto__doc_imp_nat
    do update set
      base_original = excluded.base_original,
      deducoes = excluded.deducoes,
      base_calculo = excluded.base_calculo,
      aliquota = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      updated_at = excluded.updated_at;
  end if;

  -- IPI
  if coalesce(v_vipi,0) <> 0 then
    insert into f.documento_fiscal_imposto (
      id, tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo,
      aliquota, valor_calculado, valor_ajustado,
      created_at, updated_at
    ) values (
      gen_random_uuid(), p_tenant_id, p_documento_fiscal_id, 'IPI', v_natureza_imposto,
      v_base_prod, 0, v_base_prod,
      coalesce(v_aliq_ipi,0), v_vipi, 0,
      v_now, v_now
    )
    on conflict on constraint uq_documento_fiscal_imposto__doc_imp_nat
    do update set
      base_original = excluded.base_original,
      deducoes = excluded.deducoes,
      base_calculo = excluded.base_calculo,
      aliquota = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      updated_at = excluded.updated_at;
  end if;

  -- PIS
  if coalesce(v_vpis,0) <> 0 then
    insert into f.documento_fiscal_imposto (
      id, tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo,
      aliquota, valor_calculado, valor_ajustado,
      created_at, updated_at
    ) values (
      gen_random_uuid(), p_tenant_id, p_documento_fiscal_id, 'PIS', v_natureza_imposto,
      v_base_prod, 0, v_base_prod,
      coalesce(v_aliq_pis,0), v_vpis, 0,
      v_now, v_now
    )
    on conflict on constraint uq_documento_fiscal_imposto__doc_imp_nat
    do update set
      base_original = excluded.base_original,
      deducoes = excluded.deducoes,
      base_calculo = excluded.base_calculo,
      aliquota = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      updated_at = excluded.updated_at;
  end if;

  -- COFINS
  if coalesce(v_vcofins,0) <> 0 then
    insert into f.documento_fiscal_imposto (
      id, tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo,
      aliquota, valor_calculado, valor_ajustado,
      created_at, updated_at
    ) values (
      gen_random_uuid(), p_tenant_id, p_documento_fiscal_id, 'COFINS', v_natureza_imposto,
      v_base_prod, 0, v_base_prod,
      coalesce(v_aliq_cofins,0), v_vcofins, 0,
      v_now, v_now
    )
    on conflict on constraint uq_documento_fiscal_imposto__doc_imp_nat
    do update set
      base_original = excluded.base_original,
      deducoes = excluded.deducoes,
      base_calculo = excluded.base_calculo,
      aliquota = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      updated_at = excluded.updated_at;
  end if;

end;
$$;


ALTER FUNCTION "f"."nfe_gravar_impostos_da_nf_entrada_sem_xml"("p_nf_entrada_id" bigint, "p_documento_fiscal_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."nfe_gravar_impostos_do_documento"("p_documento_fiscal_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
begin
  select d.tenant_id, d.empresa_id
    into v_tenant_id, v_empresa_id
  from f.documento_fiscal d
  where d.id = p_documento_fiscal_id
    and d.deleted_at is null;

  if not found then
    raise exception 'documento_fiscal_not_found';
  end if;
  if v_empresa_id is distinct from public.current_empresa_id__by_tenant(v_tenant_id)
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id)
     or not (
       f.has_finance_access(v_tenant_id, v_empresa_id)
       or public.can('nf_entrada', 'import', v_tenant_id)
     ) then
    raise exception 'not_allowed';
  end if;

  perform f.nfe_gravar_impostos_do_documento_unscoped_20260810(p_documento_fiscal_id);
end;
$$;


ALTER FUNCTION "f"."nfe_gravar_impostos_do_documento"("p_documento_fiscal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."nfe_gravar_impostos_do_documento_unscoped_20260810"("p_documento_fiscal_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a'
    AS $$
declare
  v_df record;
begin
  select
    id,
    tenant_id,
    empresa_id,
    source_nf_entrada_id
  into v_df
  from f.documento_fiscal
  where id = p_documento_fiscal_id
    and deleted_at is null;

  if not found then
    raise exception 'Documento fiscal não encontrado: %', p_documento_fiscal_id;
  end if;

  if v_df.source_nf_entrada_id is null then
    raise exception 'Documento fiscal % não tem source_nf_entrada_id preenchido.', p_documento_fiscal_id;
  end if;

  perform f.nfe_gravar_impostos_da_nf_entrada(v_df.source_nf_entrada_id, v_df.id, v_df.tenant_id);
end;
$$;


ALTER FUNCTION "f"."nfe_gravar_impostos_do_documento_unscoped_20260810"("p_documento_fiscal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."nfe_gravar_impostos_entrada_do_documento"("p_documento_fiscal_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a'
    AS $_$
declare
  v_df record;
  v_xml_col text;
  v_xml_text text;
  v_xml xml;

  v_vbc_icms numeric;
  v_vicms numeric;

  v_vipi numeric;
  v_base_ipi numeric;

  v_vpis numeric;
  v_base_pis numeric;

  v_vcofins numeric;
  v_base_cofins numeric;

  v_now timestamptz := now();

  v_aliq_icms numeric;
  v_aliq_ipi numeric;
  v_aliq_pis numeric;
  v_aliq_cofins numeric;

  v_cnt int;
  v_single numeric;

  v_natureza text := 'CREDITO';
begin
  select *
    into v_df
  from f.documento_fiscal
  where id = p_documento_fiscal_id
    and deleted_at is null;

  if not found then
    raise exception 'documento_fiscal não encontrado: %', p_documento_fiscal_id;
  end if;

  if v_df.operacao <> 'ENTRADA' then
    raise exception 'Esta função é somente para ENTRADA. operacao atual=%', v_df.operacao;
  end if;

  if v_df.source_nf_entrada_id is null then
    raise exception 'documento_fiscal sem source_nf_entrada_id (não consigo achar o XML).';
  end if;

  -- Descobre a coluna do XML em public.nf_entrada
  select c.column_name
    into v_xml_col
  from information_schema.columns c
  where c.table_schema = 'public'
    and c.table_name = 'nf_entrada'
    and c.column_name ilike '%xml%'
    and c.data_type in ('text','xml','character varying')
  order by
    case when c.column_name in ('xml','xml_raw','xml_text','conteudo_xml','arquivo_xml','xml_content') then 0 else 1 end,
    c.ordinal_position
  limit 1;

  if v_xml_col is null then
    raise exception 'Não encontrei coluna com XML em public.nf_entrada.';
  end if;

  execute format('select %I::text from public.nf_entrada where id = $1', v_xml_col)
    into v_xml_text
    using v_df.source_nf_entrada_id;

  if v_xml_text is null or btrim(v_xml_text) = '' then
    raise exception 'XML vazio em public.nf_entrada.id=% (coluna %).', v_df.source_nf_entrada_id, v_xml_col;
  end if;

  v_xml := v_xml_text::xml;

  -- Totais
  v_vbc_icms := coalesce(f._nfe_xpath_num(v_xml, '//nfe:ICMSTot/nfe:vBC/text()'), 0);
  v_vicms    := coalesce(f._nfe_xpath_num(v_xml, '//nfe:ICMSTot/nfe:vICMS/text()'), 0);

  v_vipi     := coalesce(f._nfe_xpath_num(v_xml, '//nfe:ICMSTot/nfe:vIPI/text()'), 0);
  v_vpis     := coalesce(f._nfe_xpath_num(v_xml, '//nfe:ICMSTot/nfe:vPIS/text()'), 0);
  v_vcofins  := coalesce(f._nfe_xpath_num(v_xml, '//nfe:ICMSTot/nfe:vCOFINS/text()'), 0);

  -- Bases por item (somando vBC)
  select coalesce(sum((x)::text::numeric), 0)
    into v_base_ipi
  from unnest(xpath(
    '//nfe:det/nfe:imposto/nfe:IPI//*[local-name()="vBC"]/text()',
    v_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  )) as t(x);

  if v_base_ipi = 0 then
    v_base_ipi := coalesce(f._nfe_xpath_num(v_xml, '//nfe:ICMSTot/nfe:vProd/text()'), 0);
  end if;

  select coalesce(sum((x)::text::numeric), 0)
    into v_base_pis
  from unnest(xpath(
    '//nfe:det/nfe:imposto/nfe:PIS//*[local-name()="vBC"]/text()',
    v_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  )) as t(x);

  select coalesce(sum((x)::text::numeric), 0)
    into v_base_cofins
  from unnest(xpath(
    '//nfe:det/nfe:imposto/nfe:COFINS//*[local-name()="vBC"]/text()',
    v_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  )) as t(x);

  if v_base_pis = 0 then
    v_base_pis := coalesce(f._nfe_xpath_num(v_xml, '//nfe:ICMSTot/nfe:vProd/text()'), 0);
  end if;
  if v_base_cofins = 0 then
    v_base_cofins := coalesce(f._nfe_xpath_num(v_xml, '//nfe:ICMSTot/nfe:vProd/text()'), 0);
  end if;

  -- Alíquotas (fonte do XML quando única; senão calcula)
  select count(distinct (x)::text::numeric), max((x)::text::numeric)
    into v_cnt, v_single
  from unnest(xpath(
    '//nfe:det/nfe:imposto/nfe:ICMS//*[local-name()="pICMS"]/text()',
    v_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  )) as t(x);

  if coalesce(v_cnt,0) = 1 and v_single is not null then
    v_aliq_icms := round(v_single, 4);
  else
    v_aliq_icms := case when v_vbc_icms > 0 then round((v_vicms / v_vbc_icms) * 100, 4) else 0 end;
  end if;

  select count(distinct (x)::text::numeric), max((x)::text::numeric)
    into v_cnt, v_single
  from unnest(xpath(
    '//nfe:det/nfe:imposto/nfe:IPI//*[local-name()="pIPI"]/text()',
    v_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  )) as t(x);

  if coalesce(v_cnt,0) = 1 and v_single is not null then
    v_aliq_ipi := round(v_single, 4);
  else
    v_aliq_ipi := case when v_base_ipi > 0 then round((v_vipi / v_base_ipi) * 100, 4) else 0 end;
  end if;

  select count(distinct (x)::text::numeric), max((x)::text::numeric)
    into v_cnt, v_single
  from unnest(xpath(
    '//nfe:det/nfe:imposto/nfe:PIS//*[local-name()="pPIS"]/text()',
    v_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  )) as t(x);

  if coalesce(v_cnt,0) = 1 and v_single is not null then
    v_aliq_pis := round(v_single, 4);
  else
    v_aliq_pis := case when v_base_pis > 0 then round((v_vpis / v_base_pis) * 100, 4) else 0 end;
  end if;

  select count(distinct (x)::text::numeric), max((x)::text::numeric)
    into v_cnt, v_single
  from unnest(xpath(
    '//nfe:det/nfe:imposto/nfe:COFINS//*[local-name()="pCOFINS"]/text()',
    v_xml,
    array[array['nfe','http://www.portalfiscal.inf.br/nfe']]
  )) as t(x);

  if coalesce(v_cnt,0) = 1 and v_single is not null then
    v_aliq_cofins := round(v_single, 4);
  else
    v_aliq_cofins := case when v_base_cofins > 0 then round((v_vcofins / v_base_cofins) * 100, 4) else 0 end;
  end if;

  -- UPSERT: CREDITO
  if v_vicms > 0 or v_vbc_icms > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo, aliquota,
      valor_calculado, valor_ajustado, created_at, updated_at, deleted_at
    ) values (
      v_df.tenant_id, v_df.id, 'ICMS', v_natureza,
      v_vbc_icms, 0, v_vbc_icms, v_aliq_icms,
      v_vicms, null, v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original=excluded.base_original,
      deducoes=excluded.deducoes,
      base_calculo=excluded.base_calculo,
      aliquota=excluded.aliquota,
      valor_calculado=excluded.valor_calculado,
      valor_ajustado=excluded.valor_ajustado,
      updated_at=excluded.updated_at,
      deleted_at=null;
  end if;

  if v_vipi > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo, aliquota,
      valor_calculado, valor_ajustado, created_at, updated_at, deleted_at
    ) values (
      v_df.tenant_id, v_df.id, 'IPI', v_natureza,
      v_base_ipi, 0, v_base_ipi, v_aliq_ipi,
      v_vipi, null, v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original=excluded.base_original,
      deducoes=excluded.deducoes,
      base_calculo=excluded.base_calculo,
      aliquota=excluded.aliquota,
      valor_calculado=excluded.valor_calculado,
      valor_ajustado=excluded.valor_ajustado,
      updated_at=excluded.updated_at,
      deleted_at=null;
  end if;

  if v_vpis > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo, aliquota,
      valor_calculado, valor_ajustado, created_at, updated_at, deleted_at
    ) values (
      v_df.tenant_id, v_df.id, 'PIS', v_natureza,
      v_base_pis, 0, v_base_pis, v_aliq_pis,
      v_vpis, null, v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original=excluded.base_original,
      deducoes=excluded.deducoes,
      base_calculo=excluded.base_calculo,
      aliquota=excluded.aliquota,
      valor_calculado=excluded.valor_calculado,
      valor_ajustado=excluded.valor_ajustado,
      updated_at=excluded.updated_at,
      deleted_at=null;
  end if;

  if v_vcofins > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo, aliquota,
      valor_calculado, valor_ajustado, created_at, updated_at, deleted_at
    ) values (
      v_df.tenant_id, v_df.id, 'COFINS', v_natureza,
      v_base_cofins, 0, v_base_cofins, v_aliq_cofins,
      v_vcofins, null, v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original=excluded.base_original,
      deducoes=excluded.deducoes,
      base_calculo=excluded.base_calculo,
      aliquota=excluded.aliquota,
      valor_calculado=excluded.valor_calculado,
      valor_ajustado=excluded.valor_ajustado,
      updated_at=excluded.updated_at,
      deleted_at=null;
  end if;

end;
$_$;


ALTER FUNCTION "f"."nfe_gravar_impostos_entrada_do_documento"("p_documento_fiscal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."nfe_sync_creditos_entrada_from_nf_itens"("p_documento_fiscal_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_df record;
  v_now timestamptz := now();

  v_base_prod numeric(15,2) := 0;
  v_vicms numeric(15,2) := 0;
  v_vpis numeric(15,2) := 0;
  v_vcofins numeric(15,2) := 0;
  v_vipi numeric(15,2) := 0;

  v_aliq_icms numeric(7,4);
  v_aliq_pis numeric(7,4);
  v_aliq_cofins numeric(7,4);
  v_aliq_ipi numeric(7,4);
begin
  if auth.uid() is null then
    if current_user not in ('postgres', 'service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  if p_documento_fiscal_id is null then
    raise exception 'p_documento_fiscal_id obrigatorio';
  end if;

  select
    df.id,
    df.tenant_id,
    df.empresa_id,
    df.operacao,
    df.natureza,
    df.source_nf_entrada_id
  into v_df
  from f.documento_fiscal df
  where df.id = p_documento_fiscal_id
    and df.deleted_at is null;

  if not found then
    raise exception 'Documento fiscal nao encontrado: %', p_documento_fiscal_id;
  end if;

  if auth.uid() is not null then
    if public.current_tenant_id() is distinct from v_df.tenant_id then
      raise exception 'Tenant mismatch';
    end if;
    if public.current_empresa_id() is distinct from v_df.empresa_id then
      raise exception 'Empresa mismatch';
    end if;
    if not f.has_finance_access(v_df.tenant_id, v_df.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  if coalesce(v_df.operacao, '') <> 'ENTRADA' then
    return;
  end if;
  if coalesce(v_df.natureza, 'PRODUTO') <> 'PRODUTO' then
    return;
  end if;
  if v_df.source_nf_entrada_id is null then
    return;
  end if;

  select
    round(coalesce(sum(coalesce(i.v_prod, 0)), 0)::numeric, 2) as base_prod,
    round(coalesce(sum(coalesce(i.v_icms, 0)), 0)::numeric, 2) as v_icms,
    round(coalesce(sum(coalesce(i.v_pis, 0)), 0)::numeric, 2) as v_pis,
    round(coalesce(sum(coalesce(i.v_cofins, 0)), 0)::numeric, 2) as v_cofins,
    round(coalesce(sum(coalesce(i.v_ipi, 0)), 0)::numeric, 2) as v_ipi
  into
    v_base_prod, v_vicms, v_vpis, v_vcofins, v_vipi
  from public.nf_entrada_itens i
  where i.tenant_id = v_df.tenant_id
    and i.empresa_id = v_df.empresa_id
    and i.nf_entrada_id = v_df.source_nf_entrada_id;

  if coalesce(v_base_prod, 0) <= 0 then
    return;
  end if;

  v_aliq_icms := case when v_base_prod > 0 then round((v_vicms / v_base_prod) * 100, 4) else null end;
  v_aliq_pis := case when v_base_prod > 0 then round((v_vpis / v_base_prod) * 100, 4) else null end;
  v_aliq_cofins := case when v_base_prod > 0 then round((v_vcofins / v_base_prod) * 100, 4) else null end;
  v_aliq_ipi := case when v_base_prod > 0 then round((v_vipi / v_base_prod) * 100, 4) else null end;

  if coalesce(v_vicms, 0) > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo, aliquota,
      valor_calculado, valor_ajustado, created_at, updated_at, deleted_at
    ) values (
      v_df.tenant_id, v_df.id, 'ICMS', 'CREDITO',
      v_base_prod, 0, v_base_prod, v_aliq_icms,
      v_vicms, null, v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original = excluded.base_original,
      deducoes = excluded.deducoes,
      base_calculo = excluded.base_calculo,
      aliquota = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      valor_ajustado = null,
      updated_at = excluded.updated_at,
      deleted_at = null;
  end if;

  if coalesce(v_vpis, 0) > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo, aliquota,
      valor_calculado, valor_ajustado, created_at, updated_at, deleted_at
    ) values (
      v_df.tenant_id, v_df.id, 'PIS', 'CREDITO',
      v_base_prod, 0, v_base_prod, v_aliq_pis,
      v_vpis, null, v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original = excluded.base_original,
      deducoes = excluded.deducoes,
      base_calculo = excluded.base_calculo,
      aliquota = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      valor_ajustado = null,
      updated_at = excluded.updated_at,
      deleted_at = null;
  end if;

  if coalesce(v_vcofins, 0) > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo, aliquota,
      valor_calculado, valor_ajustado, created_at, updated_at, deleted_at
    ) values (
      v_df.tenant_id, v_df.id, 'COFINS', 'CREDITO',
      v_base_prod, 0, v_base_prod, v_aliq_cofins,
      v_vcofins, null, v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original = excluded.base_original,
      deducoes = excluded.deducoes,
      base_calculo = excluded.base_calculo,
      aliquota = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      valor_ajustado = null,
      updated_at = excluded.updated_at,
      deleted_at = null;
  end if;

  if coalesce(v_vipi, 0) > 0 then
    insert into f.documento_fiscal_imposto (
      tenant_id, documento_fiscal_id, imposto, natureza,
      base_original, deducoes, base_calculo, aliquota,
      valor_calculado, valor_ajustado, created_at, updated_at, deleted_at
    ) values (
      v_df.tenant_id, v_df.id, 'IPI', 'CREDITO',
      v_base_prod, 0, v_base_prod, v_aliq_ipi,
      v_vipi, null, v_now, v_now, null
    )
    on conflict (tenant_id, documento_fiscal_id, imposto, natureza)
    do update set
      base_original = excluded.base_original,
      deducoes = excluded.deducoes,
      base_calculo = excluded.base_calculo,
      aliquota = excluded.aliquota,
      valor_calculado = excluded.valor_calculado,
      valor_ajustado = null,
      updated_at = excluded.updated_at,
      deleted_at = null;
  end if;
end;
$$;


ALTER FUNCTION "f"."nfe_sync_creditos_entrada_from_nf_itens"("p_documento_fiscal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."pode_escrever_regras_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
  select
    p_tenant_id = public.current_tenant_id()
    and p_empresa_id = public.current_empresa_id()
    and f.has_finance_access(p_tenant_id, p_empresa_id)
    and (
      public.has_permission('financeiro.write')
      or public.has_permission('admin.manage_users')
      or public.has_permission('admin.all')
      or exists (
        select 1
        from a.usuario u
        join a.usuario_tenant ut on ut.usuario_id = u.id
        where u.auth_user_id = auth.uid()
          and u.deleted_at is null
          and ut.tenant_id = p_tenant_id
          and ut.ativo and ut.deleted_at is null
          and ut.papel in ('OWNER', 'ADMIN')
      )
      or exists (
        select 1
        from a.usuario u
        join a.usuario_empresa ue on ue.usuario_id = u.id
        where u.auth_user_id = auth.uid()
          and u.deleted_at is null
          and ue.empresa_id = p_empresa_id
          and ue.ativo and ue.deleted_at is null
          and ue.papel in ('ADMIN', 'FINANCEIRO')
      )
    );
$$;


ALTER FUNCTION "f"."pode_escrever_regras_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."pode_ler_regras_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
  select
    p_tenant_id = public.current_tenant_id()
    and p_empresa_id = public.current_empresa_id()
    and f.has_finance_access(p_tenant_id, p_empresa_id)
    and (
      public.has_permission('financeiro.read')
      or public.has_permission('financeiro.write')
      or public.has_permission('admin.manage_users')
      or public.has_permission('admin.all')
      or exists (
        select 1
        from a.usuario u
        join a.usuario_tenant ut on ut.usuario_id = u.id
        where u.auth_user_id = auth.uid()
          and u.deleted_at is null
          and ut.tenant_id = p_tenant_id
          and ut.ativo and ut.deleted_at is null
          and ut.papel in ('OWNER', 'ADMIN')
      )
      or exists (
        select 1
        from a.usuario u
        join a.usuario_empresa ue on ue.usuario_id = u.id
        where u.auth_user_id = auth.uid()
          and u.deleted_at is null
          and ue.empresa_id = p_empresa_id
          and ue.ativo and ue.deleted_at is null
          and ue.papel in ('ADMIN', 'FINANCEIRO')
      )
    );
$$;


ALTER FUNCTION "f"."pode_ler_regras_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."preview_classificacao_compromissos"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS TABLE("titulo_id" "uuid", "status" "text", "origem" "text", "descricao" "text", "fornecedor_id" integer, "fornecedor_nome" "text", "emissao_date" "date", "competencia_date" "date", "primeiro_vencimento" "date", "ultimo_vencimento" "date", "valor_titulo" numeric, "valor_aberto_titulo" numeric, "valor_parcelas" numeric, "valor_aberto_parcelas" numeric, "quantidade_parcelas" bigint, "total_parcelas_serie" integer, "motivo_codigo" "text", "motivo_nome" "text", "arrendamento_contrato_id" "uuid", "legado_implantacao" boolean, "planos" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if p_tenant_id is null or p_empresa_id is null then
    raise exception 'Tenant e empresa sao obrigatorios.';
  end if;

  if auth.uid() is not null then
    if p_tenant_id is distinct from public.current_tenant_id()
       or p_empresa_id is distinct from public.current_empresa_id()
       or not f.has_finance_access(p_tenant_id, p_empresa_id)
    then
      raise exception 'Sem permissao para auditar compromissos deste escopo.';
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role'
        and session_user not in ('postgres', 'service_role')
  then
    raise exception 'Usuario nao autenticado.';
  end if;

  return query
  with parcelas as (
    select
      tp.titulo_id,
      min(tp.vencimento_date) as primeiro_vencimento,
      max(tp.vencimento_date) as ultimo_vencimento,
      coalesce(sum(tp.valor), 0)::numeric as valor_parcelas,
      coalesce(sum(tp.valor_aberto), 0)::numeric as valor_aberto_parcelas,
      count(*)::bigint as quantidade_parcelas
    from f.titulo_parcela tp
    join f.titulo t_scope
      on t_scope.id = tp.titulo_id
     and t_scope.tenant_id = p_tenant_id
     and t_scope.empresa_id = p_empresa_id
     and t_scope.deleted_at is null
    where tp.tenant_id = p_tenant_id
      and tp.deleted_at is null
    group by tp.titulo_id
  ),
  rateios as (
    select
      tr.titulo_id,
      jsonb_agg(
        distinct jsonb_build_object(
          'id', pc.id,
          'codigo', pc.codigo,
          'nome', pc.nome,
          'investimento',
            exists (
              select 1
              from r.dre_plano_excluido dpe
              where dpe.tenant_id = p_tenant_id
                and dpe.plano_contas_id = pc.id
            )
        )
      ) filter (where pc.id is not null) as planos
    from f.titulo_rateio tr
    join f.titulo t_scope
      on t_scope.id = tr.titulo_id
     and t_scope.tenant_id = p_tenant_id
     and t_scope.empresa_id = p_empresa_id
     and t_scope.deleted_at is null
    left join f.plano_contas pc
      on pc.id = tr.plano_contas_id
     and pc.tenant_id = p_tenant_id
     and pc.deleted_at is null
    where tr.tenant_id = p_tenant_id
      and tr.deleted_at is null
    group by tr.titulo_id
  )
  select
    t.id,
    t.status,
    t.origem,
    t.descricao,
    t.fornecedor_id,
    forn.nome::text,
    t.emissao_date,
    t.competencia_date,
    p.primeiro_vencimento,
    p.ultimo_vencimento,
    t.valor_total,
    t.valor_aberto,
    coalesce(p.valor_parcelas, 0),
    coalesce(p.valor_aberto_parcelas, 0),
    coalesce(p.quantidade_parcelas, 0),
    t.total_parcelas_serie,
    coalesce(mc.codigo, 'NAO_CLASSIFICADO'),
    coalesce(mc.nome, 'Nao classificado'),
    t.arrendamento_contrato_id,
    exists (
      select 1
      from f.titulo_legado_implantacao li
      where li.tenant_id = p_tenant_id
        and li.empresa_id = p_empresa_id
        and li.titulo_id = t.id
        and li.desmarcado_em is null
    ),
    coalesce(r.planos, '[]'::jsonb)
  from f.titulo t
  left join f.titulo_aprovacao ta
    on ta.tenant_id = p_tenant_id
   and ta.titulo_id = t.id
   and ta.deleted_at is null
  left join f.motivo_compra mc
    on mc.tenant_id = p_tenant_id
   and mc.id = coalesce(ta.motivo_compra_id, t.motivo_compra_id)
   and mc.deleted_at is null
  left join public.fornecedores forn
    on forn.id = t.fornecedor_id
   and forn.tenant_id = p_tenant_id
   and forn.empresa_id = p_empresa_id
  left join parcelas p on p.titulo_id = t.id
  left join rateios r on r.titulo_id = t.id
  where t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id
    and t.tipo = 'AP'
    and t.deleted_at is null
    and t.status <> 'CANCELADO'
  order by
    coalesce(p.primeiro_vencimento, t.competencia_date, t.emissao_date),
    t.id;
end;
$$;


ALTER FUNCTION "f"."preview_classificacao_compromissos"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."preview_classificacao_compromissos"("p_tenant_id" "uuid", "p_empresa_id" "uuid") IS 'Base somente leitura para reconciliar e classificar compromissos AP, limitada obrigatoriamente a tenant e empresa.';



CREATE OR REPLACE FUNCTION "f"."preview_inconsistencias_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS TABLE("titulo_id" "uuid", "tipo" "text", "status" "text", "origem" "text", "descricao" "text", "competencia_date" "date", "emissao_date" "date", "valor_titulo" numeric, "quantidade_rateios" bigint, "percentual_total" numeric, "valor_rateado" numeric, "excesso_valor" numeric, "duplicidades_dimensao" bigint, "duplicidades_exatas" bigint, "motivo_plano_id" "uuid", "rateios" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if p_tenant_id is null or p_empresa_id is null then
    raise exception 'Tenant e empresa sao obrigatorios.';
  end if;

  if auth.uid() is not null then
    if p_tenant_id is distinct from public.current_tenant_id()
       or p_empresa_id is distinct from public.current_empresa_id()
       or not f.has_finance_access(p_tenant_id, p_empresa_id)
    then
      raise exception 'Sem permissao para auditar rateios deste escopo.';
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role'
        and session_user not in ('postgres', 'service_role')
  then
    raise exception 'Usuario nao autenticado.';
  end if;

  return query
  with titulos as (
    select
      t.id,
      t.tipo,
      t.status,
      t.origem,
      t.descricao,
      t.competencia_date,
      t.emissao_date,
      t.valor_total,
      mc.plano_contas_id as motivo_plano_id
    from f.titulo t
    left join f.motivo_compra mc
      on mc.tenant_id = p_tenant_id
     and mc.id = t.motivo_compra_id
     and mc.deleted_at is null
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.deleted_at is null
  ),
  rateios_detalhe as (
    select
      t.id as titulo_id,
      tr.id as rateio_id,
      tr.plano_contas_id,
      tr.centro_custo_id,
      tr.os_id,
      tr.percentual,
      tr.valor,
      tr.created_at,
      tr.updated_at,
      tr.created_by,
      pc.codigo as plano_codigo,
      pc.nome as plano_nome,
      cc.codigo as centro_codigo,
      cc.nome as centro_nome
    from titulos t
    join f.titulo_rateio tr
      on tr.tenant_id = p_tenant_id
     and tr.titulo_id = t.id
     and tr.deleted_at is null
    left join f.plano_contas pc
      on pc.tenant_id = p_tenant_id
     and pc.id = tr.plano_contas_id
     and pc.deleted_at is null
    left join f.centro_custo cc
      on cc.tenant_id = p_tenant_id
     and cc.empresa_id = p_empresa_id
     and cc.id = tr.centro_custo_id
     and cc.deleted_at is null
  ),
  estatisticas as (
    select
      t.id as titulo_id,
      count(rd.rateio_id) as quantidade_rateios,
      coalesce(sum(rd.percentual), 0)::numeric as percentual_total,
      coalesce(sum(coalesce(
        rd.valor,
        round(t.valor_total * coalesce(rd.percentual, 0) / 100.0, 2),
        0
      )), 0)::numeric as valor_rateado,
      (
        count(rd.rateio_id)
        - count(distinct row(
            rd.plano_contas_id,
            rd.centro_custo_id,
            rd.os_id
          ))
      )::bigint as duplicidades_dimensao,
      (
        count(rd.rateio_id)
        - count(distinct row(
            rd.plano_contas_id,
            rd.centro_custo_id,
            rd.os_id,
            rd.percentual,
            rd.valor
          ))
      )::bigint as duplicidades_exatas,
      jsonb_agg(
        jsonb_build_object(
          'id', rd.rateio_id,
          'planoId', rd.plano_contas_id,
          'planoCodigo', rd.plano_codigo,
          'planoNome', rd.plano_nome,
          'centroId', rd.centro_custo_id,
          'centroCodigo', rd.centro_codigo,
          'centroNome', rd.centro_nome,
          'osId', rd.os_id,
          'percentual', rd.percentual,
          'valor', rd.valor,
          'createdAt', rd.created_at,
          'updatedAt', rd.updated_at,
          'createdBy', rd.created_by
        )
        order by rd.created_at, rd.rateio_id
      ) filter (where rd.rateio_id is not null) as rateios
    from titulos t
    left join rateios_detalhe rd on rd.titulo_id = t.id
    group by t.id, t.valor_total
  )
  select
    t.id,
    t.tipo,
    t.status,
    t.origem,
    t.descricao,
    t.competencia_date,
    t.emissao_date,
    t.valor_total,
    e.quantidade_rateios,
    round(e.percentual_total, 4),
    round(e.valor_rateado, 2),
    round(e.valor_rateado - t.valor_total, 2),
    e.duplicidades_dimensao,
    e.duplicidades_exatas,
    t.motivo_plano_id,
    coalesce(e.rateios, '[]'::jsonb)
  from titulos t
  join estatisticas e on e.titulo_id = t.id
  where e.quantidade_rateios > 0
    and (
      e.percentual_total > 100.0001
      or e.valor_rateado > t.valor_total + 0.01
      or e.duplicidades_dimensao > 0
      or e.duplicidades_exatas > 0
    )
  order by
    greatest(e.valor_rateado - t.valor_total, 0) desc,
    t.id;
end;
$$;


ALTER FUNCTION "f"."preview_inconsistencias_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."preview_inconsistencias_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid") IS 'Auditoria somente leitura de rateios duplicados ou superiores ao titulo, sempre limitada a tenant e empresa.';



CREATE OR REPLACE FUNCTION "f"."preview_legado_implantacao_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_corte_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_corte date;
  v_result jsonb;
begin
  if p_tenant_id is null or p_empresa_id is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_id e empresa_id sao obrigatorios';
  end if;

  if auth.uid() is null and coalesce(auth.role(), '') <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado';
  end if;

  if auth.uid() is not null then
    if public.current_tenant_id() is distinct from p_tenant_id
       or public.current_empresa_id() is distinct from p_empresa_id
       or not f.has_finance_access(p_tenant_id, p_empresa_id) then
      raise exception using
        errcode = '42501',
        message = 'Sem permissao para o escopo informado';
    end if;
  end if;

  select coalesce(p_corte_date, cfg.data_inicio_confiabilidade_ap)
  into v_corte
  from f.fin_config cfg
  where cfg.tenant_id = p_tenant_id
    and cfg.empresa_id = p_empresa_id
    and cfg.deleted_at is null
  limit 1;

  v_corte := coalesce(v_corte, p_corte_date);
  if v_corte is null then
    raise exception using
      errcode = '22023',
      message = 'Data de corte de AP nao configurada';
  end if;

  with
  titulos_base as (
    select
      t.id,
      t.status,
      t.origem,
      t.descricao,
      t.valor_total,
      t.valor_aberto,
      t.emissao_date,
      t.competencia_date,
      t.created_at,
      count(tp.id) filter (where tp.valor_aberto > 0) as parcelas_abertas,
      coalesce(sum(tp.valor_aberto) filter (where tp.valor_aberto > 0), 0)
        as valor_parcelas_abertas,
      min(tp.vencimento_date) filter (where tp.valor_aberto > 0)
        as menor_vencimento,
      max(tp.vencimento_date) filter (where tp.valor_aberto > 0)
        as maior_vencimento,
      exists (
        select 1
        from f.titulo_parcela tp_pag
        join f.pagamento_item pi
          on pi.tenant_id = p_tenant_id
         and pi.empresa_id = p_empresa_id
         and pi.titulo_parcela_id = tp_pag.id
         and pi.deleted_at is null
        join f.pagamento pag
          on pag.tenant_id = p_tenant_id
         and pag.empresa_id = p_empresa_id
         and pag.id = pi.pagamento_id
         and pag.deleted_at is null
        where tp_pag.tenant_id = p_tenant_id
          and tp_pag.titulo_id = t.id
      ) as tem_pagamento,
      f.titulo_eh_legado_implantacao(
        p_tenant_id,
        p_empresa_id,
        t.id
      ) as ja_marcado
    from f.titulo t
    left join f.titulo_parcela tp
      on tp.tenant_id = p_tenant_id
     and tp.titulo_id = t.id
     and tp.deleted_at is null
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.tipo = 'AP'
      and t.status in ('PENDENTE', 'APROVADO', 'AGENDADO')
      and t.deleted_at is null
      and t.valor_aberto > 0
    group by t.id
  ),
  candidatos as (
    select *
    from titulos_base tb
    where tb.parcelas_abertas > 0
      and tb.maior_vencimento < v_corte
      and not tb.tem_pagamento
      and not tb.ja_marcado
  ),
  por_origem as (
    select jsonb_agg(
      jsonb_build_object(
        'origem', x.origem,
        'tituloQtd', x.titulo_qtd,
        'parcelaQtd', x.parcela_qtd,
        'valorAberto', round(x.valor_aberto, 2)
      )
      order by x.valor_aberto desc, x.origem
    ) as itens
    from (
      select
        coalesce(c.origem, 'NAO_INFORMADA') as origem,
        count(*) as titulo_qtd,
        sum(c.parcelas_abertas) as parcela_qtd,
        sum(c.valor_aberto) as valor_aberto
      from candidatos c
      group by coalesce(c.origem, 'NAO_INFORMADA')
    ) x
  ),
  amostra as (
    select jsonb_agg(
      jsonb_build_object(
        'tituloId', x.id,
        'status', x.status,
        'origem', x.origem,
        'descricao', x.descricao,
        'valorTotal', round(x.valor_total, 2),
        'valorAberto', round(x.valor_aberto, 2),
        'parcelaQtd', x.parcelas_abertas,
        'menorVencimento', x.menor_vencimento,
        'maiorVencimento', x.maior_vencimento,
        'emissao', x.emissao_date,
        'competencia', x.competencia_date
      )
      order by x.valor_aberto desc, x.id
    ) as itens
    from (
      select *
      from candidatos
      order by valor_aberto desc, id
      limit 100
    ) x
  )
  select jsonb_build_object(
    'corte', v_corte,
    'candidatos', jsonb_build_object(
      'tituloQtd', (select count(*) from candidatos),
      'parcelaQtd',
        coalesce((select sum(c.parcelas_abertas) from candidatos c), 0),
      'valorAberto',
        round(coalesce((select sum(c.valor_aberto) from candidatos c), 0), 2),
      'valorParcelasAberto',
        round(coalesce((
          select sum(c.valor_parcelas_abertas)
          from candidatos c
        ), 0), 2)
    ),
    'excluidos', jsonb_build_object(
      'comParcelaNoCorteOuDepois', (
        select count(*)
        from titulos_base tb
        where tb.parcelas_abertas > 0
          and tb.maior_vencimento >= v_corte
      ),
      'comPagamento', (
        select count(*)
        from titulos_base tb
        where tb.parcelas_abertas > 0
          and tb.maior_vencimento < v_corte
          and tb.tem_pagamento
      ),
      'jaMarcados', (
        select count(*)
        from titulos_base tb
        where tb.ja_marcado
      )
    ),
    'porOrigem', coalesce((select po.itens from por_origem po), '[]'::jsonb),
    'amostra', coalesce((select a.itens from amostra a), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "f"."preview_legado_implantacao_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_corte_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."provisionar_ap_recorrencia"("p_recorrencia_id" "uuid", "p_meses_a_frente" integer DEFAULT 12, "p_change_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_rec f.ap_recorrencia%rowtype;
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_usuario_id uuid;

  v_i integer;
  v_month_first date;
  v_venc date;
  v_valor numeric(15,2);

  v_count integer := 0;
  v_exists uuid;
  v_last_valor numeric(15,2);
begin
  if p_recorrencia_id is null then
    raise exception 'p_recorrencia_id obrigat3rio';
  end if;

  -- Auth: app ou SQL Editor
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  select * into v_rec
  from f.ap_recorrencia r
  where r.id = p_recorrencia_id
    and r.deleted_at is null
    and r.ativo = true;

  if not found then
    raise exception 'Recorr8ncia n3o encontrada/inativa';
  end if;

  v_tenant_id := v_rec.tenant_id;
  v_empresa_id := v_rec.empresa_id;

  if auth.uid() is not null then
    if not f.has_finance_access(v_tenant_id, v_empresa_id) then
      raise exception 'Sem permiss3o financeira';
    end if;
  end if;

  v_usuario_id := a.fn_current_usuario_id();

  if p_meses_a_frente is null or p_meses_a_frente < 0 then
    p_meses_a_frente := 0;
  end if;

  for v_i in 0..p_meses_a_frente loop
    v_month_first := f._month_first((current_date + (v_i || ' month')::interval)::date);

    -- evita duplicar por competencia
    select t.id into v_exists
    from f.titulo t
    where t.deleted_at is null
      and t.tenant_id = v_tenant_id
      and t.recorrencia_id = v_rec.id
      and t.competencia_date = v_month_first
    limit 1;

    if v_exists is not null then
      continue;
    end if;

    v_venc := f._safe_day_in_month(v_month_first, v_rec.dia_vencimento);

    v_valor := v_rec.valor_base;

    if v_rec.auto_copiar_valor then
      select t.valor_total
        into v_last_valor
      from f.titulo t
      where t.deleted_at is null
        and t.tenant_id = v_tenant_id
        and t.recorrencia_id = v_rec.id
        and t.competencia_date < v_month_first
      order by t.competencia_date desc nulls last
      limit 1;

      if v_last_valor is not null and v_last_valor > 0 then
        v_valor := v_last_valor;
      end if;
    end if;

    insert into f.titulo (
      tenant_id,
      empresa_id,
      tipo,
      status,
      fornecedor_id,
      descricao,
      emissao_date,
      competencia_date,
      valor_total,
      valor_aberto,
      recorrencia_id,
      motivo_compra_id,
      created_at,
      updated_at,
      created_by,
      updated_by,
      deleted_at
    ) values (
      v_tenant_id,
      v_empresa_id,
      'AP',
      'PENDENTE',
      v_rec.fornecedor_id,
      v_rec.descricao,
      current_date,
      v_month_first,
      v_valor,
      v_valor,
      v_rec.id,
      v_rec.motivo_compra_id,
      now(),
      now(),
      v_usuario_id,
      v_usuario_id,
      null
    ) returning id into v_exists;

    insert into f.titulo_parcela (
      tenant_id,
      titulo_id,
      numero,
      vencimento_date,
      valor,
      valor_aberto,
      created_at,
      updated_at,
      created_by,
      updated_by,
      deleted_at
    ) values (
      v_tenant_id,
      v_exists,
      '1',
      v_venc,
      v_valor,
      v_valor,
      now(),
      now(),
      v_usuario_id,
      v_usuario_id,
      null
    );

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "f"."provisionar_ap_recorrencia"("p_recorrencia_id" "uuid", "p_meses_a_frente" integer, "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."reabrir_inconsistencia_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_tipo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tipo text := upper(nullif(btrim(p_tipo), ''));
  v_tratamento f.inconsistencia_financeira_tratamento%rowtype;
  v_actor uuid := a.fn_current_usuario_id();
begin
  if p_tenant_id is null
     or p_empresa_id is null
     or p_titulo_id is null
     or v_tipo is null
  then
    raise exception using
      errcode = '22023',
      message = 'tenant_id, empresa_id, titulo_id e tipo sao obrigatorios.';
  end if;

  if auth.uid() is null
     and coalesce(auth.role(), '') <> 'service_role'
  then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado.';
  end if;

  if auth.uid() is not null
     and not f.pode_escrever_regras_rateio(
       p_tenant_id,
       p_empresa_id
     )
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para reabrir inconsistencias desta empresa.';
  end if;

  select trat.*
    into v_tratamento
  from f.inconsistencia_financeira_tratamento trat
  join f.titulo t
    on t.id = trat.titulo_id
   and t.tenant_id = trat.tenant_id
   and t.empresa_id = trat.empresa_id
  where trat.tenant_id = p_tenant_id
    and trat.empresa_id = p_empresa_id
    and trat.titulo_id = p_titulo_id
    and trat.tipo = v_tipo
    and trat.status = 'IGNORADA'
    and trat.deleted_at is null
  for update of trat;

  if not found then
    return jsonb_build_object(
      'tituloId', p_titulo_id,
      'tipo', v_tipo,
      'status', 'JA_ABERTA'
    );
  end if;

  update f.inconsistencia_financeira_tratamento trat
  set
    deleted_at = now(),
    updated_at = now(),
    updated_by = v_actor
  where trat.id = v_tratamento.id
    and trat.tenant_id = p_tenant_id
    and trat.empresa_id = p_empresa_id;

  insert into f.evento_financeiro (
    tenant_id,
    empresa_id,
    evento,
    ref_table,
    ref_id,
    payload,
    created_by
  )
  values (
    p_tenant_id,
    p_empresa_id,
    'INCONSISTENCIA_FINANCEIRA_REABERTA',
    'f.titulo',
    p_titulo_id,
    jsonb_build_object(
      'tipo', v_tipo,
      'fingerprintIgnorado', v_tratamento.fingerprint,
      'justificativaAnterior', v_tratamento.justificativa,
      'alterouTitulo', false,
      'alterouParcela', false,
      'alterouPagamento', false
    ),
    v_actor
  );

  return jsonb_build_object(
    'tituloId', p_titulo_id,
    'tipo', v_tipo,
    'status', 'ABERTA'
  );
end;
$$;


ALTER FUNCTION "f"."reabrir_inconsistencia_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_tipo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."reabrir_inconsistencia_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_tipo" "text") IS 'Remove a decisao atual de ignorar e registra a reabertura na auditoria financeira.';



CREATE OR REPLACE FUNCTION "f"."registrar_pagamento_ap"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor" numeric, "p_observacoes" "text" DEFAULT NULL::"text", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_cb f.conta_bancaria%rowtype;

  v_user uuid;
  v_pagamento_id uuid;

  v_restante numeric(15,2);
  v_alocar numeric(15,2);
  v_soma_aberto numeric(15,2);

  r record;
begin
  if p_valor is null or p_valor <= 0 then
    raise exception 'Valor de pagamento deve ser > 0';
  end if;

  if p_data_pagamento is null then
    raise exception 'Data de pagamento obrigatoria';
  end if;

  if p_forma_pagamento is null or length(trim(p_forma_pagamento)) = 0 then
    raise exception 'Forma de pagamento obrigatoria';
  end if;

  if p_forma_pagamento not in ('PIX','BOLETO','TRANSFERENCIA','DINHEIRO','CARTAO','OUTROS') then
    raise exception 'Forma de pagamento invalida: %', p_forma_pagamento;
  end if;

  -- auth: app ou SQL Editor (postgres/service_role)
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  -- fallback SQL Editor: pega um OWNER/ADMIN do tenant do título (depois que carregar título)
  -- (vamos carregar título antes de usar fallback)

  -- título
  select * into v_titulo
  from f.titulo
  where id = p_titulo_id
    and deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if v_titulo.tipo <> 'AP' then
    raise exception 'Pagamento so permite titulo AP. Tipo atual=%', v_titulo.tipo;
  end if;

  if v_titulo.status not in ('APROVADO','AGENDADO','PAGO') then
    raise exception 'Titulo precisa estar APROVADO/AGENDADO/PAGO para pagar. Status atual=%', v_titulo.status;
  end if;

  if v_titulo.valor_aberto <= 0 then
    raise exception 'Titulo sem saldo em aberto';
  end if;

  -- permissão no app
  if auth.uid() is not null then
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  -- fallback para SQL Editor caso fn_current_usuario_id() retorne null
  if v_user is null then
    select ut.usuario_id
      into v_user
    from a.usuario_tenant ut
    where ut.tenant_id = v_titulo.tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN')
    order by ut.created_at nulls last
    limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  -- conta bancária
  select * into v_cb
  from f.conta_bancaria
  where id = p_conta_bancaria_id
    and deleted_at is null;

  if not found then
    raise exception 'Conta bancaria nao encontrada (id=%)', p_conta_bancaria_id;
  end if;

  if v_cb.tenant_id <> v_titulo.tenant_id or v_cb.empresa_id <> v_titulo.empresa_id then
    raise exception 'Conta bancaria nao pertence ao mesmo tenant/empresa do titulo';
  end if;

  -- limita pagamento ao saldo aberto (proteção extra)
  if round(p_valor,2) > round(v_titulo.valor_aberto,2) then
    raise exception 'Pagamento (% ) maior que saldo em aberto do titulo (%)', round(p_valor,2), round(v_titulo.valor_aberto,2);
  end if;

  -- cria pagamento (cabeçalho)
  insert into f.pagamento (
    tenant_id, empresa_id,
    conta_bancaria_id,
    data_pagamento,
    forma_pagamento,
    valor,
    observacoes,
    pago_por,
    created_at, updated_at, created_by, updated_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    v_cb.id,
    p_data_pagamento,
    p_forma_pagamento,
    round(p_valor, 2),
    p_observacoes,
    v_user,
    now(), now(), v_user, v_user
  )
  returning id into v_pagamento_id;

  -- alocação: paga parcelas em aberto (ordem por vencimento)
  v_restante := round(p_valor, 2);

  for r in
    select id, valor_aberto
    from f.titulo_parcela
    where tenant_id = v_titulo.tenant_id
      and titulo_id = v_titulo.id
      and deleted_at is null
      and valor_aberto > 0
    order by vencimento_date asc, created_at asc
  loop
    exit when v_restante <= 0;

    v_alocar := least(r.valor_aberto, v_restante);

    insert into f.pagamento_item (
      tenant_id, pagamento_id, titulo_parcela_id, valor,
      created_at, created_by
    )
    values (
      v_titulo.tenant_id, v_pagamento_id, r.id, v_alocar,
      now(), v_user
    );

    update f.titulo_parcela
       set valor_aberto = round(valor_aberto - v_alocar, 2),
           updated_at = now(),
           updated_by = v_user
     where id = r.id;

    v_restante := round(v_restante - v_alocar, 2);
  end loop;

  if v_restante <> 0 then
    -- não deveria acontecer por causa do check contra saldo do título,
    -- mas mantém consistência
    raise exception 'Inconsistencia: restante=%', v_restante;
  end if;

  -- recalcula saldo do título
  select coalesce(sum(valor_aberto),0)::numeric(15,2)
    into v_soma_aberto
  from f.titulo_parcela
  where tenant_id = v_titulo.tenant_id
    and titulo_id = v_titulo.id
    and deleted_at is null;

  update f.titulo
     set valor_aberto = v_soma_aberto,
         status = case when v_soma_aberto = 0 then 'PAGO' else v_titulo.status end,
         updated_at = now(),
         updated_by = v_user
   where id = v_titulo.id;

  -- evento financeiro
  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    'PAGAMENTO_REGISTRADO',
    'f.pagamento',
    v_pagamento_id,
    jsonb_build_object(
      'titulo_id', v_titulo.id,
      'conta_bancaria_id', v_cb.id,
      'data_pagamento', p_data_pagamento,
      'forma_pagamento', p_forma_pagamento,
      'valor', round(p_valor,2),
      'saldo_titulo_pos', v_soma_aberto,
      'change_reason', p_change_reason
    ),
    now(), v_user
  );

  return v_pagamento_id;
end;
$$;


ALTER FUNCTION "f"."registrar_pagamento_ap"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor" numeric, "p_observacoes" "text", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."registrar_pagamento_ap_v2"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor_principal" numeric, "p_valor_juros" numeric DEFAULT 0, "p_valor_multa" numeric DEFAULT 0, "p_valor_desconto" numeric DEFAULT 0, "p_observacoes" "text" DEFAULT NULL::"text", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_cb f.conta_bancaria%rowtype;

  v_user uuid;
  v_pagamento_id uuid;

  v_total numeric(15,2);
  v_restante numeric(15,2);
  v_alocar numeric(15,2);
  v_soma_aberto numeric(15,2);

  r record;
begin
  if p_valor_principal is null or p_valor_principal <= 0 then
    raise exception 'Valor principal deve ser > 0';
  end if;

  if coalesce(p_valor_juros,0) < 0 or coalesce(p_valor_multa,0) < 0 or coalesce(p_valor_desconto,0) < 0 then
    raise exception 'Juros/Multa/Desconto não podem ser negativos';
  end if;

  if p_data_pagamento is null then
    raise exception 'Data de pagamento obrigatoria';
  end if;

  if p_forma_pagamento is null or length(trim(p_forma_pagamento)) = 0 then
    raise exception 'Forma de pagamento obrigatoria';
  end if;

  if p_forma_pagamento not in ('PIX','BOLETO','TRANSFERENCIA','DINHEIRO','CARTAO','OUTROS') then
    raise exception 'Forma de pagamento invalida: %', p_forma_pagamento;
  end if;

  -- auth: app ou SQL Editor (postgres/service_role)
  if auth.uid() is null then
    if current_user not in ('postgres','service_role') then
      raise exception 'Usuario nao autenticado';
    end if;
  end if;

  v_user := a.fn_current_usuario_id();

  select * into v_titulo
    from f.titulo
   where id = p_titulo_id
     and deleted_at is null;

  if not found then
    raise exception 'Titulo nao encontrado (id=%)', p_titulo_id;
  end if;

  if v_titulo.tipo <> 'AP' then
    raise exception 'Pagamento so permite titulo AP. Tipo atual=%', v_titulo.tipo;
  end if;

  if v_titulo.status not in ('APROVADO','AGENDADO','PAGO') then
    raise exception 'Titulo precisa estar APROVADO/AGENDADO/PAGO para pagar. Status atual=%', v_titulo.status;
  end if;

  if v_titulo.valor_aberto <= 0 then
    raise exception 'Titulo sem saldo em aberto';
  end if;

  -- permissão no app
  if auth.uid() is not null then
    if not f.has_finance_access(v_titulo.tenant_id, v_titulo.empresa_id) then
      raise exception 'Sem permissao: somente ADMIN/FINANCEIRO';
    end if;
  end if;

  -- fallback para SQL Editor caso fn_current_usuario_id() retorne null
  if v_user is null then
    select ut.usuario_id
      into v_user
      from a.usuario_tenant ut
     where ut.tenant_id = v_titulo.tenant_id
       and ut.ativo = true
       and ut.deleted_at is null
       and ut.papel in ('OWNER','ADMIN')
     order by ut.created_at nulls last
     limit 1;

    if v_user is null then
      raise exception 'Nao foi possivel determinar usuario executor. Execute pelo app.';
    end if;
  end if;

  select * into v_cb
    from f.conta_bancaria
   where id = p_conta_bancaria_id
     and deleted_at is null;

  if not found then
    raise exception 'Conta bancaria nao encontrada (id=%)', p_conta_bancaria_id;
  end if;

  if v_cb.tenant_id <> v_titulo.tenant_id or v_cb.empresa_id <> v_titulo.empresa_id then
    raise exception 'Conta bancaria nao pertence ao mesmo tenant/empresa do titulo';
  end if;

  -- principal não pode exceder saldo do título
  if round(p_valor_principal,2) > round(v_titulo.valor_aberto,2) then
    raise exception 'Principal (%) maior que saldo em aberto do titulo (%)', round(p_valor_principal,2), round(v_titulo.valor_aberto,2);
  end if;

  v_total := round((p_valor_principal + coalesce(p_valor_juros,0) + coalesce(p_valor_multa,0) - coalesce(p_valor_desconto,0)), 2);

  if v_total <= 0 then
    raise exception 'Total do pagamento deve ser > 0 (principal + juros + multa - desconto)';
  end if;

  insert into f.pagamento (
    tenant_id, empresa_id,
    conta_bancaria_id,
    data_pagamento,
    forma_pagamento,
    valor,
    valor_principal,
    valor_juros,
    valor_multa,
    valor_desconto,
    observacoes,
    change_reason,
    pago_por,
    created_at, updated_at, created_by, updated_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    v_cb.id,
    p_data_pagamento,
    p_forma_pagamento,
    v_total,
    round(p_valor_principal,2),
    round(coalesce(p_valor_juros,0),2),
    round(coalesce(p_valor_multa,0),2),
    round(coalesce(p_valor_desconto,0),2),
    p_observacoes,
    p_change_reason,
    v_user,
    now(), now(), v_user, v_user
  )
  returning id into v_pagamento_id;

  -- baixa parcelas usando SOMENTE o principal
  v_restante := round(p_valor_principal, 2);

  for r in
    select id, valor_aberto
      from f.titulo_parcela
     where tenant_id = v_titulo.tenant_id
       and titulo_id = v_titulo.id
       and deleted_at is null
       and valor_aberto > 0
     order by vencimento_date asc, created_at asc
  loop
    exit when v_restante <= 0;

    v_alocar := least(r.valor_aberto, v_restante);

    insert into f.pagamento_item (
      tenant_id, empresa_id,
      pagamento_id, titulo_parcela_id, valor,
      change_reason,
      created_at, created_by, updated_at, updated_by
    )
    values (
      v_titulo.tenant_id, v_titulo.empresa_id,
      v_pagamento_id, r.id, v_alocar,
      p_change_reason,
      now(), v_user, now(), v_user
    );

    update f.titulo_parcela
       set valor_aberto = round(valor_aberto - v_alocar, 2),
           updated_at = now(),
           updated_by = v_user
     where id = r.id;

    v_restante := round(v_restante - v_alocar, 2);
  end loop;

  if v_restante <> 0 then
    raise exception 'Inconsistencia: restante(principal)=%', v_restante;
  end if;

  select coalesce(sum(valor_aberto),0)::numeric(15,2)
    into v_soma_aberto
    from f.titulo_parcela
   where tenant_id = v_titulo.tenant_id
     and titulo_id = v_titulo.id
     and deleted_at is null;

  update f.titulo
     set valor_aberto = v_soma_aberto,
         status = case when v_soma_aberto = 0 then 'PAGO' else v_titulo.status end,
         updated_at = now(),
         updated_by = v_user
   where id = v_titulo.id;

  insert into f.evento_financeiro (
    tenant_id, empresa_id,
    evento, ref_table, ref_id,
    payload,
    created_at, created_by
  )
  values (
    v_titulo.tenant_id, v_titulo.empresa_id,
    'PAGAMENTO_REGISTRADO',
    'f.pagamento',
    v_pagamento_id,
    jsonb_build_object(
      'titulo_id', v_titulo.id,
      'conta_bancaria_id', v_cb.id,
      'data_pagamento', p_data_pagamento,
      'forma_pagamento', p_forma_pagamento,
      'valor_total', v_total,
      'valor_principal', round(p_valor_principal,2),
      'juros', round(coalesce(p_valor_juros,0),2),
      'multa', round(coalesce(p_valor_multa,0),2),
      'desconto', round(coalesce(p_valor_desconto,0),2),
      'saldo_titulo_pos', v_soma_aberto,
      'change_reason', p_change_reason
    ),
    now(), v_user
  );

  return v_pagamento_id;
end;
$$;


ALTER FUNCTION "f"."registrar_pagamento_ap_v2"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor_principal" numeric, "p_valor_juros" numeric, "p_valor_multa" numeric, "p_valor_desconto" numeric, "p_observacoes" "text", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."registrar_pagamento_ap_valor_final"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor_principal" numeric, "p_valor_juros" numeric DEFAULT 0, "p_valor_multa" numeric DEFAULT 0, "p_valor_desconto" numeric DEFAULT 0, "p_observacoes" "text" DEFAULT NULL::"text", "p_motivo_ajuste" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_parcela f.titulo_parcela%rowtype;
  v_pagamento_id uuid;
  v_novo_valor_final numeric(15,2);
begin
  if auth.uid() is not null then
    if p_tenant_id is distinct from public.current_tenant_id()
       or not f.has_finance_access(p_tenant_id, p_empresa_id) then
      raise exception 'Sem acesso financeiro ao tenant/empresa solicitado';
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role'
        and current_user not in ('postgres', 'service_role') then
    raise exception 'Usuario nao autenticado';
  end if;

  if nullif(btrim(coalesce(p_motivo_ajuste, '')), '') is null
     or length(btrim(p_motivo_ajuste)) < 5 then
    raise exception 'Informe o motivo da revisao (minimo 5 caracteres)';
  end if;

  select t.*
    into v_titulo
  from f.titulo t
  where t.id = p_titulo_id
    and t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id
    and t.tipo = 'AP'
    and t.deleted_at is null
  for update;

  if not found then
    raise exception 'Titulo AP nao encontrado no tenant/empresa informado';
  end if;

  select tp.*
    into v_parcela
  from f.titulo_parcela tp
  where tp.id = p_titulo_parcela_id
    and tp.tenant_id = p_tenant_id
    and tp.titulo_id = p_titulo_id
    and tp.deleted_at is null
  for update;

  if not found then
    raise exception 'Parcela nao encontrada para o titulo informado';
  end if;

  if round(coalesce(p_valor_principal, 0), 2) <= 0
     or round(p_valor_principal, 2) >= round(v_parcela.valor_aberto, 2) then
    raise exception 'Para confirmar valor final, o pagamento deve ser menor que o saldo da parcela';
  end if;

  if round(v_titulo.valor_aberto, 2) <> round(v_parcela.valor_aberto, 2) then
    raise exception 'Este titulo possui outras parcelas abertas. Registre o pagamento e revise a parcela separadamente';
  end if;

  v_novo_valor_final := round(v_parcela.valor - v_parcela.valor_aberto + p_valor_principal, 2);

  v_pagamento_id := f.registrar_pagamento_ap_v2(
    p_titulo_id,
    p_conta_bancaria_id,
    p_data_pagamento,
    p_forma_pagamento,
    p_valor_principal,
    coalesce(p_valor_juros, 0),
    coalesce(p_valor_multa, 0),
    coalesce(p_valor_desconto, 0),
    p_observacoes,
    'UI: pagamento com valor final confirmado'
  );

  perform f.revisar_valor_final_ap(
    p_tenant_id,
    p_empresa_id,
    p_titulo_id,
    p_titulo_parcela_id,
    v_novo_valor_final,
    p_motivo_ajuste,
    'PAGAMENTO_VALOR_FINAL'
  );

  return v_pagamento_id;
end;
$$;


ALTER FUNCTION "f"."registrar_pagamento_ap_valor_final"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor_principal" numeric, "p_valor_juros" numeric, "p_valor_multa" numeric, "p_valor_desconto" numeric, "p_observacoes" "text", "p_motivo_ajuste" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."registrar_pagamento_ap_valor_final"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor_principal" numeric, "p_valor_juros" numeric, "p_valor_multa" numeric, "p_valor_desconto" numeric, "p_observacoes" "text", "p_motivo_ajuste" "text") IS 'Registra pagamento menor que a previsao e encerra atomicamente a diferenca revisada.';



CREATE OR REPLACE FUNCTION "f"."registrar_recebimento_ar"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor" numeric, "p_observacoes" "text" DEFAULT NULL::"text", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c', 'm', 'r', 'auth', 'extensions'
    AS $$
declare
  v_pagamento_id uuid;
  v_titulo record;
  v_valor_restante numeric;
  v_parcela record;
  v_aplicado numeric;
  v_new_aberto numeric;
begin
  if p_titulo_id is null then
    raise exception 'p_titulo_id obrigatório';
  end if;
  if p_conta_bancaria_id is null then
    raise exception 'p_conta_bancaria_id obrigatório';
  end if;
  if p_data_pagamento is null then
    raise exception 'p_data_pagamento obrigatório';
  end if;
  if p_valor is null or p_valor <= 0 then
    raise exception 'p_valor deve ser > 0';
  end if;
  if p_forma_pagamento is null or length(trim(p_forma_pagamento)) = 0 then
    raise exception 'p_forma_pagamento obrigatório';
  end if;

  select *
    into v_titulo
  from f.titulo t
  where t.id = p_titulo_id
    and t.deleted_at is null;

  if not found then
    raise exception 'Título não encontrado';
  end if;

  if v_titulo.tipo <> 'AR' then
    raise exception 'Somente AR pode receber (tipo=%)', v_titulo.tipo;
  end if;

  if v_titulo.status not in ('APROVADO','AGENDADO','PAGO') then
    -- mirror AP function behaviour: require at least approved-ish.
    raise exception 'Status inválido para recebimento (status=%)', v_titulo.status;
  end if;

  if p_valor > v_titulo.valor_aberto then
    raise exception 'Valor maior que saldo em aberto';
  end if;

  insert into f.pagamento(
    tenant_id,
    empresa_id,
    conta_bancaria_id,
    data_pagamento,
    forma_pagamento,
    valor,
    observacoes,
    change_reason
  )
  values (
    v_titulo.tenant_id,
    v_titulo.empresa_id,
    p_conta_bancaria_id,
    p_data_pagamento,
    p_forma_pagamento,
    p_valor,
    p_observacoes,
    p_change_reason
  )
  returning id into v_pagamento_id;

  v_valor_restante := p_valor;

  for v_parcela in
    select p.id, p.valor_aberto
    from f.titulo_parcela p
    where p.titulo_id = p_titulo_id
      and p.deleted_at is null
      and p.valor_aberto > 0
    order by p.vencimento_date asc, p.numero asc
  loop
    exit when v_valor_restante <= 0;

    v_aplicado := least(v_parcela.valor_aberto, v_valor_restante);

    insert into f.pagamento_item(
      tenant_id,
      empresa_id,
      pagamento_id,
      titulo_parcela_id,
      valor,
      change_reason
    )
    values (
      v_titulo.tenant_id,
      v_titulo.empresa_id,
      v_pagamento_id,
      v_parcela.id,
      v_aplicado,
      p_change_reason
    );

    update f.titulo_parcela
      set valor_aberto = valor_aberto - v_aplicado
    where id = v_parcela.id;

    v_valor_restante := v_valor_restante - v_aplicado;
  end loop;

  select coalesce(sum(p.valor_aberto), 0)
    into v_new_aberto
  from f.titulo_parcela p
  where p.titulo_id = p_titulo_id
    and p.deleted_at is null;

  update f.titulo
    set valor_aberto = v_new_aberto,
        status = case when v_new_aberto <= 0 then 'PAGO' else v_titulo.status end
  where id = p_titulo_id;

  return v_pagamento_id;
end;
$$;


ALTER FUNCTION "f"."registrar_recebimento_ar"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor" numeric, "p_observacoes" "text", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."registrar_recebimento_ar_v2"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor_principal" numeric, "p_valor_juros" numeric DEFAULT 0, "p_valor_multa" numeric DEFAULT 0, "p_valor_desconto" numeric DEFAULT 0, "p_observacoes" "text" DEFAULT NULL::"text", "p_change_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_pagamento_id uuid;
  v_titulo record;
  v_total numeric(15,2);
  v_valor_restante numeric(15,2);
  v_parcela record;
  v_aplicado numeric(15,2);
  v_new_aberto numeric(15,2);
  v_user uuid;
begin
  if p_titulo_id is null then raise exception 'p_titulo_id obrigatorio'; end if;
  if p_conta_bancaria_id is null then raise exception 'p_conta_bancaria_id obrigatorio'; end if;
  if p_data_pagamento is null then raise exception 'p_data_pagamento obrigatorio'; end if;

  if p_valor_principal is null or p_valor_principal <= 0 then
    raise exception 'Valor principal deve ser > 0';
  end if;

  if coalesce(p_valor_juros,0) < 0 or coalesce(p_valor_multa,0) < 0 or coalesce(p_valor_desconto,0) < 0 then
    raise exception 'Juros/Multa/Desconto nao podem ser negativos';
  end if;

  if p_forma_pagamento is null or length(trim(p_forma_pagamento)) = 0 then
    raise exception 'p_forma_pagamento obrigatorio';
  end if;

  select *
    into v_titulo
    from f.titulo t
   where t.id = p_titulo_id
     and t.deleted_at is null;

  if not found then raise exception 'Titulo nao encontrado'; end if;

  if v_titulo.tipo <> 'AR' then
    raise exception 'Somente AR pode receber (tipo=%)', v_titulo.tipo;
  end if;

  -- Permite recebimento tambem quando AR estiver PENDENTE.
  if v_titulo.status not in ('PENDENTE','APROVADO','AGENDADO','PAGO') then
    raise exception 'Status invalido para recebimento (status=%)', v_titulo.status;
  end if;

  if round(p_valor_principal,2) > round(v_titulo.valor_aberto,2) then
    raise exception 'Principal (%) maior que saldo em aberto (%)', round(p_valor_principal,2), round(v_titulo.valor_aberto,2);
  end if;

  v_total := round((p_valor_principal + coalesce(p_valor_juros,0) + coalesce(p_valor_multa,0) - coalesce(p_valor_desconto,0)), 2);
  if v_total <= 0 then
    raise exception 'Total do recebimento deve ser > 0';
  end if;

  v_user := a.fn_current_usuario_id();

  insert into f.pagamento(
    tenant_id,
    empresa_id,
    conta_bancaria_id,
    data_pagamento,
    forma_pagamento,
    valor,
    valor_principal,
    valor_juros,
    valor_multa,
    valor_desconto,
    observacoes,
    change_reason,
    pago_por,
    created_at, updated_at, created_by, updated_by
  )
  values (
    v_titulo.tenant_id,
    v_titulo.empresa_id,
    p_conta_bancaria_id,
    p_data_pagamento,
    p_forma_pagamento,
    v_total,
    round(p_valor_principal,2),
    round(coalesce(p_valor_juros,0),2),
    round(coalesce(p_valor_multa,0),2),
    round(coalesce(p_valor_desconto,0),2),
    p_observacoes,
    p_change_reason,
    v_user,
    now(), now(), v_user, v_user
  )
  returning id into v_pagamento_id;

  v_valor_restante := round(p_valor_principal,2);

  for v_parcela in
    select p.id, p.valor_aberto
      from f.titulo_parcela p
     where p.titulo_id = p_titulo_id
       and p.deleted_at is null
       and p.valor_aberto > 0
     order by p.vencimento_date asc, p.numero asc
  loop
    exit when v_valor_restante <= 0;

    v_aplicado := least(v_parcela.valor_aberto, v_valor_restante);

    insert into f.pagamento_item(
      tenant_id,
      empresa_id,
      pagamento_id,
      titulo_parcela_id,
      valor,
      change_reason,
      created_at, created_by, updated_at, updated_by
    )
    values (
      v_titulo.tenant_id,
      v_titulo.empresa_id,
      v_pagamento_id,
      v_parcela.id,
      v_aplicado,
      p_change_reason,
      now(), v_user, now(), v_user
    );

    update f.titulo_parcela
       set valor_aberto = round(valor_aberto - v_aplicado,2),
           updated_at = now(),
           updated_by = v_user
     where id = v_parcela.id;

    v_valor_restante := round(v_valor_restante - v_aplicado,2);
  end loop;

  select coalesce(sum(p.valor_aberto), 0)::numeric(15,2)
    into v_new_aberto
    from f.titulo_parcela p
   where p.titulo_id = p_titulo_id
     and p.deleted_at is null;

  update f.titulo
     set valor_aberto = v_new_aberto,
         status = case when v_new_aberto <= 0 then 'PAGO' else v_titulo.status end,
         updated_at = now(),
         updated_by = v_user
   where id = p_titulo_id;

  return v_pagamento_id;
end;
$$;


ALTER FUNCTION "f"."registrar_recebimento_ar_v2"("p_titulo_id" "uuid", "p_conta_bancaria_id" "uuid", "p_data_pagamento" "date", "p_forma_pagamento" "text", "p_valor_principal" numeric, "p_valor_juros" numeric, "p_valor_multa" numeric, "p_valor_desconto" numeric, "p_observacoes" "text", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."registrar_transferencia_bancaria"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_conta_origem_id" "uuid", "p_conta_destino_id" "uuid", "p_data_movimento" "date", "p_valor" numeric, "p_descricao" "text" DEFAULT NULL::"text") RETURNS TABLE("transferencia_id" "uuid", "linha_saida_id" "uuid", "linha_entrada_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_transferencia_id uuid := gen_random_uuid();
  v_extrato_origem_id uuid;
  v_extrato_destino_id uuid;
  v_linha_saida_id uuid;
  v_linha_entrada_id uuid;
  v_origem f.conta_bancaria%rowtype;
  v_destino f.conta_bancaria%rowtype;
  v_descricao text := coalesce(nullif(btrim(p_descricao), ''), 'Transferencia entre contas');
  v_referencia text;
begin
  if auth.uid() is null then
    raise exception 'Usuario nao autenticado';
  end if;

  if p_tenant_id is null
     or p_tenant_id is distinct from public.current_tenant_id() then
    raise exception 'Tenant invalido para a sessao atual';
  end if;

  if p_empresa_id is null
     or p_empresa_id is distinct from public.current_empresa_id()
     or not f.has_finance_access(p_tenant_id, p_empresa_id) then
    raise exception 'Sem acesso financeiro a empresa selecionada';
  end if;

  if not (
    public.has_permission('financeiro.write')
    or public.has_permission('admin.manage_users')
    or public.has_permission('admin.all')
  ) then
    raise exception 'Sem permissao para registrar transferencias';
  end if;

  if p_conta_origem_id is null or p_conta_destino_id is null then
    raise exception 'Informe as contas de origem e destino';
  end if;

  if p_conta_origem_id = p_conta_destino_id then
    raise exception 'As contas de origem e destino devem ser diferentes';
  end if;

  if p_data_movimento is null then
    raise exception 'Informe a data da transferencia';
  end if;

  if p_valor is null or round(p_valor, 2) <= 0 then
    raise exception 'O valor da transferencia deve ser maior que zero';
  end if;

  if length(v_descricao) > 500 then
    raise exception 'A descricao deve ter no maximo 500 caracteres';
  end if;

  -- Ordem deterministica evita deadlock em transferencias simultaneas e inversas.
  perform cb.id
  from f.conta_bancaria cb
  where cb.id in (p_conta_origem_id, p_conta_destino_id)
    and cb.tenant_id = p_tenant_id
    and cb.empresa_id = p_empresa_id
    and cb.ativo = true
    and cb.deleted_at is null
  order by cb.id
  for update;

  select cb.*
    into v_origem
  from f.conta_bancaria cb
  where cb.id = p_conta_origem_id
    and cb.tenant_id = p_tenant_id
    and cb.empresa_id = p_empresa_id
    and cb.ativo = true
    and cb.deleted_at is null;

  if not found then
    raise exception 'Conta de origem nao encontrada ou inativa';
  end if;

  select cb.*
    into v_destino
  from f.conta_bancaria cb
  where cb.id = p_conta_destino_id
    and cb.tenant_id = p_tenant_id
    and cb.empresa_id = p_empresa_id
    and cb.ativo = true
    and cb.deleted_at is null;

  if not found then
    raise exception 'Conta de destino nao encontrada ou inativa';
  end if;

  v_referencia := 'TRANSFERENCIA:' || v_transferencia_id::text;

  insert into f.extrato_bancario (
    tenant_id,
    empresa_id,
    conta_bancaria_id,
    fonte,
    referencia,
    periodo_inicio,
    periodo_fim,
    observacoes
  ) values (
    p_tenant_id,
    p_empresa_id,
    p_conta_origem_id,
    'MANUAL',
    v_referencia,
    p_data_movimento,
    p_data_movimento,
    'Saida de transferencia bancaria registrada pelo sistema.'
  ) returning id into v_extrato_origem_id;

  insert into f.extrato_bancario (
    tenant_id,
    empresa_id,
    conta_bancaria_id,
    fonte,
    referencia,
    periodo_inicio,
    periodo_fim,
    observacoes
  ) values (
    p_tenant_id,
    p_empresa_id,
    p_conta_destino_id,
    'MANUAL',
    v_referencia,
    p_data_movimento,
    p_data_movimento,
    'Entrada de transferencia bancaria registrada pelo sistema.'
  ) returning id into v_extrato_destino_id;

  insert into f.extrato_bancario_linha (
    tenant_id,
    extrato_bancario_id,
    conta_bancaria_id,
    data_movimento,
    descricao,
    documento,
    fit_id,
    valor,
    status,
    observacoes
  ) values (
    p_tenant_id,
    v_extrato_origem_id,
    p_conta_origem_id,
    p_data_movimento,
    v_descricao || ' - SAIDA PARA ' || v_destino.codigo || ' ' || v_destino.nome,
    'TRANSFERENCIA',
    v_referencia || ':SAIDA',
    -round(p_valor, 2),
    'PENDENTE',
    'Transferencia ' || v_transferencia_id::text
  ) returning id into v_linha_saida_id;

  insert into f.extrato_bancario_linha (
    tenant_id,
    extrato_bancario_id,
    conta_bancaria_id,
    data_movimento,
    descricao,
    documento,
    fit_id,
    valor,
    status,
    observacoes
  ) values (
    p_tenant_id,
    v_extrato_destino_id,
    p_conta_destino_id,
    p_data_movimento,
    v_descricao || ' - ENTRADA DE ' || v_origem.codigo || ' ' || v_origem.nome,
    'TRANSFERENCIA',
    v_referencia || ':ENTRADA',
    round(p_valor, 2),
    'PENDENTE',
    'Transferencia ' || v_transferencia_id::text
  ) returning id into v_linha_entrada_id;

  insert into f.transferencia_bancaria (
    id,
    tenant_id,
    empresa_id,
    conta_origem_id,
    conta_destino_id,
    data_movimento,
    valor,
    descricao,
    status,
    linha_saida_id,
    linha_entrada_id
  ) values (
    v_transferencia_id,
    p_tenant_id,
    p_empresa_id,
    p_conta_origem_id,
    p_conta_destino_id,
    p_data_movimento,
    round(p_valor, 2),
    v_descricao,
    'EFETIVADA',
    v_linha_saida_id,
    v_linha_entrada_id
  );

  insert into f.evento_financeiro (
    tenant_id,
    empresa_id,
    evento,
    ref_table,
    ref_id,
    payload
  ) values (
    p_tenant_id,
    p_empresa_id,
    'TRANSFERENCIA_BANCARIA_REGISTRADA',
    'f.transferencia_bancaria',
    v_transferencia_id,
    jsonb_build_object(
      'data_movimento', p_data_movimento,
      'valor', round(p_valor, 2),
      'descricao', v_descricao,
      'origem_id', p_conta_origem_id,
      'origem_codigo', v_origem.codigo,
      'origem_nome', v_origem.nome,
      'destino_id', p_conta_destino_id,
      'destino_codigo', v_destino.codigo,
      'destino_nome', v_destino.nome,
      'linha_saida_id', v_linha_saida_id,
      'linha_entrada_id', v_linha_entrada_id
    )
  );

  return query
  select v_transferencia_id, v_linha_saida_id, v_linha_entrada_id;
end;
$$;


ALTER FUNCTION "f"."registrar_transferencia_bancaria"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_conta_origem_id" "uuid", "p_conta_destino_id" "uuid", "p_data_movimento" "date", "p_valor" numeric, "p_descricao" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."registrar_transferencia_bancaria"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_conta_origem_id" "uuid", "p_conta_destino_id" "uuid", "p_data_movimento" "date", "p_valor" numeric, "p_descricao" "text") IS 'Registra atomicamente a saida, a entrada, o cabecalho e a auditoria da transferencia.';



CREATE OR REPLACE FUNCTION "f"."relatorio_saude_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'r', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_data_anterior_inicio date;
  v_data_anterior_fim date;
  v_serie_inicio date;
  v_competencia jsonb;
  v_caixa jsonb;
  v_compromissos jsonb;
  v_qualidade jsonb;
begin
  if p_tenant_id is null
     or p_empresa_id is null
     or p_data_inicio is null
     or p_data_fim is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_id, empresa_id e período são obrigatórios';
  end if;

  if p_data_fim < p_data_inicio then
    raise exception using
      errcode = '22023',
      message = 'Data final não pode ser anterior à data inicial';
  end if;

  if (p_data_fim - p_data_inicio) > 366 then
    raise exception using
      errcode = '22023',
      message = 'O período máximo permitido é de 367 dias';
  end if;

  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado';
  end if;

  if not exists (
    select 1
    from c.empresa e
    where e.id = p_empresa_id
      and e.tenant_id = p_tenant_id
      and e.deleted_at is null
  ) then
    raise exception using
      errcode = '22023',
      message = 'Empresa não encontrada no tenant informado';
  end if;

  if public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id() is distinct from p_empresa_id then
    raise exception using
      errcode = '42501',
      message = 'Tenant ou empresa não corresponde ao contexto ativo';
  end if;

  if not f.has_finance_access(p_tenant_id, p_empresa_id) then
    raise exception using
      errcode = '42501',
      message = 'Sem permissão para acessar relatórios financeiros';
  end if;

  v_data_anterior_fim := p_data_inicio - 1;
  if p_data_inicio = date_trunc('month', p_data_inicio)::date
     and p_data_fim =
       (date_trunc('month', p_data_inicio) + interval '1 month - 1 day')::date then
    v_data_anterior_inicio := (p_data_inicio - interval '1 month')::date;
  elsif extract(month from p_data_inicio) = 1
     and extract(day from p_data_inicio) = 1
     and p_data_fim = make_date(extract(year from p_data_inicio)::integer, 12, 31) then
    v_data_anterior_inicio := make_date(
      extract(year from p_data_inicio)::integer - 1,
      1,
      1
    );
  else
    v_data_anterior_inicio :=
      p_data_inicio - ((p_data_fim - p_data_inicio) + 1);
  end if;
  v_serie_inicio :=
    (date_trunc('month', p_data_fim)::date - interval '11 months')::date;

  /*
   * Competência
   *
   * O resultado segue a regra da DRE gerencial atual: somente rateios entram
   * no resultado e planos em r.dre_plano_excluido são investimentos.
   */
  with
  titulos as (
    select
      t.id,
      t.tipo,
      t.status,
      t.fornecedor_id,
      t.cliente_id,
      t.descricao,
      t.competencia_date,
      t.valor_total,
      t.valor_aberto,
      t.arrendamento_contrato_id,
      coalesce(ta.motivo_compra_id, t.motivo_compra_id) as motivo_id,
      coalesce(mc.codigo, 'NAO_CLASSIFICADO') as motivo_codigo,
      coalesce(mc.nome, 'Não classificado') as motivo_nome
    from f.titulo t
    left join f.titulo_aprovacao ta
      on ta.tenant_id = p_tenant_id
     and ta.titulo_id = t.id
     and ta.deleted_at is null
    left join f.motivo_compra mc
      on mc.tenant_id = p_tenant_id
     and mc.id = coalesce(ta.motivo_compra_id, t.motivo_compra_id)
     and mc.deleted_at is null
     and mc.ativo
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.deleted_at is null
      and t.status <> 'CANCELADO'
      and t.competencia_date between
        least(v_data_anterior_inicio, v_serie_inicio)
        and p_data_fim
  ),
  rateios as (
    select
      t.*,
      tr.id as rateio_id,
      tr.plano_contas_id,
      tr.centro_custo_id,
      coalesce(
        tr.valor,
        round(t.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
        0
      ) as valor_alocado,
      coalesce(pc.codigo, 'SEM_PLANO') as plano_codigo,
      coalesce(pc.nome, 'Sem plano de contas') as plano_nome,
      coalesce(cc.codigo, 'SEM_CENTRO') as centro_codigo,
      coalesce(cc.nome, 'Sem centro de custo') as centro_nome,
      (pc.id is not null and pc.ativo) as plano_valido,
      exists (
        select 1
        from r.dre_plano_excluido dpe
        where dpe.tenant_id = p_tenant_id
          and dpe.plano_contas_id = tr.plano_contas_id
      ) as investimento_plano
    from titulos t
    join f.titulo_rateio tr
      on tr.tenant_id = p_tenant_id
     and tr.titulo_id = t.id
     and tr.deleted_at is null
    left join f.plano_contas pc
      on pc.tenant_id = p_tenant_id
     and pc.id = tr.plano_contas_id
     and pc.deleted_at is null
    left join f.centro_custo cc
      on cc.tenant_id = p_tenant_id
     and cc.empresa_id = p_empresa_id
     and cc.id = tr.centro_custo_id
     and cc.deleted_at is null
  ),
  alocacoes as (
    select
      r.*,
      true as possui_rateio,
      r.investimento_plano as investimento,
      (
        r.plano_codigo = 'DESP_FINANCIAMENTO'
        or r.motivo_codigo = 'FINANCIAMENTO_RURAL'
        or exists (
          select 1
          from f.arrendamento_contrato ac_scope
          where ac_scope.id = r.arrendamento_contrato_id
            and ac_scope.tenant_id = p_tenant_id
            and ac_scope.empresa_id = p_empresa_id
            and ac_scope.deleted_at is null
        )
      ) as divida
    from rateios r

    union all

    select
      t.*,
      null::uuid as rateio_id,
      null::uuid as plano_contas_id,
      null::uuid as centro_custo_id,
      t.valor_total as valor_alocado,
      'SEM_PLANO'::text as plano_codigo,
      'Sem plano de contas'::text as plano_nome,
      'SEM_CENTRO'::text as centro_codigo,
      'Sem centro de custo'::text as centro_nome,
      false as plano_valido,
      false as investimento_plano,
      false as possui_rateio,
      (t.motivo_codigo = 'INVESTIMENTO') as investimento,
      (
        t.motivo_codigo = 'FINANCIAMENTO_RURAL'
        or exists (
          select 1
          from f.arrendamento_contrato ac_scope
          where ac_scope.id = t.arrendamento_contrato_id
            and ac_scope.tenant_id = p_tenant_id
            and ac_scope.empresa_id = p_empresa_id
            and ac_scope.deleted_at is null
        )
      ) as divida
    from titulos t
    where not exists (
      select 1
      from f.titulo_rateio tr
      where tr.tenant_id = p_tenant_id
        and tr.titulo_id = t.id
        and tr.deleted_at is null
    )
  ),
  resultado_mes as (
    select
      a.competencia_date,
      sum(
        case
          when a.tipo = 'AR'
           and a.possui_rateio
           and a.plano_valido
           and not a.investimento_plano
          then a.valor_alocado
          else 0
        end
      ) as receita,
      sum(
        case
          when a.tipo = 'AP'
           and a.possui_rateio
           and a.plano_valido
           and not a.investimento_plano
          then a.valor_alocado
          else 0
        end
      ) as despesa
    from alocacoes a
    group by a.competencia_date
  ),
  atual as (
    select
      coalesce(sum(rm.receita), 0) as receita,
      coalesce(sum(rm.despesa), 0) as despesa
    from resultado_mes rm
    where rm.competencia_date between p_data_inicio and p_data_fim
  ),
  anterior as (
    select
      coalesce(sum(rm.receita), 0) as receita,
      coalesce(sum(rm.despesa), 0) as despesa
    from resultado_mes rm
    where rm.competencia_date
      between v_data_anterior_inicio and v_data_anterior_fim
  ),
  meses as (
    select generate_series(
      v_serie_inicio::timestamp,
      date_trunc('month', p_data_fim)::timestamp,
      interval '1 month'
    )::date as mes
  ),
  serie as (
    select
      m.mes,
      coalesce(rm.receita, 0) as receita,
      coalesce(rm.despesa, 0) as despesa
    from meses m
    left join resultado_mes rm on rm.competencia_date = m.mes
  ),
  plano_resumo as (
    select
      a.plano_contas_id,
      a.plano_codigo,
      a.plano_nome,
      sum(a.valor_alocado) as valor
    from alocacoes a
    where a.tipo = 'AP'
      and a.competencia_date between p_data_inicio and p_data_fim
    group by a.plano_contas_id, a.plano_codigo, a.plano_nome
  ),
  motivo_resumo as (
    select
      t.motivo_id,
      t.motivo_codigo,
      t.motivo_nome,
      sum(t.valor_total) as valor
    from titulos t
    where t.tipo = 'AP'
      and t.competencia_date between p_data_inicio and p_data_fim
    group by t.motivo_id, t.motivo_codigo, t.motivo_nome
  ),
  centro_resumo as (
    select
      a.centro_custo_id,
      a.centro_codigo,
      a.centro_nome,
      sum(a.valor_alocado) as valor
    from alocacoes a
    where a.tipo = 'AP'
      and a.competencia_date between p_data_inicio and p_data_fim
    group by a.centro_custo_id, a.centro_codigo, a.centro_nome
  ),
  fornecedor_resumo as (
    select
      t.fornecedor_id,
      coalesce(forn.nome, 'Sem fornecedor') as nome,
      count(*) as quantidade,
      sum(t.valor_total) as valor
    from titulos t
    left join public.fornecedores forn
      on forn.tenant_id = p_tenant_id
     and forn.empresa_id = p_empresa_id
     and forn.id = t.fornecedor_id
    where t.tipo = 'AP'
      and t.competencia_date between p_data_inicio and p_data_fim
    group by t.fornecedor_id, coalesce(forn.nome, 'Sem fornecedor')
  ),
  plano_cobertura as (
    select
      t.id,
      t.valor_total,
      coalesce(
        sum(case when r.plano_valido then r.valor_alocado else 0 end),
        0
      ) as valor_classificado
    from titulos t
    left join rateios r on r.id = t.id
    where t.tipo = 'AP'
      and t.competencia_date between p_data_inicio and p_data_fim
    group by t.id, t.valor_total
  ),
  extras_titulo as (
    select
      t.id,
      t.competencia_date,
      case
        when count(r.rateio_id) > 0 then least(
          greatest(t.valor_total, 0),
          coalesce(sum(case when r.investimento_plano then r.valor_alocado else 0 end), 0)
        )
        when t.motivo_codigo = 'INVESTIMENTO' then greatest(t.valor_total, 0)
        else 0
      end as investimento,
      case
        when t.motivo_codigo = 'FINANCIAMENTO_RURAL'
          or exists (
            select 1
            from f.arrendamento_contrato ac_scope
            where ac_scope.id = t.arrendamento_contrato_id
              and ac_scope.tenant_id = p_tenant_id
              and ac_scope.empresa_id = p_empresa_id
              and ac_scope.deleted_at is null
          ) then greatest(t.valor_total, 0)
        else least(
          greatest(t.valor_total, 0),
          coalesce(sum(case when r.plano_codigo = 'DESP_FINANCIAMENTO' then r.valor_alocado else 0 end), 0)
        )
      end as divida
    from titulos t
    left join rateios r on r.id = t.id
    where t.tipo = 'AP'
    group by
      t.id,
      t.competencia_date,
      t.valor_total,
      t.motivo_codigo,
      t.arrendamento_contrato_id
  ),
  extras_atual as (
    select
      coalesce(sum(et.investimento), 0) as investimentos,
      coalesce(sum(et.divida), 0) as divida_identificada
    from extras_titulo et
    where et.competencia_date between p_data_inicio and p_data_fim
  ),
  extras_anterior as (
    select
      coalesce(sum(et.investimento), 0) as investimentos,
      coalesce(sum(et.divida), 0) as divida_identificada
    from extras_titulo et
    where et.competencia_date
      between v_data_anterior_inicio and v_data_anterior_fim
  ),
  ap_atual as (
    select
      coalesce(sum(t.valor_total), 0) as total_ap,
      count(*) as quantidade
    from titulos t
    where t.tipo = 'AP'
      and t.competencia_date between p_data_inicio and p_data_fim
  ),
  ap_anterior as (
    select coalesce(sum(t.valor_total), 0) as total_ap
    from titulos t
    where t.tipo = 'AP'
      and t.competencia_date
        between v_data_anterior_inicio and v_data_anterior_fim
  ),
  nao_classificado as (
    select coalesce(sum(
      greatest(
        coalesce(pc.valor_total, 0)
          - least(
              greatest(coalesce(pc.valor_classificado, 0), 0),
              greatest(coalesce(pc.valor_total, 0), 0)
            ),
        0
      )
    ), 0) as valor
    from plano_cobertura pc
  )
  select jsonb_build_object(
    'receita', round(at.receita, 2),
    'despesa', round(at.despesa, 2),
    'resultado', round(at.receita - at.despesa, 2),
    'margem', case
      when at.receita = 0 then null
      else round(((at.receita - at.despesa) / at.receita) * 100, 2)
    end,
    'investimentos', round(ea.investimentos, 2),
    'dividaIdentificada', round(ea.divida_identificada, 2),
    'totalAp', round(apa.total_ap, 2),
    'quantidadeAp', apa.quantidade,
    'naoClassificado', round(nc.valor, 2),
    'anterior', jsonb_build_object(
      'receita', round(an.receita, 2),
      'despesa', round(an.despesa, 2),
      'resultado', round(an.receita - an.despesa, 2),
      'margem', case
        when an.receita = 0 then null
        else round(((an.receita - an.despesa) / an.receita) * 100, 2)
      end,
      'investimentos', round(ean.investimentos, 2),
      'dividaIdentificada', round(ean.divida_identificada, 2),
      'totalAp', round(apan.total_ap, 2)
    ),
    'serie', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'label', to_char(s.mes, 'MM/YYYY'),
          'mes', s.mes,
          'receita', round(s.receita, 2),
          'despesa', round(s.despesa, 2),
          'resultado', round(s.receita - s.despesa, 2)
        )
        order by s.mes
      )
      from serie s
    ), '[]'::jsonb),
    'porPlano', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', x.plano_contas_id,
          'codigo', x.plano_codigo,
          'nome', x.plano_nome,
          'valor', round(x.valor, 2),
          'percentual', case
            when apa.total_ap = 0 then 0
            else round((x.valor / apa.total_ap) * 100, 2)
          end
        )
        order by x.valor desc, x.plano_nome
      )
      from (
        select pr.*
        from plano_resumo pr
        order by pr.valor desc
        limit 12
      ) x
    ), '[]'::jsonb),
    'porMotivo', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', x.motivo_id,
          'codigo', x.motivo_codigo,
          'nome', x.motivo_nome,
          'valor', round(x.valor, 2),
          'percentual', case
            when apa.total_ap = 0 then 0
            else round((x.valor / apa.total_ap) * 100, 2)
          end
        )
        order by x.valor desc, x.motivo_nome
      )
      from (
        select mr.*
        from motivo_resumo mr
        order by mr.valor desc
        limit 12
      ) x
    ), '[]'::jsonb),
    'porCentro', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', x.centro_custo_id,
          'codigo', x.centro_codigo,
          'nome', x.centro_nome,
          'valor', round(x.valor, 2),
          'percentual', case
            when apa.total_ap = 0 then 0
            else round((x.valor / apa.total_ap) * 100, 2)
          end
        )
        order by x.valor desc, x.centro_nome
      )
      from (
        select cr.*
        from centro_resumo cr
        order by cr.valor desc
        limit 12
      ) x
    ), '[]'::jsonb),
    'topFornecedores', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'fornecedorId', x.fornecedor_id,
          'nome', x.nome,
          'quantidade', x.quantidade,
          'valor', round(x.valor, 2),
          'percentual', case
            when apa.total_ap = 0 then 0
            else round((x.valor / apa.total_ap) * 100, 2)
          end
        )
        order by x.valor desc, x.nome
      )
      from (
        select fr.*
        from fornecedor_resumo fr
        order by fr.valor desc
        limit 10
      ) x
    ), '[]'::jsonb)
  )
  into v_competencia
  from atual at
  cross join anterior an
  cross join extras_atual ea
  cross join extras_anterior ean
  cross join ap_atual apa
  cross join ap_anterior apan
  cross join nao_classificado nc;

  /*
   * Caixa
   *
   * Cada cabeçalho é rateado entre seus itens pela participação no valor
   * aplicado, evitando multiplicação em pagamentos com várias parcelas.
   */
  with
  pagamentos as (
    select
      p.id,
      p.data_pagamento,
      p.valor,
      p.valor_principal,
      p.valor_juros,
      p.valor_multa,
      p.valor_desconto,
      p.conciliado_at
    from f.pagamento p
    where p.tenant_id = p_tenant_id
      and p.empresa_id = p_empresa_id
      and p.deleted_at is null
      and p.data_pagamento between
        least(v_data_anterior_inicio, v_serie_inicio)
        and p_data_fim
  ),
  itens as (
    select
      p.id as pagamento_id,
      p.data_pagamento,
      p.valor,
      p.valor_principal,
      p.valor_juros,
      p.valor_multa,
      p.valor_desconto,
      p.conciliado_at,
      t.id as titulo_id,
      t.tipo,
      t.fornecedor_id,
      t.arrendamento_contrato_id,
      coalesce(ta.motivo_compra_id, t.motivo_compra_id) as motivo_id,
      coalesce(mc.codigo, 'NAO_CLASSIFICADO') as motivo_codigo,
      coalesce(mc.nome, 'Não classificado') as motivo_nome,
      sum(pi.valor) as valor_aplicado
    from pagamentos p
    join f.pagamento_item pi
      on pi.tenant_id = p_tenant_id
     and pi.empresa_id = p_empresa_id
     and pi.pagamento_id = p.id
     and pi.deleted_at is null
    join f.titulo_parcela tp
      on tp.tenant_id = p_tenant_id
     and tp.id = pi.titulo_parcela_id
     and tp.deleted_at is null
    join f.titulo t
      on t.tenant_id = p_tenant_id
     and t.empresa_id = p_empresa_id
     and t.id = tp.titulo_id
     and t.deleted_at is null
     and t.status <> 'CANCELADO'
    left join f.titulo_aprovacao ta
      on ta.tenant_id = p_tenant_id
     and ta.titulo_id = t.id
     and ta.deleted_at is null
    left join f.motivo_compra mc
      on mc.tenant_id = p_tenant_id
     and mc.id = coalesce(ta.motivo_compra_id, t.motivo_compra_id)
     and mc.deleted_at is null
     and mc.ativo
    group by
      p.id,
      p.data_pagamento,
      p.valor,
      p.valor_principal,
      p.valor_juros,
      p.valor_multa,
      p.valor_desconto,
      p.conciliado_at,
      t.id,
      t.tipo,
      t.fornecedor_id,
      t.arrendamento_contrato_id,
      coalesce(ta.motivo_compra_id, t.motivo_compra_id),
      coalesce(mc.codigo, 'NAO_CLASSIFICADO'),
      coalesce(mc.nome, 'Não classificado')
  ),
  totais_pagamento as (
    select
      p.id as pagamento_id,
      coalesce(sum(pi.valor), 0) as valor_aplicado_total
    from pagamentos p
    left join f.pagamento_item pi
      on pi.pagamento_id = p.id
     and pi.deleted_at is null
    group by p.id
  ),
  titulos_caixa as (
    select distinct
      i.titulo_id,
      i.motivo_codigo,
      i.arrendamento_contrato_id
    from itens i
  ),
  classificacao_titulo as (
    select
      tc.titulo_id,
      t.valor_total as valor_titulo,
      coalesce(sum(
        case
          when exists (
            select 1
            from r.dre_plano_excluido dpe
            where dpe.tenant_id = p_tenant_id
              and dpe.plano_contas_id = tr.plano_contas_id
          )
          then coalesce(
            tr.valor,
            round(t.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
            0
          )
          else 0
        end
      ), 0) as valor_investimento,
      coalesce(sum(
        case
          when pc.codigo = 'DESP_FINANCIAMENTO'
            or tc.motivo_codigo = 'FINANCIAMENTO_RURAL'
            or exists (
          select 1
          from f.arrendamento_contrato ac_scope
          where ac_scope.id = tc.arrendamento_contrato_id
            and ac_scope.tenant_id = p_tenant_id
            and ac_scope.empresa_id = p_empresa_id
            and ac_scope.deleted_at is null
        )
          then coalesce(
            tr.valor,
            round(t.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
            0
          )
          else 0
        end
      ), 0) as valor_divida,
      coalesce(sum(coalesce(
        tr.valor,
        round(t.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
        0
      )), 0) as valor_rateado,
      count(tr.id) as quantidade_rateios
    from titulos_caixa tc
    join f.titulo t
      on t.tenant_id = p_tenant_id
     and t.empresa_id = p_empresa_id
     and t.id = tc.titulo_id
     and t.deleted_at is null
    left join f.titulo_rateio tr
      on tr.tenant_id = p_tenant_id
     and tr.titulo_id = t.id
     and tr.deleted_at is null
    left join f.plano_contas pc
      on pc.tenant_id = p_tenant_id
     and pc.id = tr.plano_contas_id
     and pc.deleted_at is null
    group by
      tc.titulo_id,
      t.valor_total,
      tc.motivo_codigo,
      tc.arrendamento_contrato_id
  ),
  linhas as (
    select
      i.*,
      case
        when tp.valor_aplicado_total = 0 then 0
        else i.valor * i.valor_aplicado / tp.valor_aplicado_total
      end as valor_movimento,
      case
        when tp.valor_aplicado_total = 0 then 0
        else i.valor_juros * i.valor_aplicado / tp.valor_aplicado_total
      end as juros_movimento,
      case
        when tp.valor_aplicado_total = 0 then 0
        else i.valor_multa * i.valor_aplicado / tp.valor_aplicado_total
      end as multa_movimento,
      case
        when tp.valor_aplicado_total = 0 then 0
        else i.valor_desconto * i.valor_aplicado / tp.valor_aplicado_total
      end as desconto_movimento,
      case
        when ct.quantidade_rateios > 0 and ct.valor_titulo > 0
        then least(greatest(ct.valor_investimento / ct.valor_titulo, 0), 1)
        when i.motivo_codigo = 'INVESTIMENTO' then 1
        else 0
      end as proporcao_investimento,
      case
        when i.motivo_codigo = 'FINANCIAMENTO_RURAL'
          or exists (
          select 1
          from f.arrendamento_contrato ac_scope
          where ac_scope.id = i.arrendamento_contrato_id
            and ac_scope.tenant_id = p_tenant_id
            and ac_scope.empresa_id = p_empresa_id
            and ac_scope.deleted_at is null
        )
        then 1
        when ct.quantidade_rateios > 0 and ct.valor_titulo > 0
        then least(greatest(ct.valor_divida / ct.valor_titulo, 0), 1)
        else 0
      end as proporcao_divida
    from itens i
    join totais_pagamento tp on tp.pagamento_id = i.pagamento_id
    left join classificacao_titulo ct on ct.titulo_id = i.titulo_id
  ),
  caixa_mes as (
    select
      date_trunc('month', l.data_pagamento)::date as mes,
      sum(case when l.tipo = 'AR' then l.valor_movimento else 0 end)
        as recebimentos,
      sum(case when l.tipo = 'AP' then l.valor_movimento else 0 end)
        as pagamentos
    from linhas l
    group by date_trunc('month', l.data_pagamento)::date
  ),
  caixa_atual as (
    select
      coalesce(sum(case when l.tipo = 'AR' then l.valor_movimento else 0 end), 0)
        as recebimentos,
      coalesce(sum(case when l.tipo = 'AP' then l.valor_movimento else 0 end), 0)
        as pagamentos,
      coalesce(sum(
        case when l.tipo = 'AP'
          then l.valor_movimento * l.proporcao_investimento else 0 end
      ), 0) as investimentos_pagos,
      coalesce(sum(
        case when l.tipo = 'AP'
          then l.valor_movimento * l.proporcao_divida else 0 end
      ), 0) as divida_paga,
      coalesce(sum(case when l.tipo = 'AP' then l.juros_movimento else 0 end), 0) as juros,
      coalesce(sum(case when l.tipo = 'AP' then l.multa_movimento else 0 end), 0) as multas,
      coalesce(sum(case when l.tipo = 'AP' then l.desconto_movimento else 0 end), 0) as descontos
    from linhas l
    where l.data_pagamento between p_data_inicio and p_data_fim
  ),
  caixa_anterior as (
    select
      coalesce(sum(case when l.tipo = 'AR' then l.valor_movimento else 0 end), 0)
        as recebimentos,
      coalesce(sum(case when l.tipo = 'AP' then l.valor_movimento else 0 end), 0)
        as pagamentos,
      coalesce(sum(
        case when l.tipo = 'AP'
          then l.valor_movimento * l.proporcao_investimento else 0 end
      ), 0) as investimentos_pagos,
      coalesce(sum(
        case when l.tipo = 'AP'
          then l.valor_movimento * l.proporcao_divida else 0 end
      ), 0) as divida_paga
    from linhas l
    where l.data_pagamento
      between v_data_anterior_inicio and v_data_anterior_fim
  ),
  meses as (
    select generate_series(
      v_serie_inicio::timestamp,
      date_trunc('month', p_data_fim)::timestamp,
      interval '1 month'
    )::date as mes
  ),
  serie as (
    select
      m.mes,
      coalesce(cm.recebimentos, 0) as recebimentos,
      coalesce(cm.pagamentos, 0) as pagamentos
    from meses m
    left join caixa_mes cm on cm.mes = m.mes
  ),
  motivo_resumo as (
    select
      l.motivo_id,
      l.motivo_codigo,
      l.motivo_nome,
      sum(l.valor_movimento) as valor
    from linhas l
    where l.tipo = 'AP'
      and l.data_pagamento between p_data_inicio and p_data_fim
    group by l.motivo_id, l.motivo_codigo, l.motivo_nome
  ),
  fornecedor_resumo as (
    select
      l.fornecedor_id,
      coalesce(forn.nome, 'Sem fornecedor') as nome,
      count(distinct l.pagamento_id) as quantidade,
      sum(l.valor_movimento) as valor
    from linhas l
    left join public.fornecedores forn
      on forn.tenant_id = p_tenant_id
     and forn.empresa_id = p_empresa_id
     and forn.id = l.fornecedor_id
    where l.tipo = 'AP'
      and l.data_pagamento between p_data_inicio and p_data_fim
    group by l.fornecedor_id, coalesce(forn.nome, 'Sem fornecedor')
  ),
  movimentos_sem_direcao as (
    select coalesce(sum(
      greatest(p.valor - coalesce(a.valor_atribuido, 0), 0)
    ), 0) as valor
    from pagamentos p
    left join (
      select l.pagamento_id, sum(l.valor_movimento) as valor_atribuido
      from linhas l
      group by l.pagamento_id
    ) a on a.pagamento_id = p.id
    where p.data_pagamento between p_data_inicio and p_data_fim
  ),
  conciliacao as (
    select
      coalesce(sum(
        case when p.conciliado_at is null then p.valor else 0 end
      ), 0) as nao_conciliado,
      coalesce(sum(
        case
          when p.conciliado_at is null
           and p.data_pagamento < current_date - 7
          then p.valor
          else 0
        end
      ), 0) as nao_conciliado_7_dias
    from pagamentos p
    where p.data_pagamento between p_data_inicio and p_data_fim
  )
  select jsonb_build_object(
    'recebimentos', round(ca.recebimentos, 2),
    'pagamentos', round(ca.pagamentos, 2),
    'saldo', round(ca.recebimentos - ca.pagamentos, 2),
    'investimentosPagos', round(ca.investimentos_pagos, 2),
    'dividaPaga', round(ca.divida_paga, 2),
    'juros', round(ca.juros, 2),
    'multas', round(ca.multas, 2),
    'descontos', round(ca.descontos, 2),
    'naoConciliado', round(co.nao_conciliado, 2),
    'naoConciliado7Dias', round(co.nao_conciliado_7_dias, 2),
    'movimentosSemDirecao', round(msd.valor, 2),
    'anterior', jsonb_build_object(
      'recebimentos', round(can.recebimentos, 2),
      'pagamentos', round(can.pagamentos, 2),
      'saldo', round(can.recebimentos - can.pagamentos, 2),
      'investimentosPagos', round(can.investimentos_pagos, 2),
      'dividaPaga', round(can.divida_paga, 2)
    ),
    'serie', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'label', to_char(s.mes, 'MM/YYYY'),
          'mes', s.mes,
          'recebimentos', round(s.recebimentos, 2),
          'pagamentos', round(s.pagamentos, 2),
          'saldo', round(s.recebimentos - s.pagamentos, 2)
        )
        order by s.mes
      )
      from serie s
    ), '[]'::jsonb),
    'porMotivo', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', x.motivo_id,
          'codigo', x.motivo_codigo,
          'nome', x.motivo_nome,
          'valor', round(x.valor, 2),
          'percentual', case
            when ca.pagamentos = 0 then 0
            else round((x.valor / ca.pagamentos) * 100, 2)
          end
        )
        order by x.valor desc, x.motivo_nome
      )
      from (
        select mr.*
        from motivo_resumo mr
        order by mr.valor desc
        limit 12
      ) x
    ), '[]'::jsonb),
    'topFornecedores', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'fornecedorId', x.fornecedor_id,
          'nome', x.nome,
          'quantidade', x.quantidade,
          'valor', round(x.valor, 2),
          'percentual', case
            when ca.pagamentos = 0 then 0
            else round((x.valor / ca.pagamentos) * 100, 2)
          end
        )
        order by x.valor desc, x.nome
      )
      from (
        select fr.*
        from fornecedor_resumo fr
        order by fr.valor desc
        limit 10
      ) x
    ), '[]'::jsonb)
  )
  into v_caixa
  from caixa_atual ca
  cross join caixa_anterior can
  cross join conciliacao co
  cross join movimentos_sem_direcao msd;

  /*
   * Compromissos atuais. A cobertura de 30 dias é uma razão em vezes:
   * contas a receber nos próximos 30 dias / contas a pagar no mesmo intervalo.
   */
  with
  titulos_abertos as (
    select
      t.id,
      t.tipo,
      t.fornecedor_id,
      t.valor_total,
      t.valor_aberto,
      t.arrendamento_contrato_id,
      coalesce(mc.codigo, 'NAO_CLASSIFICADO') as motivo_codigo
    from f.titulo t
    left join f.titulo_aprovacao ta
      on ta.tenant_id = p_tenant_id
     and ta.titulo_id = t.id
     and ta.deleted_at is null
    left join f.motivo_compra mc
      on mc.tenant_id = p_tenant_id
     and mc.id = coalesce(ta.motivo_compra_id, t.motivo_compra_id)
     and mc.deleted_at is null
     and mc.ativo
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.deleted_at is null
      and t.status <> 'CANCELADO'
      and not f.titulo_eh_legado_implantacao(
        p_tenant_id,
        p_empresa_id,
        t.id
      )
      and t.valor_aberto > 0
  ),
  parcelas as (
    select
      ta.*,
      tp.id as parcela_id,
      tp.vencimento_date,
      tp.valor_aberto as parcela_aberto
    from titulos_abertos ta
    join f.titulo_parcela tp
      on tp.tenant_id = p_tenant_id
     and tp.titulo_id = ta.id
     and tp.deleted_at is null
     and tp.valor_aberto > 0
  ),
  classificacao as (
    select
      ta.id as titulo_id,
      ta.valor_total as valor_titulo,
      coalesce(sum(coalesce(
        tr.valor,
        round(ta.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
        0
      )), 0) as valor_rateado,
      coalesce(sum(
        case
          when exists (
            select 1
            from r.dre_plano_excluido dpe
            where dpe.tenant_id = p_tenant_id
              and dpe.plano_contas_id = tr.plano_contas_id
          )
          then coalesce(
            tr.valor,
            round(ta.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
            0
          )
          else 0
        end
      ), 0) as investimento,
      coalesce(sum(
        case
          when pc.codigo = 'DESP_FINANCIAMENTO'
            or ta.motivo_codigo = 'FINANCIAMENTO_RURAL'
            or exists (
          select 1
          from f.arrendamento_contrato ac_scope
          where ac_scope.id = ta.arrendamento_contrato_id
            and ac_scope.tenant_id = p_tenant_id
            and ac_scope.empresa_id = p_empresa_id
            and ac_scope.deleted_at is null
        )
          then coalesce(
            tr.valor,
            round(ta.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
            0
          )
          else 0
        end
      ), 0) as divida,
      count(tr.id) as quantidade_rateios
    from titulos_abertos ta
    left join f.titulo_rateio tr
      on tr.tenant_id = p_tenant_id
     and tr.titulo_id = ta.id
     and tr.deleted_at is null
    left join f.plano_contas pc
      on pc.tenant_id = p_tenant_id
     and pc.id = tr.plano_contas_id
     and pc.deleted_at is null
    group by
      ta.id,
      ta.valor_total,
      ta.motivo_codigo,
      ta.arrendamento_contrato_id
  ),
  parcelas_classificadas as (
    select
      p.*,
      case
        when c.quantidade_rateios > 0 and c.valor_titulo > 0
        then least(greatest(c.investimento / c.valor_titulo, 0), 1)
        when p.motivo_codigo = 'INVESTIMENTO' then 1
        else 0
      end as proporcao_investimento,
      case
        when p.motivo_codigo = 'FINANCIAMENTO_RURAL'
          or exists (
          select 1
          from f.arrendamento_contrato ac_scope
          where ac_scope.id = p.arrendamento_contrato_id
            and ac_scope.tenant_id = p_tenant_id
            and ac_scope.empresa_id = p_empresa_id
            and ac_scope.deleted_at is null
        )
        then 1
        when c.quantidade_rateios > 0 and c.valor_titulo > 0
        then least(greatest(c.divida / c.valor_titulo, 0), 1)
        else 0
      end as proporcao_divida
    from parcelas p
    left join classificacao c on c.titulo_id = p.id
  ),
  abertos as (
    select
      coalesce(sum(case when ta.tipo = 'AP' then ta.valor_aberto else 0 end), 0)
        as ap_aberto,
      coalesce(sum(case when ta.tipo = 'AR' then ta.valor_aberto else 0 end), 0)
        as ar_aberto,
      coalesce(sum(case when ta.tipo = 'AP' then ta.valor_aberto *
        case
          when ta.motivo_codigo = 'FINANCIAMENTO_RURAL'
            or exists (
          select 1
          from f.arrendamento_contrato ac_scope
          where ac_scope.id = ta.arrendamento_contrato_id
            and ac_scope.tenant_id = p_tenant_id
            and ac_scope.empresa_id = p_empresa_id
            and ac_scope.deleted_at is null
        ) then 1
          when c.quantidade_rateios > 0 and c.valor_titulo > 0
            then least(greatest(c.divida / c.valor_titulo, 0), 1)
          else 0
        end
      else 0 end), 0) as divida_aberta,
      coalesce(sum(case when ta.tipo = 'AP' then ta.valor_aberto *
        case
          when c.quantidade_rateios > 0 and c.valor_titulo > 0
            then least(greatest(c.investimento / c.valor_titulo, 0), 1)
          when ta.motivo_codigo = 'INVESTIMENTO' then 1
          else 0
        end
      else 0 end), 0) as investimentos_abertos
    from titulos_abertos ta
    left join classificacao c on c.titulo_id = ta.id
  ),
  resumo as (
    select
      coalesce(sum(case when pc.tipo = 'AP'
        and pc.vencimento_date < current_date
        then pc.parcela_aberto else 0 end), 0) as ap_vencido,
      coalesce(sum(case when pc.tipo = 'AP'
        and pc.vencimento_date between current_date and current_date + 30
        then pc.parcela_aberto else 0 end), 0) as ap_vencer_30,
      coalesce(sum(case when pc.tipo = 'AR'
        and pc.vencimento_date < current_date
        then pc.parcela_aberto else 0 end), 0) as ar_vencido,
      coalesce(sum(case when pc.tipo = 'AR'
        and pc.vencimento_date between current_date and current_date + 30
        then pc.parcela_aberto else 0 end), 0) as ar_vencer_30
    from parcelas_classificadas pc
  ),
  aging as (
    select
      coalesce(sum(case when p.vencimento_date >= current_date
        then p.parcela_aberto else 0 end), 0) as a_vencer,
      coalesce(sum(case when current_date - p.vencimento_date between 1 and 30
        then p.parcela_aberto else 0 end), 0) as vencido_0_30,
      coalesce(sum(case when current_date - p.vencimento_date between 31 and 60
        then p.parcela_aberto else 0 end), 0) as vencido_31_60,
      coalesce(sum(case when current_date - p.vencimento_date between 61 and 90
        then p.parcela_aberto else 0 end), 0) as vencido_61_90,
      coalesce(sum(case when current_date - p.vencimento_date > 90
        then p.parcela_aberto else 0 end), 0) as vencido_mais_90
    from parcelas p
    where p.tipo = 'AP'
  ),
  ap_periodo as (
    select
      coalesce(sum(t.valor_total), 0) as total,
      coalesce(sum(t.valor_aberto), 0) as aberto,
      count(*) as quantidade
    from f.titulo t
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.deleted_at is null
      and t.status <> 'CANCELADO'
      and not f.titulo_eh_legado_implantacao(
        p_tenant_id,
        p_empresa_id,
        t.id
      )
      and t.tipo = 'AP'
      and t.competencia_date between p_data_inicio and p_data_fim
  )
  select jsonb_build_object(
    'apAberto', round(ab.ap_aberto, 2),
    'apVencido', round(r.ap_vencido, 2),
    'apVencer30', round(r.ap_vencer_30, 2),
    'arAberto', round(ab.ar_aberto, 2),
    'arVencido', round(r.ar_vencido, 2),
    'arVencer30', round(r.ar_vencer_30, 2),
    'cobertura30', case
      when r.ap_vencer_30 = 0 then null
      else round(r.ar_vencer_30 / r.ap_vencer_30, 4)
    end,
    'dividaAberta', round(ab.divida_aberta, 2),
    'investimentosAbertos', round(ab.investimentos_abertos, 2),
    'apPeriodoTotal', round(ap.total, 2),
    'apPeriodoAberto', round(ap.aberto, 2),
    'apPeriodoQtd', ap.quantidade,
    'agingAp', jsonb_build_object(
      'aVencer', round(ag.a_vencer, 2),
      'vencido0a30', round(ag.vencido_0_30, 2),
      'vencido31a60', round(ag.vencido_31_60, 2),
      'vencido61a90', round(ag.vencido_61_90, 2),
      'vencidoMais90', round(ag.vencido_mais_90, 2)
    )
  )
  into v_compromissos
  from resumo r
  cross join abertos ab
  cross join aging ag
  cross join ap_periodo ap;

  v_compromissos := v_compromissos || jsonb_build_object(
    'legadoExcluido',
    f.resumo_legado_implantacao_ap(p_tenant_id, p_empresa_id)
  );

  /*
   * Qualidade. Títulos sem competência entram pelo fallback emissão/criação,
   * para que a própria ausência da competência não os esconda do período.
   */
  with
  titulos as (
    select
      t.id,
      t.tipo,
      t.status,
      t.fornecedor_id,
      t.cliente_id,
      t.documento_fiscal_id,
      t.descricao,
      t.emissao_date,
      t.competencia_date,
      t.created_at::date as criado_date,
      t.valor_total,
      t.valor_aberto,
      t.arrendamento_contrato_id,
      coalesce(ta.motivo_compra_id, t.motivo_compra_id) as motivo_informado_id,
      mc.id as motivo_id,
      mc.codigo as motivo_codigo
    from f.titulo t
    left join f.titulo_aprovacao ta
      on ta.tenant_id = p_tenant_id
     and ta.titulo_id = t.id
     and ta.deleted_at is null
    left join f.motivo_compra mc
      on mc.tenant_id = p_tenant_id
     and mc.id = coalesce(ta.motivo_compra_id, t.motivo_compra_id)
     and mc.deleted_at is null
     and mc.ativo
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.deleted_at is null
      and t.status <> 'CANCELADO'
      and not f.titulo_eh_legado_implantacao(
        p_tenant_id,
        p_empresa_id,
        t.id
      )
      and (
        coalesce(t.competencia_date, t.emissao_date, t.created_at::date)
          between p_data_inicio and p_data_fim
        or t.valor_aberto > 0
      )
  ),
  parcela_stats as (
    select
      t.id as titulo_id,
      count(tp.id) as quantidade,
      coalesce(sum(tp.valor), 0) as valor,
      coalesce(sum(tp.valor_aberto), 0) as valor_aberto
    from titulos t
    left join f.titulo_parcela tp
      on tp.tenant_id = p_tenant_id
     and tp.titulo_id = t.id
     and tp.deleted_at is null
    group by t.id
  ),
  rateio_stats as (
    select
      t.id as titulo_id,
      count(tr.id) as quantidade,
      count(tr.percentual) as quantidade_percentual,
      count(tr.valor) as quantidade_valor,
      coalesce(sum(coalesce(
        tr.valor,
        round(t.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
        0
      )), 0) as valor,
      coalesce(sum(tr.percentual), 0) as percentual,
      count(*) filter (where tr.id is not null and tr.plano_contas_id is null)
        as sem_plano,
      count(*) filter (
        where tr.plano_contas_id is not null
          and (pc.id is null or not pc.ativo)
      ) as plano_invalido,
      count(*) filter (where tr.id is not null and tr.centro_custo_id is null)
        as sem_centro,
      count(*) filter (
        where tr.centro_custo_id is not null
          and (cc.id is null or not cc.ativo)
      ) as centro_invalido,
      coalesce(sum(case
        when pc.id is not null and pc.ativo
        then coalesce(
          tr.valor,
          round(t.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
          0
        )
        else 0
      end), 0) as valor_plano_valido,
      coalesce(sum(case
        when cc.id is not null and cc.ativo
        then coalesce(
          tr.valor,
          round(t.valor_total * coalesce(tr.percentual, 0) / 100.0, 2),
          0
        )
        else 0
      end), 0) as valor_centro_valido,
      bool_or(pc.codigo = 'DESP_FINANCIAMENTO') as plano_divida
    from titulos t
    left join f.titulo_rateio tr
      on tr.tenant_id = p_tenant_id
     and tr.titulo_id = t.id
     and tr.deleted_at is null
    left join f.plano_contas pc
      on pc.tenant_id = p_tenant_id
     and pc.id = tr.plano_contas_id
     and pc.deleted_at is null
    left join f.centro_custo cc
      on cc.tenant_id = p_tenant_id
     and cc.empresa_id = p_empresa_id
     and cc.id = tr.centro_custo_id
     and cc.deleted_at is null
    group by t.id, t.valor_total
  ),
  centros_ativos as (
    select count(*) as quantidade
    from f.centro_custo cc
    where cc.tenant_id = p_tenant_id
      and cc.empresa_id = p_empresa_id
      and cc.ativo
      and cc.deleted_at is null
  ),
  documentos_duplicados as (
    select
      t.documento_fiscal_id,
      t.tipo
    from f.titulo t
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.deleted_at is null
      and t.status <> 'CANCELADO'
      and not f.titulo_eh_legado_implantacao(
        p_tenant_id,
        p_empresa_id,
        t.id
      )
      and t.documento_fiscal_id is not null
    group by t.documento_fiscal_id, t.tipo
    having count(*) > 1
  ),
  pagamentos as (
    select
      p.id,
      p.data_pagamento,
      p.valor,
      p.valor_principal,
      p.conciliado_at
    from f.pagamento p
    where p.tenant_id = p_tenant_id
      and p.empresa_id = p_empresa_id
      and p.deleted_at is null
      and p.data_pagamento between p_data_inicio and p_data_fim
  ),
  pagamento_stats as (
    select
      p.id as pagamento_id,
      count(pi.id) as quantidade_itens,
      count(pi.id) filter (
        where t.id is not null and t.status <> 'CANCELADO'
      ) as quantidade_itens_validos,
      coalesce(sum(pi.valor), 0) as valor_itens,
      count(distinct t.tipo) filter (where t.status <> 'CANCELADO')
        as quantidade_tipos
    from pagamentos p
    left join f.pagamento_item pi
      on pi.tenant_id = p_tenant_id
     and pi.empresa_id = p_empresa_id
     and pi.pagamento_id = p.id
     and pi.deleted_at is null
    left join f.titulo_parcela tp
      on tp.tenant_id = p_tenant_id
     and tp.id = pi.titulo_parcela_id
     and tp.deleted_at is null
    left join f.titulo t
      on t.tenant_id = p_tenant_id
     and t.empresa_id = p_empresa_id
     and t.id = tp.titulo_id
     and t.deleted_at is null
    group by p.id
  ),
  cobertura as (
    select
      coalesce(sum(case
        when t.tipo = 'AP' then greatest(t.valor_total, 0)
        else 0
      end), 0) as total_ap,
      coalesce(sum(case
        when t.tipo = 'AP'
        then least(greatest(rs.valor, 0), greatest(t.valor_total, 0))
        else 0
      end), 0) as coberto_rateio,
      coalesce(sum(case
        when t.tipo = 'AP'
        then least(
          greatest(rs.valor_centro_valido, 0),
          greatest(t.valor_total, 0)
        )
        else 0
      end), 0) as coberto_centro,
      coalesce(sum(case
        when t.tipo = 'AP' and t.motivo_id is not null
          then greatest(t.valor_total, 0)
        when t.tipo = 'AP'
          then least(
            greatest(rs.valor_plano_valido, 0),
            greatest(t.valor_total, 0)
          )
        else 0
      end), 0) as coberto_classificacao
    from titulos t
    join rateio_stats rs on rs.titulo_id = t.id
  ),
  alertas as (
    select
      'PARCELAS_DIVERGEM_TOTAL:' || t.id::text as id,
      'CRITICO'::text as severidade,
      'PARCELAS_DIVERGEM_TOTAL'::text as codigo,
      'Soma das parcelas diverge do título'::text as titulo_alerta,
      'titulo'::text as entidade,
      t.id as entidade_id,
      coalesce(nullif(t.descricao, ''), t.id::text) as referencia,
      coalesce(t.competencia_date, t.emissao_date, t.criado_date) as data_ref,
      t.valor_total as valor,
      format(
        'Título: %s; parcelas: %s.',
        round(t.valor_total, 2),
        round(ps.valor, 2)
      ) as detalhe,
      'Revisar valores e quantidade das parcelas.'::text as acao
    from titulos t
    join parcela_stats ps on ps.titulo_id = t.id
    where abs(ps.valor - t.valor_total) > 0.01

    union all

    select
      'SALDO_PARCELAS_DIVERGE:' || t.id::text,
      'CRITICO',
      'SALDO_PARCELAS_DIVERGE',
      'Saldo das parcelas diverge do título',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_aberto,
      format(
        'Saldo do título: %s; saldo das parcelas: %s.',
        round(t.valor_aberto, 2),
        round(ps.valor_aberto, 2)
      ),
      'Reprocessar ou corrigir a baixa das parcelas.'
    from titulos t
    join parcela_stats ps on ps.titulo_id = t.id
    where abs(ps.valor_aberto - t.valor_aberto) > 0.01

    union all

    select
      'STATUS_SALDO_INCONSISTENTE:' || t.id::text,
      'CRITICO',
      'STATUS_SALDO_INCONSISTENTE',
      'Status incompatível com o saldo',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_aberto,
      format('Status: %s; saldo: %s.', t.status, round(t.valor_aberto, 2)),
      'Revisar o status ou as baixas do título.'
    from titulos t
    where (t.status = 'PAGO' and abs(t.valor_aberto) > 0.01)
       or (t.status <> 'PAGO' and t.valor_total > 0 and t.valor_aberto <= 0.01)

    union all

    select
      'DOCUMENTO_DUPLICADO:' || t.id::text,
      'CRITICO',
      'DOCUMENTO_DUPLICADO',
      'Documento financeiro duplicado',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.documento_fiscal_id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'Há mais de um título ativo do mesmo tipo para o documento fiscal.',
      'Comparar os títulos e cancelar somente o lançamento indevido.'
    from titulos t
    join documentos_duplicados dd
      on dd.documento_fiscal_id = t.documento_fiscal_id
     and dd.tipo = t.tipo

    union all

    select
      'ESCOPO_RELACIONAMENTO_DIVERGENTE:' || t.id::text,
      'CRITICO',
      'ESCOPO_RELACIONAMENTO_DIVERGENTE',
      'Relacionamento fora do tenant',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'Existe parcela, rateio ou aprovação vinculada com tenant divergente.',
      'Corrigir o vínculo antes de qualquer baixa ou alteração.'
    from titulos t
    where exists (
      select 1
      from f.titulo_parcela tp_x
      where tp_x.titulo_id = t.id
        and tp_x.deleted_at is null
        and tp_x.tenant_id is distinct from p_tenant_id
    )
    or exists (
      select 1
      from f.titulo_rateio tr_x
      where tr_x.titulo_id = t.id
        and tr_x.deleted_at is null
        and tr_x.tenant_id is distinct from p_tenant_id
    )
    or exists (
      select 1
      from f.titulo_aprovacao ta_x
      where ta_x.titulo_id = t.id
        and ta_x.deleted_at is null
        and ta_x.tenant_id is distinct from p_tenant_id
    )

    union all

    select
      'PAGAMENTO_SEM_VINCULO_VALIDO:' || p.id::text,
      'CRITICO',
      'PAGAMENTO_SEM_VINCULO_VALIDO',
      'Pagamento sem vínculo financeiro válido',
      'pagamento',
      p.id,
      p.id::text,
      p.data_pagamento,
      p.valor,
      'O cabeçalho não possui item ligado a parcela e título ativos, não cancelados, no mesmo escopo.',
      'Vincular as parcelas corretas ou estornar o pagamento.'
    from pagamentos p
    join pagamento_stats ps on ps.pagamento_id = p.id
    where ps.quantidade_itens_validos = 0

    union all

    select
      'PAGAMENTO_VINCULO_PARCIAL_INVALIDO:' || p.id::text,
      'CRITICO',
      'PAGAMENTO_VINCULO_PARCIAL_INVALIDO',
      'Pagamento possui vínculo inválido',
      'pagamento',
      p.id,
      p.id::text,
      p.data_pagamento,
      p.valor,
      'Parte dos itens não aponta para parcela e título ativos, não cancelados, no mesmo escopo.',
      'Corrigir os vínculos; a parcela sem direção não foi forçada para AP ou AR.'
    from pagamentos p
    join pagamento_stats ps on ps.pagamento_id = p.id
    where ps.quantidade_itens_validos > 0
      and ps.quantidade_itens_validos < ps.quantidade_itens

    union all

    select
      'PAGAMENTO_TIPOS_MISTOS:' || p.id::text,
      'CRITICO',
      'PAGAMENTO_TIPOS_MISTOS',
      'Pagamento mistura contas a pagar e receber',
      'pagamento',
      p.id,
      p.id::text,
      p.data_pagamento,
      p.valor,
      'O mesmo pagamento está aplicado a títulos AP e AR.',
      'Separar o pagamento em movimentos financeiros distintos.'
    from pagamentos p
    join pagamento_stats ps on ps.pagamento_id = p.id
    where ps.quantidade_tipos > 1

    union all

    select
      'PAGAMENTO_PRINCIPAL_DIVERGENTE:' || p.id::text,
      'CRITICO',
      'PAGAMENTO_PRINCIPAL_DIVERGENTE',
      'Itens divergem do principal do pagamento',
      'pagamento',
      p.id,
      p.id::text,
      p.data_pagamento,
      p.valor,
      format(
        'Principal: %s; itens: %s.',
        round(p.valor_principal, 2),
        round(ps.valor_itens, 2)
      ),
      'Revisar a composição do pagamento e suas aplicações.'
    from pagamentos p
    join pagamento_stats ps on ps.pagamento_id = p.id
    where abs(ps.valor_itens - p.valor_principal) > 0.01

    union all

    select
      'PAGAMENTO_ESCOPO_DIVERGENTE:' || p.id::text,
      'CRITICO',
      'PAGAMENTO_ESCOPO_DIVERGENTE',
      'Item de pagamento fora do escopo',
      'pagamento',
      p.id,
      p.id::text,
      p.data_pagamento,
      p.valor,
      'Existe item, parcela ou título ligado com tenant/empresa divergente.',
      'Corrigir o vínculo antes de conciliar o pagamento.'
    from pagamentos p
    where exists (
      select 1
      from f.pagamento_item pi_x
      left join f.titulo_parcela tp_x on tp_x.id = pi_x.titulo_parcela_id
      left join f.titulo t_x on t_x.id = tp_x.titulo_id
      where pi_x.pagamento_id = p.id
        and pi_x.deleted_at is null
        and (
          pi_x.tenant_id is distinct from p_tenant_id
          or pi_x.empresa_id is distinct from p_empresa_id
          or tp_x.tenant_id is distinct from p_tenant_id
          or t_x.tenant_id is distinct from p_tenant_id
          or t_x.empresa_id is distinct from p_empresa_id
        )
    )

    union all

    select
      'CANCELADO_COM_SALDO:' || t.id::text,
      'CRITICO',
      'CANCELADO_COM_SALDO',
      'Título cancelado mantém saldo em aberto',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.created_at::date),
      t.valor_aberto,
      format('Título cancelado com saldo de %s.', round(t.valor_aberto, 2)),
      'Zerar o saldo mediante estorno correto ou revisar o cancelamento.'
    from f.titulo t
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.deleted_at is null
      and t.status = 'CANCELADO'
      and t.valor_aberto > 0.01

    union all

    select
      'COMPETENCIA_AUSENTE:' || t.id::text,
      'ALTO',
      'COMPETENCIA_AUSENTE',
      'Competência não informada',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.emissao_date, t.criado_date),
      t.valor_total,
      'O lançamento não participa corretamente da análise por competência.',
      'Informar a competência contábil do título.'
    from titulos t
    where t.competencia_date is null

    union all

    select
      'CONTRAPARTE_INVALIDA:' || t.id::text,
      'ALTO',
      'CONTRAPARTE_INVALIDA',
      case when t.tipo = 'AP' then 'Fornecedor inválido ou fora da empresa'
           else 'Cliente inválido ou fora da empresa' end,
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'A contraparte informada não está ativa no mesmo tenant e empresa.',
      case when t.tipo = 'AP' then 'Vincular um fornecedor ativo desta empresa.'
           else 'Vincular um cliente ativo desta empresa.' end
    from titulos t
    where (
      t.tipo = 'AP'
      and t.fornecedor_id is not null
      and not exists (
        select 1
        from public.fornecedores f_x
        where f_x.id = t.fornecedor_id
          and f_x.tenant_id = p_tenant_id
          and f_x.empresa_id = p_empresa_id
          and coalesce(f_x.ativo, true)
      )
    ) or (
      t.tipo = 'AR'
      and t.cliente_id is not null
      and not exists (
        select 1
        from public.clientes c_x
        where c_x.id = t.cliente_id
          and c_x.tenant_id = p_tenant_id
          and c_x.empresa_id = p_empresa_id
          and coalesce(c_x.ativo, true)
      )
    )

    union all

    select
      'PARTE_AUSENTE:' || t.id::text,
      'ALTO',
      'PARTE_AUSENTE',
      case when t.tipo = 'AP' then 'Fornecedor não informado'
           else 'Cliente não informado' end,
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'O título não possui a contraparte esperada para o seu tipo.',
      case when t.tipo = 'AP' then 'Vincular o fornecedor correto.'
           else 'Vincular o cliente correto.' end
    from titulos t
    where (t.tipo = 'AP' and t.fornecedor_id is null)
       or (t.tipo = 'AR' and t.cliente_id is null)

    union all

    select
      'SEM_RATEIO:' || t.id::text,
      'ALTO',
      'SEM_RATEIO',
      'Título sem rateio',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'Sem rateio, o valor não entra no resultado gerencial por competência.',
      'Criar o rateio com plano de contas e centro de custo.'
    from titulos t
    join rateio_stats rs on rs.titulo_id = t.id
    where rs.quantidade = 0

    union all

    select
      'RATEIO_SEM_PLANO:' || t.id::text,
      'ALTO',
      'RATEIO_SEM_PLANO',
      'Rateio sem plano de contas',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      format('%s rateio(s) sem plano de contas.', rs.sem_plano),
      'Classificar todos os rateios no plano de contas.'
    from titulos t
    join rateio_stats rs on rs.titulo_id = t.id
    where rs.sem_plano > 0

    union all

    select
      'RATEIO_DIVERGENTE:' || t.id::text,
      'ALTO',
      'RATEIO_DIVERGENTE',
      'Soma do rateio diverge do título',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      format(
        'Título: %s; rateio: %s; percentual: %s%%.',
        round(t.valor_total, 2),
        round(rs.valor, 2),
        round(rs.percentual, 4)
      ),
      'Ajustar os rateios para totalizar o título e 100%.'
    from titulos t
    join rateio_stats rs on rs.titulo_id = t.id
    where rs.quantidade > 0
      and (
        abs(rs.valor - t.valor_total) > 0.01
        or (
          rs.quantidade_percentual = rs.quantidade
          and abs(rs.percentual - 100) > 0.0001
        )
      )

    union all

    select
      'PLANO_INVALIDO:' || t.id::text,
      'ALTO',
      'PLANO_INVALIDO',
      'Plano de contas inválido ou inativo',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      format(
        '%s rateio(s) usam plano inválido, excluído ou de outro tenant.',
        rs.plano_invalido
      ),
      'Substituir pelo plano de contas ativo correto.'
    from titulos t
    join rateio_stats rs on rs.titulo_id = t.id
    where rs.plano_invalido > 0

    union all

    select
      'CENTRO_INVALIDO:' || t.id::text,
      'ALTO',
      'CENTRO_INVALIDO',
      'Centro de custo inválido ou inativo',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      format(
        '%s rateio(s) usam centro inválido, excluído ou de outra empresa.',
        rs.centro_invalido
      ),
      'Substituir pelo centro de custo ativo correto.'
    from titulos t
    join rateio_stats rs on rs.titulo_id = t.id
    where rs.centro_invalido > 0

    union all

    select
      'MOTIVO_INVALIDO:' || t.id::text,
      'ALTO',
      'MOTIVO_INVALIDO',
      'Motivo da compra inválido ou inativo',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'O motivo informado não está ativo no tenant da empresa.',
      'Selecionar um motivo de compra ativo e válido.'
    from titulos t
    where t.tipo = 'AP'
      and t.motivo_informado_id is not null
      and t.motivo_id is null

    union all

    select
      'MOTIVO_AUSENTE:' || t.id::text,
      'MEDIO',
      'MOTIVO_AUSENTE',
      'Motivo da compra não informado',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'O AP não possui motivo efetivo no título nem na aprovação.',
      'Informar o motivo da compra.'
    from titulos t
    where t.tipo = 'AP'
      and t.motivo_informado_id is null

    union all

    select
      'CENTRO_CUSTO_AUSENTE:' || t.id::text,
      'MEDIO',
      'CENTRO_CUSTO_AUSENTE',
      'Centro de custo não informado',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      format('%s rateio(s) sem centro de custo.', rs.sem_centro),
      'Distribuir o gasto nos centros de custo responsáveis.'
    from titulos t
    join rateio_stats rs on rs.titulo_id = t.id
    cross join centros_ativos ca
    where ca.quantidade > 0
      and rs.quantidade > 0
      and rs.sem_centro > 0

    union all

    select
      'SEM_CENTROS_CADASTRADOS:GLOBAL',
      'MEDIO',
      'SEM_CENTROS_CADASTRADOS',
      'Empresa sem centros de custo ativos',
      'configuracao',
      null::uuid,
      'Configuração financeira',
      p_data_fim,
      0::numeric,
      'Há AP no período, mas não existe centro de custo ativo.',
      'Cadastrar a estrutura mínima de centros de custo.'
    from centros_ativos ca
    where ca.quantidade = 0
      and exists (select 1 from titulos t where t.tipo = 'AP')

    union all

    select
      'PAGAMENTO_NAO_CONCILIADO:' || p.id::text,
      'MEDIO',
      'PAGAMENTO_NAO_CONCILIADO',
      'Pagamento sem conciliação há mais de 7 dias',
      'pagamento',
      p.id,
      p.id::text,
      p.data_pagamento,
      p.valor,
      format('%s dia(s) sem conciliação.', current_date - p.data_pagamento),
      'Conciliar com o extrato bancário ou revisar o lançamento.'
    from pagamentos p
    where p.conciliado_at is null
      and p.data_pagamento < current_date - 7

    union all

    select
      'ARRENDAMENTO_INVALIDO:' || t.id::text,
      'ALTO',
      'ARRENDAMENTO_INVALIDO',
      'Contrato de arrendamento inválido ou fora do escopo',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'O contrato informado não está ativo no mesmo tenant e empresa.',
      'Vincular o contrato correto ou remover a referência inválida.'
    from titulos t
    where t.arrendamento_contrato_id is not null
      and not exists (
        select 1
        from f.arrendamento_contrato ac_x
        where ac_x.id = t.arrendamento_contrato_id
          and ac_x.tenant_id = p_tenant_id
          and ac_x.empresa_id = p_empresa_id
          and ac_x.deleted_at is null
      )

    union all

    select
      'POSSIVEL_DIVIDA_NAO_CLASSIFICADA:' || t.id::text,
      'MEDIO',
      'POSSIVEL_DIVIDA_NAO_CLASSIFICADA',
      'Possível dívida sem classificação explícita',
      'titulo',
      t.id,
      coalesce(nullif(t.descricao, ''), t.id::text),
      coalesce(t.competencia_date, t.emissao_date, t.criado_date),
      t.valor_total,
      'A descrição sugere financiamento, consórcio, leasing ou parcelamento.',
      'Confirmar a natureza e classificar como dívida quando aplicável.'
    from titulos t
    join rateio_stats rs on rs.titulo_id = t.id
    where t.tipo = 'AP'
      and coalesce(t.descricao, '')
        ~* '(FINANCIAMENTO|CONS[ÓO]RCIO|LEASING|PARCELAMENTO)'
      and not exists (
        select 1
        from f.arrendamento_contrato ac_x
        where ac_x.id = t.arrendamento_contrato_id
          and ac_x.tenant_id = p_tenant_id
          and ac_x.empresa_id = p_empresa_id
          and ac_x.deleted_at is null
      )
      and coalesce(t.motivo_codigo, '') <> 'FINANCIAMENTO_RURAL'
      and not coalesce(rs.plano_divida, false)
      and not exists (
        select 1
        from f.titulo_classificacao_compromisso tc_compromisso
        where tc_compromisso.tenant_id = p_tenant_id
          and tc_compromisso.empresa_id = p_empresa_id
          and tc_compromisso.titulo_id = t.id
          and tc_compromisso.deleted_at is null
      )
  ),
  valor_afetado as (
    select coalesce(sum(x.valor), 0) as valor
    from (
      select
        a.entidade,
        a.entidade_id,
        max(abs(coalesce(a.valor, 0))) as valor
      from alertas a
      where a.entidade_id is not null
      group by a.entidade, a.entidade_id
    ) x
  )
  select jsonb_build_object(
    'coberturaRateioPct', case
      when c.total_ap = 0 then 100
      else round((c.coberto_rateio / c.total_ap) * 100, 2)
    end,
    'coberturaCentroPct', case
      when c.total_ap = 0 then 100
      else round((c.coberto_centro / c.total_ap) * 100, 2)
    end,
    'coberturaClassificacaoPct', case
      when c.total_ap = 0 then 100
      else round((c.coberto_classificacao / c.total_ap) * 100, 2)
    end,
    'totalAlertas', (select count(*) from alertas),
    'titulosAfetados', (
      select count(distinct a.entidade_id)
      from alertas a
      where a.entidade = 'titulo'
    ),
    'valorAfetado', round(va.valor, 2),
    'porSeveridade', jsonb_build_object(
      'critico', (
        select count(*) from alertas a where a.severidade = 'CRITICO'
      ),
      'alto', (
        select count(*) from alertas a where a.severidade = 'ALTO'
      ),
      'medio', (
        select count(*) from alertas a where a.severidade = 'MEDIO'
      )
    ),
    'porTipo', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'codigo', x.codigo,
          'titulo', x.titulo_alerta,
          'severidade', x.severidade,
          'quantidade', x.quantidade,
          'valor', round(x.valor, 2)
        )
        order by
          case x.severidade
            when 'CRITICO' then 1
            when 'ALTO' then 2
            else 3
          end,
          x.quantidade desc,
          x.titulo_alerta
      )
      from (
        select
          a.codigo,
          a.titulo_alerta,
          a.severidade,
          count(*) as quantidade,
          sum(abs(coalesce(a.valor, 0))) as valor
        from alertas a
        group by a.codigo, a.titulo_alerta, a.severidade
      ) x
    ), '[]'::jsonb),
    'itens', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', x.id,
          'severidade', x.severidade,
          'codigo', x.codigo,
          'tipo', x.codigo,
          'titulo', x.titulo_alerta,
          'entidade', x.entidade,
          'entidadeId', x.entidade_id,
          'referencia', x.referencia,
          'data', x.data_ref,
          'valor', round(coalesce(x.valor, 0), 2),
          'detalhe', x.detalhe,
          'acao', x.acao
        )
        order by
          case x.severidade
            when 'CRITICO' then 1
            when 'ALTO' then 2
            else 3
          end,
          x.data_ref desc nulls last,
          x.referencia
      )
      from (
        select a.*
        from alertas a
        order by
          case a.severidade
            when 'CRITICO' then 1
            when 'ALTO' then 2
            else 3
          end,
          a.data_ref desc nulls last
        limit 250
      ) x
    ), '[]'::jsonb)
  )
  into v_qualidade
  from cobertura c
  cross join valor_afetado va;

  return jsonb_build_object(
    'meta', jsonb_build_object(
      'tenantId', p_tenant_id,
      'empresaId', p_empresa_id,
      'dataInicio', p_data_inicio,
      'dataFim', p_data_fim,
      'periodoAnteriorInicio', v_data_anterior_inicio,
      'periodoAnteriorFim', v_data_anterior_fim,
      'compromissosReferencia', current_date,
      'geradoEm', statement_timestamp(),
      'moeda', 'BRL',
      'metodologia',
        'Resultado e caixa seguem o período filtrado. AP/AR aberto, aging e cobertura representam a posição atual. Qualidade inclui o período e títulos ainda abertos. Investimentos são excluídos do resultado e podem também estar classificados como dívida.'
    ),
    'competencia', coalesce(v_competencia, '{}'::jsonb),
    'caixa', coalesce(v_caixa, '{}'::jsonb),
    'compromissos', coalesce(v_compromissos, '{}'::jsonb),
    'qualidade', coalesce(v_qualidade, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "f"."relatorio_saude_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."relatorio_saude_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") IS 'Relatorio executivo de saude financeira; classificacoes ativas eliminam falsos alertas de divida nao classificada.';



CREATE OR REPLACE FUNCTION "f"."resumo_classificacao_compromissos"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_referencia" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_resultado jsonb;
begin
  if p_tenant_id is null
     or p_empresa_id is null
     or p_data_referencia is null
  then
    raise exception 'Tenant, empresa e data de referencia sao obrigatorios.';
  end if;

  if auth.uid() is not null then
    if p_tenant_id is distinct from public.current_tenant_id()
       or p_empresa_id is distinct from public.current_empresa_id()
       or not f.has_finance_access(p_tenant_id, p_empresa_id)
    then
      raise exception 'Sem permissao para consultar compromissos deste escopo.';
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role'
        and session_user not in ('postgres', 'service_role')
  then
    raise exception 'Usuario nao autenticado.';
  end if;

  with
  categorias_def as (
    select *
    from (
      values
        ('DIVIDA_TRIBUTARIA'::text, 'Dívida tributária'::text, 1),
        ('EMPRESTIMO', 'Empréstimos', 2),
        ('MAQUINA', 'Máquinas e ativos produtivos', 3),
        ('VEICULO', 'Veículos', 4),
        ('AJUSTE', 'Ajustes de implantação', 5)
    ) c(codigo, nome, ordem)
  ),
  classificacoes as (
    select
      tc.id,
      tc.titulo_id,
      tc.categoria,
      tc.forma_contratacao,
      tc.confianca,
      tc.lote_id
    from f.titulo_classificacao_compromisso tc
    join f.titulo t
      on t.id = tc.titulo_id
     and t.tenant_id = p_tenant_id
     and t.empresa_id = p_empresa_id
     and t.tipo = 'AP'
     and t.deleted_at is null
     and t.status <> 'CANCELADO'
    where tc.tenant_id = p_tenant_id
      and tc.empresa_id = p_empresa_id
      and tc.deleted_at is null
  ),
  parcelas_classificadas as (
    select
      c.titulo_id,
      c.categoria,
      c.forma_contratacao,
      c.confianca,
      tp.id as parcela_id,
      tp.vencimento_date,
      tp.valor_aberto
    from classificacoes c
    join f.titulo_parcela tp
      on tp.tenant_id = p_tenant_id
     and tp.titulo_id = c.titulo_id
     and tp.deleted_at is null
     and tp.valor_aberto > 0
  ),
  posicao_categoria as (
    select
      d.codigo,
      d.nome,
      d.ordem,
      count(distinct pc.titulo_id)::integer as quantidade,
      round(coalesce(sum(pc.valor_aberto), 0), 2) as valor_aberto,
      round(coalesce(sum(pc.valor_aberto) filter (
        where pc.vencimento_date < p_data_referencia
      ), 0), 2) as vencido,
      round(coalesce(sum(pc.valor_aberto) filter (
        where pc.vencimento_date between
          p_data_referencia and p_data_referencia + 30
      ), 0), 2) as proximos_30
    from categorias_def d
    left join parcelas_classificadas pc
      on pc.categoria = d.codigo
    group by d.codigo, d.nome, d.ordem
  ),
  totais as (
    select
      round(coalesce(sum(pc.valor_aberto), 0), 2)
        as total_classificado,
      round(coalesce(sum(pc.valor_aberto) filter (
        where pc.categoria <> 'AJUSTE'
      ), 0), 2) as total_financeiro,
      round(coalesce(sum(pc.valor_aberto) filter (
        where pc.categoria in ('DIVIDA_TRIBUTARIA', 'EMPRESTIMO')
      ), 0), 2) as divida,
      round(coalesce(sum(pc.valor_aberto) filter (
        where pc.categoria in ('MAQUINA', 'VEICULO')
      ), 0), 2) as investimento,
      round(coalesce(sum(pc.valor_aberto) filter (
        where pc.categoria = 'AJUSTE'
      ), 0), 2) as ajustes,
      count(distinct pc.titulo_id) filter (
        where pc.confianca <> 'ALTA'
      )::integer as quantidade_revisao,
      round(coalesce(sum(pc.valor_aberto) filter (
        where pc.confianca <> 'ALTA'
      ), 0), 2) as valor_revisao
    from parcelas_classificadas pc
  ),
  formas as (
    select
      pc.forma_contratacao as codigo,
      count(distinct pc.titulo_id)::integer as quantidade,
      round(sum(pc.valor_aberto), 2) as valor_aberto
    from parcelas_classificadas pc
    group by pc.forma_contratacao
  ),
  lote as (
    select
      l.codigo,
      l.valor_referencia_informado,
      l.valor_financeiro_aberto_snapshot,
      l.valor_ajustes_aberto_snapshot,
      l.valor_total_aberto_snapshot,
      l.diferenca_referencia_snapshot,
      l.quantidade_titulos,
      l.manifest_md5,
      l.created_at
    from f.compromisso_classificacao_lote l
    where l.tenant_id = p_tenant_id
      and l.empresa_id = p_empresa_id
    order by l.created_at desc, l.id desc
    limit 1
  ),
  ap_operacional as (
    select
      round(coalesce(sum(tp.valor_aberto), 0), 2) as valor_aberto
    from f.titulo t
    join f.titulo_parcela tp
      on tp.tenant_id = p_tenant_id
     and tp.titulo_id = t.id
     and tp.deleted_at is null
     and tp.valor_aberto > 0
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.tipo = 'AP'
      and t.deleted_at is null
      and t.status <> 'CANCELADO'
      and not exists (
        select 1
        from f.titulo_legado_implantacao li
        where li.tenant_id = p_tenant_id
          and li.empresa_id = p_empresa_id
          and li.titulo_id = t.id
          and li.desmarcado_em is null
      )
  ),
  possiveis_sem_classificacao as (
    select
      count(distinct t.id)::integer as quantidade,
      round(coalesce(sum(tp_saldo.valor_aberto), 0), 2) as valor_aberto
    from f.titulo t
    join lateral (
      select coalesce(sum(tp.valor_aberto), 0)::numeric as valor_aberto
      from f.titulo_parcela tp
      where tp.tenant_id = p_tenant_id
        and tp.titulo_id = t.id
        and tp.deleted_at is null
        and tp.valor_aberto > 0
    ) tp_saldo on tp_saldo.valor_aberto > 0
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.tipo = 'AP'
      and t.deleted_at is null
      and t.status <> 'CANCELADO'
      and coalesce(t.descricao, '')
        ~* '(FINANCIAMENTO|CONS[ÓO]RCIO|LEASING|PARCELAMENTO|PRONAMP)'
      and not exists (
        select 1
        from f.titulo_classificacao_compromisso tc
        where tc.tenant_id = p_tenant_id
          and tc.empresa_id = p_empresa_id
          and tc.titulo_id = t.id
          and tc.deleted_at is null
      )
      and not exists (
        select 1
        from f.titulo_legado_implantacao li
        where li.tenant_id = p_tenant_id
          and li.empresa_id = p_empresa_id
          and li.titulo_id = t.id
          and li.desmarcado_em is null
      )
  )
  select jsonb_build_object(
    'meta', jsonb_build_object(
      'referencia', p_data_referencia,
      'atualizadoEm', now(),
      'loteCodigo', l.codigo,
      'loteCriadoEm', l.created_at,
      'manifestMd5', l.manifest_md5
    ),
    'valorReferenciaInformado', l.valor_referencia_informado,
    'totalClassificadoAberto', t.total_classificado,
    'totalFinanceiroAberto', t.total_financeiro,
    'ajustesAberto', t.ajustes,
    'dividaAberta', t.divida,
    'investimentosAbertos', t.investimento,
    'diferencaReferencia',
      round(t.total_financeiro - l.valor_referencia_informado, 2),
    'diferencaConciliacao',
      round(
        t.total_classificado
          - t.divida
          - t.investimento
          - t.ajustes,
        2
      ),
    'apOperacionalAberto', ap.valor_aberto,
    'apOperacionalForaComposicao',
      round(greatest(ap.valor_aberto - t.total_financeiro, 0), 2),
    'snapshot', jsonb_build_object(
      'valorFinanceiroAberto', l.valor_financeiro_aberto_snapshot,
      'valorAjustesAberto', l.valor_ajustes_aberto_snapshot,
      'valorTotalAberto', l.valor_total_aberto_snapshot,
      'diferencaReferencia', l.diferenca_referencia_snapshot,
      'quantidadeTitulos', l.quantidade_titulos
    ),
    'revisao', jsonb_build_object(
      'quantidade', t.quantidade_revisao,
      'valorAberto', t.valor_revisao,
      'possiveisSemClassificacaoQtd', psc.quantidade,
      'possiveisSemClassificacaoValor', psc.valor_aberto
    ),
    'categorias', (
      select jsonb_agg(
        jsonb_build_object(
          'codigo', pc.codigo,
          'nome', pc.nome,
          'quantidade', pc.quantidade,
          'valorAberto', pc.valor_aberto,
          'vencido', pc.vencido,
          'proximos30', pc.proximos_30,
          'percentual', case
            when t.total_classificado = 0 then 0
            else round(pc.valor_aberto / t.total_classificado * 100, 2)
          end
        )
        order by pc.ordem
      )
      from posicao_categoria pc
    ),
    'formas', (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'codigo', f.codigo,
          'quantidade', f.quantidade,
          'valorAberto', f.valor_aberto
        )
        order by f.valor_aberto desc, f.codigo
      ), '[]'::jsonb)
      from formas f
    )
  )
  into v_resultado
  from totais t
  cross join lote l
  cross join ap_operacional ap
  cross join possiveis_sem_classificacao psc;

  return coalesce(v_resultado, jsonb_build_object(
    'meta', jsonb_build_object(
      'referencia', p_data_referencia,
      'atualizadoEm', now()
    ),
    'valorReferenciaInformado', 0,
    'totalClassificadoAberto', 0,
    'totalFinanceiroAberto', 0,
    'ajustesAberto', 0,
    'dividaAberta', 0,
    'investimentosAbertos', 0,
    'diferencaReferencia', 0,
    'diferencaConciliacao', 0,
    'apOperacionalAberto', 0,
    'apOperacionalForaComposicao', 0,
    'revisao', jsonb_build_object(
      'quantidade', 0,
      'valorAberto', 0,
      'possiveisSemClassificacaoQtd', 0,
      'possiveisSemClassificacaoValor', 0
    ),
    'categorias', '[]'::jsonb,
    'formas', '[]'::jsonb
  ));
end;
$$;


ALTER FUNCTION "f"."resumo_classificacao_compromissos"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_referencia" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."resumo_classificacao_compromissos"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_referencia" "date") IS 'Composicao gerencial mutuamente exclusiva dos compromissos AP, com saldos vivos e referencia auditada.';



CREATE OR REPLACE FUNCTION "f"."resumo_classificacao_compromissos_referencia"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_resultado jsonb;
begin
  if p_tenant_id is null or p_empresa_id is null then
    raise exception 'Tenant e empresa sao obrigatorios.';
  end if;

  if auth.uid() is not null then
    if p_tenant_id is distinct from public.current_tenant_id()
       or p_empresa_id is distinct from public.current_empresa_id()
       or not f.has_finance_access(p_tenant_id, p_empresa_id)
    then
      raise exception 'Sem permissao para consultar este escopo.';
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role'
        and session_user not in ('postgres', 'service_role')
  then
    raise exception 'Usuario nao autenticado.';
  end if;

  with
  categorias_def as (
    select *
    from (
      values
        ('DIVIDA_TRIBUTARIA'::text, 'Dívida tributária'::text, 1),
        ('EMPRESTIMO', 'Empréstimos', 2),
        ('MAQUINA', 'Máquinas e ativos produtivos', 3),
        ('VEICULO', 'Veículos', 4),
        ('AJUSTE', 'Ajustes de implantação', 5)
    ) c(codigo, nome, ordem)
  ),
  lote as (
    select l.id, l.codigo, l.valor_referencia_informado
    from f.compromisso_classificacao_lote l
    where l.tenant_id = p_tenant_id
      and l.empresa_id = p_empresa_id
    order by l.created_at desc, l.id desc
    limit 1
  ),
  composicao as (
    select
      d.codigo,
      d.nome,
      d.ordem,
      count(tc.id)::integer as quantidade,
      round(coalesce(sum(tc.valor_referencia_historica), 0), 2)
        as valor
    from categorias_def d
    cross join lote l
    left join f.titulo_classificacao_compromisso tc
      on tc.tenant_id = p_tenant_id
     and tc.empresa_id = p_empresa_id
     and tc.lote_id = l.id
     and tc.categoria = d.codigo
     and tc.deleted_at is null
     and tc.valor_referencia_historica is not null
    group by d.codigo, d.nome, d.ordem
  )
  select jsonb_build_object(
    'loteCodigo', l.codigo,
    'valorReferencia', l.valor_referencia_informado,
    'quantidadeTitulos', sum(c.quantidade),
    'valorReconciliado', round(sum(c.valor), 2),
    'diferencaConciliacao',
      round(sum(c.valor) - l.valor_referencia_informado, 2),
    'categorias', jsonb_agg(
      jsonb_build_object(
        'codigo', c.codigo,
        'nome', c.nome,
        'quantidade', c.quantidade,
        'valor', c.valor,
        'percentual', case
          when l.valor_referencia_informado = 0 then 0
          else round(c.valor / l.valor_referencia_informado * 100, 2)
        end
      )
      order by c.ordem
    )
  )
  into v_resultado
  from lote l
  cross join composicao c
  group by l.codigo, l.valor_referencia_informado;

  return coalesce(
    v_resultado,
    jsonb_build_object(
      'valorReferencia', 0,
      'quantidadeTitulos', 0,
      'valorReconciliado', 0,
      'diferencaConciliacao', 0,
      'categorias', '[]'::jsonb
    )
  );
end;
$$;


ALTER FUNCTION "f"."resumo_classificacao_compromissos_referencia"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."resumo_classificacao_compromissos_referencia"("p_tenant_id" "uuid", "p_empresa_id" "uuid") IS 'Composicao auditada da fotografia historica de R$ 2.129.657,42.';



CREATE OR REPLACE FUNCTION "f"."resumo_estoque_saude_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_fluxo record;
  v_posicao record;
  v_qualidade record;
  v_pendencias jsonb := '[]'::jsonb;
begin
  if p_tenant_id is null
     or p_empresa_id is null
     or p_data_inicio is null
     or p_data_fim is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_id, empresa_id e periodo sao obrigatorios';
  end if;

  if p_data_fim < p_data_inicio then
    raise exception using
      errcode = '22023',
      message = 'Data final nao pode ser anterior a data inicial';
  end if;

  if (p_data_fim - p_data_inicio) > 366 then
    raise exception using
      errcode = '22023',
      message = 'O periodo maximo permitido e de 367 dias';
  end if;

  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuario nao autenticado';
  end if;

  if not exists (
    select 1
    from c.empresa e
    where e.id = p_empresa_id
      and e.tenant_id = p_tenant_id
      and e.deleted_at is null
  ) then
    raise exception using
      errcode = '22023',
      message = 'Empresa nao encontrada no tenant informado';
  end if;

  if public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id() is distinct from p_empresa_id then
    raise exception using
      errcode = '42501',
      message = 'Tenant ou empresa nao corresponde ao contexto ativo';
  end if;

  if not f.has_finance_access(p_tenant_id, p_empresa_id) then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para acessar relatorios financeiros';
  end if;

  with movimentos_periodo as (
    select
      m.id,
      m.tipo,
      coalesce(m.quantidade, 0)::numeric as quantidade,
      m.origem_nf_entrada_id,
      m.origem_os_id,
      nf.os_id as nf_os_id,
      coalesce(
        nullif(m.custo_unitario_real, 0),
        nullif(m.custo_unitario_bruto, 0),
        nullif(i.custo_medio, 0),
        nullif(i.custo_ultima_compra, 0),
        0
      )::numeric as custo_unitario,
      (coalesce(m.custo_unitario_real, 0) <= 0
       and coalesce(m.custo_unitario_bruto, 0) <= 0) as custo_historico_ausente
    from public.movimentacoes m
    join public.itens i
      on i.id = m.item_id
     and i.tenant_id = m.tenant_id
     and i.empresa_id = m.empresa_id
    left join public.nf_entrada nf
      on nf.id = m.origem_nf_entrada_id
     and nf.tenant_id = m.tenant_id
     and nf.empresa_id = m.empresa_id
     and nf.deleted_at is null
    where m.tenant_id = p_tenant_id
      and m.empresa_id = p_empresa_id
      and m.data_movimentacao::date between p_data_inicio and p_data_fim
  )
  select
    coalesce(sum(quantidade * custo_unitario)
      filter (where tipo = 'entrada' and origem_nf_entrada_id is not null and nf_os_id is null), 0)::numeric(18,2)
      as compras_para_estoque,
    coalesce(sum(quantidade * custo_unitario)
      filter (where tipo = 'entrada' and origem_nf_entrada_id is not null and nf_os_id is not null), 0)::numeric(18,2)
      as compras_diretas_os,
    coalesce(sum(quantidade * custo_unitario)
      filter (where tipo = 'entrada' and origem_nf_entrada_id is null), 0)::numeric(18,2)
      as outras_entradas,
    coalesce(sum(quantidade * custo_unitario)
      filter (where tipo = 'saida' and origem_os_id is not null and origem_nf_entrada_id is null), 0)::numeric(18,2)
      as consumo_estoque_os,
    coalesce(sum(quantidade * custo_unitario)
      filter (where tipo = 'saida' and origem_os_id is not null and origem_nf_entrada_id is not null), 0)::numeric(18,2)
      as saidas_diretas_os,
    coalesce(sum(quantidade * custo_unitario)
      filter (where tipo = 'saida' and origem_os_id is null), 0)::numeric(18,2)
      as outras_saidas,
    coalesce(sum(quantidade * custo_unitario)
      filter (where tipo = 'ajuste'), 0)::numeric(18,2)
      as ajustes,
    count(*) filter (
      where tipo = 'saida'
        and custo_historico_ausente
        and custo_unitario > 0
    )::integer as saidas_valorizadas_por_custo_atual,
    count(*) filter (where custo_unitario <= 0)::integer as movimentos_sem_valor
  into v_fluxo
  from movimentos_periodo;

  with movimento_item as (
    select
      m.item_id,
      max(m.data_movimentacao::date) as ultima_movimentacao,
      coalesce(sum(
        case
          when m.data_movimentacao::date between p_data_inicio and p_data_fim then
            case when m.tipo = 'saida' then -coalesce(m.quantidade, 0) else coalesce(m.quantidade, 0) end
          else 0
        end
      ), 0)::numeric as delta_periodo,
      coalesce(sum(
        case
          when m.data_movimentacao::date > p_data_fim then
            case when m.tipo = 'saida' then -coalesce(m.quantidade, 0) else coalesce(m.quantidade, 0) end
          else 0
        end
      ), 0)::numeric as delta_apos_periodo
    from public.movimentacoes m
    where m.tenant_id = p_tenant_id
      and m.empresa_id = p_empresa_id
    group by m.item_id
  ),
  posicao_item as (
    select
      e.item_id,
      coalesce(e.quantidade_atual, 0)::numeric as quantidade_atual,
      (coalesce(e.quantidade_atual, 0) - coalesce(mi.delta_apos_periodo, 0))::numeric as quantidade_fim,
      (
        coalesce(e.quantidade_atual, 0)
        - coalesce(mi.delta_apos_periodo, 0)
        - coalesce(mi.delta_periodo, 0)
      )::numeric as quantidade_inicio,
      coalesce(nullif(i.custo_medio, 0), nullif(i.custo_ultima_compra, 0), 0)::numeric as custo_unitario,
      coalesce(i.estoque_ideal, 0)::numeric as estoque_ideal,
      mi.ultima_movimentacao
    from public.estoque e
    join public.itens i
      on i.id = e.item_id
     and i.tenant_id = e.tenant_id
     and i.empresa_id = e.empresa_id
    left join movimento_item mi
      on mi.item_id = e.item_id
    where e.tenant_id = p_tenant_id
      and e.empresa_id = p_empresa_id
      and coalesce(i.ativo, true)
  )
  select
    coalesce(sum(greatest(quantidade_atual, 0) * custo_unitario), 0)::numeric(18,2) as valor_atual,
    coalesce(sum(greatest(quantidade_inicio, 0) * custo_unitario), 0)::numeric(18,2) as valor_inicio_periodo,
    coalesce(sum(greatest(quantidade_fim, 0) * custo_unitario), 0)::numeric(18,2) as valor_fim_periodo,
    (
      coalesce(sum(greatest(quantidade_fim, 0) * custo_unitario), 0)
      - coalesce(sum(greatest(quantidade_inicio, 0) * custo_unitario), 0)
    )::numeric(18,2) as variacao_periodo,
    count(*) filter (where quantidade_atual > 0)::integer as itens_com_saldo,
    count(*) filter (where quantidade_atual > 0 and custo_unitario <= 0)::integer as itens_sem_custo,
    coalesce(sum(quantidade_atual) filter (where quantidade_atual > 0 and custo_unitario <= 0), 0)::numeric(18,3)
      as quantidade_sem_custo,
    count(*) filter (where quantidade_atual < 0)::integer as itens_negativos,
    coalesce(sum(abs(quantidade_atual)) filter (where quantidade_atual < 0), 0)::numeric(18,3)
      as quantidade_negativa,
    count(*) filter (
      where quantidade_atual > 0
        and (ultima_movimentacao is null or ultima_movimentacao < current_date - 180)
    )::integer as itens_sem_movimento_180d,
    coalesce(sum(quantidade_atual * custo_unitario) filter (
      where quantidade_atual > 0
        and (ultima_movimentacao is null or ultima_movimentacao < current_date - 180)
    ), 0)::numeric(18,2) as valor_sem_movimento_180d,
    count(*) filter (
      where quantidade_atual > estoque_ideal
        and estoque_ideal > 0
    )::integer as itens_acima_ideal,
    coalesce(sum((quantidade_atual - estoque_ideal) * custo_unitario) filter (
      where quantidade_atual > estoque_ideal
        and estoque_ideal > 0
    ), 0)::numeric(18,2) as valor_acima_ideal
  into v_posicao
  from posicao_item;

  with nf_periodo as (
    select nf.id, nf.numero, nf.data_emissao::date as data_emissao
    from public.nf_entrada nf
    where nf.tenant_id = p_tenant_id
      and nf.empresa_id = p_empresa_id
      and nf.deleted_at is null
      and nf.finalidade_contexto in ('materia_prima'::public.item_finalidade, 'revenda'::public.item_finalidade)
      and coalesce(nf.data_emissao::date, nf.criado_em::date) between p_data_inicio and p_data_fim
  ),
  linhas as (
    select
      nfi.id,
      nfi.nf_entrada_id,
      nfi.item_id,
      nfi.descricao,
      coalesce(nfi.v_prod, 0)::numeric as valor
    from public.nf_entrada_itens nfi
    join nf_periodo nf on nf.id = nfi.nf_entrada_id
    where nfi.tenant_id = p_tenant_id
      and nfi.empresa_id = p_empresa_id
  ),
  pendencias as (
    select l.*, 'SEM_CADASTRO'::text as tipo
    from linhas l
    where l.item_id is null
    union all
    select l.*, 'SEM_ENTRADA'::text as tipo
    from linhas l
    where l.item_id is not null
      and not exists (
        select 1
        from public.movimentacoes m
        where m.tenant_id = p_tenant_id
          and m.empresa_id = p_empresa_id
          and m.origem_nf_entrada_id = l.nf_entrada_id
          and m.item_id = l.item_id
          and m.tipo = 'entrada'
      )
  )
  select
    (select count(*) from linhas)::integer as itens_esperados,
    count(*) filter (where tipo = 'SEM_CADASTRO')::integer as itens_sem_cadastro,
    coalesce(sum(valor) filter (where tipo = 'SEM_CADASTRO'), 0)::numeric(18,2) as valor_sem_cadastro,
    count(*) filter (where tipo = 'SEM_ENTRADA')::integer as itens_sem_entrada,
    coalesce(sum(valor) filter (where tipo = 'SEM_ENTRADA'), 0)::numeric(18,2) as valor_sem_entrada
  into v_qualidade
  from pendencias;

  with nf_periodo as (
    select nf.id, nf.numero, nf.data_emissao::date as data_emissao
    from public.nf_entrada nf
    where nf.tenant_id = p_tenant_id
      and nf.empresa_id = p_empresa_id
      and nf.deleted_at is null
      and nf.finalidade_contexto in ('materia_prima'::public.item_finalidade, 'revenda'::public.item_finalidade)
      and coalesce(nf.data_emissao::date, nf.criado_em::date) between p_data_inicio and p_data_fim
  ),
  pendencias as (
    select
      nf.id as nf_id,
      nf.numero,
      nf.data_emissao,
      nfi.descricao,
      coalesce(nfi.v_prod, 0)::numeric as valor,
      case
        when nfi.item_id is null then 'SEM_CADASTRO'
        else 'SEM_ENTRADA'
      end as tipo
    from nf_periodo nf
    join public.nf_entrada_itens nfi
      on nfi.nf_entrada_id = nf.id
     and nfi.tenant_id = p_tenant_id
     and nfi.empresa_id = p_empresa_id
    where nfi.item_id is null
       or not exists (
         select 1
         from public.movimentacoes m
         where m.tenant_id = p_tenant_id
           and m.empresa_id = p_empresa_id
           and m.origem_nf_entrada_id = nfi.nf_entrada_id
           and m.item_id = nfi.item_id
           and m.tipo = 'entrada'
       )
  ),
  destaque as (
    select *
    from pendencias
    order by data_emissao desc nulls last, valor desc, nf_id desc
    limit 8
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'tipo', tipo,
        'nfId', nf_id,
        'nfNumero', coalesce(numero, '-'),
        'data', data_emissao,
        'descricao', coalesce(nullif(btrim(descricao), ''), 'Item sem descricao'),
        'valor', valor
      )
      order by data_emissao desc nulls last, valor desc
    ),
    '[]'::jsonb
  )
  into v_pendencias
  from destaque;

  return jsonb_build_object(
    'meta', jsonb_build_object(
      'tenantId', p_tenant_id,
      'empresaId', p_empresa_id,
      'dataInicio', p_data_inicio,
      'dataFim', p_data_fim,
      'posicaoAtualEm', current_date,
      'criterioValoracao', 'CUSTO_MEDIO_ATUAL_COM_FALLBACK_ULTIMA_COMPRA'
    ),
    'periodo', jsonb_build_object(
      'comprasParaEstoque', coalesce(v_fluxo.compras_para_estoque, 0),
      'comprasDiretasOs', coalesce(v_fluxo.compras_diretas_os, 0),
      'outrasEntradas', coalesce(v_fluxo.outras_entradas, 0),
      'consumoEstoqueOs', coalesce(v_fluxo.consumo_estoque_os, 0),
      'saidasDiretasOs', coalesce(v_fluxo.saidas_diretas_os, 0),
      'outrasSaidas', coalesce(v_fluxo.outras_saidas, 0),
      'ajustes', coalesce(v_fluxo.ajustes, 0),
      'saidasValorizadasPorCustoAtual', coalesce(v_fluxo.saidas_valorizadas_por_custo_atual, 0),
      'movimentosSemValor', coalesce(v_fluxo.movimentos_sem_valor, 0)
    ),
    'posicao', jsonb_build_object(
      'valorAtual', coalesce(v_posicao.valor_atual, 0),
      'valorInicioPeriodo', coalesce(v_posicao.valor_inicio_periodo, 0),
      'valorFimPeriodo', coalesce(v_posicao.valor_fim_periodo, 0),
      'variacaoPeriodo', coalesce(v_posicao.variacao_periodo, 0),
      'itensComSaldo', coalesce(v_posicao.itens_com_saldo, 0),
      'itensSemCusto', coalesce(v_posicao.itens_sem_custo, 0),
      'quantidadeSemCusto', coalesce(v_posicao.quantidade_sem_custo, 0),
      'itensNegativos', coalesce(v_posicao.itens_negativos, 0),
      'quantidadeNegativa', coalesce(v_posicao.quantidade_negativa, 0),
      'itensSemMovimento180d', coalesce(v_posicao.itens_sem_movimento_180d, 0),
      'valorSemMovimento180d', coalesce(v_posicao.valor_sem_movimento_180d, 0),
      'itensAcimaIdeal', coalesce(v_posicao.itens_acima_ideal, 0),
      'valorAcimaIdeal', coalesce(v_posicao.valor_acima_ideal, 0)
    ),
    'qualidade', jsonb_build_object(
      'itensEsperados', coalesce(v_qualidade.itens_esperados, 0),
      'itensSemCadastro', coalesce(v_qualidade.itens_sem_cadastro, 0),
      'valorSemCadastro', coalesce(v_qualidade.valor_sem_cadastro, 0),
      'itensSemEntrada', coalesce(v_qualidade.itens_sem_entrada, 0),
      'valorSemEntrada', coalesce(v_qualidade.valor_sem_entrada, 0)
    ),
    'pendencias', coalesce(v_pendencias, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "f"."resumo_estoque_saude_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."resumo_estoque_saude_financeira"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") IS 'Cruza compras, movimentacoes fisicas, consumo por OS, posicao valorizada e pendencias cadastrais do estoque no tenant e empresa ativos.';



CREATE OR REPLACE FUNCTION "f"."resumo_legado_implantacao_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f'
    SET "row_security" TO 'off'
    AS $$
  select jsonb_build_object(
    'tituloQtd', count(*),
    'parcelaQtd', coalesce(sum(li.parcelas_abertas_snapshot), 0),
    'valorAberto', round(coalesce(sum(li.valor_aberto_snapshot), 0), 2),
    'valorParcelasAberto',
      round(coalesce(sum(li.valor_parcelas_abertas_snapshot), 0), 2),
    'corte', max(li.corte_date),
    'marcadoEm', max(li.marcado_em)
  )
  from f.titulo_legado_implantacao li
  where li.tenant_id = p_tenant_id
    and li.empresa_id = p_empresa_id
    and li.desmarcado_em is null;
$$;


ALTER FUNCTION "f"."resumo_legado_implantacao_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."revisar_valor_final_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid", "p_novo_valor_final" numeric, "p_motivo" "text", "p_origem" "text" DEFAULT 'REVISAO_MANUAL'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_titulo f.titulo%rowtype;
  v_parcela f.titulo_parcela%rowtype;
  v_usuario_id uuid;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_origem text := upper(coalesce(nullif(btrim(p_origem), ''), 'REVISAO_MANUAL'));
  v_novo_valor numeric(15,2) := round(coalesce(p_novo_valor_final, 0), 2);
  v_valor_pago numeric(15,2);
  v_novo_aberto numeric(15,2);
  v_titulo_total_novo numeric(15,2);
  v_titulo_aberto_novo numeric(15,2);
  v_status_novo text;
  v_rateios_ajustados boolean := false;
  v_rateio_fixo_total_anterior numeric(15,2);
  v_rateio_fixo_total_novo numeric(15,2);
  v_rateio_fixo_ultimo_id uuid;
begin
  if p_tenant_id is null
     or p_empresa_id is null
     or p_titulo_id is null
     or p_titulo_parcela_id is null then
    raise exception 'Tenant, empresa, titulo e parcela sao obrigatorios';
  end if;

  if p_novo_valor_final is null or v_novo_valor <= 0 then
    raise exception 'O novo valor final deve ser maior que zero';
  end if;

  if v_motivo is null or length(v_motivo) < 5 then
    raise exception 'Informe o motivo da revisao (minimo 5 caracteres)';
  end if;

  if auth.uid() is not null then
    if p_tenant_id is distinct from public.current_tenant_id()
       or not f.has_finance_access(p_tenant_id, p_empresa_id) then
      raise exception 'Sem acesso financeiro ao tenant/empresa solicitado';
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role'
        and current_user not in ('postgres', 'service_role') then
    raise exception 'Usuario nao autenticado';
  end if;

  select t.*
    into v_titulo
  from f.titulo t
  where t.id = p_titulo_id
    and t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id
    and t.deleted_at is null
  for update;

  if not found then
    raise exception 'Titulo AP nao encontrado no tenant/empresa informado';
  end if;

  if v_titulo.tipo <> 'AP' then
    raise exception 'A revisao de valor final permite somente titulos AP';
  end if;

  if v_titulo.status = 'CANCELADO' then
    raise exception 'Nao e possivel revisar um titulo cancelado';
  end if;

  select tp.*
    into v_parcela
  from f.titulo_parcela tp
  where tp.id = p_titulo_parcela_id
    and tp.tenant_id = p_tenant_id
    and tp.titulo_id = p_titulo_id
    and tp.deleted_at is null
  for update;

  if not found then
    raise exception 'Parcela nao encontrada para o titulo informado';
  end if;

  select coalesce(sum(pi.valor), 0)::numeric(15,2)
    into v_valor_pago
  from f.pagamento_item pi
  join f.pagamento p
    on p.id = pi.pagamento_id
   and p.tenant_id = p_tenant_id
   and p.empresa_id = p_empresa_id
   and p.deleted_at is null
  where pi.tenant_id = p_tenant_id
    and pi.empresa_id = p_empresa_id
    and pi.titulo_parcela_id = p_titulo_parcela_id
    and pi.deleted_at is null;

  v_valor_pago := round(coalesce(v_valor_pago, 0), 2);

  if v_novo_valor < v_valor_pago then
    raise exception
      'Novo valor final (%) nao pode ser menor que o total ja pago (%)',
      v_novo_valor,
      v_valor_pago;
  end if;

  if v_novo_valor = round(v_parcela.valor, 2) then
    raise exception 'O novo valor final e igual ao valor atual da parcela';
  end if;

  v_usuario_id := a.fn_current_usuario_id();
  if v_usuario_id is null then
    select ut.usuario_id
      into v_usuario_id
    from a.usuario_tenant ut
    where ut.tenant_id = p_tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER', 'ADMIN')
    order by ut.created_at nulls last
    limit 1;
  end if;

  v_novo_aberto := round(v_novo_valor - v_valor_pago, 2);

  update f.titulo_parcela tp
  set valor = v_novo_valor,
      valor_aberto = v_novo_aberto,
      updated_at = now(),
      updated_by = v_usuario_id
  where tp.id = v_parcela.id
    and tp.tenant_id = p_tenant_id;

  select
    coalesce(sum(tp.valor), 0)::numeric(15,2),
    coalesce(sum(tp.valor_aberto), 0)::numeric(15,2)
  into v_titulo_total_novo, v_titulo_aberto_novo
  from f.titulo_parcela tp
  where tp.tenant_id = p_tenant_id
    and tp.titulo_id = p_titulo_id
    and tp.deleted_at is null;

  v_status_novo := case
    when v_titulo_aberto_novo = 0 then 'PAGO'
    when v_titulo.status = 'PAGO' and exists (
      select 1
      from f.titulo_aprovacao ta
      where ta.tenant_id = p_tenant_id
        and ta.titulo_id = p_titulo_id
        and ta.deleted_at is null
    ) then 'APROVADO'
    when v_titulo.status = 'PAGO' then 'PENDENTE'
    else v_titulo.status
  end;

  -- Rateios somente em valor podem ser proporcionados antes do titulo porque
  -- o trigger imediato nao faz a validacao cruzada percentual x valor.
  select coalesce(sum(tr.valor), 0)::numeric(15,2)
    into v_rateio_fixo_total_anterior
  from f.titulo_rateio tr
  where tr.tenant_id = p_tenant_id
    and tr.titulo_id = p_titulo_id
    and tr.deleted_at is null
    and tr.percentual is null
    and tr.valor is not null;

  if v_titulo.valor_total > 0
     and abs(v_rateio_fixo_total_anterior - v_titulo.valor_total) <= 0.02
     and exists (
       select 1
       from f.titulo_rateio tr
       where tr.tenant_id = p_tenant_id
         and tr.titulo_id = p_titulo_id
         and tr.deleted_at is null
         and tr.percentual is null
         and tr.valor is not null
     ) then
    update f.titulo_rateio tr
    set valor = round(tr.valor * v_titulo_total_novo / v_titulo.valor_total, 2),
        updated_at = now(),
        updated_by = v_usuario_id
    where tr.tenant_id = p_tenant_id
      and tr.titulo_id = p_titulo_id
      and tr.deleted_at is null
      and tr.percentual is null
      and tr.valor is not null;

    select coalesce(sum(tr.valor), 0)::numeric(15,2)
      into v_rateio_fixo_total_novo
    from f.titulo_rateio tr
    where tr.tenant_id = p_tenant_id
      and tr.titulo_id = p_titulo_id
      and tr.deleted_at is null
      and tr.percentual is null
      and tr.valor is not null;

    select tr.id
      into v_rateio_fixo_ultimo_id
    from f.titulo_rateio tr
    where tr.tenant_id = p_tenant_id
      and tr.titulo_id = p_titulo_id
      and tr.deleted_at is null
      and tr.percentual is null
      and tr.valor is not null
    order by tr.id desc
    limit 1;

    if v_rateio_fixo_ultimo_id is not null
       and v_rateio_fixo_total_novo is distinct from v_titulo_total_novo then
      update f.titulo_rateio tr
      set valor = round(tr.valor + (v_titulo_total_novo - v_rateio_fixo_total_novo), 2),
          updated_at = now(),
          updated_by = v_usuario_id
      where tr.id = v_rateio_fixo_ultimo_id
        and tr.tenant_id = p_tenant_id;
    end if;

    v_rateios_ajustados := true;
  end if;

  update f.titulo t
  set valor_total = v_titulo_total_novo,
      valor_aberto = v_titulo_aberto_novo,
      status = v_status_novo,
      updated_at = now(),
      updated_by = v_usuario_id
  where t.id = p_titulo_id
    and t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id;

  -- Com o novo total ja visivel, o trigger permite recalcular os rateios que
  -- armazenam simultaneamente percentual e valor.
  update f.titulo_rateio tr
  set valor = round(v_titulo_total_novo * tr.percentual / 100.0, 2),
      updated_at = now(),
      updated_by = v_usuario_id
  where tr.tenant_id = p_tenant_id
    and tr.titulo_id = p_titulo_id
    and tr.deleted_at is null
    and tr.percentual is not null
    and tr.valor is not null
    and tr.valor is distinct from round(v_titulo_total_novo * tr.percentual / 100.0, 2);

  if found then
    v_rateios_ajustados := true;
  end if;

  insert into f.evento_financeiro (
    tenant_id,
    empresa_id,
    evento,
    ref_table,
    ref_id,
    payload,
    created_at,
    created_by
  ) values (
    p_tenant_id,
    p_empresa_id,
    'VALOR_FINAL_AP_REVISADO',
    'f.titulo',
    p_titulo_id,
    jsonb_build_object(
      'titulo_id', p_titulo_id,
      'titulo_parcela_id', p_titulo_parcela_id,
      'parcela_numero', v_parcela.numero,
      'valor_anterior', round(v_parcela.valor, 2),
      'valor_novo', v_novo_valor,
      'diferenca', round(v_novo_valor - v_parcela.valor, 2),
      'valor_pago', v_valor_pago,
      'saldo_anterior', round(v_parcela.valor_aberto, 2),
      'saldo_novo', v_novo_aberto,
      'titulo_valor_anterior', round(v_titulo.valor_total, 2),
      'titulo_valor_novo', v_titulo_total_novo,
      'titulo_saldo_anterior', round(v_titulo.valor_aberto, 2),
      'titulo_saldo_novo', v_titulo_aberto_novo,
      'status_anterior', v_titulo.status,
      'status_novo', v_status_novo,
      'rateios_ajustados', v_rateios_ajustados,
      'motivo', v_motivo,
      'origem', v_origem
    ),
    now(),
    v_usuario_id
  );

  return jsonb_build_object(
    'tituloId', p_titulo_id,
    'parcelaId', p_titulo_parcela_id,
    'valorAnterior', round(v_parcela.valor, 2),
    'valorNovo', v_novo_valor,
    'valorPago', v_valor_pago,
    'saldoNovo', v_novo_aberto,
    'statusNovo', v_status_novo
  );
end;
$$;


ALTER FUNCTION "f"."revisar_valor_final_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid", "p_novo_valor_final" numeric, "p_motivo" "text", "p_origem" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."revisar_valor_final_ap"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid", "p_titulo_parcela_id" "uuid", "p_novo_valor_final" numeric, "p_motivo" "text", "p_origem" "text") IS 'Revisa o valor efetivo de uma parcela AP, preserva pagamentos e grava trilha auditavel.';



CREATE OR REPLACE FUNCTION "f"."salvar_regra_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_regra_id" "uuid", "p_motivo_compra_id" "uuid", "p_ativo" boolean, "p_itens" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_regra_id uuid;
  v_plano_motivo uuid;
  v_item jsonb;
  v_centro_id uuid;
  v_plano_id uuid;
  v_percentual numeric(7,4);
  v_total numeric := 0;
  v_quantidade integer;
  v_distintos integer;
begin
  if auth.uid() is not null
     and not f.pode_escrever_regras_rateio(
       p_tenant_id,
       p_empresa_id
     )
  then
    raise exception using
      errcode = '42501',
      message = 'Sem permissao para alterar regras de rateio desta empresa.';
  end if;

  if p_motivo_compra_id is null then
    raise exception using
      errcode = '23502',
      message = 'Regra de rateio: motivo de compra e obrigatorio.';
  end if;

  select mc.plano_contas_id
    into v_plano_motivo
  from f.motivo_compra mc
  join f.plano_contas pc
    on pc.id = mc.plano_contas_id
   and pc.tenant_id = mc.tenant_id
   and pc.tipo = 'ANALITICA'
   and pc.ativo
   and pc.deleted_at is null
  where mc.id = p_motivo_compra_id
    and mc.tenant_id = p_tenant_id
    and mc.ativo
    and mc.deleted_at is null;

  if v_plano_motivo is null then
    raise exception using
      errcode = '23503',
      message = 'Regra de rateio: motivo sem plano analitico ativo.';
  end if;

  if p_itens is null
     or jsonb_typeof(p_itens) <> 'array'
     or jsonb_array_length(p_itens) = 0
  then
    raise exception using
      errcode = '23514',
      message = 'Regra de rateio: informe ao menos um destino.';
  end if;

  if jsonb_array_length(p_itens) > 50 then
    raise exception using
      errcode = '54000',
      message = 'Regra de rateio: limite de 50 destinos excedido.';
  end if;

  select
    count(*)::integer,
    count(distinct nullif(item ->> 'centro_custo_id', ''))::integer,
    coalesce(sum((item ->> 'percentual')::numeric), 0)
    into v_quantidade, v_distintos, v_total
  from jsonb_array_elements(p_itens) item;

  if v_quantidade <> v_distintos then
    raise exception using
      errcode = '23505',
      message = 'Regra de rateio: o mesmo centro nao pode aparecer duas vezes.';
  end if;

  if abs(v_total - 100.0000) > 0.0001 then
    raise exception using
      errcode = '23514',
      message = format(
        'Regra de rateio: os percentuais devem somar 100%% (soma atual: %s%%).',
        round(v_total, 4)
      );
  end if;

  if p_regra_id is null then
    insert into f.regra_rateio (
      tenant_id,
      empresa_id,
      motivo_compra_id,
      ativo
    )
    values (
      p_tenant_id,
      p_empresa_id,
      p_motivo_compra_id,
      coalesce(p_ativo, true)
    )
    returning id into v_regra_id;
  else
    select rr.id
      into v_regra_id
    from f.regra_rateio rr
    where rr.id = p_regra_id
      and rr.tenant_id = p_tenant_id
      and rr.empresa_id = p_empresa_id
      and rr.deleted_at is null
    for update;

    if not found then
      raise exception using
        errcode = 'P0002',
        message = 'Regra de rateio nao encontrada nesta empresa.';
    end if;

    update f.regra_rateio rr
    set
      motivo_compra_id = p_motivo_compra_id,
      ativo = coalesce(p_ativo, true),
      updated_at = now(),
      updated_by = a.fn_current_usuario_id()
    where rr.id = v_regra_id
      and rr.tenant_id = p_tenant_id
      and rr.empresa_id = p_empresa_id;

    update f.regra_rateio_item rri
    set
      deleted_at = now(),
      updated_at = now(),
      updated_by = a.fn_current_usuario_id()
    where rri.tenant_id = p_tenant_id
      and rri.regra_rateio_id = v_regra_id
      and rri.deleted_at is null;
  end if;

  for v_item in
    select value from jsonb_array_elements(p_itens)
  loop
    begin
      v_centro_id := nullif(v_item ->> 'centro_custo_id', '')::uuid;
      v_plano_id := nullif(v_item ->> 'plano_contas_id', '')::uuid;
      v_percentual := (v_item ->> 'percentual')::numeric(7,4);
    exception
      when invalid_text_representation or numeric_value_out_of_range then
        raise exception using
          errcode = '22023',
          message = 'Regra de rateio: destino com dados invalidos.';
    end;

    if v_plano_id is distinct from v_plano_motivo then
      raise exception using
        errcode = '23514',
        message = 'Regra de rateio: o plano deve ser o plano definido no motivo.';
    end if;

    if v_centro_id is null
       or v_percentual is null
       or v_percentual <= 0
       or v_percentual > 100
    then
      raise exception using
        errcode = '23514',
        message = 'Regra de rateio: centro e percentual valido sao obrigatorios.';
    end if;

    insert into f.regra_rateio_item (
      tenant_id,
      regra_rateio_id,
      plano_contas_id,
      centro_custo_id,
      percentual
    )
    values (
      p_tenant_id,
      v_regra_id,
      v_plano_id,
      v_centro_id,
      v_percentual
    );
  end loop;

  return jsonb_build_object(
    'id', v_regra_id,
    'motivo_compra_id', p_motivo_compra_id,
    'ativo', coalesce(p_ativo, true),
    'destinos', jsonb_array_length(p_itens)
  );
end;
$$;


ALTER FUNCTION "f"."salvar_regra_rateio"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_regra_id" "uuid", "p_motivo_compra_id" "uuid", "p_ativo" boolean, "p_itens" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."seed_financeiro_defaults"("p_tenant" "uuid", "p_empresa" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  -- motivos padrão
  insert into f.motivo_compra (tenant_id, codigo, nome, requires_text, requires_os, ativo)
  values
    (p_tenant, 'OS', 'ORDEM DE SERVICO', false, true, true),
    (p_tenant, 'ESTOQUE', 'ESTOQUE', false, false, true),
    (p_tenant, 'INVESTIMENTO', 'INVESTIMENTO', false, false, true),
    (p_tenant, 'MANUTENCAO', 'MANUTENCAO', false, false, true),
    (p_tenant, 'EPI', 'EPI', false, false, true),
    (p_tenant, 'OUTROS', 'OUTROS', true, false, true)
  on conflict (tenant_id, codigo) do nothing;

  -- (opcional) garantir um fin_config por empresa
  insert into f.fin_config (tenant_id, empresa_id)
  values (p_tenant, p_empresa)
  on conflict (tenant_id, empresa_id) do nothing;
end;
$$;


ALTER FUNCTION "f"."seed_financeiro_defaults"("p_tenant" "uuid", "p_empresa" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."snapshot_inconsistencia_financeira_titulo"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
  select jsonb_build_object(
    'titulo', jsonb_build_object(
      'id', t.id,
      'tipo', t.tipo,
      'status', t.status,
      'origem', t.origem,
      'descricao', t.descricao,
      'fornecedorId', t.fornecedor_id,
      'documentoFiscalId', t.documento_fiscal_id,
      'emissao', t.emissao_date,
      'competencia', t.competencia_date,
      'valorTotal', t.valor_total,
      'valorAberto', t.valor_aberto,
      'motivoCompraId', t.motivo_compra_id
    ),
    'rateios', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', tr.id,
          'planoContasId', tr.plano_contas_id,
          'centroCustoId', tr.centro_custo_id,
          'osId', tr.os_id,
          'percentual', tr.percentual,
          'valor', tr.valor,
          'origemRateio', tr.origem_rateio,
          'regraRateioId', tr.regra_rateio_id,
          'regraItemId', tr.regra_item_id
        )
        order by tr.id
      )
      from f.titulo_rateio tr
      where tr.tenant_id = p_tenant_id
        and tr.titulo_id = p_titulo_id
        and tr.deleted_at is null
    ), '[]'::jsonb),
    'imutaveis', jsonb_build_object(
      'valorTotal', t.valor_total,
      'valorAberto', t.valor_aberto,
      'parcelas', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', tp.id,
            'numero', tp.numero,
            'vencimento', tp.vencimento_date,
            'valor', tp.valor,
            'valorAberto', tp.valor_aberto
          )
          order by tp.id
        )
        from f.titulo_parcela tp
        where tp.tenant_id = p_tenant_id
          and tp.titulo_id = p_titulo_id
          and tp.deleted_at is null
      ), '[]'::jsonb),
      'pagamentos', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'pagamentoItemId', pi.id,
            'pagamentoId', pag.id,
            'parcelaId', pi.titulo_parcela_id,
            'data', pag.data_pagamento,
            'valorItem', pi.valor,
            'valorPagamento', pag.valor
          )
          order by pi.id
        )
        from f.titulo_parcela tp
        join f.pagamento_item pi
          on pi.tenant_id = p_tenant_id
         and pi.titulo_parcela_id = tp.id
         and pi.deleted_at is null
        join f.pagamento pag
          on pag.tenant_id = p_tenant_id
         and pag.empresa_id = p_empresa_id
         and pag.id = pi.pagamento_id
         and pag.deleted_at is null
        where tp.tenant_id = p_tenant_id
          and tp.titulo_id = p_titulo_id
          and tp.deleted_at is null
      ), '[]'::jsonb)
    )
  )
  from f.titulo t
  where t.id = p_titulo_id
    and t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id;
$$;


ALTER FUNCTION "f"."snapshot_inconsistencia_financeira_titulo"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."titulo_eh_legado_implantacao"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'f'
    AS $$
  select exists (
    select 1
    from f.titulo_legado_implantacao li
    where li.tenant_id = p_tenant_id
      and li.empresa_id = p_empresa_id
      and li.titulo_id = p_titulo_id
      and li.desmarcado_em is null
  );
$$;


ALTER FUNCTION "f"."titulo_eh_legado_implantacao"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "f"."titulo_eh_legado_implantacao"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_titulo_id" "uuid") IS 'Consulta a marcacao ativa de legado respeitando as politicas RLS do chamador. Em RPCs security definer, herda o escopo seguro da funcao chamadora.';



CREATE OR REPLACE FUNCTION "f"."trg_centro_custo_validar_hierarquia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_cursor uuid;
  v_parent_ativo boolean;
  v_visitados uuid[] := array[]::uuid[];
begin
  if new.parent_id is not null then
    if new.parent_id = new.id then
      raise exception using
        errcode = '23514',
        message = 'Centro de custo nao pode ser pai de si mesmo.';
    end if;

    select cc.parent_id, cc.ativo
      into v_cursor, v_parent_ativo
    from f.centro_custo cc
    where cc.id = new.parent_id
      and cc.tenant_id = new.tenant_id
      and cc.empresa_id = new.empresa_id
      and cc.deleted_at is null;

    if not found then
      raise exception using
        errcode = '23503',
        message = 'Centro pai invalido ou de outra empresa.';
    end if;

    if new.ativo and not v_parent_ativo then
      raise exception using
        errcode = '23514',
        message = 'Centro ativo nao pode ficar abaixo de um centro pai inativo.';
    end if;

    v_visitados := array_append(v_visitados, new.parent_id);
    while v_cursor is not null loop
      if v_cursor = new.id then
        raise exception using
          errcode = '23514',
          message = 'A hierarquia de centros de custo nao pode conter ciclos.';
      end if;
      if v_cursor = any(v_visitados) then
        raise exception using
          errcode = '23514',
          message = 'A hierarquia existente de centros de custo possui um ciclo.';
      end if;
      v_visitados := array_append(v_visitados, v_cursor);

      select cc.parent_id
        into v_cursor
      from f.centro_custo cc
      where cc.id = v_cursor
        and cc.tenant_id = new.tenant_id
        and cc.empresa_id = new.empresa_id
        and cc.deleted_at is null;

      if not found then
        raise exception using
          errcode = '23503',
          message = 'A hierarquia referencia centro de outra empresa ou excluido.';
      end if;
    end loop;
  end if;

  if tg_op = 'UPDATE'
     and old.deleted_at is null
     and (
       (old.ativo and not new.ativo)
       or new.deleted_at is not null
     )
  then
    if new.deleted_at is not null
       and exists (
         select 1
         from f.centro_custo filho
         where filho.tenant_id = new.tenant_id
           and filho.empresa_id = new.empresa_id
           and filho.parent_id = new.id
           and filho.deleted_at is null
       )
    then
      raise exception using
        errcode = '23514',
        message = 'Mova ou arquive os centros filhos antes de arquivar o centro principal.';
    end if;

    if not new.ativo
       and exists (
         with recursive descendentes as (
           select filho.id, filho.ativo
           from f.centro_custo filho
           where filho.tenant_id = new.tenant_id
             and filho.empresa_id = new.empresa_id
             and filho.parent_id = new.id
             and filho.deleted_at is null
           union
           select filho.id, filho.ativo
           from f.centro_custo filho
           join descendentes d on d.id = filho.parent_id
           where filho.tenant_id = new.tenant_id
             and filho.empresa_id = new.empresa_id
             and filho.deleted_at is null
         )
         select 1 from descendentes where ativo limit 1
       )
    then
      raise exception using
        errcode = '23514',
        message = 'Desative ou mova os centros subordinados antes de desativar o centro principal.';
    end if;

    if exists (
      select 1
      from f.regra_rateio_item rri
      join f.regra_rateio rr
        on rr.id = rri.regra_rateio_id
       and rr.tenant_id = rri.tenant_id
      where rri.tenant_id = new.tenant_id
        and rri.centro_custo_id = new.id
        and rri.deleted_at is null
        and rr.empresa_id = new.empresa_id
        and rr.ativo
        and rr.deleted_at is null
    ) then
      raise exception using
        errcode = '23514',
        message = 'Arquive ou altere as regras ativas antes de desativar este centro.';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


