CREATE OR REPLACE FUNCTION "f"."trg_titulo_classificacao_compromisso_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_legado boolean;
begin
  if tg_op = 'UPDATE'
     and (
       new.tenant_id,
       new.empresa_id,
       new.titulo_id,
       new.lote_id
     ) is distinct from (
       old.tenant_id,
       old.empresa_id,
       old.titulo_id,
       old.lote_id
     )
  then
    raise exception
      'Classificacao: chaves de escopo e origem sao imutaveis.';
  end if;

  if tg_op = 'INSERT' and new.deleted_at is not null then
    raise exception 'Classificacao nao pode nascer revertida.';
  end if;

  if new.deleted_at is null then
    if not exists (
      select 1
      from f.titulo t
      where t.id = new.titulo_id
        and t.tenant_id = new.tenant_id
        and t.empresa_id = new.empresa_id
        and t.tipo = 'AP'
        and t.deleted_at is null
        and t.status <> 'CANCELADO'
    ) then
      raise exception
        'Classificacao: titulo AP invalido ou fora do tenant/empresa.';
    end if;

    if not exists (
      select 1
      from f.compromisso_classificacao_lote l
      where l.id = new.lote_id
        and l.tenant_id = new.tenant_id
        and l.empresa_id = new.empresa_id
    ) then
      raise exception
        'Classificacao: lote invalido ou fora do tenant/empresa.';
    end if;

    select exists (
      select 1
      from f.titulo_legado_implantacao li
      where li.tenant_id = new.tenant_id
        and li.empresa_id = new.empresa_id
        and li.titulo_id = new.titulo_id
        and li.desmarcado_em is null
    )
    into v_legado;

    if new.categoria = 'AJUSTE' and not v_legado then
      raise exception
        'Classificacao: AJUSTE exige marcacao ativa de legado de implantacao.';
    end if;

    if new.categoria <> 'AJUSTE' and v_legado then
      raise exception
        'Classificacao: titulo legado deve permanecer exclusivamente em AJUSTE.';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "f"."trg_titulo_classificacao_compromisso_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."trg_titulo_rateio_preparar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_empresa_id uuid;
  v_valor_titulo numeric;
  v_titulo_status text;
  v_titulo_deleted_at timestamptz;
begin
  -- Serializa todas as escritas do mesmo titulo antes da validacao diferida.
  if tg_op = 'UPDATE'
     and (
       old.tenant_id is distinct from new.tenant_id
       or old.titulo_id is distinct from new.titulo_id
     )
  then
    perform 1
    from f.titulo t
    where t.tenant_id = old.tenant_id
      and t.id = old.titulo_id
    for update;
  end if;

  select t.empresa_id, t.valor_total, t.status, t.deleted_at
    into
      v_empresa_id,
      v_valor_titulo,
      v_titulo_status,
      v_titulo_deleted_at
  from f.titulo t
  where t.tenant_id = new.tenant_id
    and t.id = new.titulo_id
  for update;

  if not found then
    raise exception using
      errcode = '23503',
      message = format(
        'Rateio: titulo %s nao pertence ao tenant informado.',
        new.titulo_id
      );
  end if;

  if new.deleted_at is not null then
    return new;
  end if;

  if v_titulo_deleted_at is not null or v_titulo_status = 'CANCELADO' then
    raise exception using
      errcode = '23514',
      message = 'Rateio: nao e permitido criar ou reativar rateio em titulo excluido ou cancelado.';
  end if;

  if new.plano_contas_id is null then
    raise exception using
      errcode = '23514',
      message = 'Rateio: plano de contas e obrigatorio.';
  end if;

  if not exists (
    select 1
    from f.plano_contas pc
    where pc.tenant_id = new.tenant_id
      and pc.id = new.plano_contas_id
      and pc.ativo
      and pc.deleted_at is null
  ) then
    raise exception using
      errcode = '23503',
      message = 'Rateio: plano de contas invalido, inativo ou de outro tenant.';
  end if;

  if new.centro_custo_id is not null
     and not exists (
       select 1
       from f.centro_custo cc
       where cc.tenant_id = new.tenant_id
         and cc.empresa_id = v_empresa_id
         and cc.id = new.centro_custo_id
         and cc.ativo
         and cc.deleted_at is null
     )
  then
    raise exception using
      errcode = '23503',
      message = 'Rateio: centro de custo invalido ou de outra empresa.';
  end if;

  if new.os_id is not null
     and not exists (
       select 1
       from public.ordens_servico os
       where os.tenant_id = new.tenant_id
         and os.empresa_id = v_empresa_id
         and os.id = new.os_id
     )
  then
    raise exception using
      errcode = '23503',
      message = 'Rateio: ordem de servico invalida ou de outra empresa.';
  end if;

  if new.percentual is null and new.valor is null then
    raise exception using
      errcode = '23514',
      message = 'Rateio: informe percentual ou valor.';
  end if;

  if new.percentual is not null
     and new.valor is not null
     and abs(
       new.valor
       - round(coalesce(v_valor_titulo, 0) * new.percentual / 100.0, 2)
     ) > 0.01
  then
    raise exception using
      errcode = '23514',
      message = format(
        'Rateio: percentual %s%% equivale a %s, mas o valor informado e %s.',
        new.percentual,
        round(coalesce(v_valor_titulo, 0) * new.percentual / 100.0, 2),
        new.valor
      );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "f"."trg_titulo_rateio_preparar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."trg_titulo_rateio_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform f.validar_consistencia_rateio_titulo(
      old.tenant_id,
      old.titulo_id
    );
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    if tg_op = 'INSERT'
       or new.tenant_id is distinct from old.tenant_id
       or new.titulo_id is distinct from old.titulo_id
       or new.deleted_at is distinct from old.deleted_at
       or new.plano_contas_id is distinct from old.plano_contas_id
       or new.centro_custo_id is distinct from old.centro_custo_id
       or new.os_id is distinct from old.os_id
       or new.percentual is distinct from old.percentual
       or new.valor is distinct from old.valor
    then
      perform f.validar_consistencia_rateio_titulo(
        new.tenant_id,
        new.titulo_id
      );
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "f"."trg_titulo_rateio_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."trg_titulo_reaplicar_regra_rateio"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_resultado jsonb;
begin
  if new.tipo <> 'AP'
     or new.deleted_at is not null
     or new.status = 'CANCELADO'
  then
    return new;
  end if;

  v_resultado := f.aplicar_regra_rateio_titulo(
    new.tenant_id,
    new.id,
    true
  );

  if v_resultado ->> 'status' in (
    'MOTIVO_AUSENTE',
    'MOTIVO_INVALIDO',
    'SEM_REGRA'
  ) then
    perform f.garantir_rateio_fallback_titulo(
      new.tenant_id,
      new.id
    );
  end if;
  return new;
end;
$$;


