CREATE OR REPLACE FUNCTION "f"."validar_consistencia_rateio_titulo"("p_tenant_id" "uuid", "p_titulo_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_valor_titulo numeric;
  v_quantidade bigint;
  v_percentual numeric;
  v_valor numeric;
  v_duplicidades bigint;
begin
  if p_tenant_id is null or p_titulo_id is null then
    return;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'TITULO_RATEIO:' || p_tenant_id::text || ':' || p_titulo_id::text,
      0
    )
  );

  select t.valor_total
    into v_valor_titulo
  from f.titulo t
  where t.tenant_id = p_tenant_id
    and t.id = p_titulo_id
  for update;

  if not found then
    if exists (
      select 1
      from f.titulo_rateio tr
      where tr.tenant_id = p_tenant_id
        and tr.titulo_id = p_titulo_id
        and tr.deleted_at is null
    ) then
      raise exception using
        errcode = '23503',
        message = 'Rateio ativo sem titulo no mesmo tenant.';
    end if;
    return;
  end if;

  select
    count(*),
    coalesce(sum(tr.percentual), 0),
    coalesce(sum(coalesce(
      tr.valor,
      round(coalesce(v_valor_titulo, 0) * coalesce(tr.percentual, 0) / 100.0, 2),
      0
    )), 0),
    count(*)
      - count(distinct row(
          tr.plano_contas_id,
          tr.centro_custo_id,
          tr.os_id
        ))
    into
      v_quantidade,
      v_percentual,
      v_valor,
      v_duplicidades
  from f.titulo_rateio tr
  where tr.tenant_id = p_tenant_id
    and tr.titulo_id = p_titulo_id
    and tr.deleted_at is null;

  if v_quantidade = 0 then
    return;
  end if;

  if v_duplicidades > 0 then
    raise exception using
      errcode = '23505',
      message = 'Rateio: plano, centro de custo e OS repetidos no mesmo titulo.';
  end if;

  if v_percentual > 100.0001 then
    raise exception using
      errcode = '23514',
      message = format(
        'Rateio: soma percentual de %s%% excede 100%%.',
        round(v_percentual, 4)
      );
  end if;

  if v_valor > coalesce(v_valor_titulo, 0) + 0.01 then
    raise exception using
      errcode = '23514',
      message = format(
        'Rateio: soma de %s excede o valor do titulo (%s).',
        round(v_valor, 2),
        round(coalesce(v_valor_titulo, 0), 2)
      );
  end if;
end;
$$;


ALTER FUNCTION "f"."validar_consistencia_rateio_titulo"("p_tenant_id" "uuid", "p_titulo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "f"."validar_total_regra_rateio"("p_tenant_id" "uuid", "p_regra_rateio_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'f', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_quantidade integer;
  v_total numeric;
begin
  if not exists (
    select 1
    from f.regra_rateio rr
    where rr.id = p_regra_rateio_id
      and rr.tenant_id = p_tenant_id
      and rr.deleted_at is null
  ) then
    return;
  end if;

  select count(*)::integer, coalesce(sum(rri.percentual), 0)
    into v_quantidade, v_total
  from f.regra_rateio_item rri
  where rri.tenant_id = p_tenant_id
    and rri.regra_rateio_id = p_regra_rateio_id
    and rri.deleted_at is null;

  if v_quantidade = 0 then
    raise exception using
      errcode = '23514',
      message = 'Regra de rateio: informe ao menos um destino.';
  end if;

  if abs(v_total - 100.0000) > 0.0001 then
    raise exception using
      errcode = '23514',
      message = format(
        'Regra de rateio: os percentuais devem somar 100%% (soma atual: %s%%).',
        round(v_total, 4)
      );
  end if;
end;
$$;


ALTER FUNCTION "f"."validar_total_regra_rateio"("p_tenant_id" "uuid", "p_regra_rateio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_compra_varredura"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_incluir_os" boolean DEFAULT true, "p_incluir_estoque" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if not exists (
    select 1 from c.empresa e
    where e.id = p_empresa_id
      and e.tenant_id = p_tenant_id
      and e.ativo is true
      and e.deleted_at is null
  )
  or p_empresa_id is distinct from public.current_empresa_id__by_tenant(p_tenant_id)
  or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
  or not c.has_compras_access(p_tenant_id, p_empresa_id) then
    raise exception 'not_allowed';
  end if;

  return m.fn_compra_varredura_unscoped_20260810(
    p_tenant_id,
    p_empresa_id,
    p_incluir_os,
    p_incluir_estoque
  );
end;
$$;


ALTER FUNCTION "m"."fn_compra_varredura"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_incluir_os" boolean, "p_incluir_estoque" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_compra_varredura_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_incluir_os" boolean DEFAULT true, "p_incluir_estoque" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    AS $$
declare
  v_os_inseridas int := 0;
  v_os_canceladas int := 0;
  v_estoque_inseridas int := 0;
  v_estoque_atualizadas int := 0;
begin
  if not public.can('compras', 'write', p_tenant_id) then
    raise exception 'Sem permissao para varredura de compras';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('m.fn_compra_varredura'),
    hashtext(coalesce(p_tenant_id::text, '') || ':' || coalesce(p_empresa_id::text, ''))
  );

  if p_incluir_os then
    with fonte_os as (
      select
        oi.os_id,
        oi.item_id,
        sum(greatest(oi.quantidade - coalesce(oi.quantidade_baixada, 0), 0))::numeric(15,3) as quantidade
      from public.os_itens oi
      join public.ordens_servico os
        on os.tenant_id = p_tenant_id
       and os.empresa_id = p_empresa_id
       and os.id = oi.os_id
      where oi.tenant_id = p_tenant_id
        and oi.empresa_id = p_empresa_id
        and oi.quantidade > 0
        and greatest(oi.quantidade - coalesce(oi.quantidade_baixada, 0), 0) > 0
        and os.status in ('aberta', 'em_andamento')
      group by oi.os_id, oi.item_id
    ),
    canceladas as (
      update m.compra_pendencia cp
         set status = 'CANCELADO',
             cancel_reason = 'Cancelado automaticamente: item removido/baixado na OS.',
             updated_by = a.fn_current_usuario_id()
       where cp.tenant_id = p_tenant_id
         and cp.empresa_id = p_empresa_id
         and cp.deleted_at is null
         and cp.origem_tipo = 'OS'
         and cp.status in ('PENDENTE', 'EM_PEDIDO')
         and not exists (
           select 1
           from fonte_os f
           where f.os_id = cp.origem_os_id
             and f.item_id = cp.item_id
         )
      returning cp.id
    )
    select count(*) into v_os_canceladas from canceladas;

    with fonte_os as (
      select
        oi.os_id,
        oi.item_id,
        sum(greatest(oi.quantidade - coalesce(oi.quantidade_baixada, 0), 0))::numeric(15,3) as quantidade
      from public.os_itens oi
      join public.ordens_servico os
        on os.tenant_id = p_tenant_id
       and os.empresa_id = p_empresa_id
       and os.id = oi.os_id
      where oi.tenant_id = p_tenant_id
        and oi.empresa_id = p_empresa_id
        and oi.quantidade > 0
        and greatest(oi.quantidade - coalesce(oi.quantidade_baixada, 0), 0) > 0
        and os.status in ('aberta', 'em_andamento')
      group by oi.os_id, oi.item_id
    ),
    atualizadas as (
      update m.compra_pendencia cp
         set quantidade = f.quantidade,
             updated_by = a.fn_current_usuario_id()
        from fonte_os f
       where cp.tenant_id = p_tenant_id
         and cp.empresa_id = p_empresa_id
         and cp.deleted_at is null
         and cp.origem_tipo = 'OS'
         and cp.status = 'PENDENTE'
         and cp.origem_os_id = f.os_id
         and cp.item_id = f.item_id
      returning cp.id
    ),
    ins as (
      insert into m.compra_pendencia (
        tenant_id,
        empresa_id,
        status,
        fornecedor_id,
        origem_tipo,
        origem_os_id,
        item_id,
        item_nome,
        unidade,
        quantidade,
        prioridade,
        observacoes
      )
      select
        p_tenant_id,
        p_empresa_id,
        'PENDENTE',
        i.fornecedor_id,
        'OS',
        f.os_id,
        f.item_id,
        upper(trim(coalesce(i.nome, i.descricao, 'ITEM'))),
        coalesce(nullif(trim(i.unidade_medida), ''), 'UN'),
        f.quantidade,
        'MEDIA',
        'Varredura automatica (OS com baixa pendente/parcial de estoque)'
      from fonte_os f
      join public.itens i
        on i.tenant_id = p_tenant_id
       and i.empresa_id = p_empresa_id
       and i.id = f.item_id
      left join public.estoque e
        on e.tenant_id = p_tenant_id
       and e.empresa_id = p_empresa_id
       and e.item_id = f.item_id
      left join m.compra_pendencia cp
        on cp.tenant_id = p_tenant_id
       and cp.empresa_id = p_empresa_id
       and cp.deleted_at is null
       and cp.status in ('PENDENTE', 'EM_PEDIDO')
       and cp.origem_tipo = 'OS'
       and cp.origem_os_id = f.os_id
       and cp.item_id = f.item_id
      where cp.id is null
        and coalesce(e.quantidade_atual, 0) < f.quantidade
      returning id
    )
    select count(*) into v_os_inseridas from ins;
  end if;

  if p_incluir_estoque then
    with em_compra as (
      select
        p.tenant_id,
        p.empresa_id,
        i.item_id,
        sum(greatest(i.quantidade - i.quantidade_recebida, 0))::numeric(15,3) as qtd_em_compra
      from m.pedido_compra_item i
      join m.pedido_compra p on p.id = i.pedido_compra_id
      where p.deleted_at is null
        and p.tenant_id = p_tenant_id
        and p.empresa_id = p_empresa_id
        and p.status in ('RASCUNHO','AGUARDANDO_APROVACAO','APROVADO','ENVIADO','PARCIAL_RECEBIDO')
      group by p.tenant_id, p.empresa_id, i.item_id
    ),
    calc as (
      select
        it.id as item_id,
        it.fornecedor_id,
        upper(trim(coalesce(it.nome, it.descricao, 'ITEM'))) as item_nome,
        coalesce(nullif(trim(it.unidade_medida), ''), 'UN') as unidade,
        coalesce(it.estoque_maximo, 0)::numeric(15,3) as alvo_max,
        coalesce(e.quantidade_atual, 0)::numeric(15,3) as estoque_atual,
        coalesce(ec.qtd_em_compra, 0)::numeric(15,3) as em_compra_qtd,
        greatest(
          0::numeric,
          coalesce(it.estoque_maximo, 0)::numeric(15,3) - (coalesce(e.quantidade_atual, 0)::numeric(15,3) + coalesce(ec.qtd_em_compra, 0)::numeric(15,3))
        )::numeric(15,3) as sugestao_max
      from public.itens it
      left join public.estoque e
        on e.tenant_id = p_tenant_id
       and e.empresa_id = p_empresa_id
       and e.item_id = it.id
      left join em_compra ec
        on ec.tenant_id = p_tenant_id
       and ec.empresa_id = p_empresa_id
       and ec.item_id = it.id
      where it.tenant_id = p_tenant_id
        and it.empresa_id = p_empresa_id
        and coalesce(it.controla_estoque, false) = true
        and coalesce(it.estoque_maximo, 0) > 0
    ),
    existentes as (
      select distinct on (cp.item_id)
        cp.id,
        cp.item_id
      from m.compra_pendencia cp
      where cp.tenant_id = p_tenant_id
        and cp.empresa_id = p_empresa_id
        and cp.deleted_at is null
        and cp.origem_tipo = 'ESTOQUE'
        and cp.status in ('PENDENTE', 'EM_PEDIDO')
      order by cp.item_id, cp.created_at desc
    ),
    upd as (
      update m.compra_pendencia cp
         set quantidade = c.sugestao_max,
             estoque_meta = 'MAX',
             fornecedor_id = coalesce(cp.fornecedor_id, c.fornecedor_id),
             updated_by = a.fn_current_usuario_id()
        from calc c, existentes ex
       where ex.id = cp.id
         and ex.item_id = c.item_id
         and c.sugestao_max > 0
      returning cp.id
    ),
    ins as (
      insert into m.compra_pendencia (
        tenant_id,
        empresa_id,
        status,
        fornecedor_id,
        origem_tipo,
        item_id,
        item_nome,
        unidade,
        quantidade,
        prioridade,
        estoque_meta,
        observacoes
      )
      select
        p_tenant_id,
        p_empresa_id,
        'PENDENTE',
        c.fornecedor_id,
        'ESTOQUE',
        c.item_id,
        c.item_nome,
        c.unidade,
        c.sugestao_max,
        'MEDIA',
        'MAX',
        'Varredura automatica (estoque maximo)'
      from calc c
      left join existentes ex on ex.item_id = c.item_id
      where c.sugestao_max > 0
        and ex.id is null
      returning id
    )
    select
      (select count(*) from upd),
      (select count(*) from ins)
      into v_estoque_atualizadas, v_estoque_inseridas;
  end if;

  return jsonb_build_object(
    'os_inseridas', v_os_inseridas,
    'os_canceladas', v_os_canceladas,
    'estoque_inseridas', v_estoque_inseridas,
    'estoque_atualizadas', v_estoque_atualizadas,
    'total_movimentadas', v_os_inseridas + v_os_canceladas + v_estoque_inseridas + v_estoque_atualizadas
  );
end;
$$;


ALTER FUNCTION "m"."fn_compra_varredura_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_incluir_os" boolean, "p_incluir_estoque" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_adicionar_conjunto"("p_orcamento_id" "uuid", "p_conjunto_id" "uuid", "p_quantidade" numeric DEFAULT 1) RETURNS TABLE("conjunto_instancia_id" "uuid", "itens_inseridos" integer, "total_estimado" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'c', 'public', 'a'
    SET "row_security" TO 'off'
    AS $$
declare
  v_orc m.orcamento%rowtype;
  v_conj c.conjunto%rowtype;
  v_inst uuid := gen_random_uuid();
  v_count integer := 0;
  v_total numeric(15,6) := 0;
  r record;
begin
  if p_quantidade is null or p_quantidade <= 0 then
    raise exception 'Quantidade do conjunto deve ser > 0';
  end if;

  select * into v_orc
  from m.orcamento o
  where o.id = p_orcamento_id and o.deleted_at is null;

  if not found then raise exception 'Orcamento nao encontrado'; end if;
  if not c.has_comercial_access(v_orc.tenant_id, v_orc.empresa_id) then
    raise exception 'Sem permissao comercial para este tenant/empresa';
  end if;

  select * into v_conj
  from c.conjunto cj
  where cj.id = p_conjunto_id
    and cj.tenant_id = v_orc.tenant_id
    and cj.empresa_id = v_orc.empresa_id
    and cj.ativo is true and cj.deleted_at is null;

  if not found then raise exception 'Conjunto invalido para este tenant/empresa'; end if;

  for r in
    select ci.item_id, ci.quantidade as qtd_base, ci.ordem,
           public.fn_preco_venda_item_unscoped(v_orc.tenant_id, v_orc.empresa_id, i.id) as preco_sugerido
    from c.conjunto_item ci
    join public.itens i on i.id = ci.item_id
    where ci.conjunto_id = v_conj.id
      and ci.deleted_at is null
      and i.tenant_id = v_orc.tenant_id
      and i.empresa_id = v_orc.empresa_id
      and i.ativo is true
      and i.tipo in ('produto','servico')
    order by ci.ordem, ci.created_at
  loop
    insert into m.orcamento_item (
      orcamento_id, item_id, quantidade, valor_unitario,
      desconto_item_percent, conjunto_id, conjunto_instancia_id,
      conjunto_codigo, conjunto_nome
    ) values (
      v_orc.id, r.item_id, r.qtd_base * p_quantidade,
      coalesce(r.preco_sugerido,0)::numeric(15,4), 0,
      v_conj.id, v_inst, v_conj.codigo, v_conj.nome
    );
    v_count := v_count + 1;
    v_total := v_total + coalesce(r.preco_sugerido,0) * (r.qtd_base * p_quantidade);
  end loop;

  return query select v_inst, v_count, round(v_total,2);
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_adicionar_conjunto"("p_orcamento_id" "uuid", "p_conjunto_id" "uuid", "p_quantidade" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_atualizar_status"("p_orcamento_id" "uuid", "p_status" "text", "p_followup" "text" DEFAULT NULL::"text", "p_valor_fechado" numeric DEFAULT NULL::numeric, "p_abrir_os" boolean DEFAULT false, "p_importar_itens_os" boolean DEFAULT false, "p_tipo_documento" "text" DEFAULT NULL::"text") RETURNS TABLE("orcamento_id" "uuid", "os_id" integer, "numero_os" "text", "valor_orcado" numeric, "valor_fechado" numeric, "desconto_valor" numeric, "itens_importados" boolean)
    LANGUAGE "plpgsql"
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_orc m.orcamento%rowtype;
  v_cliente_nome text;
  v_vendedor_nome text;
  v_status text;
  v_followup text;
  v_tipo_pedido text := 'servico';
  v_tipo_documento text;
  v_tipo_documento_existente text;
  v_os_num bigint;
  v_os_id integer;
  v_numero_os text;
  v_valor_orcado numeric(15,2);
  v_valor_fechado_final numeric(15,2);
  v_desconto_valor_final numeric(15,2);
  v_itens_importados boolean := false;
  v_criado_por text;
  v_item record;
begin
  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null or v_empresa_id is null then
    raise exception 'Contexto tenant/empresa nao encontrado para atualizar status do orcamento.';
  end if;

  v_status := upper(trim(coalesce(p_status, '')));
  if v_status not in ('ANDAMENTO', 'FECHADO', 'PERDIDO') then
    raise exception 'Status de orcamento invalido: %', coalesce(p_status, '<null>');
  end if;

  v_followup := nullif(trim(coalesce(p_followup, '')), '');

  if coalesce(p_importar_itens_os, false) and not coalesce(p_abrir_os, false) then
    raise exception 'Selecione gerar o documento antes de importar os itens.';
  end if;

  if p_tipo_documento is not null
     and (v_status <> 'FECHADO' or not coalesce(p_abrir_os, false)) then
    raise exception 'O tipo de documento so pode ser escolhido ao fechar e gerar o documento.';
  end if;

  if p_tipo_documento is not null
     and upper(btrim(p_tipo_documento)) not in ('OS', 'OV') then
    raise exception 'Tipo de documento invalido: %', p_tipo_documento;
  end if;

  select orcamento.*
    into v_orc
  from m.orcamento as orcamento
  where orcamento.id = p_orcamento_id
    and orcamento.tenant_id = v_tenant_id
    and orcamento.empresa_id = v_empresa_id
    and orcamento.deleted_at is null;

  if not found then
    raise exception 'Orcamento nao encontrado para o tenant/empresa atual.';
  end if;

  select
    coalesce(nullif(trim(cliente.nome), ''), 'Cliente #' || v_orc.cliente_id::text),
    nullif(trim(usuario.nome), '')
  into v_cliente_nome, v_vendedor_nome
  from m.orcamento as orcamento
  left join public.clientes as cliente
    on cliente.tenant_id = orcamento.tenant_id
   and cliente.empresa_id = orcamento.empresa_id
   and cliente.id = orcamento.cliente_id
  left join a.usuario as usuario
    on usuario.id = orcamento.vendedor_usuario_id
  where orcamento.id = p_orcamento_id
    and orcamento.tenant_id = v_tenant_id
    and orcamento.empresa_id = v_empresa_id
    and orcamento.deleted_at is null;

  v_valor_orcado := round(coalesce(v_orc.total_liquido, 0)::numeric, 2);

  if v_status = 'FECHADO' then
    v_valor_fechado_final := round(coalesce(p_valor_fechado, v_orc.valor_fechado, v_valor_orcado)::numeric, 2);
    if v_valor_fechado_final < 0 then
      raise exception 'Valor fechado nao pode ser negativo.';
    end if;
  else
    v_valor_fechado_final := round(coalesce(v_orc.valor_fechado, 0)::numeric, 2);
  end if;

  v_desconto_valor_final := round((v_valor_orcado - v_valor_fechado_final)::numeric, 2);
  v_os_id := v_orc.os_id;

  if exists (
    select 1
    from m.orcamento_item as item_orcamento
    where item_orcamento.tenant_id = v_orc.tenant_id
      and item_orcamento.empresa_id = v_orc.empresa_id
      and item_orcamento.orcamento_id = v_orc.id
      and item_orcamento.deleted_at is null
      and item_orcamento.item_tipo = 'SERVICO'
  ) then
    v_tipo_pedido := 'servico';
  else
    v_tipo_pedido := 'material';
  end if;

  v_tipo_documento := coalesce(
    nullif(upper(btrim(coalesce(p_tipo_documento, ''))), ''),
    case when v_tipo_pedido = 'servico' then 'OS' else 'OV' end
  );

  if v_os_id is not null then
    select documento.numero_os, documento.tipo_documento
      into v_numero_os, v_tipo_documento_existente
    from public.ordens_servico as documento
    where documento.tenant_id = v_orc.tenant_id
      and documento.empresa_id = v_orc.empresa_id
      and documento.id = v_os_id;

    if not found then
      v_os_id := null;
      v_numero_os := null;
      v_tipo_documento_existente := null;
    elsif p_tipo_documento is not null
          and v_tipo_documento_existente <> v_tipo_documento then
      raise exception 'O orcamento ja esta vinculado a um documento do tipo %.', v_tipo_documento_existente;
    else
      v_tipo_documento := v_tipo_documento_existente;
    end if;
  end if;

  if coalesce(p_abrir_os, false) then
    if v_status <> 'FECHADO' then
      raise exception 'Gerar documento so e permitido ao fechar o orcamento.';
    end if;

    if v_os_id is null then
      v_os_num := nextval('public.ordens_servico_os_num_seq');
      v_numero_os := v_os_num::text;
      v_criado_por := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);

      insert into public.ordens_servico as documento (
        tenant_id,
        empresa_id,
        numero_os,
        os_num,
        cliente_id,
        cliente_nome,
        descricao_servico,
        status,
        status_fluxo,
        tipo_pedido,
        tipo_documento,
        vendedor,
        orcado,
        observacoes,
        criado_por,
        tem_gestao,
        usa_relatorio_hh
      ) values (
        v_orc.tenant_id,
        v_orc.empresa_id,
        v_numero_os,
        v_os_num,
        v_orc.cliente_id,
        left(v_cliente_nome, 255),
        nullif(upper(trim(coalesce(v_orc.titulo, ''))), ''),
        'em_andamento',
        'em_andamento',
        v_tipo_pedido,
        v_tipo_documento,
        v_vendedor_nome,
        v_valor_fechado_final,
        case
          when v_followup is null then 'Origem orcamento ' || coalesce(v_orc.codigo, v_orc.id::text)
          else 'Origem orcamento ' || coalesce(v_orc.codigo, v_orc.id::text) || ' | ' || v_followup
        end,
        v_criado_por,
        false,
        false
      )
      returning documento.id, documento.numero_os
      into v_os_id, v_numero_os;
    end if;

    update public.ordens_servico as documento
       set cliente_id = v_orc.cliente_id,
           cliente_nome = left(v_cliente_nome, 255),
           descricao_servico = coalesce(nullif(upper(trim(coalesce(v_orc.titulo, ''))), ''), documento.descricao_servico),
           vendedor = coalesce(v_vendedor_nome, documento.vendedor),
           orcado = v_valor_fechado_final,
           tem_gestao = case when documento.tipo_documento = 'OV' then false else documento.tem_gestao end,
           usa_relatorio_hh = case when documento.tipo_documento = 'OV' then false else documento.usa_relatorio_hh end,
           atualizado_em = now()
     where documento.tenant_id = v_orc.tenant_id
       and documento.empresa_id = v_orc.empresa_id
       and documento.id = v_os_id;

    if coalesce(p_importar_itens_os, false) and v_orc.os_itens_importados_at is null then
      v_criado_por := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);

      for v_item in
        select
          item_orcamento.item_id,
          item_orcamento.quantidade,
          item_orcamento.valor_unitario_liquido,
          item_orcamento.valor_total,
          round(
            (coalesce(item.preco_unitario, 0) * (1 + coalesce(item.aliquota_ipi, 0) / 100))::numeric,
            2
          ) as valor_compra_com_impostos
        from m.orcamento_item as item_orcamento
        left join public.itens as item
          on item.tenant_id = item_orcamento.tenant_id
         and item.empresa_id = item_orcamento.empresa_id
         and item.id = item_orcamento.item_id
        where item_orcamento.tenant_id = v_orc.tenant_id
          and item_orcamento.empresa_id = v_orc.empresa_id
          and item_orcamento.orcamento_id = v_orc.id
          and item_orcamento.deleted_at is null
        order by item_orcamento.seq
      loop
        perform public.add_os_item_baixa_imediata(
          p_os_id => v_os_id,
          p_item_id => v_item.item_id,
          p_quantidade => v_item.quantidade,
          p_valor_unitario => case
            when coalesce(v_item.valor_compra_com_impostos, 0) > 0 then v_item.valor_compra_com_impostos
            when coalesce(v_item.valor_unitario_liquido, 0) > 0 then v_item.valor_unitario_liquido
            when coalesce(v_item.quantidade, 0) > 0 and coalesce(v_item.valor_total, 0) > 0
              then round((v_item.valor_total / nullif(v_item.quantidade, 0))::numeric, 4)
            else 0
          end,
          p_desconto_percentual => 0,
          p_desconto_valor => 0,
          p_baixa_estoque => false,
          p_realizado_por => v_criado_por,
          p_motivo => 'Importado do orcamento ' || coalesce(v_orc.codigo, v_orc.id::text),
          p_empresa_id => v_orc.empresa_id
        );
      end loop;

      v_itens_importados := true;
    end if;
  end if;

  update m.orcamento as orcamento
     set status = v_status,
         observacoes = v_followup,
         valor_fechado = case
           when v_status = 'FECHADO' then v_valor_fechado_final
           else orcamento.valor_fechado
         end,
         os_id = coalesce(v_os_id, orcamento.os_id),
         os_itens_importados_at = case
           when v_itens_importados and orcamento.os_itens_importados_at is null then now()
           else orcamento.os_itens_importados_at
         end,
         updated_at = now()
   where orcamento.id = v_orc.id
     and orcamento.tenant_id = v_orc.tenant_id
     and orcamento.empresa_id = v_orc.empresa_id;

  orcamento_id := v_orc.id;
  os_id := v_os_id;
  numero_os := v_numero_os;
  valor_orcado := v_valor_orcado;
  valor_fechado := v_valor_fechado_final;
  desconto_valor := v_desconto_valor_final;
  itens_importados := v_itens_importados;
  return next;
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_atualizar_status"("p_orcamento_id" "uuid", "p_status" "text", "p_followup" "text", "p_valor_fechado" numeric, "p_abrir_os" boolean, "p_importar_itens_os" boolean, "p_tipo_documento" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_atualizar_status_com_responsavel"("p_orcamento_id" "uuid", "p_status" "text", "p_followup" "text" DEFAULT NULL::"text", "p_valor_fechado" numeric DEFAULT NULL::numeric, "p_abrir_os" boolean DEFAULT false, "p_importar_itens_os" boolean DEFAULT false, "p_responsavel_aprovacao_id" "uuid" DEFAULT NULL::"uuid", "p_tipo_documento" "text" DEFAULT NULL::"text") RETURNS TABLE("orcamento_id" "uuid", "os_id" integer, "numero_os" "text", "valor_orcado" numeric, "valor_fechado" numeric, "desconto_valor" numeric, "itens_importados" boolean)
    LANGUAGE "plpgsql"
    AS $$
declare
  v_result record;
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
begin
  if v_tenant_id is null or v_empresa_id is null then
    raise exception 'Contexto tenant/empresa nao encontrado para atualizar status do orcamento.';
  end if;

  select *
    into v_result
  from m.fn_orcamento_atualizar_status(
    p_orcamento_id,
    p_status,
    p_followup,
    p_valor_fechado,
    p_abrir_os,
    p_importar_itens_os,
    p_tipo_documento
  );

  if coalesce(p_abrir_os, false)
     and p_responsavel_aprovacao_id is not null
     and v_result.os_id is not null then
    update public.ordens_servico as documento
       set responsavel_aprovacao_id = case
             when documento.tipo_documento = 'OS' then p_responsavel_aprovacao_id
             else null
           end,
           atualizado_em = now()
     where documento.id = v_result.os_id
       and documento.tenant_id = v_tenant_id
       and documento.empresa_id = v_empresa_id;
  end if;

  orcamento_id := v_result.orcamento_id;
  os_id := v_result.os_id;
  numero_os := v_result.numero_os;
  valor_orcado := v_result.valor_orcado;
  valor_fechado := v_result.valor_fechado;
  desconto_valor := v_result.desconto_valor;
  itens_importados := v_result.itens_importados;
  return next;
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_atualizar_status_com_responsavel"("p_orcamento_id" "uuid", "p_status" "text", "p_followup" "text", "p_valor_fechado" numeric, "p_abrir_os" boolean, "p_importar_itens_os" boolean, "p_responsavel_aprovacao_id" "uuid", "p_tipo_documento" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_item_calcular"("p_quantidade" numeric, "p_valor_unitario" numeric, "p_desconto_item_percent" numeric, "p_acrescimo_cond_percent" numeric, "p_desconto_global_percent" numeric) RETURNS TABLE("valor_total_bruto" numeric, "valor_total" numeric, "valor_unitario_liquido" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'm', 'public', 'a', 'c', 'f', 'r', 'auth', 'extensions'
    AS $$
declare
  v_q numeric := coalesce(p_quantidade,0);
  v_vu numeric := coalesce(p_valor_unitario,0);
  v_di numeric := coalesce(p_desconto_item_percent,0);
  v_ac numeric := coalesce(p_acrescimo_cond_percent,0);
  v_dg numeric := coalesce(p_desconto_global_percent,0);

  v_bruto numeric;
  v_total numeric;
  v_unit_liq numeric;
begin
  -- base * (1-desc_item) * (1+acresc)
  v_bruto := (v_q * v_vu);
  v_bruto := v_bruto * (1 - (v_di/100));
  v_bruto := v_bruto * (1 + (v_ac/100));
  v_bruto := round(v_bruto, 2);

  -- aplica desconto global
  v_total := v_bruto * (1 - (v_dg/100));
  v_total := round(v_total, 2);

  v_unit_liq := case when v_q > 0 then round((v_total / v_q), 4) else 0 end;

  return query select v_bruto, v_total, v_unit_liq;
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_item_calcular"("p_quantidade" numeric, "p_valor_unitario" numeric, "p_desconto_item_percent" numeric, "p_acrescimo_cond_percent" numeric, "p_desconto_global_percent" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_lista_current"() RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "empresa_id" "uuid", "codigo" "text", "numero" integer, "versao" integer, "status" "text", "emissao_date" "date", "titulo" "text", "cliente_id" integer, "cliente_nome" character varying, "vendedor_usuario_id" "uuid", "vendedor_nome" "text", "condicao_pagamento_id" "uuid", "condicao_pagamento_nome" "text", "desconto_global_percent" numeric, "acrescimo_cond_pag_percent" numeric, "valor_frete" numeric, "total_produtos" numeric, "total_servicos" numeric, "total_bruto" numeric, "total_desconto_global" numeric, "total_liquido" numeric, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "valor_fechado" numeric, "desconto_fechamento_valor" numeric, "desconto_fechamento_percent" numeric, "observacoes" "text", "os_id" integer, "os_itens_importados_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid;
begin
  if auth.uid() is null or v_tenant_id is null then
    return;
  end if;

  v_empresa_id := public.current_empresa_id__by_tenant(v_tenant_id);

  if v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id)
     or not c.has_comercial_access(v_tenant_id, v_empresa_id) then
    return;
  end if;

  return query
  select
    o.id,
    o.tenant_id,
    o.empresa_id,
    o.codigo,
    o.numero,
    o.versao,
    o.status,
    o.emissao_date,
    o.titulo,
    o.cliente_id,
    cli.nome,
    o.vendedor_usuario_id,
    vendedor.nome,
    o.condicao_pagamento_id,
    cp.nome,
    o.desconto_global_percent,
    o.acrescimo_cond_pag_percent,
    o.valor_frete,
    o.total_produtos,
    o.total_servicos,
    o.total_bruto,
    o.total_desconto_global,
    o.total_liquido,
    o.created_at,
    o.updated_at,
    o.valor_fechado,
    case
      when o.valor_fechado is null then null::numeric(15,2)
      else round((o.total_liquido - o.valor_fechado)::numeric, 2)::numeric(15,2)
    end,
    case
      when o.valor_fechado is null or o.total_liquido = 0 then null::numeric(7,2)
      else round((((o.total_liquido - o.valor_fechado) / o.total_liquido) * 100)::numeric, 2)::numeric(7,2)
    end,
    o.observacoes,
    o.os_id,
    o.os_itens_importados_at
  from m.orcamento o
  join public.clientes cli
    on cli.id = o.cliente_id
   and cli.tenant_id = o.tenant_id
   and cli.empresa_id = o.empresa_id
  left join a.usuario vendedor
    on vendedor.id = o.vendedor_usuario_id
   and vendedor.ativo is true
   and vendedor.deleted_at is null
   and exists (
     select 1
     from a.usuario_tenant ut
     join a.usuario_empresa ue on ue.usuario_id = ut.usuario_id
     where ut.usuario_id = vendedor.id
       and ut.tenant_id = o.tenant_id
       and ut.ativo is true
       and ut.deleted_at is null
       and ue.empresa_id = o.empresa_id
       and ue.ativo is true
       and ue.deleted_at is null
   )
  left join c.condicao_pagamento cp
    on cp.id = o.condicao_pagamento_id
   and cp.tenant_id = o.tenant_id
   and cp.empresa_id = o.empresa_id
   and cp.deleted_at is null
  where o.tenant_id = v_tenant_id
    and o.empresa_id = v_empresa_id
    and o.deleted_at is null;
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_lista_current"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_listar"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_emissao_de" "date" DEFAULT NULL::"date", "p_emissao_ate" "date" DEFAULT NULL::"date", "p_busca" "text" DEFAULT NULL::"text", "p_offset" integer DEFAULT 0, "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_busca text := nullif(btrim(coalesce(p_busca, '')), '');
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Nao autenticado' using errcode = '42501';
  end if;

  if p_tenant_id is null or p_empresa_id is null then
    raise exception 'Tenant e empresa sao obrigatorios' using errcode = '22023';
  end if;

  if public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not c.has_comercial_access(p_tenant_id, p_empresa_id) then
    raise exception 'Sem acesso aos orcamentos desta empresa' using errcode = '42501';
  end if;

  with filtered as materialized (
    select
      o.id,
      o.codigo,
      o.numero,
      o.versao,
      o.status,
      o.emissao_date,
      o.titulo,
      o.cliente_id,
      cli.nome as cliente_nome,
      o.vendedor_usuario_id,
      vendedor.nome as vendedor_nome,
      o.condicao_pagamento_id,
      cp.nome as condicao_pagamento_nome,
      o.desconto_global_percent,
      o.acrescimo_cond_pag_percent,
      o.valor_frete,
      o.total_produtos,
      o.total_servicos,
      o.total_bruto,
      o.total_desconto_global,
      o.total_liquido,
      o.valor_fechado,
      case
        when o.valor_fechado is null then null::numeric(15,2)
        else round((o.total_liquido - o.valor_fechado)::numeric, 2)
      end as desconto_fechamento_valor,
      case
        when o.valor_fechado is null or o.total_liquido = 0 then null::numeric(7,2)
        else round((((o.total_liquido - o.valor_fechado) / o.total_liquido) * 100)::numeric, 2)
      end as desconto_fechamento_percent,
      o.observacoes,
      o.os_id,
      o.os_itens_importados_at,
      o.created_at,
      o.updated_at
    from m.orcamento o
    join public.clientes cli
      on cli.id = o.cliente_id
     and cli.tenant_id = o.tenant_id
     and cli.empresa_id = o.empresa_id
    left join a.usuario vendedor
      on vendedor.id = o.vendedor_usuario_id
     and vendedor.ativo is true
     and vendedor.deleted_at is null
     and exists (
       select 1
       from a.usuario_tenant ut
       join a.usuario_empresa ue on ue.usuario_id = ut.usuario_id
       where ut.usuario_id = vendedor.id
         and ut.tenant_id = o.tenant_id
         and ut.ativo is true
         and ut.deleted_at is null
         and ue.empresa_id = o.empresa_id
         and ue.ativo is true
         and ue.deleted_at is null
     )
    left join c.condicao_pagamento cp
      on cp.id = o.condicao_pagamento_id
     and cp.tenant_id = o.tenant_id
     and cp.empresa_id = o.empresa_id
     and cp.deleted_at is null
    where o.tenant_id = p_tenant_id
      and o.empresa_id = p_empresa_id
      and o.deleted_at is null
      and (
        p_statuses is null
        or cardinality(p_statuses) = 0
        or o.status = any (p_statuses)
      )
      and (p_emissao_de is null or o.emissao_date >= p_emissao_de)
      and (p_emissao_ate is null or o.emissao_date <= p_emissao_ate)
      and (
        v_busca is null
        or o.codigo ilike ('%' || v_busca || '%')
        or o.titulo ilike ('%' || v_busca || '%')
        or cli.nome ilike ('%' || v_busca || '%')
      )
  ),
  page_rows as (
    select *
    from filtered
    order by emissao_date desc, numero desc
    offset v_offset
    limit v_limit
  )
  select jsonb_build_object(
    'rows', coalesce(
      jsonb_agg(to_jsonb(page_rows) order by emissao_date desc, numero desc),
      '[]'::jsonb
    ),
    'count', (select count(*) from filtered)
  )
  into v_result
  from page_rows;

  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'count', 0));
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_listar"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_statuses" "text"[], "p_emissao_de" "date", "p_emissao_ate" "date", "p_busca" "text", "p_offset" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_normalize_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'm', 'public', 'a', 'c', 'f', 'r', 'auth', 'extensions'
    AS $$
begin
  new.status := upper(trim(coalesce(new.status, '')));

  if new.status = '' then
    new.status := 'ANDAMENTO';
  elsif new.status = 'RASCUNHO' then
    new.status := 'ANDAMENTO';
  elsif new.status = 'FINALIZADO' then
    new.status := 'FECHADO';
  elsif new.status = 'CANCELADO' then
    new.status := 'PERDIDO';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_normalize_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_preco_sugerido_item"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_custo_ultima_compra" numeric, "p_preco_unitario" numeric) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_margem numeric := 53;
begin
  if p_empresa_id is distinct from public.current_empresa_id__by_tenant(p_tenant_id)
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not c.has_comercial_access(p_tenant_id, p_empresa_id) then
    raise exception 'not_allowed';
  end if;

  select coalesce(c.margem_lucro_padrao_percent, 53)
    into v_margem
  from a.config_orcamento c
  where c.tenant_id = p_tenant_id
    and c.empresa_id = p_empresa_id
    and c.deleted_at is null
  order by c.updated_at desc nulls last, c.created_at desc
  limit 1;

  return public.fn_preco_venda_item_valores(
    p_custo_ultima_compra, p_preco_unitario, 0, coalesce(v_margem, 53)
  );
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_preco_sugerido_item"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_custo_ultima_compra" numeric, "p_preco_unitario" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_preco_sugerido_item_por_id"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_id" integer) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null
     or p_empresa_id is distinct from public.current_empresa_id__by_tenant(p_tenant_id)
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not c.has_comercial_access(p_tenant_id, p_empresa_id) then
    raise exception 'orcamento_preco_access_denied';
  end if;

  return public.fn_preco_venda_item_unscoped(p_tenant_id, p_empresa_id, p_item_id);
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_preco_sugerido_item_por_id"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_preco_sugerido_item_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_custo_ultima_compra" numeric, "p_preco_unitario" numeric) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'm', 'a', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_margem numeric := 53;
  v_base numeric := 0;
begin
  select coalesce(c.margem_lucro_padrao_percent, 53)
    into v_margem
  from a.config_orcamento c
  where c.tenant_id = p_tenant_id
    and c.empresa_id = p_empresa_id
    and c.deleted_at is null
  order by c.updated_at desc nulls last, c.created_at desc
  limit 1;

  v_margem := greatest(coalesce(v_margem, 53), 0);
  v_base := case
    when coalesce(p_custo_ultima_compra, 0) > 0 then coalesce(p_custo_ultima_compra, 0)
    else greatest(coalesce(p_preco_unitario, 0), 0)
  end;

  if v_base <= 0 then
    return 0;
  end if;

  return round(v_base * (1 + (v_margem / 100.0)), 2);
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_preco_sugerido_item_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_custo_ultima_compra" numeric, "p_preco_unitario" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_recalcular_totais"("p_orcamento_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_total_bruto numeric(15,2);
  v_total_liq numeric(15,2);
  v_total_desc numeric(15,2);
  v_prod numeric(15,2);
  v_serv numeric(15,2);
  v_frete numeric(15,2);
begin
  select coalesce(o.valor_frete,0)
    into v_frete
  from m.orcamento o
  where o.id = p_orcamento_id;

  select
    coalesce(sum(oi.valor_total_bruto),0)::numeric(15,2),
    coalesce(sum(oi.valor_total),0)::numeric(15,2),
    coalesce(sum(case when oi.item_tipo='PRODUTO' then oi.valor_total else 0 end),0)::numeric(15,2),
    coalesce(sum(case when oi.item_tipo='SERVICO' then oi.valor_total else 0 end),0)::numeric(15,2)
  into v_total_bruto, v_total_liq, v_prod, v_serv
  from m.orcamento_item oi
  where oi.orcamento_id = p_orcamento_id
    and oi.deleted_at is null;

  v_total_desc := (v_total_bruto - v_total_liq);

  update m.orcamento o
     set total_produtos = v_prod,
         total_servicos = v_serv,
         total_bruto = v_total_bruto,
         total_desconto_global = v_total_desc,
         total_liquido = round((v_total_liq + v_frete),2)
   where o.id = p_orcamento_id;
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_recalcular_totais"("p_orcamento_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_orcamento_sync_itens"("p_orcamento_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_desc_global numeric(7,4);
  v_acresc numeric(7,4);
begin
  select o.desconto_global_percent, o.acrescimo_cond_pag_percent
    into v_desc_global, v_acresc
  from m.orcamento o
  where o.id = p_orcamento_id;

  update m.orcamento_item oi
     set acrescimo_cond_pag_percent = v_acresc,
         desconto_global_percent = v_desc_global,
         valor_total_bruto = calc.valor_total_bruto,
         valor_total = calc.valor_total,
         valor_unitario_liquido = calc.valor_unitario_liquido
    from m.orcamento_item oi2
    join lateral (
      select * from m.fn_orcamento_item_calcular(
        oi2.quantidade,
        oi2.valor_unitario,
        oi2.desconto_item_percent,
        v_acresc,
        v_desc_global
      )
    ) calc on true
   where oi.id = oi2.id
     and oi2.orcamento_id = p_orcamento_id
     and oi2.deleted_at is null;

  perform m.fn_orcamento_recalcular_totais(p_orcamento_id);
end;
$$;


ALTER FUNCTION "m"."fn_orcamento_sync_itens"("p_orcamento_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_pedido_compra_definir_destacar_ipi"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_pedido_id" "uuid", "p_destacar" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
begin
  select p.tenant_id, p.empresa_id
    into v_tenant_id, v_empresa_id
  from m.pedido_compra p
  where p.id = p_pedido_id
    and p.deleted_at is null;
  if not found then
    raise exception 'pedido_compra_not_found';
  end if;

  if p_tenant_id is distinct from v_tenant_id
     or p_empresa_id is distinct from v_empresa_id
     or v_empresa_id is distinct from public.current_empresa_id__by_tenant(v_tenant_id)
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id)
     or not public.can('compras', 'write', v_tenant_id) then
    raise exception 'not_allowed';
  end if;

  return m.fn_pedido_compra_definir_destacar_ipi_unscoped_20260810(
    p_tenant_id, p_empresa_id, p_pedido_id, p_destacar
  );
end;
$$;


ALTER FUNCTION "m"."fn_pedido_compra_definir_destacar_ipi"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_pedido_id" "uuid", "p_destacar" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "m"."fn_pedido_compra_definir_destacar_ipi"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_pedido_id" "uuid", "p_destacar" boolean) IS 'Ativa/desativa o destaque de IPI, inicializa valores pelo cadastro fiscal e recalcula o pedido no escopo tenant/empresa.';



CREATE OR REPLACE FUNCTION "m"."fn_pedido_compra_definir_destacar_ipi_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_pedido_id" "uuid", "p_destacar" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_pedido m.pedido_compra%rowtype;
  v_itens integer;
begin
  if p_tenant_id is null
     or p_empresa_id is null
     or p_pedido_id is null
  then
    raise exception 'Tenant, empresa e pedido sao obrigatorios.';
  end if;

  if not public.can('compras', 'write', p_tenant_id) then
    raise exception 'Sem permissao para alterar pedido.';
  end if;

  select pedido.*
    into v_pedido
  from m.pedido_compra pedido
  where pedido.id = p_pedido_id
    and pedido.tenant_id = p_tenant_id
    and pedido.empresa_id = p_empresa_id
    and pedido.deleted_at is null
  for update;

  if not found then
    raise exception 'Pedido nao encontrado.';
  end if;

  update m.pedido_compra pedido
  set
    destacar_ipi = coalesce(p_destacar, false),
    updated_by = a.fn_current_usuario_id()
  where pedido.id = p_pedido_id
    and pedido.tenant_id = p_tenant_id
    and pedido.empresa_id = p_empresa_id;

  update m.pedido_compra_item item
  set
    aliquota_ipi = case
      when coalesce(p_destacar, false)
        and item.item_id is not null
        and item.valor_ipi_unitario is null
      then coalesce((
        select greatest(coalesce(fiscal.aliq_ipi, 0), 0)
        from public.fiscal_itens fiscal
        where fiscal.tenant_id = item.tenant_id
          and fiscal.empresa_id = item.empresa_id
          and fiscal.item_id = item.item_id
        limit 1
      ), 0)
      else item.aliquota_ipi
    end,
    valor_ipi_unitario = case
      when coalesce(p_destacar, false)
        and item.item_id is not null
        and item.valor_ipi_unitario is null
      then round(
        coalesce(item.valor_unitario, 0)
        * coalesce((
          select greatest(coalesce(fiscal.aliq_ipi, 0), 0)
          from public.fiscal_itens fiscal
          where fiscal.tenant_id = item.tenant_id
            and fiscal.empresa_id = item.empresa_id
            and fiscal.item_id = item.item_id
          limit 1
        ), 0)
        / 100,
        4
      )
      else item.valor_ipi_unitario
    end,
    updated_at = now(),
    updated_by = a.fn_current_usuario_id()
  where item.pedido_compra_id = p_pedido_id
    and item.tenant_id = p_tenant_id
    and item.empresa_id = p_empresa_id
    and item.deleted_at is null;

  get diagnostics v_itens = row_count;
  perform m.fn_pedido_compra_recalcular_totais(p_pedido_id);

  return jsonb_build_object(
    'pedidoId', p_pedido_id,
    'destacarIpi', coalesce(p_destacar, false),
    'itensRecalculados', v_itens
  );
end;
$$;


ALTER FUNCTION "m"."fn_pedido_compra_definir_destacar_ipi_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_pedido_id" "uuid", "p_destacar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_pedido_compra_gerar"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_fornecedor_id" integer, "p_pendencia_ids" "uuid"[], "p_observacoes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    AS $$
declare v_pedido_id uuid;
begin
  if not public.can('compras','write', p_tenant_id) then
    raise exception 'Sem permissao para gerar pedido';
  end if;
  insert into m.pedido_compra(tenant_id, empresa_id, fornecedor_id, observacoes, status, emissao_date)
  values (p_tenant_id, p_empresa_id, p_fornecedor_id, p_observacoes, 'RASCUNHO', current_date)
  returning id into v_pedido_id;

  with src as (
    select cp.*
    from m.compra_pendencia cp
    where cp.tenant_id = p_tenant_id
      and cp.empresa_id = p_empresa_id
      and cp.deleted_at is null
      and cp.status = 'PENDENTE'
      and cp.id = any(p_pendencia_ids)
  ), grp as (
    select item_id, upper(trim(coalesce(item_nome,'ITEM'))) as item_nome, coalesce(nullif(trim(unidade),''), 'UN') as unidade, sum(quantidade)::numeric(15,3) as quantidade
    from src
    group by item_id, upper(trim(coalesce(item_nome,'ITEM'))), coalesce(nullif(trim(unidade),''), 'UN')
  ), ins as (
    insert into m.pedido_compra_item(tenant_id, empresa_id, pedido_compra_id, item_id, item_nome, unidade, quantidade, valor_unitario)
    select p_tenant_id, p_empresa_id, v_pedido_id, g.item_id, g.item_nome, g.unidade, g.quantidade, 0
    from grp g
    returning id, item_id, item_nome, unidade
  )
  insert into m.pedido_compra_item_origem(tenant_id, empresa_id, pedido_compra_item_id, pendencia_id, quantidade)
  select p_tenant_id, p_empresa_id, i.id, cp.id, cp.quantidade
  from m.compra_pendencia cp
  join ins i on coalesce(i.item_id, -1) = coalesce(cp.item_id, -1)
            and upper(trim(i.item_nome)) = upper(trim(coalesce(cp.item_nome, i.item_nome)))
            and upper(trim(i.unidade)) = upper(trim(coalesce(cp.unidade, i.unidade)))
  where cp.id = any(p_pendencia_ids);

  update m.compra_pendencia cp
     set status = 'EM_PEDIDO', updated_by = a.fn_current_usuario_id()
   where cp.id = any(p_pendencia_ids)
     and cp.status = 'PENDENTE'
     and cp.deleted_at is null;

  perform m.fn_pedido_compra_log_evento(v_pedido_id, 'STATUS', null, 'RASCUNHO', 'Pedido gerado por pendencias');
  return v_pedido_id;
end;
$$;


ALTER FUNCTION "m"."fn_pedido_compra_gerar"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_fornecedor_id" integer, "p_pendencia_ids" "uuid"[], "p_observacoes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_pedido_compra_log_evento"("p_pedido_id" "uuid", "p_tipo" "text", "p_status_de" "text", "p_status_para" "text", "p_mensagem" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    AS $$
declare v_tenant uuid; v_empresa uuid;
begin
  select p.tenant_id, p.empresa_id into v_tenant, v_empresa from m.pedido_compra p where p.id = p_pedido_id;
  if v_tenant is null then return; end if;
  insert into m.pedido_compra_evento(tenant_id, empresa_id, pedido_compra_id, tipo, status_de, status_para, mensagem)
  values (v_tenant, v_empresa, p_pedido_id, p_tipo, p_status_de, p_status_para, p_mensagem);
end;
$$;


ALTER FUNCTION "m"."fn_pedido_compra_log_evento"("p_pedido_id" "uuid", "p_tipo" "text", "p_status_de" "text", "p_status_para" "text", "p_mensagem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."fn_pedido_compra_recalcular_totais"("p_pedido_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    AS $$
declare
  v_total numeric(15,2);
  v_total_ipi numeric(15,2);
begin
  select
    coalesce(sum(item.valor_total), 0),
    coalesce(sum(item.valor_ipi_total), 0)
    into v_total, v_total_ipi
  from m.pedido_compra_item item
  where item.pedido_compra_id = p_pedido_id
    and item.deleted_at is null;

  update m.pedido_compra pedido
  set
    total_itens = v_total,
    total_ipi = v_total_ipi,
    total_geral = round(
      v_total
      + coalesce(pedido.total_frete, 0)
      - coalesce(pedido.total_desconto, 0),
      2
    )
  where pedido.id = p_pedido_id;
end;
$$;


