CREATE OR REPLACE FUNCTION "m"."trg_orcamento_biu"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public', 'c', 'a'
    SET "row_security" TO 'off'
    AS $$
declare
  v_cfg a.config_orcamento%rowtype;
  v_acresc numeric(7,4);
begin
  perform a.ensure_config_orcamento(new.tenant_id, new.empresa_id);

  select * into v_cfg
  from a.config_orcamento
  where tenant_id = new.tenant_id
    and empresa_id = new.empresa_id
    and deleted_at is null
  limit 1;

  if new.desconto_global_percent > v_cfg.desconto_max_percent then
    raise exception 'Desconto global (%) excede o máximo configurado (%)',
      round(new.desconto_global_percent,2), round(v_cfg.desconto_max_percent,2);
  end if;

  new.titulo := upper(trim(new.titulo));

  if not exists (
    select 1 from public.clientes c1
    where c1.id = new.cliente_id
      and c1.tenant_id = new.tenant_id
      and c1.empresa_id = new.empresa_id
  ) then
    raise exception 'Cliente inválido para este tenant/empresa (cliente_id=%)', new.cliente_id;
  end if;

  if not exists (
    select 1 from a.usuario u
    where u.id = new.vendedor_usuario_id
      and u.deleted_at is null
      and u.ativo = true
  ) then
    raise exception 'Vendedor inválido (vendedor_usuario_id=%)', new.vendedor_usuario_id;
  end if;

  v_acresc := 0;
  if new.condicao_pagamento_id is not null then
    select cp.acrescimo_percent
      into v_acresc
    from c.condicao_pagamento cp
    where cp.id = new.condicao_pagamento_id
      and cp.tenant_id = new.tenant_id
      and cp.empresa_id = new.empresa_id
      and cp.deleted_at is null;

    if v_acresc is null then
      raise exception 'Condição de pagamento inválida para este tenant/empresa (id=%)', new.condicao_pagamento_id;
    end if;
  end if;

  new.acrescimo_cond_pag_percent := coalesce(v_acresc,0);

  -- numeração/código apenas no INSERT
  if tg_op = 'INSERT' then
    if new.numero is null or new.numero < 1 then
      new.numero := m.orcamento_next_numero(new.tenant_id, new.empresa_id);
    end if;

    if new.versao is null or new.versao < 1 then
      new.versao := 1;
    end if;

    -- NOVO PADRÃO
    new.codigo := m.orcamento_build_codigo(new.empresa_id, new.numero, new.emissao_date);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "m"."trg_orcamento_biu"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."trg_orcamento_item_aiud"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    SET "row_security" TO 'off'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform m.fn_orcamento_recalcular_totais(old.orcamento_id);
    return old;
  else
    perform m.fn_orcamento_recalcular_totais(new.orcamento_id);
    return new;
  end if;
end;
$$;


ALTER FUNCTION "m"."trg_orcamento_item_aiud"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."trg_orcamento_item_biu"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public', 'a'
    SET "row_security" TO 'off'
    AS $$
declare
  v_orc m.orcamento%rowtype;
  v_item public.itens%rowtype;
  v_tipo text;
  v_calc record;
  v_desc_livre text;
begin
  if tg_op = 'UPDATE' and new.orcamento_id is distinct from old.orcamento_id then
    raise exception 'Nao e permitido alterar orcamento_id do item.';
  end if;

  if tg_op = 'UPDATE' and new.deleted_at is not null and old.deleted_at is null then
    new.tenant_id := old.tenant_id;
    new.empresa_id := old.empresa_id;
    return new;
  end if;

  select * into v_orc
  from m.orcamento o
  where o.id = new.orcamento_id
    and o.deleted_at is null;

  if not found then
    raise exception 'Orcamento nao encontrado (orcamento_id=%)', new.orcamento_id;
  end if;

  new.tenant_id := v_orc.tenant_id;
  new.empresa_id := v_orc.empresa_id;

  if new.seq is null or new.seq < 1 then
    select coalesce(max(seq),0) + 1
      into new.seq
    from m.orcamento_item
    where orcamento_id = new.orcamento_id;
  end if;

  select * into v_item
  from public.itens i
  where i.id = new.item_id
    and i.tenant_id = new.tenant_id
    and i.empresa_id = new.empresa_id
    and i.ativo = true;

  if not found then
    raise exception 'Item invalido para este tenant/empresa (item_id=%)', new.item_id;
  end if;

  v_tipo := lower(v_item.tipo);
  if v_tipo = 'produto' then
    new.item_tipo := 'PRODUTO';
  elsif v_tipo = 'servico' then
    new.item_tipo := 'SERVICO';
  elsif v_tipo = 'despesa' then
    new.item_tipo := 'DESPESA';
  else
    raise exception 'Item do tipo "%" nao e permitido em Orcamento (somente produto/servico/despesa)', v_item.tipo;
  end if;

  new.item_nome := upper(trim(v_item.nome));
  new.unidade := upper(trim(coalesce(v_item.unidade_medida, 'UN')));

  v_desc_livre := nullif(trim(coalesce(new.observacoes, '')), '');
  if upper(trim(coalesce(v_item.codigo_interno, ''))) = '9999' and v_desc_livre is not null then
    new.item_nome := upper(v_desc_livre);
  end if;

  new.acrescimo_cond_pag_percent := v_orc.acrescimo_cond_pag_percent;
  new.desconto_global_percent := v_orc.desconto_global_percent;

  select * into v_calc
  from m.fn_orcamento_item_calcular(
    new.quantidade,
    new.valor_unitario,
    new.desconto_item_percent,
    new.acrescimo_cond_pag_percent,
    new.desconto_global_percent
  );

  new.valor_total_bruto := v_calc.valor_total_bruto;
  new.valor_total := v_calc.valor_total;
  new.valor_unitario_liquido := v_calc.valor_unitario_liquido;

  return new;
end;
$$;


ALTER FUNCTION "m"."trg_orcamento_item_biu"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."trg_pedido_compra_biu"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_condicao_id uuid;
begin
  if tg_op = 'INSERT' then
    if new.numero is null or new.numero <= 0 then
      new.numero := m.pedido_compra_next_numero(
        new.tenant_id,
        new.empresa_id
      );
    end if;
    if new.codigo is null or btrim(new.codigo) = '' then
      new.codigo := m.pedido_compra_build_codigo(
        new.empresa_id,
        new.numero,
        new.emissao_date
      );
    end if;
  end if;

  new.status := upper(trim(coalesce(new.status, 'RASCUNHO')));
  new.transporte_tipo :=
    nullif(upper(btrim(coalesce(new.transporte_tipo, ''))), '');
  new.transportadora_nome :=
    nullif(btrim(coalesce(new.transportadora_nome, '')), '');
  new.destacar_ipi := coalesce(new.destacar_ipi, false);

  if new.transporte_tipo is not null
     and new.transporte_tipo not in ('CIF', 'FOB')
  then
    raise exception 'Transporte invalido. Use CIF ou FOB.';
  end if;

  if new.transporte_tipo = 'FOB'
     and new.transportadora_nome is null
  then
    raise exception
      'Informe a transportadora quando o transporte for FOB.';
  end if;

  if new.transporte_tipo is distinct from 'FOB' then
    new.transportadora_nome := null;
  end if;

  if new.condicao_pagamento_id is not null then
    select condicao.id
      into v_condicao_id
    from c.condicao_pagamento condicao
    where condicao.id = new.condicao_pagamento_id
      and condicao.tenant_id = new.tenant_id
      and condicao.empresa_id = new.empresa_id
      and condicao.deleted_at is null
    limit 1;

    if v_condicao_id is null then
      raise exception
        'Condicao de pagamento invalida para este tenant/empresa (id=%)',
        new.condicao_pagamento_id;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "m"."trg_pedido_compra_biu"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."trg_pedido_compra_item_aiud"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    AS $$
begin
  perform m.fn_pedido_compra_recalcular_totais(coalesce(new.pedido_compra_id, old.pedido_compra_id));
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "m"."trg_pedido_compra_item_aiud"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."trg_pedido_compra_item_biu"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    AS $$
declare
  v_destacar_ipi boolean := false;
  v_aliquota_cadastro numeric(9,4);
begin
  if tg_op = 'INSERT' and (new.seq is null or new.seq <= 0) then
    select coalesce(max(item.seq), 0) + 1
      into new.seq
    from m.pedido_compra_item item
    where item.pedido_compra_id = new.pedido_compra_id
      and item.deleted_at is null;
  end if;

  if new.item_id is not null then
    select
      item.codigo_interno,
      upper(trim(coalesce(item.nome, item.descricao, new.item_nome))),
      coalesce(nullif(trim(item.unidade_medida), ''), new.unidade, 'UN')
      into new.item_codigo, new.item_nome, new.unidade
    from public.itens item
    where item.tenant_id = new.tenant_id
      and item.empresa_id = new.empresa_id
      and item.id = new.item_id
    limit 1;

    if tg_op = 'INSERT' and new.valor_ipi_unitario is null then
      select greatest(coalesce(fiscal.aliq_ipi, 0), 0)
        into v_aliquota_cadastro
      from public.fiscal_itens fiscal
      where fiscal.tenant_id = new.tenant_id
        and fiscal.empresa_id = new.empresa_id
        and fiscal.item_id = new.item_id
      limit 1;

      new.aliquota_ipi := coalesce(v_aliquota_cadastro, 0);
      new.valor_ipi_unitario := round(
        coalesce(new.valor_unitario, 0)
        * coalesce(v_aliquota_cadastro, 0)
        / 100,
        4
      );
    end if;
  else
    new.item_nome := upper(trim(coalesce(new.item_nome, '')));
    new.unidade := coalesce(nullif(trim(new.unidade), ''), 'UN');
  end if;

  select coalesce(pedido.destacar_ipi, false)
    into v_destacar_ipi
  from m.pedido_compra pedido
  where pedido.id = new.pedido_compra_id
    and pedido.tenant_id = new.tenant_id
    and pedido.empresa_id = new.empresa_id
    and pedido.deleted_at is null;

  new.valor_ipi_total := case
    when v_destacar_ipi then round(
      coalesce(new.quantidade, 0)
      * coalesce(new.valor_ipi_unitario, 0),
      2
    )
    else 0
  end;
  new.valor_total := round(
    coalesce(new.quantidade, 0)
    * (
      coalesce(new.valor_unitario, 0)
      + case
          when v_destacar_ipi then coalesce(new.valor_ipi_unitario, 0)
          else 0
        end
    ),
    2
  );
  return new;
end;
$$;


ALTER FUNCTION "m"."trg_pedido_compra_item_biu"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."venda_build_codigo"("p_empresa_id" "uuid", "p_numero" integer, "p_emissao_date" "date") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'm', 'public', 'c'
    AS $$
  select 'OV-' || upper(trim(coalesce(empresa.codigo, 'SEMEMP')))
         || '-' || lpad(greatest(p_numero, 1)::text, 5, '0')
         || '-' || lpad(((extract(year from coalesce(p_emissao_date, current_date))::int) % 1000)::text, 3, '0')
  from c.empresa as empresa
  where empresa.id = p_empresa_id;
$$;


ALTER FUNCTION "m"."venda_build_codigo"("p_empresa_id" "uuid", "p_numero" integer, "p_emissao_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."venda_cancelar"("p_venda_id" integer, "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'm', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_status text;
begin
  if auth.uid() is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticacao e contexto de empresa sao obrigatorios.';
  end if;

  if not (public.can('os_rpcs', 'execute') or public.has_permission('os.write')) then
    raise exception 'Sem permissao para cancelar a venda.';
  end if;

  if nullif(btrim(p_motivo), '') is null then
    raise exception 'Informe o motivo do cancelamento.';
  end if;

  select venda.status_fluxo
    into v_status
  from public.ordens_servico as venda
  where venda.id = p_venda_id
    and venda.tenant_id = v_tenant_id
    and venda.empresa_id = v_empresa_id
    and venda.tipo_documento = 'OV'
  for update;

  if not found then
    raise exception 'Venda nao encontrada na empresa atual.';
  end if;
  if v_status in ('faturada', 'cancelada') then
    raise exception 'Venda faturada ou ja cancelada nao pode ser cancelada.';
  end if;

  update public.ordens_servico
     set status = 'cancelada',
         status_fluxo = 'cancelada',
         observacoes = concat_ws(' | ', nullif(observacoes, ''), 'Cancelamento: ' || btrim(p_motivo)),
         atualizado_em = now()
   where id = p_venda_id
     and tenant_id = v_tenant_id
     and empresa_id = v_empresa_id;

  insert into public.ordens_servico_fluxo_eventos (
    tenant_id, empresa_id, os_id, evento, status_origem, status_destino, motivo, realizado_por
  ) values (
    v_tenant_id, v_empresa_id, p_venda_id, 'cancelar_venda', v_status, 'cancelada', btrim(p_motivo), auth.uid()
  );

  return jsonb_build_object('sucesso', true);
end;
$$;


ALTER FUNCTION "m"."venda_cancelar"("p_venda_id" integer, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."venda_converter_em_os"("p_venda_id" integer, "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'm', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_codigo_origem text;
  v_status text;
begin
  if auth.uid() is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticacao e contexto de empresa sao obrigatorios.';
  end if;

  if not (public.can('os_rpcs', 'execute') or public.has_permission('os.write')) then
    raise exception 'Sem permissao para converter a venda.';
  end if;

  select venda.codigo, venda.status_fluxo
    into v_codigo_origem, v_status
  from public.ordens_servico as venda
  where venda.id = p_venda_id
    and venda.tenant_id = v_tenant_id
    and venda.empresa_id = v_empresa_id
    and venda.tipo_documento = 'OV'
  for update;

  if not found then
    raise exception 'Venda nao encontrada na empresa atual.';
  end if;
  if coalesce(v_status, 'em_andamento') <> 'em_andamento' then
    raise exception 'Somente uma venda em andamento pode ser convertida em OS.';
  end if;
  if exists (
    select 1 from public.apontamentos_horas as horas
    where horas.os_id = p_venda_id
      and horas.tenant_id = v_tenant_id
      and horas.empresa_id = v_empresa_id
  ) or exists (
    select 1 from public.hh_lancamentos as hh
    where hh.os_id = p_venda_id
      and hh.tenant_id = v_tenant_id
      and hh.empresa_id = v_empresa_id
  ) then
    raise exception 'A venda possui lancamentos de horas e nao pode ser convertida automaticamente.';
  end if;

  update public.ordens_servico
     set tipo_documento = 'OS',
         codigo = null,
         numero_doc = null,
         atualizado_em = now()
   where id = p_venda_id
     and tenant_id = v_tenant_id
     and empresa_id = v_empresa_id;

  insert into public.ordens_servico_fluxo_eventos (
    tenant_id, empresa_id, os_id, evento, status_origem, status_destino, motivo, realizado_por
  ) values (
    v_tenant_id,
    v_empresa_id,
    p_venda_id,
    'converter_ov_em_os',
    'OV',
    'OS',
    concat_ws(' | ', 'Origem ' || v_codigo_origem, nullif(btrim(p_motivo), '')),
    auth.uid()
  );

  return jsonb_build_object('sucesso', true, 'os_id', p_venda_id);
end;
$$;


ALTER FUNCTION "m"."venda_converter_em_os"("p_venda_id" integer, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."venda_next_numero"("p_tenant" "uuid", "p_empresa" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'm', 'public'
    AS $$
declare
  v_next integer;
begin
  if p_tenant is null or p_empresa is null then
    raise exception 'Tenant e empresa sao obrigatorios para numerar a venda.';
  end if;

  insert into m.venda_seq (tenant_id, empresa_id, proximo_numero)
  values (p_tenant, p_empresa, 1)
  on conflict (tenant_id, empresa_id) do nothing;

  update m.venda_seq as sequencia
     set proximo_numero = sequencia.proximo_numero + 1,
         updated_at = now()
   where sequencia.tenant_id = p_tenant
     and sequencia.empresa_id = p_empresa
  returning sequencia.proximo_numero - 1 into v_next;

  return coalesce(v_next, 1);
end;
$$;


ALTER FUNCTION "m"."venda_next_numero"("p_tenant" "uuid", "p_empresa" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "m"."venda_vincular_documento_fiscal"("p_venda_id" integer, "p_documento_fiscal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'm', 'f', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
begin
  if auth.uid() is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticacao e contexto de empresa sao obrigatorios.';
  end if;

  if not (
    public.can('os_rpcs', 'execute')
    or public.has_permission('os.write')
    or public.can('financeiro', 'write')
    or public.has_permission('financeiro.write')
  ) then
    raise exception 'Sem permissao para vincular documento fiscal a venda.';
  end if;

  if not exists (
    select 1
    from public.ordens_servico as venda
    where venda.id = p_venda_id
      and venda.tenant_id = v_tenant_id
      and venda.empresa_id = v_empresa_id
      and venda.tipo_documento = 'OV'
  ) then
    raise exception 'Venda nao encontrada na empresa atual.';
  end if;

  update f.documento_fiscal as documento
     set os_id_import = p_venda_id,
         updated_at = now()
   where documento.id = p_documento_fiscal_id
     and documento.tenant_id = v_tenant_id
     and documento.empresa_id = v_empresa_id
     and documento.operacao = 'SAIDA'
     and documento.deleted_at is null
     and (documento.os_id_import is null or documento.os_id_import = p_venda_id);

  if not found then
    raise exception 'Documento fiscal de saida indisponivel ou ja vinculado a outro documento.';
  end if;

  insert into public.ordens_servico_fluxo_eventos (
    tenant_id, empresa_id, os_id, evento, status_origem, status_destino, motivo, realizado_por
  ) values (
    v_tenant_id, v_empresa_id, p_venda_id, 'vincular_documento_fiscal', null, null,
    'Documento fiscal ' || p_documento_fiscal_id::text, auth.uid()
  );

  return jsonb_build_object('sucesso', true);
end;
$$;


ALTER FUNCTION "m"."venda_vincular_documento_fiscal"("p_venda_id" integer, "p_documento_fiscal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."a_is_empresa_member"("p_empresa_id" "uuid") RETURNS boolean
