CREATE TABLE IF NOT EXISTS "public"."os_itens" (
    "id" integer NOT NULL,
    "os_id" integer NOT NULL,
    "item_id" integer NOT NULL,
    "quantidade" numeric(14,3) DEFAULT 0 NOT NULL,
    "valor_unitario" numeric(10,2) NOT NULL,
    "valor_total" numeric(12,2) NOT NULL,
    "desconto_percentual" numeric(5,2) DEFAULT 0,
    "desconto_valor" numeric(10,2) DEFAULT 0,
    "baixa_estoque" boolean DEFAULT false,
    "observacoes" "text",
    "criado_em" timestamp without time zone DEFAULT "now"(),
    "tenant_id" "uuid" NOT NULL,
    "empresa_id" "uuid" DEFAULT "public"."current_empresa_id"() NOT NULL,
    "quantidade_baixada" numeric(14,3) DEFAULT 0 NOT NULL,
    "registrado_em" timestamp with time zone,
    "registrado_por" "uuid",
    "registrado_por_nome" "text",
    CONSTRAINT "chk_os_itens_quantidade_baixada_lte_quantidade" CHECK (("quantidade_baixada" <= "quantidade")),
    CONSTRAINT "chk_os_itens_quantidade_baixada_nonnegative" CHECK (("quantidade_baixada" >= (0)::numeric)),
    CONSTRAINT "chk_os_itens_quantidade_pos" CHECK (("quantidade" > (0)::numeric))
);


ALTER TABLE "public"."os_itens" OWNER TO "postgres";


COMMENT ON COLUMN "public"."os_itens"."quantidade_baixada" IS 'Quantidade efetivamente baixada do estoque para o item da OS. Pode ser menor que quantidade quando o saldo disponivel nao cobre 100%.';



COMMENT ON COLUMN "public"."os_itens"."registrado_em" IS 'Data e hora da inclusao ou ultima alteracao do item na OS.';



COMMENT ON COLUMN "public"."os_itens"."registrado_por" IS 'Usuario autenticado responsavel pela inclusao ou ultima alteracao do item na OS.';



COMMENT ON COLUMN "public"."os_itens"."registrado_por_nome" IS 'Nome do usuario responsavel, preservado para exibicao e auditoria.';



CREATE OR REPLACE FUNCTION "public"."add_os_item_baixa_imediata"("p_os_id" integer, "p_item_id" integer, "p_quantidade" numeric, "p_valor_unitario" numeric, "p_desconto_percentual" numeric DEFAULT 0, "p_desconto_valor" numeric DEFAULT 0, "p_baixa_estoque" boolean DEFAULT true, "p_realizado_por" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "public"."os_itens"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select public.add_os_item_baixa_imediata(
    p_os_id,
    p_item_id,
    p_quantidade,
    p_valor_unitario,
    p_desconto_percentual,
    p_desconto_valor,
    p_baixa_estoque,
    p_realizado_por,
    p_motivo,
    null::uuid
  );
$$;


ALTER FUNCTION "public"."add_os_item_baixa_imediata"("p_os_id" integer, "p_item_id" integer, "p_quantidade" numeric, "p_valor_unitario" numeric, "p_desconto_percentual" numeric, "p_desconto_valor" numeric, "p_baixa_estoque" boolean, "p_realizado_por" "text", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_os_item_baixa_imediata"("p_os_id" integer, "p_item_id" integer, "p_quantidade" numeric, "p_valor_unitario" numeric, "p_desconto_percentual" numeric DEFAULT 0, "p_desconto_valor" numeric DEFAULT 0, "p_baixa_estoque" boolean DEFAULT true, "p_realizado_por" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_empresa_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."os_itens"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_item public.itens%rowtype;
  v_os public.ordens_servico%rowtype;
  v_total numeric;
  v_row public.os_itens%rowtype;
  v_tenant uuid;
  v_realizado_por text;
  v_empresa uuid;
  v_os_label text;
  v_motivo text;
  v_saldo_atual numeric(14,3) := 0;
  v_quantidade_baixada numeric(14,3) := 0;
begin
  if auth.uid() is null then
    raise exception 'Nao autenticado';
  end if;

  v_tenant := public.current_tenant_id();
  if v_tenant is null then
    raise exception 'Tenant atual nao definido';
  end if;

  if not (
    public.can('os_rpcs', 'execute')
    or public.has_permission('os.write')
  ) then
    raise exception 'Sem permissao para executar operacao de OS';
  end if;

  v_empresa := coalesce(p_empresa_id, public.current_empresa_id());
  if v_empresa is null then
    raise exception 'Empresa atual nao definida. Informe p_empresa_id na chamada da RPC.';
  end if;

  perform public.set_current_empresa(v_empresa);

  v_realizado_por := coalesce(p_realizado_por, auth.uid()::text);

  select *
    into v_os
  from public.ordens_servico os
  where os.id = p_os_id
    and os.tenant_id = v_tenant
    and os.empresa_id = v_empresa;

  if not found then
    raise exception 'OS invalida ou fora do tenant/empresa atual';
  end if;

  select *
    into v_item
  from public.itens
  where id = p_item_id
    and tenant_id = v_tenant
    and empresa_id = v_empresa
    and ativo = true;

  if not found then
    raise exception 'Item invalido/inativo ou fora do tenant/empresa atual';
  end if;

  if p_quantidade is null or p_quantidade <= 0 then
    raise exception 'Quantidade invalida';
  end if;

  if coalesce(p_baixa_estoque, true)
     and v_item.tipo = 'produto'
     and coalesce(v_item.controla_estoque, false) = true
  then
    if not (public.can('estoque', 'write') or public.can('os_rpcs', 'execute')) then
      raise exception 'Sem permissao para movimentar estoque';
    end if;

    select coalesce(e.quantidade_atual, 0)
      into v_saldo_atual
    from public.estoque e
    where e.tenant_id = v_tenant
      and e.empresa_id = v_empresa
      and e.item_id = p_item_id
    for update;

    if not found then
      v_saldo_atual := 0;
    end if;

    v_quantidade_baixada := least(p_quantidade, greatest(coalesce(v_saldo_atual, 0), 0));
  end if;

  v_total := (p_quantidade * coalesce(p_valor_unitario, 0)) - coalesce(p_desconto_valor, 0);

  insert into public.os_itens (
    tenant_id,
    empresa_id,
    os_id,
    item_id,
    quantidade,
    valor_unitario,
    valor_total,
    desconto_percentual,
    desconto_valor,
    baixa_estoque,
    quantidade_baixada,
    criado_em
  )
  values (
    v_tenant,
    v_empresa,
    p_os_id,
    p_item_id,
    p_quantidade,
    coalesce(p_valor_unitario, 0),
    v_total,
    coalesce(p_desconto_percentual, 0),
    coalesce(p_desconto_valor, 0),
    v_quantidade_baixada >= p_quantidade,
    v_quantidade_baixada,
    now()
  )
  returning * into v_row;

  if v_quantidade_baixada > 0 then
    v_os_label := coalesce(nullif(trim(v_os.numero_os), ''), nullif(v_os.os_num::text, ''), v_os.id::text);
    v_motivo := nullif(trim(coalesce(p_motivo, '')), '');
    if v_motivo is null then
      v_motivo := 'Baixa imediata via OS ' || v_os_label;
    end if;

    v_motivo := trim(regexp_replace(v_motivo, '[[:space:]]*\[OS[[:space:]]+[^\]]+\][[:space:]]*$', '', 'i'));
    if position(upper('OS ' || v_os_label) in upper(v_motivo)) = 0 then
      v_motivo := v_motivo || ' [OS ' || v_os_label || ']';
    end if;

    insert into public.movimentacoes (
      tenant_id,
      empresa_id,
      item_id,
      tipo,
      quantidade,
      motivo,
      realizado_por,
      data_movimentacao,
      origem_os_id,
      created_at
    )
    values (
      v_tenant,
      v_empresa,
      p_item_id,
      'saida',
      v_quantidade_baixada,
      v_motivo,
      v_realizado_por,
      now(),
      p_os_id,
      now()
    );
  end if;

  update public.ordens_servico os
  set valor_total = coalesce((
        select sum(oi.valor_total)
        from public.os_itens oi
        where oi.os_id = p_os_id
          and oi.tenant_id = v_tenant
          and oi.empresa_id = v_empresa
      ), 0),
      atualizado_em = now()
  where os.id = p_os_id
    and os.tenant_id = v_tenant
    and os.empresa_id = v_empresa;

  return v_row;
end;
$_$;


ALTER FUNCTION "public"."add_os_item_baixa_imediata"("p_os_id" integer, "p_item_id" integer, "p_quantidade" numeric, "p_valor_unitario" numeric, "p_desconto_percentual" numeric, "p_desconto_valor" numeric, "p_baixa_estoque" boolean, "p_realizado_por" "text", "p_motivo" "text", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_can_assign_legacy_roles"("p_tenant_id" "uuid", "p_role_ids" "uuid"[]) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_role_ids uuid[] := coalesce(p_role_ids, array[]::uuid[]);
begin
  if not a.fn_can_manage_legacy_role_assignments(p_tenant_id) then
    return false;
  end if;

  if cardinality(v_role_ids) <> (
    select count(distinct requested.role_id)::integer
    from unnest(v_role_ids) requested(role_id)
    where requested.role_id is not null
  ) then
    return false;
  end if;

  return not exists (
    select 1
    from unnest(v_role_ids) requested(role_id)
    left join public.roles r
      on r.id = requested.role_id
     and r.tenant_id = p_tenant_id
    where r.id is null
  );
end;
$$;


ALTER FUNCTION "public"."admin_can_assign_legacy_roles"("p_tenant_id" "uuid", "p_role_ids" "uuid"[]) OWNER TO "postgres";


