CREATE OR REPLACE FUNCTION "public"."admin_can_manage_users"("p_tenant_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select public.has_active_tenant_access(p_tenant_id)
    and coalesce(
      a.fn_current_empresa_papel(
        p_tenant_id,
        public.current_empresa_id__by_tenant(p_tenant_id)
      ),
      ''
    ) <> 'DIRETOR'
    and exists (
      select 1
      from a.usuario u
      join a.usuario_tenant ut on ut.usuario_id = u.id
      where u.auth_user_id = auth.uid()
        and u.ativo is true
        and u.deleted_at is null
        and ut.tenant_id = p_tenant_id
        and ut.papel in ('OWNER','ADMIN')
        and ut.ativo is true
        and ut.deleted_at is null
    );
$$;


ALTER FUNCTION "public"."admin_can_manage_users"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_can_manage_users"("p_tenant_id" "uuid") IS 'Gestao de usuarios e exclusiva de OWNER e ADMIN ativos; DIRETOR e somente operacional.';



CREATE OR REPLACE FUNCTION "public"."admin_finalize_invited_user"("p_tenant_id" "uuid", "p_auth_user_id" "uuid", "p_email" "text", "p_nome" "text", "p_telefone" "text", "p_tenant_papel" "text", "p_empresa_vinculos" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_usuario_id uuid;
  v_result uuid;
begin
  perform 1
  from public.tenants t
  where t.id = p_tenant_id
    and t.ativo is true
  for update;
  if not found then
    raise exception 'tenant_not_found_or_inactive';
  end if;

  perform 1
  from auth.users au
  where au.id = p_auth_user_id
  for update;
  if not found then
    raise exception 'auth_user_not_found';
  end if;

  select u.id
    into v_usuario_id
  from a.usuario u
  where u.auth_user_id = p_auth_user_id
  for update;

  perform a.assert_admin_hierarchy_locked(
    p_tenant_id,
    v_usuario_id,
    p_tenant_papel,
    false
  );
  perform a.assert_legacy_role_reactivation_scope(
    p_tenant_id,
    p_auth_user_id,
    true,
    true
  );
  perform a.assert_global_user_profile_scope(
    p_tenant_id,
    v_usuario_id,
    true,
    p_nome,
    true,
    p_email,
    true,
    p_telefone,
    true,
    true
  );
  perform a.admin_upsert_auth_profile_locked(
    p_tenant_id,
    p_auth_user_id,
    p_nome,
    p_tenant_papel,
    false
  );

  v_result := public.admin_finalize_invited_user_impl_20260811(
    p_tenant_id,
    p_auth_user_id,
    p_email,
    p_nome,
    p_telefone,
    p_tenant_papel,
    p_empresa_vinculos
  );
  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_finalize_invited_user"("p_tenant_id" "uuid", "p_auth_user_id" "uuid", "p_email" "text", "p_nome" "text", "p_telefone" "text", "p_tenant_papel" "text", "p_empresa_vinculos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_finalize_invited_user_impl_20260811"("p_tenant_id" "uuid", "p_auth_user_id" "uuid", "p_email" "text", "p_nome" "text", "p_telefone" "text", "p_tenant_papel" "text", "p_empresa_vinculos" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_usuario_id uuid;
  v_existing_usuario_id uuid;
  v_old_tenant_papel text;
  v_old_tenant_ativo boolean;
  v_tenant_papel text := upper(trim(coalesce(p_tenant_papel, '')));
  v_auth_email text;
  v_item jsonb;
begin
  if not public.admin_can_manage_users(p_tenant_id) then
    raise exception 'not_allowed';
  end if;

  if p_auth_user_id is null
     or nullif(trim(coalesce(p_nome, '')), '') is null then
    raise exception 'invalid_user_payload';
  end if;

  if v_tenant_papel not in ('OWNER','ADMIN','DIRETOR','CONTADOR','GESTOR') then
    raise exception 'invalid_tenant_role: %', v_tenant_papel;
  end if;

  perform 1
  from public.tenants t
  where t.id = p_tenant_id
    and t.ativo is true
  for update;
  if not found then
    raise exception 'tenant_not_found_or_inactive';
  end if;

  if v_tenant_papel = 'OWNER'
     and not public.admin_is_owner(p_tenant_id) then
    raise exception 'owner_change_requires_owner';
  end if;

  perform a.validate_empresa_vinculos_payload(p_tenant_id, p_empresa_vinculos);
  perform a.validate_admin_empresa_scope(p_tenant_id, p_empresa_vinculos);

  select lower(au.email)
    into v_auth_email
  from auth.users au
  where au.id = p_auth_user_id
  for update;
  if not found then
    raise exception 'auth_user_not_found';
  end if;

  if v_auth_email is null
     or lower(trim(coalesce(p_email, ''))) is distinct from v_auth_email then
    raise exception 'auth_user_email_mismatch';
  end if;

  select u.id
    into v_existing_usuario_id
  from a.usuario u
  where u.auth_user_id = p_auth_user_id
  for update;

  if v_existing_usuario_id is not null then
    select ut.papel, ut.ativo
      into v_old_tenant_papel, v_old_tenant_ativo
    from a.usuario_tenant ut
    where ut.usuario_id = v_existing_usuario_id
      and ut.tenant_id = p_tenant_id
      and ut.deleted_at is null
    for update;

    if v_old_tenant_papel = 'OWNER'
       and not public.admin_is_owner(p_tenant_id) then
      raise exception 'owner_change_requires_owner';
    end if;

    if v_old_tenant_papel = 'OWNER'
       and v_old_tenant_ativo is true
       and v_tenant_papel <> 'OWNER'
       and not exists (
         select 1
         from a.usuario_tenant other_ut
         join a.usuario other_u on other_u.id = other_ut.usuario_id
         where other_ut.tenant_id = p_tenant_id
           and other_ut.usuario_id <> v_existing_usuario_id
           and other_ut.papel = 'OWNER'
           and other_ut.ativo is true
           and other_ut.deleted_at is null
           and other_u.ativo is true
           and other_u.deleted_at is null
       ) then
      raise exception 'last_active_owner';
    end if;
  end if;

  insert into a.usuario (
    id, auth_user_id, nome, email, telefone, ativo,
    created_at, updated_at, created_by, updated_by, deleted_at
  )
  values (
    gen_random_uuid(),
    p_auth_user_id,
    trim(p_nome),
    v_auth_email,
    nullif(regexp_replace(coalesce(p_telefone, ''), '\D', '', 'g'), ''),
    true,
    now(), now(), auth.uid(), auth.uid(), null
  )
  on conflict (auth_user_id)
  do update set
    nome = excluded.nome,
    email = excluded.email,
    telefone = excluded.telefone,
    ativo = true,
    updated_at = now(),
    updated_by = auth.uid(),
    deleted_at = null
  returning id into v_usuario_id;

  insert into a.usuario_tenant (
    id, usuario_id, tenant_id, papel, ativo,
    created_at, updated_at, created_by, updated_by, deleted_at
  )
  values (
    gen_random_uuid(), v_usuario_id, p_tenant_id, v_tenant_papel, true,
    now(), now(), auth.uid(), auth.uid(), null
  )
  on conflict (usuario_id, tenant_id) where deleted_at is null
  do update set
    papel = excluded.papel,
    ativo = true,
    updated_at = now(),
    updated_by = auth.uid(),
    deleted_at = null;

  for v_item in select value from jsonb_array_elements(p_empresa_vinculos)
  loop
    insert into a.usuario_empresa (
      id, usuario_id, empresa_id, papel, ativo,
      permissoes_extra, permissoes_negadas,
      created_at, updated_at, created_by, updated_by, deleted_at
    )
    values (
      gen_random_uuid(),
      v_usuario_id,
      (v_item ->> 'empresa_id')::uuid,
      upper(trim(v_item ->> 'papel')),
      (v_item ->> 'ativo')::boolean,
      null, null,
      now(), now(), auth.uid(), auth.uid(), null
    )
    on conflict (usuario_id, empresa_id) where deleted_at is null
    do update set
      papel = excluded.papel,
      ativo = excluded.ativo,
      updated_at = now(),
      updated_by = auth.uid(),
      deleted_at = null;
  end loop;

  perform a.sync_usuario_access_projection(v_usuario_id);
  return v_usuario_id;
end;
$$;


ALTER FUNCTION "public"."admin_finalize_invited_user_impl_20260811"("p_tenant_id" "uuid", "p_auth_user_id" "uuid", "p_email" "text", "p_nome" "text", "p_telefone" "text", "p_tenant_papel" "text", "p_empresa_vinculos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_finalize_legacy_user"("p_tenant_id" "uuid", "p_auth_user_id" "uuid", "p_email" "text", "p_nome" "text", "p_role_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_role_ids uuid[] := coalesce(p_role_ids, array[]::uuid[]);
  v_usuario_id uuid;
  v_existing_membership_id uuid;
  v_existing_membership_status text;
  v_has_existing_roles boolean := false;
  v_can_manage_roles boolean;
begin
  perform 1
  from public.tenants t
  where t.id = p_tenant_id
    and t.ativo is true
  for update;
  if not found then
    raise exception 'tenant_not_found_or_inactive';
  end if;

  perform 1
  from auth.users au
  where au.id = p_auth_user_id
  for update;
  if not found then
    raise exception 'auth_user_not_found';
  end if;

  select u.id
    into v_usuario_id
  from a.usuario u
  where u.auth_user_id = p_auth_user_id
    and u.deleted_at is null
  for update;

  if v_usuario_id is not null and exists (
    select 1
    from a.usuario_tenant ut
    where ut.usuario_id = v_usuario_id
      and ut.tenant_id = p_tenant_id
      and ut.ativo is true
      and ut.deleted_at is null
  ) then
    raise exception 'user_already_active_in_tenant';
  end if;

  select tm.id, tm.status
    into v_existing_membership_id, v_existing_membership_status
  from public.tenant_memberships tm
  where tm.user_id = p_auth_user_id
    and tm.tenant_id = p_tenant_id
  for update;

  if v_existing_membership_status in ('active', 'ativo') then
    raise exception 'user_already_active_in_tenant';
  end if;

  if v_existing_membership_id is not null then
    v_has_existing_roles := exists (
      select 1
      from public.membership_roles mr
      where mr.membership_id = v_existing_membership_id
    );
  end if;

  v_can_manage_roles := a.fn_can_manage_legacy_role_assignments(p_tenant_id);

  if (cardinality(v_role_ids) > 0 or v_has_existing_roles)
     and not v_can_manage_roles then
    raise exception 'role_hierarchy_violation';
  end if;

  if v_can_manage_roles
     and not public.admin_can_assign_legacy_roles(p_tenant_id, v_role_ids) then
    raise exception 'invalid_or_out_of_scope_role_ids';
  end if;

  v_usuario_id := public.admin_finalize_invited_user(
    p_tenant_id,
    p_auth_user_id,
    p_email,
    p_nome,
    null,
    'GESTOR',
    '[]'::jsonb
  );

  if v_can_manage_roles then
    perform public.admin_replace_membership_roles(
      p_tenant_id,
      p_auth_user_id,
      v_role_ids
    );
  end if;

  return v_usuario_id;
end;
$$;


ALTER FUNCTION "public"."admin_finalize_legacy_user"("p_tenant_id" "uuid", "p_auth_user_id" "uuid", "p_email" "text", "p_nome" "text", "p_role_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_is_owner"("p_tenant_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select public.has_active_tenant_access(p_tenant_id)
    and exists (
      select 1
      from a.usuario u
      join a.usuario_tenant ut on ut.usuario_id = u.id
      where u.auth_user_id = auth.uid()
        and u.ativo is true
        and u.deleted_at is null
        and ut.tenant_id = p_tenant_id
        and ut.papel = 'OWNER'
        and ut.ativo is true
        and ut.deleted_at is null
    );
$$;


ALTER FUNCTION "public"."admin_is_owner"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_users"("p_tenant_id" "uuid") RETURNS TABLE("usuario_id" "uuid", "auth_user_id" "uuid", "nome" "text", "email" "text", "telefone" "text", "usuario_ativo" boolean, "tenant_papel" "text", "tenant_ativo" boolean, "tenant_deleted_at" timestamp with time zone, "empresas" "jsonb", "usuario_created_at" timestamp with time zone, "usuario_updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'a'
    AS $$
  -- autorização
  select
    u.id as usuario_id,
    u.auth_user_id,
    u.nome,
    u.email,
    u.telefone,
    u.ativo as usuario_ativo,
    ut.papel as tenant_papel,
    ut.ativo as tenant_ativo,
    ut.deleted_at as tenant_deleted_at,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', ue.id,
            'empresa_id', ue.empresa_id,
            'empresa_nome', coalesce(e.nome_fantasia, e.razao_social, 'Empresa'),
            'papel', ue.papel,
            'ativo', ue.ativo,
            'deleted_at', ue.deleted_at
          )
          order by coalesce(e.nome_fantasia, e.razao_social, 'Empresa')
        )
        from a.usuario_empresa ue
        join public.empresas e on e.id = ue.empresa_id
        where ue.usuario_id = u.id
          and ue.deleted_at is null
          and e.tenant_id = p_tenant_id
      ),
      '[]'::jsonb
    ) as empresas,
    u.created_at as usuario_created_at,
    u.updated_at as usuario_updated_at
  from a.usuario u
  join a.usuario_tenant ut on ut.usuario_id = u.id
  where ut.tenant_id = p_tenant_id
    and ut.deleted_at is null
    and public.admin_can_manage_users(p_tenant_id) = true
  order by coalesce(u.nome, u.email), u.created_at desc;
$$;


ALTER FUNCTION "public"."admin_list_users"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_merge_fornecedores"("p_tenant_id" "uuid", "p_keep_fornecedor_id" bigint, "p_merge_fornecedor_id" bigint, "p_soft_delete" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c', 'f', 'm', 'r', 'auth', 'extensions'
    AS $_$
declare
  r record;
  v_sql text;
begin
  if p_keep_fornecedor_id = p_merge_fornecedor_id then
    raise exception 'keep e merge não podem ser iguais';
  end if;

  -- garante que ambos são do mesmo tenant
  if not exists (
    select 1 from public.fornecedores
    where id = p_keep_fornecedor_id and tenant_id = p_tenant_id and deleted_at is null
  ) then
    raise exception 'Fornecedor KEEP não encontrado para este tenant';
  end if;

  if not exists (
    select 1 from public.fornecedores
    where id = p_merge_fornecedor_id and tenant_id = p_tenant_id and deleted_at is null
  ) then
    raise exception 'Fornecedor MERGE não encontrado para este tenant';
  end if;

  -- atualiza todas as tabelas que têm FK -> public.fornecedores(id)
  for r in
    select
      n.nspname as schema_name,
      c.relname as table_name,
      a.attname as column_name
    from pg_constraint con
    join pg_class c on c.oid = con.conrelid
    join pg_namespace n on n.oid = c.relnamespace
    join pg_class cref on cref.oid = con.confrelid
    join pg_namespace nref on nref.oid = cref.relnamespace
    join unnest(con.conkey) with ordinality as ck(attnum, ord) on true
    join pg_attribute a on a.attrelid = c.oid and a.attnum = ck.attnum
    where con.contype = 'f'
      and nref.nspname = 'public'
      and cref.relname = 'fornecedores'
      and a.attname in ('fornecedor_id') -- padrão do teu modelo
  loop
    v_sql := format(
      'update %I.%I set %I = $1 where %I = $2',
      r.schema_name, r.table_name, r.column_name, r.column_name
    );
    execute v_sql using p_keep_fornecedor_id, p_merge_fornecedor_id;
  end loop;

  -- por fim, inativa o duplicado
  if p_soft_delete then
    update public.fornecedores
      set deleted_at = now(),
          updated_at = now()
    where id = p_merge_fornecedor_id;
  else
    delete from public.fornecedores
    where id = p_merge_fornecedor_id;
  end if;
end;
$_$;


ALTER FUNCTION "public"."admin_merge_fornecedores"("p_tenant_id" "uuid", "p_keep_fornecedor_id" bigint, "p_merge_fornecedor_id" bigint, "p_soft_delete" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_replace_membership_roles"("p_tenant_id" "uuid", "p_target_auth_user_id" "uuid", "p_role_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_membership_id uuid;
  v_target_usuario_id uuid;
  v_target_deleted_at timestamptz;
  v_role_ids uuid[] := coalesce(p_role_ids, array[]::uuid[]);
begin
  perform 1
  from public.tenants t
  where t.id = p_tenant_id
    and t.ativo is true
  for update;
  if not found then
    raise exception 'tenant_not_found_or_inactive';
  end if;

  if not a.fn_can_manage_legacy_role_assignments(p_tenant_id) then
    raise exception 'role_hierarchy_violation';
  end if;

  perform 1
  from auth.users au
  where au.id = p_target_auth_user_id
  for update;
  if not found then
    raise exception 'auth_user_not_found';
  end if;

  select u.id, u.deleted_at
    into v_target_usuario_id, v_target_deleted_at
  from a.usuario u
  where u.auth_user_id = p_target_auth_user_id
  for update;

  if v_target_deleted_at is not null then
    raise exception 'canonical_user_deleted';
  end if;

  if v_target_usuario_id is not null
     and not a.fn_admin_can_manage_target(
       p_tenant_id,
       v_target_usuario_id,
       null,
       true
     ) then
    raise exception 'role_hierarchy_violation';
  end if;

  select tm.id
    into v_membership_id
  from public.tenant_memberships tm
  where tm.user_id = p_target_auth_user_id
    and tm.tenant_id = p_tenant_id
  for update;
  if not found then
    raise exception 'membership_not_found_in_tenant';
  end if;

  if not public.admin_can_assign_legacy_roles(p_tenant_id, v_role_ids) then
    raise exception 'invalid_or_out_of_scope_role_ids';
  end if;

  perform 1
  from public.roles r
  where r.id = any(v_role_ids)
    and r.tenant_id = p_tenant_id
  order by r.id
  for update;

  if cardinality(v_role_ids) <> (
    select count(*)::integer
    from public.roles r
    where r.id = any(v_role_ids)
      and r.tenant_id = p_tenant_id
  ) then
    raise exception 'invalid_or_out_of_scope_role_ids';
  end if;

  delete from public.membership_roles mr
  where mr.membership_id = v_membership_id;

  insert into public.membership_roles (membership_id, role_id)
  select v_membership_id, requested.role_id
  from unnest(v_role_ids) requested(role_id);
end;
$$;


ALTER FUNCTION "public"."admin_replace_membership_roles"("p_tenant_id" "uuid", "p_target_auth_user_id" "uuid", "p_role_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_replace_membership_roles"("p_tenant_id" "uuid", "p_target_auth_user_id" "uuid", "p_role_ids" "uuid"[]) IS 'Substitui roles legadas de um usuario no tenant; controle restrito a OWNER/ADMIN e role_ids do mesmo tenant.';



CREATE OR REPLACE FUNCTION "public"."admin_save_user_access"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_nome" "text", "p_telefone" "text", "p_usuario_ativo" boolean, "p_tenant_papel" "text", "p_tenant_ativo" boolean, "p_empresa_vinculos" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_target_auth_user_id uuid;
begin
  perform a.assert_admin_hierarchy_locked(
    p_tenant_id,
    p_usuario_id,
    p_tenant_papel,
    true
  );
  select u.auth_user_id
    into v_target_auth_user_id
  from a.usuario u
  where u.id = p_usuario_id;
  perform a.assert_legacy_role_reactivation_scope(
    p_tenant_id,
    v_target_auth_user_id,
    p_usuario_ativo,
    p_tenant_ativo
  );
  perform a.assert_global_user_profile_scope(
    p_tenant_id,
    p_usuario_id,
    true,
    p_nome,
    false,
    null,
    true,
    p_telefone,
    true,
    p_usuario_ativo
  );
  perform public.admin_save_user_access_impl_20260811(
    p_tenant_id,
    p_usuario_id,
    p_nome,
    p_telefone,
    p_usuario_ativo,
    p_tenant_papel,
    p_tenant_ativo,
    p_empresa_vinculos
  );
end;
$$;


ALTER FUNCTION "public"."admin_save_user_access"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_nome" "text", "p_telefone" "text", "p_usuario_ativo" boolean, "p_tenant_papel" "text", "p_tenant_ativo" boolean, "p_empresa_vinculos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_user_access_impl_20260811"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_nome" "text", "p_telefone" "text", "p_usuario_ativo" boolean, "p_tenant_papel" "text", "p_tenant_ativo" boolean, "p_empresa_vinculos" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_papel text;
  v_old_tenant_papel text;
  v_old_tenant_ativo boolean;
  v_item jsonb;
begin
  if not public.admin_can_manage_users(p_tenant_id) then
    raise exception 'not_allowed';
  end if;

  if p_usuario_ativo is null or p_tenant_ativo is null then
    raise exception 'active_flag_required';
  end if;

  if nullif(trim(coalesce(p_nome, '')), '') is null then
    raise exception 'user_name_required';
  end if;

  v_tenant_papel := upper(trim(coalesce(p_tenant_papel, '')));
  if v_tenant_papel not in ('OWNER','ADMIN','DIRETOR','CONTADOR','GESTOR') then
    raise exception 'invalid_tenant_role: %', v_tenant_papel;
  end if;

  perform a.validate_empresa_vinculos_payload(p_tenant_id, p_empresa_vinculos);
  perform a.validate_admin_empresa_scope(p_tenant_id, p_empresa_vinculos);

  perform 1
  from public.tenants t
  where t.id = p_tenant_id
    and t.ativo is true
  for update;
  if not found then
    raise exception 'tenant_not_found_or_inactive';
  end if;

  perform 1
  from a.usuario u
  where u.id = p_usuario_id
    and u.deleted_at is null
  for update;
  if not found then
    raise exception 'user_not_found';
  end if;

  select ut.papel, ut.ativo
    into v_old_tenant_papel, v_old_tenant_ativo
  from a.usuario_tenant ut
  where ut.usuario_id = p_usuario_id
    and ut.tenant_id = p_tenant_id
    and ut.deleted_at is null
  for update;
  if not found then
    raise exception 'user_not_in_tenant';
  end if;

  if (v_tenant_papel = 'OWNER' or v_old_tenant_papel = 'OWNER')
     and not public.admin_is_owner(p_tenant_id) then
    raise exception 'owner_change_requires_owner';
  end if;

  if v_old_tenant_papel = 'OWNER'
     and v_old_tenant_ativo is true
     and (p_usuario_ativo is false or p_tenant_ativo is false or v_tenant_papel <> 'OWNER')
     and not exists (
       select 1
       from a.usuario_tenant other_ut
       join a.usuario other_u on other_u.id = other_ut.usuario_id
       where other_ut.tenant_id = p_tenant_id
         and other_ut.usuario_id <> p_usuario_id
         and other_ut.papel = 'OWNER'
         and other_ut.ativo is true
         and other_ut.deleted_at is null
         and other_u.ativo is true
         and other_u.deleted_at is null
     ) then
    raise exception 'last_active_owner';
  end if;

  update a.usuario
     set nome = trim(p_nome),
         telefone = nullif(regexp_replace(coalesce(p_telefone, ''), '\D', '', 'g'), ''),
         ativo = p_usuario_ativo,
         updated_at = now(),
         updated_by = auth.uid()
   where id = p_usuario_id;

  update a.usuario_tenant
     set papel = v_tenant_papel,
         ativo = p_tenant_ativo,
         updated_at = now(),
         updated_by = auth.uid(),
         deleted_at = null
   where usuario_id = p_usuario_id
     and tenant_id = p_tenant_id
     and deleted_at is null;

  for v_item in select value from jsonb_array_elements(p_empresa_vinculos)
  loop
    insert into a.usuario_empresa (
      id, usuario_id, empresa_id, papel, ativo,
      permissoes_extra, permissoes_negadas,
      created_at, updated_at, created_by, updated_by, deleted_at
    )
    values (
      gen_random_uuid(),
      p_usuario_id,
      (v_item ->> 'empresa_id')::uuid,
      upper(trim(v_item ->> 'papel')),
      (v_item ->> 'ativo')::boolean,
      null,
      null,
      now(),
      now(),
      auth.uid(),
      auth.uid(),
      null
    )
    on conflict (usuario_id, empresa_id) where deleted_at is null
    do update set
      papel = excluded.papel,
      ativo = excluded.ativo,
      updated_at = now(),
      updated_by = auth.uid(),
      deleted_at = null;
  end loop;

  perform a.sync_usuario_access_projection(p_usuario_id);
end;
$$;


ALTER FUNCTION "public"."admin_save_user_access_impl_20260811"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_nome" "text", "p_telefone" "text", "p_usuario_ativo" boolean, "p_tenant_papel" "text", "p_tenant_ativo" boolean, "p_empresa_vinculos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_auth_user_tenant_status"("p_tenant_id" "uuid", "p_target_auth_user_id" "uuid", "p_ativo" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_usuario_id uuid;
  v_papel text;
begin
  if p_ativo is null then
    raise exception 'active_flag_required';
  end if;

  perform 1
  from public.tenants t
  where t.id = p_tenant_id
    and t.ativo is true
  for update;
  if not found then
    raise exception 'tenant_not_found_or_inactive';
  end if;

  select u.id, ut.papel
    into v_usuario_id, v_papel
  from a.usuario u
  join a.usuario_tenant ut on ut.usuario_id = u.id
  where u.auth_user_id = p_target_auth_user_id
    and u.deleted_at is null
    and ut.tenant_id = p_tenant_id
    and ut.deleted_at is null
  for update of u, ut;
  if not found then
    raise exception 'user_not_in_tenant';
  end if;

  perform public.admin_set_user_tenant_role(
    p_tenant_id,
    v_usuario_id,
    v_papel,
    p_ativo
  );
end;
$$;


ALTER FUNCTION "public"."admin_set_auth_user_tenant_status"("p_tenant_id" "uuid", "p_target_auth_user_id" "uuid", "p_ativo" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_user_empresa"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_usuario_id" "uuid", "p_papel" "text", "p_ativo" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_target_auth_user_id uuid;
begin
  perform a.assert_admin_hierarchy_locked(
    p_tenant_id,
    p_usuario_id,
    null,
    true
  );
  select u.auth_user_id
    into v_target_auth_user_id
  from a.usuario u
  where u.id = p_usuario_id;
  perform a.assert_legacy_role_reactivation_scope(
    p_tenant_id,
    v_target_auth_user_id,
    null,
    null
  );
  perform public.admin_set_user_empresa_impl_20260811(
    p_tenant_id,
    p_empresa_id,
    p_usuario_id,
    p_papel,
