CREATE OR REPLACE FUNCTION "public"."admin_set_user_tenant_role"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_papel" "text", "p_ativo" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
