CREATE OR REPLACE FUNCTION "public"."admin_update_user"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_nome" "text", "p_telefone" "text", "p_ativo" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_target_auth_user_id uuid;
begin
  perform a.assert_admin_hierarchy_locked(p_tenant_id, p_usuario_id, null, true);
  select u.auth_user_id
    into v_target_auth_user_id
  from a.usuario u
  where u.id = p_usuario_id;
  perform a.assert_legacy_role_reactivation_scope(
    p_tenant_id,
    v_target_auth_user_id,
    p_ativo,
    null
  );
  perform a.assert_global_user_profile_scope(
    p_tenant_id,
    p_usuario_id,
    true,
    p_nome,
    false,
    null,
    true,
    p_telefone,
    true,
    p_ativo
  );
  perform public.admin_update_user_impl_20260811(
    p_tenant_id,
    p_usuario_id,
    p_nome,
    p_telefone,
    p_ativo
  );
end;
$$;


ALTER FUNCTION "public"."admin_update_user"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_nome" "text", "p_telefone" "text", "p_ativo" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_user_impl_20260811"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_nome" "text", "p_telefone" "text", "p_ativo" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_old_user_ativo boolean;
  v_old_tenant_papel text;
  v_old_tenant_ativo boolean;
begin
  if not public.admin_can_manage_users(p_tenant_id) then
    raise exception 'not_allowed';
  end if;
  if p_ativo is null then
    raise exception 'active_flag_required';
  end if;
  if nullif(trim(coalesce(p_nome, '')), '') is null then
    raise exception 'user_name_required';
  end if;

  perform 1
  from public.tenants t
  where t.id = p_tenant_id
    and t.ativo is true
  for update;
  if not found then
    raise exception 'tenant_not_found_or_inactive';
  end if;

  select u.ativo
    into v_old_user_ativo
  from a.usuario u
  where u.id = p_usuario_id
    and u.deleted_at is null
  for update;
  if not found then
    raise exception 'user_not_found';
  end if;

  select ut.papel, ut.ativo
    into v_old_tenant_papel, v_old_tenant_ativo
  from a.usuario_tenant ut
  where ut.usuario_id = p_usuario_id
    and ut.tenant_id = p_tenant_id
    and ut.deleted_at is null
  for update;
  if not found then
    raise exception 'user_not_in_tenant';
  end if;

  if v_old_tenant_papel = 'OWNER'
     and v_old_tenant_ativo is true
     and v_old_user_ativo is true
     and p_ativo is false then
    if not public.admin_is_owner(p_tenant_id) then
      raise exception 'owner_change_requires_owner';
    end if;

    if not exists (
      select 1
      from a.usuario_tenant other_ut
      join a.usuario other_u on other_u.id = other_ut.usuario_id
      where other_ut.tenant_id = p_tenant_id
        and other_ut.usuario_id <> p_usuario_id
        and other_ut.papel = 'OWNER'
        and other_ut.ativo is true
        and other_ut.deleted_at is null
        and other_u.ativo is true
        and other_u.deleted_at is null
    ) then
      raise exception 'last_active_owner';
    end if;
  end if;

  update a.usuario
     set nome = trim(p_nome),
         telefone = nullif(regexp_replace(coalesce(p_telefone, ''), '\D', '', 'g'), ''),
         ativo = p_ativo,
         updated_at = now(),
         updated_by = auth.uid()
   where id = p_usuario_id
     and deleted_at is null;

  perform a.sync_usuario_access_projection(p_usuario_id);
end;
$$;


ALTER FUNCTION "public"."admin_update_user_impl_20260811"("p_tenant_id" "uuid", "p_usuario_id" "uuid", "p_nome" "text", "p_telefone" "text", "p_ativo" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_buscar_materiais"("p_termo" "text" DEFAULT NULL::"text", "p_fabricante" "text" DEFAULT NULL::"text", "p_limite" integer DEFAULT 100) RETURNS TABLE("item_id" integer, "codigo_interno" "text", "nome" "text", "quantidade_disponivel" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_termo text := nullif(btrim(coalesce(p_termo, '')), '');
  v_fabricante text := nullif(btrim(coalesce(p_fabricante, '')), '');
  v_limite integer := greatest(1, least(coalesce(p_limite, 100), 100));
  v_numerico boolean := coalesce(v_termo ~ '^[0-9]+$', false);
begin
  if v_auth_uid is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  if v_termo is null and v_fabricante is null then
    raise exception 'Informe nome, código ou fabricante para localizar o material.';
  end if;

  return query
  select
    item.id,
    item.codigo_interno::text,
    coalesce(item.nome, item.descricao)::text,
    coalesce(estoque.quantidade_atual, 0)::numeric
  from public.itens as item
  left join public.estoque as estoque
    on estoque.tenant_id = item.tenant_id
   and estoque.empresa_id = item.empresa_id
   and estoque.item_id = item.id
  where item.tenant_id = v_tenant_id
    and item.empresa_id = v_empresa_id
    and item.ativo is true
    and item.tipo = 'produto'
    and item.controla_estoque is true
    and (
      v_termo is null
      or (
        v_numerico
        and (item.id::text = v_termo or item.codigo_interno = v_termo or item.codigo_barras = v_termo)
      )
      or (
        not v_numerico
        and (
          item.nome ilike '%' || v_termo || '%'
          or item.descricao ilike '%' || v_termo || '%'
          or item.codigo_interno ilike '%' || v_termo || '%'
        )
      )
    )
    and (v_fabricante is null or item.fabricante ilike '%' || v_fabricante || '%')
  order by lower(coalesce(item.nome, item.descricao)), item.id
  limit v_limite;
end;
$_$;


ALTER FUNCTION "public"."app_buscar_materiais"("p_termo" "text", "p_fabricante" "text", "p_limite" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."app_buscar_materiais"("p_termo" "text", "p_fabricante" "text", "p_limite" integer) IS 'Busca materiais ativos por nome, código ou fabricante sem expor valores financeiros.';



CREATE OR REPLACE FUNCTION "public"."app_buscar_material_por_codigo"("p_codigo" "text") RETURNS TABLE("item_id" integer, "codigo_interno" "text", "nome" "text", "unidade_medida" "text", "quantidade_disponivel" numeric, "disponivel" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_codigo_normalizado text := upper(regexp_replace(btrim(coalesce(p_codigo, '')), '[[:space:]-]+', '', 'g'));
  v_quantidade_encontrada integer;
begin
  if v_auth_uid is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  if v_codigo_normalizado = '' then
    raise exception 'Informe o código do material.';
  end if;

  select count(*)
    into v_quantidade_encontrada
  from public.itens item
  where item.tenant_id = v_tenant_id
    and item.empresa_id = v_empresa_id
    and item.ativo is true
    and item.tipo = 'produto'
    and item.controla_estoque is true
    and upper(regexp_replace(coalesce(item.codigo_interno, ''), '[[:space:]-]+', '', 'g')) = v_codigo_normalizado;

  if v_quantidade_encontrada > 1 then
    raise exception 'Há mais de um produto ativo com este código. Corrija o cadastro antes de lançar o material.';
  end if;

  return query
  select
    item.id,
    item.codigo_interno::text,
    coalesce(item.nome, item.descricao)::text,
    item.unidade_medida::text,
    coalesce(estoque.quantidade_atual, 0)::numeric,
    coalesce(estoque.quantidade_atual, 0) > 0
  from public.itens item
  left join public.estoque estoque
    on estoque.tenant_id = item.tenant_id
   and estoque.empresa_id = item.empresa_id
   and estoque.item_id = item.id
  where item.tenant_id = v_tenant_id
    and item.empresa_id = v_empresa_id
    and item.ativo is true
    and item.tipo = 'produto'
    and item.controla_estoque is true
    and upper(regexp_replace(coalesce(item.codigo_interno, ''), '[[:space:]-]+', '', 'g')) = v_codigo_normalizado;
end;
$$;


