CREATE OR REPLACE FUNCTION "public"."app_criar_notificacao"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_usuario_id" "uuid", "p_tipo" "text", "p_titulo" "text", "p_corpo" "text", "p_dados" "jsonb" DEFAULT '{}'::"jsonb", "p_agrupamento_chave" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_id uuid;
  v_quantidade integer;
  v_titulo text;
  v_corpo text;
begin
  if p_usuario_id is null
     or p_tenant_id is null
     or p_empresa_id is null
     or p_tipo not in (
       'hora_pendente', 'hora_aprovada_automaticamente', 'hora_rejeitada',
       'os_concluida', 'os_faturada', 'os_concluida_garantia',
       'material_lancado', 'os_reaberta'
     ) then
    return null;
  end if;

  -- O destinatario precisa continuar ativo exatamente no contexto do evento.
  if not exists (
    select 1
    from public.empresa_memberships em
    where em.tenant_id = p_tenant_id
      and em.empresa_id = p_empresa_id
      and em.user_id = p_usuario_id
      and em.status = 'active'
  ) then
    return null;
  end if;

  if exists (
    select 1
    from public.app_notificacoes_preferencias pref
    where pref.tenant_id = p_tenant_id
      and pref.empresa_id = p_empresa_id
      and pref.usuario_id = p_usuario_id
      and pref.tipo = p_tipo
      and not pref.habilitada
  ) then
    return null;
  end if;

  if p_agrupamento_chave is not null then
    update public.app_notificacoes notificacao
       set quantidade = notificacao.quantidade + 1,
           atualizado_em = now(),
           dados = coalesce(p_dados, '{}'::jsonb) || jsonb_build_object('agrupada', true)
     where notificacao.tenant_id = p_tenant_id
       and notificacao.empresa_id = p_empresa_id
       and notificacao.usuario_id = p_usuario_id
       and notificacao.tipo = p_tipo
       and notificacao.agrupamento_chave = p_agrupamento_chave
       and notificacao.lida_em is null
     returning notificacao.id, notificacao.quantidade into v_id, v_quantidade;

    if found then
      v_titulo := case p_tipo
        when 'hora_pendente' then format('%s horas pendentes de aprovaçao', v_quantidade)
        when 'material_lancado' then format('%s materiais lançados em OS', v_quantidade)
        when 'os_concluida' then format('%s OS concluídas aguardando faturamento', v_quantidade)
        when 'os_faturada' then format('%s OS faturadas', v_quantidade)
        when 'os_concluida_garantia' then format('%s atendimentos de garantia concluídos', v_quantidade)
        when 'os_reaberta' then format('%s OS reabertas', v_quantidade)
        else format('%s novas notificações', v_quantidade)
      end;
      v_corpo := 'Abra a central de notificações para ver os detalhes.';
      update public.app_notificacoes
         set titulo = v_titulo,
             corpo = v_corpo,
             dados = dados || jsonb_build_object('url', '/notificacoes', 'quantidade', v_quantidade)
       where id = v_id;

      -- Um novo evento precisa voltar para a fila mesmo se a versao anterior
      -- ja havia sido enviada ao mesmo aparelho.
      update public.app_notificacoes_push_entregas
         set status = 'pendente', tentativas = 0, erro = null, enviado_em = null, atualizado_em = now()
       where notificacao_id = v_id;
      return v_id;
    end if;
  end if;

  insert into public.app_notificacoes (
    tenant_id, empresa_id, usuario_id, tipo, titulo, corpo, dados, agrupamento_chave
  ) values (
    p_tenant_id, p_empresa_id, p_usuario_id, p_tipo, p_titulo, p_corpo,
    coalesce(p_dados, '{}'::jsonb), p_agrupamento_chave
  ) returning id into v_id;

  insert into public.app_notificacoes_push_entregas (notificacao_id, dispositivo_id)
  select v_id, dispositivo.id
  from public.app_dispositivos_push dispositivo
  where dispositivo.tenant_id = p_tenant_id
    and dispositivo.empresa_id = p_empresa_id
    and dispositivo.usuario_id = p_usuario_id
    and dispositivo.ativo;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."app_criar_notificacao"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_usuario_id" "uuid", "p_tipo" "text", "p_titulo" "text", "p_corpo" "text", "p_dados" "jsonb", "p_agrupamento_chave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_criar_os_hh"("p_cliente_id" integer, "p_descricao_servico" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_papel_empresa text;
  v_cliente_nome character varying;
  v_cliente_ativo boolean;
  v_cliente_habilita_hh boolean;
  v_os_id integer;
  v_os_num bigint;
  v_numero_os text;
  v_criado_por text;
begin
  if v_auth_uid is null then
    return jsonb_build_object(
      'sucesso', false,
      'os_id', null,
      'numero_os', null,
      'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo', 'autenticacao', 'mensagem', 'Autenticação obrigatória para criar OS HH.'))
    );
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    return jsonb_build_object(
      'sucesso', false,
      'os_id', null,
      'numero_os', null,
      'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo', 'contexto', 'mensagem', 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.'))
    );
  end if;

  select usuario_empresa.papel
    into v_papel_empresa
  from a.usuario as usuario
  join a.usuario_empresa as usuario_empresa
    on usuario_empresa.usuario_id = usuario.id
   and usuario_empresa.empresa_id = v_empresa_id
   and usuario_empresa.ativo is true
   and usuario_empresa.deleted_at is null
  where usuario.auth_user_id = v_auth_uid
    and usuario.ativo is true
    and usuario.deleted_at is null
  limit 1;

  if v_papel_empresa is null then
    return jsonb_build_object(
      'sucesso', false,
      'os_id', null,
      'numero_os', null,
      'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo', 'permissao', 'mensagem', 'Não foi possível identificar seu papel na empresa atual.'))
    );
  end if;

  if upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') then
    return jsonb_build_object(
      'sucesso', false,
      'os_id', null,
      'numero_os', null,
      'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo', 'permissao', 'mensagem', 'O papel APONTADOR não pode criar OS.'))
    );
  end if;

  select cliente.nome, cliente.ativo, cliente.habilita_hh
    into v_cliente_nome, v_cliente_ativo, v_cliente_habilita_hh
  from public.clientes as cliente
  where cliente.id = p_cliente_id
    and cliente.tenant_id = v_tenant_id
    and cliente.empresa_id = v_empresa_id;

  if v_cliente_nome is null then
    return jsonb_build_object(
      'sucesso', false,
      'os_id', null,
      'numero_os', null,
      'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo', 'cliente', 'mensagem', 'O cliente informado não existe ou não pertence à empresa atual.'))
    );
  end if;

  if coalesce(v_cliente_ativo, false) is false then
    return jsonb_build_object(
      'sucesso', false,
      'os_id', null,
      'numero_os', null,
      'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo', 'cliente_inativo', 'mensagem', 'O cliente informado está inativo.'))
    );
  end if;

  if coalesce(v_cliente_habilita_hh, false) is false then
    return jsonb_build_object(
      'sucesso', false,
      'os_id', null,
      'numero_os', null,
      'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo', 'cliente_hh', 'mensagem', 'O cliente informado não está habilitado para HH.'))
    );
  end if;

  v_os_num := nextval('public.ordens_servico_os_num_seq');
  v_numero_os := v_os_num::text;
  v_criado_por := coalesce(nullif(auth.jwt() ->> 'email', ''), v_auth_uid::text);

  begin
    insert into public.ordens_servico (
      tenant_id,
      empresa_id,
      os_num,
      numero_os,
      cliente_id,
      cliente_nome,
      descricao_servico,
      tipo_pedido,
      orcado,
      tem_gestao,
      usa_relatorio_hh,
      is_fiado,
      status,
      criado_por,
      responsavel_aprovacao_id
    ) values (
      v_tenant_id,
      v_empresa_id,
      v_os_num,
      v_numero_os,
      p_cliente_id,
      v_cliente_nome,
      nullif(upper(btrim(p_descricao_servico)), ''),
      'servico',
      0,
      false,
      true,
      false,
      'em_andamento',
      v_criado_por,
      v_auth_uid
    )
    returning id into v_os_id;
  exception
    when unique_violation then
      return jsonb_build_object(
        'sucesso', false,
        'os_id', null,
        'numero_os', null,
        'avisos', '[]'::jsonb,
        'erros', jsonb_build_array(jsonb_build_object('tipo', 'numeracao', 'mensagem', 'Não foi possível reservar uma numeração única para a OS. Tente novamente.'))
      );
  end;

  return jsonb_build_object(
    'sucesso', true,
    'os_id', v_os_id,
    'numero_os', v_numero_os,
    'avisos', '[]'::jsonb,
    'erros', '[]'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."app_criar_os_hh"("p_cliente_id" integer, "p_descricao_servico" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_definir_preferencia_notificacao"("p_tipo" "text", "p_habilitada" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
begin
  if not public.app_notificacao_contexto_valido() then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;
  if p_tipo not in (
    'hora_pendente', 'hora_aprovada_automaticamente', 'hora_rejeitada',
    'os_concluida', 'os_faturada', 'os_concluida_garantia', 'material_lancado', 'os_reaberta'
  ) then
    raise exception 'Tipo de notificação inválido.';
  end if;
  insert into public.app_notificacoes_preferencias (tenant_id, empresa_id, usuario_id, tipo, habilitada)
  values (public.current_tenant_id(), public.current_empresa_id(), auth.uid(), p_tipo, p_habilitada)
  on conflict (tenant_id, empresa_id, usuario_id, tipo) do update
    set habilitada = excluded.habilitada, atualizado_em = now();
end;
$$;


ALTER FUNCTION "public"."app_definir_preferencia_notificacao"("p_tipo" "text", "p_habilitada" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_desativar_dispositivo_push"("p_expo_push_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
begin
  if not public.app_notificacao_contexto_valido() then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;
  update public.app_dispositivos_push
     set ativo = false, atualizado_em = now()
   where expo_push_token = nullif(btrim(p_expo_push_token), '')
     and tenant_id = public.current_tenant_id()
     and empresa_id = public.current_empresa_id()
     and usuario_id = auth.uid();
end;
$$;


ALTER FUNCTION "public"."app_desativar_dispositivo_push"("p_expo_push_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_editar_apontamento"("p_apontamento_id" "uuid", "p_horas" numeric, "p_tipo_hora_id" "uuid", "p_descricao" "text" DEFAULT NULL::"text", "p_confirmar_avisos" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_colaborador_proprio_id uuid;
  v_papel text;
  v_colaborador_id uuid;
  v_os_id integer;
  v_data date;
  v_gerado_por_hh boolean;
  v_tipo_existe boolean;
begin
  if v_auth_uid is null or v_tenant_id is null or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar autenticação, tenant e empresa ativos.';
  end if;
  if p_horas is null or p_horas <= 0 or p_horas > 24 then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo','horas','mensagem','Informe uma quantidade de horas entre 0 e 24.')));
  end if;
  select id into v_colaborador_proprio_id from public.colaboradores
  where user_id=v_auth_uid and tenant_id=v_tenant_id and empresa_id=v_empresa_id and ativo;
  if v_colaborador_proprio_id is null then raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.'; end if;
  select ue.papel into v_papel from a.usuario u join a.usuario_empresa ue on ue.usuario_id=u.id
  where u.auth_user_id=v_auth_uid and u.ativo and u.deleted_at is null and ue.empresa_id=v_empresa_id and ue.ativo and ue.deleted_at is null limit 1;
  select ah.colaborador_id, ah.os_id, ah.data, ah.gerado_por_hh
    into v_colaborador_id, v_os_id, v_data, v_gerado_por_hh
  from public.apontamentos_horas ah
  where ah.id=p_apontamento_id and ah.tenant_id=v_tenant_id and ah.empresa_id=v_empresa_id;
  if not found then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo','apontamento','mensagem','O apontamento informado não existe ou não pertence à empresa atual.')));
  end if;
  if coalesce(v_gerado_por_hh,false) then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo','hh','mensagem','Este apontamento é um espelho de HH e deve ser alterado no módulo HH.')));
  end if;
  if upper(coalesce(v_papel,'')) in ('APONTAMENTO_RH', 'APONTADOR') and v_colaborador_id <> v_colaborador_proprio_id then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo','permissao','mensagem','O perfil APONTADOR só pode editar o próprio apontamento.')));
  end if;
  select exists(select 1 from public.tipos_horas th where th.id=p_tipo_hora_id and th.tenant_id=v_tenant_id and th.ativo) into v_tipo_existe;
  if not v_tipo_existe then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo','tipo_hora','mensagem','O tipo de hora informado não existe ou está inativo.')));
  end if;
  if exists (
    select 1 from public.apontamentos_horas ah
    where ah.id <> p_apontamento_id and ah.tenant_id=v_tenant_id and ah.empresa_id=v_empresa_id
      and ah.os_id=v_os_id and ah.colaborador_id=v_colaborador_id and ah.data=v_data
      and ah.tipo_hora_id=p_tipo_hora_id and not coalesce(ah.gerado_por_hh,false)
  ) then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'avisos', '[]'::jsonb,
      'erros', jsonb_build_array(jsonb_build_object('tipo','duplicidade','mensagem','Já existe outro apontamento para esta OS, colaborador, data e tipo de hora.')));
  end if;
  update public.apontamentos_horas
  set horas=p_horas, tipo_hora_id=p_tipo_hora_id, descricao=nullif(btrim(p_descricao),'')
  where id=p_apontamento_id and tenant_id=v_tenant_id and empresa_id=v_empresa_id;
  return jsonb_build_object('sucesso', true, 'gravados', 1, 'avisos', '[]'::jsonb, 'erros', '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."app_editar_apontamento"("p_apontamento_id" "uuid", "p_horas" numeric, "p_tipo_hora_id" "uuid", "p_descricao" "text", "p_confirmar_avisos" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_excluir_apontamento"("p_apontamento_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_colaborador_proprio_id uuid;
  v_papel_empresa text;
  v_colaborador_id uuid;
  v_status text;
  v_gerado_por_hh boolean;
  v_erros jsonb := '[]'::jsonb;
  v_avisos jsonb := '[]'::jsonb;
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para excluir apontamentos.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();
  if v_tenant_id is null or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  select ue.papel into v_papel_empresa
  from a.usuario u
  join a.usuario_empresa ue
    on ue.usuario_id = u.id
   and ue.empresa_id = v_empresa_id
   and ue.ativo is true
   and ue.deleted_at is null
  where u.auth_user_id = v_auth_uid
    and u.ativo is true
    and u.deleted_at is null
  limit 1;
  if v_papel_empresa is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa atual.';
  end if;

  if upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') then
    select c.id into v_colaborador_proprio_id
    from public.colaboradores c
    where c.user_id = v_auth_uid
      and c.tenant_id = v_tenant_id
      and c.empresa_id = v_empresa_id
      and c.ativo is true;
    if v_colaborador_proprio_id is null then
      raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
    end if;
  end if;

  select ah.colaborador_id, ah.status, ah.gerado_por_hh
    into v_colaborador_id, v_status, v_gerado_por_hh
  from public.apontamentos_horas ah
  where ah.id = p_apontamento_id
    and ah.tenant_id = v_tenant_id
    and ah.empresa_id = v_empresa_id;
  if not found then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'avisos', v_avisos, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'apontamento', 'mensagem', 'O apontamento informado não existe ou não pertence à empresa atual.')));
  end if;

  if coalesce(v_gerado_por_hh, false) then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'hh', 'mensagem', 'Este apontamento é um espelho de HH e deve ser excluído no módulo HH.'));
  elsif lower(coalesce(v_status, '')) = 'fechado' then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'status', 'mensagem', 'Este apontamento está fechado e não pode ser excluído.'));
  elsif lower(coalesce(v_status, '')) = 'aprovado' then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'status', 'mensagem', 'Este apontamento está aprovado e não pode ser excluído.'));
  end if;

  if upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') and v_colaborador_id <> v_colaborador_proprio_id then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'permissao', 'mensagem', 'O perfil APONTADOR só pode excluir o próprio apontamento.'));
  end if;

  if jsonb_array_length(v_erros) > 0 then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'avisos', v_avisos, 'erros', v_erros);
  end if;

  delete from public.apontamentos_horas
  where id = p_apontamento_id
    and tenant_id = v_tenant_id
    and empresa_id = v_empresa_id;

  return jsonb_build_object('sucesso', true, 'gravados', 1, 'avisos', v_avisos, 'erros', v_erros);
end;
$$;


ALTER FUNCTION "public"."app_excluir_apontamento"("p_apontamento_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_lancar_apontamentos_lote"("p_os_id" integer, "p_data" "date", "p_tipo_hora_id" "uuid", "p_lancamentos" "jsonb", "p_descricao" "text" DEFAULT NULL::"text", "p_confirmar_avisos" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
begin
  perform public.assert_documento_operacional_os(p_os_id);
  return public.app_lancar_apontamentos_lote_unfiltered_ov_20260829(
    p_os_id, p_data, p_tipo_hora_id, p_lancamentos, p_descricao, p_confirmar_avisos
  );
end;
$$;


ALTER FUNCTION "public"."app_lancar_apontamentos_lote"("p_os_id" integer, "p_data" "date", "p_tipo_hora_id" "uuid", "p_lancamentos" "jsonb", "p_descricao" "text", "p_confirmar_avisos" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_lancar_apontamentos_lote_unfiltered_ov_20260829"("p_os_id" integer, "p_data" "date", "p_tipo_hora_id" "uuid", "p_lancamentos" "jsonb", "p_descricao" "text" DEFAULT NULL::"text", "p_confirmar_avisos" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_colaborador_proprio_id uuid;
  v_papel_empresa text;
  v_os_status text;
  v_os_hh boolean;
  v_tipo_nome text;
  v_descricao text := nullif(btrim(p_descricao), '');
  v_erros jsonb := '[]'::jsonb;
  v_avisos jsonb := '[]'::jsonb;
  v_item jsonb;
  v_colaborador_id uuid;
  v_horas numeric;
  v_colaborador_ids uuid[] := '{}'::uuid[];
  v_horas_lancadas numeric[] := '{}'::numeric[];
  v_nomes_colaboradores text[] := '{}'::text[];
  v_nome_colaborador text;
  v_colaborador_ativo boolean;
  v_total_dia numeric;
  v_duplicidades text;
  v_indice integer;
  v_gravados integer;
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para lançar apontamentos.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();
  if v_tenant_id is null or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  select c.id into v_colaborador_proprio_id
  from public.colaboradores c
  where c.user_id = v_auth_uid and c.tenant_id = v_tenant_id
    and c.empresa_id = v_empresa_id and c.ativo is true;
  if v_colaborador_proprio_id is null then
    raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
  end if;

  select ue.papel into v_papel_empresa
  from a.usuario u
  join a.usuario_empresa ue on ue.usuario_id = u.id
    and ue.empresa_id = v_empresa_id and ue.ativo is true and ue.deleted_at is null
  where u.auth_user_id = v_auth_uid and u.ativo is true and u.deleted_at is null
  limit 1;
  if v_papel_empresa is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa atual.';
  end if;

  if not public.app_papel_pode_lancar_horas(v_papel_empresa) then
    raise exception 'Seu perfil não tem permissão para lançar horas na OS.';
  end if;

  if p_data is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','data','mensagem','Informe a data do apontamento.'));
  elsif p_data > current_date then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','data_futura','mensagem','Não é permitido lançar apontamentos em data futura.'));
  end if;

  select os.status, coalesce(os.usa_relatorio_hh, false) into v_os_status, v_os_hh
  from public.ordens_servico os
  where os.id = p_os_id and os.tenant_id = v_tenant_id and os.empresa_id = v_empresa_id;
  if not found then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','os','mensagem','A OS informada não existe ou não pertence à empresa atual.'));
  elsif lower(v_os_status) = 'cancelada' then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','os_cancelada','mensagem','Não é permitido lançar apontamentos em uma OS cancelada.'));
  elsif v_os_hh then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','os_hh','mensagem','Esta é uma OS de HH. Use o lançamento por horários, que será disponibilizado em uma função própria.'));
  elsif lower(v_os_status) = 'concluida' and v_descricao is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','descricao_garantia','mensagem','Informe a descrição do serviço para lançar horas em uma OS concluída (garantia).'));
  end if;

  select th.descricao into v_tipo_nome
  from public.tipos_horas th
  where th.id = p_tipo_hora_id and th.tenant_id = v_tenant_id and th.ativo is true;
  if v_tipo_nome is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','tipo_hora','mensagem','O tipo de hora informado não existe ou está inativo.'));
  elsif lower(v_tipo_nome) ~ '(espera|improdutiv|parada|deslocamento)' and v_descricao is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','descricao_obrigatoria','mensagem',format('Informe a descrição para o tipo de hora "%s".', v_tipo_nome)));
  end if;

  if p_lancamentos is null or jsonb_typeof(p_lancamentos) <> 'array' then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','lancamentos','mensagem','Envie uma lista de lançamentos válida.'));
  elsif jsonb_array_length(p_lancamentos) = 0 then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','lancamentos','mensagem','Informe ao menos um colaborador para o lançamento.'));
  else
    for v_item in select value from jsonb_array_elements(p_lancamentos) loop
      if jsonb_typeof(v_item) <> 'object' then
        v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','lancamentos','mensagem','Cada lançamento deve informar colaborador e horas.'));
        continue;
      end if;
      begin v_colaborador_id := nullif(v_item ->> 'colaborador_id', '')::uuid; exception when others then v_colaborador_id := null; end;
      begin v_horas := (v_item ->> 'horas')::numeric; exception when others then v_horas := null; end;
      if v_colaborador_id is null then
        v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','colaborador','mensagem','Há um lançamento sem um colaborador válido.'));
        continue;
      end if;
      if v_horas is null or v_horas <= 0 or v_horas > 24 then
        v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','horas','mensagem',format('Informe entre 0 e 24 horas para o colaborador %s.', v_colaborador_id)));
        continue;
      end if;
      if v_colaborador_id = any(v_colaborador_ids) then
        v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','lote_duplicado','mensagem',format('O colaborador %s foi informado mais de uma vez no mesmo lote.', v_colaborador_id)));
        continue;
      end if;
      v_colaborador_ids := array_append(v_colaborador_ids, v_colaborador_id);
      v_horas_lancadas := array_append(v_horas_lancadas, v_horas);
    end loop;
  end if;

  if jsonb_array_length(v_erros) > 0 then
    return jsonb_build_object('sucesso',false,'gravados',0,'avisos',v_avisos,'erros',v_erros);
  end if;

  for v_indice in array_lower(v_colaborador_ids, 1)..array_upper(v_colaborador_ids, 1) loop
    select c.nome, c.ativo into v_nome_colaborador, v_colaborador_ativo
    from public.colaboradores c
    where c.id = v_colaborador_ids[v_indice] and c.tenant_id = v_tenant_id and c.empresa_id = v_empresa_id;
    if not found then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','colaborador','mensagem',format('O colaborador %s não pertence à empresa atual.',v_colaborador_ids[v_indice])));
      v_nomes_colaboradores := array_append(v_nomes_colaboradores,v_colaborador_ids[v_indice]::text);
    elsif not v_colaborador_ativo then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','colaborador_inativo','mensagem',format('O colaborador %s está inativo e não pode receber apontamentos.',v_nome_colaborador)));
      v_nomes_colaboradores := array_append(v_nomes_colaboradores,v_nome_colaborador);
    elsif not exists (
      select 1 from public.colaborador_taxas taxa
      where taxa.colaborador_id = v_colaborador_ids[v_indice]
        and p_data >= taxa.vigencia_inicio
        and (taxa.vigencia_fim is null or p_data <= taxa.vigencia_fim)
    ) then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object(
        'tipo','taxa_vigente',
        'mensagem',format('O colaborador %s não possui taxa vigente em %s. Cadastre a taxa no sistema web antes de lançar horas.',v_nome_colaborador,to_char(p_data,'DD/MM/YYYY'))
      ));
      v_nomes_colaboradores := array_append(v_nomes_colaboradores,v_nome_colaborador);
    elsif upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') and v_colaborador_ids[v_indice] <> v_colaborador_proprio_id then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','colaborador','mensagem','O perfil APONTADOR só pode lançar horas para o próprio colaborador vinculado.'));
      v_nomes_colaboradores := array_append(v_nomes_colaboradores,v_nome_colaborador);
    else
      v_nomes_colaboradores := array_append(v_nomes_colaboradores,v_nome_colaborador);
    end if;
  end loop;

  if jsonb_array_length(v_erros) > 0 then
    return jsonb_build_object('sucesso',false,'gravados',0,'avisos',v_avisos,'erros',v_erros);
  end if;

  select string_agg(format('%s (%s h)', c.nome, ah.horas::text), '; ' order by c.nome) into v_duplicidades
  from public.apontamentos_horas ah
  join public.colaboradores c on c.id = ah.colaborador_id
  where ah.tenant_id = v_tenant_id and ah.empresa_id = v_empresa_id
    and ah.os_id = p_os_id and ah.data = p_data and ah.tipo_hora_id = p_tipo_hora_id
    and ah.gerado_por_hh is false and ah.colaborador_id = any(v_colaborador_ids);
  if v_duplicidades is not null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo','duplicidade','mensagem',format('Já existe lançamento nesta OS, data e tipo de hora para: %s. Edite o lançamento existente em vez de criar outro.',v_duplicidades)));
    return jsonb_build_object('sucesso',false,'gravados',0,'avisos',v_avisos,'erros',v_erros);
  end if;

  if p_data < current_date - 7 then
    v_avisos := v_avisos || jsonb_build_array(jsonb_build_object('tipo','retroativo','mensagem',format('Este apontamento é retroativo: a data %s tem mais de 7 dias.',to_char(p_data,'DD/MM/YYYY'))));
  end if;
  for v_indice in array_lower(v_colaborador_ids, 1)..array_upper(v_colaborador_ids, 1) loop
    select coalesce(sum(ah.horas),0) into v_total_dia
    from public.apontamentos_horas ah
    where ah.tenant_id = v_tenant_id and ah.empresa_id = v_empresa_id
      and ah.colaborador_id = v_colaborador_ids[v_indice] and ah.data = p_data;
    v_total_dia := v_total_dia + v_horas_lancadas[v_indice];
    if v_total_dia > 9 then
      v_avisos := v_avisos || jsonb_build_array(jsonb_build_object('tipo','jornada_maior_que_9h','mensagem',format('%s ficará com %s h apontadas em %s. Verifique se o intervalo de almoço foi descontado.',v_nomes_colaboradores[v_indice],v_total_dia::text,to_char(p_data,'DD/MM/YYYY'))));
    end if;
  end loop;
  if jsonb_array_length(v_avisos) > 0 and not p_confirmar_avisos then
    return jsonb_build_object('sucesso',false,'gravados',0,'avisos',v_avisos,'erros',v_erros);
  end if;

  if lower(v_os_status) = 'concluida' then
    perform set_config('app.permitir_lancamento_garantia','true',true);
  end if;
  insert into public.apontamentos_horas (
    os_id,colaborador_id,data,horas,tipo_hora_id,descricao,status,tenant_id,empresa_id,gerado_por_hh,criado_por_user_id
  )
  select p_os_id,v_colaborador_ids[indice],p_data,v_horas_lancadas[indice],p_tipo_hora_id,v_descricao,
         'lancado',v_tenant_id,v_empresa_id,false,v_auth_uid
  from generate_subscripts(v_colaborador_ids,1) indice;
  get diagnostics v_gravados = row_count;
  return jsonb_build_object('sucesso',true,'gravados',v_gravados,'avisos',v_avisos,'erros',v_erros);
end;
$$;


ALTER FUNCTION "public"."app_lancar_apontamentos_lote_unfiltered_ov_20260829"("p_os_id" integer, "p_data" "date", "p_tipo_hora_id" "uuid", "p_lancamentos" "jsonb", "p_descricao" "text", "p_confirmar_avisos" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_lancar_hh"("p_os_id" integer, "p_colaborador_id" "uuid", "p_data" "date", "p_hh_servico_id" bigint, "p_entrada_1" time without time zone, "p_saida_1" time without time zone, "p_entrada_2" time without time zone DEFAULT NULL::time without time zone, "p_saida_2" time without time zone DEFAULT NULL::time without time zone, "p_percentual_manual" smallint DEFAULT NULL::smallint, "p_horas_extra_50" numeric DEFAULT 0, "p_horas_extra_100" numeric DEFAULT 0, "p_observacao" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_papel_empresa text;
  v_colaborador_proprio_id uuid;
  v_cliente_id bigint;
  v_os_status text;
  v_colaborador_nome text;
  v_percentual smallint;
  v_codigo_tipo text;
  v_hh_tipo_id bigint;
  v_preco_aplicavel numeric;
  v_horas_efetivas numeric(10,2);
  v_horas_extra_50 numeric(10,2) := coalesce(p_horas_extra_50, 0);
  v_horas_extra_100 numeric(10,2) := coalesce(p_horas_extra_100, 0);
  v_conflito text;
  v_lancamento_id bigint;
  v_erros jsonb := '[]'::jsonb;
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para lançar HH.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();
  if v_tenant_id is null or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  select ue.papel into v_papel_empresa
  from a.usuario u
  join a.usuario_empresa ue
    on ue.usuario_id = u.id
   and ue.empresa_id = v_empresa_id
   and ue.ativo is true
   and ue.deleted_at is null
  where u.auth_user_id = v_auth_uid
    and u.ativo is true
    and u.deleted_at is null
  limit 1;
  if v_papel_empresa is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa atual.';
  end if;

  if not public.app_papel_pode_lancar_horas(v_papel_empresa) then
    raise exception 'Seu perfil não tem permissão para lançar horas na OS.';
  end if;

  if upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') then
    select colaborador.id into v_colaborador_proprio_id
    from public.colaboradores colaborador
    where colaborador.user_id = v_auth_uid
      and colaborador.tenant_id = v_tenant_id
      and colaborador.empresa_id = v_empresa_id
      and colaborador.ativo is true;
    if v_colaborador_proprio_id is null then
      raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
    end if;
    if p_colaborador_id is distinct from v_colaborador_proprio_id then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'permissao', 'mensagem', 'O perfil APONTADOR só pode lançar HH para o próprio colaborador vinculado.'));
    end if;
  end if;

  if p_data is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'data', 'mensagem', 'Informe a data do lançamento HH.'));
  elsif p_data > current_date then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'data_futura', 'mensagem', 'Não é permitido lançar HH em data futura.'));
  end if;

  select os.cliente_id, os.status into v_cliente_id, v_os_status
  from public.ordens_servico os
  where os.id = p_os_id
    and os.tenant_id = v_tenant_id
    and os.empresa_id = v_empresa_id
    and coalesce(os.usa_relatorio_hh, false) is true;
  if not found then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'os', 'mensagem', 'A OS informada não existe, não pertence à empresa atual ou não é uma OS HH.'));
  elsif lower(coalesce(v_os_status, '')) <> 'em_andamento' then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'os_status', 'mensagem', 'Só é permitido lançar HH em OS com status em andamento.'));
  elsif v_cliente_id is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'cliente', 'mensagem', 'A OS HH não possui cliente identificado.'));
  end if;

  select colaborador.nome into v_colaborador_nome
  from public.colaboradores colaborador
  where colaborador.id = p_colaborador_id
    and colaborador.tenant_id = v_tenant_id
    and colaborador.empresa_id = v_empresa_id
    and colaborador.ativo is true;
  if v_colaborador_nome is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'colaborador', 'mensagem', 'O colaborador informado não existe, está inativo ou não pertence à empresa atual.'));
  end if;

  if p_entrada_1 is null or p_saida_1 is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'Informe entrada e saída do primeiro período.'));
  elsif p_entrada_1 >= p_saida_1 then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'A entrada do primeiro período deve ser anterior à saída.'));
  end if;

  if (p_entrada_2 is null) <> (p_saida_2 is null) then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'Informe entrada e saída do segundo período ou deixe ambos vazios.'));
  elsif p_entrada_2 is not null and p_saida_2 is not null then
    if p_entrada_2 >= p_saida_2 then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'A entrada do segundo período deve ser anterior à saída.'));
    elsif p_saida_1 is not null and p_saida_1 > p_entrada_2 then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'O segundo período não pode sobrepor o primeiro.'));
    end if;
  end if;

  if v_horas_extra_50 < 0 or v_horas_extra_100 < 0 then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'extras', 'mensagem', 'As horas extras não podem ser negativas.'));
  end if;

  if p_percentual_manual is not null and p_percentual_manual not in (0, 50, 100) then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'percentual', 'mensagem', 'O tipo HH manual deve ser normal, extra 50% ou extra 100%.'));
  end if;

  if jsonb_array_length(v_erros) > 0 then
    return jsonb_build_object('sucesso', false, 'lancamento_id', null, 'horas', null, 'erros', v_erros);
  end if;

  v_horas_efetivas := round(
    extract(epoch from (p_saida_1 - p_entrada_1)) / 3600
    + case when p_entrada_2 is not null then extract(epoch from (p_saida_2 - p_entrada_2)) / 3600 else 0 end,
    2
  );
  if v_horas_efetivas <= 0 then
    return jsonb_build_object('sucesso', false, 'lancamento_id', null, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'Os horários informados não resultam em horas trabalhadas válidas.')));
  end if;
  if v_horas_extra_50 + v_horas_extra_100 > v_horas_efetivas then
    return jsonb_build_object('sucesso', false, 'lancamento_id', null, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'extras', 'mensagem', 'A soma das horas extras não pode ultrapassar as horas efetivamente trabalhadas.')));
  end if;

  if p_percentual_manual is not null then
    v_percentual := p_percentual_manual;
  elsif extract(dow from p_data) = 0 then
    v_percentual := 100;
  elsif extract(dow from p_data) = 6 then
    v_percentual := 50;
  else
    v_percentual := 0;
  end if;
  v_codigo_tipo := case v_percentual when 50 then 'EXTRA_50' when 100 then 'EXTRA_100' else 'NORMAL' end;

  select hm.hh_tipo_id into v_hh_tipo_id
  from public.hh_tipos_mapping hm
  join public.tipos_horas th on th.id = hm.tipo_hora_id
  where hm.tenant_id = v_tenant_id
    and hm.ativo is true
    and th.tenant_id = v_tenant_id
    and th.ativo is true
    and th.codigo = v_codigo_tipo
  limit 1;
  if v_hh_tipo_id is null then
    return jsonb_build_object('sucesso', false, 'lancamento_id', null, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'configuracao_hh', 'mensagem', 'Não existe configuração ativa para o tipo HH desta data.')));
  end if;

  if not exists (
    select 1
    from public.cliente_hh_tabelas tabela
    where tabela.tenant_id = v_tenant_id
      and tabela.empresa_id = v_empresa_id
      and tabela.cliente_id = v_cliente_id
      and tabela.ativo is true
      and p_data between tabela.vigencia_inicio and tabela.vigencia_fim
  ) then
    return jsonb_build_object('sucesso', false, 'lancamento_id', null, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'tabela_hh', 'mensagem', 'Não há tabela HH ativa e vigente para este cliente na data informada.')));
  end if;

  select case v_percentual
           when 50 then servico.preco_50
           when 100 then servico.preco_100
           else servico.preco_base
         end
    into v_preco_aplicavel
  from public.cliente_hh_servicos servico
  where servico.id = p_hh_servico_id
    and servico.tenant_id = v_tenant_id
    and servico.empresa_id = v_empresa_id
    and servico.cliente_id = v_cliente_id
    and servico.ativo is true
    and exists (
      select 1
      from public.colaborador_cliente_funcao vinculo
      where vinculo.tenant_id = v_tenant_id
        and vinculo.empresa_id = v_empresa_id
        and vinculo.cliente_id = v_cliente_id
        and vinculo.colaborador_id = p_colaborador_id
        and vinculo.hh_servico_id = servico.id
        and vinculo.ativo is true
    );
  if v_preco_aplicavel is null then
    return jsonb_build_object('sucesso', false, 'lancamento_id', null, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'especialidade', 'mensagem', 'A especialidade não está ativa ou não possui vínculo ativo para este colaborador e cliente.')));
  end if;
  if v_preco_aplicavel <= 0 then
    return jsonb_build_object('sucesso', false, 'lancamento_id', null, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'preco_hh', 'mensagem', 'A especialidade não possui preço HH válido para o tipo de dia informado. Ajuste a configuração no sistema web.')));
  end if;

  select format('OS %s, %s-%s', coalesce(os.numero_os, hl.os_id::text), to_char(intervalo.inicio, 'HH24:MI'), to_char(intervalo.fim, 'HH24:MI'))
    into v_conflito
  from public.hh_lancamentos hl
  join public.ordens_servico os
    on os.id = hl.os_id
   and os.tenant_id = hl.tenant_id
   and os.empresa_id = hl.empresa_id
  cross join lateral (
    select hl.entrada_1 as inicio, hl.saida_1 as fim
    where hl.entrada_1 is not null and hl.saida_1 is not null
    union all
    select hl.entrada_2, hl.saida_2
    where hl.entrada_2 is not null and hl.saida_2 is not null
    union all
    select hl.hora_entrada, hl.hora_saida
    where hl.entrada_1 is null and hl.hora_entrada is not null and hl.hora_saida is not null
  ) intervalo
  cross join lateral (
    select p_entrada_1 as inicio, p_saida_1 as fim
    union all
    select p_entrada_2, p_saida_2
    where p_entrada_2 is not null and p_saida_2 is not null
  ) novo_intervalo
  where hl.tenant_id = v_tenant_id
    and hl.empresa_id = v_empresa_id
    and hl.colaborador_id = p_colaborador_id
    and hl.data = p_data
    and novo_intervalo.inicio < intervalo.fim
    and novo_intervalo.fim > intervalo.inicio
  order by hl.criado_em, hl.id
  limit 1;
  if v_conflito is not null then
    return jsonb_build_object('sucesso', false, 'lancamento_id', null, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'sobreposicao', 'mensagem', format('Há sobreposição com lançamento HH já existente na %s.', v_conflito))));
  end if;

  insert into public.hh_lancamentos (
    tenant_id,
    empresa_id,
    os_id,
    colaborador_id,
    hh_tipo_id,
    hh_servico_id,
    data,
    hora_entrada,
    hora_saida,
    horas_trabalhadas,
    percentual_aplicado,
    tem_extra_50,
    horas_extra_50,
    tem_extra_100,
    horas_extra_100,
    observacao,
    criado_por,
    entrada_1,
    saida_1,
    entrada_2,
    saida_2
  ) values (
    v_tenant_id,
    v_empresa_id,
    p_os_id,
    p_colaborador_id,
    p_hh_servico_id,
    p_hh_servico_id,
    p_data,
    p_entrada_1,
    coalesce(p_saida_2, p_saida_1),
    v_horas_efetivas,
    v_percentual,
    v_horas_extra_50 > 0,
    v_horas_extra_50,
    v_horas_extra_100 > 0,
    v_horas_extra_100,
    nullif(btrim(p_observacao), ''),
    nullif(auth.jwt() ->> 'email', ''),
    case when p_entrada_2 is null then null else p_entrada_1 end,
    case when p_saida_2 is null then null else p_saida_1 end,
    p_entrada_2,
    p_saida_2
  )
  returning id into v_lancamento_id;

  return jsonb_build_object('sucesso', true, 'lancamento_id', v_lancamento_id, 'horas', v_horas_efetivas, 'erros', '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."app_lancar_hh"("p_os_id" integer, "p_colaborador_id" "uuid", "p_data" "date", "p_hh_servico_id" bigint, "p_entrada_1" time without time zone, "p_saida_1" time without time zone, "p_entrada_2" time without time zone, "p_saida_2" time without time zone, "p_percentual_manual" smallint, "p_horas_extra_50" numeric, "p_horas_extra_100" numeric, "p_observacao" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_lancar_hh_lote"("p_os_id" integer, "p_data" "date", "p_entrada_1" time without time zone, "p_saida_1" time without time zone, "p_entrada_2" time without time zone DEFAULT NULL::time without time zone, "p_saida_2" time without time zone DEFAULT NULL::time without time zone, "p_percentual_manual" smallint DEFAULT NULL::smallint, "p_observacao" "text" DEFAULT NULL::"text", "p_lancamentos" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_papel_empresa text;
  v_colaborador_proprio_id uuid;
  v_cliente_id bigint;
  v_os_status text;
  v_percentual smallint;
  v_codigo_tipo text;
  v_hh_tipo_id bigint;
  v_horas_efetivas numeric(10,2);
  v_item jsonb;
  v_colaborador_id uuid;
  v_hh_servico_id bigint;
  v_nome_colaborador text;
  v_preco_aplicavel numeric;
  v_conflito text;
  v_colaborador_ids uuid[] := '{}'::uuid[];
  v_servico_ids bigint[] := '{}'::bigint[];
  v_erros jsonb := '[]'::jsonb;
  v_gravados integer := 0;
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para lançar HH.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();
  if v_tenant_id is null or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  select ue.papel into v_papel_empresa
  from a.usuario u
  join a.usuario_empresa ue
    on ue.usuario_id = u.id
   and ue.empresa_id = v_empresa_id
   and ue.ativo is true
   and ue.deleted_at is null
  where u.auth_user_id = v_auth_uid
    and u.ativo is true
    and u.deleted_at is null
  limit 1;
  if v_papel_empresa is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa atual.';
  end if;

  if not public.app_papel_pode_lancar_horas(v_papel_empresa) then
    raise exception 'Seu perfil não tem permissão para lançar horas na OS.';
  end if;

  if upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') then
    select colaborador.id into v_colaborador_proprio_id
    from public.colaboradores colaborador
    where colaborador.user_id = v_auth_uid
      and colaborador.tenant_id = v_tenant_id
      and colaborador.empresa_id = v_empresa_id
      and colaborador.ativo is true;
    if v_colaborador_proprio_id is null then
      raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
    end if;
  end if;

  if p_data is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'data', 'mensagem', 'Informe a data do lançamento HH.'));
  elsif p_data > current_date then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'data_futura', 'mensagem', 'Não é permitido lançar HH em data futura.'));
  end if;

  select os.cliente_id, os.status into v_cliente_id, v_os_status
  from public.ordens_servico os
  where os.id = p_os_id
    and os.tenant_id = v_tenant_id
    and os.empresa_id = v_empresa_id
    and coalesce(os.usa_relatorio_hh, false) is true;
  if not found then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'os', 'mensagem', 'A OS informada não existe, não pertence à empresa atual ou não é uma OS HH.'));
  elsif lower(coalesce(v_os_status, '')) <> 'em_andamento' then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'os_status', 'mensagem', 'Só é permitido lançar HH em OS com status em andamento.'));
  elsif v_cliente_id is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'cliente', 'mensagem', 'A OS HH não possui cliente identificado.'));
  end if;

  if p_entrada_1 is null or p_saida_1 is null then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'Informe entrada e saída do primeiro período.'));
  elsif p_entrada_1 >= p_saida_1 then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'A entrada do primeiro período deve ser anterior à saída.'));
  end if;

  if (p_entrada_2 is null) <> (p_saida_2 is null) then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'Informe entrada e saída do segundo período ou deixe ambos vazios.'));
  elsif p_entrada_2 is not null and p_saida_2 is not null then
    if p_entrada_2 >= p_saida_2 then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'A entrada do segundo período deve ser anterior à saída.'));
    elsif p_saida_1 is not null and p_saida_1 > p_entrada_2 then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'O segundo período não pode sobrepor o primeiro.'));
    end if;
  end if;

  if p_percentual_manual is not null and p_percentual_manual not in (0, 50, 100) then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'percentual', 'mensagem', 'O tipo HH manual deve ser normal, extra 50% ou extra 100%.'));
  end if;
  if p_lancamentos is null or jsonb_typeof(p_lancamentos) <> 'array' or jsonb_array_length(p_lancamentos) = 0 then
    v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'lancamentos', 'mensagem', 'Selecione ao menos um colaborador para o lançamento HH.'));
  end if;
  if jsonb_array_length(v_erros) > 0 then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'horas', null, 'erros', v_erros);
  end if;

  v_horas_efetivas := round(
    extract(epoch from (p_saida_1 - p_entrada_1)) / 3600
    + case when p_entrada_2 is not null then extract(epoch from (p_saida_2 - p_entrada_2)) / 3600 else 0 end,
    2
  );
  if v_horas_efetivas <= 0 then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'horario', 'mensagem', 'Os horários informados não resultam em horas trabalhadas válidas.')));
  end if;

  if p_percentual_manual is not null then
    v_percentual := p_percentual_manual;
  elsif extract(dow from p_data) = 0 then
    v_percentual := 100;
  elsif extract(dow from p_data) = 6 then
    v_percentual := 50;
  else
    v_percentual := 0;
  end if;
  v_codigo_tipo := case v_percentual when 50 then 'EXTRA_50' when 100 then 'EXTRA_100' else 'NORMAL' end;

  select hm.hh_tipo_id into v_hh_tipo_id
  from public.hh_tipos_mapping hm
  join public.tipos_horas th on th.id = hm.tipo_hora_id
  where hm.tenant_id = v_tenant_id
    and hm.ativo is true
    and th.tenant_id = v_tenant_id
    and th.ativo is true
    and th.codigo = v_codigo_tipo
  limit 1;
  if v_hh_tipo_id is null then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'configuracao_hh', 'mensagem', 'Não existe configuração ativa para o tipo HH desta data.')));
  end if;

  if not exists (
    select 1 from public.cliente_hh_tabelas tabela
    where tabela.tenant_id = v_tenant_id
      and tabela.empresa_id = v_empresa_id
      and tabela.cliente_id = v_cliente_id
      and tabela.ativo is true
      and p_data between tabela.vigencia_inicio and tabela.vigencia_fim
  ) then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'horas', null, 'erros', jsonb_build_array(jsonb_build_object('tipo', 'tabela_hh', 'mensagem', 'Não há tabela HH ativa e vigente para este cliente na data informada.')));
  end if;

  for v_item in select value from jsonb_array_elements(p_lancamentos) loop
    begin
      v_colaborador_id := nullif(v_item->>'colaborador_id', '')::uuid;
    exception when others then
      v_colaborador_id := null;
    end;
    begin
      v_hh_servico_id := nullif(v_item->>'hh_servico_id', '')::bigint;
    exception when others then
      v_hh_servico_id := null;
    end;

    if v_colaborador_id is null or v_hh_servico_id is null then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'lancamentos', 'mensagem', 'Há um colaborador sem especialidade HH válida.'));
      continue;
    end if;
    if v_colaborador_id = any(v_colaborador_ids) then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'lancamentos', 'mensagem', 'O mesmo colaborador foi selecionado mais de uma vez.'));
      continue;
    end if;

    select colaborador.nome into v_nome_colaborador
    from public.colaboradores colaborador
    where colaborador.id = v_colaborador_id
      and colaborador.tenant_id = v_tenant_id
      and colaborador.empresa_id = v_empresa_id
      and colaborador.ativo is true;
    if v_nome_colaborador is null then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'colaborador', 'mensagem', format('O colaborador %s está inativo ou não pertence à empresa atual.', v_colaborador_id)));
      continue;
    end if;
    if upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') and v_colaborador_id <> v_colaborador_proprio_id then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'permissao', 'mensagem', format('%s: o perfil APONTADOR só pode lançar HH para o próprio colaborador vinculado.', v_nome_colaborador)));
      continue;
    end if;

    select case v_percentual when 50 then servico.preco_50 when 100 then servico.preco_100 else servico.preco_base end
      into v_preco_aplicavel
    from public.cliente_hh_servicos servico
    where servico.id = v_hh_servico_id
      and servico.tenant_id = v_tenant_id
      and servico.empresa_id = v_empresa_id
      and servico.cliente_id = v_cliente_id
      and servico.ativo is true
      and exists (
        select 1 from public.colaborador_cliente_funcao vinculo
        where vinculo.tenant_id = v_tenant_id
          and vinculo.empresa_id = v_empresa_id
          and vinculo.cliente_id = v_cliente_id
          and vinculo.colaborador_id = v_colaborador_id
          and vinculo.hh_servico_id = servico.id
          and vinculo.ativo is true
      );
    if v_preco_aplicavel is null then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'especialidade', 'mensagem', format('%s: a especialidade não está ativa ou não possui vínculo ativo para este cliente.', v_nome_colaborador)));
      continue;
    end if;
    if v_preco_aplicavel <= 0 then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'preco_hh', 'mensagem', format('%s: a especialidade não possui preço HH válido para o tipo de dia informado. Ajuste a configuração no sistema web.', v_nome_colaborador)));
      continue;
    end if;

    select format('OS %s, %s-%s', coalesce(os.numero_os, hl.os_id::text), to_char(intervalo.inicio, 'HH24:MI'), to_char(intervalo.fim, 'HH24:MI'))
      into v_conflito
    from public.hh_lancamentos hl
    join public.ordens_servico os on os.id = hl.os_id and os.tenant_id = hl.tenant_id and os.empresa_id = hl.empresa_id
    cross join lateral (
      select hl.entrada_1 as inicio, hl.saida_1 as fim where hl.entrada_1 is not null and hl.saida_1 is not null
      union all select hl.entrada_2, hl.saida_2 where hl.entrada_2 is not null and hl.saida_2 is not null
      union all select hl.hora_entrada, hl.hora_saida where hl.entrada_1 is null and hl.hora_entrada is not null and hl.hora_saida is not null
    ) intervalo
    cross join lateral (
      select p_entrada_1 as inicio, p_saida_1 as fim
      union all select p_entrada_2, p_saida_2 where p_entrada_2 is not null and p_saida_2 is not null
    ) novo_intervalo
    where hl.tenant_id = v_tenant_id
      and hl.empresa_id = v_empresa_id
      and hl.colaborador_id = v_colaborador_id
      and hl.data = p_data
      and novo_intervalo.inicio < intervalo.fim
      and novo_intervalo.fim > intervalo.inicio
    order by hl.criado_em, hl.id
    limit 1;
    if v_conflito is not null then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object('tipo', 'sobreposicao', 'mensagem', format('%s: há sobreposição com lançamento HH já existente na %s.', v_nome_colaborador, v_conflito)));
      continue;
    end if;

    v_colaborador_ids := array_append(v_colaborador_ids, v_colaborador_id);
    v_servico_ids := array_append(v_servico_ids, v_hh_servico_id);
  end loop;

  if jsonb_array_length(v_erros) > 0 then
    return jsonb_build_object('sucesso', false, 'gravados', 0, 'horas', null, 'erros', v_erros);
  end if;

  insert into public.hh_lancamentos (
    tenant_id, empresa_id, os_id, colaborador_id, hh_tipo_id, hh_servico_id,
    data, hora_entrada, hora_saida, horas_trabalhadas, percentual_aplicado,
    tem_extra_50, horas_extra_50, tem_extra_100, horas_extra_100, observacao,
    criado_por, entrada_1, saida_1, entrada_2, saida_2
  )
  select
    v_tenant_id, v_empresa_id, p_os_id, v_colaborador_ids[i], v_servico_ids[i], v_servico_ids[i],
    p_data, p_entrada_1, coalesce(p_saida_2, p_saida_1), v_horas_efetivas, v_percentual,
    false, 0, false, 0, nullif(btrim(p_observacao), ''), nullif(auth.jwt()->>'email', ''),
    case when p_entrada_2 is null then null else p_entrada_1 end,
    case when p_saida_2 is null then null else p_saida_1 end,
    p_entrada_2, p_saida_2
  from generate_subscripts(v_colaborador_ids, 1) i;
  get diagnostics v_gravados = row_count;

  return jsonb_build_object('sucesso', true, 'gravados', v_gravados, 'horas', v_horas_efetivas, 'erros', '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."app_lancar_hh_lote"("p_os_id" integer, "p_data" "date", "p_entrada_1" time without time zone, "p_saida_1" time without time zone, "p_entrada_2" time without time zone, "p_saida_2" time without time zone, "p_percentual_manual" smallint, "p_observacao" "text", "p_lancamentos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_lancar_material_os"("p_os_id" integer, "p_codigo" "text", "p_quantidade" numeric, "p_observacao" "text" DEFAULT NULL::"text") RETURNS TABLE("os_item_id" integer, "item_id" integer, "codigo_interno" "text", "nome" "text", "unidade_medida" "text", "quantidade" numeric, "saldo_restante" numeric, "nao_cobrado" boolean, "custo_medio_ausente" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
begin
  perform public.assert_documento_operacional_os(p_os_id);
  return query
  select *
  from public.app_lancar_material_os_unfiltered_ov_20260829(
    p_os_id, p_codigo, p_quantidade, p_observacao
  );
end;
$$;


ALTER FUNCTION "public"."app_lancar_material_os"("p_os_id" integer, "p_codigo" "text", "p_quantidade" numeric, "p_observacao" "text") OWNER TO "postgres";


