CREATE OR REPLACE FUNCTION "public"."app_listar_apontamentos_os_fluxo"("p_os_id" integer) RETURNS TABLE("id" "uuid", "os_id" integer, "numero_os" character varying, "cliente_nome" character varying, "colaborador_id" "uuid", "nome_colaborador" character varying, "data" "date", "horas" numeric, "tipo_hora_id" "uuid", "nome_tipo_hora" character varying, "descricao" "text", "status" character varying, "status_aprovacao" "text", "pendente_em" timestamp with time zone, "aprovado_em" timestamp with time zone, "rejeitado_em" timestamp with time zone, "gerado_por_hh" boolean, "motivo_devolucao" "text", "criado_em" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
begin
  perform public.assert_documento_operacional_os(p_os_id);
  return query
  select * from public.app_listar_apontamentos_os_fluxo_unfiltered_ov_20260829(p_os_id);
end;
