ALTER FUNCTION "public"."app_listar_apontamentos_os_fluxo"("p_os_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_listar_apontamentos_os_fluxo_unfiltered_ov_20260829"("p_os_id" integer) RETURNS TABLE("id" "uuid", "os_id" integer, "numero_os" character varying, "cliente_nome" character varying, "colaborador_id" "uuid", "nome_colaborador" character varying, "data" "date", "horas" numeric, "tipo_hora_id" "uuid", "nome_tipo_hora" character varying, "descricao" "text", "status" character varying, "status_aprovacao" "text", "pendente_em" timestamp with time zone, "aprovado_em" timestamp with time zone, "rejeitado_em" timestamp with time zone, "gerado_por_hh" boolean, "motivo_devolucao" "text", "criado_em" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_colaborador_id uuid;
  v_papel text;
begin
  if v_auth_uid is null or v_tenant_id is null or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  select ue.papel into v_papel
  from a.usuario u
  join a.usuario_empresa ue on ue.usuario_id = u.id
  where u.auth_user_id = v_auth_uid and u.ativo and u.deleted_at is null
    and ue.empresa_id = v_empresa_id and ue.ativo and ue.deleted_at is null
  limit 1;
  if v_papel is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa.';
  end if;

  if upper(v_papel) = 'APONTAMENTO_RH' then
    select c.id into v_colaborador_id
    from public.colaboradores c
    where c.user_id = v_auth_uid and c.tenant_id = v_tenant_id and c.empresa_id = v_empresa_id and c.ativo;
    if v_colaborador_id is null then
      raise exception 'Seu usuário de apontamento não está vinculado a um colaborador ativo nesta empresa.';
    end if;
  end if;

  return query
  select ah.id, ah.os_id, os.numero_os, os.cliente_nome, ah.colaborador_id, c.nome,
         ah.data, ah.horas, ah.tipo_hora_id, th.descricao, ah.descricao, ah.status,
         ah.status_aprovacao, ah.pendente_em, ah.aprovado_em, ah.rejeitado_em,
         ah.gerado_por_hh, ah.motivo_devolucao, ah.criado_em
  from public.apontamentos_horas ah
  join public.ordens_servico os on os.id = ah.os_id and os.tenant_id = ah.tenant_id and os.empresa_id = ah.empresa_id
  join public.colaboradores c on c.id = ah.colaborador_id and c.tenant_id = v_tenant_id and c.empresa_id = v_empresa_id
  left join public.tipos_horas th on th.id = ah.tipo_hora_id and th.tenant_id = v_tenant_id
  where ah.os_id = p_os_id
    and ah.tenant_id = v_tenant_id and ah.empresa_id = v_empresa_id
    and (upper(v_papel) <> 'APONTAMENTO_RH' or ah.colaborador_id = v_colaborador_id)
  order by ah.data desc, ah.criado_em desc, ah.id desc;
end;
$$;


ALTER FUNCTION "public"."app_listar_apontamentos_os_fluxo_unfiltered_ov_20260829"("p_os_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_listar_apontamentos_unfiltered_ov_20260829"("p_data_inicio" "date" DEFAULT NULL::"date", "p_data_fim" "date" DEFAULT NULL::"date", "p_os_id" integer DEFAULT NULL::integer, "p_colaborador_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "os_id" integer, "numero_os" character varying, "cliente_nome" character varying, "colaborador_id" "uuid", "nome_colaborador" character varying, "data" "date", "horas" numeric, "tipo_hora_id" "uuid", "nome_tipo_hora" character varying, "descricao" "text", "status" character varying, "gerado_por_hh" boolean, "motivo_devolucao" "text", "criado_em" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_colaborador_proprio_id uuid;
  v_papel_empresa text;
  v_colaborador_filtro_id uuid;
  v_data_inicio date := coalesce(p_data_inicio, current_date - 29);
  v_data_fim date := coalesce(p_data_fim, current_date);
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para consultar apontamentos.';
  end if;

  if v_data_inicio > v_data_fim then
    raise exception 'A data inicial não pode ser posterior à data final.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  select colaborador.id
    into v_colaborador_proprio_id
  from public.colaboradores as colaborador
  where colaborador.user_id = v_auth_uid
    and colaborador.tenant_id = v_tenant_id
    and colaborador.empresa_id = v_empresa_id
    and colaborador.ativo is true;

  if v_colaborador_proprio_id is null then
    raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
  end if;

  select usuario_empresa.papel
    into v_papel_empresa
  from a.usuario as usuario
  join a.usuario_empresa as usuario_empresa
    on usuario_empresa.usuario_id = usuario.id
   and usuario_empresa.empresa_id = v_empresa_id
   and usuario_empresa.ativo is true
   and usuario_empresa.deleted_at is null
  where usuario.auth_user_id = v_auth_uid
    and usuario.ativo is true
    and usuario.deleted_at is null
  limit 1;

  if v_papel_empresa is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa atual.';
  end if;

  if upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') then
    v_colaborador_filtro_id := v_colaborador_proprio_id;
  else
    v_colaborador_filtro_id := p_colaborador_id;
  end if;

  return query
  select
    apontamento.id,
    apontamento.os_id,
    os.numero_os,
    os.cliente_nome,
    apontamento.colaborador_id,
    colaborador.nome,
    apontamento.data,
    apontamento.horas,
    apontamento.tipo_hora_id,
    tipo_hora.descricao,
    apontamento.descricao,
    apontamento.status,
    apontamento.gerado_por_hh,
    apontamento.motivo_devolucao,
    apontamento.criado_em
  from public.apontamentos_horas as apontamento
  join public.colaboradores as colaborador
    on colaborador.id = apontamento.colaborador_id
   and colaborador.tenant_id = v_tenant_id
   and colaborador.empresa_id = v_empresa_id
  left join public.ordens_servico as os
    on os.id = apontamento.os_id
   and os.tenant_id = v_tenant_id
   and os.empresa_id = v_empresa_id
  left join public.tipos_horas as tipo_hora
    on tipo_hora.id = apontamento.tipo_hora_id
   and tipo_hora.tenant_id = v_tenant_id
  where apontamento.tenant_id = v_tenant_id
    and apontamento.empresa_id = v_empresa_id
    and apontamento.data between v_data_inicio and v_data_fim
    and (p_os_id is null or apontamento.os_id = p_os_id)
    and (v_colaborador_filtro_id is null or apontamento.colaborador_id = v_colaborador_filtro_id)
  order by apontamento.data desc, apontamento.criado_em desc, apontamento.id desc;
end;
$$;


ALTER FUNCTION "public"."app_listar_apontamentos_unfiltered_ov_20260829"("p_data_inicio" "date", "p_data_fim" "date", "p_os_id" integer, "p_colaborador_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_listar_aprovacoes_pendentes"() RETURNS TABLE("id" "uuid", "os_id" integer, "numero_os" character varying, "cliente_nome" character varying, "colaborador_id" "uuid", "nome_colaborador" character varying, "data" "date", "horas" numeric, "nome_tipo_hora" character varying, "descricao" "text", "pendente_em" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
begin
  if v_auth_uid is null or v_tenant_id is null or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  return query
  select ah.id, ah.os_id, os.numero_os, os.cliente_nome, ah.colaborador_id, c.nome,
         ah.data, ah.horas, th.descricao, ah.descricao, ah.pendente_em
  from public.apontamentos_horas ah
  join public.ordens_servico os on os.id = ah.os_id and os.tenant_id = ah.tenant_id and os.empresa_id = ah.empresa_id
  join public.colaboradores c on c.id = ah.colaborador_id and c.tenant_id = v_tenant_id and c.empresa_id = v_empresa_id
  left join public.tipos_horas th on th.id = ah.tipo_hora_id and th.tenant_id = v_tenant_id
  where ah.tenant_id = v_tenant_id and ah.empresa_id = v_empresa_id
    and ah.status_aprovacao = 'pendente'
    and os.responsavel_aprovacao_id = v_auth_uid
  order by ah.pendente_em asc nulls last, ah.data asc, ah.criado_em asc;
end;
$$;


ALTER FUNCTION "public"."app_listar_aprovacoes_pendentes"() OWNER TO "postgres";


