    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para consultar clientes HH.';
  end if;

  v_tenant_id := public.current_tenant_id();
