CREATE OR REPLACE FUNCTION "public"."app_listar_materiais_os_unfiltered_ov_20260829"("p_os_id" integer) RETURNS TABLE("id" integer, "item_id" integer, "codigo_interno" "text", "nome" "text", "unidade_medida" "text", "quantidade" numeric, "observacoes" "text", "registrado_por_nome" "text", "criado_em" timestamp without time zone, "nao_cobrado" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
begin
  if v_auth_uid is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  if not exists (
    select 1
    from public.ordens_servico os
    where os.id = p_os_id
      and os.tenant_id = v_tenant_id
      and os.empresa_id = v_empresa_id
  ) then
    raise exception 'A OS informada não existe ou não pertence à empresa atual.';
  end if;

  return query
  select
    os_item.id,
    os_item.item_id,
    item.codigo_interno::text,
    coalesce(item.nome, item.descricao)::text,
    item.unidade_medida::text,
    os_item.quantidade,
    os_item.observacoes,
    os_item.registrado_por_nome,
    os_item.criado_em,
    public.os_lancamento_nao_cobrado(
      v_tenant_id,
      v_empresa_id,
      p_os_id,
      os_item.criado_em
    )
  from public.os_itens os_item
  join public.itens item
    on item.id = os_item.item_id
   and item.tenant_id = os_item.tenant_id
   and item.empresa_id = os_item.empresa_id
  where os_item.os_id = p_os_id
    and os_item.tenant_id = v_tenant_id
    and os_item.empresa_id = v_empresa_id
    and item.tipo = 'produto'
  order by os_item.criado_em desc, os_item.id desc;
end;
$$;


ALTER FUNCTION "public"."app_listar_materiais_os_unfiltered_ov_20260829"("p_os_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_listar_notificacoes"("p_limite" integer DEFAULT 50, "p_antes_de" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "tipo" "text", "titulo" "text", "corpo" "text", "dados" "jsonb", "quantidade" integer, "lida_em" timestamp with time zone, "criado_em" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
  select n.id, n.tipo, n.titulo, n.corpo, n.dados, n.quantidade, n.lida_em, n.criado_em
  from public.app_notificacoes n
  where n.tenant_id = public.current_tenant_id()
    and n.empresa_id = public.current_empresa_id()
    and n.usuario_id = auth.uid()
    and public.app_notificacao_contexto_valido()
    and (p_antes_de is null or n.criado_em < p_antes_de)
  order by n.criado_em desc
  limit greatest(1, least(coalesce(p_limite, 50), 100));
$$;


