CREATE OR REPLACE FUNCTION "public"."app_listar_os_fluxo_unfiltered_ov_20260829"("p_status_fluxo" "text" DEFAULT 'em_andamento'::"text", "p_busca" "text" DEFAULT NULL::"text") RETURNS TABLE("id" integer, "numero_os" character varying, "os_num" bigint, "cliente_nome" character varying, "descricao_servico" "text", "status_legado" character varying, "status_fluxo" "text", "usa_relatorio_hh" boolean, "total_horas" numeric, "responsavel_nome" "text", "situacao_margem" "text", "sou_responsavel" boolean, "pendencias_aprovacao" integer, "garantia_motivo" "text", "faturado_em" timestamp with time zone, "faturada_presumida_legado" boolean, "pode_concluir" boolean, "pode_faturar" boolean, "pode_reabrir_garantia" boolean, "pode_concluir_garantia" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_status text := lower(coalesce(nullif(btrim(p_status_fluxo), ''), 'em_andamento'));
  v_papel text;
  v_colaborador_id uuid;
begin
  if v_auth_uid is null or v_tenant_id is null or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  if v_status not in ('em_andamento', 'concluida', 'faturada') then
    raise exception 'Filtro de status inválido.';
  end if;

  select ue.papel into v_papel
  from a.usuario u
  join a.usuario_empresa ue on ue.usuario_id = u.id
  where u.auth_user_id = v_auth_uid and u.ativo and u.deleted_at is null
    and ue.empresa_id = v_empresa_id and ue.ativo and ue.deleted_at is null
  limit 1;
  if v_papel is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa.';
  end if;

  if upper(v_papel) = 'APONTADOR' and v_status <> 'em_andamento' then
    raise exception 'O perfil APONTADOR só pode consultar OS em andamento.';
  end if;

  select c.id into v_colaborador_id
  from public.colaboradores c
  where c.user_id = v_auth_uid
    and c.tenant_id = v_tenant_id
    and c.empresa_id = v_empresa_id
    and c.ativo;

  if upper(v_papel) = 'APONTAMENTO_RH' and v_colaborador_id is null then
    raise exception 'Seu usuário de apontamento não está vinculado a um colaborador ativo nesta empresa.';
  end if;

  -- Mantém o cálculo de margem da RPC existente quando há colaborador vinculado.
  -- Para perfis administrativos sem colaborador, a alternativa abaixo evita que a
  -- leitura da OS falhe por uma vinculação que não é necessária ao papel.
  if v_colaborador_id is not null and upper(v_papel) <> 'FINANCEIRO' then
    return query
  select
    base.id,
    base.numero_os,
    base.os_num,
    base.cliente_nome,
    base.descricao_servico,
    base.status,
    os.status_fluxo,
    base.usa_relatorio_hh,
    base.total_horas,
    base.responsavel_nome,
    base.situacao_margem,
    base.sou_responsavel,
    coalesce(pendencias.quantidade, 0)::integer,
    os.garantia_motivo,
    os.faturado_em,
    os.faturada_presumida_legado,
    upper(v_papel) in ('ADMIN', 'DIRETOR', 'COORDENACAO'),
    upper(v_papel) = 'FINANCEIRO' and exists (
      select 1 from f.documento_fiscal documento
      where documento.tenant_id = v_tenant_id and documento.empresa_id = v_empresa_id and documento.os_id_import = os.id
        and documento.operacao = 'SAIDA' and documento.deleted_at is null
        and ((upper(coalesce(documento.modelo, '')) = 'NFSE' and upper(coalesce(documento.nfse_status, '')) = 'EMITIDA')
          or (upper(coalesce(documento.modelo, '')) <> 'NFSE' and (nullif(upper(btrim(coalesce(documento.nfe_status, ''))), '') is null or upper(coalesce(documento.nfe_status, '')) = 'EMITIDA')))
    ),
    upper(v_papel) in ('COORDENACAO', 'FINANCEIRO')
      and os.status_fluxo = 'faturada'
      and not coalesce(os.faturada_presumida_legado, false)
      and os.faturado_em is not null
      and os.faturado_em >= now() - interval '6 months',
    upper(coalesce(v_papel, '')) = 'COORDENACAO'
  from public.app_listar_os(true, p_busca) as base
  join public.ordens_servico as os
    on os.id = base.id
   and os.tenant_id = v_tenant_id
   and os.empresa_id = v_empresa_id
  left join lateral (
    select count(*)::integer as quantidade
    from public.apontamentos_horas as ah
    where ah.os_id = os.id
      and ah.tenant_id = v_tenant_id
      and ah.empresa_id = v_empresa_id
      and ah.status_aprovacao = 'pendente'
  ) as pendencias on true
  where case v_status
    when 'em_andamento' then os.status_fluxo in ('em_andamento', 'em_andamento_garantia')
    when 'concluida' then os.status_fluxo in ('concluida', 'concluida_garantia')
    when 'faturada' then os.status_fluxo = 'faturada'
  end
  order by os.data_abertura desc nulls last, os.id desc;
    return;
  end if;

  return query
  select
    os.id,
    os.numero_os,
    os.os_num,
    os.cliente_nome,
    os.descricao_servico,
    os.status,
    os.status_fluxo,
    os.usa_relatorio_hh,
    coalesce(horas.total_horas, 0)::numeric,
    coalesce(nullif(perfil_responsavel.nome, ''), nullif(usuario_responsavel.nome, ''), nullif(colaborador_responsavel.nome, ''))::text,
    null::text,
    (os.responsavel_aprovacao_id is not distinct from v_auth_uid),
    coalesce(pendencias.quantidade, 0)::integer,
    os.garantia_motivo,
    os.faturado_em,
    os.faturada_presumida_legado,
    upper(v_papel) in ('ADMIN', 'DIRETOR', 'COORDENACAO'),
    upper(v_papel) = 'FINANCEIRO' and exists (
      select 1 from f.documento_fiscal documento
      where documento.tenant_id = v_tenant_id and documento.empresa_id = v_empresa_id and documento.os_id_import = os.id
        and documento.operacao = 'SAIDA' and documento.deleted_at is null
        and ((upper(coalesce(documento.modelo, '')) = 'NFSE' and upper(coalesce(documento.nfse_status, '')) = 'EMITIDA')
          or (upper(coalesce(documento.modelo, '')) <> 'NFSE' and (nullif(upper(btrim(coalesce(documento.nfe_status, ''))), '') is null or upper(coalesce(documento.nfe_status, '')) = 'EMITIDA')))
    ),
    upper(v_papel) in ('COORDENACAO', 'FINANCEIRO')
      and os.status_fluxo = 'faturada'
      and not coalesce(os.faturada_presumida_legado, false)
      and os.faturado_em is not null
      and os.faturado_em >= now() - interval '6 months',
    upper(v_papel) = 'COORDENACAO'
  from public.ordens_servico os
  left join lateral (
    select sum(ah.horas)::numeric as total_horas
    from public.apontamentos_horas ah
    where ah.os_id = os.id and ah.tenant_id = v_tenant_id and ah.empresa_id = v_empresa_id
  ) horas on true
  left join lateral (
    select count(*)::integer as quantidade
    from public.apontamentos_horas ah
    where ah.os_id = os.id and ah.tenant_id = v_tenant_id and ah.empresa_id = v_empresa_id and ah.status_aprovacao = 'pendente'
  ) pendencias on true
  left join public.profiles perfil_responsavel on perfil_responsavel.id = os.responsavel_aprovacao_id
  left join a.usuario usuario_responsavel on usuario_responsavel.auth_user_id = os.responsavel_aprovacao_id and usuario_responsavel.ativo and usuario_responsavel.deleted_at is null
  left join public.colaboradores colaborador_responsavel on colaborador_responsavel.user_id = os.responsavel_aprovacao_id and colaborador_responsavel.tenant_id = v_tenant_id and colaborador_responsavel.empresa_id = v_empresa_id
  where os.tenant_id = v_tenant_id and os.empresa_id = v_empresa_id
    and (p_busca is null or os.numero_os ilike '%' || btrim(p_busca) || '%' or os.os_num::text ilike '%' || btrim(p_busca) || '%' or os.cliente_nome ilike '%' || btrim(p_busca) || '%')
    and case v_status
      when 'em_andamento' then os.status_fluxo in ('em_andamento', 'em_andamento_garantia')
      when 'concluida' then os.status_fluxo in ('concluida', 'concluida_garantia')
      when 'faturada' then os.status_fluxo = 'faturada'
    end
  order by os.data_abertura desc nulls last, os.id desc;
end;
$$;


ALTER FUNCTION "public"."app_listar_os_fluxo_unfiltered_ov_20260829"("p_status_fluxo" "text", "p_busca" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_listar_os_unfiltered_ov_20260829"("p_incluir_fechadas" boolean DEFAULT false, "p_busca" "text" DEFAULT NULL::"text") RETURNS TABLE("id" integer, "numero_os" character varying, "os_num" bigint, "cliente_nome" character varying, "descricao_servico" "text", "status" character varying, "usa_relatorio_hh" boolean, "data_abertura" timestamp without time zone, "sou_responsavel" boolean, "total_horas" numeric, "responsavel_nome" "text", "situacao_margem" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_colaborador_id uuid;
  v_papel_empresa text;
  v_busca text := nullif(btrim(p_busca), '');
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para consultar ordens de serviço.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  select colaborador.id
    into v_colaborador_id
  from public.colaboradores as colaborador
  where colaborador.user_id = v_auth_uid
    and colaborador.tenant_id = v_tenant_id
    and colaborador.empresa_id = v_empresa_id
    and colaborador.ativo is true;

  if v_colaborador_id is null then
    raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
  end if;

  select usuario_empresa.papel
    into v_papel_empresa
  from a.usuario as usuario
  join a.usuario_empresa as usuario_empresa
    on usuario_empresa.usuario_id = usuario.id
   and usuario_empresa.empresa_id = v_empresa_id
   and usuario_empresa.ativo is true
   and usuario_empresa.deleted_at is null
  where usuario.auth_user_id = v_auth_uid
    and usuario.ativo is true
    and usuario.deleted_at is null
  limit 1;

  if v_papel_empresa is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa atual.';
  end if;

  return query
  with os_base as (
    select os.*
    from public.ordens_servico as os
    where os.tenant_id = v_tenant_id
      and os.empresa_id = v_empresa_id
      and os.status in (
        'em_andamento',
        case when p_incluir_fechadas then 'concluida' else 'em_andamento' end
      )
      and (
        v_busca is null
        or os.numero_os ilike '%' || v_busca || '%'
        or os.os_num::text ilike '%' || v_busca || '%'
        or os.cliente_nome ilike '%' || v_busca || '%'
      )
  ),
  horas_por_os as (
    select apontamento.os_id, coalesce(sum(apontamento.horas), 0)::numeric as total_horas
    from public.apontamentos_horas as apontamento
    join os_base as os on os.id = apontamento.os_id
    where apontamento.tenant_id = v_tenant_id
      and apontamento.empresa_id = v_empresa_id
      and (
        upper(v_papel_empresa) not in ('APONTAMENTO_RH', 'APONTADOR')
        or apontamento.colaborador_id = v_colaborador_id
      )
    group by apontamento.os_id
  ),
  materiais_por_os as (
    select os_item.os_id, coalesce(sum(os_item.valor_total), 0)::numeric as materiais
    from public.os_itens as os_item
    join os_base as os on os.id = os_item.os_id
    join public.itens as item
      on item.id = os_item.item_id
     and item.tenant_id = os_item.tenant_id
     and item.empresa_id = os_item.empresa_id
    where os_item.tenant_id = v_tenant_id
      and os_item.empresa_id = v_empresa_id
      and item.tipo = 'produto'
    group by os_item.os_id
  ),
  mao_obra_por_os as (
    select custo.os_id, coalesce(custo.custo_mao_obra, 0)::numeric as mao_obra
    from public.vw_custo_mao_obra_os as custo
    join os_base as os on os.id = custo.os_id
  ),
  hh_horas_efetivas as (
    select
      hh.os_id,
      hh.valor_hora,
      hh.valor_total,
      hh.percentual_aplicado,
      hh.tem_extra_50,
      hh.tem_extra_100,
      hh.horas_extra_50,
      hh.horas_extra_100,
      case
        when periodo.entrada_1 is not null
         and periodo.saida_1 is not null
         and periodo.entrada_2 is not null
         and periodo.saida_2 is not null
          then round((
            case when periodo.saida_1 >= periodo.entrada_1
              then extract(epoch from (periodo.saida_1 - periodo.entrada_1)) / 3600
              else 24 + extract(epoch from (periodo.saida_1 - periodo.entrada_1)) / 3600
            end
            + case when periodo.saida_2 >= periodo.entrada_2
              then extract(epoch from (periodo.saida_2 - periodo.entrada_2)) / 3600
              else 24 + extract(epoch from (periodo.saida_2 - periodo.entrada_2)) / 3600
            end
          )::numeric, 2)
        when periodo.entrada_1 is not null and periodo.saida_1 is not null
          then round((case when periodo.saida_1 >= periodo.entrada_1
            then extract(epoch from (periodo.saida_1 - periodo.entrada_1)) / 3600
            else 24 + extract(epoch from (periodo.saida_1 - periodo.entrada_1)) / 3600
          end)::numeric, 2)
        else coalesce(hh.horas_trabalhadas, 0)::numeric
      end as horas_efetivas
    from public.hh_lancamentos as hh
    join os_base as os on os.id = hh.os_id
    cross join lateral (
      select
        coalesce(hh.entrada_1, hh.hora_entrada) as entrada_1,
        coalesce(hh.saida_1, hh.hora_saida) as saida_1,
        hh.entrada_2 as entrada_2,
        hh.saida_2 as saida_2
    ) as periodo
    where hh.tenant_id = v_tenant_id
      and hh.empresa_id = v_empresa_id
  ),
  pedido_hh_por_os as (
    select hh.os_id, round(coalesce(sum(
      case
        when (
          coalesce(hh.tem_extra_50, false)
          or coalesce(hh.tem_extra_100, false)
          or coalesce(hh.horas_extra_50, 0) > 0
          or coalesce(hh.horas_extra_100, 0) > 0
          or coalesce(hh.percentual_aplicado, 0) in (50, 100)
        ) and coalesce(hh.valor_total, 0) > 0 then hh.valor_total
        when coalesce(hh.valor_hora, 0) > 0 and hh.horas_efetivas > 0 then
          case
            when coalesce(hh.tem_extra_50, false)
              or coalesce(hh.tem_extra_100, false)
              or coalesce(hh.horas_extra_50, 0) > 0
              or coalesce(hh.horas_extra_100, 0) > 0
              then greatest(0, hh.horas_efetivas - coalesce(hh.horas_extra_50, 0) - coalesce(hh.horas_extra_100, 0)) * hh.valor_hora
                   + coalesce(hh.horas_extra_50, 0) * hh.valor_hora * 1.5
                   + coalesce(hh.horas_extra_100, 0) * hh.valor_hora * 2
            when coalesce(hh.percentual_aplicado, 0) = 50 then hh.horas_efetivas * hh.valor_hora * 1.5
            when coalesce(hh.percentual_aplicado, 0) = 100 then hh.horas_efetivas * hh.valor_hora * 2
            else hh.horas_efetivas * hh.valor_hora
          end
        else coalesce(hh.valor_total, 0)
      end
    ), 0)::numeric, 2) as pedido_hh
    from hh_horas_efetivas as hh
    group by hh.os_id
  ),
  financeiro_por_os as (
    select
      os.id,
      coalesce(materiais.materiais, 0)::numeric as materiais,
      coalesce(mao_obra.mao_obra, 0)::numeric as mao_obra,
      case
        when os.usa_relatorio_hh then coalesce(pedido_hh.pedido_hh, 0)::numeric
        else coalesce(os.orcado, 0)::numeric
      end as pedido,
      case
        when os.usa_relatorio_hh then coalesce(pedido_hh.pedido_hh, 0)::numeric * 0.15
        when os.tipo_pedido = 'material' then coalesce(os.orcado, 0)::numeric * 0.27
        else coalesce(os.orcado, 0)::numeric * 0.15
      end as impostos
    from os_base as os
    left join materiais_por_os as materiais on materiais.os_id = os.id
    left join mao_obra_por_os as mao_obra on mao_obra.os_id = os.id
    left join pedido_hh_por_os as pedido_hh on pedido_hh.os_id = os.id
  )
  select
    os.id,
    os.numero_os,
    os.os_num,
    os.cliente_nome,
    os.descricao_servico,
    os.status,
    os.usa_relatorio_hh,
    os.data_abertura,
    (os.responsavel_aprovacao_id is not distinct from v_auth_uid) as sou_responsavel,
    coalesce(horas.total_horas, 0)::numeric as total_horas,
    coalesce(
      nullif(perfil_responsavel.nome, ''),
      nullif(usuario_responsavel.nome, ''),
      nullif(colaborador_responsavel.nome, '')
    )::text as responsavel_nome,
    case
      when upper(v_papel_empresa) in ('APONTAMENTO_RH', 'APONTADOR') then null
      when (financeiro.materiais + financeiro.mao_obra + financeiro.impostos) <= 0 then 'ok'
      when (financeiro.pedido - (financeiro.materiais + financeiro.mao_obra + financeiro.impostos))
        / (financeiro.materiais + financeiro.mao_obra + financeiro.impostos) < 0 then 'prejuizo'
      when (financeiro.pedido - (financeiro.materiais + financeiro.mao_obra + financeiro.impostos))
        / (financeiro.materiais + financeiro.mao_obra + financeiro.impostos) < 0.15 then 'atencao'
      else 'ok'
    end::text as situacao_margem
  from os_base as os
  left join horas_por_os as horas on horas.os_id = os.id
  left join financeiro_por_os as financeiro on financeiro.id = os.id
  left join public.profiles as perfil_responsavel on perfil_responsavel.id = os.responsavel_aprovacao_id
  left join a.usuario as usuario_responsavel
    on usuario_responsavel.auth_user_id = os.responsavel_aprovacao_id
   and usuario_responsavel.ativo is true
   and usuario_responsavel.deleted_at is null
  left join public.colaboradores as colaborador_responsavel
    on colaborador_responsavel.user_id = os.responsavel_aprovacao_id
   and colaborador_responsavel.tenant_id = v_tenant_id
   and colaborador_responsavel.empresa_id = v_empresa_id
  order by os.data_abertura desc nulls last, os.id desc;
end;
$$;


ALTER FUNCTION "public"."app_listar_os_unfiltered_ov_20260829"("p_incluir_fechadas" boolean, "p_busca" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_listar_preferencias_notificacoes"() RETURNS TABLE("tipo" "text", "habilitada" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
  with tipos(tipo) as (
    values
      ('hora_pendente'::text), ('hora_aprovada_automaticamente'::text), ('hora_rejeitada'::text),
      ('os_concluida'::text), ('os_faturada'::text), ('os_concluida_garantia'::text),
      ('material_lancado'::text), ('os_reaberta'::text)
  )
  select tipos.tipo, coalesce(pref.habilitada, true)
  from tipos
  left join public.app_notificacoes_preferencias pref
    on pref.tenant_id = public.current_tenant_id()
   and pref.empresa_id = public.current_empresa_id()
   and pref.usuario_id = auth.uid()
   and pref.tipo = tipos.tipo
  where public.app_notificacao_contexto_valido()
  order by tipos.tipo;
$$;


ALTER FUNCTION "public"."app_listar_preferencias_notificacoes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_listar_tipos_horas"() RETURNS TABLE("id" "uuid", "nome" character varying)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_colaborador_id uuid;
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para consultar tipos de hora.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  select colaborador.id
    into v_colaborador_id
  from public.colaboradores as colaborador
  where colaborador.user_id = v_auth_uid
    and colaborador.tenant_id = v_tenant_id
    and colaborador.empresa_id = v_empresa_id
    and colaborador.ativo is true;

  if v_colaborador_id is null then
    raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
  end if;

  return query
  select tipo_hora.id, tipo_hora.descricao
  from public.tipos_horas as tipo_hora
  where tipo_hora.tenant_id = v_tenant_id
    and tipo_hora.ativo is true
  order by tipo_hora.descricao;
end;
$$;


ALTER FUNCTION "public"."app_listar_tipos_horas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_marcar_notificacao_lida"("p_notificacao_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
begin
  if not public.app_notificacao_contexto_valido() then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;
  update public.app_notificacoes
     set lida_em = coalesce(lida_em, now()), atualizado_em = now()
   where id = p_notificacao_id
     and tenant_id = public.current_tenant_id()
     and empresa_id = public.current_empresa_id()
     and usuario_id = auth.uid();
end;
$$;


ALTER FUNCTION "public"."app_marcar_notificacao_lida"("p_notificacao_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_meu_papel_empresa"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_papel text;
begin
  if v_auth_uid is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  select upper(ue.papel)
    into v_papel
  from a.usuario as u
  join a.usuario_empresa as ue
    on ue.usuario_id = u.id
   and ue.empresa_id = v_empresa_id
   and ue.ativo is true
   and ue.deleted_at is null
  where u.auth_user_id = v_auth_uid
    and u.ativo is true
    and u.deleted_at is null
  limit 1;

  if v_papel is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa.';
  end if;

  return v_papel;
end;
$$;


ALTER FUNCTION "public"."app_meu_papel_empresa"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_minhas_horas_ano"("p_ano" integer) RETURNS TABLE("mes" "date", "total_horas" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_colaborador_id uuid;
  v_ano integer := coalesce(p_ano, extract(year from current_date)::integer);
begin
  if v_auth_uid is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  if v_ano not between 2000 and 2100 then
    raise exception 'Ano inválido.';
  end if;

  select colaborador.id
    into v_colaborador_id
  from public.colaboradores as colaborador
  where colaborador.user_id = v_auth_uid
    and colaborador.tenant_id = v_tenant_id
    and colaborador.empresa_id = v_empresa_id
    and colaborador.ativo is true;

  if v_colaborador_id is null then
    raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
  end if;

  return query
  with meses as (
    select generate_series(
      make_date(v_ano, 1, 1),
      make_date(v_ano, 12, 1),
      interval '1 month'
    )::date as mes
  ),
  totais as (
    select
      date_trunc('month', apontamento.data)::date as mes,
      coalesce(sum(apontamento.horas), 0)::numeric as total_horas
    from public.apontamentos_horas as apontamento
    where apontamento.tenant_id = v_tenant_id
      and apontamento.empresa_id = v_empresa_id
      and apontamento.colaborador_id = v_colaborador_id
      and apontamento.data >= make_date(v_ano, 1, 1)
      and apontamento.data < make_date(v_ano + 1, 1, 1)
    group by date_trunc('month', apontamento.data)::date
  )
  select meses.mes, coalesce(totais.total_horas, 0)::numeric
  from meses
  left join totais on totais.mes = meses.mes
  order by meses.mes;
end;
$$;


ALTER FUNCTION "public"."app_minhas_horas_ano"("p_ano" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_minhas_horas_mes"("p_ano" integer, "p_mes" integer) RETURNS TABLE("data" "date", "os_id" integer, "codigo_os" "text", "horas" numeric, "tem_rejeitado" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_colaborador_id uuid;
  v_inicio_mes date;
begin
  if v_auth_uid is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  if p_ano is null
     or p_mes is null
     or p_ano not between 2000 and 2100
     or p_mes not between 1 and 12 then
    raise exception 'Período inválido.';
  end if;

  select colaborador.id
    into v_colaborador_id
  from public.colaboradores as colaborador
  where colaborador.user_id = v_auth_uid
    and colaborador.tenant_id = v_tenant_id
    and colaborador.empresa_id = v_empresa_id
    and colaborador.ativo is true;

  if v_colaborador_id is null then
    raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
  end if;

  v_inicio_mes := make_date(p_ano, p_mes, 1);

  return query
  select
    apontamento.data,
    os.id,
    coalesce(nullif(os.numero_os, ''), os.os_num::text, os.id::text)::text as codigo_os,
    coalesce(sum(apontamento.horas), 0)::numeric as horas,
    bool_or(apontamento.status_aprovacao = 'rejeitado') as tem_rejeitado
  from public.apontamentos_horas as apontamento
  join public.ordens_servico as os
    on os.id = apontamento.os_id
   and os.tenant_id = apontamento.tenant_id
   and os.empresa_id = apontamento.empresa_id
  where apontamento.tenant_id = v_tenant_id
    and apontamento.empresa_id = v_empresa_id
    and apontamento.colaborador_id = v_colaborador_id
    and apontamento.data >= v_inicio_mes
    and apontamento.data < (v_inicio_mes + interval '1 month')::date
  group by apontamento.data, os.id, os.numero_os, os.os_num
  order by apontamento.data, codigo_os;
end;
$$;


ALTER FUNCTION "public"."app_minhas_horas_mes"("p_ano" integer, "p_mes" integer) OWNER TO "postgres";


