CREATE OR REPLACE FUNCTION "public"."app_resumo_materiais_os_unfiltered_ov_20260829"("p_os_id" integer) RETURNS TABLE("itens_lancados" bigint, "valor_total" numeric, "pode_ver_valores" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid := public.current_empresa_id();
  v_papel text;
  v_pode_ver_valores boolean;
begin
  if v_auth_uid is null
     or v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Autenticação e contexto de empresa são obrigatórios.';
  end if;

  select upper(usuario_empresa.papel)
    into v_papel
  from a.usuario as usuario
  join a.usuario_empresa as usuario_empresa
    on usuario_empresa.usuario_id = usuario.id
   and usuario_empresa.empresa_id = v_empresa_id
   and usuario_empresa.ativo is true
   and usuario_empresa.deleted_at is null
  where usuario.auth_user_id = v_auth_uid
    and usuario.ativo is true
    and usuario.deleted_at is null
  limit 1;

  if v_papel is null then
    raise exception 'Não foi possível identificar o papel deste usuário na empresa atual.';
  end if;

  if not exists (
    select 1
    from public.ordens_servico as os
    where os.id = p_os_id
      and os.tenant_id = v_tenant_id
      and os.empresa_id = v_empresa_id
  ) then
    raise exception 'A OS informada não existe ou não pertence à empresa atual.';
  end if;

  v_pode_ver_valores := v_papel not in ('APONTAMENTO_RH', 'APONTADOR');

  return query
  select
    count(os_item.id)::bigint,
    case
      when v_pode_ver_valores then coalesce(sum(os_item.valor_total), 0)::numeric
      else null::numeric
    end,
    v_pode_ver_valores
  from public.os_itens as os_item
  join public.itens as item
    on item.id = os_item.item_id
   and item.tenant_id = os_item.tenant_id
   and item.empresa_id = os_item.empresa_id
  where os_item.os_id = p_os_id
    and os_item.tenant_id = v_tenant_id
    and os_item.empresa_id = v_empresa_id
    and item.tipo = 'produto';
end;
$$;


ALTER FUNCTION "public"."app_resumo_materiais_os_unfiltered_ov_20260829"("p_os_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."app_resumo_materiais_os_unfiltered_ov_20260829"("p_os_id" integer) IS 'Resume materiais da OS e oculta o total monetário para APONTAMENTO_RH.';



CREATE OR REPLACE FUNCTION "public"."app_resumo_mes"() RETURNS TABLE("nome_colaborador" character varying, "mes_referencia" "date", "total_horas" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_colaborador_id uuid;
  v_nome_colaborador character varying;
  v_mes_referencia date := date_trunc('month', current_date)::date;
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para consultar o resumo mensal.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();

  if v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  select colaborador.id, colaborador.nome
    into v_colaborador_id, v_nome_colaborador
  from public.colaboradores as colaborador
  where colaborador.user_id = v_auth_uid
    and colaborador.tenant_id = v_tenant_id
    and colaborador.empresa_id = v_empresa_id
    and colaborador.ativo is true;

  if v_colaborador_id is null then
    raise exception 'Seu usuário não está vinculado a um colaborador ativo nesta empresa.';
  end if;

  return query
  select
    v_nome_colaborador,
    v_mes_referencia,
    coalesce(sum(apontamento.horas), 0)::numeric
  from public.apontamentos_horas as apontamento
  where apontamento.tenant_id = v_tenant_id
    and apontamento.empresa_id = v_empresa_id
    and apontamento.colaborador_id = v_colaborador_id
    and apontamento.data >= v_mes_referencia
    and apontamento.data < (v_mes_referencia + interval '1 month')::date;
end;
$$;


ALTER FUNCTION "public"."app_resumo_mes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_verificar_feriado"("p_data" "date") RETURNS TABLE("eh_feriado" boolean, "descricao" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
declare
  v_auth_uid uuid := auth.uid();
  v_tenant_id uuid;
  v_empresa_id uuid;
begin
  if v_auth_uid is null then
    raise exception 'Autenticação obrigatória para consultar feriados.';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_empresa_id := public.current_empresa_id();
  if v_tenant_id is null
     or v_empresa_id is null
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'Não foi possível identificar um tenant e uma empresa ativos para este usuário.';
  end if;

  if p_data is null then
    return query select false, null::text;
    return;
  end if;

  return query
  select true, feriado.descricao::text
  from public.feriados feriado
  where feriado.data = p_data
  order by feriado.descricao nulls last, feriado.id
  limit 1;

  if not found then
    return query select false, null::text;
  end if;
end;
$$;


ALTER FUNCTION "public"."app_verificar_feriado"("p_data" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_fiscal_regras_em_lote"("p_somente_sem_registro" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_empresa uuid := public.current_empresa_id();
  v_count int := 0;
  r record;
begin
  if auth.uid() is null then
    raise exception 'Não autenticado';
  end if;
  if v_tenant is null then
    raise exception 'Tenant atual não definido';
  end if;
  if v_empresa is null then
    raise exception 'Empresa atual não definida';
  end if;

  if not public.has_permission('fiscal.editar') then
    raise exception 'Sem permissão: fiscal.editar';
  end if;

  for r in
    select
      i.id as item_id,
      fi.ncm as ncm_atual,
      fi.cfop_padrao as cfop_atual,
      fi.cst_icms as cst_icms_atual,
      fi.cst_pis as cst_pis_atual,
      fi.cst_cofins as cst_cofins_atual,
      fi.origem as origem_atual,
      i.tipo as tipo_item
    from public.itens i
    left join public.fiscal_itens fi
      on fi.tenant_id = v_tenant
     and fi.empresa_id = v_empresa
     and fi.item_id = i.id
    where coalesce(i.ativo, true) = true
      and (
        p_somente_sem_registro = false
        or fi.item_id is null
      )
  loop
    perform public.apply_fiscal_to_item(
      r.item_id,
      r.ncm_atual,
      r.cfop_atual,
      r.cst_icms_atual,
      r.cst_pis_atual,
      r.cst_cofins_atual,
      r.origem_atual,
      r.tipo_item
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."apply_fiscal_regras_em_lote"("p_somente_sem_registro" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_fiscal_regras_em_lote_admin"("p_tenant" "uuid", "p_empresa" "uuid", "p_somente_sem_registro" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count int := 0;
  r record;
begin
  if session_user not in ('postgres', 'service_role') then
    raise exception 'Função admin: execução não permitida para %', session_user;
  end if;

  for r in
    select
      i.id as item_id,
      fi.ncm as ncm_atual,
      fi.cfop_padrao as cfop_atual,
      fi.cst_icms as cst_icms_atual,
      fi.cst_pis as cst_pis_atual,
      fi.cst_cofins as cst_cofins_atual,
      fi.origem as origem_atual,
      i.tipo as tipo_item
    from public.itens i
    left join public.fiscal_itens fi
      on fi.tenant_id = p_tenant
     and fi.empresa_id = p_empresa
     and fi.item_id = i.id
    where coalesce(i.ativo, true) = true
      and (p_somente_sem_registro = false or fi.item_id is null)
  loop
    perform public.apply_fiscal_to_item_admin(
      p_tenant, p_empresa,
      r.item_id,
      r.ncm_atual,
      r.cfop_atual,
      r.cst_icms_atual,
      r.cst_pis_atual,
      r.cst_cofins_atual,
      r.origem_atual,
      r.tipo_item
    );

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."apply_fiscal_regras_em_lote_admin"("p_tenant" "uuid", "p_empresa" "uuid", "p_somente_sem_registro" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_fiscal_to_item"("p_item_id" integer, "p_ncm" "text" DEFAULT NULL::"text", "p_cfop" "text" DEFAULT NULL::"text", "p_cst_icms" "text" DEFAULT NULL::"text", "p_cst_pis" "text" DEFAULT NULL::"text", "p_cst_cofins" "text" DEFAULT NULL::"text", "p_origem" smallint DEFAULT NULL::smallint, "p_tipo_item" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_empresa uuid := public.current_empresa_id();
  v_regra_id uuid;
  v_regra public.fiscal_regras;
begin
  if auth.uid() is null then
    raise exception 'Não autenticado';
  end if;
  if v_tenant is null then
    raise exception 'Tenant atual não definido';
  end if;
  if v_empresa is null then
    raise exception 'Empresa atual não definida';
  end if;

  if not public.has_permission('fiscal.editar') then
    raise exception 'Sem permissão: fiscal.editar';
  end if;

  v_regra_id := public.pick_fiscal_regra(
    p_ncm, p_cfop, p_cst_icms, p_cst_pis, p_cst_cofins, p_origem, p_tipo_item
  );

  if v_regra_id is null then
    raise exception 'Nenhuma regra fiscal encontrada para o contexto informado';
  end if;

  select * into v_regra
  from public.fiscal_regras
  where id = v_regra_id;

  insert into public.fiscal_itens (
    tenant_id, empresa_id, item_id,
    ncm, origem, cfop_padrao,
    cst_icms, cst_pis, cst_cofins,
    aliq_icms, aliq_pis, aliq_cofins,
    credita_icms, credita_pis, credita_cofins,
    atualizado_em
  )
  values (
    v_tenant, v_empresa, p_item_id,
    p_ncm, v_regra.origem, v_regra.cfop,
    v_regra.cst_icms, v_regra.cst_pis, v_regra.cst_cofins,
    v_regra.aliq_icms, v_regra.aliq_pis, v_regra.aliq_cofins,
    v_regra.credita_icms, v_regra.credita_pis, v_regra.credita_cofins,
    now()
  )
  on conflict (tenant_id, empresa_id, item_id) do update set
    ncm = excluded.ncm,
    origem = excluded.origem,
    cfop_padrao = excluded.cfop_padrao,
    cst_icms = excluded.cst_icms,
    cst_pis = excluded.cst_pis,
    cst_cofins = excluded.cst_cofins,
    aliq_icms = excluded.aliq_icms,
    aliq_pis = excluded.aliq_pis,
    aliq_cofins = excluded.aliq_cofins,
    credita_icms = excluded.credita_icms,
    credita_pis = excluded.credita_pis,
    credita_cofins = excluded.credita_cofins,
    atualizado_em = now();

  -- garante consistência (não deixa crédito true com CST null)
  update public.fiscal_itens fi
     set credita_icms = false
   where fi.tenant_id = v_tenant
     and fi.empresa_id = v_empresa
     and fi.item_id = p_item_id
     and fi.credita_icms = true
     and fi.cst_icms is null;

  update public.fiscal_itens fi
     set credita_pis = false
   where fi.tenant_id = v_tenant
     and fi.empresa_id = v_empresa
     and fi.item_id = p_item_id
     and fi.credita_pis = true
     and fi.cst_pis is null;

  update public.fiscal_itens fi
     set credita_cofins = false
   where fi.tenant_id = v_tenant
     and fi.empresa_id = v_empresa
     and fi.item_id = p_item_id
     and fi.credita_cofins = true
     and fi.cst_cofins is null;

end;
$$;


ALTER FUNCTION "public"."apply_fiscal_to_item"("p_item_id" integer, "p_ncm" "text", "p_cfop" "text", "p_cst_icms" "text", "p_cst_pis" "text", "p_cst_cofins" "text", "p_origem" smallint, "p_tipo_item" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_fiscal_to_item_admin"("p_tenant" "uuid", "p_empresa" "uuid", "p_item_id" integer, "p_ncm" "text" DEFAULT NULL::"text", "p_cfop" "text" DEFAULT NULL::"text", "p_cst_icms" "text" DEFAULT NULL::"text", "p_cst_pis" "text" DEFAULT NULL::"text", "p_cst_cofins" "text" DEFAULT NULL::"text", "p_origem" smallint DEFAULT NULL::smallint, "p_tipo_item" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_regra_id uuid;
  v_regra public.fiscal_regras;
begin
  if session_user not in ('postgres', 'service_role') then
    raise exception 'Função admin: execução não permitida para %', session_user;
  end if;

  v_regra_id := public.pick_fiscal_regra_admin(
    p_tenant, p_empresa,
    p_ncm, p_cfop, p_cst_icms, p_cst_pis, p_cst_cofins, p_origem, p_tipo_item
  );

  if v_regra_id is null then
    raise exception 'Nenhuma regra fiscal encontrada para o item_id=%', p_item_id;
  end if;

  select * into v_regra
  from public.fiscal_regras
  where id = v_regra_id;

  insert into public.fiscal_itens (
    tenant_id, empresa_id, item_id,
    ncm, origem, cfop_padrao,
    cst_icms, cst_pis, cst_cofins,
    aliq_icms, aliq_pis, aliq_cofins,
    credita_icms, credita_pis, credita_cofins,
    ipi_entra_no_custo,
    atualizado_em
  )
  values (
    p_tenant, p_empresa, p_item_id,
    p_ncm, v_regra.origem, v_regra.cfop,
    v_regra.cst_icms, v_regra.cst_pis, v_regra.cst_cofins,
    v_regra.aliq_icms, v_regra.aliq_pis, v_regra.aliq_cofins,
    v_regra.credita_icms, v_regra.credita_pis, v_regra.credita_cofins,
    false,
    now()
  )
  on conflict (tenant_id, empresa_id, item_id) do update set
    ncm = excluded.ncm,
    origem = excluded.origem,
    cfop_padrao = excluded.cfop_padrao,
    cst_icms = excluded.cst_icms,
    cst_pis = excluded.cst_pis,
    cst_cofins = excluded.cst_cofins,
    aliq_icms = excluded.aliq_icms,
    aliq_pis = excluded.aliq_pis,
    aliq_cofins = excluded.aliq_cofins,
    credita_icms = excluded.credita_icms,
    credita_pis = excluded.credita_pis,
    credita_cofins = excluded.credita_cofins,
    ipi_entra_no_custo = excluded.ipi_entra_no_custo,
    atualizado_em = now();
end;
$$;


ALTER FUNCTION "public"."apply_fiscal_to_item_admin"("p_tenant" "uuid", "p_empresa" "uuid", "p_item_id" integer, "p_ncm" "text", "p_cfop" "text", "p_cst_icms" "text", "p_cst_pis" "text", "p_cst_cofins" "text", "p_origem" smallint, "p_tipo_item" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_movimentacao_estoque"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c', 'f', 'm', 'r', 'auth', 'extensions'
    AS $$
declare
  v_delta numeric;
  v_saldo_anterior numeric;
  v_custo_medio numeric;
  v_custo_entrada numeric;
  v_novo_custo numeric;
  v_data_mov timestamp without time zone;
begin
  if new.item_id is null then
    return new;
  end if;

  v_saldo_anterior := 0;
  select coalesce(e.quantidade_atual, 0)
    into v_saldo_anterior
  from public.estoque e
  where e.tenant_id = new.tenant_id
    and e.empresa_id = new.empresa_id
    and e.item_id = new.item_id
  limit 1;

  v_delta := case when new.tipo = 'saida' then -1 else 1 end * coalesce(new.quantidade, 0);

  insert into public.estoque(tenant_id, empresa_id, item_id, quantidade_atual)
  values (new.tenant_id, new.empresa_id, new.item_id, v_delta)
  on conflict (tenant_id, empresa_id, item_id) do update
    set quantidade_atual = coalesce(public.estoque.quantidade_atual, 0) + v_delta;

  if new.tipo = 'entrada' and coalesce(new.quantidade, 0) > 0 then
    select coalesce(i.custo_medio, 0)
      into v_custo_medio
    from public.itens i
    where i.id = new.item_id
      and i.tenant_id = new.tenant_id
      and i.empresa_id = new.empresa_id
    limit 1;

    v_custo_entrada := coalesce(new.custo_unitario_real, new.custo_unitario_bruto, 0);
    v_novo_custo := case
      when (v_saldo_anterior + new.quantidade) > 0
        then ((v_saldo_anterior * v_custo_medio) + (new.quantidade * v_custo_entrada)) / (v_saldo_anterior + new.quantidade)
      else v_custo_entrada
    end;

    v_data_mov := coalesce(new.data_movimentacao, now()::timestamp without time zone);

    update public.itens
    set custo_ultima_compra = v_custo_entrada,
        custo_medio = v_novo_custo,
        data_ultima_compra = v_data_mov,
        preco_unitario = case
          when new.origem_nf_entrada_id is not null and v_custo_entrada > 0
            then v_custo_entrada
          else preco_unitario
        end,
        data_atualizacao_preco = case
          when new.origem_nf_entrada_id is not null and v_custo_entrada > 0
            then v_data_mov
          else data_atualizacao_preco
        end
    where id = new.item_id
      and tenant_id = new.tenant_id
      and empresa_id = new.empresa_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."apply_movimentacao_estoque"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aprovar_apontamento"("p_apontamento_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare v_auth_uid uuid:=auth.uid(); v_tenant_id uuid:=public.current_tenant_id(); v_empresa_id uuid:=public.current_empresa_id(); v_responsavel uuid;
begin
  if v_auth_uid is null or v_tenant_id is null or v_empresa_id is null or not public.has_active_empresa_access(v_tenant_id,v_empresa_id) then raise exception 'Autenticação e contexto de empresa são obrigatórios.'; end if;
  select os.responsavel_aprovacao_id into v_responsavel from public.apontamentos_horas ah join public.ordens_servico os on os.id=ah.os_id and os.tenant_id=ah.tenant_id and os.empresa_id=ah.empresa_id where ah.id=p_apontamento_id and ah.tenant_id=v_tenant_id and ah.empresa_id=v_empresa_id for update;
  if not found then raise exception 'Apontamento não encontrado na empresa atual.'; end if;
  if v_responsavel is distinct from v_auth_uid then raise exception 'Somente o responsável da OS pode aprovar horas.'; end if;
  update public.apontamentos_horas set status_aprovacao='aprovado', aprovado_por=v_auth_uid, aprovado_em=now(), aprovado_automaticamente_em=null, rejeitado_em=null, motivo_devolucao=null where id=p_apontamento_id and tenant_id=v_tenant_id and empresa_id=v_empresa_id and status_aprovacao='pendente';
  if not found then raise exception 'O apontamento não está pendente de aprovação.'; end if;
  return jsonb_build_object('sucesso',true);
end;
$$;


ALTER FUNCTION "public"."aprovar_apontamento"("p_apontamento_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aprovar_apontamentos_vencidos"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
declare v_total integer;
begin
  update public.apontamentos_horas
  set status_aprovacao='aprovado', aprovado_por=null, aprovado_em=now(), aprovado_automaticamente_em=now(), rejeitado_em=null, motivo_devolucao=null
  where status_aprovacao='pendente' and pendente_em <= now() - interval '7 days';
  get diagnostics v_total = row_count;
  return v_total;
end;
$$;


ALTER FUNCTION "public"."aprovar_apontamentos_vencidos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_documento_operacional_os"("p_os_id" integer) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
begin
  if not exists (
    select 1
    from public.ordens_servico as os
    where os.id = p_os_id
      and os.tenant_id = public.current_tenant_id()
      and os.empresa_id = public.current_empresa_id()
