CREATE OR REPLACE FUNCTION "public"."atualizar_registro_os_item_por_movimentacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'a'
    AS $$
declare
  v_os_item_id integer;
  v_usuario_id uuid;
  v_usuario_nome text;
  v_realizado_por text := nullif(trim(new.realizado_por), '');
begin
  if new.origem_os_id is null or v_realizado_por is null then
    return new;
  end if;

  select u.auth_user_id, nullif(trim(u.nome), '')
    into v_usuario_id, v_usuario_nome
    from a.usuario u
   where u.deleted_at is null
     and (
       lower(u.email) = lower(v_realizado_por)
       or u.auth_user_id::text = v_realizado_por
     )
   order by case when lower(u.email) = lower(v_realizado_por) then 0 else 1 end
   limit 1;

  if v_usuario_id is null then
    select p.id, nullif(trim(p.nome), '')
      into v_usuario_id, v_usuario_nome
      from public.profiles p
     where lower(p.email) = lower(v_realizado_por)
        or p.id::text = v_realizado_por
     limit 1;
  end if;

  v_usuario_nome := coalesce(v_usuario_nome, v_realizado_por);

  select oi.id
    into v_os_item_id
    from public.os_itens oi
   where oi.tenant_id = new.tenant_id
     and oi.empresa_id = new.empresa_id
     and oi.os_id = new.origem_os_id
     and oi.item_id = new.item_id
     and abs(extract(epoch from (oi.criado_em - new.data_movimentacao))) <= 600
   order by
     abs(extract(epoch from (oi.criado_em - new.data_movimentacao))),
     case when abs(oi.quantidade - new.quantidade) < 0.0005 then 0 else 1 end,
     oi.id desc
   limit 1;

  if v_os_item_id is not null then
    update public.os_itens
       set registrado_por = v_usuario_id,
           registrado_por_nome = v_usuario_nome
     where id = v_os_item_id
       and tenant_id = new.tenant_id
       and empresa_id = new.empresa_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."atualizar_registro_os_item_por_movimentacao"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant uuid;
  v_uid uuid;
  v_email text;
  v_pk text;
begin
  v_uid := auth.uid();
  v_email := coalesce(auth.jwt() ->> 'email', null);

  -- tenta capturar tenant_id se existir na linha
  v_tenant := null;
  begin
    if tg_op in ('INSERT','UPDATE') then
      v_tenant := (to_jsonb(new) ->> 'tenant_id')::uuid;
    else
      v_tenant := (to_jsonb(old) ->> 'tenant_id')::uuid;
    end if;
  exception when others then
    v_tenant := null;
  end;

  -- tenta capturar PK "id" se existir
  v_pk := null;
  begin
    if tg_op in ('INSERT','UPDATE') then
      v_pk := to_jsonb(new) ->> 'id';
    else
      v_pk := to_jsonb(old) ->> 'id';
    end if;
  exception when others then
    v_pk := null;
  end;

  insert into public.audit_log(
    tenant_id, table_name, action, row_pk,
    old_data, new_data,
    actor_user_id, actor_email,
    request_id
  )
  values (
    v_tenant,
    tg_table_name,
    tg_op,
    v_pk,
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end,
    v_uid,
    v_email,
    current_setting('request.jwt.claim.jti', true)
  );

  if tg_op = 'DELETE' then
    return old;
  else
    return new;
  end if;
end;
$$;


ALTER FUNCTION "public"."audit_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_assign_empresa_segau"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
begin
  -- Pegar tenant padrão
  select id into v_tenant_id
  from public.tenants
  where ativo = true
  order by created_at asc nulls last
  limit 1;

  if v_tenant_id is null then
    return NEW;
  end if;

  -- Pegar empresa Elétrica Segau
  select id into v_empresa_id
  from public.empresas
  where tenant_id = v_tenant_id
    and (
      razao_social ilike '%segau%'
      or nome_fantasia ilike '%segau%'
    )
    and ativo = true
  limit 1;

  if v_empresa_id is null then
    return NEW;
  end if;

  -- Criar tenant membership
  insert into public.tenant_memberships (
    tenant_id,
    user_id,
    status,
    role
  ) values (
    v_tenant_id,
    NEW.id,
    'active',
    'admin'
  )
  on conflict do nothing;

  -- Criar empresa membership
  insert into public.empresa_memberships (
    tenant_id,
    empresa_id,
    user_id,
    role,
    status
  ) values (
    v_tenant_id,
    v_empresa_id,
    NEW.id,
    'user',
    'active'
  )
  on conflict do nothing;

  -- Definir contexto padrão
  insert into public.user_empresa_context (
    user_id,
    tenant_id,
    empresa_id
  ) values (
    NEW.id,
    v_tenant_id,
    v_empresa_id
  )
  on conflict (user_id, tenant_id) do update
    set empresa_id = excluded.empresa_id,
        updated_at = now();

  return NEW;
end;
$$;


ALTER FUNCTION "public"."auto_assign_empresa_segau"() OWNER TO "postgres";


