CREATE OR REPLACE FUNCTION "public"."calculate_hh_lancamento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_preco_base numeric(10,2);
  v_preco_50 numeric(10,2);
  v_preco_100 numeric(10,2);
  v_total_horas numeric(10,2);
  v_horas_normais numeric(10,2);
  v_horas_extra_50 numeric(10,2);
  v_horas_extra_100 numeric(10,2);
  v_tem_extra_manual boolean;
begin
  if NEW.entrada_1 is not null
    or NEW.saida_1 is not null
    or NEW.entrada_2 is not null
    or NEW.saida_2 is not null
  then
    if NEW.entrada_1 is null
      or NEW.saida_1 is null
      or NEW.entrada_2 is null
      or NEW.saida_2 is null
    then
      raise exception 'Preencha Entrada 1, Saida 1, Entrada 2 e Saida 2 ou deixe todos em branco.';
    end if;

    if NEW.saida_1 <= NEW.entrada_1 then
      raise exception 'Saida 1 deve ser maior que Entrada 1.';
    end if;

    if NEW.saida_2 <= NEW.entrada_2 then
      raise exception 'Saida 2 deve ser maior que Entrada 2.';
    end if;

    if NEW.saida_1 > NEW.entrada_2 then
      raise exception 'Saida 1 deve ser menor ou igual a Entrada 2.';
    end if;

    v_total_horas :=
      (extract(epoch from (NEW.saida_1 - NEW.entrada_1)) / 3600.0)
      + (extract(epoch from (NEW.saida_2 - NEW.entrada_2)) / 3600.0);

    NEW.hora_entrada := NEW.entrada_1;
    NEW.hora_saida := NEW.saida_2;
  else
    if NEW.hora_entrada is null or NEW.hora_saida is null then
      raise exception 'Preencha os horarios do lancamento HH.';
    end if;

    v_total_horas := extract(epoch from (NEW.hora_saida - NEW.hora_entrada)) / 3600.0;
    if v_total_horas < 0 then
      v_total_horas := v_total_horas + 24;
    end if;
  end if;

  v_total_horas := round(coalesce(v_total_horas, 0), 2);
  if v_total_horas <= 0 then
    raise exception 'Total de horas do lancamento HH deve ser maior que zero.';
  end if;

  NEW.horas_trabalhadas := v_total_horas;

  NEW.tem_extra_50 := coalesce(NEW.tem_extra_50, false) or coalesce(NEW.horas_extra_50, 0) > 0;
  NEW.tem_extra_100 := coalesce(NEW.tem_extra_100, false) or coalesce(NEW.horas_extra_100, 0) > 0;
  NEW.horas_extra_50 := case when NEW.tem_extra_50 then round(coalesce(NEW.horas_extra_50, 0), 2) else 0 end;
  NEW.horas_extra_100 := case when NEW.tem_extra_100 then round(coalesce(NEW.horas_extra_100, 0), 2) else 0 end;

  if NEW.horas_extra_50 < 0 or NEW.horas_extra_100 < 0 then
    raise exception 'Horas extras nao podem ser negativas.';
  end if;

  if NEW.horas_extra_50 + NEW.horas_extra_100 > v_total_horas then
    raise exception 'Horas extras nao podem exceder o total de horas do lancamento.';
  end if;

  select s.preco_base, s.preco_50, s.preco_100
    into v_preco_base, v_preco_50, v_preco_100
  from public.cliente_hh_servicos s
  where s.id = NEW.hh_servico_id
    and s.tenant_id = NEW.tenant_id
    and s.empresa_id = NEW.empresa_id
    and s.ativo = true
  limit 1;

  v_preco_base := coalesce(v_preco_base, nullif(NEW.valor_hora, 0), 0);
  v_preco_50 := coalesce(v_preco_50, round(v_preco_base * 1.5, 2));
  v_preco_100 := coalesce(v_preco_100, round(v_preco_base * 2.0, 2));

  v_tem_extra_manual := NEW.tem_extra_50 or NEW.tem_extra_100;

  if v_tem_extra_manual then
    v_horas_extra_50 := NEW.horas_extra_50;
    v_horas_extra_100 := NEW.horas_extra_100;
    v_horas_normais := v_total_horas - v_horas_extra_50 - v_horas_extra_100;
  else
    v_horas_extra_50 := case when NEW.percentual_aplicado = 50 then v_total_horas else 0 end;
    v_horas_extra_100 := case when NEW.percentual_aplicado = 100 then v_total_horas else 0 end;
    v_horas_normais := case when NEW.percentual_aplicado in (50, 100) then 0 else v_total_horas end;
  end if;

  NEW.valor_hora := round(v_preco_base, 2);
  NEW.valor_total := round(
    coalesce(v_horas_normais, 0) * coalesce(v_preco_base, 0)
    + coalesce(v_horas_extra_50, 0) * coalesce(v_preco_50, 0)
    + coalesce(v_horas_extra_100, 0) * coalesce(v_preco_100, 0),
    2
  );

  return NEW;
end;
$$;


ALTER FUNCTION "public"."calculate_hh_lancamento"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can"("p_resource" "text", "p_action" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.can(p_resource, p_action, public.current_tenant_id());
$$;


ALTER FUNCTION "public"."can"("p_resource" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can"("p_resource" "text", "p_action" "text", "p_tenant_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_empresa_id uuid;
  v_empresa_papel text;
begin
  if auth.uid() is null or p_tenant_id is null then
    return false;
  end if;

  v_empresa_id := public.current_empresa_id__by_tenant(p_tenant_id);
  v_empresa_papel := a.fn_current_empresa_papel(p_tenant_id, v_empresa_id);
  if upper(coalesce(v_empresa_papel, '')) = 'APONTADOR' then
    return false;
  end if;

  -- Usuario e qualquer alias equivalente permanecem exclusivos de OWNER/ADMIN.
  if lower(coalesce(p_resource, '')) = 'admin'
     and lower(coalesce(p_action, '')) in ('manage_users','users.manage') then
    return public.admin_can_manage_users(p_tenant_id);
  end if;

  if public.current_tenant_id() is distinct from p_tenant_id then
    return false;
  end if;

  v_empresa_id := public.current_empresa_id__by_tenant(p_tenant_id);
  if not public.has_active_empresa_access(p_tenant_id, v_empresa_id) then
    return false;
  end if;

  v_empresa_papel := a.fn_current_empresa_papel(p_tenant_id, v_empresa_id);
  if v_empresa_papel = 'DIRETOR' then
    return true;
  end if;

  if v_empresa_papel = 'FINANCEIRO'
     and lower(coalesce(p_resource, '')) = 'apontamentos'
     and lower(coalesce(p_action, '')) = 'read' then
    return coalesce(
      public.get_full_permissions(p_tenant_id, v_empresa_id)
        @> jsonb_build_object('apontamentos.read', true),
      false
    );
  end if;

  return public.can_unscoped_20260810(p_resource, p_action, p_tenant_id);
end;
$$;


ALTER FUNCTION "public"."can"("p_resource" "text", "p_action" "text", "p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can__legacy_40734"("p_resource" "text", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid;
  v_papel_empresa text;
begin
  if v_tenant_id is null then
    return false;
  end if;

  v_empresa_id := public.current_empresa_id__by_tenant(v_tenant_id);

  select upper(coalesce(ue.papel, ''))
    into v_papel_empresa
  from a.usuario u
  join a.usuario_tenant ut on ut.usuario_id = u.id
  join a.usuario_empresa ue on ue.usuario_id = u.id
  where u.auth_user_id = auth.uid()
    and u.ativo is true
    and u.deleted_at is null
    and ut.tenant_id = v_tenant_id
    and ut.ativo is true
    and ut.deleted_at is null
    and ue.empresa_id = v_empresa_id
    and ue.ativo is true
    and ue.deleted_at is null
  limit 1;

  if v_papel_empresa = 'APONTADOR' then
    return false;
  end if;

  if p_resource = 'admin' and p_action = 'manage_users' then
    return public.admin_can_manage_users(v_tenant_id);
  end if;

  if not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    return false;
  end if;

  if public.can(p_resource, p_action, v_tenant_id) then
    return true;
  end if;

  if p_resource = 'os'
     and p_action in ('read','write')
     and exists (
       select 1
       from a.usuario u
       join a.usuario_tenant ut on ut.usuario_id = u.id
       join a.usuario_empresa ue on ue.usuario_id = u.id
       where u.auth_user_id = auth.uid()
         and u.ativo is true
         and u.deleted_at is null
         and ut.tenant_id = v_tenant_id
         and ut.ativo is true
         and ut.deleted_at is null
         and ue.empresa_id = v_empresa_id
         and ue.ativo is true
         and ue.deleted_at is null
         and upper(ue.papel) in ('ADMIN','COORDENACAO','APONTAMENTO_RH')
     ) then
    return true;
  end if;

  select upper(coalesce(ue.papel, ''))
    into v_papel_empresa
  from a.usuario u
  join a.usuario_tenant ut on ut.usuario_id = u.id
  join a.usuario_empresa ue on ue.usuario_id = u.id
  where u.auth_user_id = auth.uid()
    and u.ativo is true
    and u.deleted_at is null
    and ut.tenant_id = v_tenant_id
    and ut.ativo is true
    and ut.deleted_at is null
    and ue.empresa_id = v_empresa_id
    and ue.ativo is true
    and ue.deleted_at is null
  limit 1;

  if v_papel_empresa = 'APONTADOR' then
    return false;
  end if;

  return exists (
    select 1
    from public.tenant_memberships tm
    join public.membership_roles mr on mr.membership_id = tm.id
    join public.roles r on r.id = mr.role_id
    join public.role_access_rules ar on ar.role_id = r.id
    where tm.user_id = auth.uid()
      and tm.tenant_id = v_tenant_id
      and tm.status in ('active', 'ativo')
      and (r.tenant_id is null or r.tenant_id = tm.tenant_id)
      and ar.resource = p_resource
      and ar.action = p_action
  );
end;
$$;


ALTER FUNCTION "public"."can__legacy_40734"("p_resource" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can__legacy_56548"("p_resource" "text", "p_action" "text", "p_tenant_id" "uuid" DEFAULT "public"."current_tenant_id"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  allowed boolean;
begin
  if p_tenant_id is null then
    return false;
  end if;

  -- NOVO MODELO: a.usuario_tenant (OWNER/ADMIN) -> libera tudo
  if exists (
    select 1
    from a.usuario_tenant ut
    where ut.usuario_id = auth.uid()
      and ut.tenant_id = p_tenant_id
      and ut.ativo = true
      and ut.deleted_at is null
      and ut.papel in ('OWNER','ADMIN','DIRETOR')
  ) then
    return true;
  end if;

  -- MODELO ANTIGO (mantém compatibilidade)
  select exists (
    select 1
    from public.tenant_memberships tm
    join public.membership_roles mr on mr.membership_role = tm.role
    join public.roles r on r.id = mr.role_id
    join public.role_access_rules rul on rul.role_id = r.id
    where tm.user_id = auth.uid()
      and tm.tenant_id = p_tenant_id
      and tm.status = 'active'
      and r.is_active = true
      and rul.resource = p_resource
      and rul.action = p_action
  )
  into allowed;

  return coalesce(allowed, false);
end;
$$;


ALTER FUNCTION "public"."can__legacy_56548"("p_resource" "text", "p_action" "text", "p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_many"("p_pairs" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    jsonb_object_agg(key, val),
    '{}'::jsonb
  )
  from (
    select
      case
        when elem ? 'key' then elem->>'key'
        else (elem->>'resource') || '.' || (elem->>'action')
      end as key,
      public.can(elem->>'resource', elem->>'action') as val
    from jsonb_array_elements(coalesce(p_pairs, '[]'::jsonb)) elem
    where jsonb_typeof(elem) = 'object'
  ) s;
$$;


ALTER FUNCTION "public"."can_many"("p_pairs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_many"("p_pairs" "public"."capability_pair"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id uuid;
  r public.capability_pair;
  out jsonb := '{}'::jsonb;
  allowed boolean;
begin
  v_tenant_id := public.current_tenant_id();

  foreach r in array p_pairs loop
    if v_tenant_id is null then
      allowed := false;
    else
      allowed := public.can(r.resource, r.action, v_tenant_id);
    end if;

    out := out || jsonb_build_object(r.key, allowed);
  end loop;

  return out;
end;
$$;


ALTER FUNCTION "public"."can_many"("p_pairs" "public"."capability_pair"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_unscoped_20260810"("p_resource" "text", "p_action" "text", "p_tenant_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'a', 'c'
    AS $$
declare
  v_auth_user_id uuid;
  v_usuario_id uuid;
  v_papel_tenant text;
  v_papel_empresa text;
  v_empresa_id uuid;
begin
  v_auth_user_id := auth.uid();
  if v_auth_user_id is null then
    return false;
  end if;

  select u.id
    into v_usuario_id
  from a.usuario u
  where u.auth_user_id = v_auth_user_id
    and u.ativo = true
    and u.deleted_at is null
  limit 1;

  if v_usuario_id is null then
    return false;
  end if;

  select ut.papel
    into v_papel_tenant
  from a.usuario_tenant ut
  where ut.usuario_id = v_usuario_id
    and ut.tenant_id = p_tenant_id
    and ut.ativo = true
    and ut.deleted_at is null
  order by ut.updated_at desc nulls last, ut.created_at desc nulls last
  limit 1;

  if v_papel_tenant is null then
    return false;
  end if;

  v_empresa_id := public.current_empresa_id();

  if v_empresa_id is not null then
    select upper(coalesce(ue.papel, ''))
      into v_papel_empresa
    from a.usuario_empresa ue
    where ue.usuario_id = v_usuario_id
      and ue.empresa_id = v_empresa_id
      and ue.ativo = true
      and ue.deleted_at is null
    limit 1;
  end if;

  if v_papel_empresa = 'APONTADOR' then
    return false;
  end if;

  if v_papel_tenant in ('ADMIN','DIRETOR','OWNER') then
    return true;
  end if;

  v_empresa_id := public.current_empresa_id();

  if v_empresa_id is not null then
    select ue.papel
      into v_papel_empresa
    from a.usuario_empresa ue
    where ue.usuario_id = v_usuario_id
      and ue.empresa_id = v_empresa_id
      and ue.ativo = true
      and ue.deleted_at is null
    limit 1;
  end if;

  v_papel_empresa := upper(coalesce(v_papel_empresa, ''));

  if v_papel_empresa = 'FATURAMENTO' then
    if p_resource = 'admin' and p_action = 'manage_users' then
      return false;
    end if;

    if (p_resource, p_action) in (
      values
        ('os', 'read'),
        ('os', 'write'),
        ('os', 'delete'),
        ('os_itens', 'write'),
        ('os_gestao', 'write'),
        ('os_rpcs', 'execute'),
        ('estoque', 'read'),
        ('estoque', 'write'),
        ('estoque_custos', 'cost_read'),
        ('fiscal_nf', 'read'),
        ('fiscal_nf', 'write'),
        ('fiscal_nf', 'delete'),
        ('fiscal_itens', 'write'),
        ('xml_import', 'execute'),
        ('xml_import_faturamento', 'execute'),
        ('nf_entrada', 'import'),
        ('faturamento', 'read'),
        ('faturamento', 'write'),
        ('faturamento', 'nfe.import_xml'),
        ('imobilizado', 'read'),
        ('imobilizado', 'write'),
        ('apontamentos', 'read'),
        ('apontamentos', 'write'),
        ('apontamentos', 'delete'),
        ('apontamentos', 'config'),
        ('cad_clientes', 'write'),
        ('cad_fornecedores', 'write'),
        ('cad_itens', 'write'),
        ('compras', 'read'),
        ('compras', 'write'),
        ('compras', 'approve'),
        ('compras', 'receive')
    ) then
      return true;
    end if;
  end if;

  if p_resource = 'os' and p_action = 'read' and v_papel_empresa = 'COMPRAS' then
    return true;
  end if;

  if p_resource = 'xml_import' and p_action = 'execute' then
    if v_papel_empresa in ('ALMOXARIFADO', 'APONTAMENTO_RH', 'COORDENACAO', 'FINANCEIRO', 'ADMIN') then
      return true;
    end if;
  end if;

  if p_resource = 'xml_import_faturamento' and p_action = 'execute' then
    if v_papel_empresa in ('FINANCEIRO', 'ADMIN') then
      return true;
    end if;
  end if;

  if p_resource = 'nf_entrada' and p_action = 'import' then
    if v_papel_empresa in ('ALMOXARIFADO', 'APONTAMENTO_RH', 'COORDENACAO', 'FINANCEIRO', 'ADMIN') then
      return true;
    end if;
  end if;

  if p_resource = 'faturamento' and p_action in ('read', 'write', 'nfe.import_xml') then
    if v_papel_empresa in ('FINANCEIRO', 'ADMIN') then
      return true;
    end if;
  end if;

  if p_resource = 'financeiro' and p_action in ('write', 'config') then
    if v_papel_empresa in ('ALMOXARIFADO', 'APONTAMENTO_RH', 'FINANCEIRO', 'COORDENACAO', 'ADMIN') then
      return true;
    end if;
  end if;

  if p_resource = 'estoque' and p_action = 'write' then
    if v_papel_empresa in ('ALMOXARIFADO', 'APONTAMENTO_RH', 'COMPRAS', 'COORDENACAO', 'ADMIN') then
      return true;
    end if;
  end if;

  if p_resource = 'estoque' and p_action = 'read' then
    if v_papel_empresa in ('ALMOXARIFADO', 'APONTAMENTO_RH', 'COMPRAS', 'FINANCEIRO', 'COORDENACAO', 'ADMIN') then
      return true;
    end if;
  end if;

  if p_resource = 'cad_itens' and p_action = 'write' then
    if v_papel_empresa in ('ALMOXARIFADO', 'ADMIN') then
      return true;
    end if;
  end if;

  if p_resource = 'compras' and p_action = 'read' then
    if v_papel_empresa in ('ADMIN','FINANCEIRO','COORDENACAO','COMPRAS') then
      return true;
    end if;
  end if;

  if p_resource = 'compras' and p_action = 'write' then
    if v_papel_empresa in ('ADMIN','COORDENACAO','COMPRAS') then
      return true;
    end if;
  end if;

  if p_resource = 'compras' and p_action = 'approve' then
    if v_papel_empresa in ('ADMIN','FINANCEIRO','COORDENACAO') then
      return true;
    end if;
  end if;

  if p_resource = 'compras' and p_action = 'receive' then
    if v_papel_empresa in ('ADMIN','COORDENACAO','COMPRAS') then
      return true;
    end if;
  end if;

  if p_resource = 'admin' and p_action = 'manage_users' then
    return false;
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."can_unscoped_20260810"("p_resource" "text", "p_action" "text", "p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cnpj_valido"("p_documento" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v text := regexp_replace(p_documento, '[^0-9]', '', 'g');
  v_soma integer := 0;
  v_resto integer;
  v_d1 integer;
  v_d2 integer;
  v_pesos1 integer[] := array[5,4,3,2,9,8,7,6,5,4,3,2];
  v_pesos2 integer[] := array[6,5,4,3,2,9,8,7,6,5,4,3,2];
  i integer;
begin
  if length(v) <> 14 or v ~ '^(.)\1{13}$' then
    return false;
  end if;

  for i in 1..12 loop
    v_soma := v_soma + substr(v, i, 1)::integer * v_pesos1[i];
  end loop;
  v_resto := v_soma % 11;
  v_d1 := case when v_resto < 2 then 0 else 11 - v_resto end;

  v_soma := 0;
  for i in 1..13 loop
    v_soma := v_soma + substr(v, i, 1)::integer * v_pesos2[i];
  end loop;
  v_resto := v_soma % 11;
  v_d2 := case when v_resto < 2 then 0 else 11 - v_resto end;

  return v_d1 = substr(v, 13, 1)::integer
     and v_d2 = substr(v, 14, 1)::integer;
end;
$_$;


ALTER FUNCTION "public"."cnpj_valido"("p_documento" "text") OWNER TO "postgres";


