CREATE OR REPLACE FUNCTION "public"."ensure_orcamento_item_generico"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_codigo" "text" DEFAULT '9999'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if p_empresa_id is distinct from public.current_empresa_id__by_tenant(p_tenant_id)
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not c.has_comercial_access(p_tenant_id, p_empresa_id) then
    raise exception 'not_allowed';
  end if;

  return public.ensure_orcamento_item_generico_unscoped_20260810(
    p_tenant_id, p_empresa_id, p_codigo
  );
end;
$$;


ALTER FUNCTION "public"."ensure_orcamento_item_generico"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_codigo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_orcamento_item_generico_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_codigo" "text" DEFAULT '9999'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'a'
    SET "row_security" TO 'off'
    AS $$
declare
  v_codigo text := coalesce(nullif(trim(p_codigo), ''), '9999');
  v_item_id integer;
begin
  select i.id
    into v_item_id
    from public.itens i
   where i.tenant_id = p_tenant_id
     and i.empresa_id = p_empresa_id
     and i.ativo = true
     and i.codigo_interno = v_codigo
     and i.mesclado_em_item_id is null
   order by i.id
   limit 1;

  if v_item_id is not null then
    return v_item_id;
  end if;

  insert into public.itens (
    id,
    tenant_id,
    empresa_id,
    codigo_interno,
    nome,
    descricao,
    tipo,
    finalidade,
    unidade_medida,
    controla_estoque,
    ativo,
    preco_unitario,
    custo_ultima_compra,
    created_at,
    updated_at
  )
  values (
    nextval('public.itens_id_seq'),
    p_tenant_id,
    p_empresa_id,
    v_codigo,
    'ITEM GENERICO ORCAMENTO',
    'ITEM GENERICO ORCAMENTO',
    'produto',
    'outros',
    'UN',
    false,
    true,
    0,
    0,
    now(),
    now()
  )
  returning id into v_item_id;

  return v_item_id;
end;
$$;


ALTER FUNCTION "public"."ensure_orcamento_item_generico_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_codigo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."estornar_lancamento_contabil"("p_lancamento_id" "uuid", "p_historico" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_empresa uuid := public.current_empresa_id();
  v_status text;
  v_comp uuid;
  v_comp_status text;
  v_new_id uuid;
  v_hist text;
begin
  if auth.uid() is null then
    raise exception 'Não autenticado';
  end if;
  if v_tenant is null then
    raise exception 'Tenant atual não definido';
  end if;
  if v_empresa is null then
    raise exception 'Empresa atual não definida';
  end if;

  select l.status, l.competencia_id, l.historico
    into v_status, v_comp, v_hist
  from public.lancamentos_contabeis l
  where l.id = p_lancamento_id
    and l.tenant_id = v_tenant
    and l.empresa_id = v_empresa;

  if not found then
    raise exception 'Lançamento não encontrado para este tenant/empresa';
  end if;

  if v_status <> 'confirmado' then
    raise exception 'Apenas lançamentos CONFIRMADOS podem ser estornados (status atual=%)', v_status;
  end if;

  if v_comp is not null then
    select status into v_comp_status
    from public.competencias
    where id = v_comp;

    if v_comp_status <> 'aberta' then
      raise exception 'Competência fechada. Não é permitido estornar lançamentos nesse mês.';
    end if;
  end if;

  -- cria cabeçalho do estorno
  insert into public.lancamentos_contabeis (
    tenant_id, empresa_id, competencia_id, data_lancamento,
    historico, origem_tipo, origem_id, status
  )
  select
    tenant_id, empresa_id, competencia_id, data_lancamento,
    coalesce(p_historico, 'ESTORNO: ' || historico),
    'estorno',
    p_lancamento_id::text,
    'confirmado'
  from public.lancamentos_contabeis
  where id = p_lancamento_id
  returning id into v_new_id;

  -- cria itens invertendo débito/credito
  insert into public.lancamentos_contabeis_itens (
    tenant_id, empresa_id, lancamento_id, conta_id, centro_custo_id, tipo, valor, complemento
  )
  select
    tenant_id, empresa_id, v_new_id, conta_id, centro_custo_id,
    case when tipo='debito' then 'credito' else 'debito' end,
    valor,
    coalesce(complemento,'') || ' (estorno)'
  from public.lancamentos_contabeis_itens
  where lancamento_id = p_lancamento_id;

  -- marca original como estornado
  update public.lancamentos_contabeis
     set status = 'estornado',
         atualizado_em = now()
   where id = p_lancamento_id;

  return v_new_id;
end;
$$;


ALTER FUNCTION "public"."estornar_lancamento_contabil"("p_lancamento_id" "uuid", "p_historico" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."estornar_movimentacao"("p_mov_id" integer, "p_motivo" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
begin
  select mov.tenant_id, mov.empresa_id
    into v_tenant_id, v_empresa_id
  from public.movimentacoes mov
  where mov.id = p_mov_id;

  if not found then
    raise exception 'movimentacao_not_found';
  end if;
  if v_empresa_id is distinct from public.current_empresa_id__by_tenant(v_tenant_id)
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'not_allowed';
  end if;

  return public.estornar_movimentacao_unscoped_20260810(p_mov_id, p_motivo);
end;
$$;


ALTER FUNCTION "public"."estornar_movimentacao"("p_mov_id" integer, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."estornar_movimentacao_unscoped_20260810"("p_mov_id" integer, "p_motivo" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v public.movimentacoes%rowtype;
  v_new_id int;
begin
  if auth.uid() is null then
    raise exception 'Não autenticado';
  end if;

  if not public.has_permission('estoque.movimentar') then
    raise exception 'Sem permissão: estoque.movimentar';
  end if;

  select *
  into v
  from public.movimentacoes
  where id = p_mov_id
    and tenant_id = public.current_tenant_id();

  if not found then
    raise exception 'Movimentação não encontrada no tenant atual';
  end if;

  insert into public.movimentacoes (
    tenant_id,
    item_id,
    tipo,
    quantidade,
    motivo,
    realizado_por,
    data_movimentacao,
    custo_unitario_bruto,
    custo_unitario_real,
    credito_icms,
    credito_pis,
    credito_cofins,
    origem_nf_entrada_id,
    v_ipi, v_icms, v_pis, v_cofins, v_frete_rateado,
    created_at
  ) values (
    v.tenant_id,
    v.item_id,
    'estorno',
    (v.quantidade * -1),
    coalesce(p_motivo, 'Estorno da movimentação #' || v.id),
    coalesce(v.realizado_por, auth.uid()::text),
    now(),
    v.custo_unitario_bruto,
    v.custo_unitario_real,
    (v.credito_icms * -1),
    (v.credito_pis * -1),
    (v.credito_cofins * -1),
    v.origem_nf_entrada_id,
    (v.v_ipi * -1),
    (v.v_icms * -1),
    (v.v_pis * -1),
    (v.v_cofins * -1),
    (v.v_frete_rateado * -1),
    now()
  )
  returning id into v_new_id;

  return v_new_id;
end $$;


ALTER FUNCTION "public"."estornar_movimentacao_unscoped_20260810"("p_mov_id" integer, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."estornar_nf_entrada"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_nf_entrada_id" bigint, "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'f', 'a', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
declare
  v_nf public.nf_entrada%rowtype;
  v_now timestamptz := now();
  v_executor text;
  v_documentos integer := 0;
  v_titulos integer := 0;
  v_movimentacoes integer := 0;
  v_mov record;
  v_item record;
  v_saldo numeric;
  v_quantidade_nf numeric;
  v_valor_nf numeric;
  v_custo_anterior numeric;
  v_ultimo_custo numeric;
begin
  if p_tenant_id is null or p_empresa_id is null then
    raise exception 'tenant_id e empresa_id sao obrigatorios';
  end if;
  if p_nf_entrada_id is null then
    raise exception 'nf_entrada_id obrigatorio';
  end if;
  if length(trim(coalesce(p_motivo, ''))) < 5 then
    raise exception 'Informe o motivo do estorno (minimo 5 caracteres).';
  end if;

  perform set_config('app.tenant_id', p_tenant_id::text, true);
  perform set_config('app.current_tenant_id', p_tenant_id::text, true);
  perform set_config('app.current_empresa_id', p_empresa_id::text, true);

  if auth.role() <> 'service_role' then
    if auth.uid() is null then
      raise exception 'Nao autenticado';
    end if;

    if not exists (
      select 1
      from public.tenant_memberships tm
      where tm.user_id = auth.uid()
        and tm.tenant_id = p_tenant_id
        and tm.status in ('active', 'ativo')
    ) then
      raise exception 'Tenant nao autorizado';
    end if;

    if exists (select 1 from pg_tables where schemaname = 'public' and tablename = 'empresa_memberships')
       and not exists (
         select 1
         from public.empresa_memberships em
         where em.user_id = auth.uid()
           and em.tenant_id = p_tenant_id
           and em.empresa_id = p_empresa_id
           and em.status = 'active'
       ) then
      raise exception 'Sem acesso a esta empresa';
    end if;

    if not (
      public.can('financeiro', 'write')
      or public.can('financeiro', 'config')
      or f.has_finance_access(p_tenant_id, p_empresa_id)
    ) then
      raise exception 'Sem permissao para estornar NF-e de entrada';
    end if;
  end if;

  select *
    into v_nf
  from public.nf_entrada nf
  where nf.id = p_nf_entrada_id
    and nf.tenant_id = p_tenant_id
    and nf.empresa_id = p_empresa_id
    and nf.deleted_at is null
  for update;

  if not found then
    raise exception 'NF-e de entrada nao encontrada para tenant/empresa informado.';
  end if;

  if v_nf.os_id is not null then
    raise exception 'A NF-e esta vinculada a OS %. Remova o vinculo/consumo da OS antes do estorno.', v_nf.os_id;
  end if;

  if exists (
    select 1
    from public.imobilizado_itens ii
    where ii.tenant_id = p_tenant_id
      and ii.empresa_id = p_empresa_id
      and ii.nf_entrada_id = v_nf.id
      and ii.deleted_at is null
      and ii.status <> 'IMPORTADO'
  ) then
    raise exception 'A NF-e possui item de imobilizado ja colocado em uso. Reverta-o antes do estorno.';
  end if;

  if exists (
    select 1
    from public.consumo_itens ci
    where ci.tenant_id = p_tenant_id
      and ci.empresa_id = p_empresa_id
      and ci.nf_entrada_id = v_nf.id
      and ci.deleted_at is null
      and coalesce(ci.quantidade_consumida, 0) > 0
  ) then
    raise exception 'A NF-e possui item de consumo ja utilizado. Reverta o consumo antes do estorno.';
  end if;

  if exists (
    select 1
    from public.movimentacoes m
    where m.tenant_id = p_tenant_id
      and m.empresa_id = p_empresa_id
      and m.origem_nf_entrada_id = v_nf.id
      and (m.tipo <> 'entrada' or m.origem_os_id is not null)
  ) then
    raise exception 'A NF-e possui baixa/ajuste de estoque vinculado. Reverta esse consumo antes do estorno.';
  end if;

  if exists (
    select 1
    from f.documento_fiscal df
    join f.titulo t
      on t.tenant_id = df.tenant_id
     and t.empresa_id = df.empresa_id
     and t.documento_fiscal_id = df.id
     and t.deleted_at is null
    join f.titulo_parcela tp
      on tp.tenant_id = t.tenant_id
     and tp.titulo_id = t.id
     and tp.deleted_at is null
    join f.pagamento_item pi
      on pi.tenant_id = tp.tenant_id
     and pi.titulo_parcela_id = tp.id
     and pi.deleted_at is null
    join f.pagamento p
      on p.id = pi.pagamento_id
     and p.tenant_id = t.tenant_id
     and p.empresa_id = t.empresa_id
     and p.deleted_at is null
    where df.tenant_id = p_tenant_id
      and df.empresa_id = p_empresa_id
      and df.source_nf_entrada_id = v_nf.id
      and df.deleted_at is null
  ) then
    raise exception 'A NF-e possui pagamento aplicado. Estorne o pagamento antes de excluir o lancamento.';
  end if;

  if exists (
    select 1
    from f.documento_fiscal df
    join f.titulo t
      on t.tenant_id = df.tenant_id
     and t.empresa_id = df.empresa_id
     and t.documento_fiscal_id = df.id
     and t.deleted_at is null
    where df.tenant_id = p_tenant_id
      and df.empresa_id = p_empresa_id
      and df.source_nf_entrada_id = v_nf.id
      and df.deleted_at is null
      and (
        upper(coalesce(t.status, '')) = 'PAGO'
        or abs(round(coalesce(t.valor_total, 0), 2) - round(coalesce(t.valor_aberto, 0), 2)) > 0.009
      )
  ) then
    raise exception 'A NF-e possui baixa financeira. Estorne o pagamento antes de excluir o lancamento.';
  end if;

  -- Movimentos sao imutaveis. O estorno e registrado por movimentos opostos.
  -- Para preservar o custo medio, este fluxo conservador exige que nao haja
  -- movimentacao posterior dos itens afetados.
  for v_item in
    select m.item_id, max(m.id) as ultimo_mov_nf
    from public.movimentacoes m
    where m.tenant_id = p_tenant_id
      and m.empresa_id = p_empresa_id
      and m.origem_nf_entrada_id = v_nf.id
    group by m.item_id
  loop
    if exists (
      select 1
      from public.movimentacoes posterior
      where posterior.tenant_id = p_tenant_id
        and posterior.empresa_id = p_empresa_id
        and posterior.item_id = v_item.item_id
        and posterior.id > v_item.ultimo_mov_nf
    ) then
      raise exception 'O item % possui movimentacao posterior a NF-e. Faca um estorno assistido antes de excluir.', v_item.item_id;
    end if;

    select coalesce(e.quantidade_atual, 0)
      into v_saldo
    from public.estoque e
    where e.tenant_id = p_tenant_id
      and e.empresa_id = p_empresa_id
      and e.item_id = v_item.item_id
    for update;

    select
      coalesce(sum(m.quantidade), 0),
      coalesce(sum(m.quantidade * coalesce(m.custo_unitario_real, m.custo_unitario_bruto, 0)), 0)
      into v_quantidade_nf, v_valor_nf
    from public.movimentacoes m
    where m.tenant_id = p_tenant_id
      and m.empresa_id = p_empresa_id
      and m.item_id = v_item.item_id
      and m.origem_nf_entrada_id = v_nf.id
      and m.tipo = 'entrada';

    if coalesce(v_saldo, 0) + 0.000001 < v_quantidade_nf then
      raise exception 'Saldo insuficiente para estornar o item %: saldo %, necessario %.',
        v_item.item_id, coalesce(v_saldo, 0), v_quantidade_nf;
    end if;

    select case
      when (v_saldo - v_quantidade_nf) > 0
        then greatest(0, ((v_saldo * coalesce(i.custo_medio, 0)) - v_valor_nf) / (v_saldo - v_quantidade_nf))
      else 0
    end
      into v_custo_anterior
    from public.itens i
    where i.id = v_item.item_id
      and i.tenant_id = p_tenant_id;

    select coalesce(m.custo_unitario_real, m.custo_unitario_bruto, 0)
      into v_ultimo_custo
    from public.movimentacoes m
    where m.tenant_id = p_tenant_id
      and m.empresa_id = p_empresa_id
      and m.item_id = v_item.item_id
      and m.tipo = 'entrada'
      and m.origem_nf_entrada_id is distinct from v_nf.id
    order by m.id desc
    limit 1;

    for v_mov in
      select m.*
      from public.movimentacoes m
      where m.tenant_id = p_tenant_id
        and m.empresa_id = p_empresa_id
        and m.item_id = v_item.item_id
        and m.origem_nf_entrada_id = v_nf.id
        and m.tipo = 'entrada'
      order by m.id desc
    loop
      insert into public.movimentacoes (
        tenant_id, empresa_id, item_id, tipo, quantidade, motivo,
        realizado_por, data_movimentacao,
        custo_unitario_bruto, custo_unitario_real,
        credito_icms, credito_pis, credito_cofins,
        v_ipi, v_icms, v_pis, v_cofins, v_frete_rateado,
        origem_nf_entrada_id, origem_os_id, created_at
      ) values (
        p_tenant_id, p_empresa_id, v_mov.item_id, 'saida', v_mov.quantidade,
        format('ESTORNO NF-e %s/%s (NF_ENTRADA_%s): %s', coalesce(v_nf.numero, ''), coalesce(v_nf.serie, ''), v_nf.id, trim(p_motivo)),
        coalesce(public.jwt_claim('email'), auth.uid()::text, 'service_role'), now(),
        v_mov.custo_unitario_bruto, v_mov.custo_unitario_real,
        0, 0, 0, 0, 0, 0, 0, 0,
        v_nf.id, null, now()
      );
      v_movimentacoes := v_movimentacoes + 1;
    end loop;

    update public.itens i
    set custo_medio = round(coalesce(v_custo_anterior, 0), 6),
        custo_ultima_compra = round(coalesce(v_ultimo_custo, 0), 6)
    where i.id = v_item.item_id
      and i.tenant_id = p_tenant_id;
  end loop;

  update public.imobilizado_itens
  set status = 'CANCELADO', deleted_at = v_now, updated_at = v_now, updated_by = auth.uid()
  where tenant_id = p_tenant_id
    and empresa_id = p_empresa_id
    and nf_entrada_id = v_nf.id
    and deleted_at is null;

  update public.consumo_itens
  set status = 'CANCELADO', deleted_at = v_now, updated_at = v_now, updated_by = auth.uid()
  where tenant_id = p_tenant_id
    and empresa_id = p_empresa_id
    and nf_entrada_id = v_nf.id
    and deleted_at is null;

  update f.titulo_agendamento ta
  set deleted_at = v_now, updated_at = v_now
  where ta.tenant_id = p_tenant_id
    and ta.deleted_at is null
    and exists (
      select 1 from f.titulo t
      join f.documento_fiscal df on df.id = t.documento_fiscal_id
      where t.id = ta.titulo_id
        and t.tenant_id = p_tenant_id and t.empresa_id = p_empresa_id
        and df.tenant_id = p_tenant_id and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );

  update f.titulo_aprovacao ta
  set deleted_at = v_now, updated_at = v_now
  where ta.tenant_id = p_tenant_id
    and ta.deleted_at is null
    and exists (
      select 1 from f.titulo t
      join f.documento_fiscal df on df.id = t.documento_fiscal_id
      where t.id = ta.titulo_id
        and t.tenant_id = p_tenant_id and t.empresa_id = p_empresa_id
        and df.tenant_id = p_tenant_id and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );

  update f.titulo_parcela tp
  set valor_aberto = 0, deleted_at = v_now, updated_at = v_now, updated_by = a.fn_current_usuario_id()
  where tp.tenant_id = p_tenant_id
    and tp.deleted_at is null
    and exists (
      select 1 from f.titulo t
      join f.documento_fiscal df on df.id = t.documento_fiscal_id
      where t.id = tp.titulo_id
        and t.tenant_id = p_tenant_id and t.empresa_id = p_empresa_id
        and df.tenant_id = p_tenant_id and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );

  update f.titulo_rateio tr
  set deleted_at = v_now, updated_at = v_now
  where tr.tenant_id = p_tenant_id
    and tr.deleted_at is null
    and exists (
      select 1 from f.titulo t
      join f.documento_fiscal df on df.id = t.documento_fiscal_id
      where t.id = tr.titulo_id
        and t.tenant_id = p_tenant_id and t.empresa_id = p_empresa_id
        and df.tenant_id = p_tenant_id and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );

  update f.titulo t
  set status = 'CANCELADO', valor_aberto = 0, deleted_at = v_now,
      updated_at = v_now, updated_by = a.fn_current_usuario_id()
  where t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id
    and t.deleted_at is null
    and exists (
      select 1 from f.documento_fiscal df
      where df.id = t.documento_fiscal_id
        and df.tenant_id = p_tenant_id
        and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );
  get diagnostics v_titulos = row_count;

  update f.documento_fiscal_item dfi
  set deleted_at = v_now, updated_at = v_now
  where dfi.tenant_id = p_tenant_id
    and dfi.deleted_at is null
    and exists (
      select 1 from f.documento_fiscal df
      where df.id = dfi.documento_fiscal_id
        and df.tenant_id = p_tenant_id and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );

  update f.documento_fiscal_imposto dfi
  set deleted_at = v_now, updated_at = v_now
  where dfi.tenant_id = p_tenant_id
    and dfi.deleted_at is null
    and exists (
      select 1 from f.documento_fiscal df
      where df.id = dfi.documento_fiscal_id
        and df.tenant_id = p_tenant_id and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );

  update f.documento_fiscal_xml dfx
  set deleted_at = v_now
  where dfx.tenant_id = p_tenant_id
    and dfx.deleted_at is null
    and exists (
      select 1 from f.documento_fiscal df
      where df.id = dfx.documento_fiscal_id
        and df.tenant_id = p_tenant_id and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );

  update f.imposto_retencao ir
  set deleted_at = v_now, updated_at = v_now
  where ir.tenant_id = p_tenant_id
    and ir.deleted_at is null
    and exists (
      select 1 from f.documento_fiscal df
      where df.id = ir.documento_fiscal_id
        and df.tenant_id = p_tenant_id and df.empresa_id = p_empresa_id
        and df.source_nf_entrada_id = v_nf.id
    );

  update f.documento_fiscal df
  set nfe_status = 'CANCELADA', deleted_at = v_now, updated_at = v_now,
      updated_by = a.fn_current_usuario_id()
  where df.tenant_id = p_tenant_id
    and df.empresa_id = p_empresa_id
    and df.source_nf_entrada_id = v_nf.id
    and df.deleted_at is null;
  get diagnostics v_documentos = row_count;

  update public.nf_entrada
  set deleted_at = v_now, updated_at = v_now
  where id = v_nf.id
    and tenant_id = p_tenant_id
    and empresa_id = p_empresa_id
    and deleted_at is null;

  return jsonb_build_object(
    'status', 'ESTORNADA',
    'nf_entrada_id', v_nf.id,
    'numero', v_nf.numero,
    'serie', v_nf.serie,
    'documentos_cancelados', v_documentos,
    'titulos_cancelados', v_titulos,
    'movimentacoes_estorno', v_movimentacoes,
    'estornado_em', v_now
  );
end;
$$;


ALTER FUNCTION "public"."estornar_nf_entrada"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_nf_entrada_id" bigint, "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."estornar_nf_entrada"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_nf_entrada_id" bigint, "p_motivo" "text") IS 'Estorna com rastreabilidade uma NF-e de entrada sem pagamento, consumo ou movimentacao posterior; sempre escopada por tenant e empresa.';



CREATE OR REPLACE FUNCTION "public"."faturamento_empresas_disponiveis"() RETURNS TABLE("empresa_id" "uuid", "tenant_id" "uuid", "nome_fantasia" "text", "razao_social" "text", "cnpj" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select e.id, e.tenant_id, e.nome_fantasia, e.razao_social, e.cnpj
  from public.empresas e
  where e.tenant_id = public.current_tenant_id()
    and e.ativo is true
    and public.has_active_empresa_access(e.tenant_id, e.id)
    and f.has_finance_access(e.tenant_id, e.id)
  order by coalesce(nullif(trim(e.nome_fantasia), ''), nullif(trim(e.razao_social), ''), e.id::text);
$$;


ALTER FUNCTION "public"."faturamento_empresas_disponiveis"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."faturamento_excluir_documento_saida"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_documento_fiscal_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'f', 'a'
    AS $$
declare
  v_df record;
  v_now timestamptz := now();
  v_source_nf_entrada_id bigint;
  v_legacy_key text;
begin
  if auth.uid() is null then
    raise exception 'Nao autenticado';
  end if;

  if p_tenant_id is null then
    raise exception 'tenant_id obrigatorio';
  end if;
  if p_empresa_id is null then
    raise exception 'empresa_id obrigatorio';
  end if;
  if p_documento_fiscal_id is null then
    raise exception 'documento_fiscal_id obrigatorio';
  end if;

  perform set_config('app.tenant_id', p_tenant_id::text, true);
  perform set_config('app.current_empresa_id', p_empresa_id::text, true);

  if not exists (
    select 1
    from public.tenant_memberships tm
    where tm.user_id = auth.uid()
      and tm.tenant_id = p_tenant_id
      and tm.status in ('active','ativo')
  ) then
    raise exception 'Tenant nao autorizado';
  end if;

  if exists (select 1 from pg_tables where schemaname = 'public' and tablename = 'empresa_memberships') then
    if not exists (
      select 1
      from public.empresa_memberships em
      where em.user_id = auth.uid()
        and em.tenant_id = p_tenant_id
        and em.empresa_id = p_empresa_id
        and em.status = 'active'
    ) then
      raise exception 'Sem acesso a esta empresa';
    end if;
  end if;

  if not (
    public.can('financeiro','write')
    or public.can('financeiro','config')
    or f.has_finance_access(p_tenant_id, p_empresa_id)
  ) then
    raise exception 'Sem permissao para excluir documento fiscal de faturamento';
  end if;

  select
    df.id,
    df.tenant_id,
    df.empresa_id,
    df.operacao,
    df.natureza,
    df.nfe_status,
    df.nfse_status,
    df.source_nf_entrada_id,
    df.chave_acesso
  into v_df
  from f.documento_fiscal df
  where df.id = p_documento_fiscal_id
    and df.tenant_id = p_tenant_id
    and df.empresa_id = p_empresa_id
    and df.deleted_at is null
  limit 1;

  if v_df.id is null then
    raise exception 'Documento fiscal nao encontrado para tenant/empresa informado.';
  end if;

  if coalesce(v_df.operacao, '') <> 'SAIDA' then
    raise exception 'A exclusao suportada aqui e apenas para documentos de saida.';
  end if;

  if coalesce(v_df.natureza, '') not in ('PRODUTO', 'SERVICO') then
    raise exception 'Natureza de documento nao suportada para exclusao.';
  end if;

  if exists (
    select 1
    from f.titulo t
    join f.titulo_parcela tp
      on tp.titulo_id = t.id
     and tp.tenant_id = t.tenant_id
     and tp.deleted_at is null
    join f.pagamento_item pi
      on pi.titulo_parcela_id = tp.id
     and pi.deleted_at is null
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.documento_fiscal_id = v_df.id
      and t.deleted_at is null
  ) then
    raise exception 'O documento possui recebimento/baixa no financeiro. Estorne primeiro os titulos vinculados.';
  end if;

  if exists (
    select 1
    from f.titulo t
    where t.tenant_id = p_tenant_id
      and t.empresa_id = p_empresa_id
      and t.documento_fiscal_id = v_df.id
      and t.deleted_at is null
      and (
        upper(coalesce(t.status, '')) = 'PAGO'
        or abs(round(coalesce(t.valor_total, 0), 2) - round(coalesce(t.valor_aberto, 0), 2)) > 0.009
      )
  ) then
    raise exception 'O documento possui recebimento/baixa no financeiro. Estorne primeiro os titulos vinculados.';
  end if;

  update f.titulo_agendamento ta
  set deleted_at = v_now,
      updated_at = v_now
  where ta.tenant_id = p_tenant_id
    and ta.deleted_at is null
    and exists (
      select 1
      from f.titulo t
      where t.id = ta.titulo_id
        and t.tenant_id = p_tenant_id
        and t.empresa_id = p_empresa_id
        and t.documento_fiscal_id = v_df.id
        and t.deleted_at is null
    );

  update f.titulo_aprovacao ta
  set deleted_at = v_now,
      updated_at = v_now
  where ta.tenant_id = p_tenant_id
    and ta.deleted_at is null
    and exists (
      select 1
      from f.titulo t
      where t.id = ta.titulo_id
        and t.tenant_id = p_tenant_id
        and t.empresa_id = p_empresa_id
        and t.documento_fiscal_id = v_df.id
        and t.deleted_at is null
    );

  update f.titulo_parcela tp
  set valor_aberto = 0,
      deleted_at = v_now,
      updated_at = v_now,
      updated_by = a.fn_current_usuario_id()
  where tp.tenant_id = p_tenant_id
    and tp.deleted_at is null
    and exists (
      select 1
      from f.titulo t
      where t.id = tp.titulo_id
        and t.tenant_id = p_tenant_id
        and t.empresa_id = p_empresa_id
        and t.documento_fiscal_id = v_df.id
        and t.deleted_at is null
    );

  update f.titulo_rateio tr
  set deleted_at = v_now,
      updated_at = v_now
  where tr.tenant_id = p_tenant_id
    and tr.deleted_at is null
    and exists (
      select 1
      from f.titulo t
      where t.id = tr.titulo_id
        and t.tenant_id = p_tenant_id
        and t.empresa_id = p_empresa_id
        and t.documento_fiscal_id = v_df.id
        and t.deleted_at is null
    );

  update f.titulo t
  set status = 'CANCELADO',
      valor_aberto = 0,
      deleted_at = v_now,
      updated_at = v_now,
      updated_by = a.fn_current_usuario_id()
  where t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id
    and t.documento_fiscal_id = v_df.id
    and t.deleted_at is null;

  update f.documento_fiscal_item dfi
  set deleted_at = v_now,
      updated_at = v_now
  where dfi.tenant_id = p_tenant_id
    and dfi.documento_fiscal_id = v_df.id
    and dfi.deleted_at is null;

  update f.documento_fiscal_imposto dfi
  set deleted_at = v_now,
      updated_at = v_now
  where dfi.tenant_id = p_tenant_id
    and dfi.documento_fiscal_id = v_df.id
    and dfi.deleted_at is null;

  update f.documento_fiscal_xml dfx
  set deleted_at = v_now
  where dfx.tenant_id = p_tenant_id
    and dfx.documento_fiscal_id = v_df.id
    and dfx.deleted_at is null;

  v_source_nf_entrada_id := v_df.source_nf_entrada_id;
  if v_source_nf_entrada_id is not null then
    if exists (
      select 1
      from public.movimentacoes m
      where m.tenant_id = p_tenant_id
        and m.empresa_id = p_empresa_id
        and m.origem_nf_entrada_id = v_source_nf_entrada_id
    ) then
      raise exception 'A NF-e possui movimentacoes de estoque vinculadas. Remova/estorne essas movimentacoes antes de excluir.';
    end if;

    update f.documento_fiscal
    set source_nf_entrada_id = null,
        nfe_status = 'CANCELADA',
        deleted_at = v_now,
        updated_at = v_now
    where id = v_df.id
      and tenant_id = p_tenant_id
      and empresa_id = p_empresa_id
      and deleted_at is null;

    v_legacy_key := left(coalesce((select chave from public.nf_entrada where id = v_source_nf_entrada_id), 'NFEX'), 40)
      || '#DEL#' || v_source_nf_entrada_id::text;

    update public.nf_entrada
    set chave = v_legacy_key,
        deleted_at = v_now,
        updated_at = v_now
    where id = v_source_nf_entrada_id
      and tenant_id = p_tenant_id
      and empresa_id = p_empresa_id;
  else
    update f.documento_fiscal
    set
      nfe_status = case when coalesce(v_df.natureza, '') = 'PRODUTO' then 'CANCELADA' else nfe_status end,
      nfse_status = case when coalesce(v_df.natureza, '') = 'SERVICO' then 'CANCELADA' else nfse_status end,
      deleted_at = v_now,
      updated_at = v_now
    where id = v_df.id
      and tenant_id = p_tenant_id
      and empresa_id = p_empresa_id
      and deleted_at is null;
  end if;

  return v_df.id;
end;
$$;


ALTER FUNCTION "public"."faturamento_excluir_documento_saida"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_documento_fiscal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."faturamento_sync_titulo_ar_parcelas"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_documento_fiscal_id" "uuid", "p_parcelas_json" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'f', 'a'
    AS $$
declare
  v_df record;
  v_titulo_id uuid;
  v_parcelas jsonb := coalesce(p_parcelas_json, '[]'::jsonb);
  v_i int := 0;
  v_el jsonb;
  v_num text;
  v_venc date;
  v_val numeric(15,2);
  v_soma numeric(15,2) := 0;
  v_tem_recebimento boolean := false;
  v_venc_padrao date;
begin
  if auth.uid() is null then
    raise exception 'Nao autenticado';
  end if;

  if p_tenant_id is null then
    raise exception 'tenant_id obrigatorio';
  end if;
  if p_empresa_id is null then
    raise exception 'empresa_id obrigatorio';
  end if;
  if p_documento_fiscal_id is null then
    raise exception 'documento_fiscal_id obrigatorio';
  end if;

  perform set_config('app.tenant_id', p_tenant_id::text, true);
  perform set_config('app.current_empresa_id', p_empresa_id::text, true);

  if not exists (
    select 1
    from public.tenant_memberships tm
    where tm.user_id = auth.uid()
      and tm.tenant_id = p_tenant_id
      and tm.status in ('active','ativo')
  ) then
    raise exception 'Tenant nao autorizado';
  end if;

  if exists (select 1 from pg_tables where schemaname = 'public' and tablename = 'empresa_memberships') then
    if not exists (
      select 1
      from public.empresa_memberships em
      where em.user_id = auth.uid()
        and em.tenant_id = p_tenant_id
        and em.empresa_id = p_empresa_id
        and em.status = 'active'
    ) then
      raise exception 'Sem acesso a esta empresa';
    end if;
  end if;

  if not (
    public.can('xml_import','execute')
    or public.can('xml_import_faturamento','execute')
    or f.has_finance_access(p_tenant_id, p_empresa_id)
  ) then
    raise exception 'Sem permissao para gerar contas a receber';
  end if;

  select
    df.id,
    df.tenant_id,
    df.empresa_id,
    df.cliente_id,
    df.emissao_date,
    df.competencia_date,
    coalesce(df.valor_total, 0)::numeric(15,2) as valor_total,
    df.modelo,
    df.numero,
    df.serie,
    df.natureza,
    df.operacao,
    df.nfe_status,
    df.nfse_status
  into v_df
  from f.documento_fiscal df
  where df.id = p_documento_fiscal_id
    and df.tenant_id = p_tenant_id
    and df.empresa_id = p_empresa_id
    and df.operacao = 'SAIDA'
    and df.natureza in ('PRODUTO', 'SERVICO')
    and df.deleted_at is null
  limit 1;

  if v_df.id is null then
    raise exception 'Documento fiscal nao encontrado para tenant/empresa informado.';
  end if;

  if v_df.cliente_id is null then
    raise exception 'cliente_id obrigatorio para gerar contas a receber.';
  end if;

  if v_df.natureza = 'SERVICO' and coalesce(v_df.nfse_status, '') <> 'EMITIDA' then
    raise exception 'NFS-e precisa estar EMITIDA para sincronizar contas a receber.';
  end if;

  if v_df.natureza = 'PRODUTO' and coalesce(v_df.nfe_status, '') <> 'EMITIDA' then
    raise exception 'NF-e precisa estar EMITIDA para sincronizar contas a receber.';
  end if;

  select t.id
    into v_titulo_id
  from f.titulo t
  where t.tenant_id = p_tenant_id
    and t.empresa_id = p_empresa_id
    and t.tipo = 'AR'
    and t.documento_fiscal_id = v_df.id
    and t.deleted_at is null
  limit 1;

  if v_titulo_id is null then
    if v_df.natureza = 'SERVICO' then
      v_titulo_id := f.fn_upsert_ar_from_documento_fiscal_v2(v_df.id, null);
    else
      v_titulo_id := f.fn_upsert_ar_from_nfe_venda(v_df.id, null);
    end if;
  end if;

  if v_titulo_id is null then
    raise exception 'Nao foi possivel localizar/gerar o titulo AR.';
  end if;

  select exists (
    select 1
    from f.titulo_parcela tp
    join f.pagamento_item pi
      on pi.titulo_parcela_id = tp.id
     and pi.deleted_at is null
    where tp.tenant_id = p_tenant_id
      and tp.titulo_id = v_titulo_id
      and tp.deleted_at is null
  ) into v_tem_recebimento;

  if coalesce(v_tem_recebimento, false) then
    raise exception 'Nao e possivel ajustar parcelas: titulo ja possui recebimentos aplicados.';
  end if;

  update f.titulo_parcela
  set deleted_at = now(),
      updated_at = now(),
      updated_by = a.fn_current_usuario_id()
  where tenant_id = p_tenant_id
    and titulo_id = v_titulo_id
    and deleted_at is null;

  if jsonb_typeof(v_parcelas) = 'array' and jsonb_array_length(v_parcelas) > 0 then
    for v_el in select * from jsonb_array_elements(v_parcelas)
    loop
      v_num := coalesce(nullif(trim(v_el->>'numero'),''), lpad((v_i+1)::text, 3, '0'));
      v_num := regexp_replace(v_num, '\D', '', 'g');
      if v_num is null or v_num = '' then
        v_num := lpad((v_i+1)::text, 3, '0');
      else
        v_num := lpad(v_num, 3, '0');
      end if;

      v_venc := coalesce(nullif(trim(v_el->>'vencimento'), '')::date, nullif(trim(v_el->>'data'), '')::date);
      v_val := round(coalesce(nullif(trim(v_el->>'valor'), '')::numeric, 0), 2);

      if v_venc is null then
        raise exception 'Parcela sem data de vencimento (numero=%).', v_num;
      end if;
      if v_val <= 0 then
        raise exception 'Parcela com valor invalido (numero=% valor=%).', v_num, v_val;
      end if;

      insert into f.titulo_parcela (
        tenant_id,
        titulo_id,
        numero,
        vencimento_date,
        valor,
        valor_aberto
      )
      values (
        p_tenant_id,
        v_titulo_id,
        v_num,
        v_venc,
        v_val,
        v_val
      );

      v_soma := round(v_soma + v_val, 2);
      v_i := v_i + 1;
    end loop;

    if abs(v_soma - v_df.valor_total) > 0.05 then
      raise exception 'Soma das parcelas (%) difere do total do documento (%).', v_soma, v_df.valor_total;
    end if;
  else
    v_venc_padrao := coalesce(v_df.emissao_date, current_date) + 15;

    insert into f.titulo_parcela (
      tenant_id,
      titulo_id,
      numero,
      vencimento_date,
      valor,
      valor_aberto
    )
    values (
      p_tenant_id,
      v_titulo_id,
      '001',
      v_venc_padrao,
      v_df.valor_total,
      v_df.valor_total
    );
  end if;

  update f.titulo t
  set cliente_id = v_df.cliente_id,
      emissao_date = v_df.emissao_date,
      competencia_date = v_df.competencia_date,
      valor_total = v_df.valor_total,
      valor_aberto = case
        when coalesce(t.status, '') in ('PAGO', 'CANCELADO') then t.valor_aberto
        else (
          select coalesce(sum(tp.valor_aberto), 0)
          from f.titulo_parcela tp
          where tp.tenant_id = p_tenant_id
            and tp.titulo_id = v_titulo_id
            and tp.deleted_at is null
        )
      end,
      updated_at = now(),
      updated_by = a.fn_current_usuario_id()
  where t.id = v_titulo_id
    and t.tenant_id = p_tenant_id
    and t.deleted_at is null;

  return v_titulo_id;
end;
$$;


ALTER FUNCTION "public"."faturamento_sync_titulo_ar_parcelas"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_documento_fiscal_id" "uuid", "p_parcelas_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fechar_competencia"("p_ano" integer, "p_mes" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_empresa uuid := public.current_empresa_id();
  v_competencia_date date := make_date(p_ano, p_mes, 1);
begin
  if auth.uid() is null then
    raise exception 'Não autenticado';
  end if;

  if v_tenant is null then
    raise exception 'Tenant atual não definido';
  end if;

  if v_empresa is null then
    raise exception 'Empresa atual não definido';
  end if;

  -- upsert: cria/fecha em um passo
  insert into public.competencias (
    tenant_id, empresa_id, ano, mes,
    status, fechada_em, fechada_por, atualizado_em
  )
  values (
    v_tenant, v_empresa, p_ano, p_mes,
    'fechada', now(), auth.uid(), now()
  )
  on conflict (tenant_id, empresa_id, ano, mes) do update
  set
    status = 'fechada',
    fechada_em = coalesce(public.competencias.fechada_em, excluded.fechada_em),
    fechada_por = coalesce(public.competencias.fechada_por, excluded.fechada_por),
    atualizado_em = now();

  -- Hook IRPJ/CSLL (não bloqueia fechamento)
  begin
    perform f.fn_irpj_csll_ao_fechar_competencia(v_tenant, v_empresa, v_competencia_date);
  exception when others then
    raise notice 'Fechamento: hook IRPJ/CSLL falhou na competência %: %', v_competencia_date, sqlerrm;
  end;
end;
$$;


ALTER FUNCTION "public"."fechar_competencia"("p_ano" integer, "p_mes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fechar_competencia_admin"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_ano" integer, "p_mes" integer, "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_competencia_date date := make_date(p_ano, p_mes, 1);
begin
  insert into public.competencias (
    tenant_id, empresa_id, ano, mes,
    status, fechada_em, fechada_por, atualizado_em
  )
  values (
    p_tenant_id, p_empresa_id, p_ano, p_mes,
    'fechada', now(), p_user_id, now()
  )
  on conflict (tenant_id, empresa_id, ano, mes) do update
  set
    status = 'fechada',
    -- não sobrescreve quem/ quando fechou se já estava fechado
    fechada_em = coalesce(public.competencias.fechada_em, excluded.fechada_em),
    fechada_por = coalesce(public.competencias.fechada_por, excluded.fechada_por),
    atualizado_em = now();

  -- Hook IRPJ/CSLL (não bloqueia)
  begin
    perform f.fn_irpj_csll_ao_fechar_competencia(p_tenant_id, p_empresa_id, v_competencia_date);
  exception when others then
    raise notice 'Fechamento admin: hook IRPJ/CSLL falhou na competência %: %', v_competencia_date, sqlerrm;
  end;
end;
$$;


ALTER FUNCTION "public"."fechar_competencia_admin"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_ano" integer, "p_mes" integer, "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_apontamento_bloquear_duplicidade"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_horas_existentes numeric;
begin
  -- Scripts e manutenção com service role não entram nesta proteção.
  if auth.uid() is null or coalesce(new.gerado_por_hh, false) then
    return new;
  end if;

  select ah.horas
    into v_horas_existentes
  from public.apontamentos_horas ah
  where ah.os_id = new.os_id
    and ah.colaborador_id = new.colaborador_id
    and ah.data = new.data
    and ah.tipo_hora_id = new.tipo_hora_id
    and ah.gerado_por_hh = false
  order by ah.criado_em asc
  limit 1;

  if found then
    raise exception using
      errcode = '23505',
      message = format(
        'Já existe um apontamento normal de %s hora(s) em %s para esta OS, colaborador e tipo de hora. Para corrigir, edite o lançamento existente.',
        replace(v_horas_existentes::text, '.', ','),
        to_char(new.data, 'DD/MM/YYYY')
      );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_apontamento_bloquear_duplicidade"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_apontamento_bloquear_fechado"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_apontamento_bloquear_fechado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_apontamento_preparar_aprovacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'auth'
    AS $$
declare
  v_papel_criador text;
  v_editou boolean := false;
  v_exige_aprovacao boolean;
begin
  if tg_op = 'INSERT' then
    new.criado_por_user_id := coalesce(new.criado_por_user_id, auth.uid());
  else
    v_editou := row(
      new.data, new.horas, new.tipo_hora_id, new.fator_aplicado, new.descricao,
      new.hora_entrada_1, new.hora_saida_1, new.hora_entrada_2, new.hora_saida_2
    ) is distinct from row(
      old.data, old.horas, old.tipo_hora_id, old.fator_aplicado, old.descricao,
      old.hora_entrada_1, old.hora_saida_1, old.hora_entrada_2, old.hora_saida_2
    );

    -- Aprovar, rejeitar ou executar outra atualização técnica não recalcula o
    -- status. Somente um novo lançamento ou a edição das horas o faz.
    if not v_editou then
      return new;
    end if;
  end if;

  select upper(usuario_empresa.papel)
    into v_papel_criador
  from a.usuario as usuario
  join a.usuario_empresa as usuario_empresa
    on usuario_empresa.usuario_id = usuario.id
   and usuario_empresa.empresa_id = new.empresa_id
   and usuario_empresa.ativo is true
   and usuario_empresa.deleted_at is null
  where usuario.auth_user_id = new.criado_por_user_id
    and usuario.ativo is true
    and usuario.deleted_at is null
  limit 1;

  -- Papel desconhecido é mantido pendente por segurança.
  v_exige_aprovacao := coalesce(v_papel_criador, '') in ('APONTAMENTO_RH', 'APONTADOR')
    or v_papel_criador is null;

  if v_exige_aprovacao then
    new.status_aprovacao := 'pendente';
    new.pendente_em := case when tg_op = 'UPDATE' then now() else coalesce(new.pendente_em, now()) end;
    new.aprovado_por := null;
    new.aprovado_em := null;
    new.aprovado_automaticamente_em := null;
    new.rejeitado_em := null;
    new.motivo_devolucao := null;
  else
    new.status_aprovacao := 'aprovado';
    new.pendente_em := null;
    new.aprovado_por := new.criado_por_user_id;
    new.aprovado_em := now();
    new.aprovado_automaticamente_em := now();
    new.rejeitado_em := null;
    new.motivo_devolucao := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_apontamento_preparar_aprovacao"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_apontamento_registrar_evento_aprovacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_evento text;
  v_motivo text;
begin
  if tg_op = 'INSERT' then
    v_evento := case
      when new.status_aprovacao = 'pendente' then 'pendente'
      when new.gerado_por_hh then 'aprovado_hh'
      when new.aprovado_automaticamente_em is not null then 'aprovado_automaticamente'
      else 'aprovado'
    end;
  elsif old.status_aprovacao is distinct from new.status_aprovacao then
    v_evento := case new.status_aprovacao
      when 'pendente' then 'pendente'
      when 'aprovado' then case when new.aprovado_automaticamente_em is not null then 'aprovado_automaticamente' else 'aprovado' end
      when 'rejeitado' then 'rejeitado'
    end;
  else
    return new;
  end if;

  v_motivo := case when v_evento = 'rejeitado' then new.motivo_devolucao else null end;
  insert into public.apontamentos_horas_aprovacao_eventos (
    tenant_id, empresa_id, apontamento_id, evento, realizado_por, motivo
  ) values (
    new.tenant_id, new.empresa_id, new.id, v_evento, auth.uid(), v_motivo
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_apontamento_registrar_evento_aprovacao"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_apontamento_validar_aprovacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_executor uuid := auth.uid();
  v_user_id_colaborador uuid;
begin
  -- Scripts e manutenção podem aprovar sem carimbo automático de usuário.
  if v_executor is null then
    return new;
  end if;

  if new.status = 'aprovado' then
    select c.user_id
      into v_user_id_colaborador
    from public.colaboradores c
    where c.id = new.colaborador_id;

    if v_user_id_colaborador is not null and v_user_id_colaborador = v_executor then
      raise exception using
        errcode = '42501',
        message = 'Autoaprovação não é permitida: o colaborador não pode aprovar o próprio apontamento.';
    end if;

    if tg_op = 'INSERT' or old.status is distinct from new.status then
      new.aprovado_por := v_executor;
      new.aprovado_em := now();
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_apontamento_validar_aprovacao"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_app_notificar_apontamento_horas"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_responsavel uuid;
  v_destinatario uuid;
  v_os_numero text;
  v_dados jsonb;
begin
  if coalesce(new.gerado_por_hh, false) then
    return new;
  end if;

  select os.responsavel_aprovacao_id,
         coalesce(nullif(btrim(os.numero_os), ''), os.os_num::text, os.id::text)
    into v_responsavel, v_os_numero
  from public.ordens_servico os
  where os.id = new.os_id
    and os.tenant_id = new.tenant_id
    and os.empresa_id = new.empresa_id;

  v_dados := jsonb_build_object(
    'os_id', new.os_id,
    'apontamento_id', new.id,
    'url', '/os/' || new.os_id::text
  );

  if tg_op = 'INSERT' and new.status_aprovacao = 'pendente' then
    perform public.app_criar_notificacao(
      new.tenant_id, new.empresa_id, v_responsavel, 'hora_pendente',
      'Hora pendente de aprovação',
      format('Há uma hora lançada na OS %s aguardando sua aprovação.', v_os_numero),
      jsonb_set(v_dados, '{url}', '"/(tabs)/aprovacao"'::jsonb), 'hora_pendente'
    );
  elsif tg_op = 'UPDATE'
    and old.status_aprovacao is distinct from new.status_aprovacao
    and new.status_aprovacao = 'aprovado'
    and new.aprovado_automaticamente_em is not null then
    foreach v_destinatario in array array_remove(array[v_responsavel, new.criado_por_user_id], null)
    loop
      perform public.app_criar_notificacao(
        new.tenant_id, new.empresa_id, v_destinatario, 'hora_aprovada_automaticamente',
        'Hora aprovada automaticamente',
        format('A hora lançada na OS %s foi aprovada após 7 dias.', v_os_numero),
        v_dados, null
      );
    end loop;
  elsif tg_op = 'UPDATE'
    and old.status_aprovacao is distinct from new.status_aprovacao
    and new.status_aprovacao = 'rejeitado' then
    perform public.app_criar_notificacao(
      new.tenant_id, new.empresa_id, new.criado_por_user_id, 'hora_rejeitada',
      'Hora rejeitada',
      format('A hora lançada na OS %s foi rejeitada. Motivo: %s', v_os_numero, coalesce(new.motivo_devolucao, 'não informado')),
      v_dados, null
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_app_notificar_apontamento_horas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_app_notificar_fluxo_os"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_numero_os text := coalesce(nullif(btrim(new.numero_os), ''), new.os_num::text, new.id::text);
  v_dados jsonb := jsonb_build_object('os_id', new.id, 'url', '/os/' || new.id::text);
begin
  if old.status_fluxo is not distinct from new.status_fluxo then
    return new;
  end if;

  if new.status_fluxo = 'concluida' then
    perform public.app_notificar_usuarios_por_papel(
      new.tenant_id, new.empresa_id, array['ADMIN', 'DIRETOR', 'FINANCEIRO'], 'os_concluida',
      'OS concluída', format('A OS %s está pronta para faturamento.', v_numero_os), v_dados, 'os_concluida'
    );
  elsif new.status_fluxo = 'faturada' then
    perform public.app_notificar_usuarios_por_papel(
      new.tenant_id, new.empresa_id, array['ADMIN', 'DIRETOR'], 'os_faturada',
      'OS faturada', format('A OS %s foi faturada.', v_numero_os), v_dados, 'os_faturada'
    );
    perform public.app_criar_notificacao(
      new.tenant_id, new.empresa_id, new.responsavel_aprovacao_id, 'os_faturada',
      'OS faturada', format('A OS %s foi faturada.', v_numero_os), v_dados, 'os_faturada'
    );
  elsif new.status_fluxo = 'concluida_garantia' then
    perform public.app_notificar_usuarios_por_papel(
      new.tenant_id, new.empresa_id, array['ADMIN', 'DIRETOR'], 'os_concluida_garantia',
      'Garantia concluída', format('O atendimento de garantia da OS %s foi concluído sem cobrança.', v_numero_os), v_dados, 'os_concluida_garantia'
    );
    perform public.app_criar_notificacao(
      new.tenant_id, new.empresa_id, new.responsavel_aprovacao_id, 'os_concluida_garantia',
      'Garantia concluída', format('O atendimento de garantia da OS %s foi concluído sem cobrança.', v_numero_os), v_dados, 'os_concluida_garantia'
    );
  elsif new.status_fluxo in ('em_andamento', 'em_andamento_garantia')
    and old.status_fluxo in ('concluida', 'faturada') then
    perform public.app_notificar_usuarios_por_papel(
      new.tenant_id, new.empresa_id, array['ADMIN', 'DIRETOR'], 'os_reaberta',
      'OS reaberta', format('A OS %s voltou para Em andamento.', v_numero_os), v_dados, 'os_reaberta'
    );
    perform public.app_criar_notificacao(
      new.tenant_id, new.empresa_id, new.responsavel_aprovacao_id, 'os_reaberta',
      'OS reaberta', format('A OS %s voltou para Em andamento.', v_numero_os), v_dados, 'os_reaberta'
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_app_notificar_fluxo_os"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_app_notificar_material_lancado"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_responsavel uuid;
  v_numero_os text;
  v_url text;
begin
  -- A RPC do app grava esta origem; movimentacoes criadas pela web/importacao
  -- nao disparam a notificacao definida para o tecnico no mobile.
  if new.origem_os_id is null or new.tipo <> 'saida'
     or new.motivo not like 'Material lançado pelo app na OS %' then
    return new;
  end if;

  select os.responsavel_aprovacao_id,
         coalesce(nullif(btrim(os.numero_os), ''), os.os_num::text, os.id::text)
    into v_responsavel, v_numero_os
  from public.ordens_servico os
  where os.id = new.origem_os_id
    and os.tenant_id = new.tenant_id
    and os.empresa_id = new.empresa_id;

  v_url := '/os/' || new.origem_os_id::text || '/material';
  perform public.app_criar_notificacao(
    new.tenant_id, new.empresa_id, v_responsavel, 'material_lancado',
    'Material lançado na OS', format('Foi lançado material na OS %s.', v_numero_os),
    jsonb_build_object('os_id', new.origem_os_id, 'url', v_url), 'material_lancado'
  );
  return new;
end;
$$;


