CREATE OR REPLACE FUNCTION "public"."fn_atualiza_estoque_por_mov"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c', 'f', 'm', 'r', 'auth', 'extensions'
    AS $$
declare
  v_delta numeric;
  v_qtd   numeric;
begin
  if new.empresa_id is null then
    raise exception 'empresa_id obrigatório na movimentação (tenant_id=%, item_id=%)', new.tenant_id, new.item_id;
  end if;

  v_delta :=
    case new.tipo
      when 'entrada' then coalesce(new.quantidade, 0)
      when 'saida'   then -coalesce(new.quantidade, 0)
      when 'ajuste'  then coalesce(new.quantidade, 0)
      else null
    end;

  if v_delta is null then
    raise exception 'Tipo de movimentação inválido: %', new.tipo;
  end if;

  -- garante linha no estoque (tenant+empresa+item)
  insert into public.estoque (tenant_id, empresa_id, item_id, quantidade_atual, atualizado_em)
  values (new.tenant_id, new.empresa_id, new.item_id, 0, now())
  on conflict on constraint estoque_tenant_empresa_item_key do nothing;

  -- atualiza e captura novo saldo
  update public.estoque
     set quantidade_atual = quantidade_atual + v_delta,
         atualizado_em = now()
   where tenant_id  = new.tenant_id
     and empresa_id = new.empresa_id
     and item_id    = new.item_id
   returning quantidade_atual into v_qtd;

  if v_qtd < 0 then
    raise exception
      'Estoque não pode ficar negativo (tenant_id=%, empresa_id=%, item_id=%, saldo=%)',
      new.tenant_id, new.empresa_id, new.item_id, v_qtd;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_atualiza_estoque_por_mov"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auditar_ap_por_nf_entrada_range"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_comp_ini" "date", "p_comp_fim" "date") RETURNS TABLE("tenant_id" "uuid", "empresa_id" "uuid", "source_nf_entrada_id" bigint, "documento_fiscal_id" "uuid", "competencia_date" "date", "emissao_date" "date", "chave_acesso" "text", "doc_valor_total" numeric, "titulo_id" "uuid", "titulo_status" "text", "titulo_origem" "text", "titulo_valor_total" numeric, "titulo_valor_aberto" numeric, "titulo_deleted_at" timestamp with time zone, "parcelas_count" bigint, "parcelas_total" numeric, "has_issue" boolean, "issue_codes" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'f', 'a', 'c'
    SET "row_security" TO 'off'
    AS $$
with docs as (
  select
    df.tenant_id,
    df.empresa_id,
    df.source_nf_entrada_id,
    df.id as documento_fiscal_id,
    df.competencia_date,
    df.emissao_date,
    df.chave_acesso,
    coalesce(df.valor_total, 0)::numeric as doc_valor_total
  from f.documento_fiscal df
  where df.tenant_id = p_tenant_id
    and df.empresa_id = p_empresa_id
    and df.deleted_at is null
    and df.operacao = 'ENTRADA'
    and df.natureza = 'PRODUTO'
    and df.source_nf_entrada_id is not null
    and df.competencia_date >= p_comp_ini
    and df.competencia_date < p_comp_fim
),
t as (
  select
    d.documento_fiscal_id,
    t.id as titulo_id,
    t.status as titulo_status,
    t.origem as titulo_origem,
    coalesce(t.valor_total, 0)::numeric as titulo_valor_total,
    coalesce(t.valor_aberto, 0)::numeric as titulo_valor_aberto,
    t.deleted_at as titulo_deleted_at
  from docs d
  left join lateral (
    select x.*
    from f.titulo x
    where x.tenant_id = d.tenant_id
      and x.empresa_id = d.empresa_id
      and x.tipo = 'AP'
      and x.documento_fiscal_id = d.documento_fiscal_id
    order by (x.deleted_at is null) desc, x.created_at desc
    limit 1
  ) t on true
),
p as (
  select
    t.documento_fiscal_id,
    count(tp.*)::bigint as parcelas_count,
    coalesce(sum(tp.valor), 0)::numeric as parcelas_total
  from t
  left join f.titulo_parcela tp
    on tp.titulo_id = t.titulo_id
   and tp.tenant_id = p_tenant_id
   and tp.deleted_at is null
  group by t.documento_fiscal_id
)
select
  d.tenant_id,
  d.empresa_id,
  d.source_nf_entrada_id,
  d.documento_fiscal_id,
  d.competencia_date,
  d.emissao_date,
  d.chave_acesso,
  d.doc_valor_total,
  t.titulo_id,
  t.titulo_status,
  t.titulo_origem,
  t.titulo_valor_total,
  t.titulo_valor_aberto,
  t.titulo_deleted_at,
  coalesce(p.parcelas_count, 0) as parcelas_count,
  coalesce(p.parcelas_total, 0) as parcelas_total,
  (
    t.titulo_id is null
    or t.titulo_deleted_at is not null
    or coalesce(p.parcelas_count, 0) = 0
    or abs(coalesce(p.parcelas_total, 0) - coalesce(d.doc_valor_total, 0)) > 0.05
  ) as has_issue,
  concat_ws(
    ',',
    case when t.titulo_id is null then 'MISSING_TITULO' end,
    case when t.titulo_deleted_at is not null then 'TITULO_SOFT_DELETED' end,
    case when t.titulo_id is not null and coalesce(p.parcelas_count, 0) = 0 then 'MISSING_PARCELAS' end,
    case when t.titulo_id is not null and abs(coalesce(p.parcelas_total, 0) - coalesce(d.doc_valor_total, 0)) > 0.05 then 'PARCELAS_TOTAL_DIFF' end
  ) as issue_codes
from docs d
left join t on t.documento_fiscal_id = d.documento_fiscal_id
left join p on p.documento_fiscal_id = d.documento_fiscal_id
order by d.competencia_date asc, d.documento_fiscal_id asc;
$$;


ALTER FUNCTION "public"."fn_auditar_ap_por_nf_entrada_range"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_comp_ini" "date", "p_comp_fim" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_backfill_movimentacoes_nf_entrada"("p_nf_entrada_id" bigint) RETURNS TABLE("rows_inserted" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_nf public.nf_entrada%rowtype;
  v_rows integer := 0;
begin
  if p_nf_entrada_id is null then
    raise exception 'p_nf_entrada_id obrigatorio';
  end if;

  select *
    into v_nf
  from public.nf_entrada
  where id = p_nf_entrada_id
  limit 1;

  if v_nf.id is null then
    raise exception 'NF de entrada nao encontrada (id=%)', p_nf_entrada_id;
  end if;

  insert into public.movimentacoes (
    item_id,
    tipo,
    quantidade,
    motivo,
    realizado_por,
    data_movimentacao,
    custo_unitario_bruto,
    custo_unitario_real,
    credito_icms,
    credito_pis,
    credito_cofins,
    origem_nf_entrada_id,
    origem_os_id,
    v_ipi,
    v_icms,
    v_pis,
    v_cofins,
    v_frete_rateado,
    tenant_id,
    empresa_id
  )
  select
    i.id,
    'entrada'::text,
    coalesce(ni.qtd, 0),
    'Backfill automatico importacao XML NF-e ' || v_nf.chave,
    coalesce(public.jwt_claim('email'), auth.uid()::text, 'system-backfill'),
    now(),
    nullif(ni.v_unit, 0),
    nullif(ni.v_unit, 0),
    coalesce(ni.v_icms, 0),
    coalesce(ni.v_pis, 0),
    coalesce(ni.v_cofins, 0),
    v_nf.id,
    v_nf.os_id,
    coalesce(ni.v_ipi, 0),
    coalesce(ni.v_icms, 0),
    coalesce(ni.v_pis, 0),
    coalesce(ni.v_cofins, 0),
    0,
    v_nf.tenant_id,
    v_nf.empresa_id
  from public.nf_entrada_itens ni
  join public.itens i
    on i.tenant_id = v_nf.tenant_id
   and i.empresa_id = v_nf.empresa_id
   and i.id = ni.item_id
   and i.tipo = 'produto'
   and coalesce(i.controla_estoque, false) = true
  where ni.nf_entrada_id = v_nf.id
    and ni.tenant_id = v_nf.tenant_id
    and not exists (
      select 1
      from public.movimentacoes m
      where m.tenant_id = v_nf.tenant_id
        and m.empresa_id = v_nf.empresa_id
        and m.origem_nf_entrada_id = v_nf.id
        and m.item_id = i.id
        and m.tipo = 'entrada'
      limit 1
    );

  get diagnostics v_rows = row_count;
  rows_inserted := coalesce(v_rows, 0);
  return next;
end;
$$;


ALTER FUNCTION "public"."fn_backfill_movimentacoes_nf_entrada"("p_nf_entrada_id" bigint) OWNER TO "postgres";


