    AS $$
begin
  perform public.fn_hh_sync_apontamento_key(
    new.tenant_id,
    new.empresa_id,
    new.os_id,
    new.colaborador_id,
    new.data,
    new.id
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_hh_sync_apontamento"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_hh_sync_apontamento_key"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_id" integer, "p_colaborador_id" "uuid", "p_data" "date", "p_hh_lancamento_id" bigint DEFAULT NULL::bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.fn_hh_sync_apontamento_key(
    p_tenant_id,
    p_empresa_id,
    p_os_id::bigint,
    p_colaborador_id,
    p_data,
    p_hh_lancamento_id
  );
