CREATE OR REPLACE FUNCTION "public"."fn_venda_credito_ao_receber_oc"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if nullif(btrim(new.pedido_compra), '') is not null
     and nullif(btrim(old.pedido_compra), '') is null then
    update f.gestao_cobranca_os g
       set status = case when g.status = 'ABERTO' then 'OC_RECEBIDA' else g.status end,
           pedido_compra_cliente = btrim(new.pedido_compra),
           pedido_recebido_em = coalesce(g.pedido_recebido_em, current_date),
           updated_at = now(),
           updated_by = a.fn_current_usuario_id()
     where g.tenant_id = new.tenant_id
       and g.empresa_id = new.empresa_id
       and g.os_id = new.id
       and g.deleted_at is null
       and g.status not in ('RECEBIDO','CANCELADO');
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."fn_venda_credito_ao_receber_oc"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_xml_strip_default_namespace"("p_xml_raw" "text") RETURNS "xml"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c', 'f', 'm', 'r', 'auth', 'extensions'
    AS $$
  select xmlparse(document
    regexp_replace(
      regexp_replace(coalesce(p_xml_raw,''), 'xmlns(:\w+)?="[^"]+"', '', 'g'),
      '</?\w+:(\w+)', '<\1', 'g'
    )
  );
$$;


ALTER FUNCTION "public"."fn_xml_strip_default_namespace"("p_xml_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gerar_relatorio_hh_os"("p_os_id" integer, "p_periodo_inicio" "date", "p_periodo_fim" "date") RETURNS TABLE("relatorio_id" bigint, "total" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
  v_tipo_documento text;
begin
  select os.tenant_id, os.empresa_id, os.tipo_documento
    into v_tenant_id, v_empresa_id, v_tipo_documento
  from public.ordens_servico as os
  where os.id = p_os_id;

  if not found or v_tipo_documento <> 'OS' then
    raise exception 'ordem_servico_not_found';
  end if;
  if v_empresa_id is distinct from public.current_empresa_id__by_tenant(v_tenant_id)
     or not public.has_active_empresa_access(v_tenant_id, v_empresa_id) then
    raise exception 'not_allowed';
  end if;

  return query
  select relatorio.relatorio_id, relatorio.total
  from public.gerar_relatorio_hh_os_unscoped_20260810(
    p_os_id, p_periodo_inicio, p_periodo_fim
  ) as relatorio;
end;
$$;


ALTER FUNCTION "public"."gerar_relatorio_hh_os"("p_os_id" integer, "p_periodo_inicio" "date", "p_periodo_fim" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gerar_relatorio_hh_os_unscoped_20260810"("p_os_id" integer, "p_periodo_inicio" "date", "p_periodo_fim" "date") RETURNS TABLE("relatorio_id" bigint, "total" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tenant_id uuid;
  v_cliente_id bigint;
  v_tabela_hh_id bigint;
  v_relatorio_id bigint;
  v_total numeric := 0;
  v_ano int;
  v_missing_apontamento_id text;
  v_missing_valor_apontamento_id text;
BEGIN
  -- 1) Tenant obrigatorio
  v_tenant_id := current_tenant_id();
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Tenant nao definido (current_tenant_id retornou null).';
  END IF;

  IF p_periodo_inicio IS NULL OR p_periodo_fim IS NULL THEN
    RAISE EXCEPTION 'Periodo inicio e fim sao obrigatorios.';
  END IF;

  IF p_periodo_inicio > p_periodo_fim THEN
    RAISE EXCEPTION 'Periodo inicio maior que periodo fim.';
  END IF;

  -- 2) Descobrir cliente da OS
  SELECT os.cliente_id
    INTO v_cliente_id
  FROM public.ordens_servico os
  WHERE os.id = p_os_id
    AND os.tenant_id = v_tenant_id
  LIMIT 1;

  IF v_cliente_id IS NULL THEN
    RAISE EXCEPTION 'OS % nao encontrada ou sem cliente vinculado.', p_os_id;
  END IF;

  -- 3) Descobrir tabela HH ativa do cliente para o ano do periodo
  v_ano := EXTRACT(YEAR FROM p_periodo_inicio)::int;
  SELECT t.id
    INTO v_tabela_hh_id
  FROM public.cliente_hh_tabela t
  WHERE t.tenant_id = v_tenant_id
    AND t.cliente_id = v_cliente_id
    AND t.ano = v_ano
    AND t.ativo = true
  ORDER BY t.criado_em DESC
  LIMIT 1;

  IF v_tabela_hh_id IS NULL THEN
    RAISE EXCEPTION 'Tabela HH ativa nao encontrada para cliente % no ano %.', v_cliente_id, v_ano;
  END IF;

  -- 4) Nao recalcular se ja existir relatorio fechado para a mesma OS e periodo
  IF EXISTS (
    SELECT 1
    FROM public.os_relatorios_hh r
    WHERE r.tenant_id = v_tenant_id
      AND r.os_id = p_os_id
      AND r.periodo_inicio = p_periodo_inicio
      AND r.periodo_fim = p_periodo_fim
      AND r.status = 'fechado'
  ) THEN
    RAISE EXCEPTION 'Relatorio HH ja fechado para OS % no periodo % a %.', p_os_id, p_periodo_inicio, p_periodo_fim;
  END IF;

  -- 5) Cria cabecalho (status fechado) com total 0 (sera atualizado no fim)
  INSERT INTO public.os_relatorios_hh (
    tenant_id,
    os_id,
    cliente_id,
    tabela_hh_id,
    periodo_inicio,
    periodo_fim,
    data_emissao,
    status,
    total
  ) VALUES (
    v_tenant_id,
    p_os_id,
    v_cliente_id,
    v_tabela_hh_id,
    p_periodo_inicio,
    p_periodo_fim,
    current_date,
    'fechado',
    0
  )
  RETURNING id INTO v_relatorio_id;

  -- 6) Validar especialidade: se nao houver, aborta com erro claro
  WITH base AS (
    SELECT
      ah.id AS apontamento_id,
      ah.colaborador_id,
      ah.data,
      ah.entrada_1,
      ah.saida_1,
      ah.entrada_2,
      ah.saida_2,
      ah.horas_trabalhadas,
      ah.tipo_hora_id,
      ah.fator_aplicado,
      COALESCE(ah.hh_especialidade_id, c.hh_especialidade_id) AS especialidade_id,
      th.codigo AS tipo_hora_codigo,
      th.fator AS tipo_hora_fator
    FROM public.apontamentos_horas ah
    LEFT JOIN public.colaboradores c ON c.id = ah.colaborador_id
    LEFT JOIN public.tipos_horas th ON th.id = ah.tipo_hora_id
    WHERE ah.tenant_id = v_tenant_id
      AND ah.os_id = p_os_id
      AND ah.data BETWEEN p_periodo_inicio AND p_periodo_fim
  )
  SELECT b.apontamento_id
    INTO v_missing_apontamento_id
  FROM base b
  WHERE b.especialidade_id IS NULL
  LIMIT 1;

  IF v_missing_apontamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Apontamento % sem especialidade (hh_especialidade_id).', v_missing_apontamento_id;
  END IF;

  -- 7) Validar valor_base da tabela HH para cada especialidade
  WITH base AS (
    SELECT
      ah.id AS apontamento_id,
      ah.colaborador_id,
      ah.data,
      ah.entrada_1,
      ah.saida_1,
      ah.entrada_2,
      ah.saida_2,
      ah.horas_trabalhadas,
      ah.tipo_hora_id,
      ah.fator_aplicado,
      COALESCE(ah.hh_especialidade_id, c.hh_especialidade_id) AS especialidade_id,
      th.codigo AS tipo_hora_codigo,
      th.fator AS tipo_hora_fator
    FROM public.apontamentos_horas ah
    LEFT JOIN public.colaboradores c ON c.id = ah.colaborador_id
    LEFT JOIN public.tipos_horas th ON th.id = ah.tipo_hora_id
    WHERE ah.tenant_id = v_tenant_id
      AND ah.os_id = p_os_id
      AND ah.data BETWEEN p_periodo_inicio AND p_periodo_fim
  ), enriched AS (
    SELECT
      b.*,
      ti.valor_base
    FROM base b
    LEFT JOIN public.cliente_hh_tabela_itens ti
      ON ti.tabela_hh_id = v_tabela_hh_id
     AND ti.hh_especialidade_id = b.especialidade_id
  )
  SELECT e.apontamento_id
    INTO v_missing_valor_apontamento_id
  FROM enriched e
  WHERE e.valor_base IS NULL
  LIMIT 1;

  IF v_missing_valor_apontamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Valor base nao encontrado na tabela HH para o apontamento %.', v_missing_valor_apontamento_id;
  END IF;

  -- 8) Inserir linhas (snapshot) com calculos financeiros
  WITH base AS (
    SELECT
      ah.id AS apontamento_id,
      ah.colaborador_id,
      ah.data,
      ah.entrada_1,
      ah.saida_1,
      ah.entrada_2,
      ah.saida_2,
      ah.horas_trabalhadas,
      ah.tipo_hora_id,
      ah.fator_aplicado,
      COALESCE(ah.hh_especialidade_id, c.hh_especialidade_id) AS especialidade_id,
      th.codigo AS tipo_hora_codigo,
      th.fator AS tipo_hora_fator
    FROM public.apontamentos_horas ah
    LEFT JOIN public.colaboradores c ON c.id = ah.colaborador_id
    LEFT JOIN public.tipos_horas th ON th.id = ah.tipo_hora_id
    WHERE ah.tenant_id = v_tenant_id
      AND ah.os_id = p_os_id
      AND ah.data BETWEEN p_periodo_inicio AND p_periodo_fim
  ), enriched AS (
    SELECT
      b.*,
      he.descricao AS especialidade_descricao,
      ti.valor_base,
      COALESCE(b.fator_aplicado, b.tipo_hora_fator, 1) AS fator_final
    FROM base b
    JOIN public.hh_especialidades he ON he.id = b.especialidade_id
    JOIN public.cliente_hh_tabela_itens ti
      ON ti.tabela_hh_id = v_tabela_hh_id
     AND ti.hh_especialidade_id = b.especialidade_id
  )
  INSERT INTO public.os_relatorios_hh_linhas (
    tenant_id,
    relatorio_id,
    colaborador_id,
    data,
    entrada_1,
    saida_1,
    entrada_2,
    saida_2,
    horas_trabalhadas,
    fator,
    tipo_hora_codigo,
    especialidade_descricao,
    valor_hora_base,
    valor_hora_aplicado,
    total
  )
  SELECT
    v_tenant_id,
    v_relatorio_id,
    e.colaborador_id,
    e.data,
    e.entrada_1,
    e.saida_1,
    e.entrada_2,
    e.saida_2,
    e.horas_trabalhadas,
    e.fator_final,
    e.tipo_hora_codigo,
    e.especialidade_descricao,
    e.valor_base,
    (e.valor_base * e.fator_final) AS valor_hora_aplicado,
    ROUND(e.horas_trabalhadas * (e.valor_base * e.fator_final), 2) AS total
  FROM enriched e;

  -- 9) Atualizar total no cabecalho (arredondamento financeiro)
  SELECT COALESCE(ROUND(SUM(l.total), 2), 0)
    INTO v_total
  FROM public.os_relatorios_hh_linhas l
  WHERE l.relatorio_id = v_relatorio_id;

  UPDATE public.os_relatorios_hh
     SET total = v_total
   WHERE id = v_relatorio_id;

  -- 10) Retorna id e total
  RETURN QUERY SELECT v_relatorio_id, v_total;
END;
$$;


ALTER FUNCTION "public"."gerar_relatorio_hh_os_unscoped_20260810"("p_os_id" integer, "p_periodo_inicio" "date", "p_periodo_fim" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_default_empresa_id"("p_tenant_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select e.id
  from public.empresas e
  where e.tenant_id = p_tenant_id
    and e.ativo is true
    and public.has_active_empresa_access(e.tenant_id, e.id)
  order by e.criado_em asc nulls last, e.id
  limit 1;
$$;


ALTER FUNCTION "public"."get_default_empresa_id"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_default_tenant_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  tenant_id uuid;
  has_created_at boolean;
  has_criado_em boolean;
begin
  if not exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = 'tenants'
  ) then
    raise exception 'Tabela tenants nao encontrada.';
  end if;

  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'tenants'
      and column_name = 'created_at'
  ) into has_created_at;

  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'tenants'
      and column_name = 'criado_em'
  ) into has_criado_em;

  if has_criado_em then
    execute 'select id from public.tenants order by criado_em asc nulls last limit 1'
      into tenant_id;
  elsif has_created_at then
    execute 'select id from public.tenants order by created_at asc nulls last limit 1'
      into tenant_id;
  else
    execute 'select id from public.tenants limit 1'
      into tenant_id;
  end if;

  if tenant_id is null then
    raise exception 'Nenhum tenant encontrado.';
  end if;

  return tenant_id;
end;
$$;


ALTER FUNCTION "public"."get_default_tenant_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_full_permissions"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_result jsonb;
  v_admin jsonb;
  v_empresa_papel text;
  v_tenant_papel text;
  v_negadas jsonb;
  v_negadas_keys text[];
begin
  if not public.has_active_empresa_access(p_tenant_id, p_empresa_id) then
    return '{}'::jsonb;
  end if;

  v_result := coalesce(
    public.get_full_permissions_unscoped_20260810(p_tenant_id, p_empresa_id),
    '{}'::jsonb
  );

  select upper(trim(ut.papel)), upper(trim(ue.papel)), ue.permissoes_negadas
    into v_tenant_papel, v_empresa_papel, v_negadas
  from a.usuario u
  join a.usuario_tenant ut on ut.usuario_id = u.id
  join a.usuario_empresa ue on ue.usuario_id = u.id
  where u.auth_user_id = auth.uid()
    and u.ativo is true
    and u.deleted_at is null
    and ut.tenant_id = p_tenant_id
    and ut.ativo is true
    and ut.deleted_at is null
    and ue.empresa_id = p_empresa_id
    and ue.ativo is true
    and ue.deleted_at is null
  limit 1;

  if v_empresa_papel = 'FINANCEIRO'
     and not coalesce(
       jsonb_typeof(v_negadas) = 'object'
       and v_negadas ? 'apontamentos.read',
       false
     ) then
    v_result := v_result || jsonb_build_object('apontamentos.read', true);
  end if;

  if v_empresa_papel = 'DIRETOR' then
    select coalesce(jsonb_object_agg(rp.permission, true), '{}'::jsonb)
      into v_admin
    from public.role_permissions rp
    where rp.role = 'admin';

    v_result := v_result || v_admin || jsonb_build_object('modulo_preferencial', 'admin');

    if jsonb_typeof(v_negadas) = 'object' then
      select array_agg(k) into v_negadas_keys
      from jsonb_object_keys(v_negadas) k;
      if v_negadas_keys is not null then
        v_result := v_result - v_negadas_keys;
      end if;
    end if;
  end if;

  -- O DIRETOR, antigo ou novo, nunca recebe gestao de identidades.
  if v_empresa_papel = 'DIRETOR' or v_tenant_papel = 'DIRETOR' then
    v_result := v_result - array['admin.manage_users','admin.users.manage'];
  end if;

  return coalesce(v_result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_full_permissions"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_full_permissions_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'a'
    AS $$
declare
  v_usuario_id uuid;
  v_tenant_papel text;
  v_empresa_papel text;
  v_perm_extra jsonb;
  v_perm_negadas jsonb;
  v_empresa_papel_norm text;
  v_negadas text[];
  base_perms jsonb := '{}'::jsonb;
  extra_perms jsonb := '{}'::jsonb;
  result_perms jsonb;
begin
  select u.id
    into v_usuario_id
  from a.usuario u
  where u.auth_user_id = auth.uid()
    and u.deleted_at is null
  limit 1;

  if v_usuario_id is null then
    return '{}'::jsonb;
  end if;

  select ut.papel
    into v_tenant_papel
  from a.usuario_tenant ut
  where ut.usuario_id = v_usuario_id
    and ut.tenant_id = p_tenant_id
    and ut.ativo = true
    and ut.deleted_at is null
  limit 1;

  if v_tenant_papel is null then
    return '{}'::jsonb;
  end if;

  select ue.papel, ue.permissoes_extra, ue.permissoes_negadas
    into v_empresa_papel, v_perm_extra, v_perm_negadas
  from a.usuario_empresa ue
  where ue.usuario_id = v_usuario_id
    and ue.empresa_id = p_empresa_id
    and ue.ativo = true
    and ue.deleted_at is null
  limit 1;

  if upper(coalesce(v_empresa_papel, '')) = 'APONTADOR' then
    return '{}'::jsonb;
  end if;

  select jsonb_object_agg(rp.permission, true)
    into base_perms
  from public.role_permissions rp
  where rp.role = a.fn_map_papel_tenant_to_role(v_tenant_papel);

  base_perms := coalesce(base_perms, '{}'::jsonb);

  if v_empresa_papel is null then
    return base_perms;
  end if;

  v_empresa_papel_norm := upper(coalesce(v_empresa_papel, ''));

  extra_perms := extra_perms || jsonb_build_object(
    'modulo_preferencial',
    case v_empresa_papel_norm
      when 'ADMIN' then 'admin'
      when 'FINANCEIRO' then 'financeiro'
      when 'FATURAMENTO' then 'faturamento'
      when 'COORDENACAO' then 'projetos'
      when 'COMPRAS' then 'estoque'
      when 'ALMOXARIFADO' then 'estoque'
      when 'APONTAMENTO_RH' then 'projetos'
      else null
    end
  );

  if v_empresa_papel_norm in ('ADMIN','COORDENACAO','FATURAMENTO') then
    extra_perms := extra_perms || jsonb_build_object(
      'os.read', true,
      'os.write', true,
      'os.delete', true,
      'os_itens.write', true,
      'os_gestao.write', true,
      'os_rpcs.execute', true
    );
  elsif v_empresa_papel_norm = 'COMPRAS' then
    extra_perms := extra_perms || jsonb_build_object('os.read', true);
  elsif v_empresa_papel_norm = 'APONTAMENTO_RH' then
    extra_perms := extra_perms || jsonb_build_object(
      'os.read', true,
      'os.write', true
    );
  end if;

  if v_empresa_papel_norm in ('ADMIN','FINANCEIRO') then
    extra_perms := extra_perms || jsonb_build_object(
      'financeiro.read', true,
      'financeiro.write', true,
      'faturamento.read', true,
      'faturamento.write', true,
      'faturamento.nfe.import_xml', true
    );
  end if;

  if v_empresa_papel_norm = 'FATURAMENTO' then
    extra_perms := extra_perms || jsonb_build_object(
      'faturamento.read', true,
      'faturamento.write', true,
      'faturamento.nfe.import_xml', true,
      'xml_import_faturamento.execute', true
    );
  end if;

  if v_empresa_papel_norm in ('ADMIN','FINANCEIRO','COORDENACAO','COMPRAS','ALMOXARIFADO','APONTAMENTO_RH','FATURAMENTO') then
    extra_perms := extra_perms || jsonb_build_object('estoque.read', true);
  end if;

  if v_empresa_papel_norm in ('ADMIN','COMPRAS','ALMOXARIFADO','APONTAMENTO_RH','COORDENACAO','FATURAMENTO') then
    extra_perms := extra_perms || jsonb_build_object('estoque.write', true);
  end if;

  if v_empresa_papel_norm in ('ADMIN','FINANCEIRO','COORDENACAO','COMPRAS','ALMOXARIFADO','APONTAMENTO_RH','FATURAMENTO') then
    extra_perms := extra_perms || jsonb_build_object('imobilizado.read', true);
  end if;

  if v_empresa_papel_norm in ('ADMIN','COORDENACAO','COMPRAS','ALMOXARIFADO','APONTAMENTO_RH','FATURAMENTO') then
    extra_perms := extra_perms || jsonb_build_object('imobilizado.write', true);
  end if;

  if v_empresa_papel_norm in ('ALMOXARIFADO','APONTAMENTO_RH','COORDENACAO','FINANCEIRO','FATURAMENTO') then
    extra_perms := extra_perms || jsonb_build_object(
      'xml_import.execute', true,
      'nf_entrada.import', true,
      'cad_fornecedores.write', true,
      'cad_itens.write', true
    );
  end if;

  if v_empresa_papel_norm = 'FATURAMENTO' then
    extra_perms := extra_perms || jsonb_build_object(
      'estoque_custos.cost_read', true,
      'fiscal_nf.read', true,
      'fiscal_nf.write', true,
      'fiscal_nf.delete', true,
      'fiscal_itens.write', true,
      'apontamentos.read', true,
      'apontamentos.write', true,
      'apontamentos.delete', true,
      'apontamentos.config', true,
      'cad_clientes.write', true,
      'compras.read', true,
      'compras.write', true,
      'compras.approve', true,
      'compras.receive', true
    );
  end if;

  if v_perm_extra is not null then
    extra_perms := extra_perms || v_perm_extra;
  end if;

  result_perms := base_perms || extra_perms;

  if v_perm_negadas is not null then
    select array_agg(key)
      into v_negadas
    from jsonb_object_keys(v_perm_negadas) as key;

    if v_negadas is not null then
      result_perms := result_perms - v_negadas;
    end if;
  end if;

  return coalesce(result_perms, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_full_permissions_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_hh_tipo_id_for_tenant"("p_tenant_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c', 'f', 'm', 'r', 'auth', 'extensions'
    AS $$
DECLARE
  v_hh_tipo_id BIGINT;
BEGIN
  -- Busca primeiro mapeamento ativo para o tenant
  SELECT hh_tipo_id INTO v_hh_tipo_id
  FROM public.hh_tipos_mapping
  WHERE tenant_id = p_tenant_id AND ativo = true
  LIMIT 1;
  
  RETURN v_hh_tipo_id;
END;
$$;


