CREATE OR REPLACE FUNCTION "public"."get_os_detail_operacional"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if not exists (
    select 1
    from public.ordens_servico as os
    where os.id = p_os_id
      and os.tenant_id = p_tenant_id
      and os.empresa_id = p_empresa_id
      and os.tipo_documento = 'OS'
  ) then
    raise exception 'os_not_found';
  end if;

  return public.get_os_detail_operacional_unfiltered_ov_20260829(
    p_tenant_id, p_empresa_id, p_os_id
  );
end;
$$;


ALTER FUNCTION "public"."get_os_detail_operacional"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_os_detail_operacional_unfiltered_ov_20260829"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_papel text := a.fn_current_empresa_papel(p_tenant_id, p_empresa_id);
  v_os public.ordens_servico%rowtype;
  v_result jsonb;
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or p_os_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or coalesce(v_papel, '') not in (
       'ADMIN', 'DIRETOR', 'FINANCEIRO', 'FATURAMENTO', 'COORDENACAO',
       'COMPRAS', 'ALMOXARIFADO', 'TECNICO', 'APONTAMENTO_RH'
     ) then
    raise exception 'os_detail_access_denied';
  end if;

  select os.*
    into v_os
  from public.ordens_servico os
  where os.id = p_os_id
    and os.tenant_id = p_tenant_id
    and os.empresa_id = p_empresa_id;

  if not found then
    raise exception 'os_not_found';
  end if;

  select jsonb_build_object(
    'os', jsonb_build_object(
      'id', v_os.id,
      'numero_os', v_os.numero_os,
      'cliente_nome', v_os.cliente_nome,
      'cliente_id', v_os.cliente_id,
      'status', v_os.status,
      'descricao_servico', v_os.descricao_servico,
      'valor_total', v_os.valor_total,
      'data_abertura', v_os.data_abertura,
      'orcado', v_os.orcado,
      'tipo_pedido', v_os.tipo_pedido,
      'tem_gestao', v_os.tem_gestao,
      'pedido_compra', v_os.pedido_compra,
      'vendedor', v_os.vendedor,
      'usa_relatorio_hh', v_os.usa_relatorio_hh,
      'is_fiado', coalesce(v_os.is_fiado, false),
      'orcamento_gerado_id', v_os.orcamento_gerado_id
    ),
    'cliente_habilita_hh', coalesce((
      select c.habilita_hh
      from public.clientes c
      where c.id = v_os.cliente_id
        and c.tenant_id = p_tenant_id
        and c.empresa_id = p_empresa_id
    ), false) or coalesce(v_os.usa_relatorio_hh, false),
    'itens', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', oi.id,
          'item_id', oi.item_id,
          'quantidade', oi.quantidade,
          'valor_unitario', oi.valor_unitario,
          'valor_total', oi.valor_total,
          'desconto_percentual', oi.desconto_percentual,
          'desconto_valor', oi.desconto_valor,
          'baixa_estoque', oi.baixa_estoque,
          'quantidade_baixada', oi.quantidade_baixada,
          'criado_em', oi.criado_em,
          'registrado_em', oi.registrado_em,
          'registrado_por_nome', oi.registrado_por_nome,
          'itens', case when i.id is null then null else jsonb_build_object(
            'nome', i.nome,
            'codigo_interno', i.codigo_interno,
            'tipo', i.tipo
          ) end
        ) order by oi.id desc
      )
      from public.os_itens oi
      left join public.itens i
        on i.id = oi.item_id
       and i.tenant_id = oi.tenant_id
       and i.empresa_id = oi.empresa_id
      where oi.os_id = p_os_id
        and oi.tenant_id = p_tenant_id
        and oi.empresa_id = p_empresa_id
    ), '[]'::jsonb),
    'custo_mao_obra', coalesce((
      select v.custo_mao_obra
      from public.vw_custo_mao_obra_os v
      where v.os_id = p_os_id
      limit 1
    ), 0),
    'total_hh', coalesce((
      select v.total_hh
      from public.vw_hh_total_os v
      where v.os_id = p_os_id
      limit 1
    ), 0),
    'hh_lancamentos', coalesce((
      select jsonb_agg(jsonb_build_object(
        'entrada_1', h.entrada_1,
        'saida_1', h.saida_1,
        'entrada_2', h.entrada_2,
        'saida_2', h.saida_2,
        'hora_entrada', h.hora_entrada,
        'hora_saida', h.hora_saida,
        'horas_trabalhadas', h.horas_trabalhadas,
        'percentual_aplicado', h.percentual_aplicado,
        'tem_extra_50', h.tem_extra_50,
        'horas_extra_50', h.horas_extra_50,
        'tem_extra_100', h.tem_extra_100,
        'horas_extra_100', h.horas_extra_100,
        'valor_hora', h.valor_hora,
        'valor_total', h.valor_total
      ))
      from public.hh_lancamentos h
      where h.os_id = p_os_id
        and h.tenant_id = p_tenant_id
        and h.empresa_id = p_empresa_id
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_os_detail_operacional_unfiltered_ov_20260829"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_os_detail_operacional_unfiltered_ov_20260829"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_id" integer) IS 'Carrega o detalhe operacional de uma OS em uma unica consulta escopada e autorizada. Inclui is_fiado/orcamento_gerado_id (OS Fiado) desde 20260823175000.';



CREATE OR REPLACE FUNCTION "public"."get_os_lista_custos_operacionais"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_ids" integer[]) RETURNS TABLE("os_id" integer, "custo_total" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_papel text := a.fn_current_empresa_papel(p_tenant_id, p_empresa_id);
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or coalesce(array_length(p_os_ids, 1), 0) = 0
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or coalesce(v_papel, '') not in (
       'ADMIN', 'DIRETOR', 'FINANCEIRO', 'FATURAMENTO', 'COORDENACAO',
       'COMPRAS', 'ALMOXARIFADO', 'TECNICO', 'APONTAMENTO_RH'
     ) then
    raise exception 'os_cost_list_access_denied';
  end if;

  return query
  with os_base as (
    select os.id, os.orcado, os.tipo_pedido, coalesce(os.usa_relatorio_hh, false) as usa_relatorio_hh
    from public.ordens_servico as os
    where os.id = any(p_os_ids)
      and os.tenant_id = p_tenant_id
      and os.empresa_id = p_empresa_id
  ),
  itens_por_os as (
    select
      os_item.os_id,
      coalesce(sum(os_item.valor_total) filter (
        where not (
          os_item.item_id between 1 and 99
          or lower(coalesce(item.tipo, '')) = 'despesa'
        )
        and item.tipo = 'produto'
      ), 0)::numeric as materiais,
      coalesce(sum(os_item.valor_total) filter (
        where os_item.item_id between 1 and 99
           or lower(coalesce(item.tipo, '')) = 'despesa'
      ), 0)::numeric as despesas
    from public.os_itens as os_item
    join os_base as os on os.id = os_item.os_id
    left join public.itens as item
      on item.id = os_item.item_id
     and item.tenant_id = os_item.tenant_id
     and item.empresa_id = os_item.empresa_id
    where os_item.tenant_id = p_tenant_id
      and os_item.empresa_id = p_empresa_id
    group by os_item.os_id
  ),
  mao_obra_por_os as (
    select custo.os_id, coalesce(custo.custo_mao_obra, 0)::numeric as mao_obra
    from public.vw_custo_mao_obra_os as custo
    join os_base as os on os.id = custo.os_id
  ),
  hh_horas_efetivas as (
    select
      hh.os_id,
      hh.valor_hora,
      hh.valor_total,
      hh.percentual_aplicado,
      hh.tem_extra_50,
      hh.tem_extra_100,
      hh.horas_extra_50,
      hh.horas_extra_100,
      case
        when periodo.entrada_1 is not null
         and periodo.saida_1 is not null
         and periodo.entrada_2 is not null
         and periodo.saida_2 is not null
          then round((
            case when periodo.saida_1 >= periodo.entrada_1
              then extract(epoch from (periodo.saida_1 - periodo.entrada_1)) / 3600
              else 24 + extract(epoch from (periodo.saida_1 - periodo.entrada_1)) / 3600
            end
            + case when periodo.saida_2 >= periodo.entrada_2
              then extract(epoch from (periodo.saida_2 - periodo.entrada_2)) / 3600
              else 24 + extract(epoch from (periodo.saida_2 - periodo.entrada_2)) / 3600
            end
          )::numeric, 2)
        when periodo.entrada_1 is not null and periodo.saida_1 is not null
          then round((case when periodo.saida_1 >= periodo.entrada_1
            then extract(epoch from (periodo.saida_1 - periodo.entrada_1)) / 3600
            else 24 + extract(epoch from (periodo.saida_1 - periodo.entrada_1)) / 3600
          end)::numeric, 2)
        else coalesce(hh.horas_trabalhadas, 0)::numeric
      end as horas_efetivas
    from public.hh_lancamentos as hh
    join os_base as os on os.id = hh.os_id
    cross join lateral (
      select
        coalesce(hh.entrada_1, hh.hora_entrada) as entrada_1,
        coalesce(hh.saida_1, hh.hora_saida) as saida_1,
        hh.entrada_2 as entrada_2,
        hh.saida_2 as saida_2
    ) as periodo
    where hh.tenant_id = p_tenant_id
      and hh.empresa_id = p_empresa_id
  ),
  pedido_hh_por_os as (
    select hh.os_id, round(coalesce(sum(
      case
        when (
          coalesce(hh.tem_extra_50, false)
          or coalesce(hh.tem_extra_100, false)
          or coalesce(hh.horas_extra_50, 0) > 0
          or coalesce(hh.horas_extra_100, 0) > 0
          or coalesce(hh.percentual_aplicado, 0) in (50, 100)
        ) and coalesce(hh.valor_total, 0) > 0 then hh.valor_total
        when coalesce(hh.valor_hora, 0) > 0 and hh.horas_efetivas > 0 then
          case
            when coalesce(hh.tem_extra_50, false)
              or coalesce(hh.tem_extra_100, false)
              or coalesce(hh.horas_extra_50, 0) > 0
              or coalesce(hh.horas_extra_100, 0) > 0
              then greatest(0, hh.horas_efetivas - coalesce(hh.horas_extra_50, 0) - coalesce(hh.horas_extra_100, 0)) * hh.valor_hora
                   + coalesce(hh.horas_extra_50, 0) * hh.valor_hora * 1.5
                   + coalesce(hh.horas_extra_100, 0) * hh.valor_hora * 2
            when coalesce(hh.percentual_aplicado, 0) = 50 then hh.horas_efetivas * hh.valor_hora * 1.5
            when coalesce(hh.percentual_aplicado, 0) = 100 then hh.horas_efetivas * hh.valor_hora * 2
            else hh.horas_efetivas * hh.valor_hora
          end
        else coalesce(hh.valor_total, 0)
      end
    ), 0)::numeric, 2) as pedido_hh
    from hh_horas_efetivas as hh
    group by hh.os_id
  )
  select
    os.id,
    case
      when os.usa_relatorio_hh then
        coalesce(itens.materiais, 0)
        + coalesce(itens.despesas, 0)
        + coalesce(mao_obra.mao_obra, 0)
        + coalesce(pedido_hh.pedido_hh, 0) * 0.15
      else
        coalesce(itens.materiais, 0)
        + coalesce(itens.despesas, 0)
        + coalesce(mao_obra.mao_obra, 0)
        + case
            when os.tipo_pedido = 'material' then coalesce(os.orcado, 0) * 0.27
            else coalesce(os.orcado, 0) * 0.15
          end
    end::numeric as custo_total
  from os_base as os
  left join itens_por_os as itens on itens.os_id = os.id
  left join mao_obra_por_os as mao_obra on mao_obra.os_id = os.id
  left join pedido_hh_por_os as pedido_hh on pedido_hh.os_id = os.id;
end;
$$;


ALTER FUNCTION "public"."get_os_lista_custos_operacionais"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_ids" integer[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_os_lista_custos_operacionais"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_os_ids" integer[]) IS 'Retorna o custo operacional total de uma lista de OS usando a mesma fórmula da tela de detalhe.';



CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  insert into public.profiles (id, email, nome)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'nome', new.raw_user_meta_data ->> 'name')
  )
  on conflict (id)
  do update set
    email = excluded.email,
    nome = excluded.nome;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_active_empresa_access"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select p_tenant_id is not null
    and p_empresa_id is not null
    and auth.uid() is not null
    and exists (
      select 1
      from a.usuario u
      join a.usuario_tenant ut on ut.usuario_id = u.id
      join a.usuario_empresa ue on ue.usuario_id = u.id
      join c.empresa ce on ce.id = ue.empresa_id
      join public.empresas pe
        on pe.id = ce.id
       and pe.tenant_id = ce.tenant_id
      join public.tenants t on t.id = ce.tenant_id
      where u.auth_user_id = auth.uid()
        and u.ativo is true
        and u.deleted_at is null
        and ut.tenant_id = p_tenant_id
        and ut.ativo is true
        and ut.deleted_at is null
        and ue.empresa_id = p_empresa_id
        and ue.ativo is true
        and ue.deleted_at is null
        and ce.tenant_id = p_tenant_id
        and ce.ativo is true
        and ce.deleted_at is null
        and pe.ativo is true
        and t.ativo is true
    );
$$;


ALTER FUNCTION "public"."has_active_empresa_access"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."has_active_empresa_access"("p_tenant_id" "uuid", "p_empresa_id" "uuid") IS 'Fronteira canonica: exige usuario, tenant, empresa e vinculo a.usuario_empresa ativos.';



CREATE OR REPLACE FUNCTION "public"."has_active_tenant_access"("p_tenant_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select p_tenant_id is not null
    and auth.uid() is not null
    and exists (
      select 1
      from a.usuario u
      join a.usuario_tenant ut on ut.usuario_id = u.id
      join public.tenants t on t.id = ut.tenant_id
      where u.auth_user_id = auth.uid()
        and u.ativo is true
        and u.deleted_at is null
        and ut.tenant_id = p_tenant_id
        and ut.ativo is true
        and ut.deleted_at is null
        and t.ativo is true
    );
$$;


ALTER FUNCTION "public"."has_active_tenant_access"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_any_active_empresa_access"("p_tenant_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select exists (
    select 1
    from a.usuario u
    join a.usuario_tenant ut on ut.usuario_id = u.id
    join a.usuario_empresa ue on ue.usuario_id = u.id
    join c.empresa ce on ce.id = ue.empresa_id
    join public.empresas pe on pe.id = ce.id and pe.tenant_id = ce.tenant_id
    join public.tenants t on t.id = ce.tenant_id
    where u.auth_user_id = auth.uid()
      and u.ativo is true
      and u.deleted_at is null
      and ut.tenant_id = p_tenant_id
      and ut.ativo is true
      and ut.deleted_at is null
      and ue.ativo is true
      and ue.deleted_at is null
      and ce.tenant_id = p_tenant_id
      and ce.ativo is true
      and ce.deleted_at is null
      and pe.ativo is true
      and t.ativo is true
  );
$$;


ALTER FUNCTION "public"."has_any_active_empresa_access"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_capability"("p_capability" "text", "p_tenant_id" "uuid" DEFAULT "public"."current_tenant_id"(), "p_empresa_id" "uuid" DEFAULT "public"."current_empresa_id"()) RETURNS boolean
