CREATE OR REPLACE FUNCTION "public"."list_compras_fornecedores"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_search" "text" DEFAULT NULL::"text") RETURNS TABLE("id" integer, "nome" "text", "documento" "text", "ativo" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_search_digits text := regexp_replace(btrim(coalesce(p_search, '')), '[^0-9]', '', 'g');
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not c.has_compras_access(p_tenant_id, p_empresa_id) then
    raise exception 'compras_fornecedores_access_denied';
  end if;

  return query
  select
    f.id,
    f.nome::text,
    f.documento::text,
    f.ativo
  from public.fornecedores f
  where f.tenant_id = p_tenant_id
    and f.empresa_id = p_empresa_id
    and (
      v_search is null
      or f.nome ilike '%' || v_search || '%'
      or f.documento ilike '%' || v_search || '%'
      or (
        length(v_search_digits) >= 3
        and regexp_replace(coalesce(f.documento, ''), '[^0-9]', '', 'g') like '%' || v_search_digits || '%'
      )
    )
  order by f.nome asc, f.id asc;
end;
$$;


ALTER FUNCTION "public"."list_compras_fornecedores"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_search" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_compras_fornecedores"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_search" "text") IS 'Lista fornecedores por nome ou CPF/CNPJ para criacao de pedidos de compra.';



CREATE OR REPLACE FUNCTION "public"."list_compras_fornecedores_pendentes"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS TABLE("fornecedor_id" integer, "fornecedor_nome" "text", "fornecedor_documento" "text", "qtd_pendencias_abertas" bigint, "qtd_total_pendente" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not c.has_compras_access(p_tenant_id, p_empresa_id) then
    raise exception 'compras_fornecedores_pendentes_access_denied';
  end if;

  return query
  select
    cp.fornecedor_id,
    coalesce(f.nome, 'SEM FORNECEDOR')::text as fornecedor_nome,
    f.documento::text as fornecedor_documento,
    count(*)::bigint as qtd_pendencias_abertas,
    coalesce(sum(cp.quantidade), 0)::numeric as qtd_total_pendente
  from m.compra_pendencia cp
  left join public.fornecedores f
    on f.tenant_id = cp.tenant_id
   and f.empresa_id = cp.empresa_id
   and f.id = cp.fornecedor_id
  where cp.tenant_id = p_tenant_id
    and cp.empresa_id = p_empresa_id
    and cp.deleted_at is null
    and cp.status = 'PENDENTE'
  group by cp.fornecedor_id, f.nome, f.documento
  order by coalesce(f.nome, 'SEM FORNECEDOR') asc, cp.fornecedor_id asc;
end;
$$;


ALTER FUNCTION "public"."list_compras_fornecedores_pendentes"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_compras_fornecedores_pendentes"("p_tenant_id" "uuid", "p_empresa_id" "uuid") IS 'Lista fornecedores com pendencias de compra, incluindo CPF/CNPJ, no tenant e empresa ativos.';



CREATE OR REPLACE FUNCTION "public"."list_fornecedores_cadastro_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid") RETURNS TABLE("id" integer, "nome" "text", "ativo" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not public.can('cad_itens', 'write') then
    raise exception 'fornecedores_cadastro_itens_access_denied';
  end if;

  return query
  select
    f.id,
    f.nome::text,
    f.ativo
  from public.fornecedores f
  where f.tenant_id = p_tenant_id
    and f.empresa_id = p_empresa_id
    and f.ativo = true
  order by f.nome asc, f.id asc;
end;
$$;


ALTER FUNCTION "public"."list_fornecedores_cadastro_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_imported_nfe"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_emitente" "text" DEFAULT NULL::"text", "p_numero" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" bigint, "chave" "text", "numero" "text", "serie" "text", "emitente_nome" "text", "data_emissao" timestamp with time zone, "valor_total" numeric, "criado_em" timestamp with time zone, "finalidade_contexto" "public"."item_finalidade")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_emitente text := nullif(btrim(coalesce(p_emitente, '')), '');
  v_numero text := nullif(btrim(coalesce(p_numero, '')), '');
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 100));
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not (
       public.can('xml_import', 'execute', p_tenant_id)
       or public.can('xml_import_faturamento', 'execute', p_tenant_id)
       or public.can('estoque', 'read', p_tenant_id)
       or public.can('estoque', 'write', p_tenant_id)
       or public.can('financeiro', 'read', p_tenant_id)
       or public.can('financeiro', 'write', p_tenant_id)
       or public.can('cad_itens', 'write', p_tenant_id)
       or public.can('cad_fornecedores', 'write', p_tenant_id)
     ) then
    raise exception 'imported_nfe_list_access_denied';
  end if;

  if p_start_date is not null
     and p_end_date is not null
     and p_end_date <= p_start_date then
    raise exception 'imported_nfe_list_invalid_period';
  end if;

  return query
  select
    nf.id,
    nf.chave::text,
    nf.numero::text,
    nf.serie::text,
    nf.emitente_nome::text,
    nf.data_emissao,
    nf.valor_total,
    nf.criado_em,
    nf.finalidade_contexto
  from public.nf_entrada nf
  where nf.tenant_id = p_tenant_id
    and nf.empresa_id = p_empresa_id
    and nf.deleted_at is null
    and nf.chave is not null
    and (p_start_date is null or nf.data_emissao >= p_start_date)
    and (p_end_date is null or nf.data_emissao < p_end_date)
    and (v_emitente is null or nf.emitente_nome ilike '%' || v_emitente || '%')
    and (v_numero is null or nf.numero ilike '%' || v_numero || '%')
  order by nf.criado_em desc, nf.id desc
  limit v_limit;
end;
$$;


ALTER FUNCTION "public"."list_imported_nfe"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_emitente" "text", "p_numero" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_imported_nfe"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_emitente" "text", "p_numero" "text", "p_limit" integer) IS 'Lista NF-e importadas da empresa ativa apos validar tenant, empresa e permissao do usuario.';



CREATE OR REPLACE FUNCTION "public"."list_itens_auditoria"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_ids" integer[]) RETURNS TABLE("item_id" integer, "acao" "text", "data_acao" timestamp without time zone, "autor_nome" "text", "autor_identificador" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if p_empresa_id is distinct from public.current_empresa_id__by_tenant(p_tenant_id)
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id) then
    return;
  end if;

  return query
  select *
  from public.list_itens_auditoria_unscoped_20260810(
    p_tenant_id, p_empresa_id, p_item_ids
  );
end;
$$;


ALTER FUNCTION "public"."list_itens_auditoria"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_ids" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_itens_auditoria_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_ids" integer[]) RETURNS TABLE("item_id" integer, "acao" "text", "data_acao" timestamp without time zone, "autor_nome" "text", "autor_identificador" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'a'
    AS $$
  select
    i.id as item_id,
    case
      when nullif(trim(i.atualizado_por), '') is not null then 'alteracao'
      else 'criacao'
    end as acao,
    case
      when nullif(trim(i.atualizado_por), '') is not null then i.atualizado_em
      else i.criado_em
    end as data_acao,
    coalesce(
      nullif(trim(autor.nome), ''),
      nullif(trim(perfil.nome), ''),
      nullif(trim(coalesce(i.atualizado_por, i.criado_por)), ''),
      'Não identificado'
    ) as autor_nome,
    nullif(trim(coalesce(i.atualizado_por, i.criado_por)), '') as autor_identificador
  from public.itens i
  left join lateral (
    select u.nome, u.auth_user_id
      from a.usuario u
     where u.deleted_at is null
       and (
         lower(u.email) = lower(nullif(trim(coalesce(i.atualizado_por, i.criado_por)), ''))
         or u.auth_user_id::text = nullif(trim(coalesce(i.atualizado_por, i.criado_por)), '')
       )
     order by case
       when lower(u.email) = lower(nullif(trim(coalesce(i.atualizado_por, i.criado_por)), '')) then 0
       else 1
     end
     limit 1
  ) autor on true
  left join public.profiles perfil
    on perfil.id = autor.auth_user_id
  where i.tenant_id = p_tenant_id
    and i.empresa_id = p_empresa_id
    and i.id = any(coalesce(p_item_ids, array[]::integer[]))
    and (
      public.can__legacy_40734('estoque', 'read')
      or public.can__legacy_40734('os', 'read')
      or public.can__legacy_40734('cad_itens', 'write')
    );
$$;


ALTER FUNCTION "public"."list_itens_auditoria_unscoped_20260810"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_ids" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_motivos_compra_import"("p_origem" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "codigo" "text", "nome" "text", "requires_text" boolean, "requires_os" boolean, "aplica_em" "text", "favorito" boolean, "ordem" integer, "qtd_usos_180d" bigint, "ativo" boolean, "deleted_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid := public.current_tenant_id();
  v_empresa_id uuid;
  v_origem text := upper(trim(coalesce(p_origem, '')));
begin
  if auth.uid() is null or v_tenant_id is null then
    raise exception 'not_authenticated_or_tenant_missing';
  end if;

  v_empresa_id := public.current_empresa_id__by_tenant(v_tenant_id);

  if not public.has_active_empresa_access(v_tenant_id, v_empresa_id)
     or not f.has_motivo_compra_access(v_tenant_id) then
    raise exception 'motivo_compra_access_denied';
  end if;

  if v_origem not in ('', 'XML_PRODUTO') then
    raise exception 'invalid_motivo_compra_origem';
  end if;

  return query
  select
    mc.id,
    mc.codigo,
    mc.nome,
    mc.requires_text,
    mc.requires_os,
    mc.aplica_em,
    mc.favorito,
    mc.ordem,
    coalesce((
      select count(*)
      from f.titulo t
      where t.tenant_id = v_tenant_id
        and t.empresa_id = v_empresa_id
        and t.motivo_compra_id = mc.id
        and t.deleted_at is null
        and t.created_at >= now() - interval '180 days'
    ), 0)::bigint as qtd_usos_180d,
    mc.ativo,
    mc.deleted_at
  from f.motivo_compra mc
  where mc.tenant_id = v_tenant_id
    and mc.deleted_at is null
    and mc.ativo is true
    and mc.visivel_import_nfe is true
    and (v_origem <> 'XML_PRODUTO' or mc.aplica_em in ('PRODUTO','AMBOS'))
  order by mc.favorito desc,
           qtd_usos_180d desc,
           mc.ordem desc,
           mc.nome asc;
end;
$$;


