CREATE OR REPLACE FUNCTION "public"."os_reabrir_correcao"("p_os_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare v_auth_uid uuid:=auth.uid(); v_tenant_id uuid:=public.current_tenant_id(); v_empresa_id uuid:=public.current_empresa_id(); v_papel text;
begin
  if v_auth_uid is null or v_tenant_id is null or v_empresa_id is null or not public.has_active_empresa_access(v_tenant_id,v_empresa_id) then raise exception 'Autenticação e contexto de empresa são obrigatórios.'; end if;
  select ue.papel into v_papel from a.usuario u join a.usuario_empresa ue on ue.usuario_id=u.id where u.auth_user_id=v_auth_uid and u.ativo and u.deleted_at is null and ue.empresa_id=v_empresa_id and ue.ativo and ue.deleted_at is null limit 1;
  if upper(coalesce(v_papel,'')) not in ('ADMIN','DIRETOR','COORDENACAO') then raise exception 'Somente coordenação, admin ou diretor podem reabrir a OS.'; end if;
  if not exists (select 1 from public.ordens_servico where id=p_os_id and tenant_id=v_tenant_id and empresa_id=v_empresa_id and status_fluxo='concluida' for update) then raise exception 'Somente uma OS concluída pode ser reaberta para correção.'; end if;
  update public.ordens_servico set status_fluxo='em_andamento', status='em_andamento', data_conclusao=null, atualizado_em=now() where id=p_os_id and tenant_id=v_tenant_id and empresa_id=v_empresa_id;
  insert into public.ordens_servico_fluxo_eventos (tenant_id,empresa_id,os_id,evento,status_origem,status_destino,realizado_por) values (v_tenant_id,v_empresa_id,p_os_id,'reabrir_correcao','concluida','em_andamento',v_auth_uid);
  return jsonb_build_object('sucesso',true);
end;
$$;


ALTER FUNCTION "public"."os_reabrir_correcao"("p_os_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."os_reabrir_garantia"("p_os_id" integer, "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare v_auth_uid uuid:=auth.uid(); v_tenant_id uuid:=public.current_tenant_id(); v_empresa_id uuid:=public.current_empresa_id(); v_papel text; v_faturado_em timestamptz; v_presumida boolean;
begin
  if v_auth_uid is null or v_tenant_id is null or v_empresa_id is null or not public.has_active_empresa_access(v_tenant_id,v_empresa_id) then raise exception 'Autenticação e contexto de empresa são obrigatórios.'; end if;
  if nullif(btrim(p_motivo),'') is null then raise exception 'O motivo da garantia é obrigatório.'; end if;
  select ue.papel into v_papel from a.usuario u join a.usuario_empresa ue on ue.usuario_id=u.id where u.auth_user_id=v_auth_uid and u.ativo and u.deleted_at is null and ue.empresa_id=v_empresa_id and ue.ativo and ue.deleted_at is null limit 1;
  if upper(coalesce(v_papel,'')) not in ('COORDENACAO','FINANCEIRO') then raise exception 'Somente coordenação ou financeiro podem reabrir uma garantia.'; end if;
  select faturado_em, faturada_presumida_legado into v_faturado_em, v_presumida from public.ordens_servico where id=p_os_id and tenant_id=v_tenant_id and empresa_id=v_empresa_id and status_fluxo='faturada' for update;
  if not found then raise exception 'Somente uma OS faturada pode ser reaberta como garantia.'; end if;
  if v_presumida then raise exception 'OS faturada presumida de legado não pode ser reaberta como garantia.'; end if;
  if v_faturado_em is null or v_faturado_em < now() - interval '6 months' then raise exception 'A garantia só pode ser reaberta até seis meses após o faturamento.'; end if;
  update public.ordens_servico set status_fluxo='em_andamento_garantia', status='em_andamento', garantia_motivo=nullif(btrim(p_motivo),''), garantia_reaberta_em=now(), atualizado_em=now() where id=p_os_id and tenant_id=v_tenant_id and empresa_id=v_empresa_id;
  insert into public.ordens_servico_fluxo_eventos (tenant_id,empresa_id,os_id,evento,status_origem,status_destino,motivo,realizado_por) values (v_tenant_id,v_empresa_id,p_os_id,'reabrir_garantia','faturada','em_andamento_garantia',nullif(btrim(p_motivo),''),v_auth_uid);
  return jsonb_build_object('sucesso',true);
end;
$$;


ALTER FUNCTION "public"."os_reabrir_garantia"("p_os_id" integer, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."os_sync_itens_from_nf_entrada"("p_nf_entrada_id" bigint) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_nf public.nf_entrada%rowtype;
  v_inserted integer := 0;
begin
  select *
    into v_nf
  from public.nf_entrada nf
  where nf.id = p_nf_entrada_id;

  if v_nf.id is null then
    raise exception 'NF nao encontrada (id=%)', p_nf_entrada_id;
  end if;

  if v_nf.os_id is null then
    return 0;
  end if;

  -- Emitente igual a empresa selecionada caracteriza documento de saida.
  if exists (
    select 1
    from c.empresa e
    where e.tenant_id = v_nf.tenant_id
      and e.id = v_nf.empresa_id
      and e.deleted_at is null
      and nullif(regexp_replace(coalesce(e.cnpj, ''), '[^0-9]', '', 'g'), '') =
          nullif(regexp_replace(coalesce(v_nf.emitente_cnpj, ''), '[^0-9]', '', 'g'), '')
  ) then
    return 0;
  end if;

  insert into public.os_itens (
    tenant_id,
    empresa_id,
    os_id,
    item_id,
    quantidade,
    valor_unitario,
    valor_total,
    desconto_percentual,
    desconto_valor,
    baixa_estoque,
    observacoes,
    criado_em
  )
  select
    v_nf.tenant_id,
    v_nf.empresa_id,
    v_nf.os_id,
    ni.item_id::integer,
    round(ni.qtd, 3),
    round(ni.v_unit, 2),
    round(ni.v_prod, 2),
    0,
    0,
    false,
    'IMPORT XML NF ' || v_nf.chave || ' NF_ITEM ' || ni.id::text,
    now()
  from public.nf_entrada_itens ni
  where ni.tenant_id = v_nf.tenant_id
    and ni.empresa_id = v_nf.empresa_id
    and ni.nf_entrada_id = v_nf.id
    and ni.item_id is not null
    and ni.qtd > 0
    and not exists (
      select 1
      from public.os_itens oi
      where oi.tenant_id = v_nf.tenant_id
        and oi.empresa_id = v_nf.empresa_id
        and oi.os_id = v_nf.os_id
        and oi.observacoes = 'IMPORT XML NF ' || v_nf.chave || ' NF_ITEM ' || ni.id::text
    );

  get diagnostics v_inserted = row_count;

  update public.ordens_servico os
  set valor_total = coalesce((
        select sum(oi.valor_total)
        from public.os_itens oi
        where oi.tenant_id = v_nf.tenant_id
          and oi.empresa_id = v_nf.empresa_id
          and oi.os_id = v_nf.os_id
      ), 0),
      atualizado_em = now()
  where os.id = v_nf.os_id
    and os.tenant_id = v_nf.tenant_id
    and os.empresa_id = v_nf.empresa_id;

  return v_inserted;
end;
$$;


ALTER FUNCTION "public"."os_sync_itens_from_nf_entrada"("p_nf_entrada_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."os_sync_itens_from_nf_entrada"("p_nf_entrada_id" bigint) IS 'Sincroniza materiais de NF de entrada com OS e ignora NF-e emitida pela propria empresa (faturamento/saida).';



CREATE OR REPLACE FUNCTION "public"."pick_fiscal_regra"("p_ncm" "text", "p_cfop" "text", "p_cst_icms" "text", "p_cst_pis" "text", "p_cst_cofins" "text", "p_origem" smallint, "p_tipo_item" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select r.id
  from public.fiscal_regras r
  where r.tenant_id = public.current_tenant_id()
    and r.empresa_id = public.current_empresa_id()
    and r.ativo = true

    -- "match" com coringas (null = aceita qualquer)
    and (r.ncm is null or r.ncm = p_ncm)
    and (r.cfop is null or r.cfop = p_cfop)
    and (r.cst_icms is null or r.cst_icms = p_cst_icms)
    and (r.cst_pis is null or r.cst_pis = p_cst_pis)
    and (r.cst_cofins is null or r.cst_cofins = p_cst_cofins)
    and (r.origem is null or r.origem = p_origem)
    and (r.tipo_item is null or r.tipo_item = p_tipo_item)

  order by
    -- 1) prioridade explícita
    r.prioridade asc,

    -- 2) mais específico ganha (quanto mais campos preenchidos, menor "score")
    (
      (case when r.ncm is null then 1 else 0 end) +
      (case when r.cfop is null then 1 else 0 end) +
      (case when r.cst_icms is null then 1 else 0 end) +
      (case when r.cst_pis is null then 1 else 0 end) +
      (case when r.cst_cofins is null then 1 else 0 end) +
      (case when r.origem is null then 1 else 0 end) +
      (case when r.tipo_item is null then 1 else 0 end)
    ) asc,

    r.atualizado_em desc
  limit 1;
$$;


ALTER FUNCTION "public"."pick_fiscal_regra"("p_ncm" "text", "p_cfop" "text", "p_cst_icms" "text", "p_cst_pis" "text", "p_cst_cofins" "text", "p_origem" smallint, "p_tipo_item" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pick_fiscal_regra_admin"("p_tenant" "uuid", "p_empresa" "uuid", "p_ncm" "text", "p_cfop" "text", "p_cst_icms" "text", "p_cst_pis" "text", "p_cst_cofins" "text", "p_origem" smallint, "p_tipo_item" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
  select r.id
  from public.fiscal_regras r
  where public.has_active_empresa_access(p_tenant, p_empresa)
    and r.tenant_id = p_tenant
    and r.empresa_id = p_empresa
    and r.ativo is true
    and (r.ncm is null or r.ncm = p_ncm)
    and (r.cfop is null or r.cfop = p_cfop)
    and (r.cst_icms is null or r.cst_icms = p_cst_icms)
    and (r.cst_pis is null or r.cst_pis = p_cst_pis)
    and (r.cst_cofins is null or r.cst_cofins = p_cst_cofins)
    and (r.origem is null or r.origem = p_origem)
    and (r.tipo_item is null or r.tipo_item = p_tipo_item)
  order by coalesce(r.prioridade, 0) desc, r.atualizado_em desc
  limit 1;
$$;


ALTER FUNCTION "public"."pick_fiscal_regra_admin"("p_tenant" "uuid", "p_empresa" "uuid", "p_ncm" "text", "p_cfop" "text", "p_cst_icms" "text", "p_cst_pis" "text", "p_cst_cofins" "text", "p_origem" smallint, "p_tipo_item" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preencher_registro_os_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_user_nome text;
begin
  if v_user_id is not null then
    select nullif(trim(u.nome), '')
      into v_user_nome
      from a.usuario u
     where u.auth_user_id = v_user_id
       and u.deleted_at is null;

    if v_user_nome is null then
      select nullif(trim(p.nome), '')
        into v_user_nome
        from public.profiles p
       where p.id = v_user_id;
    end if;

    v_user_nome := coalesce(
      v_user_nome,
      nullif(trim(auth.jwt() -> 'user_metadata' ->> 'full_name'), ''),
      nullif(trim(auth.jwt() -> 'user_metadata' ->> 'name'), ''),
      nullif(trim(auth.jwt() ->> 'email'), ''),
      v_user_id::text
    );

    new.registrado_por := v_user_id;
    new.registrado_por_nome := v_user_nome;
  elsif tg_op = 'INSERT' then
    new.registrado_por := null;
    new.registrado_por_nome := coalesce(nullif(trim(new.registrado_por_nome), ''), 'Sistema');
  end if;

  new.registrado_em := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."preencher_registro_os_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reclassificar_mov_saida_para_os"("p_mov_id" bigint, "p_origem_os_id" integer, "p_realizado_por" "text" DEFAULT NULL::"text") RETURNS TABLE("mov_original_id" integer, "mov_ajuste_id" integer, "mov_saida_corrigida_id" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_mov public.movimentacoes%rowtype;
  v_os public.ordens_servico%rowtype;
  v_realizado_por text;
  v_motivo_saida text;
  v_os_label text;
  v_mov_ajuste_id integer;
  v_mov_saida_id integer;
begin
  if p_mov_id is null or p_origem_os_id is null then
    raise exception 'Parametros obrigatorios: p_mov_id e p_origem_os_id';
  end if;

  select *
    into v_mov
  from public.movimentacoes
  where id = p_mov_id;

  if not found then
    raise exception 'Movimentacao % nao encontrada', p_mov_id;
  end if;

  if v_mov.tipo <> 'saida' then
    raise exception 'Movimentacao % nao e saida', p_mov_id;
  end if;

  if v_mov.origem_os_id is not null then
    raise exception 'Movimentacao % ja possui origem_os_id', p_mov_id;
  end if;

  select *
    into v_os
  from public.ordens_servico os
  where os.id = p_origem_os_id
    and os.tenant_id = v_mov.tenant_id
    and os.empresa_id = v_mov.empresa_id;

  if not found then
    raise exception 'OS % nao encontrada no mesmo tenant/empresa da movimentacao %', p_origem_os_id, p_mov_id;
  end if;

  select m.id
    into v_mov_ajuste_id
  from public.movimentacoes m
  where m.tenant_id = v_mov.tenant_id
    and m.empresa_id = v_mov.empresa_id
    and m.item_id = v_mov.item_id
    and m.tipo = 'ajuste'
    and m.motivo = ('CORRECAO RASTREIO OS: neutraliza mov #' || v_mov.id::text)
  order by m.id asc
  limit 1;

  if v_mov_ajuste_id is not null then
    select m.id
      into v_mov_saida_id
    from public.movimentacoes m
    where m.tenant_id = v_mov.tenant_id
      and m.empresa_id = v_mov.empresa_id
      and m.item_id = v_mov.item_id
      and m.tipo = 'saida'
      and m.origem_os_id = p_origem_os_id
      and abs(coalesce(m.quantidade, 0) - coalesce(v_mov.quantidade, 0)) < 0.0001
      and abs(extract(epoch from (coalesce(m.data_movimentacao, m.created_at) - coalesce(v_mov.data_movimentacao, v_mov.created_at)))) <= 120
    order by m.id asc
    limit 1;

    if v_mov_saida_id is not null then
      return query
      select v_mov.id::integer, v_mov_ajuste_id, v_mov_saida_id;
      return;
    end if;
  end if;

  v_realizado_por := coalesce(p_realizado_por, auth.uid()::text, 'auditoria_sistema');

  insert into public.movimentacoes (
    tenant_id,
    empresa_id,
    item_id,
    tipo,
    quantidade,
    motivo,
    realizado_por,
    data_movimentacao,
    origem_nf_entrada_id,
    origem_os_id,
    created_at
  )
  values (
    v_mov.tenant_id,
    v_mov.empresa_id,
    v_mov.item_id,
    'ajuste',
    v_mov.quantidade,
    'CORRECAO RASTREIO OS: neutraliza mov #' || v_mov.id::text,
    v_realizado_por,
    coalesce(v_mov.data_movimentacao, now()),
    v_mov.origem_nf_entrada_id,
    null,
    now()
  )
  returning id into v_mov_ajuste_id;

  v_os_label := coalesce(nullif(trim(v_os.numero_os), ''), nullif(v_os.os_num::text, ''), v_os.id::text);
  v_motivo_saida := nullif(trim(coalesce(v_mov.motivo, '')), '');
  if v_motivo_saida is null then
    v_motivo_saida := 'Baixa de estoque via OS ' || v_os_label;
  end if;

  v_motivo_saida := trim(regexp_replace(v_motivo_saida, '[[:space:]]*\[OS[[:space:]]+[^\]]+\][[:space:]]*$', '', 'i'));
  if position(upper('OS ' || v_os_label) in upper(v_motivo_saida)) = 0 then
    v_motivo_saida := v_motivo_saida || ' [OS ' || v_os_label || ']';
  end if;

  insert into public.movimentacoes (
    tenant_id,
    empresa_id,
    item_id,
    tipo,
    quantidade,
    motivo,
    realizado_por,
    data_movimentacao,
    origem_nf_entrada_id,
    origem_os_id,
    created_at
  )
  values (
    v_mov.tenant_id,
    v_mov.empresa_id,
    v_mov.item_id,
    'saida',
    v_mov.quantidade,
    v_motivo_saida,
    v_realizado_por,
    coalesce(v_mov.data_movimentacao, now()),
    v_mov.origem_nf_entrada_id,
    p_origem_os_id,
    now()
  )
  returning id into v_mov_saida_id;

  return query
  select v_mov.id::integer, v_mov_ajuste_id, v_mov_saida_id;
end;
$_$;


ALTER FUNCTION "public"."reclassificar_mov_saida_para_os"("p_mov_id" bigint, "p_origem_os_id" integer, "p_realizado_por" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rejeitar_apontamento"("p_apontamento_id" "uuid", "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    SET "row_security" TO 'off'
    AS $$
declare v_auth_uid uuid:=auth.uid(); v_tenant_id uuid:=public.current_tenant_id(); v_empresa_id uuid:=public.current_empresa_id(); v_responsavel uuid;
begin
  if v_auth_uid is null or v_tenant_id is null or v_empresa_id is null or not public.has_active_empresa_access(v_tenant_id,v_empresa_id) then raise exception 'Autenticação e contexto de empresa são obrigatórios.'; end if;
  if nullif(btrim(p_motivo),'') is null then raise exception 'Informe o motivo da rejeição.'; end if;
  select os.responsavel_aprovacao_id into v_responsavel from public.apontamentos_horas ah join public.ordens_servico os on os.id=ah.os_id and os.tenant_id=ah.tenant_id and os.empresa_id=ah.empresa_id where ah.id=p_apontamento_id and ah.tenant_id=v_tenant_id and ah.empresa_id=v_empresa_id for update;
  if not found then raise exception 'Apontamento não encontrado na empresa atual.'; end if;
  if v_responsavel is distinct from v_auth_uid then raise exception 'Somente o responsável da OS pode rejeitar horas.'; end if;
  update public.apontamentos_horas set status_aprovacao='rejeitado', aprovado_por=null, aprovado_em=null, aprovado_automaticamente_em=null, rejeitado_em=now(), motivo_devolucao=nullif(btrim(p_motivo),'') where id=p_apontamento_id and tenant_id=v_tenant_id and empresa_id=v_empresa_id and status_aprovacao='pendente';
  if not found then raise exception 'O apontamento não está pendente de aprovação.'; end if;
  return jsonb_build_object('sucesso',true);
end;
$$;


ALTER FUNCTION "public"."rejeitar_apontamento"("p_apontamento_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rel_entradas_periodo_consolidado"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_ini" "date", "p_data_fim" "date", "p_fornecedor_prefix" "text" DEFAULT NULL::"text", "p_busca_item" "text" DEFAULT NULL::"text", "p_os_mode" "text" DEFAULT 'todos'::"text", "p_com_nf" boolean DEFAULT false, "p_destacar_saldo_alto" boolean DEFAULT false) RETURNS TABLE("item_id" integer, "fornecedor_id" integer, "codigo_interno" "text", "item_nome" "text", "fornecedor_nome" "text", "motivo" "text", "unidade_medida" "text", "qtd_comprada" numeric, "qtd_para_os" numeric, "qtd_para_estoque" numeric, "percentual_os" numeric, "destino_os" "text", "saldo_atual" numeric, "saldo_ajustado" numeric, "estoque_ideal" numeric, "situacao" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c', 'f', 'm', 'r', 'auth', 'extensions'
    AS $$
  with base as (
    select
      m.item_id,
      coalesce(nf.fornecedor_id::integer, i.fornecedor_id) as fornecedor_id,
      i.codigo_interno,
      i.nome as item_nome,
      i.unidade_medida,
      coalesce(e.quantidade_atual, 0)::numeric as saldo_atual,
      coalesce(i.estoque_ideal, 0)::numeric as estoque_ideal,
      m.quantidade::numeric as quantidade,
      m.origem_os_id,
      case
        when m.origem_nf_entrada_id is not null then 'NF ' || coalesce(nf.numero::text, '-')
        else 'MOV. MANUAL'
      end as motivo_linha
    from public.movimentacoes m
    join public.itens i
      on i.id = m.item_id
     and i.tenant_id = m.tenant_id
     and i.empresa_id = m.empresa_id
    left join public.nf_entrada nf
      on nf.id = m.origem_nf_entrada_id
     and nf.tenant_id = m.tenant_id
     and nf.empresa_id = m.empresa_id
    left join public.estoque e
      on e.item_id = m.item_id
     and e.tenant_id = m.tenant_id
     and e.empresa_id = m.empresa_id
    where m.tenant_id = p_tenant_id
      and m.empresa_id = p_empresa_id
      and m.tipo = 'entrada'
      and m.data_movimentacao::date between p_data_ini and p_data_fim
      and (
        p_os_mode = 'todos'
        or (p_os_mode = 'com_os' and m.origem_os_id is not null)
        or (p_os_mode = 'sem_os' and m.origem_os_id is null)
      )
      and (not p_com_nf or m.origem_nf_entrada_id is not null)
      and (
        coalesce(p_busca_item, '') = ''
        or i.nome ilike ('%' || p_busca_item || '%')
        or i.codigo_interno ilike ('%' || p_busca_item || '%')
      )
      and not exists (
        select 1
        from public.relatorio_operacional_exclusoes x
        where x.tenant_id = m.tenant_id
          and x.empresa_id = m.empresa_id
          and x.item_id = m.item_id
      )
  ),
  agg as (
    select
      b.item_id,
      b.fornecedor_id,
      max(b.codigo_interno) as codigo_interno,
      max(b.item_nome) as item_nome,
      max(b.unidade_medida) as unidade_medida,
      string_agg(distinct b.motivo_linha, ' | ' order by b.motivo_linha) as motivo,
      sum(b.quantidade) as qtd_comprada,
      sum(case when b.origem_os_id is not null then b.quantidade else 0 end) as qtd_para_os,
      sum(case when b.origem_os_id is null then b.quantidade else 0 end) as qtd_para_estoque,
      string_agg(distinct case when b.origem_os_id is not null then ('OS ' || b.origem_os_id::text) else null end, ' | ') as destino_os,
      max(b.saldo_atual) as saldo_atual,
      max(b.estoque_ideal) as estoque_ideal
    from base b
    group by b.item_id, b.fornecedor_id
  ),
  calc as (
    select
      a.*,
      case
        when a.saldo_atual < 0 then a.saldo_atual
        when a.qtd_para_os > 0 and a.saldo_atual >= a.qtd_para_os then (a.saldo_atual - a.qtd_para_os)
        else a.saldo_atual
      end as saldo_ajustado_calc
    from agg a
  )
  select
    c.item_id,
    c.fornecedor_id,
    c.codigo_interno,
    c.item_nome,
    coalesce(f.nome, 'SEM FORNECEDOR') as fornecedor_nome,
    coalesce(c.motivo, 'MOV. MANUAL') as motivo,
    c.unidade_medida,
    c.qtd_comprada,
    c.qtd_para_os,
    c.qtd_para_estoque,
    case when c.qtd_comprada > 0 then (c.qtd_para_os / c.qtd_comprada) * 100 else 0 end as percentual_os,
    coalesce(c.destino_os, '-') as destino_os,
    c.saldo_atual,
    c.saldo_ajustado_calc as saldo_ajustado,
    c.estoque_ideal,
    case
      when c.saldo_ajustado_calc < 0 then 'ALERTA'
      when c.estoque_ideal > 0 and c.saldo_ajustado_calc > c.estoque_ideal then 'ALERTA'
      else 'OK'
    end as situacao
  from calc c
  left join public.fornecedores f
    on f.id = c.fornecedor_id
   and f.tenant_id = p_tenant_id
   and f.empresa_id = p_empresa_id
  where (
    coalesce(p_fornecedor_prefix, '') = ''
    or coalesce(f.nome, 'SEM FORNECEDOR') ilike (p_fornecedor_prefix || '%')
  )
    and (
      not p_destacar_saldo_alto
      or (c.estoque_ideal > 0 and c.saldo_ajustado_calc > c.estoque_ideal)
    )
  order by coalesce(f.nome, 'SEM FORNECEDOR') asc, c.item_nome asc;
$$;


ALTER FUNCTION "public"."rel_entradas_periodo_consolidado"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_ini" "date", "p_data_fim" "date", "p_fornecedor_prefix" "text", "p_busca_item" "text", "p_os_mode" "text", "p_com_nf" boolean, "p_destacar_saldo_alto" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rel_entradas_periodo_detalhes"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_ini" "date", "p_data_fim" "date", "p_item_id" integer, "p_fornecedor_id" integer DEFAULT NULL::integer, "p_os_mode" "text" DEFAULT 'todos'::"text", "p_com_nf" boolean DEFAULT false) RETURNS TABLE("movimentacao_id" integer, "data_movimentacao" timestamp without time zone, "nf" "text", "quantidade" numeric, "os_id" integer, "tipo" "text", "realizado_por" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'a', 'c', 'f', 'm', 'r', 'auth', 'extensions'
    AS $$
  select
    m.id as movimentacao_id,
    m.data_movimentacao,
    coalesce(nf.numero::text, '-') as nf,
    m.quantidade::numeric as quantidade,
    m.origem_os_id as os_id,
    case when m.origem_os_id is not null then 'DIRETO OS' else 'ENTRADA ESTOQUE' end as tipo,
    nullif(trim(m.realizado_por), '') as realizado_por
  from public.movimentacoes m
  join public.itens i
    on i.id = m.item_id
   and i.tenant_id = m.tenant_id
   and i.empresa_id = m.empresa_id
  left join public.nf_entrada nf
    on nf.id = m.origem_nf_entrada_id
   and nf.tenant_id = m.tenant_id
   and nf.empresa_id = m.empresa_id
  where m.tenant_id = p_tenant_id
    and m.empresa_id = p_empresa_id
    and m.tipo = 'entrada'
    and m.item_id = p_item_id
    and m.data_movimentacao::date between p_data_ini and p_data_fim
    and (
      (p_fornecedor_id is null and coalesce(nf.fornecedor_id::integer, i.fornecedor_id) is null)
      or coalesce(nf.fornecedor_id::integer, i.fornecedor_id) = p_fornecedor_id
    )
    and (
      p_os_mode = 'todos'
      or (p_os_mode = 'com_os' and m.origem_os_id is not null)
      or (p_os_mode = 'sem_os' and m.origem_os_id is null)
    )
    and (not p_com_nf or m.origem_nf_entrada_id is not null)
  order by m.data_movimentacao desc, m.id desc;
$$;


ALTER FUNCTION "public"."rel_entradas_periodo_detalhes"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_data_ini" "date", "p_data_fim" "date", "p_item_id" integer, "p_fornecedor_id" integer, "p_os_mode" "text", "p_com_nf" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_os_item_reverte_estoque"("p_os_item_id" integer, "p_realizado_por" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_empresa_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_tenant uuid;
  v_empresa uuid;
  v_realizado_por text;
  v_row public.os_itens%rowtype;
  v_os public.ordens_servico%rowtype;
  v_os_label text;
  v_motivo text;
  v_quantidade_estorno numeric(14,3) := 0;
begin
  if auth.uid() is null then
    raise exception 'Nao autenticado';
  end if;

  v_tenant := public.current_tenant_id();
  if v_tenant is null then
    raise exception 'Tenant atual nao definido';
  end if;

  if not (
    public.can('os_rpcs', 'execute')
    or public.has_permission('os.write')
  ) then
    raise exception 'Sem permissao para executar operacao de OS';
  end if;

  v_empresa := coalesce(p_empresa_id, public.current_empresa_id());
  if v_empresa is null then
    raise exception 'Empresa atual nao definida. Informe p_empresa_id na chamada da RPC.';
  end if;

  perform public.set_current_empresa(v_empresa);

  v_realizado_por := coalesce(p_realizado_por, auth.uid()::text);

  select *
    into v_row
  from public.os_itens
  where id = p_os_item_id
    and tenant_id = v_tenant
    and empresa_id = v_empresa;

  if not found then
    raise exception 'Item da OS nao encontrado';
  end if;

  select *
    into v_os
  from public.ordens_servico os
  where os.id = v_row.os_id
    and os.tenant_id = v_tenant
    and os.empresa_id = v_empresa;

  if not found then
    raise exception 'OS do item nao encontrada no tenant/empresa atual';
  end if;

  v_quantidade_estorno := least(coalesce(v_row.quantidade_baixada, 0), v_row.quantidade);

  delete from public.os_itens
  where id = p_os_item_id
    and tenant_id = v_tenant
    and empresa_id = v_empresa;

  if v_quantidade_estorno > 0 then
    if not (public.can('estoque', 'write') or public.can('os_rpcs', 'execute')) then
      raise exception 'Sem permissao para movimentar estoque';
    end if;

    v_os_label := coalesce(nullif(trim(v_os.numero_os), ''), nullif(v_os.os_num::text, ''), v_os.id::text);
    v_motivo := nullif(trim(coalesce(p_motivo, '')), '');
    if v_motivo is null then
      v_motivo := 'Estorno baixa OS ' || v_os_label;
    end if;

    v_motivo := trim(regexp_replace(v_motivo, '[[:space:]]*\[OS[[:space:]]+[^\]]+\][[:space:]]*$', '', 'i'));
    if position(upper('OS ' || v_os_label) in upper(v_motivo)) = 0 then
      v_motivo := v_motivo || ' [OS ' || v_os_label || ']';
    end if;

    insert into public.movimentacoes (
      tenant_id,
      empresa_id,
      item_id,
      tipo,
      quantidade,
      motivo,
      realizado_por,
      data_movimentacao,
      origem_os_id,
      created_at
    )
    values (
      v_tenant,
      v_empresa,
      v_row.item_id,
      'entrada',
      v_quantidade_estorno,
      v_motivo,
      v_realizado_por,
      now(),
      v_row.os_id,
      now()
    );
  end if;

  update public.ordens_servico os
  set valor_total = coalesce((
        select sum(oi.valor_total)
        from public.os_itens oi
        where oi.os_id = v_row.os_id
          and oi.tenant_id = v_tenant
          and oi.empresa_id = v_empresa
      ), 0),
      atualizado_em = now()
  where os.id = v_row.os_id
    and os.tenant_id = v_tenant
    and os.empresa_id = v_empresa;
end;
$_$;


ALTER FUNCTION "public"."remove_os_item_reverte_estoque"("p_os_item_id" integer, "p_realizado_por" "text", "p_motivo" "text", "p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_cadastro_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_id" integer DEFAULT NULL::integer, "p_codigo" "text" DEFAULT NULL::"text", "p_produto" "text" DEFAULT NULL::"text", "p_fornecedor" "text" DEFAULT NULL::"text", "p_tipo" "text" DEFAULT NULL::"text", "p_finalidade" "text" DEFAULT NULL::"text", "p_ativo_only" boolean DEFAULT false, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 100, "p_sort_key" "text" DEFAULT 'nome'::"text", "p_sort_dir" "text" DEFAULT 'asc'::"text") RETURNS TABLE("total_count" bigint, "id" integer, "codigo_interno" "text", "codigo_barras" "text", "nome" "text", "descricao" "text", "tipo" "text", "categoria" "text", "subcategoria" "text", "fabricante" "text", "finalidade" "text", "motivo_compra_id" "uuid", "unidade_medida" "text", "peso_liquido" numeric, "controla_estoque" boolean, "estoque_minimo" numeric, "estoque_maximo" numeric, "estoque_ideal" numeric, "custo_ultima_compra" numeric, "custo_medio" numeric, "preco_unitario" numeric, "fornecedor_id" integer, "fornecedor_nome" "text", "ativo" boolean, "criado_em" timestamp without time zone, "criado_por" "text", "atualizado_em" timestamp without time zone, "atualizado_por" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_codigo text := nullif(btrim(coalesce(p_codigo, '')), '');
  v_produto text := nullif(btrim(coalesce(p_produto, '')), '');
  v_fornecedor text := nullif(btrim(coalesce(p_fornecedor, '')), '');
  v_tipo text := nullif(btrim(coalesce(p_tipo, '')), '');
  v_finalidade text := nullif(btrim(coalesce(p_finalidade, '')), '');
  v_page integer := greatest(1, coalesce(p_page, 1));
  v_page_size integer := greatest(1, least(coalesce(p_page_size, 100), 200));
  v_sort_key text := lower(coalesce(p_sort_key, 'nome'));
  v_sort_dir text := lower(coalesce(p_sort_dir, 'asc'));
  v_codigo_exato boolean := v_codigo ~ '^[0-9]+$';
  v_papel text := a.fn_current_empresa_papel(p_tenant_id, p_empresa_id);
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or coalesce(v_papel, '') not in (
       'ADMIN', 'DIRETOR', 'FINANCEIRO', 'FATURAMENTO', 'COORDENACAO',
       'COMPRAS', 'ALMOXARIFADO', 'TECNICO', 'APONTAMENTO_RH'
     ) then
    raise exception 'cadastro_item_search_access_denied';
  end if;

  if v_sort_key not in ('id', 'codigo_interno', 'nome', 'tipo', 'finalidade', 'fornecedor', 'ativo') then
    v_sort_key := 'nome';
  end if;
  if v_sort_dir not in ('asc', 'desc') then
    v_sort_dir := 'asc';
  end if;

  return query
  with filtered as (
    select
      i.id,
      i.codigo_interno::text,
      i.codigo_barras::text,
      i.nome::text,
      i.descricao,
      i.tipo::text,
      i.categoria::text,
      i.subcategoria::text,
      i.fabricante::text,
      i.finalidade::text,
      i.motivo_compra_id,
      i.unidade_medida::text,
      i.peso_liquido,
      i.controla_estoque,
      i.estoque_minimo::numeric,
      i.estoque_maximo::numeric,
      i.estoque_ideal::numeric,
      i.custo_ultima_compra,
      i.custo_medio,
      i.preco_unitario,
      i.fornecedor_id,
      f.nome::text as fornecedor_nome,
      i.ativo,
      i.criado_em,
      i.criado_por::text,
      i.atualizado_em,
      i.atualizado_por::text
    from public.itens i
    left join public.fornecedores f
      on f.tenant_id = i.tenant_id
     and f.empresa_id = i.empresa_id
     and f.id = i.fornecedor_id
    where i.tenant_id = p_tenant_id
      and i.empresa_id = p_empresa_id
      and (p_item_id is null or i.id = p_item_id)
      and (
        v_codigo is null
        or (v_codigo_exato and (i.codigo_interno = v_codigo or i.codigo_barras = v_codigo))
        or (not v_codigo_exato and (i.codigo_interno ilike '%' || v_codigo || '%' or i.codigo_barras ilike '%' || v_codigo || '%'))
      )
      and (v_produto is null or i.nome ilike '%' || v_produto || '%')
      and (v_fornecedor is null or f.nome ilike '%' || v_fornecedor || '%')
      and (v_tipo is null or i.tipo::text = v_tipo)
      and (v_finalidade is null or i.finalidade::text = v_finalidade)
      and (not coalesce(p_ativo_only, false) or i.ativo is true)
  ), counted as (
    select count(*) over () as total_count, filtered.*
    from filtered
  )
  select counted.*
  from counted
  order by
    case when v_sort_key = 'id' and v_sort_dir = 'asc' then counted.id end asc,
    case when v_sort_key = 'id' and v_sort_dir = 'desc' then counted.id end desc,
    case when v_sort_key = 'codigo_interno' and v_sort_dir = 'asc' then lower(counted.codigo_interno) end asc,
    case when v_sort_key = 'codigo_interno' and v_sort_dir = 'desc' then lower(counted.codigo_interno) end desc,
    case when v_sort_key = 'nome' and v_sort_dir = 'asc' then lower(counted.nome) end asc,
    case when v_sort_key = 'nome' and v_sort_dir = 'desc' then lower(counted.nome) end desc,
    case when v_sort_key = 'tipo' and v_sort_dir = 'asc' then lower(counted.tipo) end asc,
    case when v_sort_key = 'tipo' and v_sort_dir = 'desc' then lower(counted.tipo) end desc,
    case when v_sort_key = 'finalidade' and v_sort_dir = 'asc' then lower(counted.finalidade) end asc,
    case when v_sort_key = 'finalidade' and v_sort_dir = 'desc' then lower(counted.finalidade) end desc,
    case when v_sort_key = 'fornecedor' and v_sort_dir = 'asc' then lower(counted.fornecedor_nome) end asc,
    case when v_sort_key = 'fornecedor' and v_sort_dir = 'desc' then lower(counted.fornecedor_nome) end desc,
    case when v_sort_key = 'ativo' and v_sort_dir = 'asc' then counted.ativo end asc,
    case when v_sort_key = 'ativo' and v_sort_dir = 'desc' then counted.ativo end desc,
    counted.id desc
  offset ((v_page - 1) * v_page_size)
  limit v_page_size;
end;
$_$;


ALTER FUNCTION "public"."search_cadastro_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_id" integer, "p_codigo" "text", "p_produto" "text", "p_fornecedor" "text", "p_tipo" "text", "p_finalidade" "text", "p_ativo_only" boolean, "p_page" integer, "p_page_size" integer, "p_sort_key" "text", "p_sort_dir" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_estoque_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_busca_geral" "text" DEFAULT NULL::"text", "p_codigo" "text" DEFAULT NULL::"text", "p_nome" "text" DEFAULT NULL::"text", "p_fornecedor" "text" DEFAULT NULL::"text", "p_item_id" integer DEFAULT NULL::integer, "p_ativo_only" boolean DEFAULT false, "p_finalidade" "text" DEFAULT NULL::"text", "p_abaixo_minimo" boolean DEFAULT false, "p_sem_fornecedor" boolean DEFAULT false, "p_saldo_positivo" boolean DEFAULT false, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_sort_key" "text" DEFAULT 'nome'::"text", "p_sort_dir" "text" DEFAULT 'asc'::"text") RETURNS TABLE("total_count" bigint, "item_id" integer, "estoque_id" integer, "codigo_interno" "text", "codigo_barras" "text", "item_nome" "text", "tipo" "text", "unidade_medida" "text", "quantidade_atual" numeric, "preco_unitario" numeric, "custo_medio" numeric, "estoque_minimo" numeric, "estoque_ideal" numeric, "estoque_maximo" numeric, "fornecedor_id" integer, "fornecedor_nome" "text", "finalidade" "text", "controla_estoque" boolean, "ativo" boolean, "atualizado_em" timestamp without time zone, "localizacao" "text", "abaixo_minimo" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_busca text := nullif(btrim(coalesce(p_busca_geral, '')), '');
  v_codigo text := nullif(btrim(coalesce(p_codigo, '')), '');
  v_nome text := nullif(btrim(coalesce(p_nome, '')), '');
  v_fornecedor text := nullif(btrim(coalesce(p_fornecedor, '')), '');
  v_finalidade text := nullif(btrim(coalesce(p_finalidade, '')), '');
  v_page integer := greatest(1, coalesce(p_page, 1));
  v_page_size integer := greatest(1, least(coalesce(p_page_size, 50), 500));
  v_sort_key text := lower(coalesce(p_sort_key, 'nome'));
  v_sort_dir text := lower(coalesce(p_sort_dir, 'asc'));
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not (
       public.can('estoque', 'read', p_tenant_id)
       or public.can('estoque', 'write', p_tenant_id)
     ) then
    raise exception 'estoque_search_access_denied';
  end if;

  if v_sort_key not in ('id', 'codigo', 'nome') then
    v_sort_key := 'nome';
  end if;
  if v_sort_dir not in ('asc', 'desc') then
    v_sort_dir := 'asc';
  end if;

  return query
  with filtered as (
    select
      i.id as item_id,
      e.id as estoque_id,
      i.codigo_interno::text as codigo_interno,
      i.codigo_barras::text as codigo_barras,
      i.nome::text as item_nome,
      i.tipo::text as tipo,
      i.unidade_medida::text as unidade_medida,
      coalesce(e.quantidade_atual, 0)::numeric as quantidade_atual,
      i.preco_unitario::numeric as preco_unitario,
      i.custo_medio::numeric as custo_medio,
      i.estoque_minimo::numeric as estoque_minimo,
      i.estoque_ideal::numeric as estoque_ideal,
      i.estoque_maximo::numeric as estoque_maximo,
      i.fornecedor_id,
      f.nome::text as fornecedor_nome,
      i.finalidade::text as finalidade,
      i.controla_estoque,
      i.ativo,
      e.atualizado_em,
      e.localizacao::text as localizacao,
      (coalesce(e.quantidade_atual, 0) < coalesce(i.estoque_minimo, 0)) as abaixo_minimo
    from public.itens i
    left join public.estoque e
      on e.tenant_id = i.tenant_id
     and e.empresa_id = i.empresa_id
     and e.item_id = i.id
    left join public.fornecedores f
      on f.tenant_id = i.tenant_id
     and f.empresa_id = i.empresa_id
     and f.id = i.fornecedor_id
    where i.tenant_id = p_tenant_id
      and i.empresa_id = p_empresa_id
      and i.tipo = 'produto'
      and i.controla_estoque is true
      and (not coalesce(p_ativo_only, false) or i.ativo is true)
      and (p_item_id is null or i.id = p_item_id)
      and (
        v_busca is null
        or i.codigo_interno ilike '%' || v_busca || '%'
        or i.codigo_barras ilike '%' || v_busca || '%'
        or i.nome ilike '%' || v_busca || '%'
      )
      and (
        v_codigo is null
        or i.codigo_interno ilike '%' || v_codigo || '%'
        or i.codigo_barras ilike '%' || v_codigo || '%'
      )
      and (v_nome is null or i.nome ilike '%' || v_nome || '%')
      and (v_finalidade is null or i.finalidade::text = v_finalidade)
      and (
        (v_fornecedor is null and not coalesce(p_sem_fornecedor, false))
        or (v_fornecedor is null and coalesce(p_sem_fornecedor, false) and i.fornecedor_id is null)
        or (v_fornecedor is not null and f.nome ilike '%' || v_fornecedor || '%')
        or (v_fornecedor is not null and coalesce(p_sem_fornecedor, false) and i.fornecedor_id is null)
      )
      and (not coalesce(p_saldo_positivo, false) or coalesce(e.quantidade_atual, 0) > 0)
      and (
        not coalesce(p_abaixo_minimo, false)
        or coalesce(e.quantidade_atual, 0) < coalesce(i.estoque_minimo, 0)
      )
  ), counted as (
    select count(*) over () as total_count, filtered.*
    from filtered
  )
  select
    counted.total_count,
    counted.item_id,
    counted.estoque_id,
    counted.codigo_interno,
    counted.codigo_barras,
    counted.item_nome,
    counted.tipo,
    counted.unidade_medida,
    counted.quantidade_atual,
    counted.preco_unitario,
    counted.custo_medio,
    counted.estoque_minimo,
    counted.estoque_ideal,
    counted.estoque_maximo,
    counted.fornecedor_id,
    counted.fornecedor_nome,
    counted.finalidade,
    counted.controla_estoque,
    counted.ativo,
    counted.atualizado_em,
    counted.localizacao,
    counted.abaixo_minimo
  from counted
  order by
    case when v_sort_key = 'id' and v_sort_dir = 'asc' then counted.item_id end asc,
    case when v_sort_key = 'id' and v_sort_dir = 'desc' then counted.item_id end desc,
    case when v_sort_key = 'codigo' and v_sort_dir = 'asc' then lower(counted.codigo_interno) end asc,
    case when v_sort_key = 'codigo' and v_sort_dir = 'desc' then lower(counted.codigo_interno) end desc,
    case when v_sort_key = 'nome' and v_sort_dir = 'asc' then lower(counted.item_nome) end asc,
    case when v_sort_key = 'nome' and v_sort_dir = 'desc' then lower(counted.item_nome) end desc,
    counted.item_id asc
  offset ((v_page - 1) * v_page_size)
  limit v_page_size;
end;
$$;


ALTER FUNCTION "public"."search_estoque_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_busca_geral" "text", "p_codigo" "text", "p_nome" "text", "p_fornecedor" "text", "p_item_id" integer, "p_ativo_only" boolean, "p_finalidade" "text", "p_abaixo_minimo" boolean, "p_sem_fornecedor" boolean, "p_saldo_positivo" boolean, "p_page" integer, "p_page_size" integer, "p_sort_key" "text", "p_sort_dir" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_estoque_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_busca_geral" "text", "p_codigo" "text", "p_nome" "text", "p_fornecedor" "text", "p_item_id" integer, "p_ativo_only" boolean, "p_finalidade" "text", "p_abaixo_minimo" boolean, "p_sem_fornecedor" boolean, "p_saldo_positivo" boolean, "p_page" integer, "p_page_size" integer, "p_sort_key" "text", "p_sort_dir" "text") IS 'Busca itens de estoque por codigo, barras ou nome apos validar o contexto e a permissao de estoque.';



CREATE OR REPLACE FUNCTION "public"."search_orcamento_clientes"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_term" "text", "p_limit" integer DEFAULT 25) RETURNS TABLE("id" integer, "nome" "text", "documento" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_term text := btrim(coalesce(p_term, ''));
  v_term_digits text := regexp_replace(btrim(coalesce(p_term, '')), '[^0-9]', '', 'g');
  v_limit integer := greatest(1, least(coalesce(p_limit, 25), 50));
  v_id bigint;
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not c.has_comercial_access(p_tenant_id, p_empresa_id) then
    raise exception 'orcamento_client_search_access_denied';
  end if;

  if v_term = '' then
    return;
  end if;

  if v_term ~ '^[0-9]{1,18}$' then
    v_id := v_term::bigint;
  end if;

  return query
  select
    cli.id,
    cli.nome::text,
    cli.documento::text
  from public.clientes cli
  where cli.tenant_id = p_tenant_id
    and cli.empresa_id = p_empresa_id
    and (
      (v_id is not null and cli.id::bigint = v_id)
      or cli.nome ilike '%' || v_term || '%'
      or cli.documento ilike '%' || v_term || '%'
      or (
        length(v_term_digits) >= 3
        and regexp_replace(coalesce(cli.documento, ''), '[^0-9]', '', 'g') like '%' || v_term_digits || '%'
      )
    )
  order by cli.nome asc, cli.id asc
  limit v_limit;
end;
$_$;


ALTER FUNCTION "public"."search_orcamento_clientes"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_term" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_orcamento_clientes"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_term" "text", "p_limit" integer) IS 'Busca clientes por nome, ID ou CPF/CNPJ para orcamentos, limitada ao tenant e empresa ativos.';



CREATE OR REPLACE FUNCTION "public"."search_orcamento_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_term" "text" DEFAULT NULL::"text", "p_fornecedor" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 150) RETURNS TABLE("id" integer, "codigo_interno" "text", "nome" "text", "fabricante" "text", "preco_unitario" numeric, "custo_ultima_compra" numeric, "fornecedor" "text", "ultima_entrada" timestamp without time zone, "estoque_atual" numeric, "preco_sugerido" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_term text := nullif(btrim(coalesce(p_term, '')), '');
  v_fornecedor text := nullif(btrim(coalesce(p_fornecedor, '')), '');
  v_limit integer := greatest(1, least(coalesce(p_limit, 150), 200));
  v_codigo_exato boolean := v_term ~ '^[0-9]+$';
begin
  if auth.uid() is null or p_tenant_id is null or p_empresa_id is null
     or not public.has_active_empresa_access(p_tenant_id,p_empresa_id)
     or not c.has_comercial_access(p_tenant_id,p_empresa_id) then
    raise exception 'orcamento_item_search_access_denied';
  end if;

  return query
  select i.id, i.codigo_interno::text, i.nome::text, i.fabricante::text,
         i.preco_unitario, i.custo_ultima_compra, f.nome::text,
         mov.data_movimentacao, e.quantidade_atual,
         public.fn_preco_venda_item_unscoped(p_tenant_id,p_empresa_id,i.id)
  from public.itens i
  left join public.fornecedores f on f.tenant_id=i.tenant_id and f.empresa_id=i.empresa_id and f.id=i.fornecedor_id
  left join public.estoque e on e.tenant_id=i.tenant_id and e.empresa_id=i.empresa_id and e.item_id=i.id
  left join lateral (
    select m.data_movimentacao from public.movimentacoes m
    where m.tenant_id=i.tenant_id and m.empresa_id=i.empresa_id and m.item_id=i.id and m.tipo='entrada'
    order by m.data_movimentacao desc nulls last, m.id desc limit 1
  ) mov on true
  where i.tenant_id=p_tenant_id and i.empresa_id=p_empresa_id and i.ativo is true
    and (
      v_term is null
      or (v_codigo_exato and (i.codigo_interno=v_term or i.codigo_barras=v_term or i.id::text=v_term))
      or (not v_codigo_exato and (i.nome ilike '%'||v_term||'%' or i.codigo_interno ilike '%'||v_term||'%' or i.fabricante ilike '%'||v_term||'%'))
    )
    and (v_fornecedor is null or f.nome ilike '%'||v_fornecedor||'%')
  order by i.nome, i.id
  limit v_limit;
end;
$_$;


ALTER FUNCTION "public"."search_orcamento_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_term" "text", "p_fornecedor" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_os_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_term" "text" DEFAULT NULL::"text", "p_fornecedor" "text" DEFAULT NULL::"text", "p_despesa_only" boolean DEFAULT false, "p_limit" integer DEFAULT 150) RETURNS TABLE("id" integer, "codigo_interno" "text", "nome" "text", "fabricante" "text", "tipo" "text", "finalidade" "text", "preco_unitario" numeric, "aliquota_ipi" numeric, "controla_estoque" boolean, "fornecedor" "text", "ultima_entrada" timestamp without time zone, "estoque_atual" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_term text := nullif(btrim(coalesce(p_term, '')), '');
  v_fornecedor text := nullif(btrim(coalesce(p_fornecedor, '')), '');
  v_limit integer := greatest(1, least(coalesce(p_limit, 150), 200));
  v_codigo_exato boolean := v_term ~ '^[0-9]+$';
  v_papel text := a.fn_current_empresa_papel(p_tenant_id, p_empresa_id);
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or coalesce(v_papel, '') not in (
       'ADMIN', 'DIRETOR', 'FINANCEIRO', 'FATURAMENTO', 'COORDENACAO',
       'COMPRAS', 'ALMOXARIFADO', 'TECNICO', 'APONTAMENTO_RH'
     ) then
    raise exception 'os_item_search_access_denied';
  end if;

  return query
  select
    i.id,
    i.codigo_interno::text,
    i.nome::text,
    i.fabricante::text,
    i.tipo::text,
    i.finalidade::text,
    i.preco_unitario,
    i.aliquota_ipi,
    i.controla_estoque,
    f.nome::text as fornecedor,
    mov.data_movimentacao as ultima_entrada,
    e.quantidade_atual as estoque_atual
  from public.itens i
  left join public.fornecedores f
    on f.tenant_id = i.tenant_id
   and f.empresa_id = i.empresa_id
   and f.id = i.fornecedor_id
  left join public.estoque e
    on e.tenant_id = i.tenant_id
   and e.empresa_id = i.empresa_id
   and e.item_id = i.id
  left join lateral (
    select m.data_movimentacao
    from public.movimentacoes m
    where m.tenant_id = i.tenant_id
      and m.empresa_id = i.empresa_id
      and m.item_id = i.id
      and m.tipo = 'entrada'
    order by m.data_movimentacao desc nulls last, m.id desc
    limit 1
  ) mov on true
  where i.tenant_id = p_tenant_id
    and i.empresa_id = p_empresa_id
    and i.ativo is true
    and (not coalesce(p_despesa_only, false) or i.id between 1 and 99)
    and (
      v_term is null
      or (
        v_codigo_exato
        and (i.id::text = v_term or i.codigo_interno = v_term or i.codigo_barras = v_term)
      )
      or (
        not v_codigo_exato
        and (
          i.nome ilike '%' || v_term || '%'
          or i.codigo_interno ilike '%' || v_term || '%'
          or i.fabricante ilike '%' || v_term || '%'
        )
      )
    )
    and (v_fornecedor is null or f.nome ilike '%' || v_fornecedor || '%')
  order by i.nome asc, i.id asc
  limit v_limit;
end;
$_$;


ALTER FUNCTION "public"."search_os_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_term" "text", "p_fornecedor" "text", "p_despesa_only" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_relatorio_estoque"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_busca" "text" DEFAULT NULL::"text", "p_fornecedor" "text" DEFAULT NULL::"text", "p_finalidade" "text" DEFAULT NULL::"text", "p_localizacao" "text" DEFAULT NULL::"text", "p_abaixo_minimo" boolean DEFAULT false, "p_sem_fornecedor" boolean DEFAULT false, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_sort_key" "text" DEFAULT 'nome'::"text", "p_sort_dir" "text" DEFAULT 'asc'::"text") RETURNS TABLE("total_count" bigint, "item_id" integer, "codigo_interno" "text", "item_nome" "text", "unidade_medida" "text", "quantidade_atual" numeric, "preco_unitario" numeric, "custo_medio" numeric, "estoque_minimo" numeric, "estoque_ideal" numeric, "estoque_maximo" numeric, "fornecedor_id" integer, "fornecedor_nome" "text", "localizacao" "text", "finalidade" "text", "controla_estoque" boolean, "abaixo_minimo" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_busca text := nullif(btrim(coalesce(p_busca, '')), '');
  v_fornecedor text := nullif(btrim(coalesce(p_fornecedor, '')), '');
  v_finalidade text := nullif(btrim(coalesce(p_finalidade, '')), '');
  v_localizacao text := nullif(btrim(coalesce(p_localizacao, '')), '');
  v_page integer := greatest(1, coalesce(p_page, 1));
  v_page_size integer := greatest(1, least(coalesce(p_page_size, 50), 500));
  v_sort_key text := lower(coalesce(p_sort_key, 'nome'));
  v_sort_dir text := lower(coalesce(p_sort_dir, 'asc'));
begin
  if auth.uid() is null
     or p_tenant_id is null
     or p_empresa_id is null
     or public.current_tenant_id() is distinct from p_tenant_id
     or public.current_empresa_id__by_tenant(p_tenant_id) is distinct from p_empresa_id
     or not public.has_active_empresa_access(p_tenant_id, p_empresa_id)
     or not (
       public.can('estoque', 'read', p_tenant_id)
       or public.can('estoque', 'write', p_tenant_id)
     ) then
    raise exception 'estoque_report_access_denied';
  end if;

  if v_sort_key not in ('id', 'codigo', 'nome') then
    v_sort_key := 'nome';
  end if;
  if v_sort_dir not in ('asc', 'desc') then
    v_sort_dir := 'asc';
  end if;

  return query
  with filtered as (
    select
      i.id as item_id,
      i.codigo_interno::text as codigo_interno,
      i.nome::text as item_nome,
      i.unidade_medida::text as unidade_medida,
      coalesce(e.quantidade_atual, 0)::numeric as quantidade_atual,
      i.preco_unitario::numeric as preco_unitario,
      i.custo_medio::numeric as custo_medio,
      i.estoque_minimo::numeric as estoque_minimo,
      i.estoque_ideal::numeric as estoque_ideal,
      i.estoque_maximo::numeric as estoque_maximo,
      i.fornecedor_id,
      f.nome::text as fornecedor_nome,
      e.localizacao::text as localizacao,
      i.finalidade::text as finalidade,
      i.controla_estoque,
      (coalesce(e.quantidade_atual, 0) < coalesce(i.estoque_minimo, 0)) as abaixo_minimo
    from public.itens i
    left join public.estoque e
      on e.tenant_id = i.tenant_id
     and e.empresa_id = i.empresa_id
     and e.item_id = i.id
    left join public.fornecedores f
      on f.tenant_id = i.tenant_id
     and f.empresa_id = i.empresa_id
     and f.id = i.fornecedor_id
    where i.tenant_id = p_tenant_id
      and i.empresa_id = p_empresa_id
      and i.tipo = 'produto'
      and i.controla_estoque is true
      and (
        v_busca is null
        or i.codigo_interno ilike '%' || v_busca || '%'
        or i.codigo_barras ilike '%' || v_busca || '%'
        or i.nome ilike '%' || v_busca || '%'
      )
      and (v_finalidade is null or i.finalidade::text = v_finalidade)
      and (v_localizacao is null or e.localizacao ilike '%' || v_localizacao || '%')
      and (
        (v_fornecedor is null and not coalesce(p_sem_fornecedor, false))
        or (v_fornecedor is null and coalesce(p_sem_fornecedor, false) and i.fornecedor_id is null)
        or (v_fornecedor is not null and f.nome ilike '%' || v_fornecedor || '%')
        or (v_fornecedor is not null and coalesce(p_sem_fornecedor, false) and i.fornecedor_id is null)
      )
      and (
        coalesce(p_abaixo_minimo, false)
        or coalesce(e.quantidade_atual, 0) > 0
      )
      and (
        not coalesce(p_abaixo_minimo, false)
        or coalesce(e.quantidade_atual, 0) < coalesce(i.estoque_minimo, 0)
      )
  ), counted as (
    select count(*) over () as total_count, filtered.*
    from filtered
  )
  select
    counted.total_count,
    counted.item_id,
    counted.codigo_interno,
    counted.item_nome,
    counted.unidade_medida,
    counted.quantidade_atual,
    counted.preco_unitario,
    counted.custo_medio,
    counted.estoque_minimo,
    counted.estoque_ideal,
    counted.estoque_maximo,
    counted.fornecedor_id,
    counted.fornecedor_nome,
    counted.localizacao,
    counted.finalidade,
    counted.controla_estoque,
    counted.abaixo_minimo
  from counted
  order by
    case when v_sort_key = 'id' and v_sort_dir = 'asc' then counted.item_id end asc,
    case when v_sort_key = 'id' and v_sort_dir = 'desc' then counted.item_id end desc,
    case when v_sort_key = 'codigo' and v_sort_dir = 'asc' then lower(counted.codigo_interno) end asc,
    case when v_sort_key = 'codigo' and v_sort_dir = 'desc' then lower(counted.codigo_interno) end desc,
    case when v_sort_key = 'nome' and v_sort_dir = 'asc' then lower(counted.item_nome) end asc,
    case when v_sort_key = 'nome' and v_sort_dir = 'desc' then lower(counted.item_nome) end desc,
    counted.item_id asc
  offset ((v_page - 1) * v_page_size)
  limit v_page_size;
end;
$$;


ALTER FUNCTION "public"."search_relatorio_estoque"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_busca" "text", "p_fornecedor" "text", "p_finalidade" "text", "p_localizacao" "text", "p_abaixo_minimo" boolean, "p_sem_fornecedor" boolean, "p_page" integer, "p_page_size" integer, "p_sort_key" "text", "p_sort_dir" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_relatorio_estoque"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_busca" "text", "p_fornecedor" "text", "p_finalidade" "text", "p_localizacao" "text", "p_abaixo_minimo" boolean, "p_sem_fornecedor" boolean, "p_page" integer, "p_page_size" integer, "p_sort_key" "text", "p_sort_dir" "text") IS 'Relatorio de saldo consolidado, sempre escopado ao tenant e empresa ativos.';



CREATE OR REPLACE FUNCTION "public"."set_current_empresa"("p_empresa_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Nao autenticado';
  end if;

  if p_empresa_id is null then
    raise exception 'Empresa nao informada';
  end if;

  v_tenant_id := public.current_tenant_id();
  if v_tenant_id is null then
    raise exception 'Tenant atual nao definido';
  end if;

  if not public.has_active_empresa_access(v_tenant_id, p_empresa_id) then
    raise exception 'Sem acesso ativo a esta empresa';
  end if;

  insert into public.user_empresa_context (user_id, tenant_id, empresa_id)
  values (auth.uid(), v_tenant_id, p_empresa_id)
  on conflict (user_id, tenant_id)
  do update set
    empresa_id = excluded.empresa_id,
    updated_at = now();

  perform set_config('app.current_empresa_id', p_empresa_id::text, true);
end;
$$;


ALTER FUNCTION "public"."set_current_empresa"("p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_current_tenant"("p_tenant_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Nao autenticado';
  end if;

  if not public.has_active_tenant_access(p_tenant_id) then
    raise exception 'Sem acesso ativo a este tenant';
  end if;

  insert into public.user_tenant_context (user_id, tenant_id)
  values (auth.uid(), p_tenant_id)
  on conflict (user_id)
  do update set
    tenant_id = excluded.tenant_id,
    updated_at = now();

  perform set_config('app.current_tenant_id', p_tenant_id::text, true);
end;
$$;


ALTER FUNCTION "public"."set_current_tenant"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_fornecedor_import_defaults"("p_fornecedor_id" integer, "p_finalidade" "public"."item_finalidade", "p_motivo_compra_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'a', 'f'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_empresa uuid := public.current_empresa_id();
  v_ok boolean;
begin
  -- Permissão: ADMIN do tenant OU papéis da empresa (os que importam)
  select (
    exists (
      select 1
      from a.usuario u
      join a.usuario_tenant ut on ut.usuario_id = u.id
      where u.auth_user_id = auth.uid()
        and ut.tenant_id = v_tenant
        and ut.deleted_at is null
        and ut.ativo = true
        and ut.papel in ('OWNER','ADMIN','DIRETOR')
    )
    or
    exists (
      select 1
      from a.usuario u
      join a.usuario_empresa ue on ue.usuario_id = u.id
      where u.auth_user_id = auth.uid()
        and ue.empresa_id = v_empresa
        and ue.deleted_at is null
        and ue.ativo = true
        and ue.papel in ('ADMIN','FINANCEIRO','COORDENACAO','COMPRAS','ALMOXARIFADO','APONTAMENTO_RH')
    )
  ) into v_ok;

  if not v_ok then
    raise exception 'Sem permissão para alterar defaults de importação do fornecedor.';
  end if;

  -- Valida fornecedor no tenant/empresa do contexto
  if not exists (
    select 1
    from public.fornecedores f
    where f.id = p_fornecedor_id
      and f.tenant_id = v_tenant
      and f.empresa_id = v_empresa
  ) then
    raise exception 'Fornecedor inválido para o contexto atual.';
  end if;

  -- Valida motivo (se informado): mesmo tenant + ativo + não deletado
  if p_motivo_compra_id is not null then
    if not exists (
      select 1
      from f.motivo_compra mc
      where mc.id = p_motivo_compra_id
        and mc.tenant_id = v_tenant
        and mc.deleted_at is null
        and mc.ativo = true
        -- IMPORTAÇÃO XML (produtos): bloquear motivo de SERVIÇO
        and (
          -- se você já criou aplica_em:
          (mc.aplica_em in ('PRODUTO','AMBOS'))
        )
    ) then
      raise exception 'Motivo inválido (ou não permitido para importação de produtos).';
    end if;
  end if;

  update public.fornecedores
  set
    finalidade_padrao = p_finalidade,
    motivo_compra_padrao_id = p_motivo_compra_id,
    atualizado_em = now()
  where id = p_fornecedor_id
    and tenant_id = v_tenant
    and empresa_id = v_empresa;
end;
$$;


ALTER FUNCTION "public"."set_fornecedor_import_defaults"("p_fornecedor_id" integer, "p_finalidade" "public"."item_finalidade", "p_motivo_compra_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_fornecedor_import_defaults"("p_fornecedor_id" bigint, "p_finalidade" "public"."item_finalidade", "p_motivo_compra_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_tenant_id uuid;
  v_empresa_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Usuario nao autenticado';
  end if;

  select f.tenant_id, f.empresa_id
    into v_tenant_id, v_empresa_id
  from public.fornecedores f
  where f.id = p_fornecedor_id
  limit 1;

  if v_tenant_id is null or v_empresa_id is null then
    raise exception 'Fornecedor nao encontrado';
  end if;

  -- Ensure the caller belongs to the same tenant/empresa.
  if not exists (
    select 1
    from public.tenant_memberships tm
    where tm.user_id = auth.uid()
      and tm.tenant_id = v_tenant_id
      and tm.status = 'active'
  ) then
    raise exception 'Tenant nao autorizado';
  end if;

  if not exists (
    select 1
    from public.empresa_memberships em
    where em.user_id = auth.uid()
      and em.empresa_id = v_empresa_id
      and em.status = 'active'
  ) then
    raise exception 'Empresa nao autorizada';
  end if;

  -- Best-effort: set context so public.can(...) evaluates consistently.
  begin
    perform public.set_current_tenant(v_tenant_id);
  exception
    when undefined_function then
      null;
  end;

  begin
    perform public.set_current_empresa(v_empresa_id);
  exception
    when undefined_function then
      null;
  end;

  if not (
    public.can('xml_import','execute')
    or public.can('cad_fornecedores','write')
    or public.can('estoque','write')
  ) then
    raise exception 'Sem permissao.';
  end if;

  -- Optional validation: if f.motivo_compra exists, ensure the chosen motivo belongs to the same tenant.
  if p_motivo_compra_id is not null and to_regclass('f.motivo_compra') is not null then
    if not exists (
      select 1
      from f.motivo_compra m
      where m.id = p_motivo_compra_id
        and m.tenant_id = v_tenant_id
        and m.ativo = true
        and m.deleted_at is null
    ) then
      raise exception 'Motivo invalido para este tenant.';
    end if;
  end if;

  update public.fornecedores f
  set finalidade_padrao = p_finalidade,
      motivo_compra_padrao_id = p_motivo_compra_id,
      atualizado_em = now()
  where f.id = p_fornecedor_id;
end;
$$;


ALTER FUNCTION "public"."set_fornecedor_import_defaults"("p_fornecedor_id" bigint, "p_finalidade" "public"."item_finalidade", "p_motivo_compra_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_os_item_quantidade_baixada"("p_os_item_id" integer, "p_quantidade_baixada" numeric, "p_realizado_por" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_empresa_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."os_itens"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_tenant uuid;
  v_empresa uuid;
  v_realizado_por text;
  v_row public.os_itens%rowtype;
  v_updated public.os_itens%rowtype;
  v_item public.itens%rowtype;
  v_os public.ordens_servico%rowtype;
  v_atual numeric(14,3);
  v_nova numeric(14,3);
  v_delta numeric(14,3);
  v_saldo_atual numeric(14,3) := 0;
  v_os_label text;
  v_motivo text;
begin
  if auth.uid() is null then
    raise exception 'Nao autenticado';
  end if;

  v_tenant := public.current_tenant_id();
  if v_tenant is null then
    raise exception 'Tenant atual nao definido';
  end if;

  if not (
    public.can('os_rpcs', 'execute')
    or public.has_permission('os.write')
  ) then
    raise exception 'Sem permissao para executar operacao de OS';
  end if;

  v_empresa := coalesce(p_empresa_id, public.current_empresa_id());
  if v_empresa is null then
    raise exception 'Empresa atual nao definida. Informe p_empresa_id na chamada da RPC.';
  end if;

  perform public.set_current_empresa(v_empresa);

  v_realizado_por := coalesce(p_realizado_por, auth.uid()::text);

  select *
    into v_row
  from public.os_itens
  where id = p_os_item_id
    and tenant_id = v_tenant
    and empresa_id = v_empresa
  for update;

  if not found then
    raise exception 'Item da OS nao encontrado';
  end if;

  select *
    into v_os
  from public.ordens_servico os
  where os.id = v_row.os_id
    and os.tenant_id = v_tenant
    and os.empresa_id = v_empresa;

  if not found then
    raise exception 'OS do item nao encontrada no tenant/empresa atual';
  end if;

  select *
    into v_item
  from public.itens
  where id = v_row.item_id
    and tenant_id = v_tenant
    and empresa_id = v_empresa;

  if not found then
    raise exception 'Item invalido ou fora do tenant/empresa atual';
  end if;

  if p_quantidade_baixada is null then
    raise exception 'Quantidade baixada invalida';
  end if;

  v_nova := round(p_quantidade_baixada, 3);
  if v_nova < 0 or v_nova > v_row.quantidade then
    raise exception 'Quantidade baixada deve ficar entre 0 e %', v_row.quantidade;
  end if;

  v_atual := least(coalesce(v_row.quantidade_baixada, 0), v_row.quantidade);
  v_delta := v_nova - v_atual;

  if abs(v_delta) < 0.0005 then
    update public.os_itens
       set quantidade_baixada = v_nova,
           baixa_estoque = (v_nova >= v_row.quantidade)
     where id = v_row.id
       and tenant_id = v_tenant
       and empresa_id = v_empresa
     returning * into v_updated;

    return v_updated;
  end if;

  if coalesce(v_item.tipo, '') <> 'produto' or coalesce(v_item.controla_estoque, false) = false then
    raise exception 'Item nao controla estoque; quantidade baixada deve permanecer 0';
  end if;

  if not (public.can('estoque', 'write') or public.can('os_rpcs', 'execute')) then
    raise exception 'Sem permissao para movimentar estoque';
  end if;

  v_os_label := coalesce(nullif(trim(v_os.numero_os), ''), nullif(v_os.os_num::text, ''), v_os.id::text);
  v_motivo := nullif(trim(coalesce(p_motivo, '')), '');
  if v_motivo is null then
    v_motivo := 'Ajuste quantidade baixada OS ' || v_os_label;
  end if;

  v_motivo := trim(regexp_replace(v_motivo, '[[:space:]]*\[OS[[:space:]]+[^\]]+\][[:space:]]*$', '', 'i'));
  if position(upper('OS ' || v_os_label) in upper(v_motivo)) = 0 then
    v_motivo := v_motivo || ' [OS ' || v_os_label || ']';
  end if;

  if v_delta > 0 then
    select coalesce(e.quantidade_atual, 0)
      into v_saldo_atual
    from public.estoque e
    where e.tenant_id = v_tenant
      and e.empresa_id = v_empresa
      and e.item_id = v_row.item_id
    for update;

    if not found then
      v_saldo_atual := 0;
    end if;

    if v_delta > coalesce(v_saldo_atual, 0) then
      raise exception 'Saldo insuficiente para baixar %. Saldo atual: %', v_delta, coalesce(v_saldo_atual, 0);
    end if;

    insert into public.movimentacoes (
      tenant_id,
      empresa_id,
      item_id,
      tipo,
      quantidade,
      motivo,
      realizado_por,
      data_movimentacao,
      origem_os_id,
      created_at
    )
    values (
      v_tenant,
      v_empresa,
      v_row.item_id,
      'saida',
      v_delta,
      v_motivo,
      v_realizado_por,
      now(),
      v_row.os_id,
      now()
    );
  else
    insert into public.movimentacoes (
      tenant_id,
      empresa_id,
      item_id,
      tipo,
      quantidade,
      motivo,
      realizado_por,
      data_movimentacao,
      origem_os_id,
      created_at
    )
    values (
      v_tenant,
      v_empresa,
      v_row.item_id,
      'entrada',
      abs(v_delta),
      v_motivo,
      v_realizado_por,
      now(),
      v_row.os_id,
      now()
    );
  end if;

  update public.os_itens
     set quantidade_baixada = v_nova,
         baixa_estoque = (v_nova >= quantidade)
   where id = v_row.id
     and tenant_id = v_tenant
     and empresa_id = v_empresa
   returning * into v_updated;

  return v_updated;
end;
$_$;


ALTER FUNCTION "public"."set_os_item_quantidade_baixada"("p_os_item_id" integer, "p_quantidade_baixada" numeric, "p_realizado_por" "text", "p_motivo" "text", "p_empresa_id" "uuid") OWNER TO "postgres";


