CREATE OR REPLACE FUNCTION "public"."ultima_entrada_por_itens"("p_tenant_id" "uuid", "p_empresa_id" "uuid", "p_item_ids" integer[]) RETURNS TABLE("item_id" integer, "data_movimentacao" timestamp without time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select distinct on (m.item_id)
    m.item_id,
    m.data_movimentacao
  from public.movimentacoes m
  where m.tenant_id = p_tenant_id
    and m.empresa_id = p_empresa_id
    and m.tipo = 'entrada'
    and m.item_id = any(coalesce(p_item_ids, array[]::integer[]))
  order by m.item_id, m.data_movimentacao desc nulls last, m.id desc;
$$;


