             LEFT JOIN "aprov" "ap" ON ((("ap"."tenant_id" = "t"."tenant_id") AND ("ap"."titulo_id" = "t"."id"))))
          WHERE (("ta"."deleted_at" IS NULL) AND ("t"."deleted_at" IS NULL) AND ("t"."tipo" = 'AP'::"text"))
        ), "venc" AS (
         SELECT "t"."tenant_id",
