    CONSTRAINT "ck_titulo_classificacao_compromisso_referencia_historica" CHECK (((("valor_referencia_historica" IS NULL) AND ("regra_referencia_historica" IS NULL)) OR (("valor_referencia_historica" > (0)::numeric) AND ("length"("btrim"(COALESCE("regra_referencia_historica", ''::"text"))) >= 10)))),
    CONSTRAINT "ck_titulo_classificacao_compromisso_reversao" CHECK (((("deleted_at" IS NULL) AND ("motivo_reversao" IS NULL)) OR (("deleted_at" IS NOT NULL) AND ("length"("btrim"(COALESCE("motivo_reversao", ''::"text"))) >= 10)))),
    CONSTRAINT "ck_titulo_classificacao_compromisso_valores" CHECK ((("valor_total_snapshot" >= (0)::numeric) AND ("valor_aberto_titulo_snapshot" >= (0)::numeric) AND ("valor_aberto_parcelas_snapshot" >= (0)::numeric)))
);


