    "valor_total" numeric(12,2) DEFAULT 0,
    "observacoes" "text",
    "criado_por" character varying(100),
    "atualizado_em" timestamp without time zone DEFAULT "now"(),
    "os_num" bigint NOT NULL,
    "pedido_compra" "text",
    "tipo_pedido" "text",
    "vendedor" "text",
    "orcado" numeric(12,2) DEFAULT 0,
    "custo" numeric(12,2) DEFAULT 0,
    "tem_gestao" boolean DEFAULT false NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "usa_relatorio_hh" boolean DEFAULT false NOT NULL,
    "empresa_id" "uuid" DEFAULT "public"."current_empresa_id"() NOT NULL,
    "responsavel_aprovacao_id" "uuid",
    "is_fiado" boolean DEFAULT false NOT NULL,
    "orcamento_gerado_id" "uuid",
    "status_fluxo" "text",
    "faturado_em" timestamp with time zone,
    "faturada_presumida_legado" boolean DEFAULT false NOT NULL,
    "garantia_motivo" "text",
    "garantia_reaberta_em" timestamp with time zone,
    "unidade_id" bigint,
    "tipo_documento" "text" DEFAULT 'OS'::"text" NOT NULL,
    "codigo" "text" NOT NULL,
    "numero_doc" integer,
    CONSTRAINT "chk_ordens_servico_status_fluxo" CHECK ((("status_fluxo" IS NULL) OR ("status_fluxo" = ANY (ARRAY['em_andamento'::"text", 'concluida'::"text", 'faturada'::"text", 'em_andamento_garantia'::"text", 'concluida_garantia'::"text", 'cancelada'::"text"])))),
    CONSTRAINT "ordens_servico_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['aberta'::character varying, 'em_andamento'::character varying, 'concluida'::character varying, 'cancelada'::character varying])::"text"[]))),
    CONSTRAINT "ordens_servico_tipo_documento_check" CHECK (("tipo_documento" = ANY (ARRAY['OS'::"text", 'OV'::"text"]))),
    CONSTRAINT "ordens_servico_tipo_pedido_check" CHECK (("tipo_pedido" = ANY (ARRAY['servico'::"text", 'material'::"text"])))
);


ALTER TABLE "public"."ordens_servico" OWNER TO "postgres";


COMMENT ON COLUMN "public"."ordens_servico"."is_fiado" IS 'OS aberta diretamente sem orcamento previo (OS Fiado): materiais/despesas e mao de obra (HH ou apontamento) ficam disponiveis simultaneamente, em vez de mutuamente exclusivos.';



COMMENT ON COLUMN "public"."ordens_servico"."orcamento_gerado_id" IS 'Orcamento gerado/atualizado a partir desta OS Fiado via fn_gerar_ou_atualizar_orcamento_de_os. Link reverso de m.orcamento.os_id. Nao usa FK composta (tenant_id, empresa_id) porque m.orcamento nao tem unique nessas 3 colunas; o RPC revalida tenant/empresa manualmente.';



COMMENT ON COLUMN "public"."ordens_servico"."tipo_documento" IS 'Discriminador do documento comercial: OS para ordem de servico e OV para ordem de venda.';



COMMENT ON COLUMN "public"."ordens_servico"."codigo" IS 'Codigo visivel do documento. OVs usam OV-{EMPRESA}-{NUMERO}-{ANO}; OS preservam a numeracao tecnica.';



COMMENT ON COLUMN "public"."ordens_servico"."numero_doc" IS 'Numero sequencial da OV dentro do tenant e da empresa.';



CREATE OR REPLACE VIEW "f"."v_os_exposicao_valor" WITH ("security_invoker"='true') AS
 SELECT "os"."tenant_id",
    "os"."empresa_id",
    "os"."id" AS "os_id",
    ("x"."valor")::numeric(15,2) AS "valor_estimado",
    "x"."origem" AS "valor_origem"
   FROM ("public"."ordens_servico" "os"
     CROSS JOIN LATERAL "f"."fn_calcular_exposicao_os_unscoped"("os"."tenant_id", "os"."empresa_id", "os"."id") "x"("valor", "origem"));


ALTER VIEW "f"."v_os_exposicao_valor" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "f"."vencimento_regra" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "codigo" "text" NOT NULL,
    "nome" "text" NOT NULL,
    "tipo" "text" NOT NULL,
    "dia" integer,
    "ativo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "deleted_at" timestamp with time zone,
    CONSTRAINT "ck_vencimento_regra_dia" CHECK (((("tipo" = 'M1_ULTIMO_DIA'::"text") AND ("dia" IS NULL)) OR (("tipo" = 'M1_DIA_FIXO'::"text") AND (("dia" >= 1) AND ("dia" <= 31))))),
    CONSTRAINT "ck_vencimento_regra_tipo" CHECK (("tipo" = ANY (ARRAY['M1_ULTIMO_DIA'::"text", 'M1_DIA_FIXO'::"text"])))
);


ALTER TABLE "f"."vencimento_regra" OWNER TO "postgres";


CREATE OR REPLACE VIEW "f"."vw_imposto_apuracao_mensal" WITH ("security_invoker"='true') AS
 SELECT "df"."tenant_id",
    "df"."empresa_id",
    "df"."competencia_date",
    "df"."operacao",
    "dfi"."imposto",
    "dfi"."natureza",
    "sum"(COALESCE("dfi"."base_calculo", (0)::numeric)) AS "base_total",
    "sum"(COALESCE("dfi"."valor_ajustado", "dfi"."valor_calculado", (0)::numeric)) AS "valor_total_calculado",
    "sum"(COALESCE("dfi"."valor_ajustado", (0)::numeric)) AS "valor_total_ajustado",
    "count"(DISTINCT "dfi"."documento_fiscal_id") AS "qtd_documentos"
   FROM ("f"."documento_fiscal_imposto" "dfi"
     JOIN "f"."documento_fiscal" "df" ON ((("df"."id" = "dfi"."documento_fiscal_id") AND ("df"."tenant_id" = "dfi"."tenant_id"))))
  WHERE (("df"."deleted_at" IS NULL) AND ("dfi"."deleted_at" IS NULL) AND ("df"."competencia_date" IS NOT NULL))
  GROUP BY "df"."tenant_id", "df"."empresa_id", "df"."competencia_date", "df"."operacao", "dfi"."imposto", "dfi"."natureza";


ALTER VIEW "f"."vw_imposto_apuracao_mensal" OWNER TO "postgres";


