COMMENT ON COLUMN "public"."apontamentos_horas"."hora_entrada_2" IS 'Entrada período 2 (tarde)';



COMMENT ON COLUMN "public"."apontamentos_horas"."hora_saida_2" IS 'Saída período 2 (tarde)';



