CREATE TABLE IF NOT EXISTS "public"."item_cadastro_agente_sugestoes" (
    "id" bigint NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "empresa_id" "uuid" NOT NULL,
    "item_id" integer NOT NULL,
    "fornecedor_id" integer NOT NULL,
    "codigo_interno" "text" NOT NULL,
    "quantidade_referencia" numeric(14,3) NOT NULL,
    "sugestao_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "pesquisa_precos_json" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "preco_origem" numeric(14,4),
    "preco_final" numeric(14,4),
    "moeda_origem" character varying(3),
    "regra_preco" "text",
    "multiplicador_preco" numeric(8,4) DEFAULT 1 NOT NULL,
    "item_similar_id" integer,
    "fiscal_sugerido_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "modelo" "text" NOT NULL,
    "confirmado_por" "text" NOT NULL,
    "confirmado_em" timestamp with time zone DEFAULT "now"() NOT NULL,
    "criado_em" timestamp with time zone DEFAULT "now"() NOT NULL,
    "preco_confirmado" numeric(14,4),
    "movimentacao_estoque_id" integer,
    CONSTRAINT "item_cadastro_agente_sugestoes_codigo_nao_vazio_ck" CHECK (("btrim"("codigo_interno") <> ''::"text")),
    CONSTRAINT "item_cadastro_agente_sugestoes_confirmado_por_nao_vazio_ck" CHECK (("btrim"("confirmado_por") <> ''::"text")),
    CONSTRAINT "item_cadastro_agente_sugestoes_fiscal_json_obj_ck" CHECK (("jsonb_typeof"("fiscal_sugerido_json") = 'object'::"text")),
    CONSTRAINT "item_cadastro_agente_sugestoes_modelo_nao_vazio_ck" CHECK (("btrim"("modelo") <> ''::"text")),
    CONSTRAINT "item_cadastro_agente_sugestoes_moeda_formato_ck" CHECK ((("moeda_origem" IS NULL) OR ((("moeda_origem")::"text" = "upper"(("moeda_origem")::"text")) AND (("moeda_origem")::"text" ~ '^[A-Z]{3}$'::"text")))),
    CONSTRAINT "item_cadastro_agente_sugestoes_multiplicador_positivo_ck" CHECK (("multiplicador_preco" > (0)::numeric)),
    CONSTRAINT "item_cadastro_agente_sugestoes_pesquisa_precos_json_arr_ck" CHECK (("jsonb_typeof"("pesquisa_precos_json") = 'array'::"text")),
    CONSTRAINT "item_cadastro_agente_sugestoes_preco_confirmado_positivo_ck" CHECK ((("preco_confirmado" IS NULL) OR ("preco_confirmado" > (0)::numeric))),
    CONSTRAINT "item_cadastro_agente_sugestoes_preco_final_positivo_ck" CHECK ((("preco_final" IS NULL) OR ("preco_final" >= (0)::numeric))),
    CONSTRAINT "item_cadastro_agente_sugestoes_preco_origem_positivo_ck" CHECK ((("preco_origem" IS NULL) OR ("preco_origem" >= (0)::numeric))),
    CONSTRAINT "item_cadastro_agente_sugestoes_quantidade_positiva_ck" CHECK (("quantidade_referencia" >= (0)::numeric)),
    CONSTRAINT "item_cadastro_agente_sugestoes_sugestao_json_obj_ck" CHECK (("jsonb_typeof"("sugestao_json") = 'object'::"text"))
);


ALTER TABLE "public"."item_cadastro_agente_sugestoes" OWNER TO "postgres";


COMMENT ON TABLE "public"."item_cadastro_agente_sugestoes" IS 'Auditoria imutavel de propostas de cadastro de item confirmadas pelo agente de IA, incluindo fontes de preco e referencia fiscal interna.';



COMMENT ON COLUMN "public"."item_cadastro_agente_sugestoes"."quantidade_referencia" IS 'Quantidade informada para a cotacao; quando maior que zero, tambem define o estoque inicial criado na confirmacao.';



COMMENT ON COLUMN "public"."item_cadastro_agente_sugestoes"."sugestao_json" IS 'Proposta completa aprovada, incluindo descricao normalizada, grupo e dados comerciais revisados.';



COMMENT ON COLUMN "public"."item_cadastro_agente_sugestoes"."pesquisa_precos_json" IS 'Fontes externas consultadas pelo agente, com URL, marketplace, preco, moeda e tipo de correspondencia.';



COMMENT ON COLUMN "public"."item_cadastro_agente_sugestoes"."preco_final" IS 'Preco final calculado pela pesquisa do agente, antes de eventual ajuste manual na confirmacao.';



COMMENT ON COLUMN "public"."item_cadastro_agente_sugestoes"."item_similar_id" IS 'Item interno usado como referencia para a sugestao fiscal/comercial, quando houver.';



COMMENT ON COLUMN "public"."item_cadastro_agente_sugestoes"."preco_confirmado" IS 'Preco unitario efetivamente confirmado pela pessoa usuaria, gravado no cadastro do item e na movimentacao de estoque inicial.';



COMMENT ON COLUMN "public"."item_cadastro_agente_sugestoes"."movimentacao_estoque_id" IS 'Movimentacao de entrada criada para o estoque inicial quando a quantidade informada for maior que zero.';



