CREATE OR REPLACE VIEW "r"."r_nfse_iss_conferencia" WITH ("security_invoker"='true') AS
 SELECT "df"."tenant_id",
    "df"."empresa_id",
    "df"."id" AS "documento_fiscal_id",
    "df"."emissao_date",
    "df"."modelo",
    "df"."serie",
    "df"."numero",
    "df"."chave_acesso",
    "df"."valor_total",
    "df"."valor_servicos",
    "df"."material_percent",
    "df"."material_valor",
    "imp"."natureza" AS "iss_natureza",
    "imp"."base_original",
    "imp"."deducoes",
    "imp"."base_calculo",
    "imp"."aliquota",
    "imp"."valor_calculado",
    "imp"."valor_ajustado",
