    "df"."updated_at"
   FROM ("f"."documento_fiscal" "df"
     LEFT JOIN "f"."documento_fiscal_imposto" "imp" ON ((("imp"."documento_fiscal_id" = "df"."id") AND ("imp"."tenant_id" = "df"."tenant_id") AND ("imp"."imposto" = 'ISS'::"text") AND ("imp"."deleted_at" IS NULL))))
  WHERE (("df"."deleted_at" IS NULL) AND ("df"."operacao" = 'SAIDA'::"text") AND ("df"."natureza" = 'SERVICO'::"text"));


ALTER VIEW "r"."r_nfse_iss_conferencia" OWNER TO "postgres";


CREATE OR REPLACE VIEW "r"."r_orcamento_catalogo_busca" WITH ("security_invoker"='true') AS
 SELECT 'ITEM'::"text" AS "origem",
    "i"."tenant_id",
    "i"."empresa_id",
    ("i"."id")::"text" AS "ref_id",
    "i"."id" AS "item_id",
    NULL::"uuid" AS "conjunto_id",
    "upper"("btrim"(("i"."codigo_interno")::"text")) AS "codigo",
    "upper"("btrim"(("i"."nome")::"text")) AS "nome",
    "upper"("btrim"((COALESCE("i"."unidade_medida", 'UN'::character varying))::"text")) AS "unidade",
        CASE
            WHEN ("lower"(("i"."tipo")::"text") = 'produto'::"text") THEN 'PRODUTO'::"text"
            WHEN ("lower"(("i"."tipo")::"text") = 'servico'::"text") THEN 'SERVICO'::"text"
            ELSE "upper"(("i"."tipo")::"text")
        END AS "tipo",
    ("m"."fn_orcamento_preco_sugerido_item_por_id"("i"."tenant_id", "i"."empresa_id", "i"."id"))::numeric(15,2) AS "preco_sugerido"
   FROM "public"."itens" "i"
  WHERE (("i"."ativo" IS TRUE) AND (("i"."tipo")::"text" = ANY ((ARRAY['produto'::character varying, 'servico'::character varying])::"text"[])))
UNION ALL
 SELECT 'CONJUNTO'::"text" AS "origem",
    "c"."tenant_id",
    "c"."empresa_id",
    ("c"."id")::"text" AS "ref_id",
    NULL::integer AS "item_id",
    "c"."id" AS "conjunto_id",
    "c"."codigo",
    "c"."nome",
    'CJ'::"text" AS "unidade",
    'CONJUNTO'::"text" AS "tipo",
        CASE
            WHEN ("c"."precificacao" = 'PRECO_FIXO'::"text") THEN "c"."preco_fixo"
            ELSE (COALESCE("sum"(("ci"."quantidade" * "m"."fn_orcamento_preco_sugerido_item_por_id"("c"."tenant_id", "c"."empresa_id", "i"."id"))), (0)::numeric))::numeric(15,2)
        END AS "preco_sugerido"
   FROM (("c"."conjunto" "c"
     LEFT JOIN "c"."conjunto_item" "ci" ON ((("ci"."conjunto_id" = "c"."id") AND ("ci"."deleted_at" IS NULL))))
     LEFT JOIN "public"."itens" "i" ON ((("i"."id" = "ci"."item_id") AND ("i"."tenant_id" = "c"."tenant_id") AND ("i"."empresa_id" = "c"."empresa_id") AND ("i"."ativo" IS TRUE))))
  WHERE (("c"."deleted_at" IS NULL) AND ("c"."ativo" IS TRUE))
  GROUP BY "c"."id";


ALTER VIEW "r"."r_orcamento_catalogo_busca" OWNER TO "postgres";


