   FROM "m"."fn_orcamento_lista_current"() "src"("id", "tenant_id", "empresa_id", "codigo", "numero", "versao", "status", "emissao_date", "titulo", "cliente_id", "cliente_nome", "vendedor_usuario_id", "vendedor_nome", "condicao_pagamento_id", "condicao_pagamento_nome", "desconto_global_percent", "acrescimo_cond_pag_percent", "valor_frete", "total_produtos", "total_servicos", "total_bruto", "total_desconto_global", "total_liquido", "created_at", "updated_at", "valor_fechado", "desconto_fechamento_valor", "desconto_fechamento_percent", "observacoes", "os_id", "os_itens_importados_at");


ALTER VIEW "r"."r_orcamento_lista" OWNER TO "postgres";


CREATE OR REPLACE VIEW "r"."r_pendencias_xml_entrada" WITH ("security_invoker"='true') AS
 SELECT "p"."tenant_id",
    "p"."empresa_id",
    "df"."competencia_date",
    "df"."emissao_date",
    "df"."id" AS "documento_fiscal_id",
    "df"."chave_acesso",
    "df"."valor_total" AS "doc_valor_total",
    "p"."tipo" AS "pendencia_tipo",
    "p"."detalhe" AS "pendencia_detalhe",
    "p"."created_at" AS "pendencia_created_at",
    "df"."source_nf_entrada_id",
    "ne"."modelo" AS "nf_modelo",
    "ne"."serie" AS "nf_serie",
    "ne"."numero" AS "nf_numero",
    "ne"."valor_total" AS "nf_valor_total",
    "ne"."emitente_nome" AS "fornecedor_nome",
    "ne"."emitente_cnpj" AS "fornecedor_cnpj",
    "ne"."fornecedor_id",
        CASE
            WHEN (("ne"."xml_raw" IS NULL) OR ("btrim"("ne"."xml_raw") = ''::"text")) THEN 'AUSENTE'::"text"
            WHEN ("length"("ne"."xml_raw") < 200) THEN 'CURTO'::"text"
            ELSE 'OK'::"text"
        END AS "xml_status",
    "length"("ne"."xml_raw") AS "xml_len"
   FROM (("f"."documento_fiscal_pendencia" "p"
     JOIN "f"."documento_fiscal" "df" ON ((("df"."id" = "p"."documento_fiscal_id") AND ("df"."tenant_id" = "p"."tenant_id"))))
     LEFT JOIN "public"."nf_entrada" "ne" ON ((("ne"."id" = "df"."source_nf_entrada_id") AND ("ne"."tenant_id" = "df"."tenant_id") AND ("ne"."empresa_id" = "df"."empresa_id"))))
  WHERE (("p"."resolved_at" IS NULL) AND ("df"."deleted_at" IS NULL) AND ("df"."operacao" = 'ENTRADA'::"text") AND ("df"."natureza" = 'PRODUTO'::"text"));


ALTER VIEW "r"."r_pendencias_xml_entrada" OWNER TO "postgres";


CREATE OR REPLACE VIEW "r"."r_venda_credito" WITH ("security_invoker"='false') AS
 SELECT "g"."tenant_id",
    "g"."empresa_id",
    "g"."id" AS "credito_id",
    "g"."os_id",
    "os"."numero_os",
    "os"."status" AS "os_status",
    "os"."status_fluxo" AS "os_status_fluxo",
    "g"."cliente_id",
    "c"."nome" AS "cliente_nome",
    "c"."documento",
    "c"."documento_norm",
    "c"."documento_raiz",
    COALESCE("c"."documento_raiz", ('CLIENTE:'::"text" || ("g"."cliente_id")::"text")) AS "grupo_cliente",
    "g"."unidade_id",
    "u"."nome" AS "unidade_nome",
    "g"."status",
    "g"."origem",
    COALESCE("g"."descricao", "os"."descricao_servico") AS "descricao",
    "g"."data_competencia",
    "g"."pedido_compra_cliente",
    "g"."pedido_recebido_em",
    "g"."faturado_em",
    "g"."documento_fiscal_id",
    "df"."modelo" AS "documento_modelo",
    "df"."serie" AS "documento_serie",
    "df"."numero" AS "documento_numero",
    "g"."titulo_ar_id",
    "g"."responsavel_id",
    "au"."nome" AS "responsavel_nome",
    "g"."responsavel_cliente_nome",
    "g"."proximo_contato_date",
    "g"."observacao",
    "g"."valor_estimado",
    "g"."valor_confirmado",
    (COALESCE("g"."valor_confirmado", "g"."valor_estimado", (0)::numeric))::numeric(15,2) AS "valor_exposicao",
    "g"."valor_origem",
    "g"."valor_calculado_em",
    (CURRENT_DATE - COALESCE("g"."data_competencia", ("g"."created_at")::"date")) AS "dias_em_aberto",
    "g"."created_at",
    "g"."updated_at"
   FROM ((((("f"."gestao_cobranca_os" "g"
     LEFT JOIN "public"."ordens_servico" "os" ON ((("os"."id" = "g"."os_id") AND ("os"."tenant_id" = "g"."tenant_id") AND ("os"."empresa_id" = "g"."empresa_id"))))
     LEFT JOIN "public"."clientes" "c" ON ((("c"."id" = "g"."cliente_id") AND ("c"."tenant_id" = "g"."tenant_id") AND ("c"."empresa_id" = "g"."empresa_id"))))
     LEFT JOIN "public"."cliente_unidades" "u" ON ((("u"."id" = "g"."unidade_id") AND ("u"."tenant_id" = "g"."tenant_id") AND ("u"."empresa_id" = "g"."empresa_id"))))
     LEFT JOIN "f"."documento_fiscal" "df" ON ((("df"."id" = "g"."documento_fiscal_id") AND ("df"."tenant_id" = "g"."tenant_id") AND ("df"."empresa_id" = "g"."empresa_id"))))
     LEFT JOIN "a"."usuario" "au" ON (("au"."id" = "g"."responsavel_id")))
  WHERE (("g"."deleted_at" IS NULL) AND (("auth"."role"() = 'service_role'::"text") OR (("g"."tenant_id" = "public"."current_tenant_id"()) AND ("g"."empresa_id" = "public"."current_empresa_id__by_tenant"("g"."tenant_id")) AND "f"."has_cobranca_access"("g"."tenant_id", "g"."empresa_id"))));


ALTER VIEW "r"."r_venda_credito" OWNER TO "postgres";


CREATE OR REPLACE VIEW "r"."r_vendas_ov_divergencias" WITH ("security_invoker"='true') AS
 SELECT "tenant_id",
    "empresa_id",
    "id" AS "venda_id",
    "codigo",
    "cliente_id",
    "status_fluxo",
    ("cliente_id" IS NULL) AS "sem_cliente",
    COALESCE("tem_gestao", false) AS "tem_gestao",
    COALESCE("usa_relatorio_hh", false) AS "usa_relatorio_hh",
    (EXISTS ( SELECT 1
           FROM "public"."os_gestao_itens" "gestao"
          WHERE (("gestao"."tenant_id" = "venda"."tenant_id") AND ("gestao"."empresa_id" = "venda"."empresa_id") AND ("gestao"."os_id" = "venda"."id")))) AS "possui_gestao",
    ((EXISTS ( SELECT 1
           FROM "public"."apontamentos_horas" "horas"
          WHERE (("horas"."tenant_id" = "venda"."tenant_id") AND ("horas"."empresa_id" = "venda"."empresa_id") AND ("horas"."os_id" = "venda"."id")))) OR (EXISTS ( SELECT 1
           FROM "public"."hh_lancamentos" "hh"
          WHERE (("hh"."tenant_id" = "venda"."tenant_id") AND ("hh"."empresa_id" = "venda"."empresa_id") AND ("hh"."os_id" = "venda"."id"))))) AS "possui_horas"
   FROM "public"."ordens_servico" "venda"
  WHERE (("tipo_documento" = 'OV'::"text") AND (("cliente_id" IS NULL) OR COALESCE("tem_gestao", false) OR COALESCE("usa_relatorio_hh", false) OR (EXISTS ( SELECT 1
           FROM "public"."os_gestao_itens" "gestao"
          WHERE (("gestao"."tenant_id" = "venda"."tenant_id") AND ("gestao"."empresa_id" = "venda"."empresa_id") AND ("gestao"."os_id" = "venda"."id")))) OR (EXISTS ( SELECT 1
           FROM "public"."apontamentos_horas" "horas"
          WHERE (("horas"."tenant_id" = "venda"."tenant_id") AND ("horas"."empresa_id" = "venda"."empresa_id") AND ("horas"."os_id" = "venda"."id")))) OR (EXISTS ( SELECT 1
           FROM "public"."hh_lancamentos" "hh"
          WHERE (("hh"."tenant_id" = "venda"."tenant_id") AND ("hh"."empresa_id" = "venda"."empresa_id") AND ("hh"."os_id" = "venda"."id"))))));


